    /// Pretty-print the Series as a string table.
    ///
    /// Matches `str(series)` / `series.to_string()` in pandas.
    #[must_use]
    pub fn to_string_repr(&self) -> String {
        let mut lines = Vec::with_capacity(self.len() + 2);
        // Compute max label width using the same display format as rendering
        let label_width = self
            .index
            .labels()
            .iter()
            .map(|l| match l {
                IndexLabel::Int64(v) => v.to_string().len(),
                IndexLabel::Utf8(s) => s.len(),
                IndexLabel::Timedelta64(ns) => Timedelta::format(*ns).len(),
                IndexLabel::Datetime64(ns) => format_datetime_ns(*ns).len(),
                f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string().len(),
                IndexLabel::Null(_) => l.to_string().len(),
            })
            .max()
            .unwrap_or(0);

        for (label, val) in self.index.labels().iter().zip(self.column.values()) {
            let lbl_str = match label {
                IndexLabel::Int64(v) => v.to_string(),
                IndexLabel::Utf8(s) => s.clone(),
                IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                IndexLabel::Null(_) => label.to_string(),
            };
            let val_str = match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => s.clone(),
                Scalar::Timedelta64(v) => Timedelta::format(*v),
                Scalar::Datetime64(v) => format_datetime_ns(*v),
                Scalar::Period(ordinal) => ordinal.calendar_string(),
                Scalar::Interval(interval) => format!("{interval}"),
            };
            lines.push(format!("{lbl_str:<label_width$}    {val_str}"));
        }
        lines.push(format!("Name: {}, Length: {}", self.name, self.len()));
        lines.join("\n")
    }

    /// Broadcast a single scalar value across the given index.
    ///
    /// Matches `pd.Series(5, index=[0, 1, 2])`.
    pub fn broadcast(
        name: impl Into<String>,
        value: Scalar,
        index_labels: Vec<IndexLabel>,
    ) -> Result<Self, FrameError> {
        let n = index_labels.len();
        let values = vec![value; n];
        Self::from_values(name, index_labels, values)
    }

    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    #[must_use]
    pub fn index(&self) -> &Index {
        &self.index
    }

    #[must_use]
    pub fn column(&self) -> &Column {
        &self.column
    }

    #[must_use]
    pub fn values(&self) -> &[Scalar] {
        self.column.values()
    }

    /// Borrow the native numeric buffer and its validity mask when available.
    ///
    /// Unlike [`Self::values`], this never allocates or boxes one `Scalar` per
    /// element. Non-numeric Series deliberately return `None` so callers retain
    /// the scalar path for heterogeneous and object-like data.
    #[must_use]
    pub fn typed_values(&self) -> Option<SeriesTypedValues<'_>> {
        if let Some((data, validity)) = self.column.as_i64_slice_with_validity() {
            return Some(SeriesTypedValues::Int64 { data, validity });
        }
        self.column
            .as_f64_slice_with_validity()
            .map(|(data, validity)| SeriesTypedValues::Float64 { data, validity })
    }

