    /// Matches `pd.Series.array` at the API-shape level for the current
    /// immutable scalar-vector representation.
    #[must_use]
    pub fn array(&self) -> Vec<Scalar> {
        self.to_list()
    }

    /// Flatten Series values to a one-dimensional scalar vector.
