    /// Swap Series axes.
    ///
    /// Matches `pd.Series.swapaxes()` for a one-dimensional object; the
    /// operation is identity because Series has only axis 0.
    #[must_use]
    pub fn swapaxes(&self) -> Self {
        self.clone()
    }

    /// Swap the last two tuple-style index levels.
    ///
    /// Matches `pd.Series.swaplevel()` for the tuple-label MultiIndex
    /// representation currently used by FrankenPandas. Non-tuple labels are
    /// returned unchanged, matching the existing DataFrame fallback shape.
    #[must_use]
    pub fn swaplevel(&self) -> Self {
        self.reorder_levels(&[1, 0])
            .unwrap_or_else(|_| self.clone())
    }

    /// Reorder tuple-style index levels.
    ///
    /// Matches `pd.Series.reorder_levels(order)` for labels formatted like
    /// `(level0, level1, ...)`. Single-level Series accept `[0]` as identity.
    pub fn reorder_levels(&self, order: &[usize]) -> Result<Self, FrameError> {
        if order == [0] {
            return Ok(self.clone());
        }

        let mut labels = Vec::with_capacity(self.len());
        for label in self.index.labels() {
            let IndexLabel::Utf8(text) = label else {
                return Err(FrameError::CompatibilityRejected(
                    "reorder_levels: Series index is not tuple-style MultiIndex labels".to_owned(),
                ));
            };
            let Some(inner) = text
                .trim()
                .strip_prefix('(')
                .and_then(|value| value.strip_suffix(')'))
            else {
                return Err(FrameError::CompatibilityRejected(
                    "reorder_levels: Series index is not tuple-style MultiIndex labels".to_owned(),
                ));
            };

            let parts: Vec<&str> = inner.split(", ").collect();
            if parts.len() != order.len() {
                return Err(FrameError::CompatibilityRejected(format!(
                    "reorder_levels: order length {} does not match index level count {}",
                    order.len(),
                    parts.len()
                )));
            }
            let mut seen = vec![false; parts.len()];
            for &level in order {
                if level >= parts.len() || seen[level] {
                    return Err(FrameError::CompatibilityRejected(
                        "reorder_levels: order must be a permutation of index levels".to_owned(),
                    ));
                }
                seen[level] = true;
            }

            let reordered = order
                .iter()
                .map(|&level| parts[level])
                .collect::<Vec<_>>()
                .join(", ");
            labels.push(IndexLabel::Utf8(format!("({reordered})")));
        }

        // Per br-frankenpandas-v956y: pandas Series.reorder_levels preserves
        // the index axis name (the levels reorder; the axis name is metadata).
        Ok(Self {
            name: self.name.clone(),
            index: Index::new(labels).rename_index(self.index.name()),
            column: self.column.clone(),
            categorical: self.categorical.clone(),
            sparse: self.sparse.clone(),
        })
    }

    /// Return the dtype of this Series.
    ///
    /// Matches `pd.Series.dtype`.
    #[must_use]
    pub fn dtype(&self) -> DType {
        if self.sparse.is_some() {
            DType::Sparse
        } else if self.categorical.is_some() {
            DType::Categorical
        } else {
            self.column.dtype()
        }
    }

    /// Return the pandas dtype NAME of this Series.
    ///
    /// br-frankenpandas-3gxc6. This is not `self.dtype().name()`: for a sparse
    /// Series pandas reports the parameterized `Sparse[int64, 0]`, and
    /// [`DType::name`] can only answer the bare `"Sparse"` because
    /// `DType::Sparse` carries no payload. The subtype and fill live in the
    /// `SparseDType` descriptor this Series is holding, so this is the only
    /// level that can spell the full name.
    ///
    /// Every non-sparse dtype is unchanged and delegates to [`DType::name`].
    /// Categorical stays `"category"`: pandas parameterizes `CategoricalDtype`
    /// in its *repr* but `.dtype.name` is plain `"category"`, so there is
    /// nothing to widen there.
    #[must_use]
    pub fn dtype_name(&self) -> String {
        if let Some(sparse) = self.sparse.as_ref() {
            return sparse.pandas_name();
        }
        self.dtype().name().to_owned()
    }

    /// Plural pandas alias for [`Self::dtype`].
    ///
    /// Matches `pd.Series.dtypes`.
    #[must_use]
    pub fn dtypes(&self) -> DType {
        self.dtype()
    }

    /// Return a deep copy of this Series.
    ///
    /// Matches `pd.Series.copy(deep=True)`.
    #[must_use]
    pub fn copy(&self) -> Self {
        self.clone()
    }

    /// Return the Series index.
    ///
    /// Matches `pd.Series.keys()`. This is an alias for the index.
    #[must_use]
    pub fn keys(&self) -> Index {
        self.index.clone()
    }

    /// Core binary arithmetic: align indexes, reindex columns, apply op.
    fn binary_op_with_policy(
        &self,
        other: &Self,
        op: ArithmeticOp,
        policy: &RuntimePolicy,
        ledger: &mut EvidenceLedger,
    ) -> Result<Self, FrameError> {
        let op_symbol = match op {
            ArithmeticOp::Add => "+",
            ArithmeticOp::Sub => "-",
            ArithmeticOp::Mul => "*",
            ArithmeticOp::Div => "/",
            ArithmeticOp::Mod => "%",
            ArithmeticOp::Pow => "**",
            ArithmeticOp::FloorDiv => "//",
        };
        let out_name = if self.name == other.name {
            self.name.clone()
        } else {
            format!("{}{op_symbol}{}", self.name, other.name)
        };

        let has_duplicate_labels = self.index.has_duplicates() || other.index.has_duplicates();
        let exact_index_fast_path = self.index == other.index;

        if exact_index_fast_path {
            let union_index = self.index.clone();
            record_alignment_semantic_witness(
                ledger,
                &format!("series.{}", arithmetic_op_name(op)),
                AlignMode::Outer,
                &self.index,
                &other.index,
                &union_index,
                "series_binary_arithmetic_materialization",
            );

            let action = policy.decide_join_admission(union_index.len(), ledger);
            if matches!(action, DecisionAction::Reject) {
                return Err(FrameError::CompatibilityRejected(
                    "runtime policy rejected alignment admission".to_owned(),
                ));
            }

            let column = if matches!(self.column.dtype(), DType::Float64)
                && matches!(other.column.dtype(), DType::Float64)
            {
                self.column
                    .aligned_binary_f64_same_positions(&other.column, op)?
            } else {
                self.column.binary_numeric(&other.column, op)?
            };

            return Self::new(out_name, union_index, column);
        }

        let typed_unit_range_columns = matches!(
            (self.column.dtype(), other.column.dtype()),
            (DType::Float64, DType::Float64) | (DType::Int64, DType::Int64)
        );
        if !has_duplicate_labels
            && typed_unit_range_columns
            && let Some(range) = int64_unit_range_alignment(&self.index, &other.index)
        {
            let union_index = range.union_index(&self.index, &other.index);
            record_alignment_semantic_witness(
                ledger,
                &format!("series.{}", arithmetic_op_name(op)),
                AlignMode::Outer,
                &self.index,
                &other.index,
                &union_index,
                "series_binary_arithmetic_materialization",
            );

            let action = policy.decide_join_admission(union_index.len(), ledger);
            if matches!(action, DecisionAction::Reject) {
                return Err(FrameError::CompatibilityRejected(
                    "runtime policy rejected alignment admission".to_owned(),
                ));
            }

            let column = match self.column.dtype() {
                DType::Float64 => self.column.aligned_binary_f64_int64_unit_ranges(
                    &other.column,
                    range.left_range(),
                    range.right_range(),
                    range.union_range(),
                    op,
                )?,
                DType::Int64 => self.column.aligned_binary_i64_int64_unit_ranges(
                    &other.column,
                    range.left_range(),
                    range.right_range(),
                    range.union_range(),
                    op,
                )?,
                _ => unreachable!("typed unit-range gate admits only numeric peers"),
            };
            return Self::new(out_name, union_index, column);
        }

        let (union_index, left_positions, right_positions) = if has_duplicate_labels {
            align_union_duplicate_aware(&self.index, &other.index)
        } else {
            let plan = align_union_sorted_unique(&self.index, &other.index);
            validate_alignment_plan(&plan)?;
            (plan.union_index, plan.left_positions, plan.right_positions)
        };

        record_alignment_semantic_witness(
            ledger,
            &format!("series.{}", arithmetic_op_name(op)),
            AlignMode::Outer,
            &self.index,
            &other.index,
            &union_index,
            "series_binary_arithmetic_materialization",
        );

        let action = policy.decide_join_admission(union_index.len(), ledger);
        if matches!(action, DecisionAction::Reject) {
            return Err(FrameError::CompatibilityRejected(
                "runtime policy rejected alignment admission".to_owned(),
            ));
        }

        // AG-10 fused fast path: when both columns are already Float64, gather
        // f64 directly from the originals into the union layout and apply the op
        // in one vectorized pass — skipping the two intermediate reindexed
        // `Vec<Scalar>` materializations. Output is byte-identical to the general
        // reindex + binary_numeric path in the `else` arm (proof in
        // `Column::aligned_binary_f64`). All other dtype combinations (incl. the
        // Int64/Bool→Float64 gap promotion) take the general path unchanged.
        let column = if matches!(self.column.dtype(), DType::Float64)
            && matches!(other.column.dtype(), DType::Float64)
        {
            self.column
                .aligned_binary_f64(&other.column, &left_positions, &right_positions, op)?
        } else {
            let left = self.column.reindex_by_positions(&left_positions)?;
            let right = other.column.reindex_by_positions(&right_positions)?;

            // Pandas promotes to Float64 when alignment introduces missing values,
            // so NaN can be used as the missing sentinel (numpy int64 has no NaN).
            //
            // THE PROMOTION IS PER-LANE: a lane widens iff IT gains a gap and it
            // cannot represent one. This is the same nywa8 rule `align_on_index`
            // already applies — "a lane widens iff IT gains a gap; the join mode
            // only decides which lanes do" — but this path was asking a different
            // question. It required BOTH sides to be numpy `Int64`/`Bool` and
            // then widened BOTH on a gap ANYWHERE, so a NULLABLE lane on either
            // side switched the promotion off entirely.
            //
            // MEASURED, live pandas 2.2.3, `s1 * s2` under union alignment:
            //
            //   Int64[a,b,c]   * int64[c,a,d]   both gain gaps   -> Float64
            //   Int64[a,b,c]   * int64[a,b]     only RIGHT gains -> Float64
            //   Int64[a,b]     * int64[a,b,c]   only LEFT  gains -> Int64
            //   Int64[a,b,c]   * int64[a,b,c]   neither gains    -> Int64
            //   boolean[a,b,c] * int64[c,a,d]   both gain gaps   -> Float64
            //   int64[a,b,c]   * int64[c,a,d]   both gain gaps   -> float64
            //
            // Rows 2 and 3 are the pair that settles it: the SAME dtypes give
            // different answers depending on WHICH side the gap lands on, so no
            // rule phrased over "are there gaps anywhere" can reproduce pandas.
            // A nullable lane holds pd.NA natively and never widens; the numpy
            // lane beside it still does, and `common_dtype` then carries the
            // result to `Float64Nullable` — which is why FP returned `Int64(6)`
            // where pandas gives 6.0. (br-frankenpandas-f0aaa)
            //
            // Restricting the widen set to numpy `Int64`/`Bool` is deliberate and
            // leaves the existing corpus untouched: for two numpy-int lanes this
            // is result-equivalent, because widening a lane that gained no gap is
            // numerically a no-op and `common_dtype(Int64, Float64)` is Float64
            // either way.
            let left_gains_gap = left_positions.iter().any(Option::is_none);
            let right_gains_gap = right_positions.iter().any(Option::is_none);
            let widens = |column: &Column, gains_gap: bool| {
                gains_gap && matches!(column.dtype(), DType::Int64 | DType::Bool)
            };
            let left = if widens(&left, left_gains_gap) {
                left.astype(DType::Float64)?
            } else {
                left
            };
            let right = if widens(&right, right_gains_gap) {
                right.astype(DType::Float64)?
            } else {
                right
            };

            left.binary_numeric(&right, op)?
        };

        Self::new(out_name, union_index, column)
    }

    pub fn add_with_policy(
        &self,
        other: &Self,
        policy: &RuntimePolicy,
        ledger: &mut EvidenceLedger,
    ) -> Result<Self, FrameError> {
        self.binary_op_with_policy(other, ArithmeticOp::Add, policy, ledger)
    }

