    /// Binary operation with fill_value for NaN handling.
    ///
    /// Matches `s1.add(s2, fill_value=0)` in pandas. When one operand is NaN
    /// and the other is not, the NaN is replaced with `fill_value` before the
    /// operation. When both are NaN, the result is NaN.
    fn binary_op_fill(
        &self,
        other: &Self,
        op: ArithmeticOp,
        fill_value: f64,
    ) -> Result<Self, FrameError> {
        let has_duplicate_labels = self.index.has_duplicates() || other.index.has_duplicates();
        let plan = if self.index == other.index {
            let positions = (0..self.len()).map(Some).collect::<Vec<_>>();
            AlignmentPlan {
                union_index: self.index.clone(),
                left_positions: positions.clone(),
                right_positions: positions,
            }
        } else if has_duplicate_labels {
            let (union_index, left_positions, right_positions) =
                align_union_duplicate_aware(&self.index, &other.index);
            AlignmentPlan {
                union_index,
                left_positions,
                right_positions,
            }
        } else {
            align_union_sorted_unique(&self.index, &other.index)
        };
        validate_alignment_plan(&plan)?;

        // Typed fast path: both columns numeric — gather directly from the
        // source f64/i64+validity slices with fill semantics (bit-identical to
        // the Scalar loop below), bypassing reindex_by_positions' Scalar path
        // for nullable sources AND the per-cell Vec<Scalar> materialization.
        // (unaligned s.add(fill_value=) was 0.05x pandas — 20x slower.)
        if matches!(
            self.column.dtype(),
            DType::Int64 | DType::Float64 | DType::Null
        ) && matches!(
            other.column.dtype(),
            DType::Int64 | DType::Float64 | DType::Null
        ) {
            let op_fn = |a: f64, b: f64| -> f64 {
                match op {
                    ArithmeticOp::Add => a + b,
                    ArithmeticOp::Sub => a - b,
                    ArithmeticOp::Mul => a * b,
                    ArithmeticOp::Div => a / b,
                    ArithmeticOp::Mod => a - (a / b).floor() * b,
                    ArithmeticOp::Pow => a.powf(b),
                    ArithmeticOp::FloorDiv => (a / b).floor(),
                }
            };
            let column = binary_gather_op_fill_numeric(
                &self.column,
                &plan.left_positions,
                &other.column,
                &plan.right_positions,
                &op_fn,
                fill_value,
            )?;
            let out_name = if self.name == other.name {
                self.name.clone()
            } else {
                let op_sym = match op {
                    ArithmeticOp::Add => "+",
                    ArithmeticOp::Sub => "-",
                    ArithmeticOp::Mul => "*",
                    ArithmeticOp::Div => "/",
                    ArithmeticOp::Mod => "%",
                    ArithmeticOp::Pow => "**",
                    ArithmeticOp::FloorDiv => "//",
                };
                format!("{}{op_sym}{}", self.name, other.name)
            };
            let shared_index_name = if self.index.name() == other.index.name() {
                self.index.name()
            } else {
                None
            };
            let index = plan.union_index.rename_index(shared_index_name);
            return Self::new(out_name, index, column);
        }

        let left_col = self.column.reindex_by_positions(&plan.left_positions)?;
        let right_col = other.column.reindex_by_positions(&plan.right_positions)?;

        let mut out = Vec::with_capacity(plan.union_index.len());
        for (lv, rv) in left_col.values().iter().zip(right_col.values().iter()) {
            let result = match (lv.is_missing(), rv.is_missing()) {
                (true, true) => Scalar::Null(NullKind::NaN),
                (true, false) => {
                    let r = rv.to_f64().map_err(ColumnError::from)?;
                    let v = match op {
                        ArithmeticOp::Add => fill_value + r,
                        ArithmeticOp::Sub => fill_value - r,
                        ArithmeticOp::Mul => fill_value * r,
                        // Per br-frankenpandas: pandas div/floordiv by zero give
                        // +/-inf (sign of the numerator), NOT NaN — only 0/0 is
                        // NaN. Rust IEEE division already produces inf/-inf/nan,
                        // so do NOT special-case a zero divisor. (Mod by zero IS
                        // NaN in both pandas and Rust.)
                        ArithmeticOp::Div => fill_value / r,
                        // pandas mod takes the sign of the DIVISOR (floored
                        // remainder), unlike Rust's % which takes the dividend's
                        // sign: 3 % -2 == -1, not 1. Use the floored identity
                        // l - floor(l/r)*r (also yields NaN for a zero divisor).
                        ArithmeticOp::Mod => fill_value - (fill_value / r).floor() * r,
                        ArithmeticOp::Pow => fill_value.powf(r),
                        ArithmeticOp::FloorDiv => (fill_value / r).floor(),
                    };
                    Scalar::Float64(v)
                }
                (false, true) => {
                    let l = lv.to_f64().map_err(ColumnError::from)?;
                    let v = match op {
                        ArithmeticOp::Add => l + fill_value,
                        ArithmeticOp::Sub => l - fill_value,
                        ArithmeticOp::Mul => l * fill_value,
                        // div/floordiv by zero -> +/-inf (numerator sign), 0/0 ->
                        // NaN; rely on Rust IEEE division (see (true,false) arm).
                        ArithmeticOp::Div => l / fill_value,
                        ArithmeticOp::Mod => l - (l / fill_value).floor() * fill_value,
                        ArithmeticOp::Pow => l.powf(fill_value),
                        ArithmeticOp::FloorDiv => (l / fill_value).floor(),
                    };
                    Scalar::Float64(v)
                }
                (false, false) => {
                    let l = lv.to_f64().map_err(ColumnError::from)?;
                    let r = rv.to_f64().map_err(ColumnError::from)?;
                    let v = match op {
                        ArithmeticOp::Add => l + r,
                        ArithmeticOp::Sub => l - r,
                        ArithmeticOp::Mul => l * r,
                        // div/floordiv by zero -> +/-inf (numerator sign), 0/0 ->
                        // NaN; rely on Rust IEEE division (see (true,false) arm).
                        ArithmeticOp::Div => l / r,
                        ArithmeticOp::Mod => l - (l / r).floor() * r,
                        ArithmeticOp::Pow => l.powf(r),
                        ArithmeticOp::FloorDiv => (l / r).floor(),
                    };
                    Scalar::Float64(v)
                }
            };
            out.push(result);
        }

        let out_name = if self.name == other.name {
            self.name.clone()
        } else {
            let op_sym = match op {
                ArithmeticOp::Add => "+",
                ArithmeticOp::Sub => "-",
                ArithmeticOp::Mul => "*",
                ArithmeticOp::Div => "/",
                ArithmeticOp::Mod => "%",
                ArithmeticOp::Pow => "**",
                ArithmeticOp::FloorDiv => "//",
            };
            format!("{}{op_sym}{}", self.name, other.name)
        };

        // Per br-frankenpandas-aed1h: pandas Series arithmetic preserves
        // the shared index name when both operands agree (and clears it
        // when they differ).
        let shared_index_name = if self.index.name() == other.index.name() {
            self.index.name()
        } else {
            None
        };
        let index = plan.union_index.rename_index(shared_index_name);
        let column = Column::from_values(out)?;
        Self::new(out_name, index, column)
    }

    /// Add with fill_value for NaN handling.
    ///
    /// Matches `s1.add(s2, fill_value=0)`.
    pub fn add_fill(&self, other: &Self, fill_value: f64) -> Result<Self, FrameError> {
        self.binary_op_fill(other, ArithmeticOp::Add, fill_value)
    }

    /// Subtract with fill_value for NaN handling.
    pub fn sub_fill(&self, other: &Self, fill_value: f64) -> Result<Self, FrameError> {
        self.binary_op_fill(other, ArithmeticOp::Sub, fill_value)
    }

    /// Multiply with fill_value for NaN handling.
    pub fn mul_fill(&self, other: &Self, fill_value: f64) -> Result<Self, FrameError> {
        self.binary_op_fill(other, ArithmeticOp::Mul, fill_value)
    }

    /// Divide with fill_value for NaN handling.
    pub fn div_fill(&self, other: &Self, fill_value: f64) -> Result<Self, FrameError> {
        self.binary_op_fill(other, ArithmeticOp::Div, fill_value)
    }

