/// Single-pass dense groupby `diff(periods)` over an all-valid no-NaN Float64
/// value slice and a precomputed dense gid per row (br-frankenpandas-gbcum).
/// Keeps a per-gid ring buffer of the last `periods` values so each output is
/// `v - v_periods_ago_within_group` in one row-order pass; the first `periods`
/// rows of each group are invalid (group-boundary nulls). Bit-identical to the
/// generic per-group `vals[i] - vals[i-periods]` scan: rows are visited in
/// ascending order, the subtraction order is preserved, and an invalid bit
/// materializes the same `Null(NaN)`. `periods` must be >= 1.
/// Key-offset sibling of [`dense_groupby_diff_f64`]: indexes the per-group ring
/// buffer by the int64 key's dense offset `(key - min)` DIRECTLY, so it never
/// materializes the n-element `gid_per_row` Vec that `dense_group_ids` builds and
/// reads back (the bulk of grouped shift/diff — diff was 0.35x, shift 0.25x).
/// Bit-identical: each distinct key is one group, processed in row order, so the
/// per-group history/validity is identical to the gid-keyed version.
fn dense_groupby_diff_f64_by_key(
    keys: &[i64],
    min: i64,
    range: usize,
    vals: &[f64],
    periods: usize,
) -> (Vec<f64>, fp_columnar::ValidityMask) {
    let n = vals.len();
    if periods == 1 {
        let mut last = vec![0.0_f64; range];
        let mut seen = vec![0_u8; range];
        let mut out = vec![0.0_f64; n];
        let mut words = vec![0u64; n.div_ceil(64)];
        for row in 0..n {
            let off = (keys[row] as i128 - min as i128) as usize;
            let v = vals[row];
            if seen[off] != 0 {
                out[row] = v - last[off];
                words[row / 64] |= 1u64 << (row % 64);
            } else {
                seen[off] = 1;
            }
            last[off] = v;
        }
        return (out, fp_columnar::ValidityMask::from_words(words, n));
    }
    let mut hist = vec![0.0_f64; range.saturating_mul(periods)];
    let mut cnt = vec![0usize; range];
    let mut out = vec![0.0_f64; n];
    let mut words = vec![0u64; n.div_ceil(64)];
    for row in 0..n {
        let off = (keys[row] as i128 - min as i128) as usize;
        let v = vals[row];
        let c = cnt[off];
        let slot = off * periods + (c % periods);
        if c >= periods {
            out[row] = v - hist[slot];
            words[row / 64] |= 1u64 << (row % 64);
        }
        hist[slot] = v;
        cnt[off] = c + 1;
    }
    (out, fp_columnar::ValidityMask::from_words(words, n))
}

