/// NULLABLE-aware key-offset dense groupby `shift(periods)` over a Float64 column
/// with a validity mask (the all-valid `dense_groupby_shift_f64_by_key` gates on
/// no-missing, so a column with nulls fell to the generic per-group Scalar path —
/// grouped shift on 20%-null f64 was ~18x slower than pandas). Emits the value
/// `periods` rows earlier WITHIN the group, CARRYING that source's missing-ness:
/// a shifted-in position (first `periods` of the group) is missing, and a shifted
/// value that was itself missing stays missing. Bit-identical to the generic
/// `out[idx] = vals[src].clone()` shift for a Float64 column (a present source →
/// its datum; a missing source → missing; source non-NaN by construction so a set
/// bit carries a real value). Ring buffer carries (datum, valid) per group slot.
fn dense_groupby_shift_nullable_f64_by_key(
    keys: &[i64],
    min: i64,
    range: usize,
    data: &[f64],
    validity: &fp_columnar::ValidityMask,
    periods: usize,
) -> (Vec<f64>, fp_columnar::ValidityMask) {
    let n = data.len();
    if periods == 1 {
        let mut last = vec![0.0_f64; range];
        let mut last_valid = vec![false; range];
        let mut seen = vec![0_u8; range];
        let mut out = vec![0.0_f64; n];
        let mut words = vec![0u64; n.div_ceil(64)];
        for row in 0..n {
            let off = (keys[row] as i128 - min as i128) as usize;
            if seen[off] != 0 && last_valid[off] {
                out[row] = last[off];
                words[row / 64] |= 1u64 << (row % 64);
            }
            last[off] = data[row];
            last_valid[off] = validity.get(row);
            seen[off] = 1;
        }
        return (out, fp_columnar::ValidityMask::from_words(words, n));
    }
    let mut hist = vec![0.0_f64; range.saturating_mul(periods)];
    let mut hist_valid = vec![false; range.saturating_mul(periods)];
    let mut cnt = vec![0usize; range];
    let mut out = vec![0.0_f64; n];
    let mut words = vec![0u64; n.div_ceil(64)];
    for row in 0..n {
        let off = (keys[row] as i128 - min as i128) as usize;
        let c = cnt[off];
        let slot = off * periods + (c % periods);
        if c >= periods && hist_valid[slot] {
            out[row] = hist[slot];
            words[row / 64] |= 1u64 << (row % 64);
        }
        hist[slot] = data[row];
        hist_valid[slot] = validity.get(row);
        cnt[off] = c + 1;
    }
    (out, fp_columnar::ValidityMask::from_words(words, n))
}

