/// NULLABLE-aware key-offset dense groupby `diff(periods)` over a Float64 column
/// with validity. Sister of [`dense_groupby_diff_f64_by_key`] but POSITIONAL and
/// NaN-propagating: `out = v - v_{periods-back}`, valid iff BOTH the current slot
/// and the `periods`-back slot are present (the all-valid path gates on
/// `as_f64_slice`, so a nullable column fell to the generic Scalar gather —
/// grouped diff on 20%-null f64 was ~17x slower than pandas). Bit-identical to the
/// generic `value.is_missing() || previous.is_missing() -> NaN; else cur - prev`.
fn dense_groupby_diff_nullable_f64_by_key(
    keys: &[i64],
    min: i64,
    range: usize,
    data: &[f64],
    validity: &fp_columnar::ValidityMask,
    periods: usize,
) -> (Vec<f64>, fp_columnar::ValidityMask) {
    let n = data.len();
    let mut hist = vec![0.0_f64; range.saturating_mul(periods)];
    let mut hist_valid = vec![false; range.saturating_mul(periods)];
    let mut cnt = vec![0usize; range];
    let mut out = vec![0.0_f64; n];
    let mut words = vec![0u64; n.div_ceil(64)];
    for row in 0..n {
        let off = (keys[row] as i128 - min as i128) as usize;
        let cur_valid = validity.get(row);
        let c = cnt[off];
        let slot = off * periods + (c % periods);
        if c >= periods && cur_valid && hist_valid[slot] {
            out[row] = data[row] - hist[slot];
            words[row / 64] |= 1u64 << (row % 64);
        }
        hist[slot] = data[row];
        hist_valid[slot] = cur_valid;
        cnt[off] = c + 1;
    }
    (out, fp_columnar::ValidityMask::from_words(words, n))
}

