/// Int64-input sister of [`dense_groupby_diff_nullable_f64_by_key`]: grouped
/// `diff(periods)` over an Int64 value column, producing a **Float64** output
/// (`out = cur as f64 - prev as f64`), exactly as the generic path does via
/// `value.to_f64() - previous.to_f64()` — pandas returns float64 for int diff.
/// Valid iff BOTH the current slot and the `periods`-back slot are present. The
/// ring stores the i64-as-f64 value so the subtract is a plain f64 op. Bit-
/// identical to the generic Scalar diff for an Int64 column (missing slots ->
/// `missing_for_dtype(Float64)` = `Null(NaN)`, which the generic also emits).
fn dense_groupby_diff_i64_to_f64_by_key(
    keys: &[i64],
    min: i64,
    range: usize,
    data: &[i64],
    validity: &fp_columnar::ValidityMask,
    periods: usize,
) -> (Vec<f64>, fp_columnar::ValidityMask) {
    let n = data.len();
    let mut hist = vec![0.0_f64; range.saturating_mul(periods)];
    let mut hist_valid = vec![false; range.saturating_mul(periods)];
    let mut cnt = vec![0usize; range];
    let mut out = vec![0.0_f64; n];
    let mut words = vec![0u64; n.div_ceil(64)];
    for row in 0..n {
        let off = (keys[row] as i128 - min as i128) as usize;
        let cur_valid = validity.get(row);
        let cur = data[row] as f64;
        let c = cnt[off];
        let slot = off * periods + (c % periods);
        if c >= periods && cur_valid && hist_valid[slot] {
            out[row] = cur - hist[slot];
            words[row / 64] |= 1u64 << (row % 64);
        }
        hist[slot] = cur;
        hist_valid[slot] = cur_valid;
        cnt[off] = c + 1;
    }
    (out, fp_columnar::ValidityMask::from_words(words, n))
}

