#[cfg(feature = "lazy-transpose-view")]
enum LazyDataFrameColumnOrder {
    Eager(Vec<String>),
    Int64UnitRange {
        start: i64,
        len: usize,
        materialized: OnceLock<Vec<String>>,
    },
}

#[cfg(feature = "lazy-transpose-view")]
impl LazyDataFrameColumnOrder {
    fn int64_unit_range(start: i64, len: usize) -> Self {
        Self::Int64UnitRange {
            start,
            len,
            materialized: OnceLock::new(),
        }
    }

    /// O(1) single-name access: an `Int64UnitRange` order formats the one
    /// label directly instead of materializing all n label `String`s (the
    /// `column_names()` path). Mirrors pandas' `df.columns[i]`, which never
    /// materializes the whole axis for one lookup.
    fn name_at(&self, position: usize) -> Option<String> {
        match self {
            Self::Eager(names) => names.get(position).cloned(),
            Self::Int64UnitRange {
                start,
                len,
                materialized,
            } => {
                if position >= *len {
                    return None;
                }
                if let Some(names) = materialized.get() {
                    return names.get(position).cloned();
                }
                Some(
                    start
                        .checked_add(i64::try_from(position).ok()?)?
                        .to_string(),
                )
            }
        }
    }

    fn is_lazy_range(&self) -> bool {
        matches!(
            self,
            Self::Int64UnitRange { materialized, .. } if materialized.get().is_none()
        )
    }

    fn materialize_range(start: i64, len: usize) -> Vec<String> {
        (0..len)
            .map(|offset| {
                let offset =
                    i64::try_from(offset).expect("transpose output column count must fit in i64");
                start
                    .checked_add(offset)
                    .expect("certified transpose column label must fit in i64")
                    .to_string()
            })
            .collect()
    }

    fn materialized(&self) -> &Vec<String> {
        match self {
            Self::Eager(order) => order,
            Self::Int64UnitRange {
                start,
                len,
                materialized,
            } => materialized.get_or_init(|| Self::materialize_range(*start, *len)),
        }
    }

    fn make_eager(&mut self) -> &mut Vec<String> {
        if matches!(self, Self::Int64UnitRange { .. }) {
            let previous = std::mem::replace(self, Self::Eager(Vec::new()));
            let Self::Int64UnitRange {
                start,
                len,
                materialized,
            } = previous
            else {
                unreachable!();
            };
            let order = materialized
                .into_inner()
                .unwrap_or_else(|| Self::materialize_range(start, len));
            *self = Self::Eager(order);
        }
        let Self::Eager(order) = self else {
            unreachable!();
        };
        order
    }

    fn into_materialized(self) -> Vec<String> {
        match self {
            Self::Eager(order) => order,
            Self::Int64UnitRange {
                start,
                len,
                materialized,
            } => materialized
                .into_inner()
                .unwrap_or_else(|| Self::materialize_range(start, len)),
        }
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl From<Vec<String>> for LazyDataFrameColumnOrder {
    fn from(order: Vec<String>) -> Self {
        Self::Eager(order)
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl From<LazyDataFrameColumnOrder> for Vec<String> {
    fn from(order: LazyDataFrameColumnOrder) -> Self {
        order.into_materialized()
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl Default for LazyDataFrameColumnOrder {
    fn default() -> Self {
        Self::Eager(Vec::new())
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl Clone for LazyDataFrameColumnOrder {
    fn clone(&self) -> Self {
        match self {
            Self::Eager(order) => Self::Eager(order.clone()),
            Self::Int64UnitRange {
                start,
                len,
                materialized,
            } => {
                let cloned = OnceLock::new();
                if let Some(order) = materialized.get() {
                    let _ = cloned.set(order.clone());
                }
                Self::Int64UnitRange {
                    start: *start,
                    len: *len,
                    materialized: cloned,
                }
            }
        }
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl PartialEq for LazyDataFrameColumnOrder {
    fn eq(&self, other: &Self) -> bool {
        self.materialized() == other.materialized()
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl<T: AsRef<str>> PartialEq<Vec<T>> for LazyDataFrameColumnOrder {
    fn eq(&self, other: &Vec<T>) -> bool {
        self.materialized().len() == other.len()
            && self
                .materialized()
                .iter()
                .zip(other)
                .all(|(left, right)| left == right.as_ref())
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl<T: AsRef<str>> PartialEq<LazyDataFrameColumnOrder> for Vec<T> {
    fn eq(&self, other: &LazyDataFrameColumnOrder) -> bool {
        other == self
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl<T: AsRef<str>, const N: usize> PartialEq<&[T; N]> for LazyDataFrameColumnOrder {
    fn eq(&self, other: &&[T; N]) -> bool {
        self.materialized().len() == N
            && self
                .materialized()
                .iter()
                .zip(other.iter())
                .all(|(left, right)| left == right.as_ref())
    }
}

