#[cfg(feature = "lazy-transpose-view")]
type DataFrameColumnsStore = LazyDataFrameColumns;
#[cfg(not(feature = "lazy-transpose-view"))]
type DataFrameColumnsStore = ColumnStore;

#[cfg(feature = "lazy-transpose-view")]
type DataFrameColumnOrderStore = LazyDataFrameColumnOrder;
#[cfg(not(feature = "lazy-transpose-view"))]
type DataFrameColumnOrderStore = Vec<String>;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DataFrame {
    index: Index,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    row_multiindex: Option<fp_index::MultiIndex>,
    columns: DataFrameColumnsStore,
    // fd90.196: column_order is the user-visible insertion order. The
    // previous `#[serde(skip)]` silently dropped it on round-trip,
    // contradicting the README's "Round-trips perfectly" claim. Now
    // serialized normally with `default` for backwards-compat with any
    // pre-fd90.196 blobs (they'll deserialize with an empty Vec, which
    // matches the prior behavior).
    #[serde(default)]
    column_order: DataFrameColumnOrderStore,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    column_multiindex: Option<fp_index::MultiIndex>,
    #[serde(
        default = "default_allows_duplicate_labels",
        skip_serializing_if = "bool_is_true"
    )]
    allows_duplicate_labels: bool,
}

const fn default_allows_duplicate_labels() -> bool {
    true
}

fn bool_is_true(value: &bool) -> bool {
    *value
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct DataFrameFlags {
    allows_duplicate_labels: bool,
}

impl DataFrameFlags {
    #[must_use]
    pub fn allows_duplicate_labels(&self) -> bool {
        self.allows_duplicate_labels
    }
}

/// Feature-gated lazy homogeneous transpose view.
///
/// The view stores references to the original typed columns plus axis
/// metadata. Constructing it is O(number of source columns), not O(number of
/// source rows), so tall-frame `.T` can avoid building one public `Column` and
/// one `BTreeMap` entry per output column. Unsupported shapes keep using
/// [`DataFrame::transpose`].
#[cfg(feature = "lazy-transpose-view")]
#[derive(Debug, Clone)]
enum HomogeneousTransposeColumns<'a> {
    Float64(Vec<&'a [f64]>),
    Int64(Vec<&'a [i64]>),
    Bool(Vec<&'a [bool]>),
    Datetime64(Vec<&'a [i64]>),
    Timedelta64(Vec<&'a [i64]>),
    /// Mixed all-valid Int64/Float64 sources promoted to Float64 output,
    /// mirroring the eager fallback's `from_values` dtype inference for this
    /// shape (Int64 cells cast to f64; output dtype is Float64).
    PromotedFloat64(Vec<NumericTransposeSource<'a>>),
    /// All-valid contiguous-Utf8 sources, one `(bytes, offsets)` span pair
    /// per source column. Materialized output columns are built as
    /// contiguous-Utf8 directly (`from_utf8_contiguous` is semantically
    /// identical to `Column::new(DType::Utf8, scalars)` over the same
    /// strings), skipping the eager path's per-cell `String`/`Scalar` clone.
    Utf8(Vec<(&'a [u8], &'a [usize])>),
    /// Nullable Int64 sources as `(values, validity)` pairs. Int64 is the
    /// one numeric dtype whose missing representation is SINGLE-VALUED
    /// (`Scalar::Null(NullKind::Null)`), so a typed view plus validity fully
    /// reproduces the eager `values()` Scalars; Float64/temporal nullable
    /// shapes stay excluded (non-single-valued missing reps). Materialized
    /// rows go through `Column::from_values` — the exact eager constructor —
    /// so even the all-null-row dtype inference edge is identical.
    NullableInt64(Vec<(&'a [i64], &'a ValidityMask)>),
    /// CANONICAL nullable Float64 sources (`LazyNullableFloat64` backing
    /// only, certified by `as_canonical_nullable_f64`): the Scalar emission
    /// is fully determined by `(data, validity)` via the backing's own rule
    /// (`valid || data[i].is_nan()` → `Float64`, else `Null(NaN)`), so
    /// per-cell reconstruction plus `Column::from_values` — the exact eager
    /// constructor — is bit-identical. Eager nullable Float64 (mixed
    /// NullKinds) never reaches this arm.
    NullableFloat64(Vec<(&'a [f64], &'a ValidityMask)>),
}

/// One typed source column of a promoted mixed-numeric transpose view.
#[cfg(feature = "lazy-transpose-view")]
#[derive(Debug, Clone, Copy)]
enum NumericTransposeSource<'a> {
    F64(&'a [f64]),
    I64(&'a [i64]),
}

#[cfg(feature = "lazy-transpose-view")]
impl NumericTransposeSource<'_> {
    fn get_f64(&self, position: usize) -> Option<f64> {
        match self {
            Self::F64(values) => values.get(position).copied(),
            Self::I64(values) => values.get(position).copied().map(|value| value as f64),
        }
    }
}

#[cfg(feature = "lazy-transpose-view")]
impl HomogeneousTransposeColumns<'_> {
    fn len(&self) -> usize {
        match self {
            Self::Float64(columns) => columns.len(),
            Self::Int64(columns) => columns.len(),
            Self::Bool(columns) => columns.len(),
            Self::Datetime64(columns) => columns.len(),
            Self::Timedelta64(columns) => columns.len(),
            Self::PromotedFloat64(columns) => columns.len(),
            Self::Utf8(columns) => columns.len(),
            Self::NullableInt64(columns) => columns.len(),
            Self::NullableFloat64(columns) => columns.len(),
        }
    }

    fn dtype(&self) -> DType {
        match self {
            Self::Float64(_) | Self::PromotedFloat64(_) | Self::NullableFloat64(_) => {
                DType::Float64
            }
            Self::Int64(_) | Self::NullableInt64(_) => DType::Int64,
            Self::Bool(_) => DType::Bool,
            Self::Datetime64(_) => DType::Datetime64,
            Self::Timedelta64(_) => DType::Timedelta64,
            Self::Utf8(_) => DType::Utf8,
        }
    }
}

#[cfg(feature = "lazy-transpose-view")]
#[derive(Debug, Clone)]
pub struct DataFrameTransposeView<'a> {
    source_columns: HomogeneousTransposeColumns<'a>,
    row_index: Index,
    column_start: i64,
    column_len: usize,
}

#[cfg(feature = "lazy-transpose-view")]
impl DataFrameTransposeView<'_> {
    /// Return `(rows, columns)` for the transposed view.
    #[must_use]
    pub fn shape(&self) -> (usize, usize) {
        (self.source_columns.len(), self.column_len)
    }

    /// Return the homogeneous dtype carried by this view.
    #[must_use]
    pub fn dtype(&self) -> DType {
        self.source_columns.dtype()
    }

    /// Return the transposed value at `(row, column)` without materializing an
    /// output `Column`.
    #[must_use]
    pub fn get_scalar(&self, row: usize, column: usize) -> Option<Scalar> {
        match &self.source_columns {
            HomogeneousTransposeColumns::Float64(columns) => {
                columns.get(row)?.get(column).copied().map(Scalar::Float64)
            }
            HomogeneousTransposeColumns::Int64(columns) => {
                columns.get(row)?.get(column).copied().map(Scalar::Int64)
            }
            HomogeneousTransposeColumns::Bool(columns) => {
                columns.get(row)?.get(column).copied().map(Scalar::Bool)
            }
            HomogeneousTransposeColumns::Datetime64(columns) => columns
                .get(row)?
                .get(column)
                .copied()
                .map(Scalar::Datetime64),
            HomogeneousTransposeColumns::Timedelta64(columns) => columns
                .get(row)?
                .get(column)
                .copied()
                .map(Scalar::Timedelta64),
            HomogeneousTransposeColumns::PromotedFloat64(columns) => {
                columns.get(row)?.get_f64(column).map(Scalar::Float64)
            }
            HomogeneousTransposeColumns::Utf8(columns) => {
                let (bytes, offsets) = columns.get(row)?;
                let start = *offsets.get(column)?;
                let end = *offsets.get(column + 1)?;
                std::str::from_utf8(&bytes[start..end])
                    .ok()
                    .map(|value| Scalar::Utf8(value.to_owned()))
            }
            HomogeneousTransposeColumns::NullableInt64(columns) => {
                let (values, validity) = columns.get(row)?;
                let value = *values.get(column)?;
                Some(if validity.get(column) {
                    Scalar::Int64(value)
                } else {
                    Scalar::Null(NullKind::Null)
                })
            }
            HomogeneousTransposeColumns::NullableFloat64(columns) => {
                let (values, validity) = columns.get(row)?;
                let value = *values.get(column)?;
                Some(if validity.get(column) || value.is_nan() {
                    Scalar::Float64(value)
                } else {
                    Scalar::Null(NullKind::NaN)
                })
            }
        }
    }

    /// Return a Float64 value when this view carries Float64 data.
    #[must_use]
    pub fn get_f64(&self, row: usize, column: usize) -> Option<f64> {
        match &self.source_columns {
            HomogeneousTransposeColumns::Float64(columns) => columns.get(row)?.get(column).copied(),
            HomogeneousTransposeColumns::PromotedFloat64(columns) => {
                columns.get(row)?.get_f64(column)
            }
            _ => None,
        }
    }

    /// Return an Int64 value when this view carries Int64 data.
    #[must_use]
    pub fn get_i64(&self, row: usize, column: usize) -> Option<i64> {
        let HomogeneousTransposeColumns::Int64(columns) = &self.source_columns else {
            return None;
        };
        columns.get(row)?.get(column).copied()
    }

    /// Return a Bool value when this view carries Bool data.
    #[must_use]
    pub fn get_bool(&self, row: usize, column: usize) -> Option<bool> {
        let HomogeneousTransposeColumns::Bool(columns) = &self.source_columns else {
            return None;
        };
        columns.get(row)?.get(column).copied()
    }

    /// Return a Datetime64 nanosecond value when this view carries Datetime64 data.
    #[must_use]
    pub fn get_datetime64(&self, row: usize, column: usize) -> Option<i64> {
        let HomogeneousTransposeColumns::Datetime64(columns) = &self.source_columns else {
            return None;
        };
        columns.get(row)?.get(column).copied()
    }

    /// Return a Timedelta64 nanosecond value when this view carries Timedelta64 data.
    #[must_use]
    pub fn get_timedelta64(&self, row: usize, column: usize) -> Option<i64> {
        let HomogeneousTransposeColumns::Timedelta64(columns) = &self.source_columns else {
            return None;
        };
        columns.get(row)?.get(column).copied()
    }

    /// Return one lazily generated output column name.
    #[must_use]
    pub fn column_name(&self, column: usize) -> Option<String> {
        (column < self.column_len)
            .then(|| self.column_start.checked_add(i64::try_from(column).ok()?))
            .flatten()
            .map(|label| label.to_string())
    }

    /// Materialize one output column on demand.
    #[must_use]
    pub fn column(&self, column: usize) -> Option<Column> {
        if column >= self.column_len {
            return None;
        }
        match &self.source_columns {
            HomogeneousTransposeColumns::Float64(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(*source.get(column)?);
                }
                Some(Column::from_f64_values(values))
            }
            HomogeneousTransposeColumns::Int64(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(*source.get(column)?);
                }
                Some(Column::from_i64_values_owned(values))
            }
            HomogeneousTransposeColumns::Bool(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(*source.get(column)?);
                }
                Some(Column::from_bool_values(values))
            }
            HomogeneousTransposeColumns::Datetime64(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(*source.get(column)?);
                }
                Some(Column::from_datetime64_values(values))
            }
            HomogeneousTransposeColumns::Timedelta64(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(*source.get(column)?);
                }
                let len = values.len();
                Some(Column::from_timedelta64_values_with_validity(
                    values,
                    ValidityMask::all_valid(len),
                ))
            }
            HomogeneousTransposeColumns::PromotedFloat64(columns) => {
                let mut values = Vec::with_capacity(columns.len());
                for source in columns {
                    values.push(source.get_f64(column)?);
                }
                Some(Column::from_f64_values(values))
            }
            HomogeneousTransposeColumns::Utf8(columns) => {
                let mut bytes = Vec::new();
                let mut offsets = Vec::with_capacity(columns.len() + 1);
                offsets.push(0);
                for (src_bytes, src_offsets) in columns {
                    let start = *src_offsets.get(column)?;
                    let end = *src_offsets.get(column + 1)?;
                    bytes.extend_from_slice(&src_bytes[start..end]);
                    offsets.push(bytes.len());
                }
                Some(Column::from_utf8_contiguous(bytes, offsets))
            }
            HomogeneousTransposeColumns::NullableInt64(columns) => {
                let mut scalars = Vec::with_capacity(columns.len());
                for (values, validity) in columns {
                    let value = *values.get(column)?;
                    scalars.push(if validity.get(column) {
                        Scalar::Int64(value)
                    } else {
                        Scalar::Null(NullKind::Null)
                    });
                }
                Column::from_values(scalars).ok()
            }
            HomogeneousTransposeColumns::NullableFloat64(columns) => {
                let mut scalars = Vec::with_capacity(columns.len());
                for (values, validity) in columns {
                    let value = *values.get(column)?;
                    scalars.push(if validity.get(column) || value.is_nan() {
                        Scalar::Float64(value)
                    } else {
                        Scalar::Null(NullKind::NaN)
                    });
                }
                Column::from_values(scalars).ok()
            }
        }
    }

    /// Return the row index of the transposed view (the source column names).
    #[must_use]
    pub fn row_index(&self) -> &Index {
        &self.row_index
    }
}

/// Which extreme a `highlight_*` rule marks within each numeric column.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HighlightKind {
    Max,
    Min,
}

/// A `highlight_max` / `highlight_min` directive: paint the per-column
/// extreme cell(s) with `color`. Matches pandas `Styler.highlight_max(axis=0)`
/// (and ties are all highlighted, as pandas does).
#[derive(Debug, Clone, PartialEq)]
struct HighlightRule {
    kind: HighlightKind,
    color: String,
}

/// A two-colour `background_gradient` directive. pandas defaults to a
/// matplotlib colormap (`PuBu`); replicating matplotlib's colormaps would
/// require linking their lookup tables, so this pure-Rust port interpolates
/// linearly between two caller-supplied `#rrggbb` endpoints over each column's
/// `[min, max]` range — the common, dependency-free case.
#[derive(Debug, Clone, PartialEq)]
struct GradientRule {
    low: (u8, u8, u8),
    high: (u8, u8, u8),
}

/// An in-cell bar-chart directive (pandas `Styler.bar`): each numeric cell is
/// backed by a CSS `linear-gradient` whose filled width is proportional to the
/// value within its column's `[min, max]` range.
#[derive(Debug, Clone, PartialEq)]
struct BarRule {
    color: String,
}

/// Accumulated, order-preserving styling directives for a [`StyledDataFrame`].
#[derive(Debug, Clone, PartialEq, Default)]
struct StyleDirectives {
    caption: Option<String>,
    number_format: Option<String>,
    na_rep: Option<String>,
    highlights: Vec<HighlightRule>,
    gradients: Vec<GradientRule>,
    properties: Vec<(String, String)>,
    bars: Vec<BarRule>,
    hide_index: bool,
}

impl StyleDirectives {
    fn is_empty(&self) -> bool {
        self.caption.is_none()
            && self.number_format.is_none()
            && self.na_rep.is_none()
            && self.highlights.is_empty()
            && self.gradients.is_empty()
            && self.properties.is_empty()
            && self.bars.is_empty()
            && !self.hide_index
    }
}

/// A lightweight analogue of pandas' `Styler`, returned by [`DataFrame::style`].
///
/// Directive methods (`highlight_max`, `highlight_min`, `background_gradient`,
/// `format`, `set_caption`) consume and return `self` so they chain like the
/// pandas builder API. With no directives set, [`StyledDataFrame::to_html`]
/// reproduces [`DataFrame::to_html`] byte-for-byte; once any directive is set,
/// the renderer emits per-cell inline `style` attributes and an optional
/// `<caption>`.
#[derive(Debug, Clone, PartialEq)]
pub struct StyledDataFrame<'a> {
    df: &'a DataFrame,
    directives: StyleDirectives,
}

impl<'a> StyledDataFrame<'a> {
    #[must_use]
    pub fn dataframe(&self) -> &'a DataFrame {
        self.df
    }

    fn escape_html_attr(value: &str) -> String {
        value
            .replace('&', "&amp;")
            .replace('"', "&quot;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
    }

    fn escape_html_text(value: &str) -> String {
        value
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
    }

    /// Highlight the maximum value in each numeric column with `color`
    /// (pandas `Styler.highlight_max(color=...)`, `axis=0`). Ties are all
    /// highlighted, matching pandas.
    #[must_use]
    pub fn highlight_max(mut self, color: &str) -> Self {
        self.directives.highlights.push(HighlightRule {
            kind: HighlightKind::Max,
            color: color.to_owned(),
        });
        self
    }

    /// Highlight the minimum value in each numeric column with `color`
    /// (pandas `Styler.highlight_min(color=...)`, `axis=0`).
    #[must_use]
    pub fn highlight_min(mut self, color: &str) -> Self {
        self.directives.highlights.push(HighlightRule {
            kind: HighlightKind::Min,
            color: color.to_owned(),
        });
        self
    }

    /// Shade numeric cells along a two-colour gradient from `low` (column
    /// minimum) to `high` (column maximum). Endpoints are `#rrggbb` hex
    /// strings; unparseable endpoints make the directive a no-op. Approximates
    /// pandas `Styler.background_gradient` without a matplotlib colormap.
    #[must_use]
    pub fn background_gradient(mut self, low: &str, high: &str) -> Self {
        if let (Some(low), Some(high)) = (Self::parse_hex_color(low), Self::parse_hex_color(high)) {
            self.directives.gradients.push(GradientRule { low, high });
        }
        self
    }

    /// Apply a Python-style format string to numeric cells, e.g. `"{:.2f}"`,
    /// `"${:,.2f}"`, or `"{:.1%}"` (pandas `Styler.format(fmt)`). Literal text
    /// surrounding the `{...}` placeholder is preserved. A format string with
    /// no placeholder leaves values unformatted.
    #[must_use]
    pub fn format(mut self, fmt: &str) -> Self {
        self.directives.number_format = Some(fmt.to_owned());
        self
    }

    /// Render missing / NaN cells with `placeholder` instead of the default
    /// `"NaN"` (pandas `Styler.format(na_rep=...)`).
    #[must_use]
    pub fn na_rep(mut self, placeholder: &str) -> Self {
        self.directives.na_rep = Some(placeholder.to_owned());
        self
    }

    /// Set the table caption rendered as a `<caption>` element
    /// (pandas `Styler.set_caption`).
    #[must_use]
    pub fn set_caption(mut self, caption: &str) -> Self {
        self.directives.caption = Some(caption.to_owned());
        self
    }

    /// Apply fixed CSS `(property, value)` pairs to every data cell
    /// (pandas `Styler.set_properties(**css)`), e.g.
    /// `&[("background-color", "black"), ("color", "white")]`.
    #[must_use]
    pub fn set_properties(mut self, props: &[(&str, &str)]) -> Self {
        self.directives.properties.extend(
            props
                .iter()
                .map(|(k, v)| ((*k).to_owned(), (*v).to_owned())),
        );
        self
    }

    /// Draw an in-cell horizontal bar chart in each numeric cell, with the
    /// filled width proportional to the value within its column's `[min, max]`
    /// range (pandas `Styler.bar(color=...)`). Rendered as a CSS
    /// `linear-gradient` background.
    #[must_use]
    pub fn bar(mut self, color: &str) -> Self {
        self.directives.bars.push(BarRule {
            color: color.to_owned(),
        });
        self
    }

    /// Omit the index column and its header from the HTML render
    /// (pandas `Styler.hide(axis="index")`, formerly `hide_index()`).
    #[must_use]
    pub fn hide_index(mut self) -> Self {
        self.directives.hide_index = true;
        self
    }

    fn parse_hex_color(s: &str) -> Option<(u8, u8, u8)> {
        let h = s.strip_prefix('#').unwrap_or(s);
        if h.len() != 6 || !h.bytes().all(|b| b.is_ascii_hexdigit()) {
            return None;
        }
        let r = u8::from_str_radix(&h[0..2], 16).ok()?;
        let g = u8::from_str_radix(&h[2..4], 16).ok()?;
        let b = u8::from_str_radix(&h[4..6], 16).ok()?;
        Some((r, g, b))
    }

    fn numeric_value(scalar: &Scalar) -> Option<f64> {
        match scalar {
            Scalar::Int64(v) => Some(*v as f64),
            Scalar::Float64(v) if !v.is_nan() => Some(*v),
            Scalar::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => None,
        }
    }

    /// Apply a `format` spec like `"{:.2f}"` / `"${:,.2f}"` / `"{:.1%}"` to a
    /// numeric value, preserving any literal prefix/suffix around the
    /// placeholder. Returns `None` when the spec has no `{...}` placeholder.
    fn apply_number_format(fmt: &str, value: f64) -> Option<String> {
        let open = fmt.find('{')?;
        let close = fmt[open..].find('}')? + open;
        let prefix = &fmt[..open];
        let suffix = &fmt[close + 1..];
        let spec = fmt[open + 1..close].trim_start_matches(':');

        let thousands = spec.contains(',');
        let type_char = spec
            .chars()
            .last()
            .filter(|c| c.is_ascii_alphabetic() || *c == '%');
        let precision = spec
            .split('.')
            .nth(1)
            .map(|p| p.trim_end_matches([',', 'f', 'e', 'g', '%', 'd']))
            .and_then(|p| p.parse::<usize>().ok());

        let body = match type_char {
            Some('%') => {
                let p = precision.unwrap_or(0);
                format!("{:.*}%", p, value * 100.0)
            }
            Some('e') => {
                let p = precision.unwrap_or(6);
                format!("{value:.p$e}")
            }
            Some('d') => format!("{}", value.round() as i64),
            _ => {
                // 'f', 'g', or unspecified → fixed-point with the given precision.
                let p = precision.unwrap_or(6);
                format!("{value:.p$}")
            }
        };
        let body = if thousands {
            Self::insert_thousands_separators(&body)
        } else {
            body
        };
        Some(format!("{prefix}{body}{suffix}"))
    }

    /// Insert `,` group separators into the integer part of a formatted number.
    fn insert_thousands_separators(s: &str) -> String {
        let (sign, rest) = s.strip_prefix('-').map_or(("", s), |r| ("-", r));
        let (int_part, frac_part) = rest
            .split_once('.')
            .map_or((rest, None), |(i, f)| (i, Some(f)));
        let mut grouped = String::new();
        let bytes = int_part.as_bytes();
        for (i, ch) in int_part.char_indices() {
            if i > 0 && (bytes.len() - i) % 3 == 0 {
                grouped.push(',');
            }
            grouped.push(ch);
        }
        match frac_part {
            Some(f) => format!("{sign}{grouped}.{f}"),
            None => format!("{sign}{grouped}"),
        }
    }

    /// Format a scalar for an HTML cell, identical to `DataFrame::to_html`'s
    /// formatter when no `number_format` directive is active so the
    /// no-directive render stays byte-for-byte compatible.
    fn format_cell(&self, scalar: &Scalar) -> String {
        let is_missing =
            matches!(scalar, Scalar::Null(_)) || matches!(scalar, Scalar::Float64(v) if v.is_nan());
        if is_missing && let Some(na) = &self.directives.na_rep {
            return Self::escape_html_text(na);
        }
        if let Some(fmt) = &self.directives.number_format
            && let Some(v) = Self::numeric_value(scalar)
            && let Some(formatted) = Self::apply_number_format(fmt, v)
        {
            return Self::escape_html_text(&formatted);
        }
        match scalar {
            Scalar::Null(_) => "NaN".to_owned(),
            Scalar::Bool(b) => if *b { "True" } else { "False" }.to_owned(),
            Scalar::Int64(v) => v.to_string(),
            Scalar::Float64(v) => {
                if v.is_nan() {
                    "NaN".to_owned()
                } else if v.fract() == 0.0 {
                    format!("{v:.1}")
                } else {
                    v.to_string()
                }
            }
            Scalar::Utf8(s) => Self::escape_html_text(s),
            Scalar::Timedelta64(v) => Self::escape_html_text(&Timedelta::format(*v)),
            Scalar::Datetime64(v) => Self::escape_html_text(&format_datetime_ns(*v)),
            Scalar::Period(v) => v.calendar_string(),
            Scalar::Interval(interval) => Self::escape_html_text(&format!("{interval}")),
        }
    }

    /// Compute the inline `style` attribute body for every cell, indexed
    /// `[row][col]`, applying highlight then gradient directives in order.
    fn cell_styles(&self) -> Vec<Vec<String>> {
        let nrows = self.df.len();
        let order = &self.df.column_order;
        let mut styles = vec![vec![String::new(); order.len()]; nrows];

        // Fixed properties apply to every data cell, numeric or not.
        if !self.directives.properties.is_empty() {
            let prop_str: String = self
                .directives
                .properties
                .iter()
                .map(|(k, v)| format!("{k}: {v};"))
                .collect();
            for row in &mut styles {
                for cell in row.iter_mut() {
                    cell.push_str(&prop_str);
                }
            }
        }

        let needs_numeric = !self.directives.highlights.is_empty()
            || !self.directives.gradients.is_empty()
            || !self.directives.bars.is_empty();
        if !needs_numeric {
            return styles;
        }

        for (col_idx, name) in order.iter().enumerate() {
            let column = &self.df.columns[name];
            let values = column.values();
            let numeric: Vec<Option<f64>> = values.iter().map(Self::numeric_value).collect();
            let finite: Vec<f64> = numeric.iter().filter_map(|v| *v).collect();
            if finite.is_empty() {
                continue;
            }
            let col_min = finite.iter().copied().fold(f64::INFINITY, f64::min);
            let col_max = finite.iter().copied().fold(f64::NEG_INFINITY, f64::max);

            for rule in &self.directives.highlights {
                let target = match rule.kind {
                    HighlightKind::Max => col_max,
                    HighlightKind::Min => col_min,
                };
                for (row_idx, value) in numeric.iter().enumerate() {
                    if value.is_some_and(|v| v == target) {
                        styles[row_idx][col_idx]
                            .push_str(&format!("background-color: {};", rule.color));
                    }
                }
            }

            for rule in &self.directives.gradients {
                let span = col_max - col_min;
                for (row_idx, value) in numeric.iter().enumerate() {
                    if let Some(v) = value {
                        let t = if span > 0.0 {
                            (v - col_min) / span
                        } else {
                            0.0
                        };
                        let lerp = |lo: u8, hi: u8| {
                            (f64::from(lo) + t * (f64::from(hi) - f64::from(lo))).round() as u8
                        };
                        let (r, g, b) = (
                            lerp(rule.low.0, rule.high.0),
                            lerp(rule.low.1, rule.high.1),
                            lerp(rule.low.2, rule.high.2),
                        );
                        styles[row_idx][col_idx]
                            .push_str(&format!("background-color: #{r:02x}{g:02x}{b:02x};"));
                    }
                }
            }

            for rule in &self.directives.bars {
                let span = col_max - col_min;
                for (row_idx, value) in numeric.iter().enumerate() {
                    if let Some(v) = value {
                        let pct = if span > 0.0 {
                            ((v - col_min) / span * 100.0).round() as i64
                        } else {
                            100
                        };
                        styles[row_idx][col_idx].push_str(&format!(
                            "background: linear-gradient(90deg, {} {pct}%, transparent {pct}%);",
                            rule.color
                        ));
                    }
                }
            }
        }
        styles
    }

    /// Render the styled HTML table. With no directives this is byte-for-byte
    /// identical to [`DataFrame::to_html`]; otherwise it injects an optional
    /// `<caption>`, per-cell inline `style` attributes, and formatted values.
    fn render_html(&self, include_index: bool) -> String {
        if self.directives.is_empty() {
            return self.df.to_html(include_index);
        }
        // hide_index suppresses the index column/header regardless of caller.
        let include_index = include_index && !self.directives.hide_index;

        let styles = self.cell_styles();
        let mut out = String::new();
        out.push_str("<table border=\"1\" class=\"dataframe\">\n");
        if let Some(caption) = &self.directives.caption {
            out.push_str(&format!(
                "  <caption>{}</caption>\n",
                Self::escape_html_text(caption)
            ));
        }
        out.push_str("  <thead>\n    <tr style=\"text-align: right;\">\n");
        if include_index {
            out.push_str("      <th></th>\n");
        }
        for name in &self.df.column_order {
            out.push_str(&format!(
                "      <th>{}</th>\n",
                Self::escape_html_text(name)
            ));
        }
        out.push_str("    </tr>\n  </thead>\n  <tbody>\n");

        for (row_idx, label) in self.df.index.labels().iter().enumerate() {
            out.push_str("    <tr>\n");
            if include_index {
                let idx_str = match label {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => Self::escape_html_text(s),
                    IndexLabel::Timedelta64(ns) => Self::escape_html_text(&Timedelta::format(*ns)),
                    IndexLabel::Datetime64(ns) => Self::escape_html_text(&format_datetime_ns(*ns)),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    IndexLabel::Null(_) => label.to_string(),
                };
                out.push_str(&format!("      <th>{idx_str}</th>\n"));
            }
            for (col_idx, name) in self.df.column_order.iter().enumerate() {
                let value = &self.df.columns[name].values()[row_idx];
                let cell = self.format_cell(value);
                let style = &styles[row_idx][col_idx];
                if style.is_empty() {
                    out.push_str(&format!("      <td>{cell}</td>\n"));
                } else {
                    out.push_str(&format!("      <td style=\"{style}\">{cell}</td>\n"));
                }
            }
            out.push_str("    </tr>\n");
        }

        out.push_str("  </tbody>\n</table>");
        out
    }

    /// Render the styled DataFrame as an HTML table.
    ///
    /// With no directives this matches `DataFrame::to_html` exactly; with
    /// directives it emits inline cell styles and an optional caption.
    #[must_use]
    pub fn to_html(&self, include_index: bool) -> String {
        self.render_html(include_index)
    }

    /// Render the styled DataFrame as the plain text table representation.
    ///
    /// Styling directives are HTML-only (as in pandas), so this always renders
    /// the plain `DataFrame::to_string_table` form.
    #[must_use]
    pub fn to_string_table(&self, include_index: bool) -> String {
        self.df.to_string_table(include_index)
    }

    /// Render the HTML table with a single CSS class.
    #[must_use]
    pub fn to_html_classed(&self, include_index: bool, class_name: &str) -> String {
        self.to_html_with_classes(include_index, &[class_name])
    }

    /// Render the HTML table with caller-provided CSS classes.
    ///
    /// Empty class names are ignored. If no classes remain, the existing
    /// `dataframe` class is preserved.
    #[must_use]
    pub fn to_html_with_classes(&self, include_index: bool, classes: &[&str]) -> String {
        let class_attr = classes
            .iter()
            .filter_map(|class| {
                let trimmed = class.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(Self::escape_html_attr(trimmed))
                }
            })
            .collect::<Vec<_>>()
            .join(" ");
        let class_attr = if class_attr.is_empty() {
            "dataframe".to_owned()
        } else {
            class_attr
        };
        self.render_html(include_index).replacen(
            "class=\"dataframe\"",
            &format!("class=\"{class_attr}\""),
            1,
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SparseDataFrameView<'a> {
    df: &'a DataFrame,
}

impl<'a> SparseDataFrameView<'a> {
    #[must_use]
    pub fn dataframe(&self) -> &'a DataFrame {
        self.df
    }

    fn default_fill_value(column: &Column) -> Scalar {
        Scalar::missing_for_dtype(column.dtype())
    }

    fn column_npoints_for(column: &Column, fill_value: &Scalar) -> usize {
        column
            .values()
            .iter()
            .filter(|value| !value.semantic_eq(fill_value))
            .count()
    }

    fn density_for(npoints: usize, total_cells: usize) -> f64 {
        if total_cells == 0 {
            0.0
        } else {
            npoints as f64 / total_cells as f64
        }
    }

    fn total_cells(&self) -> usize {
        self.df
            .column_order
            .iter()
            .map(|name| self.df.columns[name].values().len())
            .sum()
    }

    /// Count non-fill values across all columns.
    ///
    /// Dense-backed DataFrames do not yet store per-column `SparseDType`
    /// descriptors, so the default fill value is each column dtype's missing
    /// marker.
    #[must_use]
    pub fn npoints(&self) -> usize {
        self.df
            .column_order
            .iter()
            .map(|name| {
                let column = &self.df.columns[name];
                Self::column_npoints_for(column, &Self::default_fill_value(column))
            })
            .sum()
    }

    /// Return total non-fill density across the DataFrame.
    #[must_use]
    pub fn density(&self) -> f64 {
        Self::density_for(self.npoints(), self.total_cells())
    }

    /// Count non-fill values in each column.
    #[must_use]
    pub fn column_npoints(&self) -> BTreeMap<String, usize> {
        self.df
            .column_order
            .iter()
            .map(|name| {
                let column = &self.df.columns[name];
                (
                    name.clone(),
                    Self::column_npoints_for(column, &Self::default_fill_value(column)),
                )
            })
            .collect()
    }

    /// Return non-fill density in each column.
    #[must_use]
    pub fn column_density(&self) -> BTreeMap<String, f64> {
        self.df
            .column_order
            .iter()
            .map(|name| {
                let column = &self.df.columns[name];
                let npoints = Self::column_npoints_for(column, &Self::default_fill_value(column));
                (
                    name.clone(),
                    Self::density_for(npoints, column.values().len()),
                )
            })
            .collect()
    }

    /// Count values that differ from a caller-provided fill value.
    ///
    /// This mirrors the Series sparse accessor's `SparseDType(fill_value)`
    /// semantics for callers that know the intended sparse fill value.
    #[must_use]
    pub fn npoints_with_fill_value(&self, fill_value: &Scalar) -> usize {
        self.df
            .column_order
            .iter()
            .map(|name| Self::column_npoints_for(&self.df.columns[name], fill_value))
            .sum()
    }

    /// Return total density using a caller-provided fill value.
    #[must_use]
    pub fn density_with_fill_value(&self, fill_value: &Scalar) -> f64 {
        Self::density_for(self.npoints_with_fill_value(fill_value), self.total_cells())
    }

    /// Count per-column values that differ from a caller-provided fill value.
    #[must_use]
    pub fn column_npoints_with_fill_value(&self, fill_value: &Scalar) -> BTreeMap<String, usize> {
        self.df
            .column_order
            .iter()
            .map(|name| {
                (
                    name.clone(),
                    Self::column_npoints_for(&self.df.columns[name], fill_value),
                )
            })
            .collect()
    }

    /// Return per-column density using a caller-provided fill value.
    #[must_use]
    pub fn column_density_with_fill_value(&self, fill_value: &Scalar) -> BTreeMap<String, f64> {
        self.df
            .column_order
            .iter()
            .map(|name| {
                let column = &self.df.columns[name];
                let npoints = Self::column_npoints_for(column, fill_value);
                (
                    name.clone(),
                    Self::density_for(npoints, column.values().len()),
                )
            })
            .collect()
    }

    /// Materialize the sparse view as a dense DataFrame.
    ///
    /// Current DataFrame storage is already dense; this returns a clone while
    /// preserving DataFrame metadata such as duplicate-label policy.
    #[must_use]
    pub fn to_dense(&self) -> DataFrame {
        self.df.clone()
    }
}

