#[derive(Debug)]
pub enum DataFrameDictResult {
    // Shared-key nested mapping for `to_dict("dict")` / `("index")`. The inner keys
    // are carried ONCE in `keys` instead of cloned into every n*m cell; each outer
    // entry stores only its bare values, aligned position-for-position with `keys`.
    // For "dict": outer = column name, `keys` = index labels, `values[col][i]` is
    // the value at label `keys[i]`. For "index": outer = index label, `keys` = column
    // names, `values[label][j]` is the value in column `keys[j]`. This skips the 10M
    // per-cell inner-key `String` clones the old `Vec<(String, Scalar)>` form paid.
    Mapping {
        keys: Vec<String>,
        values: BTreeMap<String, Vec<Scalar>>,
    },
    // Lazy shared-key index mapping: `to_dict("index")` can be a terminal
    // construction-only result. Preserve the public mapping accessor exactly,
    // but defer the row-major BTreeMap and per-row Vec<Scalar> allocations until
    // a caller asks for `as_mapping()`.
    IndexMappingLazy {
        keys: Vec<String>,
        labels: Vec<String>,
        columns: Vec<Column>,
        values: OnceLock<BTreeMap<String, Vec<Scalar>>>,
    },
    List(BTreeMap<String, Vec<Scalar>>),
    // Shared-key records: the column names are carried ONCE (`columns`) instead of
    // cloned into every one of the n*m cells; row `i`'s value for column `j` is
    // `rows[i][j]` (aligned with `columns`). This is the `to_dict(orient="records")`
    // result — a list of `{column: value}` rows — in a representation that skips the
    // 10M per-cell column-name `String` heap allocations the old
    // `Vec<Vec<(String, Scalar)>>` paid. (`records` is consumed only inside fp-frame;
    // fp-python's `to_dict` builds its column-oriented dict directly.)
    Records {
        columns: Vec<String>,
        rows: Vec<Vec<Scalar>>,
    },
    Series(BTreeMap<String, Series>),
    Split(DataFrameDictSplit),
    Tight(DataFrameDictTight),
}

impl Clone for DataFrameDictResult {
    fn clone(&self) -> Self {
        match self {
            Self::Mapping { keys, values } => Self::Mapping {
                keys: keys.clone(),
                values: values.clone(),
            },
            Self::IndexMappingLazy {
                keys,
                labels,
                columns,
                values,
            } => {
                let cloned_values = OnceLock::new();
                if let Some(values) = values.get() {
                    let _ = cloned_values.set(values.clone());
                }
                Self::IndexMappingLazy {
                    keys: keys.clone(),
                    labels: labels.clone(),
                    columns: columns.clone(),
                    values: cloned_values,
                }
            }
            Self::List(list) => Self::List(list.clone()),
            Self::Records { columns, rows } => Self::Records {
                columns: columns.clone(),
                rows: rows.clone(),
            },
            Self::Series(series) => Self::Series(series.clone()),
            Self::Split(split) => Self::Split(split.clone()),
            Self::Tight(tight) => Self::Tight(tight.clone()),
        }
    }
}

impl PartialEq for DataFrameDictResult {
    fn eq(&self, other: &Self) -> bool {
        if let (Some((left_keys, left_values)), Some((right_keys, right_values))) =
            (self.as_mapping(), other.as_mapping())
        {
            return left_keys == right_keys && left_values == right_values;
        }

        match (self, other) {
            (Self::List(left), Self::List(right)) => left == right,
            (
                Self::Records {
                    columns: left_columns,
                    rows: left_rows,
                },
                Self::Records {
                    columns: right_columns,
                    rows: right_rows,
                },
            ) => left_columns == right_columns && left_rows == right_rows,
            (Self::Series(left), Self::Series(right)) => left == right,
            (Self::Split(left), Self::Split(right)) => left == right,
            (Self::Tight(left), Self::Tight(right)) => left == right,
            _ => false,
        }
    }
}

/// Per-column cell source for `to_dict("index")` materialization: all-valid
/// typed slices build their `Scalar`s directly (skipping the per-column
/// `values()` Scalar-cache materialization, the dominant serial cost at 1M);
/// everything else reads the materialized Scalar view unchanged.
enum ToDictCellSource<'a> {
    F64(&'a [f64]),
    I64(&'a [i64]),
    Scalars(&'a [Scalar]),
}

impl ToDictCellSource<'_> {
    fn cell(&self, row: usize) -> Scalar {
        match self {
            Self::F64(values) => Scalar::Float64(values[row]),
            Self::I64(values) => Scalar::Int64(values[row]),
            Self::Scalars(values) => values[row].clone(),
        }
    }
}

const TO_DICT_INDEX_MATERIALIZE_PAR_MIN_ROWS: usize = 50_000;
const TO_DICT_INDEX_MATERIALIZE_PAR_MIN_PER_WORKER: usize = 16_384;

impl DataFrameDictResult {
    fn materialize_index_mapping(
        labels: &[String],
        columns: &[Column],
    ) -> BTreeMap<String, Vec<Scalar>> {
        // Typed cell reads: an all-valid Float64/Int64 column emits exactly
        // `Scalar::Float64(v)` / `Scalar::Int64(v)` per valid slot from its
        // `values()` view, so building those Scalars straight from the typed
        // slice is bit-identical while skipping the whole-column Scalar-cache
        // materialization. Nullable / non-numeric columns keep the exact
        // `values()` read (NullKind fidelity preserved by not touching it).
        let col_sources: Vec<ToDictCellSource<'_>> = columns
            .iter()
            .map(|column| {
                if column.validity().all() {
                    if let Some(values) = column.as_f64_slice() {
                        return ToDictCellSource::F64(values);
                    }
                    if let Some(values) = column.as_i64_slice() {
                        return ToDictCellSource::I64(values);
                    }
                }
                ToDictCellSource::Scalars(column.values())
            })
            .collect();
        let n = labels.len();
        // Row-range pair-build + bulk collect: the outer map is keyed by the
        // pre-checked unique labels, so it is determined by its key->value
        // SET and the collect is bit-identical to serial insertion.
        let build_pairs = |lo: usize, hi: usize| -> Vec<(String, Vec<Scalar>)> {
            let mut out = Vec::with_capacity(hi - lo);
            for (offset, label) in labels[lo..hi].iter().enumerate() {
                let row_idx = lo + offset;
                out.push((
                    label.clone(),
                    col_sources
                        .iter()
                        .map(|source| source.cell(row_idx))
                        .collect(),
                ));
            }
            out
        };
        let workers = if n >= TO_DICT_INDEX_MATERIALIZE_PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism()
                .min(16)
                .min((n / TO_DICT_INDEX_MATERIALIZE_PAR_MIN_PER_WORKER).max(1))
                .max(1)
        } else {
            1
        };
        if workers >= 2 {
            let chunk = n.div_ceil(workers);
            let build = &build_pairs;
            let parts: Vec<Vec<(String, Vec<Scalar>)>> = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(workers);
                let mut start = 0;
                while start < n {
                    let end = (start + chunk).min(n);
                    handles.push(scope.spawn(move || build(start, end)));
                    start = end;
                }
                handles
                    .into_iter()
                    .map(|handle| handle.join().expect("to_dict index materialize thread"))
                    .collect()
            });
            parts.into_iter().flatten().collect()
        } else {
            build_pairs(0, n).into_iter().collect()
        }
    }

    /// Returns the shared inner keys and the per-outer bare values of a `dict`/`index`
    /// mapping result (`values[outer][k]` is the value at inner key `keys[k]`).
    #[allow(clippy::type_complexity)]
    pub fn as_mapping(&self) -> Option<(&[String], &BTreeMap<String, Vec<Scalar>>)> {
        match self {
            Self::Mapping { keys, values } => Some((keys, values)),
            Self::IndexMappingLazy {
                keys,
                labels,
                columns,
                values,
            } => Some((
                keys,
                values.get_or_init(|| Self::materialize_index_mapping(labels, columns)),
            )),
            _ => None,
        }
    }

    pub fn as_list(&self) -> Option<&BTreeMap<String, Vec<Scalar>>> {
        match self {
            Self::List(list) => Some(list),
            _ => None,
        }
    }

    /// Returns the shared column names and the row-major values of a `records`
    /// result (`rows[i][j]` is row `i`'s value for `columns[j]`).
    pub fn as_records(&self) -> Option<(&[String], &[Vec<Scalar>])> {
        match self {
            Self::Records { columns, rows } => Some((columns, rows)),
            _ => None,
        }
    }

    pub fn as_series(&self) -> Option<&BTreeMap<String, Series>> {
        match self {
            Self::Series(series) => Some(series),
            _ => None,
        }
    }

    pub fn as_tight(&self) -> Option<&DataFrameDictTight> {
        match self {
            Self::Tight(tight) => Some(tight),
            _ => None,
        }
    }

    pub fn as_split(&self) -> Option<&DataFrameDictSplit> {
        match self {
            Self::Split(split) => Some(split),
            _ => None,
        }
    }
}

// `reset_index` returns either a Series (drop=true) or a DataFrame (drop=false),
// both by value on the common path; boxing the larger DataFrame variant would add
// heap indirection to every frame-returning reset_index for no caller benefit, so
// the size asymmetry is accepted here (br-frankenpandas-scowx).
#[allow(clippy::large_enum_variant)]
#[derive(Debug, Clone, PartialEq)]
pub enum SeriesResetIndexResult {
    Series(Series),
    DataFrame(DataFrame),
}

impl SeriesResetIndexResult {
    pub fn as_series(&self) -> Option<&Series> {
        match self {
            Self::Series(series) => Some(series),
            _ => None,
        }
    }

    pub fn as_dataframe(&self) -> Option<&DataFrame> {
        match self {
            Self::DataFrame(frame) => Some(frame),
            _ => None,
        }
    }

    pub fn into_series(self) -> Option<Series> {
        match self {
            Self::Series(series) => Some(series),
            _ => None,
        }
    }

    pub fn into_dataframe(self) -> Option<DataFrame> {
        match self {
            Self::DataFrame(frame) => Some(frame),
            _ => None,
        }
    }
}

pub trait DataFrameApplyArg {
    type Output;

    fn execute(self, frame: &DataFrame, axis: usize) -> Result<Self::Output, FrameError>;
}

impl DataFrameApplyArg for &str {
    type Output = Series;

    fn execute(self, frame: &DataFrame, axis: usize) -> Result<Self::Output, FrameError> {
        frame.apply_named(self, axis)
    }
}

impl<F> DataFrameApplyArg for F
where
    F: Fn(&[Scalar]) -> Scalar,
{
    type Output = DataFrame;

    fn execute(self, frame: &DataFrame, axis: usize) -> Result<Self::Output, FrameError> {
        frame.apply_fn(self, axis)
    }
}

