    /// `pd.DataFrame(dict_of_series, columns=[...])` — SELECT the named columns
    /// first, then align only those.
    ///
    /// The order matters and is observable in the ROW COUNT. MEASURED, live
    /// pandas 2.2.3, with `a` indexed `[1,2]` and `b` indexed `[2,3]`:
    ///
    /// ```text
    /// pd.DataFrame({'a': a, 'b': b})                index [1, 2, 3]   the union
    /// pd.DataFrame({'a': a, 'b': b}, columns=['b']) index [2, 3]      b's index ALONE
    ///     b -> [30, 40]      int64, no gap invented, so no widening
    /// pd.DataFrame({'a': a, 'b': b}, columns=['a','z'])
    ///                                              index [1, 2]      a's index alone
    ///     a -> [10, 20]      int64
    ///     z -> [nan, nan]    OBJECT, an all-missing column for the absent name
    /// ```
    ///
    /// Building the full union and projecting afterwards gives three rows where
    /// pandas gives two, and null-fills columns that pandas leaves intact. A
    /// name absent from the data contributes NO index labels — it becomes an
    /// all-missing column over whatever the present names span.
    ///
    /// `columns = None` is the plain union, i.e. [`Self::from_series`].
    /// (br-frankenpandas-oxodo, br-frankenpandas-fixture-divergence-triage-9s0c4)
    pub fn from_series_with_columns(
        series_list: Vec<Series>,
        columns: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        let Some(columns) = columns else {
            return Self::from_series(series_list);
        };
        let mut by_name: BTreeMap<String, Series> = BTreeMap::new();
        for series in series_list {
            // A repeated name keeps the LAST series, matching the dict the
            // caller would have written (see op_dataframe_from_series).
            by_name.insert(series.name().to_owned(), series);
        }

        let selected: Vec<Series> = columns
            .iter()
            .filter_map(|name| by_name.get(name).cloned())
            .collect();
        let absent: Vec<&String> = columns
            .iter()
            .filter(|name| !by_name.contains_key(*name))
            .collect();

        // The index spans only the SELECTED columns.
        let aligned = Self::from_series(selected)?;
        let row_count = aligned.index.len();

        let mut cols = BTreeMap::new();
        let mut order = Vec::with_capacity(columns.len());
        for name in columns {
            if let Some(column) = aligned.columns.get(name) {
                cols.insert(name.clone(), column.clone());
            } else if absent.contains(&name) {
                // An absent name is an all-missing column. pandas builds it as
                // OBJECT holding nan (measured above), which is the invented-gap
                // marker, not a supplied None.
                cols.insert(
                    name.clone(),
                    Column::new(DType::Utf8, vec![Scalar::Null(NullKind::NaN); row_count])?,
                );
            }
            order.push(name.clone());
        }
        Self::new_with_column_order(aligned.index.clone(), cols, order)
    }

    /// AG-05: Pre-compute N-way union index across all series first, then
    /// reindex each column exactly once. Eliminates O(N²) iterative
    /// realignment where N = number of series.
    pub fn from_series(series_list: Vec<Series>) -> Result<Self, FrameError> {
        if series_list.is_empty() {
            return Self::new(Index::new(Vec::new()), BTreeMap::new());
        }

        let materialized_series = series_list
            .into_iter()
            .map(|series| {
                if let Some(cat) = series.cat() {
                    cat.to_values()
                } else {
                    Ok(series)
                }
            })
            .collect::<Result<Vec<_>, _>>()?;

        // pandas DataFrame(dict-of-series) keeps the LAST series for a repeated
        // name and does NOT union the dropped series' index — so a duplicate
        // column name collapses to a single column with only the surviving
        // series' index. Dedup by name (keep last value, first-appearance
        // column order) BEFORE computing the union. (br-frankenpandas-vsnuu)
        let materialized_series = {
            let mut name_order: Vec<String> = Vec::new();
            let mut by_name: BTreeMap<String, Series> = BTreeMap::new();
            for series in materialized_series {
                if !by_name.contains_key(&series.name) {
                    name_order.push(series.name.clone());
                }
                by_name.insert(series.name.clone(), series);
            }
            name_order
                .into_iter()
                .map(|name| by_name.remove(&name).expect("name present"))
                .collect::<Vec<_>>()
        };

        // Phase 1: Compute global union index across all series.
        let has_duplicates = materialized_series.iter().any(|s| s.index.has_duplicates());
        let first_index = &materialized_series[0].index;
        let all_identical = materialized_series[1..]
            .iter()
            .all(|s| &s.index == first_index);
        let union_index = if all_identical {
            // pandas keeps the shared order when every series has the same index
            // (even if that index is unsorted).
            first_index.clone()
        } else if has_duplicates {
            let mut union_index = materialized_series[0].index.clone();
            for series in &materialized_series[1..] {
                let plan = align_union(&union_index, &series.index);
                validate_alignment_plan(&plan)?;
                union_index = plan.union_index;
            }
            union_index
        } else {
            // pandas DataFrame(dict-of-series) returns the SORTED union when the
            // series indexes differ (Index.union sorts) — NOT first-appearance.
            // (br-frankenpandas-tvey8) concat(axis=1) keeps first-appearance and
            // uses its own union code, so this does not affect it.
            let mut union_index = first_index.clone();
            for series in &materialized_series[1..] {
                union_index = align_union_sorted_plan(&union_index, &series.index).union_index;
            }
            union_index
        };

        // Phase 2: Reindex each series column exactly once against the final union index.
        let mut columns = BTreeMap::new();
        let mut column_order = Vec::new();
        for series in materialized_series {
            let plan = align_union(&union_index, &series.index);
            // The right_positions map from the union to this series's positions.
            // Since union_index already contains all labels, the union_index in
            // this plan equals our pre-computed union. We use right_positions to
            // locate each series's values within the union.
            let aligned_column = series.column.reindex_by_positions(&plan.right_positions)?;
            // pandas promotes a non-nullable int column to Float64 when alignment
            // introduces missing values (np.int64 cannot hold NaN), e.g. building
            // a frame from series with differing indexes. Mirrors the
            // arithmetic-alignment promotion above. Bool promotes to object in
            // pandas (left as-is here). (br-frankenpandas-33d1h)
            let aligned_column = if plan.right_positions.iter().any(Option::is_none)
                && aligned_column.dtype() == DType::Int64
            {
                aligned_column.astype(DType::Float64)?
            } else {
                aligned_column
            };
            column_order.push(series.name.clone());
            columns.insert(series.name, aligned_column);
        }

        Self::new_with_column_order(union_index, columns, column_order)
    }

    /// Construct a DataFrame from a dict of column vectors.
    ///
    /// Matches `pd.DataFrame({"a": [1, 2], "b": [3, 4]})`.
    /// All vectors must have the same length. Index is auto-generated
    /// as 0..n (RangeIndex-style).
    ///
    /// `column_order` controls observable column label order.
    pub fn from_dict(
        column_order: &[&str],
        data: Vec<(&str, Vec<Scalar>)>,
    ) -> Result<Self, FrameError> {
        if data.is_empty() {
            return Self::new(Index::new(Vec::new()), BTreeMap::new());
        }

        let n = data[0].1.len();
        // Lazy unit-range default index (br-frankenpandas-arr72).
        let index = Index::new_known_unique_int64_unit_range(0, n);

        let mut columns = BTreeMap::new();
        let mut input_order = Vec::new();
        for (name, values) in data {
            if values.len() != n {
                return Err(FrameError::LengthMismatch {
                    index_len: n,
                    column_len: values.len(),
                });
            }
            input_order.push(name.to_owned());
            columns.insert(name.to_owned(), Column::from_values(values)?);
        }

        let output_order = if column_order.is_empty() {
            input_order
        } else {
            let mut explicit = Vec::with_capacity(columns.len());
            let mut seen = BTreeSet::new();
            for &name in column_order {
                if !columns.contains_key(name) {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "column '{name}' not found in data"
                    )));
                }
                if !seen.insert(name.to_owned()) {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "duplicate column selector: '{name}'"
                    )));
                }
                explicit.push(name.to_owned());
            }
            for name in input_order {
                if seen.insert(name.clone()) {
                    explicit.push(name);
                }
            }
            explicit
        };

        Self::new_with_column_order(index, columns, output_order)
    }

    /// Construct a DataFrame from dict-of-columns data under pandas' `columns=`
    /// contract, with an optional explicit index.
    ///
    /// Matches `pd.DataFrame(dict, columns=..., index=...)`. This is NOT
    /// [`from_dict`](Self::from_dict)'s `column_order`, which is an ORDERING
    /// hint over columns that are all expected to exist: that one appends any
    /// dict key the caller did not list, and REJECTS a listed name that is
    /// absent. pandas' `columns=` is a SELECTOR. Measured on live pandas 2.2.3
    /// with `d = {"a": [1, 2], "b": [3, 4]}`:
    ///
    /// ```text
    /// pd.DataFrame(d, columns=["a", "z"])   -> a=[1,2], z=[nan,nan] (object)
    /// pd.DataFrame(d, columns=["b"])        -> ONLY b; 'a' is DROPPED
    /// pd.DataFrame(d, columns=["z", "y"])   -> shape (0, 2): no requested name
    ///                                          exists, so there is no index to
    ///                                          take a length from
    /// pd.DataFrame(d, columns=[])           -> shape (0, 0)
    /// pd.DataFrame(d, columns=[], index=[10, 20])   -> shape (2, 0)
    /// pd.DataFrame(d, columns=["a"], index=[1,2,3]) -> ValueError (length)
    /// pd.DataFrame({"a":[1,2],"b":[3]}, columns=["a"]) -> OK: an unselected
    ///     ragged column is dropped BEFORE the equal-length check, while the
    ///     same dict with no `columns=` raises "All arrays must be of the same
    ///     length"
    /// ```
    ///
    /// br-frankenpandas-oxodo: this contract had no owner in FrankenPandas.
    /// The conformance harness held a private copy of it
    /// (`collect_dict_constructor_payloads`) and got the first line wrong — it
    /// raised "column 'z' not found in data", which pandas does not do — and
    /// the oracle carried the same invented rejection, so all three layers
    /// agreed on an error and `fp_p2d_018` pinned it as truth. A user calling
    /// FrankenPandas could not express the operation the packet certified.
    ///
    /// A repeated name in `columns` is rejected: pandas returns the column
    /// twice, and the column store cannot represent duplicate labels
    /// (br-frankenpandas-ih4t0).
    pub fn from_dict_with_columns(
        data: Vec<(&str, Vec<Scalar>)>,
        columns: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
    ) -> Result<Self, FrameError> {
        let Some(requested) = columns else {
            return match index_labels {
                Some(labels) => Self::from_dict_with_index(data, labels),
                None => Self::from_dict(&[], data),
            };
        };

        let mut supplied: BTreeMap<&str, Vec<Scalar>> = BTreeMap::new();
        for (name, values) in data {
            // A repeated key keeps the LAST value, as the dict literal the
            // caller would have written does.
            supplied.insert(name, values);
        }

        let mut seen: BTreeSet<&str> = BTreeSet::new();
        for name in requested {
            if !seen.insert(name.as_str()) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "duplicate column selector: '{name}'"
                )));
            }
        }

        // The row count comes from the SELECTED columns, not from the dict: a
        // selector naming nothing that exists yields a 0-row frame, not a frame
        // of missing rows.
        let row_count = match &index_labels {
            Some(labels) => labels.len(),
            None => requested
                .iter()
                .find_map(|name| supplied.get(name.as_str()).map(Vec::len))
                .unwrap_or(0),
        };

        let mut cols = BTreeMap::new();
        let mut order = Vec::with_capacity(requested.len());
        for name in requested {
            let column = match supplied.remove(name.as_str()) {
                Some(values) => {
                    if values.len() != row_count {
                        return Err(FrameError::LengthMismatch {
                            index_len: row_count,
                            column_len: values.len(),
                        });
                    }
                    Column::from_values(values)?
                }
                // An absent name is an all-missing column. pandas builds it as
                // OBJECT holding nan — an invented gap, not a supplied None —
                // which is how `from_series_with_columns` spells it too.
                None => Column::new(DType::Utf8, vec![Scalar::Null(NullKind::NaN); row_count])?,
            };
            cols.insert(name.clone(), column);
            order.push(name.clone());
        }

        let index = match index_labels {
            Some(labels) => Index::new(labels),
            None => Index::new_known_unique_int64_unit_range(0, row_count),
        };
        Self::new_with_column_order(index, cols, order)
    }

    /// Construct a DataFrame from a dict with `orient='index'`.
    ///
    /// Matches `pd.DataFrame.from_dict(data, orient='index')`.
    /// Each key becomes a row index label, and each value is a list of
    /// column values. Column names default to 0, 1, 2, ...
    pub fn from_dict_index(data: Vec<(&str, Vec<Scalar>)>) -> Result<Self, FrameError> {
        if data.is_empty() {
            return Self::new(Index::new(Vec::new()), BTreeMap::new());
        }

        let ncols = data[0].1.len();
        for (name, vals) in &data {
            if vals.len() != ncols {
                return Err(FrameError::CompatibilityRejected(format!(
                    "from_dict_index: row '{}' has {} values, expected {}",
                    name,
                    vals.len(),
                    ncols
                )));
            }
        }

        let labels: Vec<IndexLabel> = data.iter().map(|(k, _)| (*k).into()).collect();
        let index = Index::new(labels);

        let mut columns = BTreeMap::new();
        let mut col_order = Vec::new();

        for col_idx in 0..ncols {
            let col_name = col_idx.to_string();
            let vals: Vec<Scalar> = data.iter().map(|(_, row)| row[col_idx].clone()).collect();
            columns.insert(col_name.clone(), Column::from_values(vals)?);
            col_order.push(col_name);
        }

        Self::new_with_column_order(index, columns, col_order)
    }

    /// Construct a DataFrame from a dict with orient='index' and custom column names.
    ///
    /// Like `from_dict_index` but with explicit column names.
    pub fn from_dict_index_columns(
        data: Vec<(&str, Vec<Scalar>)>,
        column_names: &[&str],
    ) -> Result<Self, FrameError> {
        if data.is_empty() {
            return Self::new(Index::new(Vec::new()), BTreeMap::new());
        }

        let ncols = data[0].1.len();
        if column_names.len() != ncols {
            return Err(FrameError::LengthMismatch {
                index_len: ncols,
                column_len: column_names.len(),
            });
        }

        let labels: Vec<IndexLabel> = data.iter().map(|(k, _)| (*k).into()).collect();
        let index = Index::new(labels);

        let mut columns = BTreeMap::new();
        let mut col_order = Vec::new();

        for (col_idx, &col_name) in column_names.iter().enumerate() {
            let vals: Vec<Scalar> = data.iter().map(|(_, row)| row[col_idx].clone()).collect();
            columns.insert(col_name.to_string(), Column::from_values(vals)?);
            col_order.push(col_name.to_string());
        }

        Self::new_with_column_order(index, columns, col_order)
    }

    /// What a row-matrix constructor does with a cell no row supplied.
    ///
    /// The policy is per ENTRY POINT because pandas disagrees between them, even
    /// though both land in `from_matrix_rows`. Measured on 2.2.3:
    ///
    /// ```text
    /// pd.DataFrame([[1,2],[3]])                     -> col1 [2, NaN] float64
    /// from_records(..., columns=['a','b','c'])      -> ValueError: 3 columns
    ///   over 2-wide rows                               passed, passed data had
    ///                                                  2 columns
    /// ```
    ///
    /// So the list-like constructor pads and widens, while `from_records` with
    /// an explicit `columns=` is an error pandas does not even reach a fill for.
    /// FrankenPandas' `from_records` currently pads instead of raising — an
    /// FP-defined contract with no oracle behind it — so its policy stays
    /// `PRESERVE_NULL` until that is decided separately.
    /// (br-frankenpandas-nywa8, br-frankenpandas-oxodo)
    ///
    /// Mint `NullKind::Null` and never widen — the historical behaviour.
    const PRESERVE_NULL: bool = false;
    /// Mint `NullKind::NaN` and widen an all-valid int64 column to float64,
    /// matching pandas' list-like constructor.
    const INVENT_NAN: bool = true;

    fn from_matrix_rows(
        matrix_rows: Vec<Vec<Scalar>>,
        column_order: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
        operation_name: &str,
    ) -> Result<Self, FrameError> {
        Self::from_matrix_rows_with_gap_policy(
            matrix_rows,
            column_order,
            index_labels,
            operation_name,
            Self::PRESERVE_NULL,
        )
    }

    /// `pd.DataFrame([[...], [...]], columns=..., index=...)`.
    ///
    /// The list-like constructor: short rows are padded with NaN and the padded
    /// column widens to float64, matching pandas. Added so the conformance
    /// harness can stop building this frame itself (br-frankenpandas-oxodo).
    pub fn from_list_like(
        matrix_rows: Vec<Vec<Scalar>>,
        column_order: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
    ) -> Result<Self, FrameError> {
        Self::from_matrix_rows_with_gap_policy(
            matrix_rows,
            column_order,
            index_labels,
            "dataframe_constructor_list_like",
            Self::INVENT_NAN,
        )
    }

    fn from_matrix_rows_with_gap_policy(
        matrix_rows: Vec<Vec<Scalar>>,
        column_order: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
        operation_name: &str,
        invent_nan: bool,
    ) -> Result<Self, FrameError> {
        let mut matrix_rows = matrix_rows;
        let mut row_count = matrix_rows.len();
        // pandas lets the INDEX win when there are no rows at all: with no
        // `columns=`, `pd.DataFrame([], index=[0])` is shape (1, 0) — the index
        // is honoured and the frame simply has no columns; `index=[0, 1]` gives
        // (2, 0). Only a NON-empty row set that disagrees with the index is an
        // error ("Length of values (2) does not match length of index (1)").
        // FrankenPandas used to reject the empty case too
        // (br-frankenpandas-fp-stricter-than-pandas-rejections-gtkz1).
        if let Some(labels) = index_labels.as_ref()
            && labels.len() != row_count
            && row_count > 0
        {
            // A list-like DataFrame constructor repeats one supplied row for a
            // longer explicit index. It does not repeat a multi-row input or
            // truncate a one-row input to a shorter index.
            if invent_nan && row_count == 1 && labels.len() > row_count {
                matrix_rows = vec![matrix_rows[0].clone(); labels.len()];
                row_count = labels.len();
            } else {
                return Err(FrameError::CompatibilityRejected(format!(
                    "{operation_name} index length {} does not match row count {row_count}",
                    labels.len()
                )));
            }
        }

        let max_row_width = matrix_rows
            .iter()
            .map(std::vec::Vec::len)
            .max()
            .unwrap_or(0);
        let output_order = if let Some(requested_order) = column_order {
            let mut explicit = Vec::with_capacity(requested_order.len());
            let mut seen = BTreeSet::new();
            for requested in requested_order {
                if !seen.insert(requested.clone()) {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "duplicate column selector: '{requested}'"
                    )));
                }
                explicit.push(requested.clone());
            }
            if max_row_width > explicit.len() {
                return Err(FrameError::CompatibilityRejected(format!(
                    "{operation_name} row width {max_row_width} exceeds columns length {}",
                    explicit.len()
                )));
            }
            explicit
        } else {
            (0..max_row_width).map(|idx| idx.to_string()).collect()
        };

        let index = match index_labels {
            Some(labels) => Index::new(labels),
            None => range_index(row_count)?,
        };

        // Every column is built to the INDEX's length, not to `matrix_rows`'s.
        // They are equal except in the empty-rows case allowed above, where the
        // index is longer and pandas null-fills:
        // `pd.DataFrame([], index=[0], columns=['a'])` is shape (1, 1) holding
        // NaN. Reading rows positionally keeps the two in step.
        // ⚠️ The whole CONSTRUCTION is an FP-only contract when an explicit
        // `columns=` is wider than the data: pandas does not fill anything there,
        // it raises "N columns passed, passed data had M columns" — measured for
        // the list-like constructor as well as from_records. FrankenPandas pads
        // instead, and no oracle can verify that padding, so such a call keeps
        // the historical Null pad throughout rather than being widened into an
        // answer nothing checks. Ragged rows UNDER the data's own width are a
        // different case: pandas pads and widens those, and they are what
        // `INVENT_NAN` is for. (br-frankenpandas-nywa8)
        let columns_exceed_data = column_order
            .is_some_and(|requested| requested.len() > max_row_width && !matrix_rows.is_empty());
        let invent_gaps = invent_nan && !columns_exceed_data;

        let output_row_count = index.len();
        let mut columns = BTreeMap::new();
        for (column_offset, column_name) in output_order.iter().enumerate() {
            // The gap policy is the CALLER's, not this function's — see
            // `PRESERVE_NULL` / `INVENT_NAN`. Under PRESERVE_NULL this is the
            // historical pad, which `from_records` still relies on: its padded
            // frame is an FP-defined contract with no oracle behind it, because
            // pandas raises "3 columns passed, passed data had 2 columns" for
            // that input rather than filling anything.
            let supplied = |row_offset: usize| {
                matrix_rows
                    .get(row_offset)
                    .and_then(|row| row.get(column_offset))
            };
            let invented_a_gap =
                invent_gaps && (0..output_row_count).any(|row| supplied(row).is_none());
            let source_was_all_valid = (0..output_row_count)
                .filter_map(supplied)
                .all(|value| !value.is_missing());
            let gap = if invented_a_gap && source_was_all_valid {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Null(NullKind::Null)
            };
            let values = (0..output_row_count)
                .map(|row_offset| supplied(row_offset).cloned().unwrap_or_else(|| gap.clone()))
                .collect::<Vec<_>>();
            // nywa8 RULE 2, which `column_with_invented_gaps` does not cover: a
            // SUPPLIED missing value survives only if the dtype can store it.
            // Rule 1 (that helper) is about a gap this constructor INVENTED;
            // here the caller handed us the None as data, and numpy int64 still
            // cannot hold it, so pandas widens the column and normalizes the
            // marker. MEASURED, live pandas 2.2.3, on
            // `pd.DataFrame(rows, columns=['a','b'])` reading column b:
            //   [[1, None], [2, 3]]        -> float64 [nan, 3.0]   None -> nan
            //   [[1.0, None], [2.0, 3.0]]  -> float64 [nan, 3.0]
            //   [["x", None], ["y", "z"]]  -> object  [None, 'z']  None PRESERVED
            //   [[True, None], [False, True]] -> object [None, True] PRESERVED
            //   [[1, 4], [2, 3]]           -> int64   [4, 3]       the control:
            //                                 no gap, no widening
            // So the widening is NUMERIC-ONLY: object columns keep the caller's
            // None, which is the same dtype-dependence br-frankenpandas-lufpu
            // relies on. Gated on `invent_gaps` so the PRESERVE_NULL callers
            // (from_records, whose padded frame is an FP-defined contract with
            // no oracle behind it) are untouched.
            let supplied_missing_in_numeric_column = invent_gaps
                && values.iter().any(Scalar::is_missing)
                && values
                    .iter()
                    .any(|value| matches!(value, Scalar::Int64(_) | Scalar::Float64(_)))
                && values.iter().all(|value| {
                    matches!(value, Scalar::Int64(_) | Scalar::Float64(_)) || value.is_missing()
                });
            let column = if supplied_missing_in_numeric_column {
                let widened = values
                    .into_iter()
                    .map(|value| {
                        if value.is_missing() {
                            Scalar::Null(NullKind::NaN)
                        } else {
                            value
                        }
                    })
                    .collect::<Vec<_>>();
                Column::new(DType::Float64, widened)?
            } else {
                column_with_invented_gaps(values, invented_a_gap, source_was_all_valid)?
            };
            columns.insert(column_name.clone(), column);
        }

        Self::new_with_column_order(index, columns, output_order)
    }

    /// Construct a DataFrame from row-oriented list-like records.
    ///
    /// Matches `pd.DataFrame.from_records(data, columns=..., index=...)` for
    /// tuple/list-style records. Short rows are null-filled; explicit columns
    /// may also introduce trailing all-null columns.
    pub fn from_records(
        records: Vec<Vec<Scalar>>,
        column_order: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
    ) -> Result<Self, FrameError> {
        Self::from_matrix_rows(
            records,
            column_order,
            index_labels,
            "dataframe_from_records",
        )
    }

    /// Construct a DataFrame from row-oriented tuples.
    ///
    /// Matches the rectangular tuple/list subset of
    /// `pd.DataFrame.from_records(data, columns=...)`. Each inner Vec is a row;
    /// all rows must have the same length as `columns`.
    /// Construct a DataFrame by BROADCASTING one scalar over an index and a
    /// column set.
    ///
    /// Matches `pd.DataFrame(scalar, index=..., columns=...)`. Measured on
    /// pandas 2.2.3:
    /// ```text
    /// pd.DataFrame(5,    index=[0,1], columns=['a','b']) -> [[5,5],[5,5]] int64
    /// pd.DataFrame(2.5,  index=[0,1], columns=['a'])     -> [[2.5],[2.5]] float64
    /// pd.DataFrame('x',  index=[0,1], columns=['a'])     -> [['x'],['x']] object
    /// pd.DataFrame(True, index=[0],   columns=['a'])     -> [[True]] bool
    /// pd.DataFrame(5,    index=[],    columns=['a'])     -> shape (0,1), int64
    /// pd.DataFrame(5,    index=[1,2], columns=[])        -> shape (2,0)
    /// pd.DataFrame(5,    index=[0,1])                    -> ValueError:
    ///     "DataFrame constructor not properly called!"   <- columns OMITTED
    /// ```
    ///
    /// `columns` is `Option` because pandas draws a real distinction that a bare
    /// slice cannot express: an EXPLICIT empty list is legal and yields shape
    /// (n, 0), while OMITTING columns is an error — a bare scalar carries no
    /// labels to infer. Collapsing the two would make one of those two measured
    /// behaviours unreachable.
    ///
    /// Added by br-frankenpandas-oxodo. The conformance harness had been
    /// building this frame ITSELF for eight `dataframe_constructor_scalar`
    /// fixtures, so the packet was green against an operation FrankenPandas did
    /// not actually expose.
    pub fn from_scalar(
        value: &Scalar,
        index_labels: Vec<IndexLabel>,
        column_order: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        let Some(column_order) = column_order else {
            return Err(FrameError::CompatibilityRejected(
                "dataframe_constructor_scalar: DataFrame constructor not properly called! \
                 columns are required to broadcast a scalar"
                    .to_string(),
            ));
        };

        let mut seen = BTreeSet::new();
        for name in column_order {
            if !seen.insert(name.clone()) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "duplicate column selector: '{name}'"
                )));
            }
        }

        // Broadcasting a MISSING scalar invents every cell, so the gap is NaN
        // rather than whatever null kind was handed in. Measured on pandas
        // 2.2.3: pd.DataFrame(None, index=[1,2], columns=['a','b']) is object
        // dtype whose elements are float `nan`, not None.
        // (br-frankenpandas-nywa8)
        let broadcast = if value.is_missing() {
            Scalar::Null(NullKind::NaN)
        } else {
            value.clone()
        };

        let row_count = index_labels.len();
        let mut columns = BTreeMap::new();
        for name in column_order {
            let values = vec![broadcast.clone(); row_count];
            columns.insert(name.clone(), Column::from_values(values)?);
        }

        Self::new_with_column_order(Index::new(index_labels), columns, column_order.to_vec())
    }

    pub fn from_tuples(records: Vec<Vec<Scalar>>, columns: &[&str]) -> Result<Self, FrameError> {
        if records.is_empty() {
            let cols: BTreeMap<String, Column> = columns
                .iter()
                .map(|&c| Ok((c.to_string(), Column::new(DType::Float64, Vec::new())?)))
                .collect::<Result<_, FrameError>>()?;
            let col_order: Vec<String> = columns.iter().map(|c| c.to_string()).collect();
            return Self::new_with_column_order(Index::new(Vec::new()), cols, col_order);
        }

        let n_rows = records.len();
        let n_cols = columns.len();

        // Validate row lengths
        for (i, row) in records.iter().enumerate() {
            if row.len() != n_cols {
                return Err(FrameError::CompatibilityRejected(format!(
                    "from_records: row {i} has {} values, expected {n_cols}",
                    row.len()
                )));
            }
        }

        let column_order = columns
            .iter()
            .map(|name| (*name).to_owned())
            .collect::<Vec<_>>();
        Self::from_matrix_rows(
            records,
            Some(&column_order),
            Some((0..n_rows as i64).map(IndexLabel::from).collect()),
            "from_tuples",
        )
    }

    /// Construct a DataFrame from a list of row tuples with custom index.
    ///
    /// Matches `pd.DataFrame(data, columns=columns, index=index)` for list-of-lists.
    pub fn from_tuples_with_index(
        records: Vec<Vec<Scalar>>,
        columns: &[&str],
        index_labels: Vec<IndexLabel>,
    ) -> Result<Self, FrameError> {
        if !records.is_empty() && index_labels.len() != records.len() {
            return Err(FrameError::LengthMismatch {
                index_len: index_labels.len(),
                column_len: records.len(),
            });
        }
        let column_order = columns
            .iter()
            .map(|name| (*name).to_owned())
            .collect::<Vec<_>>();
        Self::from_matrix_rows(
            records,
            Some(&column_order),
            Some(index_labels),
            "from_tuples_with_index",
        )
    }

    /// Construct a DataFrame from mixed dict inputs (`Vec<Scalar>` and scalar).
    ///
    /// Scalar values are broadcast to the row count inferred from the first
    /// non-scalar column. If all inputs are scalar, an explicit index is
    /// required and this constructor rejects the operation.
    pub fn from_dict_mixed(
        column_order: &[&str],
        data: Vec<(&str, DataFrameColumnInput)>,
    ) -> Result<Self, FrameError> {
        if data.is_empty() {
            return Self::new(Index::new(Vec::new()), BTreeMap::new());
        }

        let row_count = data
            .iter()
            .find_map(|(_, input)| match input {
                DataFrameColumnInput::Values(values) => Some(values.len()),
                DataFrameColumnInput::Scalar(_) => None,
            })
            .ok_or_else(|| {
                FrameError::CompatibilityRejected(
                    "dataframe_from_dict with all-scalar values requires explicit index".to_owned(),
                )
            })?;

        let expanded = data
            .into_iter()
            .map(|(name, input)| {
                let values = match input {
                    DataFrameColumnInput::Values(values) => {
                        if values.len() != row_count {
                            return Err(FrameError::LengthMismatch {
                                index_len: row_count,
                                column_len: values.len(),
                            });
                        }
                        values
                    }
                    DataFrameColumnInput::Scalar(value) => vec![value; row_count],
                };
                Ok((name, values))
            })
            .collect::<Result<Vec<_>, FrameError>>()?;

        Self::from_dict(column_order, expanded)
    }

    /// Construct a DataFrame from mapping records.
    ///
    /// Matches the mapping-record branch of
    /// `pd.DataFrame.from_records(records, columns=..., index=...)`.
    /// Missing keys are null-filled. If `column_order` is provided, it is used
    /// as the exact output column selector/order and may include labels absent
    /// from the records (materialized as all-null columns).
    pub fn from_record_maps(
        records: Vec<BTreeMap<String, Scalar>>,
        column_order: Option<&[String]>,
        index_labels: Option<Vec<IndexLabel>>,
    ) -> Result<Self, FrameError> {
        let row_count = records.len();

        if let Some(labels) = index_labels.as_ref()
            && labels.len() != row_count
        {
            return Err(FrameError::CompatibilityRejected(format!(
                "dataframe_from_records index length {} does not match records length {}",
                labels.len(),
                row_count
            )));
        }

        let mut discovered_columns = Vec::new();
        let mut discovered_seen = BTreeSet::new();
        for record in &records {
            for key in record.keys() {
                if discovered_seen.insert(key.clone()) {
                    discovered_columns.push(key.clone());
                }
            }
        }

        let output_order = if let Some(requested_order) = column_order {
            let mut explicit = Vec::with_capacity(requested_order.len());
            let mut seen = BTreeSet::new();
            for requested in requested_order {
                if !seen.insert(requested.clone()) {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "duplicate column selector: '{requested}'"
                    )));
                }
                explicit.push(requested.clone());
            }
            explicit
        } else {
            discovered_columns
        };

        let mut columns = BTreeMap::new();
        for name in &output_order {
            // A key absent from a record is a gap the CONSTRUCTOR invents, and
            // pandas fills it with NaN, widening that column to float64.
            // Measured: from_records([{'a':1},{'a':2}], columns=['a','z'])
            // gives a int64 and z all-NaN float64 — only the column with the gap
            // widens. A column whose supplied values already included a missing
            // one is nullable and keeps its dtype with a Null gap.
            // (br-frankenpandas-nywa8)
            let invented_a_gap = records.iter().any(|record| !record.contains_key(name));
            let source_was_all_valid = records
                .iter()
                .filter_map(|record| record.get(name))
                .all(|value| !value.is_missing());
            let gap = if source_was_all_valid {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Null(NullKind::Null)
            };
            let values = records
                .iter()
                .map(|record| record.get(name).cloned().unwrap_or_else(|| gap.clone()))
                .collect::<Vec<_>>();
            columns.insert(
                name.clone(),
                column_with_invented_gaps(values, invented_a_gap, source_was_all_valid)?,
            );
        }

        let index = match index_labels {
            Some(labels) => Index::new(labels),
            // Lazy unit-range default index (br-frankenpandas-arr72).
            None => Index::new_known_unique_int64_unit_range(0, row_count),
        };

        Self::new_with_column_order(index, columns, output_order)
    }

    /// Parse a CSV string into a DataFrame.
    ///
    /// Matches `pd.read_csv(StringIO(text))`. The first line is treated as
    /// column headers. Values are auto-detected as Int64, Float64, Bool, or Utf8.
    pub fn from_csv(text: &str, sep: char) -> Result<Self, FrameError> {
        let options = DataFrameCsvReadOptions {
            sep,
            ..DataFrameCsvReadOptions::default()
        };
        Self::from_csv_with_options(text, &options)
    }

    /// Parse a CSV string into a DataFrame with explicit parsing options.
    ///
    /// Matches the `pd.read_csv(..., header=..., dtype=..., index_col=..., na_values=...)`
    /// shape for currently supported options.
    pub fn from_csv_with_options(
        text: &str,
        options: &DataFrameCsvReadOptions,
    ) -> Result<Self, FrameError> {
        let mut lines = text.lines().map(str::trim).filter(|line| !line.is_empty());

        let mut col_names: Vec<String> = if options.has_header {
            let header = lines
                .next()
                .ok_or_else(|| FrameError::CompatibilityRejected("empty CSV".to_owned()))?;
            header
                .split(options.sep)
                .map(|field| field.trim().to_owned())
                .collect()
        } else {
            let first = lines
                .next()
                .ok_or_else(|| FrameError::CompatibilityRejected("empty CSV".to_owned()))?;
            let width = first.split(options.sep).count();
            (0..width).map(|idx| idx.to_string()).collect()
        };

        for name in options.dtypes.keys() {
            if !col_names.iter().any(|col| col == name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "dtype override for unknown column '{name}'"
                )));
            }
        }

        let mut col_data: Vec<Vec<Scalar>> = vec![Vec::new(); col_names.len()];
        let mut pending_rows: Vec<String> = Vec::new();
        if !options.has_header {
            let first_data_row = text
                .lines()
                .map(str::trim)
                .find(|line| !line.is_empty())
                .ok_or_else(|| FrameError::CompatibilityRejected("empty CSV".to_owned()))?;
            pending_rows.push(first_data_row.to_owned());
        }
        pending_rows.extend(lines.map(ToOwned::to_owned));

        // Per br-frankenpandas-fcf5d: pre-build NA set once instead of
        // O(|na_values|) Vec::iter().any() per cell. CSV parsing is
        // hot-loop territory; this turns N × M × |na| into N × M.
        let na_set: HashSet<&str> = options.na_values.iter().map(String::as_str).collect();

        for line in pending_rows {
            let fields: Vec<&str> = line.split(options.sep).collect();
            for (idx, col) in col_data.iter_mut().enumerate() {
                let raw = fields.get(idx).map(|field| field.trim()).unwrap_or("");
                let is_na = raw.is_empty() || na_set.contains(raw);
                let value = if let Some(dtype) = options.dtypes.get(&col_names[idx]) {
                    if is_na {
                        Scalar::missing_for_dtype(*dtype)
                    } else {
                        match dtype {
                            DType::Null => Scalar::Null(NullKind::Null),
                            DType::Bool | DType::BoolNullable => {
                                if raw.eq_ignore_ascii_case("true") || raw == "1" {
                                    Scalar::Bool(true)
                                } else if raw.eq_ignore_ascii_case("false") || raw == "0" {
                                    Scalar::Bool(false)
                                } else {
                                    return Err(FrameError::CompatibilityRejected(format!(
                                        "cannot parse bool value '{raw}' in column '{}'",
                                        col_names[idx]
                                    )));
                                }
                            }
                            DType::Int64 | DType::Int64Nullable => {
                                raw.parse::<i64>().map(Scalar::Int64).map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse int64 value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?
                            }
                            DType::Float64 | DType::Float64Nullable => {
                                raw.parse::<f64>().map(Scalar::Float64).map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse float64 value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?
                            }
                            DType::Utf8 => Scalar::Utf8(raw.to_owned()),
                            DType::Categorical => {
                                return Err(FrameError::CompatibilityRejected(format!(
                                    "cannot parse categorical value '{raw}' in column '{}'; construct categorical series explicitly",
                                    col_names[idx]
                                )));
                            }
                            DType::Sparse => {
                                return Err(FrameError::CompatibilityRejected(format!(
                                    "cannot parse sparse value '{raw}' in column '{}'; construct sparse series explicitly",
                                    col_names[idx]
                                )));
                            }
                            DType::Timedelta64 => Timedelta::parse(raw)
                                .map(Scalar::Timedelta64)
                                .map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse timedelta value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?,
                            DType::Datetime64 => parse_datetime64_nanos(raw)
                                .map(Scalar::Datetime64)
                                .map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse datetime value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?,
                            DType::Period => {
                                parse_period_ordinal(raw).map(Scalar::Period).map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse period value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?
                            }
                            DType::Interval => parse_interval_value(raw)
                                .map(Scalar::Interval)
                                .map_err(|_| {
                                    FrameError::CompatibilityRejected(format!(
                                        "cannot parse interval value '{raw}' in column '{}'",
                                        col_names[idx]
                                    ))
                                })?,
                        }
                    }
                } else if is_na {
                    Scalar::Null(NullKind::NaN)
                } else if let Ok(v) = raw.parse::<i64>() {
                    Scalar::Int64(v)
                } else if let Ok(v) = raw.parse::<f64>() {
                    Scalar::Float64(v)
                } else if raw.eq_ignore_ascii_case("true") {
                    Scalar::Bool(true)
                } else if raw.eq_ignore_ascii_case("false") {
                    Scalar::Bool(false)
                } else {
                    Scalar::Utf8(raw.to_owned())
                };
                col.push(value);
            }
        }

        // Unify inferred columns only: mixed int/float inferred columns promote to Float64.
        for (idx, col) in col_data.iter_mut().enumerate() {
            if options.dtypes.contains_key(&col_names[idx]) {
                continue;
            }
            let has_float = col.iter().any(|v| matches!(v, Scalar::Float64(_)));
            let has_int = col.iter().any(|v| matches!(v, Scalar::Int64(_)));
            if has_float && has_int {
                for val in col.iter_mut() {
                    if let Scalar::Int64(i) = val {
                        *val = Scalar::Float64(*i as f64);
                    }
                }
            }
        }

        if let Some(index_col) = &options.index_col {
            let idx_pos = col_names
                .iter()
                .position(|name| name == index_col)
                .ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "index column '{index_col}' not found in CSV headers"
                    ))
                })?;
            let index_values = col_data.remove(idx_pos);
            col_names.remove(idx_pos);
            let index_labels = index_values
                .into_iter()
                .map(|value| match value {
                    Scalar::Int64(v) => IndexLabel::Int64(v),
                    Scalar::Utf8(v) => IndexLabel::Utf8(v),
                    Scalar::Float64(v) => IndexLabel::Utf8(v.to_string()),
                    Scalar::Bool(v) => {
                        IndexLabel::Utf8(if v { "True" } else { "False" }.to_string())
                    }
                    // Typed null label (br-frankenpandas-8m6ay): pandas
                    // set_index keeps a real nan index entry for a missing
                    // key value. Kind-preserving bijection.
                    Scalar::Null(kind) => IndexLabel::Null(kind),
                    Scalar::Timedelta64(v) => IndexLabel::Utf8(Timedelta::format(v)),
                    Scalar::Datetime64(v) => IndexLabel::Utf8(format_datetime_ns(v)),
                    Scalar::Period(v) => IndexLabel::Utf8(v.calendar_string()),
                    Scalar::Interval(interval) => IndexLabel::Utf8(format!("{interval}")),
                })
                .collect::<Vec<_>>();

            let data: Vec<(&str, Vec<Scalar>)> = col_names
                .iter()
                .zip(col_data)
                .map(|(name, values)| (name.as_str(), values))
                .collect();
            Self::from_dict_with_index(data, index_labels)
        } else {
            let data: Vec<(&str, Vec<Scalar>)> = col_names
                .iter()
                .zip(col_data)
                .map(|(name, values)| (name.as_str(), values))
                .collect();
            let order: Vec<&str> = col_names.iter().map(String::as_str).collect();
            Self::from_dict(&order, data)
        }
    }

    /// Construct a DataFrame from a dict of column vectors with an explicit index.
    ///
    /// Matches `pd.DataFrame({"a": [1, 2]}, index=["x", "y"])`.
    pub fn from_dict_with_index(
        data: Vec<(&str, Vec<Scalar>)>,
        index_labels: Vec<IndexLabel>,
    ) -> Result<Self, FrameError> {
        let n = index_labels.len();
        let index = Index::new(index_labels);

        let mut columns = BTreeMap::new();
        let mut input_order = Vec::new();
        for (name, values) in data {
            if values.len() != n {
                return Err(FrameError::LengthMismatch {
                    index_len: n,
                    column_len: values.len(),
                });
            }
            input_order.push(name.to_owned());
            columns.insert(name.to_owned(), Column::from_values(values)?);
        }

        Self::new_with_column_order(index, columns, input_order)
    }

    /// Construct a DataFrame from mixed dict inputs with an explicit index.
    ///
    /// Scalar values are broadcast to the explicit index length.
    pub fn from_dict_with_index_mixed(
        data: Vec<(&str, DataFrameColumnInput)>,
        index_labels: Vec<IndexLabel>,
    ) -> Result<Self, FrameError> {
        let row_count = index_labels.len();
        let expanded = data
            .into_iter()
            .map(|(name, input)| {
                let values = match input {
                    DataFrameColumnInput::Values(values) => {
                        if values.len() != row_count {
                            return Err(FrameError::LengthMismatch {
                                index_len: row_count,
                                column_len: values.len(),
                            });
                        }
                        values
                    }
                    DataFrameColumnInput::Scalar(value) => vec![value; row_count],
                };
                Ok((name, values))
            })
            .collect::<Result<Vec<_>, FrameError>>()?;

        Self::from_dict_with_index(expanded, index_labels)
    }

    /// Return a new DataFrame with only the specified columns, in order.
    ///
    /// Matches `df[["a", "c"]]` column selection in pandas.
    pub fn select_columns(&self, names: &[&str]) -> Result<Self, FrameError> {
        // Per br-frankenpandas-76e1fd: build the name->position map once so
        // the per-name lookup is O(1). Was O(|column_order|) iter().position
        // per name → O(|names| × |column_order|) total.
        let position_index: std::collections::HashMap<&str, usize> = self
            .column_order
            .iter()
            .enumerate()
            .map(|(i, name)| (name.as_str(), i))
            .collect();
        let mut columns = BTreeMap::new();
        let mut selected_positions = Vec::with_capacity(names.len());
        for &name in names {
            match self.columns.get(name) {
                Some(col) => {
                    columns.insert(name.to_owned(), col.clone());
                    selected_positions.push(
                        *position_index
                            .get(name)
                            .expect("selected column must exist in observable order"),
                    );
                }
                None => {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "column '{name}' not found"
                    )));
                }
            }
        }
        let column_order: Vec<String> = names.iter().map(|name| (*name).to_owned()).collect();
        let column_multiindex = self
            .column_multiindex
            .as_ref()
            .map(|multiindex| Self::project_column_multiindex(multiindex, &selected_positions))
            .transpose()?;
        // Per br-frankenpandas-wv2mi: select_columns only changes which
        // columns are present; the row axis (and any row_multiindex) is
        // untouched and should pass through. Was being silently dropped
        // via new_with_column_order_and_multiindex which hardcodes
        // row_multiindex to None.
        Self::new_with_axes(
            self.index.clone(),
            self.row_multiindex.clone(),
            columns,
            column_order,
            column_multiindex,
        )
    }

    /// Return the number of rows.
    #[must_use]
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Return true if the DataFrame has zero rows.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.index.is_empty()
    }

    /// Pandas-style `.empty` property: true iff the DataFrame contains
    /// zero rows OR zero columns.
    ///
    /// Matches `pd.DataFrame.empty`. This is a stricter predicate than
    /// `is_empty()` — a frame with rows but no columns is still empty
    /// under pandas' definition because there are no values to
    /// operate on.
    #[must_use]
    pub fn empty(&self) -> bool {
        self.index.is_empty() || self.num_columns() == 0
    }

    /// Return the number of columns.
    #[must_use]
    pub fn num_columns(&self) -> usize {
        #[cfg(feature = "lazy-transpose-view")]
        {
            self.columns.logical_len()
        }
        #[cfg(not(feature = "lazy-transpose-view"))]
        {
            self.columns.len()
        }
    }

    /// Return (nrows, ncols) tuple.
    ///
    /// Matches `pd.DataFrame.shape`.
    #[must_use]
    pub fn shape(&self) -> (usize, usize) {
        (self.len(), self.num_columns())
    }

    /// Whether this frame still carries the feature-gated homogeneous
    /// transpose representation without whole-store materialization.
    #[cfg(feature = "lazy-transpose-view")]
    #[must_use]
    #[doc(hidden)]
    pub fn is_lazy_transpose_storage(&self) -> bool {
        self.columns.is_lazy_transpose() && self.column_order.is_lazy_range()
    }

    /// Return a Series of dtypes, one per column.
    ///
    /// Matches `pd.DataFrame.dtypes`.
    pub fn dtypes(&self) -> Result<Series, FrameError> {
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|n| n.as_str().into())
            .collect();
        let values: Vec<Scalar> = self
            .column_order
            .iter()
            .map(|n| Scalar::Utf8(format!("{:?}", self.columns[n].dtype())))
            .collect();
        Series::from_values("dtypes".to_string(), labels, values)
    }

    /// Return a deep copy of this DataFrame.
    ///
    /// Matches `pd.DataFrame.copy(deep=True)`.
    #[must_use]
    pub fn copy(&self) -> Self {
        self.clone()
    }

    /// Return the DataFrame info axis.
    ///
    /// Matches `pd.DataFrame.keys()`. This is an alias for the column labels.
    #[must_use]
    pub fn keys(&self) -> fp_index::MultiIndexOrIndex {
        self.columns_index()
    }

    #[must_use]
    pub fn index(&self) -> &Index {
        &self.index
    }

    /// Return the logical DataFrame row index.
    ///
    /// When row MultiIndex metadata is present, this returns it instead of the
    /// flat storage fallback in `index()`.
    #[must_use]
    pub fn row_index(&self) -> fp_index::MultiIndexOrIndex {
        match &self.row_multiindex {
            Some(multiindex) => fp_index::MultiIndexOrIndex::Multi(multiindex.clone()),
            None => fp_index::MultiIndexOrIndex::Index(self.index.clone()),
        }
    }

    #[must_use]
    pub fn row_multiindex(&self) -> Option<&fp_index::MultiIndex> {
        self.row_multiindex.as_ref()
    }

    /// The COLUMN axis when it has more than one level, as
    /// `df.groupby(k).agg({'x': ['sum','mean']})` and `resample(...).ohlc()`
    /// both produce. `None` means the flat `column_order` is the whole axis.
    ///
    /// Sibling of [`Self::row_multiindex`]; the field already existed but had no
    /// reader outside this crate, so the conformance harness could not see a
    /// two-level column axis at all. (br-frankenpandas-nv5ct)
    #[must_use]
    pub fn column_multiindex(&self) -> Option<&fp_index::MultiIndex> {
        self.column_multiindex.as_ref()
    }

    /// Borrowed view of the column store.
    ///
    /// Returns [`ColumnStore`], not `&BTreeMap<String, Column>`: the concrete
    /// map type used to be part of this crate's public API, which meant a
    /// duplicate-tolerant store could only be exposed by materializing a map
    /// per call — collapsing exactly the repeated labels the store exists to
    /// carry (`br-frankenpandas-u387a`). The view offers the same reads the
    /// map did (`get`, `contains_key`, `keys`, `values`, `iter`, `len`,
    /// `is_empty`, and `[name]` indexing), with iteration still NAME-SORTED.
    #[must_use]
    pub fn columns(&self) -> &ColumnStore {
        #[cfg(feature = "lazy-transpose-view")]
        {
            self.columns.materialized()
        }
        #[cfg(not(feature = "lazy-transpose-view"))]
        {
            &self.columns
        }
    }

    /// Return the logical DataFrame columns index.
    ///
    /// Matches `pd.DataFrame.columns`, including MultiIndex columns for
    /// operations like `groupby.ohlc()`.
    #[must_use]
    pub fn columns_index(&self) -> fp_index::MultiIndexOrIndex {
        match &self.column_multiindex {
            Some(multiindex) => fp_index::MultiIndexOrIndex::Multi(multiindex.clone()),
            None => {
                fp_index::MultiIndexOrIndex::Index(Index::from_utf8(self.column_order.to_vec()))
            }
        }
    }

    #[must_use]
    pub fn columns_multiindex(&self) -> Option<&fp_index::MultiIndex> {
        self.column_multiindex.as_ref()
    }

    /// Return the flat storage column names in observable DataFrame order.
    ///
    /// For the pandas-visible logical column index, including MultiIndex
    /// metadata, use `columns_index()`.
    #[must_use]
    pub fn column_names(&self) -> Vec<&String> {
        self.column_order.iter().collect()
    }

    #[must_use]
    pub fn column(&self, name: &str) -> Option<&Column> {
        #[cfg(feature = "lazy-transpose-view")]
        {
            self.columns.get_one(name)
        }
        #[cfg(not(feature = "lazy-transpose-view"))]
        {
            self.columns.get(name)
        }
    }

    /// O(1) positional column access, the value counterpart to
    /// [`Self::column_name_at`].
    ///
    /// br-frankenpandas-3ya6b. Reading every column of a frame had no route
    /// that did not go through a label: callers had to ask
    /// `column_name_at(i)` for an OWNED `String` and hand it straight back to
    /// [`Self::column`]. On a transposed frame that label is a formatted
    /// integer, so the round trip per column was
    ///
    /// * `i.to_string()` — one allocation to make the label,
    /// * `name.parse::<i64>()` — to recover the position it came from, and
    /// * `label.to_string() != name` — a SECOND allocation to validate the
    ///   round trip (see `homogeneous_transpose_column_position`),
    ///
    /// to arrive back at the position the caller already had. A transposed
    /// frame has one output column per SOURCE ROW, so this is the one shape in
    /// the corpus where a per-column constant scales with the data: at 1M rows
    /// the old route pays ~2M allocations and ~1M parses before any column is
    /// materialized.
    ///
    /// ⚠️ THIS REMOVES A CONSTANT, NOT THE STRUCTURAL GAP. pandas answers
    /// `df.T.to_numpy()` from its 2D BlockManager and measured FLAT at
    /// 45.2/44.6/44.6us from 10k to 1M rows, while FrankenPandas must still
    /// build one `Column` per output column however it is addressed
    /// (br-frankenpandas-l4vzc). Do not expect this to change the SIGN of that
    /// comparison; if a measurement ever shows it doing so, l4vzc's structural
    /// account is wrong and that is the interesting result.
    #[must_use]
    pub fn column_at(&self, position: usize) -> Option<&Column> {
        #[cfg(feature = "lazy-transpose-view")]
        {
            // The fast path answers only for a not-yet-materialized
            // `HomogeneousTranspose`. Every other storage — `Eager`, an
            // already-materialized transpose, `Float64Block` — is ordered by
            // `column_order`, which the column store cannot see, so it MUST
            // fall back to the label route. Returning the fast path's `None`
            // directly would report real columns as absent.
            if let Some(column) = self.columns.get_one_at(position) {
                return Some(column);
            }
            let name = self.column_order.name_at(position)?;
            self.columns.get_one(name.as_str())
        }
        #[cfg(not(feature = "lazy-transpose-view"))]
        {
            let name = self.column_order.get(position)?;
            self.columns.get(name)
        }
    }

    /// O(1) positional column-name access, matching `df.columns[i]` in
    /// pandas. Unlike `column_names()`, a lazily labeled column axis (a
    /// transposed frame's `Int64UnitRange` order) formats just the requested
    /// label instead of materializing every label `String`.
    #[must_use]
    pub fn column_name_at(&self, position: usize) -> Option<String> {
        #[cfg(feature = "lazy-transpose-view")]
        {
            self.column_order.name_at(position)
        }
        #[cfg(not(feature = "lazy-transpose-view"))]
        {
            self.column_order.get(position).cloned()
        }
    }

    /// Filter rows where `mask` is `True`.
    ///
    /// Matches `df[bool_series]` boolean indexing in pandas.
    /// The mask must be a Bool-typed Series. Indexes are aligned; missing
    /// mask values are treated as `False`.
    pub fn filter_rows(&self, mask: &Series) -> Result<Self, FrameError> {
        // Fast path: when indexes are identical AND no duplicates, skip alignment.
        // This is the common case for df[df['col'] > x].
        // Per br-frankenpandas-axw58 perf optimization.
        // Per br-frankenpandas-rg8ys.2.8: must NOT use fast path with duplicate
        // indexes - the duplicate-handling path preserves all matching rows.
        if self.index.identical(mask.index()) && !self.index.has_duplicates() {
            if let Some(mask_bits) = mask.column().as_bool_slice() {
                return self.loc_bool_with_affine_witness(
                    mask_bits,
                    mask.column().bool_affine_selection_witness(),
                );
            }
            if let Some(offending) = mask
                .column()
                .values()
                .iter()
                .find(|v| !matches!(v, Scalar::Bool(_) | Scalar::Null(_)))
            {
                return Err(FrameError::CompatibilityRejected(format!(
                    "boolean mask required for filter_rows; found dtype {:?}",
                    offending.dtype()
                )));
            }
            // Collect positions where mask is True (pre-allocate for ~50% selectivity)
            let mut keep_positions = Vec::with_capacity(self.len() / 2);
            for (i, v) in mask.column().values().iter().enumerate() {
                if matches!(v, Scalar::Bool(true)) {
                    keep_positions.push(i);
                }
            }
            // Use unchecked take - positions are valid indices into self
            return self.take_rows_by_positions_unchecked(&keep_positions);
        }

        // Align mask to DataFrame index (pandas behavior: extra mask labels are ignored).
        if self.index.has_duplicates() || mask.index().has_duplicates() {
            let data_first = self.index.position_map_first();
            let mask_first = mask.index().position_map_first();

            let mut new_labels = Vec::new();
            let mut kept_positions = Vec::new();

            for label in self.index.labels() {
                let Some(&mask_pos) = mask_first.get(label) else {
                    continue;
                };
                if matches!(mask.column().values()[mask_pos], Scalar::Bool(true)) {
                    let data_pos = data_first.get(label).copied().unwrap_or(mask_pos);
                    new_labels.push(label.clone());
                    kept_positions.push(data_pos);
                }
            }

            let mut new_columns = BTreeMap::new();
            for name in &self.column_order {
                let col = self
                    .columns
                    .get(name)
                    .expect("column name listed in order must exist");
                // perf (br-frankenpandas-j4qjl): zero-copy typed per-column gather
                // instead of a per-element Scalar clone + Column::new rebuild.
                new_columns.insert(name.clone(), col.take_positions(&kept_positions));
            }

            // Per br-frankenpandas-z5qu1: pandas preserves the index name
            // through dropna / boolean-indexing.
            return Self::new_with_column_order(
                Index::new(new_labels).rename_index(self.index.name()),
                new_columns,
                self.column_order.clone(),
            );
        }

        let plan = align(&self.index, mask.index(), AlignMode::Left);
        validate_alignment_plan(&plan)?;

        let aligned_mask = mask.column().reindex_by_positions(&plan.right_positions)?;
        if let Some(offending) = aligned_mask
            .values()
            .iter()
            .find(|value| !matches!(value, Scalar::Bool(_) | Scalar::Null(_)))
        {
            return Err(FrameError::CompatibilityRejected(format!(
                "boolean mask required for filter_rows; found dtype {:?}",
                offending.dtype()
            )));
        }

        // Determine which rows to keep.
        let keep: Vec<bool> = aligned_mask
            .values()
            .iter()
            .map(|v| matches!(v, Scalar::Bool(true)))
            .collect();

        let mut new_labels = Vec::new();
        for (i, &k) in keep.iter().enumerate() {
            if k {
                new_labels.push(plan.union_index.labels()[i].clone());
            }
        }

        let mut new_columns = BTreeMap::new();
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            let aligned = col.reindex_by_positions(&plan.left_positions)?;
            let filtered_values: Vec<Scalar> = aligned
                .values()
                .iter()
                .zip(&keep)
                .filter_map(|(v, &k)| if k { Some(v.clone()) } else { None })
                .collect();
            new_columns.insert(name.clone(), Column::new(col.dtype(), filtered_values)?);
        }

        // Per br-frankenpandas-z5qu1: pandas preserves the index name
        // through dropna / boolean-indexing.
        Self::new_with_column_order(
            Index::new(new_labels).rename_index(self.index.name()),
            new_columns,
            self.column_order.clone(),
        )
    }

    /// Return a DataFrame of booleans indicating missing values.
    ///
    /// Matches `df.isna()`.
    pub fn isna(&self) -> Result<Self, FrameError> {
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            let column = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), column_na_mask(column, true));
        }

        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Return a DataFrame of booleans indicating non-missing values.
    ///
    /// Matches `df.notna()`.
    pub fn notna(&self) -> Result<Self, FrameError> {
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            let column = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), column_na_mask(column, false));
        }

        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Alias for `isna`.
    ///
    /// Matches `df.isnull()`.
    pub fn isnull(&self) -> Result<Self, FrameError> {
        self.isna()
    }

    /// Alias for `notna`.
    ///
    /// Matches `df.notnull()`.
    pub fn notnull(&self) -> Result<Self, FrameError> {
        self.notna()
    }

    /// Return non-missing counts for each column.
    ///
    /// Matches `df.count()` default behavior (`axis=0`, `skipna=True`).
    pub fn count(&self) -> Result<Series, FrameError> {
        let labels = self
            .column_order
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect::<Vec<_>>();
        let values = self
            .column_order
            .iter()
            .map(|name| {
                let column = self
                    .columns
                    .get(name)
                    .expect("column name listed in order must exist");
                let count = i64::try_from(column.validity().count_valid()).unwrap_or(i64::MAX);
                Scalar::Int64(count)
            })
            .collect::<Vec<_>>();
        Series::from_values("count", labels, values)
    }

    /// Count of missing (NaN/null) values per column.
    ///
    /// Matches `df.isna().sum()`. Returns a Series indexed by column name.
    pub fn count_na(&self) -> Result<Series, FrameError> {
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        let values: Vec<Scalar> = self
            .column_order
            .iter()
            .map(|name| {
                let col = &self.columns[name];
                let na_count = col.values().iter().filter(|v| v.is_missing()).count();
                Scalar::Int64(na_count as i64)
            })
            .collect();
        Series::from_values("count_na", labels, values)
    }

    /// Fill missing values in each column with `fill_value`.
    ///
    /// Matches `df.fillna(value)` for scalar `value`.
    pub fn fillna(&self, fill_value: &Scalar) -> Result<Self, FrameError> {
        // Column-parallel (br-frankenpandas-applyall-par): each column's fill is
        // independent, so spread the columns across par_map_columns scope
        // workers. Bit-identical — same Column::fillna per column, reassembled in
        // column_order.
        let filled = self.par_map_columns(&self.column_order, |name| {
            Ok(self
                .columns
                .get(name)
                .expect("column name listed in order must exist")
                .fillna(fill_value)?)
        })?;
        let mut columns = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(filled) {
            columns.insert(name.clone(), column);
        }

        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Fill missing values with `fill_value`, filling at most `limit`
    /// consecutive NaN positions per column.
    ///
    /// Matches `df.fillna(value, limit=N)`.
    pub fn fillna_limit(&self, fill_value: &Scalar, limit: usize) -> Result<Self, FrameError> {
        self.apply_all_columns(|s| s.fillna_limit(fill_value, limit))
    }

    /// Fill missing values with per-column values.
    ///
    /// Matches `df.fillna({'col1': val1, 'col2': val2})`.
    /// Columns not listed in `fill_map` are left unchanged.
    pub fn fillna_dict(&self, fill_map: &BTreeMap<String, Scalar>) -> Result<Self, FrameError> {
        for name in fill_map.keys() {
            if !self.columns.contains_key(name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "column '{name}' not found"
                )));
            }
        }
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            if let Some(fill_val) = fill_map.get(name) {
                columns.insert(name.clone(), col.fillna(fill_val)?);
            } else {
                columns.insert(name.clone(), col.clone());
            }
        }
        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Drop rows containing missing values in any selected column.
    ///
    /// Matches default `df.dropna()` row-wise behavior (`axis=0`, `how='any'`).
    pub fn dropna(&self) -> Result<Self, FrameError> {
        self.dropna_with_options(DropNaHow::Any, None)
    }

    /// Drop rows by configurable missing-value policy.
    ///
    /// Matches `df.dropna(how=..., subset=...)` for row-wise mode (`axis=0`).
    pub fn dropna_with_options(
        &self,
        how: DropNaHow,
        subset: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        if self.is_empty() {
            return Ok(self.clone());
        }

        let selected_columns = self.resolve_column_selector(subset)?;
        if selected_columns.is_empty() {
            return Ok(self.clone());
        }

        let row_count = self.len();
        let mut keep_positions = Vec::with_capacity(row_count);
        // Typed Float64 fast path (br-frankenpandas-dropf): when every selected column is
        // Float64, gather (data, validity) once per column and test each row typed —
        // `!validity.get(row) || data[row].is_nan()` is EXACTLY `Scalar::is_missing()` for a
        // Float64 cell (Null/cleared-bit OR NaN), so the keep set is bit-identical — avoiding
        // the per-cell `values()` Vec<Scalar> materialization (the 11× cost vs pandas).
        let typed_f64 = selected_columns
            .iter()
            .map(|name| {
                let column = self.columns.get(name).expect("selected column must exist");
                if column.dtype() == DType::Float64 {
                    column
                        .as_f64_slice_with_validity()
                        .map(|(data, validity)| (data, validity, column.as_f64_slice().is_some()))
                } else {
                    None
                }
            })
            .collect::<Option<Vec<_>>>();
        let run_gather_ready = typed_f64.is_some()
            && self.column_order.iter().all(|name| {
                self.columns
                    .get(name)
                    .expect("column name listed in order must exist")
                    .supports_fast_position_run_gather()
            });
        if let Some(cols) = typed_f64 {
            let ncols = cols.len();
            let missing_columns = cols
                .iter()
                .filter_map(|&(data, validity, missing_free)| {
                    if missing_free {
                        None
                    } else {
                        Some((data, validity))
                    }
                })
                .collect::<Vec<_>>();
            match how {
                DropNaHow::Any if missing_columns.is_empty() => return Ok(self.clone()),
                DropNaHow::All if missing_columns.len() < ncols => return Ok(self.clone()),
                _ => {}
            }
            let mut runs = Vec::new();
            let mut run_start = None;
            let mut run_len = 0usize;
            let mut keep_count = 0usize;
            for row_position in 0..row_count {
                let mut missing_count = 0_usize;
                for (data, validity) in &missing_columns {
                    if !validity.get(row_position) || data[row_position].is_nan() {
                        missing_count += 1;
                    }
                }
                let row_keep = match how {
                    DropNaHow::Any => missing_count == 0,
                    DropNaHow::All => missing_count < ncols,
                };
                if row_keep {
                    if !run_gather_ready {
                        keep_positions.push(row_position);
                    }
                    keep_count += 1;
                    if run_start.is_none() {
                        run_start = Some(row_position);
                    }
                    run_len += 1;
                } else if let Some(start) = run_start.take() {
                    runs.push((start, run_len));
                    run_len = 0;
                }
            }
            if let Some(start) = run_start {
                runs.push((start, run_len));
            }
            if run_gather_ready {
                if keep_count == row_count {
                    return Ok(self.clone());
                }
                let all_valid_f64_columns =
                    matches!(how, DropNaHow::Any).then_some(selected_columns.as_slice());
                return self.take_rows_by_position_runs_unchecked(
                    &runs,
                    keep_count,
                    all_valid_f64_columns,
                );
            }
        } else {
            for row_position in 0..row_count {
                let mut missing_count = 0_usize;
                for name in &selected_columns {
                    let column = self.columns.get(name).expect("selected column must exist");
                    if column.values()[row_position].is_missing() {
                        missing_count += 1;
                    }
                }
                let row_keep = match how {
                    DropNaHow::Any => missing_count == 0,
                    DropNaHow::All => missing_count < selected_columns.len(),
                };
                if row_keep {
                    keep_positions.push(row_position);
                }
            }
        }

        if keep_positions.len() == row_count {
            return Ok(self.clone());
        }

        self.take_rows_by_positions_unchecked(&keep_positions)
    }

    /// Drop rows by minimum non-missing value count.
    ///
    /// Matches `df.dropna(thresh=..., subset=...)` for row-wise mode (`axis=0`).
    pub fn dropna_with_threshold(
        &self,
        thresh: usize,
        subset: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        if self.is_empty() || thresh == 0 {
            return Ok(self.clone());
        }

        let selected_columns = self.resolve_column_selector(subset)?;
        if selected_columns.is_empty() {
            return Ok(self.clone());
        }

        let row_count = self.len();
        let mut keep_positions = Vec::with_capacity(row_count);
        for row_position in 0..row_count {
            let mut non_missing_count = 0_usize;
            for name in &selected_columns {
                let column = self.columns.get(name).expect("selected column must exist");
                if !column.values()[row_position].is_missing() {
                    non_missing_count += 1;
                }
            }
            if non_missing_count >= thresh {
                keep_positions.push(row_position);
            }
        }

        if keep_positions.len() == row_count {
            return Ok(self.clone());
        }

        self.take_rows_by_positions_unchecked(&keep_positions)
    }

    /// Drop columns containing missing values in any row.
    ///
    /// Matches default `df.dropna(axis=1)` behavior (`how='any'`).
    pub fn dropna_columns(&self) -> Result<Self, FrameError> {
        self.dropna_columns_with_options(DropNaHow::Any, None)
    }

    /// Drop columns by configurable missing-value policy.
    ///
    /// Matches `df.dropna(axis=1, how=..., subset=...)` where `subset` selects
    /// row labels to consider during missing-value checks.
    pub fn dropna_columns_with_options(
        &self,
        how: DropNaHow,
        subset: Option<&[IndexLabel]>,
    ) -> Result<Self, FrameError> {
        if self.column_order.is_empty() {
            return Ok(self.clone());
        }

        let selected_rows = self.resolve_row_label_selector(subset)?;
        if selected_rows.is_empty() {
            return Ok(self.clone());
        }

        let mut keep_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let column = self.columns.get(name).expect("selected column must exist");
            let mut missing_count = 0_usize;
            for &row_position in &selected_rows {
                if column.values()[row_position].is_missing() {
                    missing_count += 1;
                }
            }

            let column_keep = match how {
                DropNaHow::Any => missing_count == 0,
                DropNaHow::All => missing_count < selected_rows.len(),
            };
            if column_keep {
                keep_columns.push(name.clone());
            }
        }

        let mut columns = BTreeMap::new();
        for name in &keep_columns {
            let column = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), column.clone());
        }

        Self::new_with_column_order(self.index.clone(), columns, keep_columns)
    }

    /// Drop columns by minimum non-missing value count.
    ///
    /// Matches `df.dropna(axis=1, thresh=..., subset=...)` where `subset`
    /// selects row labels to consider.
    pub fn dropna_columns_with_threshold(
        &self,
        thresh: usize,
        subset: Option<&[IndexLabel]>,
    ) -> Result<Self, FrameError> {
        if self.column_order.is_empty() || thresh == 0 {
            return Ok(self.clone());
        }

        let selected_rows = self.resolve_row_label_selector(subset)?;
        if selected_rows.is_empty() {
            return Ok(self.clone());
        }

        let mut keep_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let column = self.columns.get(name).expect("selected column must exist");
            let mut non_missing_count = 0_usize;
            for &row_position in &selected_rows {
                if !column.values()[row_position].is_missing() {
                    non_missing_count += 1;
                }
            }
            if non_missing_count >= thresh {
                keep_columns.push(name.clone());
            }
        }

        let mut columns = BTreeMap::new();
        for name in &keep_columns {
            let column = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), column.clone());
        }

        Self::new_with_column_order(self.index.clone(), columns, keep_columns)
    }

    /// Return a boolean Series indicating duplicated rows.
    ///
    /// Matches `df.duplicated(subset=..., keep=...)`.
    ///
    /// Uses hash-based O(n) deduplication instead of O(n²) pairwise comparison.
    /// Per br-frankenpandas-cclly performance optimization.
    pub fn duplicated(
        &self,
        subset: Option<&[String]>,
        keep: DuplicateKeep,
    ) -> Result<Series, FrameError> {
        let mask = self.duplicated_mask(subset, keep)?;
        // Per br-frankenpandas-fgvu8: pandas df.duplicated() returns an unnamed
        // bool Series whose index matches self.index (name and all). Typed bool
        // output (br-frankenpandas-dupe-fx): the mask is all-valid.
        Series::new("", self.index.clone(), Column::from_bool_values(mask))
    }

    /// Core of [`duplicated`] / [`drop_duplicates`]: the per-row duplicate mask
    /// as a raw `Vec<bool>` (no `Series`/`Scalar` wrap). Callers that only need
    /// the mask (e.g. `drop_duplicates`) avoid the `.values()` Scalar
    /// materialization of the public `duplicated` wrapper.
    fn duplicated_mask(
        &self,
        subset: Option<&[String]>,
        keep: DuplicateKeep,
    ) -> Result<Vec<bool>, FrameError> {
        use std::collections::hash_map::Entry;

        let selected_columns = self.resolve_column_selector(subset)?;
        let selected_column_refs = selected_columns
            .iter()
            .map(|col_name| self.columns.get(col_name).expect("column must exist"))
            .collect::<Vec<_>>();
        let row_count = self.len();
        let mut duplicated = vec![false; row_count];

        // Single typed Float64 column fast path (BlackThrush): the general digest
        // + RowBucket framework keys rows by a splitmix digest of `to_bits` and
        // re-verifies equality on collisions — overkill when exactly one Float64
        // column is selected, where the raw bit pattern IS the dedup key. Probe an
        // `FxHashMap<u64, ()>` keyed on raw `to_bits` directly (a row is "present"
        // iff valid and not NaN — matching the digest path's present arm; all
        // missing/NaN rows collapse to one equivalence class, exactly the digest's
        // `mix(0)` bucket). Bit-identical to the framework path for every input
        // without a splitmix digest collision (the digest is an injective mix of
        // `to_bits` here, so collisions never occur on realistic data — and the
        // framework's fuzzy `float_semantic_eq` only ever fires on such a
        // collision, which the digest construction precludes). ~3x faster: one
        // hash probe per row, no digest, no parallel-partition spin-up, no bucket
        // re-verification.
        if selected_column_refs.len() == 1
            && let Some((data, validity)) = selected_column_refs[0].as_f64_slice_with_validity()
        {
            return Ok(Self::duplicated_single_f64(data, validity, keep));
        }

        // Single all-valid Int64 column fast path (BlackThrush): same as the
        // Float64 path but the i64 value IS the dedup key directly (`as_i64_slice`
        // is all-valid, so there is no missing class). The general digest path
        // keyed Int64 by `mix(2)+mix(value)` and re-verified collisions through
        // RowBucket — measured ~5-7x slower than pandas' khash factorize. Bit-
        // identical: exact-i64 dedup matches the digest path for any input without
        // a splitmix collision (which never occurs on realistic data).
        if selected_column_refs.len() == 1
            && let Some(data) = selected_column_refs[0].as_i64_slice()
        {
            return Ok(Self::duplicated_single_i64(data, keep));
        }

        // Single all-valid contiguous Utf8 column fast path (BlackThrush): key
        // each row by its raw `&[u8]` span directly (`as_utf8_contiguous` is
        // all-valid ⇒ no missing class), mirroring the `value_counts` span tally.
        // The general digest path FNV-hashed every byte then re-verified through
        // RowBucket. Bit-identical: exact byte-span equality matches the digest
        // path's `Scalar::Utf8` semantic_eq for any input without a digest
        // collision (which never occurs on realistic data).
        if selected_column_refs.len() == 1
            && let Some((bytes, offsets)) = selected_column_refs[0].as_utf8_contiguous()
        {
            return Ok(Self::duplicated_single_utf8(bytes, offsets, keep));
        }

        // Typed Float64 fast path (br-frankenpandas-g29hf): when EVERY selected
        // column is a contiguous Float64 backing, read raw f64 + validity once
        // and digest / compare rows directly, skipping the per-row Scalar
        // materialization the `col.values()[row]` path forces. Bit-identical: a
        // slot is "present" iff its validity bit is set AND its datum is not NaN
        // (a valid-bit-NaN materializes as Float64(NaN), which Scalar::is_missing
        // treats as missing) — matching the Scalar digest's missing/Float64 arms
        // and Scalar::semantic_eq (both-missing equal, present-vs-missing not,
        // both-present via the identical fuzzy `float_semantic_eq`). The digest
        // bytes are byte-for-byte the same (mix(0) for missing, mix(3)+mix(bits)
        // for present), so bucket assignment — and therefore the hash-collision
        // outcome — is unchanged.
        // Typed raw-backing per selected column (br-frankenpandas: extend the f64
        // path to Int64/contiguous-Utf8). When EVERY selected column has one of
        // these backings, the digest + equality below read the raw slice directly,
        // skipping the per-cell `col.values()[row]` Scalar materialization (for
        // multi-Utf8/mixed subsets that meant a String alloc per cell). Bit-
        // identical: the per-type digest mixes match `scalar_digest` exactly (Int64
        // mix(2)+value; Utf8 mix(4)+len+bytes_digest; Float64 mix(3)+bits with the
        // same present-iff-valid-and-not-NaN rule) and equality matches
        // `Scalar::semantic_eq` (Int64/Utf8 exact, Float64 fuzzy). `as_i64_slice` /
        // `as_utf8_contiguous` are all-valid, so there is no missing class to skip.
        enum TypedDedupCol<'a> {
            F64(&'a [f64], &'a fp_columnar::ValidityMask),
            I64(&'a [i64]),
            Utf8(&'a [u8], &'a [usize]),
        }
        let typed_cols: Option<Vec<TypedDedupCol<'_>>> = selected_column_refs
            .iter()
            .map(|col| {
                if let Some((data, validity)) = col.as_f64_slice_with_validity() {
                    Some(TypedDedupCol::F64(data, validity))
                } else if let Some(data) = col.as_i64_slice() {
                    Some(TypedDedupCol::I64(data))
                } else if let Some((bytes, offsets)) = col.as_utf8_contiguous() {
                    Some(TypedDedupCol::Utf8(bytes, offsets))
                } else {
                    None
                }
            })
            .collect();

        enum RowBucket {
            Single(usize),
            Collision(Vec<usize>),
        }

        fn mix_digest(state: &mut u64, value: u64) {
            let mut mixed = value.wrapping_add(0x9e37_79b9_7f4a_7c15);
            mixed = (mixed ^ (mixed >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
            mixed = (mixed ^ (mixed >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
            mixed ^= mixed >> 31;
            *state ^= mixed;
            *state = state.rotate_left(27).wrapping_mul(0x3c79_ac49_2ba7_b653);
        }

        fn bytes_digest(bytes: &[u8]) -> u64 {
            let mut state = 0xcbf2_9ce4_8422_2325;
            for &byte in bytes {
                state ^= u64::from(byte);
                state = state.wrapping_mul(0x0000_0100_0000_01b3);
            }
            state
        }

        fn scalar_digest(state: &mut u64, value: &Scalar) {
            if value.is_missing() {
                mix_digest(state, 0);
                return;
            }

            match value {
                Scalar::Null(_) => mix_digest(state, 0),
                Scalar::Bool(value) => {
                    mix_digest(state, 1);
                    mix_digest(state, u64::from(*value));
                }
                Scalar::Int64(value) => {
                    mix_digest(state, 2);
                    mix_digest(state, *value as u64);
                }
                Scalar::Float64(value) => {
                    mix_digest(state, 3);
                    mix_digest(state, value.to_bits());
                }
                Scalar::Utf8(value) => {
                    mix_digest(state, 4);
                    mix_digest(state, value.len() as u64);
                    mix_digest(state, bytes_digest(value.as_bytes()));
                }
                Scalar::Datetime64(value) => {
                    mix_digest(state, 5);
                    mix_digest(state, *value as u64);
                }
                Scalar::Timedelta64(value) => {
                    mix_digest(state, 6);
                    mix_digest(state, *value as u64);
                }
                Scalar::Period(value) => {
                    mix_digest(state, 7);
                    mix_digest(state, value.ordinal as u64);
                }
                Scalar::Interval(value) => {
                    mix_digest(state, 8);
                    mix_digest(state, value.left.to_bits());
                    mix_digest(state, value.right.to_bits());
                }
            }
        }

        let row_digest = |row: usize| {
            let mut state = 0x517c_c1b7_2722_0a95;
            mix_digest(&mut state, selected_column_refs.len() as u64);
            if let Some(typed) = &typed_cols {
                for tc in typed {
                    match tc {
                        TypedDedupCol::F64(data, validity) => {
                            if validity.get(row) && !data[row].is_nan() {
                                mix_digest(&mut state, 3);
                                mix_digest(&mut state, data[row].to_bits());
                            } else {
                                mix_digest(&mut state, 0);
                            }
                        }
                        TypedDedupCol::I64(data) => {
                            mix_digest(&mut state, 2);
                            mix_digest(&mut state, data[row] as u64);
                        }
                        TypedDedupCol::Utf8(bytes, offsets) => {
                            let span = &bytes[offsets[row]..offsets[row + 1]];
                            mix_digest(&mut state, 4);
                            mix_digest(&mut state, span.len() as u64);
                            mix_digest(&mut state, bytes_digest(span));
                        }
                    }
                }
            } else {
                for col in &selected_column_refs {
                    let value = &col.values()[row];
                    scalar_digest(&mut state, value);
                }
            }
            state
        };

        // Row equality on the selected subset: typed when every column is
        // Float64 (present iff valid-and-not-NaN; both-missing equal; otherwise
        // the identical fuzzy `float_semantic_eq`), else the Scalar method.
        let rows_equal = |left: usize, right: usize| -> bool {
            if let Some(typed) = &typed_cols {
                typed.iter().all(|tc| match tc {
                    TypedDedupCol::F64(data, validity) => {
                        let lpres = validity.get(left) && !data[left].is_nan();
                        let rpres = validity.get(right) && !data[right].is_nan();
                        if lpres != rpres {
                            return false;
                        }
                        if !lpres {
                            return true;
                        }
                        float_semantic_eq(data[left], data[right])
                    }
                    TypedDedupCol::I64(data) => data[left] == data[right],
                    TypedDedupCol::Utf8(bytes, offsets) => {
                        bytes[offsets[left]..offsets[left + 1]]
                            == bytes[offsets[right]..offsets[right + 1]]
                    }
                })
            } else {
                self.rows_equal_on_subset(left, right, &selected_columns)
            }
        };

        // Precompute every row digest, in parallel for large frames
        // (br-frankenpandas-dupe-fx). The digest is 8 strided f64 streams + a
        // per-value splitmix per row, embarrassingly parallel (each row
        // independent). Bit-identical: identical digest values, chunks_mut hands
        // each worker a disjoint output slice so writes never alias.
        const DEDUP_PAR_MIN_ROWS: usize = 8_192;
        let worker_count = if row_count >= DEDUP_PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism().min(row_count)
        } else {
            1
        };
        let digests: Vec<u64> = {
            let mut digests = vec![0_u64; row_count];
            if worker_count >= 2 {
                let chunk = row_count.div_ceil(worker_count);
                std::thread::scope(|scope| {
                    for (w, slot) in digests.chunks_mut(chunk).enumerate() {
                        let row_digest = &row_digest;
                        let base = w * chunk;
                        scope.spawn(move || {
                            for (k, d) in slot.iter_mut().enumerate() {
                                *d = row_digest(base + k);
                            }
                        });
                    }
                });
            } else {
                for (i, d) in digests.iter_mut().enumerate() {
                    *d = row_digest(i);
                }
            }
            digests
        };

        match keep {
            DuplicateKeep::First => {
                // Partitioned parallel dedup: equal rows share a digest, so
                // bucketing by `digest % P` keeps every occurrence of a value in
                // ONE partition. Each partition dedups its rows in ascending
                // index order (first-seen kept, rest marked) into a cache-resident
                // local map — fully independent, so the dominant hash-insert work
                // parallelizes. Bit-identical to the serial map (same first-seen
                // semantics; rows_equal still verifies digest collisions).
                if worker_count >= 2 {
                    let mut parts: Vec<Vec<usize>> =
                        (0..worker_count).map(|_| Vec::new()).collect();
                    for (i, &d) in digests.iter().enumerate() {
                        parts[(d as usize) % worker_count].push(i);
                    }
                    let dup_lists: Vec<Vec<usize>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(parts.len());
                        for part in &parts {
                            let digests = &digests;
                            let rows_equal = &rows_equal;
                            handles.push(scope.spawn(move || {
                                let mut local: FxHashMap<u64, RowBucket> =
                                    FxHashMap::with_capacity_and_hasher(
                                        part.len(),
                                        Default::default(),
                                    );
                                let mut dups = Vec::new();
                                for &i in part {
                                    match local.entry(digests[i]) {
                                        Entry::Vacant(entry) => {
                                            entry.insert(RowBucket::Single(i));
                                        }
                                        Entry::Occupied(mut entry) => match entry.get_mut() {
                                            RowBucket::Single(first_idx) => {
                                                if rows_equal(i, *first_idx) {
                                                    dups.push(i);
                                                } else {
                                                    *entry.get_mut() =
                                                        RowBucket::Collision(vec![*first_idx, i]);
                                                }
                                            }
                                            RowBucket::Collision(indices) => {
                                                if indices
                                                    .iter()
                                                    .any(|&first_idx| rows_equal(i, first_idx))
                                                {
                                                    dups.push(i);
                                                } else {
                                                    indices.push(i);
                                                }
                                            }
                                        },
                                    }
                                }
                                dups
                            }));
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("dedup partition worker panicked"))
                            .collect()
                    });
                    for dups in dup_lists {
                        for i in dups {
                            duplicated[i] = true;
                        }
                    }
                } else {
                    let mut seen: FxHashMap<u64, RowBucket> =
                        FxHashMap::with_capacity_and_hasher(row_count, Default::default());
                    for (i, duplicated_i) in duplicated.iter_mut().enumerate() {
                        match seen.entry(digests[i]) {
                            Entry::Vacant(entry) => {
                                entry.insert(RowBucket::Single(i));
                            }
                            Entry::Occupied(mut entry) => match entry.get_mut() {
                                RowBucket::Single(first_idx) => {
                                    if rows_equal(i, *first_idx) {
                                        *duplicated_i = true;
                                    } else {
                                        *entry.get_mut() =
                                            RowBucket::Collision(vec![*first_idx, i]);
                                    }
                                }
                                RowBucket::Collision(indices) => {
                                    if indices.iter().any(|&first_idx| rows_equal(i, first_idx)) {
                                        *duplicated_i = true;
                                    } else {
                                        indices.push(i);
                                    }
                                }
                            },
                        }
                    }
                }
            }
            DuplicateKeep::Last => {
                let mut seen: FxHashMap<u64, RowBucket> =
                    FxHashMap::with_capacity_and_hasher(row_count, Default::default());
                for (i, duplicated_i) in duplicated.iter_mut().enumerate().rev() {
                    match seen.entry(digests[i]) {
                        Entry::Vacant(entry) => {
                            entry.insert(RowBucket::Single(i));
                        }
                        Entry::Occupied(mut entry) => match entry.get_mut() {
                            RowBucket::Single(last_idx) => {
                                if rows_equal(i, *last_idx) {
                                    *duplicated_i = true;
                                } else {
                                    *entry.get_mut() = RowBucket::Collision(vec![*last_idx, i]);
                                }
                            }
                            RowBucket::Collision(indices) => {
                                if indices.iter().any(|&last_idx| rows_equal(i, last_idx)) {
                                    *duplicated_i = true;
                                } else {
                                    indices.push(i);
                                }
                            }
                        },
                    }
                }
            }
            DuplicateKeep::None => {
                let mut buckets: FxHashMap<u64, RowBucket> =
                    FxHashMap::with_capacity_and_hasher(row_count, Default::default());
                for (i, &digest) in digests.iter().enumerate() {
                    match buckets.entry(digest) {
                        Entry::Vacant(entry) => {
                            entry.insert(RowBucket::Single(i));
                        }
                        Entry::Occupied(mut entry) => match entry.get_mut() {
                            RowBucket::Single(first_idx) => {
                                *entry.get_mut() = RowBucket::Collision(vec![*first_idx, i]);
                            }
                            RowBucket::Collision(indices) => indices.push(i),
                        },
                    }
                }

                for bucket in buckets.values() {
                    if let RowBucket::Collision(indices) = bucket
                        && indices.len() > 1
                    {
                        // Verify actual equality for hash collisions.
                        for &i in indices {
                            for &j in indices {
                                if i != j && rows_equal(i, j) {
                                    duplicated[i] = true;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

        Ok(duplicated)
    }

    /// Single-Float64-column duplicate mask keyed directly on the raw `to_bits`
    /// pattern. A row is "present" iff valid and not NaN; all missing/NaN rows
    /// form one equivalence class (`seen_missing`). Bit-identical to the general
    /// digest path's output for any input without a splitmix digest collision.
    fn duplicated_single_f64(
        data: &[f64],
        validity: &fp_columnar::ValidityMask,
        keep: DuplicateKeep,
    ) -> Vec<bool> {
        let n = data.len();
        let mut duplicated = vec![false; n];
        match keep {
            DuplicateKeep::First | DuplicateKeep::Last => {
                let mut seen: FxHashMap<u64, ()> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                let mut seen_missing = false;
                let mark = |i: usize, seen: &mut FxHashMap<u64, ()>, seen_missing: &mut bool| {
                    if validity.get(i) && !data[i].is_nan() {
                        seen.insert(data[i].to_bits(), ()).is_some()
                    } else {
                        let was = *seen_missing;
                        *seen_missing = true;
                        was
                    }
                };
                if matches!(keep, DuplicateKeep::First) {
                    for (i, dup) in duplicated.iter_mut().enumerate() {
                        *dup = mark(i, &mut seen, &mut seen_missing);
                    }
                } else {
                    for i in (0..n).rev() {
                        duplicated[i] = mark(i, &mut seen, &mut seen_missing);
                    }
                }
            }
            DuplicateKeep::None => {
                // Two passes: count occurrences per key, then mark every row whose
                // key (or the missing class) occurs more than once.
                let mut counts: FxHashMap<u64, u32> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                let mut missing_count: u32 = 0;
                for (i, value) in data.iter().enumerate().take(n) {
                    if validity.get(i) && !value.is_nan() {
                        *counts.entry(value.to_bits()).or_insert(0) += 1;
                    } else {
                        missing_count += 1;
                    }
                }
                for (i, dup) in duplicated.iter_mut().enumerate() {
                    *dup = if validity.get(i) && !data[i].is_nan() {
                        counts.get(&data[i].to_bits()).copied().unwrap_or(0) > 1
                    } else {
                        missing_count > 1
                    };
                }
            }
        }
        duplicated
    }

    /// Single all-valid-Int64-column duplicate mask keyed directly on the i64
    /// value. `as_i64_slice` is all-valid, so every row is present (no missing
    /// class). Bit-identical to the general digest path for any input without a
    /// splitmix digest collision.
    fn duplicated_single_i64(data: &[i64], keep: DuplicateKeep) -> Vec<bool> {
        let n = data.len();
        // First/Last: the custom open-addressing i64 table (Series::oa_dup_flags_i64)
        // beats FxHashMap<i64> on wide/high-cardinality data (the khash floor) — the
        // same lever that flipped Series.duplicated 0.29x->1.73x. df.duplicated on a
        // single Int64 column was only at PARITY with pandas via FxHashMap; this
        // brings it to the ~2.5x Series-path speed. Bit-identical (first/last
        // occurrence unflagged, rest flagged — same per-keep semantics).
        match keep {
            DuplicateKeep::First => return Series::oa_dup_flags_i64(data, false),
            DuplicateKeep::Last => return Series::oa_dup_flags_i64(data, true),
            DuplicateKeep::None => {}
        }
        let mut duplicated = vec![false; n];
        match keep {
            DuplicateKeep::First | DuplicateKeep::Last => unreachable!("handled above"),
            DuplicateKeep::None => {
                let mut counts: FxHashMap<i64, u32> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                for &v in data {
                    *counts.entry(v).or_insert(0) += 1;
                }
                for (i, dup) in duplicated.iter_mut().enumerate() {
                    *dup = counts.get(&data[i]).copied().unwrap_or(0) > 1;
                }
            }
        }
        duplicated
    }

    /// Single all-valid contiguous-Utf8-column duplicate mask keyed directly on
    /// the raw `&[u8]` span (`as_utf8_contiguous` is all-valid ⇒ no missing
    /// class). Bit-identical to the general digest path for any input without a
    /// digest collision.
    fn duplicated_single_utf8(bytes: &[u8], offsets: &[usize], keep: DuplicateKeep) -> Vec<bool> {
        let n = offsets.len().saturating_sub(1);
        let mut duplicated = vec![false; n];
        let span = |i: usize| -> &[u8] { &bytes[offsets[i]..offsets[i + 1]] };
        match keep {
            DuplicateKeep::First => {
                let mut seen: FxHashMap<&[u8], ()> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                for (i, dup) in duplicated.iter_mut().enumerate() {
                    *dup = seen.insert(span(i), ()).is_some();
                }
            }
            DuplicateKeep::Last => {
                let mut seen: FxHashMap<&[u8], ()> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                for i in (0..n).rev() {
                    duplicated[i] = seen.insert(span(i), ()).is_some();
                }
            }
            DuplicateKeep::None => {
                let mut counts: FxHashMap<&[u8], u32> =
                    FxHashMap::with_capacity_and_hasher(n, Default::default());
                for i in 0..n {
                    *counts.entry(span(i)).or_insert(0) += 1;
                }
                for (i, dup) in duplicated.iter_mut().enumerate() {
                    *dup = counts.get(span(i)).copied().unwrap_or(0) > 1;
                }
            }
        }
        duplicated
    }

    /// Drop duplicated rows.
    ///
    /// Matches `df.drop_duplicates(subset=..., keep=..., ignore_index=...)`.
    pub fn drop_duplicates(
        &self,
        subset: Option<&[String]>,
        keep: DuplicateKeep,
        ignore_index: bool,
    ) -> Result<Self, FrameError> {
        if !ignore_index {
            let selected_columns = self.resolve_column_selector(subset)?;
            if !selected_columns.is_empty()
                && self.subset_has_all_valid_unique_column(&selected_columns)
            {
                return Ok(self.clone());
            }
        }

        // Consume the raw `Vec<bool>` mask directly (BlackThrush): the prior path
        // built a `Series`, then `.values()` materialized a `Vec<Scalar::Bool>`
        // only to re-discriminate it here. Iterating the typed mask skips both.
        let duplicated = self.duplicated_mask(subset, keep)?;
        let mut saw_duplicate = false;
        let keep_positions = duplicated
            .iter()
            .enumerate()
            .filter_map(|(position, &is_dup)| {
                if is_dup {
                    saw_duplicate = true;
                    None
                } else {
                    Some(position)
                }
            })
            .collect::<Vec<_>>();

        if !ignore_index && !saw_duplicate {
            return Ok(self.clone());
        }

        let out = self.take_rows_by_positions(&keep_positions)?;
        if ignore_index {
            out.reset_index(true)
        } else {
            Ok(out)
        }
    }

    /// Return the first `n` rows.
    ///
    /// Matches `df.head(n)`. If `n` is negative, this returns all rows except
    /// the last `-n` rows.
    pub fn head(&self, n: i64) -> Result<Self, FrameError> {
        let take = normalize_head_take(n, self.len());
        // perf (br-frankenpandas-4dhu8): zero-copy contiguous slice per column +
        // index (typed/affine backing) instead of full materialization to Vec.
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), col.slice(0, take)?);
        }
        // Per br-frankenpandas-lhzot: preserve the index name.
        Self::new_with_column_order(
            self.index.slice(0, take).rename_index(self.index.name()),
            columns,
            self.column_order.clone(),
        )
    }

    /// Return the last `n` rows.
    ///
    /// Matches `df.tail(n)`. If `n` is negative, this returns all rows except
    /// the first `-n` rows.
    pub fn tail(&self, n: i64) -> Result<Self, FrameError> {
        let (start, take) = normalize_tail_window(n, self.len());
        // perf (br-frankenpandas-4dhu8): zero-copy contiguous slice per column +
        // index (typed/affine backing) instead of full materialization to Vec.
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            columns.insert(name.clone(), col.slice(start, take)?);
        }
        // Per br-frankenpandas-lhzot: preserve the index name.
        Self::new_with_column_order(
            self.index
                .slice(start, take)
                .rename_index(self.index.name()),
            columns,
            self.column_order.clone(),
        )
    }

    /// Set the DataFrame index from an existing column.
    ///
    /// Matches `df.set_index(column, drop=...)` for a single column selector.
    pub fn set_index(&self, column: &str, drop: bool) -> Result<Self, FrameError> {
        self.set_index_with_verify_integrity(column, drop, false)
    }

    /// Set the DataFrame index from an existing column while optionally
    /// rejecting duplicate labels.
    pub fn set_index_with_verify_integrity(
        &self,
        column: &str,
        drop: bool,
        verify_integrity: bool,
    ) -> Result<Self, FrameError> {
        let source = self.columns.get(column).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("column '{column}' not found"))
        })?;

        // perf (br-frankenpandas-p9omo): typed Int64 column -> index without the
        // per-Scalar scalar_to_index_label map + Index::new generic build. as_i64_slice
        // is Some only for an all-valid Int64 column (no nulls to reject), so this is
        // bit-identical to Index::new([IndexLabel::Int64..]) — the inverse of bp6k7.
        // Per br-frankenpandas-fuzon: pandas set_index(col) sets the new index name to col.
        let index = if let Some(data) = source.as_i64_slice() {
            Index::from_i64_values(data.to_vec()).rename_index(Some(column))
        } else if let Some(data) = source.as_f64_slice() {
            // Typed all-valid Float64 -> Float64 labels directly, skipping the
            // `.values()` Scalar Vec + the `scalar_to_index_label` map. Bit-
            // identical to the generic path: `scalar_to_index_label(Float64(v))`
            // IS this (`-0.0` normalized to `+0.0`, wrapped in `OrderedF64`), and
            // `as_f64_slice` is all-valid so there is no Null label to reject.
            let labels: Vec<IndexLabel> = data
                .iter()
                .map(|&v| {
                    let v = if v == 0.0 { 0.0 } else { v };
                    IndexLabel::Float64(fp_index::OrderedF64(v))
                })
                .collect();
            Index::new(labels).rename_index(Some(column))
        } else if let Some((bytes, offsets)) = source.utf8_contiguous_arcs() {
            // Typed all-valid contiguous-Utf8 -> lazy Utf8 index over the same
            // immutable backing. `Index::labels()` materializes the identical
            // `IndexLabel::Utf8` strings as the direct path, but set_index can
            // return without allocating one String per row.
            Index::from_utf8_contiguous(bytes, offsets).rename_index(Some(column))
        } else if source.dtype() == DType::Utf8 && source.validity().all() {
            // Scalar-backed (from_values) all-valid Utf8: the contiguous-arc fast
            // path above misses it, so set_index fell to the generic path that
            // allocates one IndexLabel::Utf8(String) PER ROW (2M small allocs,
            // 0.13x vs pandas at 2M). Materialize the strings into ONE contiguous
            // buffer (a single big alloc + sequential copy) and build the same
            // lazy Utf8 index. Bit-identical: the lazy index materializes the
            // identical per-row IndexLabel::Utf8 strings the generic path builds.
            let (bytes, offsets) = utf8_key_owned_contiguous(source)
                .expect("all-valid Utf8 column yields a contiguous buffer");
            Index::from_utf8_contiguous(std::sync::Arc::from(bytes), std::sync::Arc::from(offsets))
                .rename_index(Some(column))
        } else if let Some(data) = source.as_datetime64_slice()
            && !data.contains(&fp_types::Timestamp::NAT)
        {
            // Typed all-valid Datetime64 (no NaT) -> Datetime64 labels directly
            // (the common `df.set_index('datetime_col')` time-series path),
            // skipping the `.values()` Scalar Vec. Bit-identical:
            // `scalar_to_index_label(Datetime64(v)) = IndexLabel::Datetime64(v)`.
            // The NaT guard preserves the generic path's missing-label rejection.
            let labels: Vec<IndexLabel> = data.iter().map(|&v| IndexLabel::Datetime64(v)).collect();
            Index::new(labels).rename_index(Some(column))
        } else if let Some(data) = source.as_bool_slice() {
            // Typed all-valid Bool (as_bool_slice requires validity.all) -> Bool
            // labels directly. Bit-identical:
            // `scalar_to_index_label(Bool(b)) = IndexLabel::Bool(b)`.
            let labels: Vec<IndexLabel> = data.iter().map(|&b| IndexLabel::Bool(b)).collect();
            Index::new(labels).rename_index(Some(column))
        } else if let Some(data) = source.as_timedelta64_slice()
            && !data.contains(&fp_types::Timedelta::NAT)
        {
            // Typed all-valid Timedelta64 (no NaT) -> Timedelta64 labels directly.
            // Bit-identical: `scalar_to_index_label(Timedelta64(v)) =
            // IndexLabel::Timedelta64(v)`; the NaT guard preserves the generic
            // path's missing-label rejection.
            let labels: Vec<IndexLabel> =
                data.iter().map(|&v| IndexLabel::Timedelta64(v)).collect();
            Index::new(labels).rename_index(Some(column))
        } else {
            let labels = source
                .values()
                .iter()
                .map(scalar_to_index_label)
                .collect::<Result<Vec<_>, _>>()?;
            Index::new(labels).rename_index(Some(column))
        };

        if verify_integrity && index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "Index has duplicate keys".to_owned(),
            ));
        }

        if !drop {
            return Self::new_with_column_order(
                index,
                self.columns.clone(),
                self.column_order.clone(),
            );
        }

        let column_order = self
            .column_order
            .iter()
            .filter(|name| name.as_str() != column)
            .cloned()
            .collect::<Vec<_>>();
        let columns: BTreeMap<String, Column> = column_order
            .iter()
            .map(|name| (name.clone(), self.columns[name].clone()))
            .collect();
        Self::new_with_column_order(index, columns, column_order)
    }

    /// Set the index from multiple columns, creating a composite index.
    ///
    /// Matches `df.set_index([col1, col2, ...])` in pandas. The composite
    /// index labels are created by joining column values with a separator.
    /// A `MultiIndex` can be recovered via `to_multi_index()`.
    pub fn set_index_multi(
        &self,
        columns: &[&str],
        drop: bool,
        sep: &str,
    ) -> Result<Self, FrameError> {
        if columns.is_empty() {
            return Err(FrameError::CompatibilityRejected(
                "set_index_multi requires at least one column".into(),
            ));
        }

        // Single column: delegate to existing set_index.
        if columns.len() == 1 {
            return self.set_index(columns[0], drop);
        }

        // Validate all columns exist.
        for &col in columns {
            if !self.columns.contains_key(col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "column '{col}' not found"
                )));
            }
        }

        let row_multiindex = self.to_multi_index(columns)?;
        // Keep the flat storage fallback index for now so the existing API
        // surface keeps working while row MultiIndex support lands incrementally.
        // `to_flat_index` now returns a contiguous-Utf8-backed Index; keep that
        // backing and just set the name — the old `.labels().to_vec()` +
        // `Index::new(labels)` round-trip re-materialized every composite label into a
        // fresh `String`, throwing away the contiguous build's whole benefit.
        let new_name_parts: Vec<String> = columns.iter().map(|c| (*c).to_owned()).collect();
        let index = row_multiindex
            .to_flat_index(sep)
            .set_name(&new_name_parts.join(sep));

        let mut out_columns = self.columns.clone();
        let mut out_order = self.column_order.clone();

        if drop {
            for &col in columns {
                out_columns.remove(col);
                out_order.retain(|n| n != col);
            }
        }

        Self::new_with_axes(index, Some(row_multiindex), out_columns, out_order, None)
    }

    /// Extract a `MultiIndex` from the specified columns.
    ///
    /// Does NOT modify the DataFrame. Returns a standalone `MultiIndex`
    /// that can be used for hierarchical indexing operations.
    pub fn to_multi_index(&self, columns: &[&str]) -> Result<fp_index::MultiIndex, FrameError> {
        let nrows = self.index.len();
        let mut levels: Vec<Vec<IndexLabel>> = Vec::with_capacity(columns.len());

        for &col_name in columns {
            let col = self.columns.get(col_name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{col_name}' not found"))
            })?;
            // Typed Int64 fast path (br-frankenpandas-mi-typed): an all-valid Int64
            // column maps each raw `&[i64]` value straight to `IndexLabel::Int64` —
            // BIT-IDENTICAL to the per-cell path (which turns `Scalar::Int64(v)` into
            // `IndexLabel::Int64(v)`) but skips the per-cell `col.value(i)` Scalar
            // materialization. This is the reshape/set_index MultiIndex level build
            // (hit by wide_to_long / stack / unstack / set_index_multi). `as_i64_slice`
            // is `Some` only for an all-valid Int64 column, so no missing-slot / other
            // dtype ever reaches here; those keep the generic per-cell path below.
            let level_labels: Vec<IndexLabel> = match col.as_i64_slice() {
                Some(s) if s.len() == nrows => s.iter().map(|&v| IndexLabel::Int64(v)).collect(),
                _ => (0..nrows)
                    .map(|i| {
                        col.value(i)
                            .map(|s| match s {
                                Scalar::Int64(v) => IndexLabel::Int64(*v),
                                Scalar::Utf8(v) => IndexLabel::Utf8(v.clone()),
                                // br-frankenpandas-9m9zf: pandas keeps these TYPED.
                                // Measured, live 2.2.3:
                                //   pd.MultiIndex.from_frame(df).levels
                                //     -> [[1.5, 2.5], [False, True]]  float / bool
                                // These two arms used to stringify to "1.5" and
                                // "True"/"False".
                                //
                                // ⚠️ ONLY these two arms move. The `Null` arm below
                                // maps to an EMPTY STRING, where the shared
                                // `scalar_to_typed_index_label` would give a typed
                                // null — a different question with its own blast
                                // radius, so this is not routed through that mapper
                                // wholesale.
                                Scalar::Float64(v) => IndexLabel::Float64(fp_index::OrderedF64(*v)),
                                Scalar::Bool(b) => IndexLabel::Bool(*b),
                                Scalar::Null(_) => IndexLabel::Utf8(String::new()),
                                Scalar::Timedelta64(v) => IndexLabel::Utf8(Timedelta::format(*v)),
                                Scalar::Datetime64(v) => IndexLabel::Utf8(format_datetime_ns(*v)),
                                Scalar::Period(v) => IndexLabel::Utf8(v.calendar_string()),
                                Scalar::Interval(interval) => {
                                    IndexLabel::Utf8(format!("{interval}"))
                                }
                            })
                            .unwrap_or(IndexLabel::Utf8(String::new()))
                    })
                    .collect(),
            };
            levels.push(level_labels);
        }

        let names: Vec<Option<String>> = columns.iter().map(|&c| Some(c.to_owned())).collect();

        fp_index::MultiIndex::from_arrays(levels)
            .map(|mi| mi.set_names(names))
            .map_err(FrameError::Index)
    }

    /// Reset the index to a default RangeIndex.
    ///
    /// Matches `df.reset_index(drop=...)` for the single-index DataFrame model.
    pub fn reset_index(&self, drop: bool) -> Result<Self, FrameError> {
        let index = range_index(self.len())?;
        if drop {
            return Self::new_with_axes(
                index,
                None,
                self.columns.clone(),
                self.column_order.clone(),
                self.column_multiindex.clone(),
            );
        }

        if let Some(row_multiindex) = self.row_multiindex.as_ref() {
            let mut columns = self.columns.clone();
            let mut column_order = self.reset_index_multi_column_names(row_multiindex)?;
            for (level, column_name) in column_order.iter().enumerate() {
                let level_index = row_multiindex.get_level_values(level)?;
                // perf (br-frankenpandas-bp6k7): typed Int64 level -> column without
                // the Scalar round-trip (all-Int64 level has no missing labels).
                let level_column = match level_index.int64_label_values() {
                    Some(view) => Column::from_i64_values_owned(view.as_ref().clone()),
                    None => {
                        Column::from_values(Self::index_labels_to_scalars(level_index.labels()))?
                    }
                };
                columns.insert(column_name.clone(), level_column);
            }
            column_order.extend(self.column_order.iter().cloned());
            return Self::new_with_axes(
                index,
                None,
                columns,
                column_order,
                self.column_multiindex.clone(),
            );
        }

        let index_column_name = self.reset_index_column_name()?;
        // perf (br-frankenpandas-bp6k7): typed Int64 index -> column without the
        // per-label Scalar materialize + re-validation. An all-Int64 index (default
        // RangeIndex / int indexes) has no missing labels, so from_i64_values is
        // bit-identical to from_values([Scalar::Int64..]).
        let index_column = match self.index.int64_label_values() {
            Some(view) => Column::from_i64_values_owned(view.as_ref().clone()),
            None => Column::from_values(Self::index_labels_to_scalars(self.index.labels()))?,
        };

        let mut columns = self.columns.clone();
        columns.insert(index_column_name.clone(), index_column);
        let mut column_order = Vec::with_capacity(self.column_order.len() + 1);
        column_order.push(index_column_name);
        column_order.extend(self.column_order.iter().cloned());

        Self::new_with_axes(
            index,
            None,
            columns,
            column_order,
            self.column_multiindex.clone(),
        )
    }

    fn rebuild_with_row_multiindex(
        &self,
        row_multiindex: fp_index::MultiIndex,
    ) -> Result<Self, FrameError> {
        let index = Self::flatten_row_multiindex(&row_multiindex, "|");
        Self::new_with_axes(
            index,
            Some(row_multiindex),
            self.columns.clone(),
            self.column_order.clone(),
            self.column_multiindex.clone(),
        )
    }

    fn rebuild_with_row_index(
        &self,
        row_index: fp_index::MultiIndexOrIndex,
    ) -> Result<Self, FrameError> {
        match row_index {
            fp_index::MultiIndexOrIndex::Index(index) => Self::new_with_axes(
                index,
                None,
                self.columns.clone(),
                self.column_order.clone(),
                self.column_multiindex.clone(),
            ),
            fp_index::MultiIndexOrIndex::Multi(row_multiindex) => {
                self.rebuild_with_row_multiindex(row_multiindex)
            }
        }
    }

    /// Return a new DataFrame sorted by index labels.
    ///
    /// Matches `df.sort_index(ascending=...)` for 1D index labels.
    pub fn sort_index(&self, ascending: bool) -> Result<Self, FrameError> {
        // Already-sorted short-circuit (matches pandas, which returns a copy
        // near-instantly for a monotonic index instead of materializing the
        // label keys, argsorting, and gathering every row). A STABLE sort of an
        // already-ordered index is the identity permutation — ties keep input
        // order — so the result equals `self`. The monotonic check is O(1) for
        // an affine/RangeIndex backing (no label materialization). This is the
        // common case: a default RangeIndex is always ascending-monotonic, so
        // `df.sort_index()` was paying a full radix-sort + 10-column gather to
        // reproduce its own rows.
        if (ascending && self.index.is_monotonic_increasing())
            || (!ascending && self.index.is_monotonic_decreasing())
        {
            return Ok(self.clone());
        }
        // Radix fast path (br-frankenpandas-y5s15): an all-Int64 index sorts its
        // i64 label keys with the comparison-free O(n) stable radix instead of
        // the O(n log n) IndexLabel comparator. Bit-identical — every label is
        // Int64, so `IndexLabel::cmp` reduces to `i64::cmp`; the stable radix
        // keeps duplicate-label ties in original order (exactly the stable
        // `sort_by`), and descending flips the key without reordering ties.
        if let Some(values) = self.index.int64_label_values() {
            let order = fp_columnar::radix_argsort_i64(&values, ascending);
            return self.reorder_rows_by_positions_unchecked(&order);
        }
        let mut order = (0..self.len()).collect::<Vec<_>>();
        order.sort_by(|&left, &right| {
            if ascending {
                self.index.labels()[left].cmp(&self.index.labels()[right])
            } else {
                self.index.labels()[right].cmp(&self.index.labels()[left])
            }
        });
        // order is a permutation of 0..len(), always valid
        self.reorder_rows_by_positions_unchecked(&order)
    }

    /// Sort the DataFrame by column names (axis=1).
    ///
    /// Matches `df.sort_index(axis=1, ascending=...)`.
    pub fn sort_index_axis1(&self, ascending: bool) -> Result<Self, FrameError> {
        let mut order: Vec<usize> = (0..self.column_order.len()).collect();
        order.sort_by(|&a, &b| {
            if ascending {
                self.column_order[a].cmp(&self.column_order[b])
            } else {
                self.column_order[b].cmp(&self.column_order[a])
            }
        });
        let sorted_cols: Vec<&str> = order
            .iter()
            .map(|&i| self.column_order[i].as_str())
            .collect();
        self.select_columns(&sorted_cols)
    }

    /// Return a new DataFrame sorted by a column's values.
    ///
    /// Matches `df.sort_values(by=column, ascending=...)` for a single
    /// column key with default `na_position='last'`.
    pub fn sort_values(&self, column: &str, ascending: bool) -> Result<Self, FrameError> {
        self.sort_values_na(column, ascending, "last")
    }

    /// Return a new DataFrame sorted by a column's values with explicit NA position.
    ///
    /// Matches `df.sort_values(by=column, ascending=..., na_position='first'|'last')`.
    pub fn sort_values_na(
        &self,
        column: &str,
        ascending: bool,
        na_position: &str,
    ) -> Result<Self, FrameError> {
        let sort_column = self.columns.get(column).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("column '{column}' not found"))
        })?;
        // Per br-frankenpandas-2ca7d.
        match na_position {
            "first" | "last" => {}
            other => {
                return Err(FrameError::CompatibilityRejected(format!(
                    "sort_values: na_position must be 'first' or 'last', got '{other}'"
                )));
            }
        }

        let na_first = na_position == "first";
        // All-valid Utf8 (na_position='last'): argsort_with runs a stable MSD byte
        // radix for BOTH the contiguous backing (raw &[u8] spans) AND the
        // Scalar-backed backing (over the materialized &str) — but this gate only
        // admitted the contiguous one, so a from_values Utf8 sort key fell to the
        // generic O(n log n) compare_scalars Scalar sort (0.59x vs pandas; ~2.3s at
        // 2M). Relaxing the gate to any all-valid Utf8 routes both backings through
        // the same radix. Bit-identical: identical argsort_with call/result.
        if !na_first && sort_column.dtype() == DType::Utf8 && sort_column.validity().all() {
            let order = sort_column.argsort_with(ascending);
            return self.reorder_rows_by_positions_unchecked(&order);
        }
        // br-frankenpandas-uza04: try the column's contiguous typed buffer FIRST,
        // and only fall back to `sort_column.values()` when it has none. On an
        // all-valid Int64/Float64 key that keeps the `Vec<Scalar>` spine out of a
        // single-column sort entirely — the multi-column sibling has read its keys
        // this way since br-frankenpandas-1tuf5.
        let already_sorted = typed_slice_already_sorted(sort_column, ascending)
            .or_else(|| {
                typed_dense_values_already_sorted(
                    sort_column.values(),
                    sort_column.dtype(),
                    ascending,
                )
            })
            .unwrap_or_else(|| {
                values_already_sorted_with_na_position(sort_column.values(), ascending, na_first)
            });
        if already_sorted {
            return Ok(self.clone());
        }

        let order = if !na_first && let Some(order) = typed_slice_sort_order(sort_column, ascending)
        {
            order
        } else if !na_first
            && let Some(order) =
                typed_dense_sort_order(sort_column.values(), sort_column.dtype(), ascending)
        {
            order
        } else if !na_first
            && ascending
            && let Some((data, validity)) = sort_column.as_f64_slice_with_validity()
        {
            // Typed nullable Float64, na_position='last', ascending fast path
            // (br-frankenpandas-s2i37): the all-valid `typed_dense_sort_order`
            // above bails on ANY NaN/missing, so a nullable Float64 sort key fell
            // to the generic O(n log n) `compare_scalars_with_na_position` sort
            // over materialized `Scalar`s. Radix-argsort the valid finite values
            // off the raw `&[f64]` (the same stable `radix_argsort_f64` kernel the
            // all-valid path uses) and append the missing/NaN positions in input
            // order. Bit-identical to the generic stable sort: for the valid
            // subset, stable ascending radix == the stable `partial_cmp` compare
            // (equal values keep input order); NA rows sort last
            // (`na_position='last'`) and, comparing Equal to one another under a
            // stable sort, keep their input order — which `na_pos` preserves.
            let mut valid: Vec<f64> = Vec::with_capacity(data.len());
            let mut valid_pos: Vec<usize> = Vec::with_capacity(data.len());
            let mut na_pos: Vec<usize> = Vec::new();
            for (i, &value) in data.iter().enumerate() {
                if validity.get(i) && !value.is_nan() {
                    valid.push(value);
                    valid_pos.push(i);
                } else {
                    na_pos.push(i);
                }
            }
            let sorted = fp_columnar::radix_argsort_f64(&valid, true);
            let mut order: Vec<usize> = sorted.into_iter().map(|k| valid_pos[k]).collect();
            order.extend(na_pos);
            order
        } else {
            let mut order = (0..self.len()).collect::<Vec<_>>();
            order.sort_by(|&left_pos, &right_pos| {
                compare_scalars_with_na_position(
                    &sort_column.values()[left_pos],
                    &sort_column.values()[right_pos],
                    ascending,
                    na_first,
                )
            });
            order
        };

        // order is a permutation of 0..len(), always valid. Preserve ownership
        // so large homogeneous Float64 frames can share the tape across lazy
        // payload gathers without copying it into every column operation.
        self.reorder_rows_by_owned_positions_unchecked(order)
    }

    /// Sort by multiple columns with per-column ascending flags.
    ///
    /// Matches `df.sort_values(by=[...], ascending=[...], na_position='first'|'last')`.
    /// `na_position` defaults to "last".
    pub fn sort_values_multi(
        &self,
        by: &[&str],
        ascending: &[bool],
        na_position: &str,
    ) -> Result<Self, FrameError> {
        if by.is_empty() {
            return Ok(self.clone());
        }

        // Validate columns exist
        let sort_cols: Vec<&Column> = by
            .iter()
            .map(|name| {
                self.columns.get(name).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!("column '{name}' not found"))
                })
            })
            .collect::<Result<Vec<_>, _>>()?;

        // Pad ascending to match by length (default true)
        let asc: Vec<bool> = by
            .iter()
            .enumerate()
            .map(|(i, _)| ascending.get(i).copied().unwrap_or(true))
            .collect();
        // Per br-frankenpandas-2ca7d.
        match na_position {
            "first" | "last" => {}
            other => {
                return Err(FrameError::CompatibilityRejected(format!(
                    "sort_values: na_position must be 'first' or 'last', got '{other}'"
                )));
            }
        }

        let na_first = na_position == "first";

        // Stable LSD radix lexsort fast path (br-frankenpandas-lnsu6): when every
        // sort column is an all-valid Int64 or all-valid no-NaN Float64, the order
        // is a pure stable lexicographic value sort (no missing ⇒ na_position
        // moot), which the comparison-free O(n·k) multi-key radix computes
        // bit-identically — per-column ascending/descending baked into the
        // monotonic keys, stable ties keeping original order, exactly the
        // `compare_scalars_with_na_position` (false,false) lexicographic result.
        // Any Utf8/Bool/nullable/NaN-Float64 column → keys are `None` → fall to
        // the typed-comparison path below.
        let radix_keys: Option<Vec<Vec<u64>>> = sort_cols
            .iter()
            .zip(asc.iter())
            .map(|(col, &ascending)| col.typed_radix_keys(ascending))
            .collect();
        if let Some(keys) = radix_keys {
            let order = fp_columnar::radix_argsort_multi_u64(&keys);
            return self.reorder_rows_by_owned_positions_unchecked(order);
        }

        // Per-column typed sort key (br-frankenpandas-1tuf5): an all-valid Int64
        // or all-valid no-NaN Float64 column compares over its contiguous typed
        // slice — no `Vec<Scalar>` materialization, no `is_missing` branch, no
        // `compare_scalars` enum dispatch. Bit-identical to the Scalar path: such
        // columns have no missing (the `(false,false)` arm always fires), the
        // Int64 typed `cmp` is exactly `compare_non_missing`'s Int64 branch, and
        // a no-NaN Float64 `partial_cmp` never returns `None`, matching the
        // Float64 branch's `unwrap_or(Equal)`. Other columns keep the Scalar path.
        enum SortKey<'a> {
            I64(&'a [i64]),
            F64(&'a [f64]),
            Scalars(&'a [Scalar]),
        }
        let keys: Vec<SortKey<'_>> = sort_cols
            .iter()
            .map(|col| {
                if let Some(s) = col.as_i64_slice() {
                    SortKey::I64(s)
                } else if let Some(s) = col.as_f64_slice()
                    && !s.iter().any(|x| x.is_nan())
                {
                    SortKey::F64(s)
                } else {
                    SortKey::Scalars(col.values())
                }
            })
            .collect();

        let mut order: Vec<usize> = (0..self.len()).collect();
        order.sort_by(|&a, &b| {
            for (col_idx, key) in keys.iter().enumerate() {
                let ascending = asc[col_idx];
                let cmp = match key {
                    SortKey::I64(s) => {
                        let order = s[a].cmp(&s[b]);
                        if ascending { order } else { order.reverse() }
                    }
                    SortKey::F64(s) => {
                        let order = s[a].partial_cmp(&s[b]).unwrap_or(Ordering::Equal);
                        if ascending { order } else { order.reverse() }
                    }
                    SortKey::Scalars(vals) => {
                        let left = &vals[a];
                        let right = &vals[b];
                        let l_miss = left.is_missing();
                        let r_miss = right.is_missing();
                        if l_miss && r_miss {
                            continue;
                        }
                        if l_miss {
                            return if na_first {
                                Ordering::Less
                            } else {
                                Ordering::Greater
                            };
                        }
                        if r_miss {
                            return if na_first {
                                Ordering::Greater
                            } else {
                                Ordering::Less
                            };
                        }
                        compare_scalars_with_na_last(left, right, ascending)
                    }
                };
                if cmp != Ordering::Equal {
                    return cmp;
                }
            }
            Ordering::Equal
        });

        // order is a permutation of 0..len(), always valid. Preserve ownership
        // so the multi-key path shares the same deferred payload-gather tape as
        // the single-key radix path.
        self.reorder_rows_by_owned_positions_unchecked(order)
    }

    /// Label-based row selection for list-like indexers.
    ///
    /// Matches `df.loc[[...]]` for list selectors. Requested labels are
    /// returned in selector order and duplicate labels are preserved.
    /// Missing labels fail closed.
    pub fn loc(&self, labels: &[IndexLabel]) -> Result<Self, FrameError> {
        self.loc_with_columns(labels, None)
    }

    /// Label-based row+column selection for list-like indexers.
    ///
    /// Matches `df.loc[[...], [...]]` for list selectors. Requested rows are
    /// returned in selector order and duplicate row labels are preserved.
    /// Missing labels/columns fail closed.
    pub fn loc_with_columns(
        &self,
        labels: &[IndexLabel],
        column_selector: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        // O(m+n): build a label->positions map once (ascending positions) and
        // look up each requested row label, replacing the old O(m·n) per-label
        // full-index rescan. Bit-identical: each requested label yields every
        // matching position in ascending index order, selector order +
        // duplicate selectors are preserved, and a missing label fails closed.
        let mut positions = Vec::with_capacity(labels.len());
        // The unit-range fast path collects raw `i64` labels so the result index
        // can be built as a typed (lazy) Int64 index via `from_i64_values` — no
        // `Vec<IndexLabel>` materialization (input OR output) and no eager
        // duplicate scan; the general path collects `IndexLabel`s as before.
        let unit_range = self.index.int64_unit_range_labels();
        let mut out_label_ints: Vec<i64> = Vec::new();
        let mut out_labels: Vec<IndexLabel> = Vec::new();
        let mut use_typed_int64_index = false;
        if let Some((start, len)) = unit_range {
            // Unit-range Int64 index (pandas RangeIndex default): resolve each
            // requested Int64(v) to position v-start arithmetically — O(1) per
            // label, NO `positions_by_label` map (which allocated a `Vec<usize>`
            // per index label, ~100k tiny allocs) (br-frankenpandas-uza04.113).
            // The unit range is strictly unique, so each label matches exactly
            // one position (or none ⇒ fail closed, same as the map miss); the
            // emitted out_label equals the requested `Int64(v)` (off = v-start,
            // label = start+off = v), so we record the raw `v` and never touch
            // `self.index.labels()` (br index-rematerialization family).
            use_typed_int64_index = true;
            out_label_ints.reserve(labels.len());
            for requested in labels {
                match requested {
                    IndexLabel::Int64(v) => {
                        let off = v.wrapping_sub(start);
                        if off >= 0 && (off as u64) < len as u64 {
                            positions.push(off as usize);
                            out_label_ints.push(*v);
                        } else {
                            return Err(FrameError::CompatibilityRejected(format!(
                                "loc label not found: {requested:?}"
                            )));
                        }
                    }
                    _ => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else if let Some(resolved_positions) = self.index.sorted_unique_int64_positions(labels) {
            // Same unique sorted-Int64 row resolver as Series::loc: one raw i64
            // binary search per requested label, duplicate/unsorted indexes keep
            // the map path below so multi-position pandas semantics are intact.
            use_typed_int64_index = true;
            out_label_ints.reserve(labels.len());
            for (requested, position) in labels.iter().zip(resolved_positions) {
                match (requested, position) {
                    (IndexLabel::Int64(value), Some(position)) => {
                        positions.push(position);
                        out_label_ints.push(*value);
                    }
                    _ => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else if let Some(resolved_positions) = self.index.unsorted_unique_int64_positions(labels)
        {
            // Unsorted unique Int64 rows: identity-cached i64->position hashtable
            // (mirror of Series::loc); duplicate/non-Int64 indexes keep the map
            // path below for multi-position pandas semantics.
            use_typed_int64_index = true;
            out_label_ints.reserve(labels.len());
            for (requested, position) in labels.iter().zip(resolved_positions) {
                match (requested, position) {
                    (IndexLabel::Int64(value), Some(position)) => {
                        positions.push(position);
                        out_label_ints.push(*value);
                    }
                    _ => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else if let Some(resolved_positions) = self.index.unique_utf8_positions(labels) {
            // Unique all-Utf8 index: identity-cached String->position hashtable
            // (mirror of Series::loc); the matched label equals the requested
            // Utf8 selector. Missing/non-Utf8 fail closed; dup/non-utf8 indexes
            // keep the map path for multi-position pandas semantics.
            out_labels.reserve(labels.len());
            for (requested, position) in labels.iter().zip(resolved_positions) {
                match position {
                    Some(position) => {
                        positions.push(position);
                        out_labels.push(requested.clone());
                    }
                    None => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else if let Some(resolved_positions) = self.index.unique_datetime64_positions(labels) {
            // Unique Datetime64 (time-series) index: identity-cached ns->position
            // hashtable (mirror of Series::loc). Missing/non-Datetime64 fail
            // closed; dup/non-datetime keep the map path.
            out_labels.reserve(labels.len());
            for (requested, position) in labels.iter().zip(resolved_positions) {
                match position {
                    Some(position) => {
                        positions.push(position);
                        out_labels.push(requested.clone());
                    }
                    None => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else if let Some(resolved_positions) = self.index.unique_timedelta64_positions(labels) {
            // Unique Timedelta64 index: identity-cached ns->position hashtable
            // (deferred mirror of the Datetime64 path). Missing/non-Timedelta64
            // fail closed; dup/non-timedelta keep the map path.
            out_labels.reserve(labels.len());
            for (requested, position) in labels.iter().zip(resolved_positions) {
                match position {
                    Some(position) => {
                        positions.push(position);
                        out_labels.push(requested.clone());
                    }
                    None => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        } else {
            out_labels.reserve(labels.len());
            let index_labels = self.index.labels();
            let mut positions_by_label: FxHashMap<&IndexLabel, Vec<usize>> =
                FxHashMap::with_capacity_and_hasher(index_labels.len(), Default::default());
            for (position, actual) in index_labels.iter().enumerate() {
                positions_by_label.entry(actual).or_default().push(position);
            }
            for requested in labels {
                match positions_by_label.get(requested) {
                    Some(matched) => {
                        for &position in matched {
                            positions.push(position);
                            out_labels.push(index_labels[position].clone());
                        }
                    }
                    None => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "loc label not found: {requested:?}"
                        )));
                    }
                }
            }
        }

        let selected_columns = self.resolve_column_selector(column_selector)?;
        let mut columns = BTreeMap::new();
        for name in &selected_columns {
            let column = self.columns.get(name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{name}' not found"))
            })?;
            // Position-based gather (every `position` indexes an existing row —
            // loc fails closed on missing labels). `take_positions` is the same
            // typed gather iloc uses: bit-identical row order, dtype and validity,
            // but it also hits the zero-copy contiguous-range Float64/Int64/Utf8
            // VIEW fast path (share the source Arc, defer materialization) when
            // the positions are a contiguous ascending run — e.g. df.loc over a
            // range of RangeIndex labels — instead of copying every cell out.
            let column = column.take_positions(&positions);
            columns.insert(name.clone(), column);
        }

        // Per br-frankenpandas-j5tsz: pandas df.loc preserves row index name
        // on the selected subset. The unit-range fast path emits a typed Int64
        // index (lazy backing); the general path keeps the IndexLabel vector.
        let index = if use_typed_int64_index {
            Index::from_i64_values(out_label_ints).rename_index(self.index.name())
        } else {
            Index::new(out_labels).rename_index(self.index.name())
        };
        Self::new_with_column_order(index, columns, selected_columns)
    }

    fn require_row_multiindex(&self) -> Result<&fp_index::MultiIndex, FrameError> {
        self.row_multiindex.as_ref().ok_or_else(|| {
            FrameError::CompatibilityRejected(
                "operation requires a row MultiIndex on the DataFrame".to_owned(),
            )
        })
    }

    /// Tuple-/prefix-key row selection against a row MultiIndex.
    ///
    /// Exact tuple keys (`[lvl0, lvl1, ...]`) match full composite rows.
    /// Shorter keys act as prefix selection, mirroring `df.loc[(a, slice(None))]`
    /// for the leading levels.
    pub fn loc_tuple(&self, key: &[IndexLabel]) -> Result<Self, FrameError> {
        self.loc_tuple_with_columns(key, None)
    }

    /// Tuple-/prefix-key row selection with an optional column subset.
    pub fn loc_tuple_with_columns(
        &self,
        key: &[IndexLabel],
        column_selector: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        let row_multiindex = self.require_row_multiindex()?;
        let (positions, remaining_index) = row_multiindex
            .get_loc_level(key)
            .map_err(FrameError::Index)?;
        let selected_columns = self.resolve_column_selector(column_selector)?;
        let mut columns = BTreeMap::new();
        for name in &selected_columns {
            let column = self.columns.get(name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{name}' not found"))
            })?;
            // perf (br-frankenpandas-j4qjl): zero-copy typed per-column gather.
            columns.insert(name.clone(), column.take_positions(&positions));
        }

        match remaining_index {
            Some(fp_index::MultiIndexOrIndex::Index(index)) => {
                Self::new_with_axes(index, None, columns, selected_columns, None)
            }
            Some(fp_index::MultiIndexOrIndex::Multi(row_multiindex)) => Self::new_with_axes(
                Self::flatten_row_multiindex(&row_multiindex, "|"),
                Some(row_multiindex),
                columns,
                selected_columns,
                None,
            ),
            None => {
                let index = self.index.take(&positions);
                let row_multiindex = self
                    .row_multiindex
                    .as_ref()
                    .map(|multiindex| Self::project_row_multiindex(multiindex, &positions))
                    .transpose()?;
                Self::new_with_axes(index, row_multiindex, columns, selected_columns, None)
            }
        }
    }

    /// Return row positions for a row-MultiIndex tuple or a single level key.
    ///
    /// `level=None` performs exact or prefix tuple lookup depending on key arity.
    /// `level=Some(n)` performs a single-label lookup on the N-th level.
    pub fn get_loc(
        &self,
        key: &[IndexLabel],
        level: Option<usize>,
    ) -> Result<Vec<usize>, FrameError> {
        self.require_row_multiindex()?
            .get_loc(key, level)
            .map_err(FrameError::Index)
    }

    /// pandas-style tuple lookup returning matching positions and the remaining row index.
    pub fn get_loc_level(
        &self,
        key: &[IndexLabel],
    ) -> Result<(Vec<usize>, Option<fp_index::MultiIndexOrIndex>), FrameError> {
        self.require_row_multiindex()?
            .get_loc_level(key)
            .map_err(FrameError::Index)
    }

    /// Position-based row selection for list-like indexers.
    ///
    /// Matches `df.iloc[[...]]` for list selectors. Requested positions are
    /// returned in selector order and duplicates are preserved.
    /// Negative positions are resolved from the end of the DataFrame.
    pub fn iloc(&self, positions: &[i64]) -> Result<Self, FrameError> {
        self.iloc_with_columns(positions, None)
    }

    /// Position-based row+column selection for list-like indexers.
    ///
    /// Matches `df.iloc[[...], [...]]` for list selectors. Requested rows are
    /// returned in selector order and duplicates are preserved.
    /// Missing columns fail closed.
    pub fn iloc_with_columns(
        &self,
        positions: &[i64],
        column_selector: Option<&[String]>,
    ) -> Result<Self, FrameError> {
        let normalized_positions = positions
            .iter()
            .copied()
            .map(|position| normalize_iloc_position(position, self.len()))
            .collect::<Result<Vec<_>, _>>()?;

        // Fast path (br-frankenpandas-2tr7w): a strictly-ascending arithmetic
        // progression of positions — the common `iloc[a:b]` contiguous slice
        // (step 1) or `iloc[a:b:s]` stride — routes to the O(1) affine selection
        // (arithmetic index + slice-view columns) that `loc_bool` already uses,
        // skipping the per-row label clone + per-row gather. Restricted to the
        // all-columns selector because the affine path returns every column in
        // `column_order`; any column subset keeps the general gather. Bit-
        // identical: the affine path selects the same rows in the same order and
        // preserves each source dtype/value and the index labels (proven by the
        // shared use in `loc_bool`).
        if column_selector.is_none()
            && let Some(certificate) = affine_certificate_from_positions(&normalized_positions)
            && let Some(result) = self.take_rows_by_affine_certificate_unchecked(certificate)
        {
            return result;
        }

        let mut out_labels = Vec::with_capacity(normalized_positions.len());
        for &position in &normalized_positions {
            out_labels.push(self.index.labels()[position].clone());
        }

        let selected_columns = self.resolve_column_selector(column_selector)?;
        let mut columns = BTreeMap::new();
        for name in &selected_columns {
            let column = self.columns.get(name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{name}' not found"))
            })?;
            // Typed gather: Column::take_positions keeps an all-valid Int64/
            // Float64 buffer contiguous (and carries data+validity for nullable
            // Float64) instead of cloning a 32 B Scalar per row + re-validating
            // in Column::new. Bit-identical — it preserves the source dtype, the
            // same Column the DataFrame row-reorder path already produces.
            columns.insert(name.clone(), column.take_positions(&normalized_positions));
        }

        // Per br-frankenpandas-4wlg0: pandas df.iloc preserves row index name.
        let index = Index::new(out_labels).rename_index(self.index.name());
        Self::new_with_column_order(index, columns, selected_columns)
    }

    /// Boolean mask row selection.
    ///
    /// Matches `df.loc[bool_array]` in pandas. The boolean mask must have the
    /// same length as the DataFrame. Rows where the mask is `True` are kept.
    pub fn loc_bool(&self, mask: &[bool]) -> Result<Self, FrameError> {
        self.loc_bool_with_affine_witness(mask, None)
    }

    fn loc_bool_with_affine_witness(
        &self,
        mask: &[bool],
        witness: Option<BoolAffineSelectionWitness>,
    ) -> Result<Self, FrameError> {
        if mask.len() != self.len() {
            return Err(FrameError::CompatibilityRejected(format!(
                "boolean index has wrong length: {} instead of {}",
                mask.len(),
                self.len()
            )));
        }

        if let Some(witness) = witness {
            let certificate = AffineSelectionCertificate {
                start: witness.start,
                step: witness.step,
                len: witness.len,
            };
            if let Some(result) = self.take_rows_by_affine_certificate_unchecked(certificate) {
                return result;
            }
        }

        if let Some(certificate) = boolean_mask_affine_certificate(mask)
            && let Some(result) = self.take_rows_by_affine_certificate_unchecked(certificate)
        {
            return result;
        }

        let (positions, affine_certificate) = boolean_mask_positions(mask);
        self.take_rows_by_positions_with_affine_certificate_unchecked(
            &positions,
            affine_certificate,
        )
    }

    /// Boolean mask row selection (position-based).
    ///
    /// Matches `df.iloc[bool_array]` in pandas. Semantically identical to
    /// `loc_bool` for DataFrames (the mask selects rows by position either way).
    pub fn iloc_bool(&self, mask: &[bool]) -> Result<Self, FrameError> {
        self.loc_bool(mask)
    }

    /// Boolean Series mask row selection with index alignment.
    ///
    /// Matches `df.loc[bool_series]` in pandas, the most common usage pattern
    /// (e.g., `df.loc[df['col'] > 5]`). The mask Series is aligned with the
    /// DataFrame by index before filtering. Missing mask values are treated
    /// as `False`. This is an alias for `DataFrame::filter_rows`.
    pub fn loc_bool_series(&self, mask: &Series) -> Result<Self, FrameError> {
        self.filter_rows(mask)
    }

    /// Position-based boolean Series mask row selection with index alignment.
    ///
    /// Matches `df.iloc[bool_series]` in pandas. Semantically identical to
    /// `loc_bool_series` (delegates to `filter_rows`).
    pub fn iloc_bool_series(&self, mask: &Series) -> Result<Self, FrameError> {
        self.filter_rows(mask)
    }

    /// Label-based slice row selection (inclusive on both ends).
    ///
    /// Matches `df.loc[start:stop]` in pandas. Both endpoints are inclusive
    /// (pandas label-slicing semantics). Either may be `None` to mean "from
    /// the beginning" or "to the end".
    pub fn loc_slice(
        &self,
        start: Option<&IndexLabel>,
        stop: Option<&IndexLabel>,
    ) -> Result<Self, FrameError> {
        let labels = self.index.labels();
        if labels.is_empty() {
            let mut empty_cols = BTreeMap::new();
            for name in &self.column_order {
                let col = self
                    .columns
                    .get(name)
                    .expect("column name listed in order must exist");
                empty_cols.insert(name.clone(), Column::new(col.dtype(), Vec::new())?);
            }
            return Self::new_with_column_order(
                Index::new(Vec::new()),
                empty_cols,
                self.column_order.clone(),
            );
        }

        let start_pos = match start {
            Some(label) => labels.iter().position(|l| l == label).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!(
                    "loc slice start label not found: {label:?}"
                ))
            })?,
            None => 0,
        };

        let end_pos = match stop {
            Some(label) => labels.iter().rposition(|l| l == label).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!(
                    "loc slice stop label not found: {label:?}"
                ))
            })?,
            None => labels.len().saturating_sub(1),
        };

        if start_pos > end_pos {
            let empty_cols: BTreeMap<String, Column> = self
                .column_order
                .iter()
                .map(|name| {
                    let col = &self.columns[name];
                    (name.clone(), Column::new(col.dtype(), Vec::new()).unwrap())
                })
                .collect();
            return Self::new_with_column_order(
                Index::new(Vec::new()),
                empty_cols,
                self.column_order.clone(),
            );
        }

        let positions: Vec<usize> = (start_pos..=end_pos).collect();
        self.take_rows_by_positions(&positions)
    }

    /// Position-based slice row selection (exclusive end).
    ///
    /// Matches `df.iloc[start:stop]` in pandas. The `start` is inclusive and
    /// `stop` is exclusive (Python slice semantics). Negative values are
    /// resolved from the end. Both are optional.
    pub fn iloc_slice(&self, start: Option<i64>, stop: Option<i64>) -> Result<Self, FrameError> {
        let len = self.len();

        let resolve = |pos: i64| -> usize {
            if pos < 0 {
                (len as i64 + pos).max(0) as usize
            } else {
                (pos as usize).min(len)
            }
        };

        let start_pos = start.map_or(0, resolve);
        let end_pos = stop.map_or(len, resolve);

        if start_pos >= end_pos || start_pos >= len {
            let empty_cols: BTreeMap<String, Column> = self
                .column_order
                .iter()
                .map(|name| {
                    let col = &self.columns[name];
                    (name.clone(), Column::new(col.dtype(), Vec::new()).unwrap())
                })
                .collect();
            return Self::new_with_column_order(
                Index::new(Vec::new()),
                empty_cols,
                self.column_order.clone(),
            );
        }

        let len = end_pos - start_pos;
        if self.row_multiindex.is_none() {
            return self.take_contiguous_row_range_unchecked(start_pos, len);
        }

        let positions: Vec<usize> = (start_pos..end_pos).collect();
        self.take_rows_by_positions(&positions)
    }

    /// Return a single row as a Series by label.
    ///
    /// Matches `df.loc[label]` when `label` is a scalar in pandas. The
    /// returned Series has the DataFrame's column names as its index and the
    /// row values as data.
    pub fn loc_row(&self, label: &IndexLabel) -> Result<Series, FrameError> {
        let pos = self
            .index
            .labels()
            .iter()
            .position(|l| l == label)
            .ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("loc label not found: {label:?}"))
            })?;

        self.row_to_series(pos)
    }

    /// Return a single row as a Series by exact row-MultiIndex tuple.
    pub fn loc_row_tuple(&self, key: &[IndexLabel]) -> Result<Series, FrameError> {
        let positions = self.require_row_multiindex()?.get_loc_tuple(key)?;
        if positions.len() != 1 {
            return Err(FrameError::CompatibilityRejected(format!(
                "loc_row_tuple expected exactly 1 row for {:?}, found {}",
                key,
                positions.len()
            )));
        }
        self.row_to_series(positions[0])
    }

    /// Return a single row as a Series by position.
    ///
    /// Matches `df.iloc[n]` when `n` is a scalar in pandas. The returned
    /// Series has the DataFrame's column names as its index and the row values
    /// as data.
    pub fn iloc_row(&self, position: i64) -> Result<Series, FrameError> {
        let pos = normalize_iloc_position(position, self.len())?;
        self.row_to_series(pos)
    }

    /// Internal helper: extract a single row by position into a Series.
    fn row_to_series(&self, position: usize) -> Result<Series, FrameError> {
        let mut labels = Vec::with_capacity(self.column_order.len());
        let mut values = Vec::with_capacity(self.column_order.len());

        for name in &self.column_order {
            labels.push(IndexLabel::Utf8(name.clone()));
            let col = self.columns.get(name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{name}' not found"))
            })?;
            values.push(col.values()[position].clone());
        }

        // Use the index label as the Series name (pandas semantics).
        let row_label = &self.index.labels()[position];
        let name = match row_label {
            IndexLabel::Int64(v) => v.to_string(),
            IndexLabel::Utf8(s) => s.clone(),
            IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
            IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
            f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
            IndexLabel::Null(_) => row_label.to_string(),
        };

        // Try direct construction first. If dtypes are incompatible (e.g.,
        // Int64 + Utf8), fall back to Utf8 representation, matching pandas'
        // `object` dtype behavior for mixed-type rows.
        match Series::from_values(name.clone(), labels.clone(), values.clone()) {
            Ok(s) => Ok(s),
            Err(_) => {
                let utf8_values: Vec<Scalar> = values
                    .into_iter()
                    .map(|v| match v {
                        Scalar::Null(_) => Scalar::Null(NullKind::Null),
                        Scalar::Bool(b) => {
                            Scalar::Utf8(if b { "True" } else { "False" }.to_owned())
                        }
                        Scalar::Int64(n) => Scalar::Utf8(n.to_string()),
                        Scalar::Float64(f) => Scalar::Utf8(format!("{f}")),
                        Scalar::Utf8(s) => Scalar::Utf8(s),
                        Scalar::Timedelta64(v) => Scalar::Utf8(Timedelta::format(v)),
                        Scalar::Datetime64(v) => Scalar::Utf8(format_datetime_ns(v)),
                        Scalar::Period(v) => Scalar::Utf8(v.calendar_string()),
                        Scalar::Interval(interval) => Scalar::Utf8(format!("{interval}")),
                    })
                    .collect();
                Series::from_values(name, labels, utf8_values)
            }
        }
    }

    /// Add or replace a column.
    ///
    /// Matches `df['new_col'] = values`.
    pub fn with_column(&self, name: impl Into<String>, column: Column) -> Result<Self, FrameError> {
        if column.len() != self.len() {
            return Err(FrameError::LengthMismatch {
                index_len: self.len(),
                column_len: column.len(),
            });
        }
        let name = name.into();
        let mut columns = self.columns.clone();
        columns.insert(name.clone(), column);
        let mut column_order = self.column_order.clone();
        if !column_order.contains(&name) {
            column_order.push(name);
        }
        Self::new_with_column_order(self.index.clone(), columns, column_order)
    }

    /// Cast one or more columns to target dtypes.
    ///
    /// Matches mapping-style `df.astype({"a": dtype_a, "b": dtype_b})`.
    /// Mapping order is processed deterministically and duplicate selectors
    /// are rejected.
    pub fn astype_columns(&self, mapping: &[(&str, DType)]) -> Result<Self, FrameError> {
        let mut seen = BTreeSet::new();
        for &(name, _) in mapping {
            if !seen.insert(name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "duplicate astype selector: '{name}'"
                )));
            }

            if !self.columns.contains_key(name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "column '{name}' not found"
                )));
            }
        }

        let mut columns = self.columns.clone();
        for &(name, dtype) in mapping {
            let source = self.columns.get(name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column '{name}' not found"))
            })?;
            let casted = source.astype(dtype)?;
            columns.insert(name.to_owned(), casted);
        }

        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Cast a single column to a target dtype.
    ///
    /// Matches `df.astype({\"col\": dtype})` for single-column mapping.
    pub fn astype_column(&self, name: &str, dtype: DType) -> Result<Self, FrameError> {
        self.astype_columns(&[(name, dtype)])
    }

    /// Cast all columns to a single target dtype.
    ///
    /// Matches `df.astype(dtype)` (scalar form).
    pub fn astype(&self, dtype: DType) -> Result<Self, FrameError> {
        let mut columns = BTreeMap::new();
        for (name, col) in &self.columns {
            let casted = col.astype(dtype)?;
            columns.insert(name.clone(), casted);
        }
        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Apply the CONSTRUCTOR's `dtype=` argument to every column.
    ///
    /// Matches the `dtype=` parameter of `pd.DataFrame(data, dtype=...)`, which
    /// is deliberately NOT the same operation as [`Self::astype`] even though
    /// both name a target dtype. Measured on pandas 2.2.3:
    ///
    /// ```text
    /// pd.DataFrame([[1.5]], dtype='int64')     -> ValueError: Trying to coerce
    ///                                             float values to integers
    /// pd.DataFrame([[1.5]]).astype('int64')    -> [[1]]   <- TRUNCATES
    /// pd.DataFrame([[2.0]], dtype='int64')     -> [[2]]   <- lossless is fine
    /// ```
    ///
    /// So the constructor REFUSES a lossy float->int while `astype` truncates
    /// toward zero. `Column::new` already encodes the strict rule
    /// (br-frankenpandas-8nupg), and this is its frame-level composition.
    ///
    /// It exists as its own method rather than reusing `astype` because the two
    /// only COINCIDE today: `Self::astype` currently also goes through
    /// `Column::new` without pre-truncating, so it inherits the strict rule. The
    /// moment `astype` is corrected to truncate, a constructor path routed
    /// through it would silently start truncating too — a divergence nothing
    /// would catch. Keeping them separate makes that fix safe.
    ///
    /// Added by br-frankenpandas-oxodo: the conformance harness had been
    /// applying constructor `dtype=` ITSELF, so every `constructor_dtype`
    /// fixture was green against a capability FrankenPandas did not expose.
    /// Apply the DataFrame constructor's `dtype=` to every column.
    ///
    /// **A NON-NULLABLE `int64` REFUSES A MISSING VALUE.** numpy's `int64` has no
    /// NA representation, and pandas aborts the whole construction rather than
    /// inventing one - it does NOT fall back to a nullable dtype or to NaN.
    /// br-frankenpandas-v1zy1. MEASURED, live pandas 2.2.3, on
    /// `[[True, None], [False, True]]`:
    ///
    /// | `dtype=` | pandas | why |
    /// |---|---|---|
    /// | `int64` | **TypeError** | numpy int64 cannot hold NA |
    /// | `Int64` | `[1, <NA>]` | the nullable extension dtype can |
    /// | `float64` | `[1.0, nan]` | NaN IS float64's missing value |
    /// | `Float64` | `[1.0, <NA>]` | extension dtype |
    /// | `str` | `['True', None]` | the missing value SURVIVES the cast |
    /// | `string` | `['True', <NA>]` | ditto, as the extension dtype |
    /// | `bool` | `[True, False]` | COERCED by truthiness; `bool` has no NA |
    /// | `boolean` | `[True, <NA>]` | extension dtype |
    ///
    /// **THE THREE FAMILIES RESOLVE THE SAME PROBLEM THREE DIFFERENT WAYS**, which
    /// is why there is no single "non-nullable dtypes reject missing values" rule:
    /// `int64` RAISES, `bool` COERCES, `float64` has NaN as its own missing value.
    ///
    /// **A STRING CAST PRESERVES MISSINGNESS HERE AND ONLY HERE.** `astype(str)`
    /// genuinely does stringify - measured, `pd.Series([True, None]).astype(str)`
    /// is `['True', 'None']` - so the shared cast in `Column::new` is RIGHT for
    /// `astype` and wrong only for the constructor, which is why this method
    /// restores the missing values rather than the cast being changed.
    /// br-frankenpandas-constructor-utf8-null-stringified-r1bbv.
    ///
    /// Before this check FrankenPandas returned `[1, Null]` for BOTH spellings, so
    /// `int64` and `Int64` were behaviourally identical at the constructor and no
    /// value fixture could detect them being confused - which is why
    /// br-frankenpandas-jozfk's spec-resolution fix, correct on its own terms, did
    /// not make the corpus able to catch a regression that reverted it.
    ///
    /// The check lives HERE and deliberately NOT in `Column::new`: numpy-int64
    /// semantics are a property of the CONSTRUCTOR's `dtype=`, while `Column::new`
    /// is shared with `astype` and with internal builders that legitimately pair
    /// `DType::Int64` with missing values.
    pub fn with_constructor_dtype(&self, dtype: DType) -> Result<Self, FrameError> {
        let mut columns = BTreeMap::new();
        for (name, column) in &self.columns {
            // Bound once: `values()` may materialize a lazy column representation.
            let original = column.values();
            // Checked in the SAME pass that builds the columns, so that lazy
            // representation is walked once rather than twice.
            if dtype == DType::Int64 && original.iter().any(|v| matches!(v, Scalar::Null(_))) {
                // pandas' own message, verbatim - it surfaces from int(None).
                return Err(FrameError::CompatibilityRejected(
                    "int() argument must be a string, a bytes-like object or a real number, not 'NoneType'"
                        .to_string(),
                ));
            }
            // ⚠️ THE timedelta64 CONSTRUCTOR REFUSES A NON-FINITE FLOAT WHERE
            // astype ACCEPTS ONE. This is the constructor-only strictness that
            // `float_to_temporal_nanos` (fp-types) documents and deliberately
            // does NOT encode, because that cast is shared with astype and the
            // two pandas paths disagree. Same reason the int64 check above lives
            // here rather than in `Column::new`.
            //
            // MEASURED, live pandas 2.2.3, constructor beside astype:
            //
            //   dtype='timedelta64[ns]'   ctor                    astype
            //     inf / -inf / 1e30       OverflowError           NaT
            //     NaN                     NaT                     NaT
            //     exactly  2^63           OverflowError           NaT
            //     exactly -2^63           NaT                     NaT
            //
            // ⚠️ THE TWO 2^63 ENDS DISAGREE, and that is not a typo: -2^63 IS
            // i64::MIN, which is the NaT sentinel, so Python's int conversion
            // succeeds and lands exactly on NaT. +2^63 does not fit.
            //
            // ⚠️ datetime64 HAS NO SUCH REFUSAL — its constructor yields NaT for
            // inf too — so this is guarded on Timedelta64 alone.
            if dtype == DType::Timedelta64 {
                for value in original.iter() {
                    let Scalar::Float64(raw) = value else {
                        continue;
                    };
                    if raw.is_nan() {
                        continue;
                    }
                    if !raw.is_finite() {
                        // pandas' own message, verbatim.
                        return Err(FrameError::CompatibilityRejected(
                            "cannot convert float infinity to integer".to_string(),
                        ));
                    }
                    if *raw >= 9_223_372_036_854_775_808.0 || *raw < -9_223_372_036_854_775_808.0 {
                        return Err(FrameError::CompatibilityRejected(
                            "Python int too large to convert to C long".to_string(),
                        ));
                    }
                }
            }
            let coerced = if dtype == DType::Utf8 {
                // A STRING CAST PRESERVES MISSINGNESS AT THE CONSTRUCTOR.
                // br-frankenpandas-constructor-utf8-null-stringified-r1bbv.
                //
                // Cast through the ordinary rules first (so `true` still becomes
                // pandas' "True" rather than Rust's "true"), then put the missing
                // values back where they were. Restoring is what makes this
                // different from `astype`, NOT the casting.
                let cast = Column::new(dtype, original.to_vec())?;
                let mut values = cast.values().to_vec();
                for (slot, source) in values.iter_mut().zip(original.iter()) {
                    if let Scalar::Null(kind) = source {
                        *slot = Scalar::Null(*kind);
                    }
                }
                // Every element is now Utf8-or-Null, which is the arm of
                // `Column::new` that preserves a missing value instead of
                // coercing it.
                Column::new(dtype, values)?
            } else if dtype == DType::Bool {
                // numpy `bool` HAS NO NA, and pandas resolves that by COERCING
                // rather than by raising (as `int64` does) or by carrying a null.
                // The coercion is Python truthiness of whatever the missing value
                // IS, which is why the two NullKinds go opposite ways.
                // br-frankenpandas-constructor-bool-null-not-coerced-sgugy.
                let mut values = original.to_vec();
                for slot in values.iter_mut() {
                    if let Scalar::Null(kind) = slot {
                        *slot = Scalar::Bool(!matches!(kind, NullKind::Null));
                    }
                }
                Column::new(dtype, values)?
            } else {
                Column::new(dtype, original.to_vec())?
            };
            columns.insert(name.clone(), coerced);
        }
        Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
    }

    /// Localize tz-naive datetime columns to a timezone or strip timezone info.
    ///
    /// Matches the supported subset of `pd.DataFrame.tz_localize(tz)`. Walks
    /// every Utf8-typed column whose values look like ISO-8601 datetime
    /// strings and applies [`DatetimeAccessor::tz_localize`] column-by-column.
    /// Non-Utf8 columns and Utf8 columns whose contents don't parse as
    /// datetimes are passed through unchanged. Per br-frankenpandas-6iac0.
    ///
    /// Note: pandas' `DataFrame.tz_localize` operates on the index axis by
    /// default; this implementation deviates by walking column VALUES because
    /// fp-index doesn't yet have a dedicated DatetimeIndex variant (tracked
    /// separately under br-frankenpandas-t8hz0). When the DatetimeIndex
    /// variant lands, this method should grow an `axis` parameter.
    pub fn tz_localize(&self, tz: Option<&str>) -> Result<Self, FrameError> {
        self.tz_op_each_column(|series| series.dt().tz_localize(tz))
    }

    /// Localize tz-naive datetime columns with explicit DST policy.
    ///
    /// Matches the supported subset of `pd.DataFrame.tz_localize(tz,
    /// ambiguous=..., nonexistent=...)`. Same column-walking rules as
    /// [`Self::tz_localize`].
    pub fn tz_localize_with_options(
        &self,
        tz: Option<&str>,
        options: TzLocalizeOptions,
    ) -> Result<Self, FrameError> {
        self.tz_op_each_column(|series| series.dt().tz_localize_with_options(tz, options.clone()))
    }

    /// Convert timezone-aware datetime columns to a different timezone.
    ///
    /// Matches the supported subset of `pd.DataFrame.tz_convert(tz)`. Walks
    /// every Utf8 datetime-string column and applies [`DatetimeAccessor::tz_convert`]
    /// column-by-column. Non-Utf8 columns are passed through; columns whose
    /// values are tz-naive (no offset suffix) raise an error matching
    /// pandas' "Cannot convert tz-naive timestamps, use tz_localize" message.
    /// Per br-frankenpandas-6iac0.
    ///
    /// Same axis-deviation note as [`Self::tz_localize`].
    pub fn tz_convert(&self, tz: Option<&str>) -> Result<Self, FrameError> {
        self.tz_op_each_column(|series| series.dt().tz_convert(tz))
    }

    /// Convert a datetime-like row index to period-style labels.
    ///
    /// Matches the row-index default of `pd.DataFrame.to_period(freq)` for the
    /// supported `Y`, `Q`, `M`, `W`, `D`, `B`, `H`, `T`/`min`, and `S`
    /// frequencies.
    /// FrankenPandas stores the converted labels in the existing flat `Index`
    /// as canonical period strings until a dedicated Period label variant lands.
    pub fn to_period(&self, freq: &str) -> Result<Self, FrameError> {
        if self.row_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "to_period currently supports flat row indexes only".to_owned(),
            ));
        }

        let index = period_index_from_datetime_like_index(&self.index, freq)?;
        Ok(Self {
            index,
            row_multiindex: None,
            columns: self.columns.clone(),
            column_order: self.column_order.clone(),
            column_multiindex: self.column_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Convert period-style row index labels to timestamp labels.
    ///
    /// Matches the row-index default of `pd.DataFrame.to_timestamp(freq, how)`
    /// for the supported `Y`, `Q`, `M`, `D`, `H`, `T`/`min`, and `S`
    /// frequencies. Until FrankenPandas has a dedicated PeriodIndex label type,
    /// this accepts the canonical period strings emitted by [`Self::to_period`].
    pub fn to_timestamp(&self, freq: &str, how: &str) -> Result<Self, FrameError> {
        if self.row_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "to_timestamp currently supports flat row indexes only".to_owned(),
            ));
        }

        // Anchored weekly labels (W-MON..W-SAT) share the canonical Weekly
        // START/END string shape, so timestamp resolution is anchor-independent.
        let how = normalize_period_timestamp_how(how)?;

        // Anchored fiscal-year labels (Y-JAN..Y-NOV) need the anchor month to
        // resolve their start/end; anchored weekly labels share the canonical
        // Weekly START/END shape, so they route through PeriodFreq::Weekly.
        let labels = if let Some(anchor) = annual_anchor_month(freq) {
            self.index
                .labels()
                .iter()
                .map(|label| annual_anchored_label_to_timestamp(label, anchor, how))
                .collect::<Result<Vec<_>, _>>()?
        } else if let Some(anchor) = quarterly_anchor_month(freq) {
            self.index
                .labels()
                .iter()
                .map(|label| quarterly_anchored_label_to_timestamp(label, anchor, how))
                .collect::<Result<Vec<_>, _>>()?
        } else {
            let period_freq = if weekly_anchor_weekday(freq).is_some() {
                PeriodFreq::Weekly
            } else {
                PeriodFreq::parse(freq).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "to_timestamp: unsupported frequency '{freq}'"
                    ))
                })?
            };
            self.index
                .labels()
                .iter()
                .map(|label| period_label_to_timestamp(label, period_freq, how))
                .collect::<Result<Vec<_>, _>>()?
        };
        let index = Index::new(labels).set_names(self.index.name());
        Ok(Self {
            index,
            row_multiindex: None,
            columns: self.columns.clone(),
            column_order: self.column_order.clone(),
            column_multiindex: self.column_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Per br-frankenpandas-6iac0: shared column-walker used by tz_localize
    /// and tz_convert. For each Utf8 column, attempt the operation; on
    /// success, replace the column. For each non-Utf8 column, pass through
    /// unchanged. Errors from a Utf8 column propagate (matches pandas
    /// behavior of raising when applied to a non-datetime column).
    fn tz_op_each_column<F>(&self, mut op: F) -> Result<Self, FrameError>
    where
        F: FnMut(&Series) -> Result<Series, FrameError>,
    {
        let mut new_columns = BTreeMap::new();
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            if col.dtype() == DType::Utf8 {
                let series = Series::new(name.clone(), self.index.clone(), col.clone())?;
                let converted = op(&series)?;
                let new_col = Column::new(DType::Utf8, converted.values().to_vec())?;
                new_columns.insert(name.clone(), new_col);
            } else {
                new_columns.insert(name.clone(), col.clone());
            }
        }
        Self::new_with_column_order(self.index.clone(), new_columns, self.column_order.clone())
    }

    /// Cast one or more columns with error handling.
    ///
    /// Matches `df.astype({"a": dtype}, errors='coerce'|'raise'|'ignore')`.
    /// - `errors="raise"` (default): propagate conversion errors
    /// - `errors="coerce"`: values that fail conversion become NaN
    /// - `errors="ignore"`: return the original DataFrame unchanged on error
    pub fn astype_columns_safe(
        &self,
        mapping: &[(&str, DType)],
        errors: &str,
    ) -> Result<Self, FrameError> {
        // Per br-frankenpandas-3d30a.
        match errors {
            "raise" => self.astype_columns(mapping),
            "ignore" => self.astype_columns(mapping).or_else(|_| Ok(self.clone())),
            "coerce" => {
                let mut columns = self.columns.clone();
                for &(name, dtype) in mapping {
                    let source = self.columns.get(name).ok_or_else(|| {
                        FrameError::CompatibilityRejected(format!("column '{name}' not found"))
                    })?;
                    let vals: Vec<Scalar> = source
                        .values()
                        .iter()
                        .map(|val| coerce_scalar(val, dtype))
                        .collect();
                    let casted = Column::new(dtype, vals)?;
                    columns.insert(name.to_owned(), casted);
                }
                Self::new_with_column_order(self.index.clone(), columns, self.column_order.clone())
            }
            other => Err(FrameError::CompatibilityRejected(format!(
                "astype: errors must be 'raise', 'ignore', or 'coerce', got '{other}'"
            ))),
        }
    }

    /// Cast all columns with error handling.
    ///
    /// Matches `df.astype(dtype, errors='coerce'|'raise'|'ignore')`.
    pub fn astype_safe(&self, dtype: DType, errors: &str) -> Result<Self, FrameError> {
        let mapping: Vec<(&str, DType)> = self
            .column_order
            .iter()
            .map(|n| (n.as_str(), dtype))
            .collect();
        self.astype_columns_safe(&mapping, errors)
    }

    /// Remove a column by name, returning the modified DataFrame.
    ///
    /// Matches `df.drop(columns=['col'])`.
    pub fn drop_column(&self, name: &str) -> Result<Self, FrameError> {
        if !self.columns.contains_key(name) {
            return Err(FrameError::CompatibilityRejected(format!(
                "column '{name}' not found"
            )));
        }
        let mut columns = self.columns.clone();
        columns.remove(name);
        let column_order: Vec<String> = self
            .column_order
            .iter()
            .filter(|column| column.as_str() != name)
            .cloned()
            .collect();
        Self::new_with_column_order(self.index.clone(), columns, column_order)
    }

    /// Drop multiple columns at once.
    ///
    /// Matches `df.drop(columns=[...])`. Returns error if any column is missing.
    pub fn drop_columns(&self, names: &[&str]) -> Result<Self, FrameError> {
        for name in names {
            if !self.columns.contains_key(name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "column '{name}' not found"
                )));
            }
        }
        let drop_set: std::collections::HashSet<&str> = names.iter().copied().collect();
        let mut columns = self.columns.clone();
        for name in names {
            columns.remove(name);
        }
        let column_order: Vec<String> = self
            .column_order
            .iter()
            .filter(|c| !drop_set.contains(c.as_str()))
            .cloned()
            .collect();
        Self::new_with_column_order(self.index.clone(), columns, column_order)
    }

    /// Filter the DataFrame by column-label patterns.
    ///
    /// Matches `pd.DataFrame.filter(items=None, like=None, regex=None, axis=1)`
    /// (column-axis filter). Exactly one of `items`, `like`, or `regex` must
    /// be `Some`; the others must be `None`. Per br-frankenpandas-nk54a.
    ///
    /// - `items: Some(list)`: keep columns whose names appear in `list`,
    ///   in `list` order. Missing names are silently dropped (matches pandas).
    /// - `like: Some(substr)`: keep columns whose names contain `substr`.
    /// - `regex: Some(pattern)`: keep columns whose names match the regex.
    ///
    /// Use [`DataFrame::filter_axis`] with `axis=0` for row-index label
    /// matching.
    pub fn filter(
        &self,
        items: Option<&[&str]>,
        like: Option<&str>,
        regex: Option<&str>,
    ) -> Result<Self, FrameError> {
        self.filter_axis(items, like, regex, 1)
    }

    /// Filter rows or columns by label.
    ///
    /// Matches `pd.DataFrame.filter(items=None, like=None, regex=None, axis=...)`.
    /// - `axis=0`: filter rows by row-index label string form.
    /// - `axis=1`: filter columns by column label.
    ///
    /// Exactly one of `items`, `like`, or `regex` must be provided. `items`
    /// preserves the caller-provided item order and silently drops missing
    /// labels.
    pub fn filter_axis(
        &self,
        items: Option<&[&str]>,
        like: Option<&str>,
        regex: Option<&str>,
        axis: usize,
    ) -> Result<Self, FrameError> {
        let arg_count = [items.is_some(), like.is_some(), regex.is_some()]
            .iter()
            .filter(|x| **x)
            .count();
        if arg_count != 1 {
            return Err(FrameError::CompatibilityRejected(
                "filter: exactly one of items, like, regex must be Some".to_owned(),
            ));
        }
        if axis > 1 {
            return Err(FrameError::CompatibilityRejected(format!(
                "filter: axis must be 0 or 1, got {axis}"
            )));
        }

        if axis == 0 {
            let kept_positions = self.filter_row_positions_by_label(items, like, regex)?;
            return self.take_rows_by_positions(&kept_positions);
        }

        let kept_in_order: Vec<String> = if let Some(items) = items {
            let mut seen = HashSet::new();
            items
                .iter()
                .filter(|name| self.columns.contains_key(name) && seen.insert(*name))
                .map(|name| (*name).to_owned())
                .collect()
        } else if let Some(like) = like {
            self.column_order
                .iter()
                .filter(|name| name.contains(like))
                .cloned()
                .collect()
        } else {
            let pattern = regex.expect("regex Some checked above");
            let re = regex::Regex::new(pattern).map_err(|e| {
                FrameError::CompatibilityRejected(format!("filter: invalid regex: {e}"))
            })?;
            self.column_order
                .iter()
                .filter(|name| re.is_match(name))
                .cloned()
                .collect()
        };

        let kept_set: std::collections::HashSet<&str> =
            kept_in_order.iter().map(|s| s.as_str()).collect();
        let mut columns = BTreeMap::new();
        for name in &self.column_order {
            if kept_set.contains(name.as_str()) {
                let col = self.columns.get(name).expect("column in order must exist");
                columns.insert(name.clone(), col.clone());
            }
        }
        Self::new_with_column_order(self.index.clone(), columns, kept_in_order)
    }

    fn filter_row_positions_by_label(
        &self,
        items: Option<&[&str]>,
        like: Option<&str>,
        regex: Option<&str>,
    ) -> Result<Vec<usize>, FrameError> {
        if let Some(items) = items {
            if self.index.has_duplicates() {
                return Err(FrameError::CompatibilityRejected(
                    "filter: axis=0 items cannot reindex duplicate labels".to_owned(),
                ));
            }
            let positions_by_label: HashMap<String, usize> = self
                .index
                .labels()
                .iter()
                .enumerate()
                .map(|(position, label)| (label.to_string(), position))
                .collect();
            let mut seen = HashSet::new();
            return Ok(items
                .iter()
                .filter_map(|label| {
                    if !seen.insert(*label) {
                        return None;
                    }
                    positions_by_label.get(*label).copied()
                })
                .collect());
        }

        if let Some(like) = like {
            return Ok(self
                .index
                .labels()
                .iter()
                .enumerate()
                .filter_map(|(position, label)| {
                    label.to_string().contains(like).then_some(position)
                })
                .collect());
        }

        let pattern = regex.expect("regex Some checked above");
        let re = Regex::new(pattern)
            .map_err(|e| FrameError::CompatibilityRejected(format!("invalid regex: {e}")))?;
        Ok(self
            .index
            .labels()
            .iter()
            .enumerate()
            .filter_map(|(position, label)| re.is_match(&label.to_string()).then_some(position))
            .collect())
    }

    /// pandas-named column rename alias.
    ///
    /// Matches `df.rename(columns={'old': 'new'})` for mapping-style
    /// column renames.
    pub fn rename(&self, mapping: &[(&str, &str)]) -> Result<Self, FrameError> {
        self.rename_columns(mapping)
    }

    /// Rename columns using a mapping.
    ///
    /// Matches `df.rename(columns={'old': 'new'})`.
    pub fn rename_columns(&self, mapping: &[(&str, &str)]) -> Result<Self, FrameError> {
        let rename_map: BTreeMap<&str, &str> = mapping.iter().copied().collect();
        let mut columns = BTreeMap::new();
        let mut column_order = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            let name_str = name.as_str();
            let new_name = rename_map.get(name_str).unwrap_or(&name_str);

            if columns.contains_key(*new_name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "duplicate column '{}' resulting from rename",
                    new_name
                )));
            }

            column_order.push((*new_name).to_owned());
            columns.insert((*new_name).to_owned(), col.clone());
        }
        Self::new_with_column_order(self.index.clone(), columns, column_order)
    }

    /// Rename columns using a HashMap mapping.
    ///
    /// Convenience wrapper matching `df.rename(columns={...})` semantics.
    /// Only columns present in the mapping are renamed; others are kept as-is.
    pub fn rename_columns_map(
        &self,
        mapping: &std::collections::HashMap<String, String>,
    ) -> Result<Self, FrameError> {
        let pairs: Vec<(&str, &str)> = mapping
            .iter()
            .map(|(k, v)| (k.as_str(), v.as_str()))
            .collect();
        self.rename_columns(&pairs)
    }

    /// Rename columns using a mapper function.
    ///
    /// Matches `df.rename(columns=func)`. Applies the function to each column name.
    pub fn rename_with<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&str) -> String,
    {
        let mut columns = BTreeMap::new();
        let mut column_order = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let col = &self.columns[name];
            let new_name = func(name);
            if columns.contains_key(&new_name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "duplicate column '{new_name}' resulting from rename"
                )));
            }
            column_order.push(new_name.clone());
            columns.insert(new_name, col.clone());
        }
        Self::new_with_column_order(self.index.clone(), columns, column_order)
    }

    /// Rename index labels using a mapping.
    ///
    /// Matches `df.rename(index={...})`. Labels not in the mapping are
    /// left unchanged.
    pub fn rename_index(&self, mapping: &[(IndexLabel, IndexLabel)]) -> Self {
        let map: std::collections::HashMap<&IndexLabel, &IndexLabel> =
            mapping.iter().map(|(k, v)| (k, v)).collect();
        let new_labels: Vec<IndexLabel> = self
            .index
            .labels()
            .iter()
            .map(|lbl| match map.get(lbl) {
                Some(new) => (*new).clone(),
                None => lbl.clone(),
            })
            .collect();
        // Per br-frankenpandas-saitv: pandas preserves the index axis name
        // through rename(index=mapping). Sister to br-789xi (rename_index_with).
        Self {
            columns: self.columns.clone(),
            column_order: self.column_order.clone(),
            index: Index::new(new_labels).rename_index(self.index.name()),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        }
    }

    /// Rename index labels using a function.
    ///
    /// Matches `df.rename(index=func)`. Applies the function to each
    /// index label.
    pub fn rename_index_with<F>(&self, func: F) -> Self
    where
        F: Fn(&IndexLabel) -> IndexLabel,
    {
        let new_labels: Vec<IndexLabel> = self.index.labels().iter().map(func).collect();
        // Per br-frankenpandas-789xi: pandas preserves the index name through
        // label-transforming operations (rename_index, add_prefix_axis(0),
        // add_suffix_axis(0)). Was lost because Index::new(...) builds an
        // unnamed Index.
        Self {
            columns: self.columns.clone(),
            column_order: self.column_order.clone(),
            index: Index::new(new_labels).rename_index(self.index.name()),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        }
    }

    /// Rename the row index axis.
    ///
    /// Matches `pd.DataFrame.rename_axis(name)` for flat row indexes.
    pub fn rename_axis(&self, name: &str) -> Result<Self, FrameError> {
        if self.row_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "DataFrame.rename_axis: scalar name requires a flat row index".to_owned(),
            ));
        }

        Ok(Self {
            columns: self.columns.clone(),
            column_order: self.column_order.clone(),
            index: self.index.set_name(name),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Add a prefix to all column names.
    ///
    /// Matches `df.add_prefix(prefix)`.
    pub fn add_prefix(&self, prefix: &str) -> Result<Self, FrameError> {
        let p = prefix.to_owned();
        self.rename_with(|name| format!("{p}{name}"))
    }

    /// Add a suffix to all column names.
    ///
    /// Matches `df.add_suffix(suffix)`.
    pub fn add_suffix(&self, suffix: &str) -> Result<Self, FrameError> {
        let s = suffix.to_owned();
        self.rename_with(|name| format!("{name}{s}"))
    }

    /// Add a prefix to labels along the chosen axis.
    ///
    /// Matches `df.add_prefix(prefix, axis=...)`. `axis=0` prefixes the
    /// index (labels are stringified), `axis=1` prefixes column names.
    pub fn add_prefix_axis(&self, prefix: &str, axis: usize) -> Result<Self, FrameError> {
        match axis {
            0 => {
                let p = prefix.to_owned();
                Ok(self.rename_index_with(|label| IndexLabel::Utf8(format!("{p}{label}"))))
            }
            1 => self.add_prefix(prefix),
            other => Err(FrameError::CompatibilityRejected(format!(
                "axis must be 0 or 1, got {other}"
            ))),
        }
    }

    /// Add a suffix to labels along the chosen axis.
    ///
    /// Matches `df.add_suffix(suffix, axis=...)`. `axis=0` suffixes the
    /// index (labels are stringified), `axis=1` suffixes column names.
    pub fn add_suffix_axis(&self, suffix: &str, axis: usize) -> Result<Self, FrameError> {
        match axis {
            0 => {
                let s = suffix.to_owned();
                Ok(self.rename_index_with(|label| IndexLabel::Utf8(format!("{label}{s}"))))
            }
            1 => self.add_suffix(suffix),
            other => Err(FrameError::CompatibilityRejected(format!(
                "axis must be 0 or 1, got {other}"
            ))),
        }
    }

    /// Summary statistics for numeric columns.
    ///
    /// Matches `df.describe()` — returns a DataFrame with index
    /// `[count, mean, std, min, 25%, 50%, 75%, max]` and one column per
    /// numeric input column.
    pub fn describe(&self) -> Result<Self, FrameError> {
        let stat_labels = vec![
            IndexLabel::Utf8("count".to_owned()),
            IndexLabel::Utf8("mean".to_owned()),
            IndexLabel::Utf8("std".to_owned()),
            IndexLabel::Utf8("min".to_owned()),
            IndexLabel::Utf8("25%".to_owned()),
            IndexLabel::Utf8("50%".to_owned()),
            IndexLabel::Utf8("75%".to_owned()),
            IndexLabel::Utf8("max".to_owned()),
        ];
        let out_index = Index::new(stat_labels);

        // Column-parallel describe (br-frankenpandas-describe-par): each numeric
        // column's 8-stat column (count/mean/std/min/q25/q50/q75/max) is computed
        // INDEPENDENTLY — the per-column cost is the typed extraction + three
        // quantile_select passes + mean/var folds — so spreading columns across
        // the par_map_columns scope workers is bit-identical (identical per-column
        // arithmetic, results reassembled in column_order). The serial loop left
        // all but one core idle.
        let out_order: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Int64 | DType::Float64
                )
            })
            .cloned()
            .collect();

        let stat_columns = self.par_map_columns(&out_order, |name| {
            let col = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");

            // Typed Float64 extraction (br-frankenpandas-c6yf1): collect present
            // values straight from the f64 + validity slices (validity set AND
            // datum not NaN == the prior `!is_missing && to_f64.is_ok()` filter),
            // in index order so the sum/mean/var folds are byte-identical.
            let mut nums: Vec<f64> = Vec::new();
            if let Some((data, validity)) = col.as_f64_slice_with_validity() {
                for (i, &v) in data.iter().enumerate() {
                    if validity.get(i) && !v.is_nan() {
                        nums.push(v);
                    }
                }
            } else if let Some(data) = col.as_i64_slice() {
                // Typed all-valid Int64 (sister to quantile's arm): every value is
                // present and `v as f64 == to_f64(Int64(v))`, so `nums` == the generic
                // collect below — same count/mean/var folds + quantile_select passes.
                nums.extend(data.iter().map(|&v| v as f64));
            } else if let Some((data, validity)) = col.as_i64_slice_with_validity() {
                // Nullable Int64: collect present values (`validity.get` == the generic
                // `!is_missing` filter for an Int64 cell; Int64 is never NaN).
                for (i, &v) in data.iter().enumerate() {
                    if validity.get(i) {
                        nums.push(v as f64);
                    }
                }
            } else {
                for val in col.values() {
                    if !val.is_missing()
                        && let Ok(v) = val.to_f64()
                    {
                        nums.push(v);
                    }
                }
            }

            let count = nums.len() as f64;
            let (mean, std, min, q25, q50, q75, max) = if nums.is_empty() {
                (
                    f64::NAN,
                    f64::NAN,
                    f64::NAN,
                    f64::NAN,
                    f64::NAN,
                    f64::NAN,
                    f64::NAN,
                )
            } else {
                let sum: f64 = nums.iter().sum();
                let mean_val = sum / count;
                let var = if nums.len() > 1 {
                    nums.iter().map(|x| (x - mean_val).powi(2)).sum::<f64>() / (count - 1.0)
                } else {
                    f64::NAN
                };
                // Order statistics via O(n) selection instead of a full O(n log n)
                // sort: min/max are folds and the three percentiles reuse
                // quantile_select. -0.0/0.0 ties (equal under partial_cmp but
                // bit-distinct) could pick a different signed zero than a stable
                // sort, so any negative zero routes to the exact sort +
                // percentile_linear path (matching min/max from sorted[0]/[n-1]).
                let (min_val, q25_val, q50_val, q75_val, max_val) =
                    if nums.iter().any(|&v| v == 0.0 && v.is_sign_negative()) {
                        nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                        (
                            nums[0],
                            Self::percentile_linear(&nums, 0.25),
                            Self::percentile_linear(&nums, 0.50),
                            Self::percentile_linear(&nums, 0.75),
                            nums[nums.len() - 1],
                        )
                    } else {
                        let min_val = nums
                            .iter()
                            .copied()
                            .fold(f64::INFINITY, |a, b| if b < a { b } else { a });
                        let max_val = nums
                            .iter()
                            .copied()
                            .fold(f64::NEG_INFINITY, |a, b| if b > a { b } else { a });
                        let q25_val = Self::quantile_select(&mut nums, 0.25);
                        let q50_val = Self::quantile_select(&mut nums, 0.50);
                        let q75_val = Self::quantile_select(&mut nums, 0.75);
                        (min_val, q25_val, q50_val, q75_val, max_val)
                    };
                (
                    mean_val,
                    var.sqrt(),
                    min_val,
                    q25_val,
                    q50_val,
                    q75_val,
                    max_val,
                )
            };

            let stats = vec![
                Scalar::Float64(count),
                Scalar::Float64(mean),
                Scalar::Float64(std),
                Scalar::Float64(min),
                Scalar::Float64(q25),
                Scalar::Float64(q50),
                Scalar::Float64(q75),
                Scalar::Float64(max),
            ];

            Ok(Column::from_values(stats)?)
        })?;

        let mut out_columns = BTreeMap::new();
        for (name, column) in out_order.iter().zip(stat_columns) {
            out_columns.insert(name.clone(), column);
        }

        Self::new_with_column_order(out_index, out_columns, out_order)
    }

    /// Describe with custom percentiles.
    ///
    /// Matches `pd.DataFrame.describe(percentiles=[...])`.
    pub fn describe_with_percentiles(&self, percentiles: &[f64]) -> Result<Self, FrameError> {
        let percentiles = normalize_describe_percentiles(percentiles)?;
        let mut stat_labels = vec![
            IndexLabel::Utf8("count".to_owned()),
            IndexLabel::Utf8("mean".to_owned()),
            IndexLabel::Utf8("std".to_owned()),
            IndexLabel::Utf8("min".to_owned()),
        ];
        for &p in &percentiles {
            stat_labels.push(IndexLabel::Utf8(describe_percentile_label(p)));
        }
        stat_labels.push(IndexLabel::Utf8("max".to_owned()));
        let out_index = Index::new(stat_labels);
        let num_stats = 4 + percentiles.len() + 1; // count, mean, std, min, percentiles..., max

        // Column-parallel describe (br-frankenpandas-describe-par): each numeric
        // column's stats column (count/mean/std/min/percentiles/max, dominated by
        // the per-column f64 SORT for the percentiles) is computed INDEPENDENTLY,
        // so spreading columns across the par_map_columns scope workers is
        // bit-identical — every column runs the identical extraction + sort +
        // percentile_linear and the result columns are reassembled in
        // column_order. The serial loop left all but one core idle.
        let out_order: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Int64 | DType::Float64
                )
            })
            .cloned()
            .collect();

        let stat_columns = self.par_map_columns(&out_order, |name| {
            let col = &self.columns[name];
            let mut nums: Vec<f64> = col
                .values()
                .iter()
                .filter_map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect();

            let mut stats = Vec::with_capacity(num_stats);
            let count = nums.len() as f64;

            if nums.is_empty() {
                for _ in 0..num_stats {
                    stats.push(Scalar::Float64(f64::NAN));
                }
            } else {
                let sum: f64 = nums.iter().sum();
                let mean = sum / count;
                let var = if nums.len() > 1 {
                    nums.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / (count - 1.0)
                } else {
                    f64::NAN
                };
                nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

                stats.push(Scalar::Float64(count));
                stats.push(Scalar::Float64(mean));
                stats.push(Scalar::Float64(var.sqrt()));
                stats.push(Scalar::Float64(nums[0]));
                for &p in &percentiles {
                    stats.push(Scalar::Float64(Self::percentile_linear(&nums, p)));
                }
                stats.push(Scalar::Float64(nums[nums.len() - 1]));
            }

            Ok(Column::from_values(stats)?)
        })?;

        let mut out_columns = BTreeMap::new();
        for (name, column) in out_order.iter().zip(stat_columns) {
            out_columns.insert(name.clone(), column);
        }

        Self::new_with_column_order(out_index, out_columns, out_order)
    }

    /// Describe with include/exclude dtype filters.
    ///
    /// Matches `df.describe(include=[...], exclude=[...])`. Pass empty
    /// slices to use defaults (numeric only). Supported dtype strings:
    /// "int64", "float64", "bool", "object"/"string".
    pub fn describe_dtypes(&self, include: &[&str], exclude: &[&str]) -> Result<Self, FrameError> {
        let dtype_matches = |dt: DType, filter: &str| -> bool {
            match filter {
                "int64" | "int" => dt == DType::Int64,
                "float64" | "float" => dt == DType::Float64,
                "bool" | "boolean" => dt == DType::Bool,
                "object" | "string" | "str" => dt == DType::Utf8,
                "category" | "categorical" => dt == DType::Categorical,
                "number" | "numeric" => matches!(dt, DType::Int64 | DType::Float64),
                "all" => true,
                _ => false,
            }
        };

        let should_include = |dt: DType| -> bool {
            let inc = if include.is_empty() {
                matches!(dt, DType::Int64 | DType::Float64)
            } else {
                include.iter().any(|f| dtype_matches(dt, f))
            };
            let exc = if exclude.is_empty() {
                false
            } else {
                exclude.iter().any(|f| dtype_matches(dt, f))
            };
            inc && !exc
        };

        // For non-numeric types, describe shows count, unique, top, freq
        let has_non_numeric = self.column_order.iter().any(|name| {
            let dt = self.columns[name].dtype();
            should_include(dt) && !matches!(dt, DType::Int64 | DType::Float64)
        });

        if has_non_numeric {
            // Object-style describe: count, unique, top, freq
            let stat_labels = vec![
                IndexLabel::Utf8("count".into()),
                IndexLabel::Utf8("unique".into()),
                IndexLabel::Utf8("top".into()),
                IndexLabel::Utf8("freq".into()),
            ];
            let out_index = Index::new(stat_labels);
            let mut out_columns = BTreeMap::new();
            let mut out_order = Vec::new();

            for name in &self.column_order {
                let col = &self.columns[name];
                if !should_include(col.dtype()) {
                    continue;
                }
                let vals = col.values();
                let count = vals.iter().filter(|v| !v.is_missing()).count();
                let mut freq_map: HashMap<ScalarKey<'_>, (Scalar, usize)> = HashMap::new();
                for v in vals {
                    if let Some(key) = scalar_key_skip_missing(v) {
                        freq_map
                            .entry(key)
                            .and_modify(|(_, c)| *c += 1)
                            .or_insert_with(|| (v.clone(), 1));
                    }
                }
                let unique = freq_map.len();
                let (top, freq) = freq_map
                    .values()
                    .max_by_key(|(_, c)| *c)
                    .map(|(v, c)| {
                        let label = scalar_to_value_counts_index_label(v);
                        let rendered = match label {
                            IndexLabel::Int64(n) => n.to_string(),
                            IndexLabel::Utf8(s) => s,
                            IndexLabel::Timedelta64(ns) => Timedelta::format(ns),
                            IndexLabel::Datetime64(ns) => format_datetime_ns(ns),
                            f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                            null @ IndexLabel::Null(_) => null.to_string(),
                        };
                        (rendered, *c)
                    })
                    .unwrap_or_default();

                let stats = vec![
                    Scalar::Utf8(count.to_string()),
                    Scalar::Utf8(unique.to_string()),
                    Scalar::Utf8(top),
                    Scalar::Utf8(freq.to_string()),
                ];
                out_columns.insert(name.clone(), Column::from_values(stats)?);
                out_order.push(name.clone());
            }
            return Self::new_with_column_order(out_index, out_columns, out_order);
        }

        // Numeric describe: filter to included columns, then delegate
        let selected = self.select_columns(
            &self
                .column_order
                .iter()
                .filter(|name| should_include(self.columns[*name].dtype()))
                .map(|s| s.as_str())
                .collect::<Vec<_>>(),
        )?;
        selected.describe()
    }

    /// Compute quantile(s) for each numeric column.
    ///
    /// Matches `df.quantile(q)` for a single quantile value.
    /// Returns a Series indexed by column names.
    pub fn quantile(&self, q: f64) -> Result<Series, FrameError> {
        if !(0.0..=1.0).contains(&q) {
            return Err(FrameError::CompatibilityRejected(format!(
                "quantile must be between 0 and 1, got {q}"
            )));
        }
        // Column-parallel (br-frankenpandas-quantile-par): each numeric column's
        // quantile (typed extraction + O(n) quantile_select) is independent, so
        // spread the columns across par_map_columns scope workers. Bit-identical —
        // identical per-column extraction/select, reassembled in column_order.
        let allowed: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Int64 | DType::Float64
                )
            })
            .cloned()
            .collect();
        let values = self.par_map_columns(&allowed, |name| {
            let col = &self.columns[name];
            // Typed Float64 fast path (br-frankenpandas-zjc5z): collect the
            // present values straight from the f64 + validity slices, skipping the
            // col.values() Vec<Scalar> materialization + per-element to_f64. A
            // value is collected iff its materialized Scalar is Float64(finite) —
            // validity set AND datum not NaN (Float64(NaN)/Null are missing),
            // exactly the `!is_missing && to_f64.is_ok()` filter — so `nums` is
            // identical and the downstream sort + percentile_linear are unchanged.
            let mut nums: Vec<f64> = Vec::new();
            if let Some((data, validity)) = col.as_f64_slice_with_validity() {
                for (i, &v) in data.iter().enumerate() {
                    if validity.get(i) && !v.is_nan() {
                        nums.push(v);
                    }
                }
            } else if let Some(data) = col.as_i64_slice() {
                // Typed all-valid Int64 (sister to the Float64 arm): every value is
                // present and `v as f64 == to_f64(Int64(v))`, so `nums` == the generic
                // collect below — same sort + percentile_linear, Float64 output.
                nums.extend(data.iter().map(|&v| v as f64));
            } else if let Some((data, validity)) = col.as_i64_slice_with_validity() {
                // Nullable Int64: collect present values (`validity.get` == the generic
                // `!is_missing` filter for an Int64 cell; Int64 is never NaN).
                for (i, &v) in data.iter().enumerate() {
                    if validity.get(i) {
                        nums.push(v as f64);
                    }
                }
            } else {
                for val in col.values() {
                    if !val.is_missing()
                        && let Ok(v) = val.to_f64()
                    {
                        nums.push(v);
                    }
                }
            }
            Ok(if nums.is_empty() {
                Scalar::Float64(f64::NAN)
            } else {
                Scalar::Float64(Self::quantile_select(&mut nums, q))
            })
        })?;
        let labels: Vec<IndexLabel> = allowed
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        Series::from_values(format!("{q}"), labels, values)
    }

    /// Apply an aggregation function along an axis.
    ///
    /// `axis=0` (default): apply function to each column, returning a Series
    /// indexed by column names.
    /// `axis=1`: apply function to each row, returning a Series indexed by
    /// the original DataFrame index.
    ///
    /// Matches `df.apply(func, axis=...)` for built-in aggregations.
    fn apply_named(&self, func: &str, axis: usize) -> Result<Series, FrameError> {
        if func == "nunique" {
            return self.nunique_axis(axis);
        }
        if axis == 0 {
            // Column-wise: aggregate each column
            let mut labels = Vec::new();
            let mut values = Vec::new();
            for name in &self.column_order {
                let col = self
                    .columns
                    .get(name)
                    .expect("column name listed in order must exist");
                labels.push(IndexLabel::Utf8(name.clone()));
                let s = Series::new(name.clone(), self.index.clone(), col.clone())?;
                let agg = match func {
                    "sum" => s.sum()?,
                    "mean" => s.mean()?,
                    "min" => s.min()?,
                    "max" => s.max()?,
                    "std" => s.std()?,
                    "var" => s.var()?,
                    "median" => s.median()?,
                    "count" => Scalar::Int64(s.count() as i64),
                    "sem" => Scalar::Float64(s.sem().unwrap_or(f64::NAN)),
                    "skew" => Scalar::Float64(s.skew()?),
                    "kurt" | "kurtosis" => Scalar::Float64(s.kurt()?),
                    "prod" | "product" => s.prod()?,
                    // br-frankenpandas-groupby-idxmax-idxmin, seventh surface.
                    // pandas' df.apply(str) accepts 22 names; this accepted 14.
                    // Every one added here is an existing Series method, reached
                    // through the per-column Series this loop already builds.
                    //
                    // MEASURED, live pandas 2.2.3: df.apply(name) works for all,
                    // any, cumsum, idxmax, idxmin, nunique, quantile, rank and size
                    // on a numeric frame. The seven below are the REDUCTION-shaped
                    // ones — a scalar per column, which is what this match yields.
                    // `cumsum` and `rank` return a DataFrame (one row per input row)
                    // and cannot be expressed here, exactly as on the groupby
                    // surfaces.
                    //
                    // `quantile` carries no q through the string form, so it is
                    // pandas' default 0.5 — verified on the pivot surface in the
                    // same commit that aggfunc='quantile' equals aggfunc='median'.
                    "any" => Scalar::Bool(s.any()?),
                    "all" => Scalar::Bool(s.all()?),
                    "nunique" => Scalar::Int64(s.nunique() as i64),
                    "size" => Scalar::Int64(s.len() as i64),
                    "quantile" => s.quantile(0.5)?,
                    "idxmax" => index_label_to_scalar(&s.idxmax()?),
                    "idxmin" => index_label_to_scalar(&s.idxmin()?),
                    other => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "unsupported apply function: '{other}'"
                        )));
                    }
                };
                values.push(agg);
            }
            Series::from_values(func, labels, values)
        } else if axis == 1 {
            // Row-wise: aggregate each row across columns
            let mut values = Vec::with_capacity(self.len());
            for row_idx in 0..self.len() {
                let row_vals: Vec<f64> = self
                    .column_order
                    .iter()
                    .filter_map(|name| {
                        let col = self.columns.get(name)?;
                        let val = &col.values()[row_idx];
                        if val.is_missing() {
                            None
                        } else {
                            val.to_f64().ok()
                        }
                    })
                    .collect();
                let sample_median = |vals: &[f64]| -> f64 {
                    if vals.is_empty() {
                        return f64::NAN;
                    }
                    let mut sorted = vals.to_vec();
                    sorted.sort_unstable_by(|a, b| {
                        a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
                    });
                    let mid = sorted.len() / 2;
                    if sorted.len().is_multiple_of(2) {
                        (sorted[mid - 1] + sorted[mid]) / 2.0
                    } else {
                        sorted[mid]
                    }
                };
                let result = match func {
                    "sum" => Scalar::Float64(row_vals.iter().sum::<f64>()),
                    "mean" => Scalar::Float64(if row_vals.is_empty() {
                        f64::NAN
                    } else {
                        row_vals.iter().sum::<f64>() / row_vals.len() as f64
                    }),
                    "min" => Scalar::Float64(
                        row_vals
                            .iter()
                            .copied()
                            .reduce(f64::min)
                            .unwrap_or(f64::NAN),
                    ),
                    "max" => Scalar::Float64(
                        row_vals
                            .iter()
                            .copied()
                            .reduce(f64::max)
                            .unwrap_or(f64::NAN),
                    ),
                    "count" => Scalar::Int64(row_vals.len() as i64),
                    "median" => Scalar::Float64(sample_median(&row_vals)),
                    "prod" | "product" => Scalar::Float64(row_vals.iter().product::<f64>()),
                    "var" => Scalar::Float64(Self::row_sample_var(&row_vals)),
                    "std" => Scalar::Float64(Self::row_sample_var(&row_vals).sqrt()),
                    "sem" => Scalar::Float64(Self::row_sem(&row_vals)),
                    "skew" => Scalar::Float64(Self::row_skew(&row_vals)),
                    "kurt" | "kurtosis" => Scalar::Float64(Self::row_kurtosis(&row_vals)),
                    // br-frankenpandas-groupby-idxmax-idxmin, axis=1 half.
                    // pandas accepts these row-wise too; only the axis=0 arm had
                    // them, and an earlier attempt to copy the arms across
                    // failed to compile because it reached for `s`, the
                    // per-column Series the axis=0 loop builds and this loop has
                    // no equivalent of.
                    //
                    // ⚠️ MISSING VALUES ARE EXCLUDED FROM EVERY ONE OF THESE
                    // EXCEPT `size`, which counts the COLUMNS. `row_vals` has
                    // already dropped them, so it is the right input for four of
                    // the five and the wrong input for the other two.
                    // MEASURED, live pandas 2.2.3, one case per rule:
                    //
                    //   {a:[1.0,2.0], b:[3.0,NaN]}
                    //     any     [True, True]      all      [True, True]
                    //     size    [2, 2]            quantile [2.0, 2.0]
                    //     idxmax  ['b', 'a']        idxmin   ['a', 'a']
                    //   {a:[0.0], b:[0.0]}    any [False]  all [False]
                    //   {a:[0.0], b:[1.0]}    any [True]   all [False]
                    //   {a:[NaN], b:[NaN]}    any [False]  all [True]   <- VACUOUS
                    //                         quantile [nan]  idxmax [nan]
                    //   {a:[5.0], b:[5.0]}    idxmax ['a']  idxmin ['a'] <- FIRST wins
                    //   {a:[NaN], b:[2.0]}    idxmin ['b']  <- a missing cell is
                    //                                          not a candidate
                    //
                    // An all-missing row is the case that separates them: `any`
                    // is false and `all` is TRUE there, which is exactly Rust's
                    // empty-iterator behaviour, so both fall out of `row_vals`
                    // without a special case.
                    "any" => Scalar::Bool(row_vals.iter().any(|value| *value != 0.0)),
                    "all" => Scalar::Bool(row_vals.iter().all(|value| *value != 0.0)),
                    // The COLUMN COUNT, missing cells included — the one name
                    // here that must not look at `row_vals`.
                    "size" => Scalar::Int64(self.column_order.len() as i64),
                    // The string form carries no q, so it is pandas' default 0.5.
                    //
                    // ⚠️ NOT `sample_median`, even though q=0.5 makes them agree
                    // to within an ulp on every input. They are DIFFERENT
                    // ALGORITHMS: the median averages the two middle values
                    // `(a+b)/2`, while the quantile interpolates
                    // `lo + (hi - lo) * weight`. MEASURED, live pandas 2.2.3, on
                    // the row {a: -1.356, b: 6.844}:
                    //
                    // ```text
                    // df.apply('median',   axis=1) -> 2.744
                    // df.apply('quantile', axis=1) -> 2.7439999999999998
                    // ```
                    //
                    // so routing quantile through the median would be a silently
                    // wrong LAST BIT. `group_nanquantile_f64` is the crate's own
                    // interpolating quantile, bit-identical to
                    // `fp_types::nanquantile`'s numeric arm — which is what the
                    // axis=0 arm reaches through `s.quantile(0.5)`. Using it here
                    // makes the two axes agree with each other by construction.
                    //
                    // (FP's interpolation still differs from pandas' in the last
                    // ulp — pandas reproduces neither `(a+b)/2` nor
                    // `lo + (hi-lo)*w` exactly. That is a pre-existing,
                    // crate-wide property of nanquantile and not something to
                    // fork per call site; noted here so the next reader does not
                    // "fix" it by switching formulas on one arm.)
                    "quantile" => {
                        if row_vals.is_empty() {
                            // group_nanquantile_f64 selects an order statistic
                            // and would panic on an empty slice; pandas returns
                            // NaN for an all-missing row.
                            Scalar::Float64(f64::NAN)
                        } else {
                            let mut sorted = row_vals.clone();
                            Scalar::Float64(group_nanquantile_f64(&mut sorted, 0.5))
                        }
                    }
                    "idxmax" | "idxmin" => {
                        let want_max = func == "idxmax";
                        // Walk the row WITH its labels. Strict `>` / `<` keeps
                        // the FIRST column on a tie, matching pandas.
                        let mut best: Option<(&String, f64)> = None;
                        for name in &self.column_order {
                            let Some(col) = self.columns.get(name) else {
                                continue;
                            };
                            let value = &col.values()[row_idx];
                            if value.is_missing() {
                                continue;
                            }
                            let Ok(value) = value.to_f64() else {
                                continue;
                            };
                            let better = match best {
                                None => true,
                                Some((_, current)) => {
                                    if want_max {
                                        value > current
                                    } else {
                                        value < current
                                    }
                                }
                            };
                            if better {
                                best = Some((name, value));
                            }
                        }
                        match best {
                            Some((name, _)) => Scalar::Utf8(name.clone()),
                            // An all-missing row has no argmax to name; pandas
                            // returns NaN rather than raising.
                            None => Scalar::Null(NullKind::NaN),
                        }
                    }
                    // `nunique` never reaches here: apply_named short-circuits it
                    // to `nunique_axis(axis)` before either dispatch, which
                    // already handles both axes.
                    //
                    // `cumsum` and `rank` are the two names pandas accepts that
                    // this match still cannot express — they return one row per
                    // input row, not a scalar per row, exactly as on the axis=0
                    // arm and the groupby surfaces.
                    other => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "unsupported apply function: '{other}'"
                        )));
                    }
                };
                values.push(result);
            }
            // Per br-frankenpandas-8y2ns: pandas df.apply(func, axis=1)
            // preserves df.index.name on the row-wise result.
            let index = self.index.clone();
            let column = Column::from_values(values)?;
            Series::new(func, index, column)
        } else {
            Err(FrameError::CompatibilityRejected(format!(
                "axis must be 0 or 1, got {axis}"
            )))
        }
    }

    /// Apply either a built-in reducer name or a user closure along an axis.
    ///
    /// - `df.apply("sum", 0)` returns a `Series`.
    /// - `df.apply(|vals| ..., 1)` returns a single-column `DataFrame`.
    pub fn apply<A>(&self, func: A, axis: usize) -> Result<A::Output, FrameError>
    where
        A: DataFrameApplyArg,
    {
        func.execute(self, axis)
    }

    /// Transpose the DataFrame: rows become columns, columns become rows.
    ///
    /// Matches `df.T` / `df.transpose()`. Column names become the index
    /// of the result, and the original index labels become column names
    /// (converted to strings).
    #[cfg(feature = "lazy-transpose-view")]
    pub fn transpose_view(&self) -> Result<Option<DataFrameTransposeView<'_>>, FrameError> {
        if self.index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "transpose requires unique index labels: the source index \
                 contains duplicates and would silently collapse columns \
                 in the transposed DataFrame (column store keys must be \
                 unique). Deduplicate the index before transposing."
                    .to_owned(),
            ));
        }

        let Some((column_start, column_len)) = self.index.int64_unit_range_labels() else {
            return Ok(None);
        };
        if column_len != self.len()
            || self.row_multiindex.is_some()
            || self.column_multiindex.is_some()
        {
            return Ok(None);
        }

        if self.column_order.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Float64(Vec::new()),
                row_index: Index::from_utf8(Vec::new()),
                column_start,
                column_len,
            }));
        }

        let mut f64_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some(values) = column.as_f64_slice() else {
                f64_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            f64_columns.push(values);
        }
        if !f64_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Float64(f64_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        let mut i64_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some(values) = column.as_i64_slice() else {
                i64_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            i64_columns.push(values);
        }
        if !i64_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Int64(i64_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        let mut datetime_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            // `as_datetime64_slice()` may expose a cached raw nanos buffer for
            // a nullable eager column.  The view currently carries no validity
            // masks, so admitting that shape would turn NaT into a present raw
            // value when reading or materializing the transposed column.
            if !column.validity().all() {
                datetime_columns.clear();
                break;
            }
            let Some(values) = column.as_datetime64_slice() else {
                datetime_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            datetime_columns.push(values);
        }
        if !datetime_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Datetime64(datetime_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        let mut timedelta_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            // Timedelta64 has the same cached-data/validity split as
            // Datetime64.  Keep nullable inputs on the eager fallback until a
            // future view representation carries per-source validity masks.
            if !column.validity().all() {
                timedelta_columns.clear();
                break;
            }
            let Some(values) = column.as_timedelta64_slice() else {
                timedelta_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            timedelta_columns.push(values);
        }
        if !timedelta_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Timedelta64(timedelta_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        let mut bool_columns = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some(values) = column.as_bool_slice() else {
                bool_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            bool_columns.push(values);
        }
        if !bool_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Bool(bool_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        // All-valid contiguous-Utf8 sources: the eager fallback clones one
        // `String` + `Scalar` per cell into a `from_values` re-inference; the
        // lazy view carries the `(bytes, offsets)` span pairs and builds each
        // output column as contiguous-Utf8 directly. Eager-Utf8 sources
        // (plain `from_values` construction) have no contiguous view and keep
        // the eager fallback.
        let mut utf8_columns: Vec<(&[u8], &[usize])> = Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some((bytes, offsets)) = column.as_utf8_contiguous() else {
                utf8_columns.clear();
                break;
            };
            if !column.validity().all() {
                return Ok(None);
            }
            if offsets.len().saturating_sub(1) != self.len() {
                return Ok(None);
            }
            utf8_columns.push((bytes, offsets));
        }
        if !utf8_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::Utf8(utf8_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        // Nullable (or mixed-validity) Int64 sources: Int64 missing is
        // single-valued (`Null(Null)`), so `(values, validity)` pairs fully
        // reproduce the eager Scalars. All-valid Int64 frames never reach
        // here (the dedicated arm above returns first), so this arm serves
        // frames where at least one Int64 column carries nulls.
        let mut nullable_i64_columns: Vec<(&[i64], &ValidityMask)> =
            Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some((values, validity)) = column.as_i64_slice_with_validity() else {
                nullable_i64_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            nullable_i64_columns.push((values, validity));
        }
        if !nullable_i64_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::NullableInt64(nullable_i64_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        // CANONICAL nullable Float64 sources: LazyNullableFloat64-backed
        // columns only, where the Scalar emission is fully determined by
        // `(data, validity)`. Eager nullable Float64 (mixed NullKinds) and
        // mixed-validity frames stay on the eager fallback.
        let mut nullable_f64_columns: Vec<(&[f64], &ValidityMask)> =
            Vec::with_capacity(self.column_order.len());
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            let Some((values, validity)) = column.as_canonical_nullable_f64() else {
                nullable_f64_columns.clear();
                break;
            };
            if values.len() != self.len() {
                return Ok(None);
            }
            nullable_f64_columns.push((values, validity));
        }
        if !nullable_f64_columns.is_empty() {
            return Ok(Some(DataFrameTransposeView {
                source_columns: HomogeneousTransposeColumns::NullableFloat64(nullable_f64_columns),
                row_index: Index::from_utf8(self.column_order.to_vec()),
                column_start,
                column_len,
            }));
        }

        // Mixed all-valid Int64/Float64 sources: the eager fallback promotes
        // this shape to Float64 output columns via `from_values` dtype
        // inference, so a lazy view can carry the typed source slices and
        // cast Int64 cells at materialization time. Only all-valid sources
        // are admitted: `as_i64_slice` can expose a cached raw buffer for a
        // nullable eager column (the same hazard the Datetime64 arm guards),
        // and nullable Float64 mixes have a non-single-valued missing
        // representation.
        let mut numeric_sources = Vec::with_capacity(self.column_order.len());
        let mut has_f64 = false;
        let mut has_i64 = false;
        for name in &self.column_order {
            let Some(column) = self.columns.get(name) else {
                return Ok(None);
            };
            if !column.validity().all() {
                return Ok(None);
            }
            if let Some(values) = column.as_f64_slice() {
                if values.len() != self.len() {
                    return Ok(None);
                }
                has_f64 = true;
                numeric_sources.push(NumericTransposeSource::F64(values));
            } else if let Some(values) = column.as_i64_slice() {
                if values.len() != self.len() {
                    return Ok(None);
                }
                has_i64 = true;
                numeric_sources.push(NumericTransposeSource::I64(values));
            } else {
                return Ok(None);
            }
        }
        if !(has_f64 && has_i64) {
            // Pure shapes are owned by the dedicated arms above; reaching
            // here pure means some typed view was unavailable, so the eager
            // fallback stays authoritative.
            return Ok(None);
        }

        Ok(Some(DataFrameTransposeView {
            source_columns: HomogeneousTransposeColumns::PromotedFloat64(numeric_sources),
            row_index: Index::from_utf8(self.column_order.to_vec()),
            column_start,
            column_len,
        }))
    }

    pub fn transpose(&self) -> Result<Self, FrameError> {
        #[cfg(feature = "lazy-transpose-view")]
        if !self.column_order.is_empty()
            && let Some(view) = self.transpose_view()?
        {
            let source_columns: Arc<[Column]> = self
                .column_order
                .iter()
                .map(|name| {
                    self.columns
                        .get(name)
                        .expect("column name listed in order must exist")
                        .clone()
                })
                .collect::<Vec<_>>()
                .into();
            let plan = Arc::new(LazyTransposeFramePlan {
                source_columns,
                dtype: view.dtype(),
                output_columns: view.column_len,
                column_slot_pages: LazyTransposeFramePlan::empty_column_slot_pages(view.column_len),
            });
            return Ok(Self {
                index: view.row_index.clone(),
                row_multiindex: None,
                columns: LazyDataFrameColumns::homogeneous_transpose(
                    Arc::clone(&plan),
                    view.column_start,
                ),
                column_order: LazyDataFrameColumnOrder::int64_unit_range(
                    view.column_start,
                    view.column_len,
                ),
                column_multiindex: None,
                allows_duplicate_labels: true,
            });
        }

        self.transpose_materialized()
    }

    fn transpose_materialized(&self) -> Result<Self, FrameError> {
        // Per br-frankenpandas-3eaa5: DataFrame's column store is
        // BTreeMap<String, Column> and cannot hold duplicate column names.
        // If the source index has duplicate labels (e.g. [10, 10, 20]),
        // transpose would silently collapse them via BTreeMap::insert
        // (last-write-wins) and lose data. Detect that case up front and
        // return a clear error rather than silently dropping rows.
        if self.index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "transpose requires unique index labels: the source index \
                 contains duplicates and would silently collapse columns \
                 in the transposed DataFrame (column store keys must be \
                 unique). Deduplicate the index before transposing."
                    .to_owned(),
            ));
        }

        let n_rows = self.len();
        let n_cols = self.num_columns();

        // New index: original column names
        let new_index_labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        let new_index = Index::new(new_index_labels);

        // New columns: one per original row, named by index label.
        let mut new_columns = BTreeMap::new();
        let mut new_order = Vec::with_capacity(n_rows);

        // Hoist the source labels and per-column references OUT of the row loop.
        // The old code re-fetched `self.columns.get(name)` (a BTreeMap lookup) on
        // every (row, col) cell — n_rows * n_cols string-keyed lookups — and
        // built every transposed column through the `Scalar` path. For a tall
        // frame that is the difference between ~1.5s and ~tens of ms.
        let label_to_name = |label: &IndexLabel| -> String {
            match label {
                IndexLabel::Int64(v) => v.to_string(),
                IndexLabel::Utf8(v) => v.clone(),
                IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                null @ IndexLabel::Null(_) => null.to_string(),
            }
        };
        let src_cols: Vec<&Column> = self
            .column_order
            .iter()
            .map(|name| {
                self.columns
                    .get(name)
                    .expect("column name listed in order must exist")
            })
            .collect();

        // Shared-row-plan Float64 fast path: for Arc-backed all-valid Float64
        // sources, every transposed output column is a lazy view of one source
        // row across the original columns. This avoids allocating/copying a
        // tiny f64 buffer per source row while preserving the exact column-order
        // materialization used by the eager path below.
        let f64_arc_sources: Option<Vec<_>> = src_cols
            .iter()
            .map(|c| c.as_f64_arc_view_source())
            .collect();
        if let Some(f64_arc_sources) = f64_arc_sources {
            let row_plan = Column::f64_transpose_rows_plan(f64_arc_sources, n_rows);

            if let Some((start, len)) = self.index.int64_unit_range_labels() {
                debug_assert_eq!(len, n_rows);
                if start == 0 {
                    // BTreeMap bulk-builds from sorted keys; keep public order
                    // numeric while feeding the map lexicographic key order.
                    fn push_lexical_transpose_row_entry(
                        entries: &mut Vec<(String, Column)>,
                        names: &[String],
                        row_plan: &fp_columnar::Float64TransposeRows,
                        row_idx: usize,
                        len: usize,
                    ) {
                        if row_idx >= len {
                            return;
                        }
                        entries.push((
                            names[row_idx].clone(),
                            Column::from_f64_transpose_row(row_plan, row_idx),
                        ));
                        let Some(base) = row_idx.checked_mul(10) else {
                            return;
                        };
                        for digit in 0..=9 {
                            let Some(child) = base.checked_add(digit) else {
                                break;
                            };
                            if child >= len {
                                break;
                            }
                            push_lexical_transpose_row_entry(entries, names, row_plan, child, len);
                        }
                    }

                    new_order = (0..n_rows).map(|row_idx| row_idx.to_string()).collect();
                    let mut column_entries = Vec::with_capacity(n_rows);
                    if n_rows > 0 {
                        column_entries.push((
                            new_order[0].clone(),
                            Column::from_f64_transpose_row(&row_plan, 0),
                        ));
                        for first_digit in 1..=9 {
                            push_lexical_transpose_row_entry(
                                &mut column_entries,
                                &new_order,
                                &row_plan,
                                first_digit,
                                n_rows,
                            );
                        }
                    }
                    debug_assert_eq!(column_entries.len(), n_rows);
                    let new_columns: BTreeMap<String, Column> =
                        column_entries.into_iter().collect();
                    return Ok(Self::new_with_axes_trusted(
                        new_index,
                        None,
                        new_columns,
                        new_order,
                        None,
                    ));
                }

                for row_idx in 0..n_rows {
                    let col_name = (start + row_idx as i64).to_string();
                    new_columns.insert(
                        col_name.clone(),
                        Column::from_f64_transpose_row(&row_plan, row_idx),
                    );
                    new_order.push(col_name);
                }
                return Ok(Self::new_with_axes_trusted(
                    new_index,
                    None,
                    new_columns,
                    new_order,
                    None,
                ));
            }

            if let Some(labels) = self.index.int64_label_values() {
                for (row_idx, label) in labels.iter().enumerate() {
                    let col_name = label.to_string();
                    new_columns.insert(
                        col_name.clone(),
                        Column::from_f64_transpose_row(&row_plan, row_idx),
                    );
                    new_order.push(col_name);
                }
                return Ok(Self::new_with_axes_trusted(
                    new_index,
                    None,
                    new_columns,
                    new_order,
                    None,
                ));
            }

            let labels = self.index.labels();
            for (row_idx, label) in labels.iter().enumerate() {
                let col_name = label_to_name(label);
                if new_columns
                    .insert(
                        col_name.clone(),
                        Column::from_f64_transpose_row(&row_plan, row_idx),
                    )
                    .is_some()
                {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "transpose requires unique stringified index labels: \
                         more than one source index label maps to column name '{col_name}'"
                    )));
                }
                new_order.push(col_name);
            }
            return Ok(Self::new_with_axes_trusted(
                new_index,
                None,
                new_columns,
                new_order,
                None,
            ));
        }

        // Typed all-valid-Float64 fast path: when every source column is a dense
        // f64 slice, each transposed row is itself all-f64, so build it directly
        // from `&[f64]` via `from_f64_values` — no per-cell `Scalar` clone, no
        // `from_values` dtype inference. Bit-identical to the Scalar path for
        // all-valid f64 (from_f64_values marks NaN missing exactly as
        // Scalar::Float64(NaN) would, and there is no NaN in an all-valid slice).
        let f64_slices: Option<Vec<&[f64]>> = src_cols.iter().map(|c| c.as_f64_slice()).collect();
        if let Some(f64_slices) = f64_slices {
            if let Some((start, len)) = self.index.int64_unit_range_labels() {
                debug_assert_eq!(len, n_rows);
                for row_idx in 0..n_rows {
                    let col_name = (start + row_idx as i64).to_string();
                    let mut row_values = Vec::with_capacity(n_cols);
                    for s in &f64_slices {
                        row_values.push(s[row_idx]);
                    }
                    new_columns.insert(col_name.clone(), Column::from_f64_values(row_values));
                    new_order.push(col_name);
                }
                return Ok(Self::new_with_axes_trusted(
                    new_index,
                    None,
                    new_columns,
                    new_order,
                    None,
                ));
            }

            if let Some(labels) = self.index.int64_label_values() {
                for (row_idx, label) in labels.iter().enumerate() {
                    let col_name = label.to_string();
                    let mut row_values = Vec::with_capacity(n_cols);
                    for s in &f64_slices {
                        row_values.push(s[row_idx]);
                    }
                    new_columns.insert(col_name.clone(), Column::from_f64_values(row_values));
                    new_order.push(col_name);
                }
                return Ok(Self::new_with_axes_trusted(
                    new_index,
                    None,
                    new_columns,
                    new_order,
                    None,
                ));
            }

            let labels = self.index.labels();
            for (row_idx, label) in labels.iter().enumerate() {
                let col_name = label_to_name(label);
                let mut row_values = Vec::with_capacity(n_cols);
                for s in &f64_slices {
                    row_values.push(s[row_idx]);
                }
                if new_columns
                    .insert(col_name.clone(), Column::from_f64_values(row_values))
                    .is_some()
                {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "transpose requires unique stringified index labels: \
                         more than one source index label maps to column name '{col_name}'"
                    )));
                }
                new_order.push(col_name);
            }
            return Ok(Self::new_with_axes_trusted(
                new_index,
                None,
                new_columns,
                new_order,
                None,
            ));
        }

        // Generic (mixed / nullable) path — still hoisted out of the BTreeMap.
        let labels = self.index.labels();
        let src_values: Vec<&[Scalar]> = src_cols.iter().map(|c| c.values()).collect();
        for (row_idx, label) in labels.iter().enumerate() {
            let col_name = label_to_name(label);
            let mut row_values = Vec::with_capacity(n_cols);
            for vals in &src_values {
                row_values.push(vals[row_idx].clone());
            }
            if new_columns
                .insert(col_name.clone(), Column::from_values(row_values)?)
                .is_some()
            {
                return Err(FrameError::CompatibilityRejected(format!(
                    "transpose requires unique stringified index labels: \
                     more than one source index label maps to column name '{col_name}'"
                )));
            }
            new_order.push(col_name);
        }

        Ok(Self::new_with_axes_trusted(
            new_index,
            None,
            new_columns,
            new_order,
            None,
        ))
    }

    /// Alias for `transpose()`.
    ///
    /// Matches `df.T` in pandas.
    pub fn t(&self) -> Result<Self, FrameError> {
        self.transpose()
    }

    /// Uppercase pandas spelling for [`Self::transpose`].
    ///
    /// Rust style prefers [`Self::t`], but pandas exposes `df.T`.
    #[allow(non_snake_case)]
    pub fn T(&self) -> Result<Self, FrameError> {
        self.transpose()
    }

    /// Return row-major scalar values.
    ///
    /// Matches `pd.DataFrame.values` at the API-shape level. Unlike
    /// [`Self::to_numpy`], this preserves non-numeric scalar values.
    #[must_use]
    pub fn values(&self) -> Vec<Vec<Scalar>> {
        self.row_major_values()
    }

    /// Per-column product alias.
    ///
    /// Matches `pd.DataFrame.product()` as an alias of `prod()`.
    pub fn product(&self) -> Result<Series, FrameError> {
        self.prod()
    }

    /// `df.product(numeric_only=...)`, the alias's sibling of
    /// [`Self::prod_with_numeric_only`]. An alias must offer the same options
    /// as the method it aliases, or callers get a silently narrower API on one
    /// spelling. (br-frankenpandas-reductions-numeric-only-default-zx21n)
    pub fn product_with_numeric_only(&self, numeric_only: bool) -> Result<Series, FrameError> {
        self.prod_with_numeric_only(numeric_only)
    }

    /// Dict-like column lookup.
    ///
    /// Matches `pd.DataFrame.get(key)` by returning `None` instead of an
    /// error for a missing column.
    pub fn get(&self, key: &str) -> Result<Option<Series>, FrameError> {
        self.column_as_series(key).map(Some).or_else(|err| {
            if matches!(err, FrameError::CompatibilityRejected(_)) {
                Ok(None)
            } else {
                Err(err)
            }
        })
    }

    /// Dict-like column lookup with a fallback Series.
    ///
    /// Matches `pd.DataFrame.get(key, default)` for Series defaults.
    pub fn get_or(&self, key: &str, default: Series) -> Result<Series, FrameError> {
        self.get(key).map(|series| series.unwrap_or(default))
    }

    /// Extract the single boolean value from a 1x1 DataFrame.
    ///
    /// Matches `pd.DataFrame.bool()`. Raises unless the DataFrame has exactly
    /// one row, one column, and that cell is a boolean scalar.
    pub fn bool_(&self) -> Result<bool, FrameError> {
        if self.len() != 1 || self.num_columns() != 1 {
            return Err(FrameError::CompatibilityRejected(
                "bool_: DataFrame must contain exactly one element".to_string(),
            ));
        }
        let column_name = self.column_order.first().ok_or_else(|| {
            FrameError::CompatibilityRejected(
                "bool_: DataFrame must contain exactly one column".to_string(),
            )
        })?;
        match &self.columns[column_name].values()[0] {
            Scalar::Bool(flag) => Ok(*flag),
            _ => Err(FrameError::CompatibilityRejected(
                "bool_: value must be a boolean scalar".to_string(),
            )),
        }
    }

    /// User metadata mapping.
    ///
    /// Matches `pd.DataFrame.attrs` shape. FrankenPandas does not yet persist
    /// mutable attrs on the DataFrame storage object, so the current accessor
    /// returns the default empty metadata map.
    #[must_use]
    pub fn attrs(&self) -> BTreeMap<String, Scalar> {
        BTreeMap::new()
    }

    /// DataFrame flags metadata.
    ///
    /// Matches `pd.DataFrame.flags` for the duplicate-label flag currently
    /// represented by FrankenPandas.
    #[must_use]
    pub fn flags(&self) -> DataFrameFlags {
        DataFrameFlags {
            allows_duplicate_labels: self.allows_duplicate_labels,
        }
    }

    /// Return a DataFrame with updated flags.
    ///
    /// Matches `pd.DataFrame.set_flags(allows_duplicate_labels=...)` for the
    /// duplicate-label flag.
    pub fn set_flags(&self, allows_duplicate_labels: Option<bool>) -> Result<Self, FrameError> {
        let next_allows = allows_duplicate_labels.unwrap_or(self.allows_duplicate_labels);
        Self::validate_duplicate_label_policy(
            next_allows,
            &self.index,
            self.row_multiindex.as_ref(),
            "set_flags",
        )?;

        let mut out = self.clone();
        out.allows_duplicate_labels = next_allows;
        Ok(out)
    }

    /// Styling accessor for DataFrame HTML and text rendering helpers.
    ///
    /// Matches `pd.DataFrame.style` as a typed accessor over the current
    /// DataFrame. The current implementation supports practical table
    /// rendering methods such as [`StyledDataFrame::to_html`],
    /// [`StyledDataFrame::to_string_table`], and classed HTML output.
    #[must_use]
    pub fn style(&self) -> StyledDataFrame<'_> {
        StyledDataFrame {
            df: self,
            directives: StyleDirectives::default(),
        }
    }

    /// Sparse accessor for DataFrame density and dense materialization helpers.
    ///
    /// Matches `pd.DataFrame.sparse` as a typed accessor over the current
    /// DataFrame. The current dense-backed implementation exposes non-fill
    /// counts, density metrics, caller-provided fill-value variants, and
    /// [`SparseDataFrameView::to_dense`].
    #[must_use]
    pub fn sparse(&self) -> SparseDataFrameView<'_> {
        SparseDataFrameView { df: self }
    }

    /// Swap axes (rows and columns).
    ///
    /// Matches `df.swapaxes('index', 'columns')`. Alias for `transpose()`.
    pub fn swapaxes(&self) -> Result<Self, FrameError> {
        self.transpose()
    }

    /// Label-based element lookup.
    ///
    /// Matches `df.lookup(row_labels, col_labels)`. Returns a Vec of Scalars
    /// where element `i` is the value at (`row_labels[i]`, `col_labels[i]`).
    pub fn lookup(
        &self,
        row_labels: &[IndexLabel],
        col_labels: &[&str],
    ) -> Result<Vec<Scalar>, FrameError> {
        if row_labels.len() != col_labels.len() {
            return Err(FrameError::CompatibilityRejected(
                "row_labels and col_labels must have the same length".to_owned(),
            ));
        }

        let pos_map = self.index.position_map_first();
        let mut result = Vec::with_capacity(row_labels.len());

        for (rl, cl) in row_labels.iter().zip(col_labels) {
            let row_pos = pos_map.get(rl).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("row label not found: {rl:?}"))
            })?;
            let col = self.columns.get(cl).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("column not found: {cl}"))
            })?;
            result.push(col.values()[*row_pos].clone());
        }

        Ok(result)
    }

    /// Linear interpolation percentile (matching pandas default method).
    /// Linear-interpolation quantile via O(n) selection instead of an O(n log n)
    /// sort (br-frankenpandas-zjc5z). percentile_linear only reads the order
    /// statistics at `lower = floor(q·(n-1))` and `upper = ceil(...)`, so a
    /// quickselect for `lower` (plus the min of the right partition for `upper`)
    /// yields the identical two values without sorting the whole slice.
    ///
    /// Bit-identical to `sort_by(partial_cmp) + percentile_linear`: for finite,
    /// non-negative-zero data the k-th order statistic is unique-valued, so
    /// select and sort agree; equal values are bit-identical so the
    /// right-partition min equals sorted[lower+1]. The ONE case a stable sort and
    /// an unstable select can disagree is a -0.0/0.0 tie (equal under partial_cmp
    /// but bit-distinct), so any negative zero present routes to the exact sort.
    fn quantile_select(nums: &mut [f64], q: f64) -> f64 {
        let n = nums.len();
        if n == 0 {
            return f64::NAN;
        }
        if n == 1 {
            return nums[0];
        }
        let cmp = |a: &f64, b: &f64| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal);
        if nums.iter().any(|&v| v == 0.0 && v.is_sign_negative()) {
            nums.sort_by(cmp);
            return Self::percentile_linear(nums, q);
        }
        let pos = q * (n - 1) as f64;
        let lower = pos.floor() as usize;
        let upper = pos.ceil() as usize;
        nums.select_nth_unstable_by(lower, cmp);
        let lo_val = nums[lower];
        if lower == upper {
            lo_val
        } else {
            // upper == lower + 1: the (lower+1)-th smallest is the minimum of the
            // right partition (every element after `lower` is >= lo_val).
            let hi_val = *nums[lower + 1..]
                .iter()
                .min_by(|a, b| cmp(a, b))
                .expect("right partition is non-empty when upper > lower");
            let frac = pos - lower as f64;
            lo_val * (1.0 - frac) + hi_val * frac
        }
    }

    fn percentile_linear(sorted: &[f64], q: f64) -> f64 {
        if sorted.is_empty() {
            return f64::NAN;
        }
        if sorted.len() == 1 {
            return sorted[0];
        }
        let pos = q * (sorted.len() - 1) as f64;
        let lower = pos.floor() as usize;
        let upper = pos.ceil() as usize;
        if lower == upper {
            sorted[lower]
        } else {
            let frac = pos - lower as f64;
            sorted[lower] * (1.0 - frac) + sorted[upper] * frac
        }
    }

    /// Keep values where `cond` is True; replace others with `other`.
    ///
    /// Typed Float64 fast path shared by `where_cond` and `mask`
    /// (br-frankenpandas-mz8hj). Fires when the index is identical to `cond`'s
    /// AND unique (so the Left alignment is the identity — for a duplicate-label
    /// index the general path maps each self row to cond's FIRST occurrence of
    /// that label, which positional access would not reproduce), `other` is a
    /// finite Float64 fill, and every column is Float64 with a contiguous
    /// backing — selecting straight from the f64 + validity slices into a typed
    /// output, skipping the cond reindex, the per-element self `Scalar`
    /// materialization, and the `Column::from_values` revalidation. Returns
    /// `None` to fall back.
    ///
    /// Bit-identical to the general select: `cond == Bool(keep_self)` keeps the
    /// self value (present Float64, or its missing scalar when self is
    /// missing/NaN — a cleared bit + datum materializes the same Null(NaN) /
    /// Float64(NaN)); the other Bool keeps the finite fill; `cond == Null` (and
    /// any non-Bool cond) yields Null(NaN) for where / the self value for mask,
    /// exactly the general arms (`Null(_) => Null(NaN)`, `_ => fill`/`val`).
    fn where_mask_typed_f64(
        &self,
        cond: &Self,
        other: Option<&Scalar>,
        mask_mode: bool,
    ) -> Option<Result<Self, FrameError>> {
        let &Scalar::Float64(fill) = other? else {
            return None;
        };
        if !fill.is_finite() || self.index != cond.index || !self.index.is_unique() {
            return None;
        }
        for name in &self.column_order {
            if !matches!(self.columns[name].dtype(), DType::Float64)
                || !cond.columns.contains_key(name)
            {
                return None;
            }
        }
        // Column-parallel (br-frankenpandas-wheremask-par): each column's
        // where/mask select is independent, so spread them across par_map_columns
        // scope workers. The closure returns None when a column can't take the
        // typed path (non-contiguous Float64 or a cond/self length mismatch); if
        // ANY column bails the whole typed attempt returns None and the caller
        // falls through to the general Scalar path — preserving the old
        // early-`?`/`return None` semantics, just computed in parallel.
        // Bit-identical: identical per-column select arm, reassembled in
        // column_order.
        let computed = match self.par_map_columns(&self.column_order, |name| {
            let Some((sd, sv)) = self.columns[name].as_f64_slice_with_validity() else {
                return Ok(None);
            };
            let cond_vals = cond.columns[name].values();
            if cond_vals.len() != sd.len() {
                return Ok(None);
            }
            let n = sd.len();
            let mut out = vec![0.0_f64; n];
            let mut out_valid = fp_columnar::ValidityMask::all_valid(n);
            for i in 0..n {
                let keep_self = match &cond_vals[i] {
                    Scalar::Bool(b) => {
                        // where: keep self iff cond true; mask: iff cond false.
                        if mask_mode { !*b } else { *b }
                    }
                    // A MISSING condition is not a missing RESULT. The condition
                    // is a SELECTOR: undecidable means "not the keep-branch", so
                    // the cell takes `other` in BOTH modes. This arm used to
                    // propagate the condition's missingness into the output
                    // (`out_valid.set(i, false)`), which is what
                    // br-frankenpandas-yf758's two translation-covariance
                    // proptests caught.
                    //
                    // MEASURED, live pandas 2.2.3, nullable-boolean cond
                    // [NA, True, False] over [1.0, 2.0, 3.0] with other=99.0:
                    // ```text
                    //   df.where(cond, 99.0) -> [99.0, 2.0, 99.0]
                    //   df.mask (cond, 99.0) -> [99.0, 99.0, 3.0]
                    // ```
                    // Row 0 is the NA-cond cell and takes 99.0 in BOTH modes;
                    // pandas never yields NaN there. Rows 1-2 differ between the
                    // modes, which is the control proving this is about the
                    // selector and not about the data.
                    //
                    // br-frankenpandas-fixture-divergence-triage-9s0c4 already
                    // established this and fixed the DataFrame-`other` variants
                    // (see `where_and_mask_treat_a_null_condition_as_false`);
                    // this SCALAR-`other` typed path is the sibling it missed.
                    //
                    // The non-Bool arm collapses into the same rule and for the
                    // same reason. `aligned_condition_cells` — the general
                    // path's reader — maps EVERY non-Bool cell (Null or
                    // otherwise) to `None`, and the general path then keeps only
                    // on `Some(true)` for where / `Some(false)` for mask. The old
                    // `_ => mask_mode` arm therefore also disagreed in mask mode:
                    // it KEPT SELF on a non-Bool cond where the general path
                    // takes `other`. A typed fast path has to be bit-identical
                    // to the path it short-circuits, so keep-self is now exactly
                    // "a PRESENT Bool of the right polarity" and everything else
                    // takes `other`.
                    _ => false,
                };
                if keep_self {
                    out[i] = sd[i];
                    if !(sv.get(i) && !sd[i].is_nan()) {
                        out_valid.set(i, false);
                    }
                } else {
                    out[i] = fill;
                }
            }
            Ok(Some(Column::from_f64_values_with_validity(out, out_valid)))
        }) {
            Ok(c) => c,
            Err(e) => return Some(Err(e)),
        };
        if !computed.iter().all(Option::is_some) {
            return None;
        }
        let mut new_columns = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(computed) {
            new_columns.insert(name.clone(), column.expect("all columns checked is_some"));
        }
        Some(Self::new_with_column_order(
            self.index.clone(),
            new_columns,
            self.column_order.clone(),
        ))
    }

    /// Keep values where `cond` is True; replace others with `other`.
    ///
    /// Typed Int64 fast path shared by `where_cond` and `mask`
    /// (br-frankenpandas-eydcr). The Int64 analogue of [`where_mask_typed_f64`],
    /// but deliberately narrower: it fires only when `other` is an Int64 fill,
    /// the index is identical to `cond`'s AND unique (the Left alignment is then
    /// the identity), every self column is an all-valid Int64 contiguous backing
    /// (`as_i64_slice`), and every cond column is an all-valid `Bool` contiguous
    /// backing (`as_bool_slice`). Under those gates NO missing values are ever
    /// produced — each output datum is `self_int` (keep) or `fill_int`
    /// (replace) — so the result is a pure all-valid Int64 column built straight
    /// from the i64 slices, skipping the cond reindex, the per-element `Scalar`
    /// materialization, and the `Column::from_values` dtype-inference +
    /// revalidation. Returns `None` (caller keeps the Scalar path) for any
    /// cond-null / non-Bool cond / non-Int64 column / fractional or
    /// non-finite fill — those arms can introduce Null(NaN) or upcast to
    /// Float64, which this all-valid-Int64 path does not model.
    ///
    /// Bit-identical to the general select over this gated input: for `where`,
    /// `cond == Bool(true)` keeps `Int64(self)` and `Bool(false)` takes the
    /// `Int64(fill)`; `mask` swaps the two arms. Both produce the same Int64
    /// scalar at every row, and `from_i64_values` yields the same all-valid
    /// Int64 column `Column::from_values` would infer from those scalars.
    fn where_mask_typed_i64(
        &self,
        cond: &Self,
        other: Option<&Scalar>,
        mask_mode: bool,
    ) -> Option<Result<Self, FrameError>> {
        let &Scalar::Int64(fill) = other? else {
            return None;
        };
        if self.index != cond.index || !self.index.is_unique() {
            return None;
        }
        for name in &self.column_order {
            if !matches!(self.columns[name].dtype(), DType::Int64)
                || !cond.columns.contains_key(name)
            {
                return None;
            }
        }
        // Column-parallel (br-frankenpandas-wheremask-par): see
        // where_mask_typed_f64. Each column's typed Int64 select is independent;
        // a None bail (non-contiguous Int64 self / non-Bool cond / length
        // mismatch) makes the whole typed attempt fall through to the Scalar path.
        let computed = match self.par_map_columns(&self.column_order, |name| {
            let Some(sd) = self.columns[name].as_i64_slice() else {
                return Ok(None);
            };
            let Some(cb) = cond.columns[name].as_bool_slice() else {
                return Ok(None);
            };
            if cb.len() != sd.len() {
                return Ok(None);
            }
            let n = sd.len();
            let mut out = vec![0_i64; n];
            for i in 0..n {
                // where: keep self iff cond true; mask: iff cond false.
                let keep_self = if mask_mode { !cb[i] } else { cb[i] };
                out[i] = if keep_self { sd[i] } else { fill };
            }
            Ok(Some(Column::from_i64_values_owned(out)))
        }) {
            Ok(c) => c,
            Err(e) => return Some(Err(e)),
        };
        if !computed.iter().all(Option::is_some) {
            return None;
        }
        let mut new_columns = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(computed) {
            new_columns.insert(name.clone(), column.expect("all columns checked is_some"));
        }
        Some(Self::new_with_column_order(
            self.index.clone(),
            new_columns,
            self.column_order.clone(),
        ))
    }

    /// Align a `where`/`mask` condition column onto this frame's rows.
    ///
    /// `None` in the result means the condition is ABSENT OR UNDECIDABLE for
    /// that cell — the column is missing from `cond`, the row did not align, or
    /// the cell is not a `Bool`. Every such cell takes the else-branch
    /// (`other`), for BOTH `where` and `mask`.
    ///
    /// A MISSING CONDITION COLUMN IS NOT AN ERROR. pandas reindexes `cond` onto
    /// the frame's BOTH axes, so a column `cond` does not have simply becomes
    /// all-absent. MEASURED, live pandas 2.2.3, `df = {'a':[1,2],'b':[3,4]}`:
    ///
    /// ```text
    ///   cond = {'a':[True,False]}          (no 'b' at all)
    ///     df.where(cond, -1) -> a [1,-1]   b [-1,-1]   stays int64
    ///     df.mask (cond, -1) -> a [-1,2]   b [-1,-1]
    ///   cond = {'a':[True],'b':[True]} on index [0]    (no row 1)
    ///     df.where(cond, -1) -> a [1,-1]   b [3,-1]
    ///   cond carrying an EXTRA column 'c'              -> 'c' IGNORED
    /// ```
    ///
    /// Both ops answer `other` for an absent cell, and they differ only on a
    /// PRESENT value — `where` keeps on `True`, `mask` keeps on `False`. That
    /// asymmetry is why `mask` is `where(~cond)` with the inversion applied
    /// BEFORE alignment: a missing column never reaches the `~`, which is also
    /// why pandas raises `TypeError: bad operand type for unary ~: 'float'` for
    /// `mask` when a PRESENT cond cell is a float NaN but not when the whole
    /// column is absent. FrankenPandas routes that present-NaN case to `other`
    /// like `where` rather than raising; no fixture covers it and adding a raise
    /// would be an unmeasured error-surface change.
    ///
    /// The extra column is ignored for free because every caller iterates
    /// `self.column_order`, never the condition's.
    ///
    /// (br-frankenpandas-xg7hf)
    fn aligned_condition_cells(
        cond: &Self,
        col_name: &str,
        positions: &[Option<usize>],
        rows: usize,
    ) -> Result<Vec<Option<bool>>, FrameError> {
        let Some(cond_col) = cond.columns.get(col_name) else {
            return Ok(vec![None; rows]);
        };
        let aligned = cond_col.reindex_by_positions(positions)?;
        Ok(aligned
            .values()
            .iter()
            .map(|cell| match cell {
                Scalar::Bool(flag) => Some(*flag),
                _ => None,
            })
            .collect())
    }

    /// Matches `df.where(cond, other)`. Applies element-wise to each column.
    /// If `other` is `None`, replaced values become NaN.
    pub fn where_cond(&self, cond: &Self, other: Option<&Scalar>) -> Result<Self, FrameError> {
        if let Some(result) = self.where_mask_typed_f64(cond, other, false) {
            return result;
        }
        if let Some(result) = self.where_mask_typed_i64(cond, other, false) {
            return result;
        }
        let fill = other.cloned().unwrap_or(Scalar::Null(NullKind::NaN));
        let plan = align(&self.index, &cond.index, AlignMode::Left);
        validate_alignment_plan(&plan)?;
        let mut new_columns = BTreeMap::new();

        for col_name in &self.column_order {
            let data_col = self
                .columns
                .get(col_name)
                .expect("column in order must exist");
            // Keep iff the condition is PRESENT and True; absent/undecidable
            // takes `other`, and a missing column is all-absent rather than an
            // error. The old `Scalar::Null(_) => Null(NaN)` arm answered NaN
            // where pandas answers `other` — invisible whenever `other` is None,
            // because then the fill IS NaN. (br-frankenpandas-xg7hf)
            let cond_cells = Self::aligned_condition_cells(
                cond,
                col_name,
                &plan.right_positions,
                data_col.len(),
            )?;

            let values: Vec<Scalar> = data_col
                .values()
                .iter()
                .zip(cond_cells)
                .map(|(val, cell)| {
                    if cell == Some(true) {
                        val.clone()
                    } else {
                        fill.clone()
                    }
                })
                .collect();

            new_columns.insert(col_name.clone(), Column::from_values(values)?);
        }

        Self::new_with_column_order(self.index.clone(), new_columns, self.column_order.clone())
    }

    /// pandas-named alias for [`Self::where_cond`]. Matches `df.where(cond, other)`.
    ///
    /// Per br-frankenpandas-nk54a. `where` would conflict with the Rust
    /// keyword in `where` clauses if used as an identifier in some
    /// contexts, but it's not a reserved identifier — the inherent
    /// method works directly. Provided as a pandas-faithful alias.
    pub fn r#where(&self, cond: &Self, other: Option<&Scalar>) -> Result<Self, FrameError> {
        self.where_cond(cond, other)
    }

    /// Replace values where `cond` is True with `other`.
    ///
    /// Matches `df.mask(cond, other)`. Inverse of `where_cond`.
    pub fn mask(&self, cond: &Self, other: Option<&Scalar>) -> Result<Self, FrameError> {
        if let Some(result) = self.where_mask_typed_f64(cond, other, true) {
            return result;
        }
        if let Some(result) = self.where_mask_typed_i64(cond, other, true) {
            return result;
        }
        let fill = other.cloned().unwrap_or(Scalar::Null(NullKind::NaN));
        let plan = align(&self.index, &cond.index, AlignMode::Left);
        validate_alignment_plan(&plan)?;
        let mut new_columns = BTreeMap::new();

        for col_name in &self.column_order {
            let data_col = self
                .columns
                .get(col_name)
                .expect("column in order must exist");
            // mask keeps on a PRESENT False; everything else — True, absent, or
            // undecidable — takes `other`. Sibling of `where_cond` above, and
            // the only difference is which present value keeps.
            // (br-frankenpandas-xg7hf)
            let cond_cells = Self::aligned_condition_cells(
                cond,
                col_name,
                &plan.right_positions,
                data_col.len(),
            )?;

            let values: Vec<Scalar> = data_col
                .values()
                .iter()
                .zip(cond_cells)
                .map(|(val, cell)| {
                    if cell == Some(false) {
                        val.clone()
                    } else {
                        fill.clone()
                    }
                })
                .collect();

            new_columns.insert(col_name.clone(), Column::from_values(values)?);
        }

        Self::new_with_column_order(self.index.clone(), new_columns, self.column_order.clone())
    }

    /// Keep values where `cond` is True, replacing False positions with
    /// corresponding values from `other` DataFrame.
    ///
    /// Matches `df.where(cond, other=df)`.
    pub fn where_cond_df(&self, cond: &Self, other: &Self) -> Result<Self, FrameError> {
        // Typed select fast path: identical unique index across self/cond/other,
        // every column two-sided Float64 with an all-valid Bool cond. The general
        // path below materializes 3 Scalar Vecs per column and clones a Scalar per
        // cell (5M clones at 5 cols x 1M rows — df.where(cond,other) was 0.12x
        // pandas). Select straight from the f64 + validity slices via the bool
        // slice into a typed output. Bit-identical to the per-cell Scalar select:
        // cond True keeps self (present iff self valid), cond False takes other
        // (present iff other valid); an all-valid cond has no Null cell.
        if self.index == cond.index
            && self.index == other.index
            && self.index.is_unique()
            && self.row_multiindex.is_none()
            && self.column_order.iter().all(|name| {
                self.columns[name].as_f64_slice_with_validity().is_some()
                    && cond
                        .columns
                        .get(name)
                        .is_some_and(|c| c.as_bool_slice().is_some())
                    && other
                        .columns
                        .get(name)
                        .is_some_and(|c| c.as_f64_slice_with_validity().is_some())
            })
        {
            let n = self.index.len();
            let ok = self.column_order.iter().all(|name| {
                self.columns[name].len() == n
                    && cond.columns[name].len() == n
                    && other.columns[name].len() == n
            });
            if ok {
                let computed = self.par_map_columns(&self.column_order, |name| {
                    let (sx, sv) = self.columns[name].as_f64_slice_with_validity().unwrap();
                    let (ox, ov) = other.columns[name].as_f64_slice_with_validity().unwrap();
                    let cb = cond.columns[name].as_bool_slice().unwrap();
                    let mut out = vec![0.0_f64; n];
                    let mut valid = fp_columnar::ValidityMask::all_valid(n);
                    for i in 0..n {
                        if cb[i] {
                            out[i] = sx[i];
                            if !sv.get(i) {
                                valid.set(i, false);
                            }
                        } else {
                            out[i] = ox[i];
                            if !ov.get(i) {
                                valid.set(i, false);
                            }
                        }
                    }
                    Ok(Column::from_f64_values_with_validity(out, valid))
                })?;
                let mut result_cols = BTreeMap::new();
                for (name, column) in self.column_order.iter().zip(computed) {
                    result_cols.insert(name.clone(), column);
                }
                return Self::new_with_column_order(
                    self.index.clone(),
                    result_cols,
                    self.column_order.clone(),
                );
            }
        }

        let cond_plan = align(&self.index, &cond.index, AlignMode::Left);
        validate_alignment_plan(&cond_plan)?;
        let other_plan = align(&self.index, &other.index, AlignMode::Left);
        validate_alignment_plan(&other_plan)?;

        // Typed unaligned select fast path: self+other Float64 with validity,
        // all-valid Bool cond, unique indexes, no row-MultiIndex. Gather cond and
        // other onto self via the Left-align position vectors (bit-identical to
        // the Scalar reindex + per-cell select below) — the general path clones
        // a Scalar per cell over reindexed columns (df.where unaligned was 0.85x
        // pandas, and pandas itself reindexes both frames here so this flips it
        // to a large win). Bails per-column to the Scalar path on any non-fit.
        if self.row_multiindex.is_none()
            && self.index.is_unique()
            && cond.index.is_unique()
            && other.index.is_unique()
            && self.column_order.iter().all(|name| {
                cond.columns.contains_key(name)
                    && self.columns[name].as_f64_slice_with_validity().is_some()
                    && cond.columns[name].as_bool_slice().is_some()
                    && other
                        .columns
                        .get(name)
                        .is_none_or(|o| o.as_f64_slice_with_validity().is_some())
            })
        {
            let computed = self.par_map_columns(&self.column_order, |name| {
                match where_gather_df_col(
                    &self.columns[name],
                    &cond.columns[name],
                    &cond_plan.right_positions,
                    other.columns.get(name),
                    &other_plan.right_positions,
                    false,
                ) {
                    Some(r) => r.map(Some),
                    None => Ok(None),
                }
            })?;
            if computed.iter().all(Option::is_some) {
                let mut result_cols = BTreeMap::new();
                for (name, column) in self.column_order.iter().zip(computed) {
                    result_cols.insert(name.clone(), column.expect("all is_some checked"));
                }
                return Self::new_with_column_order(
                    self.index.clone(),
                    result_cols,
                    self.column_order.clone(),
                );
            }
        }

        let mut new_columns = BTreeMap::new();

        for col_name in &self.column_order {
            let data_col = &self.columns[col_name];
            // A missing cond COLUMN is all-absent, not an error
            // (br-frankenpandas-xg7hf); the NON-TRUE rule below is unchanged.
            let cond_cells = Self::aligned_condition_cells(
                cond,
                col_name,
                &cond_plan.right_positions,
                data_col.len(),
            )?;
            let aligned_other = other
                .columns
                .get(col_name)
                .map(|col| col.reindex_by_positions(&other_plan.right_positions))
                .transpose()?;

            let values: Vec<Scalar> = data_col
                .values()
                .iter()
                .zip(cond_cells)
                .enumerate()
                .map(|(i, (val, cell))| match cell {
                    Some(true) => val.clone(),
                    // A NON-TRUE condition — False OR MISSING — takes `other`.
                    // The condition is a SELECTOR, and an undecidable selector
                    // falls to the else-branch; pandas never propagates the
                    // condition's own missingness into the result. MEASURED,
                    // live pandas 2.2.3, df=[10.0,20.0], other=[100.0,200.0],
                    // cond=[<NA>, False]:
                    //   df.where(cond, other) -> [100.0, 200.0]
                    // The old `_ => Null(NaN)` arm produced [nan, 200.0].
                    // (br-frankenpandas-fixture-divergence-triage-9s0c4)
                    _ => aligned_other
                        .as_ref()
                        .and_then(|oc| oc.values().get(i).cloned())
                        .unwrap_or(Scalar::Null(NullKind::NaN)),
                })
                .collect();

            new_columns.insert(col_name.clone(), Column::from_values(values)?);
        }

        Self::new_with_column_order(self.index.clone(), new_columns, self.column_order.clone())
    }

    /// Replace values where `cond` is True with corresponding values from
    /// `other` DataFrame.
    ///
    /// Matches `df.mask(cond, other=df)`.
    pub fn mask_df_other(&self, cond: &Self, other: &Self) -> Result<Self, FrameError> {
        // Typed select fast path — inverse of where_cond_df's (cond True -> OTHER,
        // False -> self). Same gate/semantics; avoids the per-cell Scalar select.
        if self.index == cond.index
            && self.index == other.index
            && self.index.is_unique()
            && self.row_multiindex.is_none()
            && self.column_order.iter().all(|name| {
                self.columns[name].as_f64_slice_with_validity().is_some()
                    && cond
                        .columns
                        .get(name)
                        .is_some_and(|c| c.as_bool_slice().is_some())
                    && other
                        .columns
                        .get(name)
                        .is_some_and(|c| c.as_f64_slice_with_validity().is_some())
            })
        {
            let n = self.index.len();
            let ok = self.column_order.iter().all(|name| {
                self.columns[name].len() == n
                    && cond.columns[name].len() == n
                    && other.columns[name].len() == n
            });
            if ok {
                let computed = self.par_map_columns(&self.column_order, |name| {
                    let (sx, sv) = self.columns[name].as_f64_slice_with_validity().unwrap();
                    let (ox, ov) = other.columns[name].as_f64_slice_with_validity().unwrap();
                    let cb = cond.columns[name].as_bool_slice().unwrap();
                    let mut out = vec![0.0_f64; n];
                    let mut valid = fp_columnar::ValidityMask::all_valid(n);
                    for i in 0..n {
                        if cb[i] {
                            out[i] = ox[i];
                            if !ov.get(i) {
                                valid.set(i, false);
                            }
                        } else {
                            out[i] = sx[i];
                            if !sv.get(i) {
                                valid.set(i, false);
                            }
                        }
                    }
                    Ok(Column::from_f64_values_with_validity(out, valid))
                })?;
                let mut result_cols = BTreeMap::new();
                for (name, column) in self.column_order.iter().zip(computed) {
                    result_cols.insert(name.clone(), column);
                }
                return Self::new_with_column_order(
                    self.index.clone(),
                    result_cols,
                    self.column_order.clone(),
                );
            }
        }

        let cond_plan = align(&self.index, &cond.index, AlignMode::Left);
        validate_alignment_plan(&cond_plan)?;
        let other_plan = align(&self.index, &other.index, AlignMode::Left);
        validate_alignment_plan(&other_plan)?;

        // Typed unaligned select fast path (inverse of where_cond_df's: cond True
        // -> other, False -> self). Same gate/gather; bit-identical to the Scalar
        // select below (mask unaligned was 0.85x pandas).
        if self.row_multiindex.is_none()
            && self.index.is_unique()
            && cond.index.is_unique()
            && other.index.is_unique()
            && self.column_order.iter().all(|name| {
                cond.columns.contains_key(name)
                    && self.columns[name].as_f64_slice_with_validity().is_some()
                    && cond.columns[name].as_bool_slice().is_some()
                    && other
                        .columns
                        .get(name)
                        .is_none_or(|o| o.as_f64_slice_with_validity().is_some())
            })
        {
            let computed = self.par_map_columns(&self.column_order, |name| {
                match where_gather_df_col(
                    &self.columns[name],
                    &cond.columns[name],
                    &cond_plan.right_positions,
                    other.columns.get(name),
                    &other_plan.right_positions,
                    true,
                ) {
                    Some(r) => r.map(Some),
                    None => Ok(None),
                }
            })?;
            if computed.iter().all(Option::is_some) {
                let mut result_cols = BTreeMap::new();
                for (name, column) in self.column_order.iter().zip(computed) {
                    result_cols.insert(name.clone(), column.expect("all is_some checked"));
                }
                return Self::new_with_column_order(
                    self.index.clone(),
                    result_cols,
                    self.column_order.clone(),
                );
            }
        }

        let mut new_columns = BTreeMap::new();

        for col_name in &self.column_order {
            let data_col = &self.columns[col_name];
            // A missing cond COLUMN is all-absent, not an error
            // (br-frankenpandas-xg7hf); the MISSING rule below is unchanged.
            let cond_cells = Self::aligned_condition_cells(
                cond,
                col_name,
                &cond_plan.right_positions,
                data_col.len(),
            )?;
            let aligned_other = other
                .columns
                .get(col_name)
                .map(|col| col.reindex_by_positions(&other_plan.right_positions))
                .transpose()?;

            let values: Vec<Scalar> = data_col
                .values()
                .iter()
                .zip(cond_cells)
                .enumerate()
                .map(|(i, (val, cell))| match cell {
                    Some(true) => aligned_other
                        .as_ref()
                        .and_then(|oc| oc.values().get(i).cloned())
                        .unwrap_or(Scalar::Null(NullKind::NaN)),
                    Some(false) => val.clone(),
                    // A MISSING condition takes `other`, same as in
                    // `where_cond_df`. mask is where(~cond), and inverting an
                    // undecidable selector leaves it undecidable, so it still
                    // falls to the else-branch rather than yielding NaN.
                    // MEASURED, live pandas 2.2.3 with cond=[<NA>, False]:
                    //   df.mask(cond, other) -> [100.0, 20.0]
                    // Row 1 differs from `where`'s 200.0 precisely because mask
                    // inverts — the null row does not.
                    // (br-frankenpandas-fixture-divergence-triage-9s0c4)
                    _ => aligned_other
                        .as_ref()
                        .and_then(|oc| oc.values().get(i).cloned())
                        .unwrap_or(Scalar::Null(NullKind::NaN)),
                })
                .collect();

            new_columns.insert(col_name.clone(), Column::from_values(values)?);
        }

        Self::new_with_column_order(self.index.clone(), new_columns, self.column_order.clone())
    }

    /// Symmetry alias for `where_cond_df` (br-frankenpandas-df9v7 /
    /// fd90.138, refactored in br-frankenpandas-a2sck / fd90.139).
    ///
    /// `mask_df_other` already existed but no parallel-named `where_*` was
    /// reachable from a `mask_df_other` callsite without remembering the
    /// `where_cond_df` name. This alias makes the symmetry explicit; both
    /// names dispatch through the same implementation. Prefer `where_cond_df`
    /// in new code.
    pub fn where_mask_df_other(&self, cond: &Self, other: &Self) -> Result<Self, FrameError> {
        self.where_cond_df(cond, other)
    }

    /// Iterate over rows as `(IndexLabel, Vec<(&str, Scalar)>)` pairs.
    ///
    /// Matches `df.iterrows()`. Returns an iterator over (index_label, row_data)
    /// where row_data is a vector of (column_name, value) pairs.
    pub fn iterrows(&self) -> Vec<(IndexLabel, Vec<(&str, Scalar)>)> {
        // Resolve each column's Scalar slice ONCE (was a per-cell
        // `self.columns.get(col_name)` BTreeMap lookup, n*m tree traversals —
        // the per-cell BTreeMap anti-pattern; to_records already resolves once).
        // Bit-identical: same missing-column -> Null default, same values, same
        // column order. Measured 2.27x on df_iterrows (100k x10).
        let cols: Vec<(&str, Option<&[Scalar]>)> = self
            .column_order
            .iter()
            .map(|name| (name.as_str(), self.columns.get(name).map(Column::values)))
            .collect();
        let mut rows = Vec::with_capacity(self.len());
        for i in 0..self.len() {
            let label = label_at(&self.index, i);
            let row: Vec<(&str, Scalar)> = cols
                .iter()
                .map(|(name, values)| {
                    (
                        *name,
                        values.map_or(Scalar::Null(NullKind::Null), |col| col[i].clone()),
                    )
                })
                .collect();
            rows.push((label, row));
        }
        rows
    }

    /// Iterate over rows as tuples of `(IndexLabel, Vec<Scalar>)`.
    ///
    /// Matches `df.itertuples()`. Returns (index_label, values_in_column_order).
    pub fn itertuples(&self) -> Vec<(IndexLabel, Vec<Scalar>)> {
        // Resolve each column's Scalar slice ONCE (per-cell BTreeMap
        // anti-pattern, n*m tree traversals). Bit-identical. Measured 2.57x on
        // df_itertuples (100k x10).
        let cols: Vec<Option<&[Scalar]>> = self
            .column_order
            .iter()
            .map(|name| self.columns.get(name).map(Column::values))
            .collect();
        let mut rows = Vec::with_capacity(self.len());
        for i in 0..self.len() {
            let label = label_at(&self.index, i);
            let vals: Vec<Scalar> = cols
                .iter()
                .map(|values| values.map_or(Scalar::Null(NullKind::Null), |col| col[i].clone()))
                .collect();
            rows.push((label, vals));
        }
        rows
    }

    /// Convert DataFrame to a list of record tuples.
    ///
    /// Matches `df.to_records()`. Each record is a Vec of Scalar where the
    /// first element is the index label (converted to Scalar) followed by
    /// each column value in column order.
    pub fn to_records(&self) -> Vec<Vec<Scalar>> {
        // Hoist the per-row self.index.labels() (was an accessor call EVERY row)
        // and the per-cell columns.get(name).values() (n*m BTreeMap lookups) to
        // once each. Bit-identical.
        let labels = self.index.labels();
        let col_values: Vec<Option<&[Scalar]>> = self
            .column_order
            .iter()
            .map(|name| self.columns.get(name).map(|col| col.values()))
            .collect();
        let n = self.len();
        let n_cols = self.column_order.len();
        // Parallelize the per-row transpose the same way `to_dict("records")` was
        // unlocked (8b19e667b): each row is an independent `Vec<Scalar>` of
        // `[index_label, col0, col1, ...]` — one per-ROW allocation + cheap value
        // clones (NOT a per-cell String tax), so mimalloc's per-thread arenas scale it
        // and the concat just MOVES the inner row-Vec pointers. Each worker builds a
        // contiguous row range; concatenation preserves order → bit-identical.
        let build = |lo: usize, hi: usize| -> Vec<Vec<Scalar>> {
            let mut out = Vec::with_capacity(hi - lo);
            for i in lo..hi {
                let mut row = Vec::with_capacity(n_cols + 1);
                let lbl = &labels[i];
                row.push(match lbl {
                    IndexLabel::Int64(v) => Scalar::Int64(*v),
                    IndexLabel::Float64(v) => Scalar::Float64(v.0),
                    IndexLabel::Bool(b) => Scalar::Bool(*b),
                    IndexLabel::Utf8(s) => Scalar::Utf8(s.clone()),
                    IndexLabel::Timedelta64(ns) => Scalar::Timedelta64(*ns),
                    IndexLabel::Datetime64(ns) => Scalar::Utf8(format_datetime_ns(*ns)),
                    IndexLabel::Null(kind) => Scalar::Null(*kind),
                });
                for col_vals in &col_values {
                    row.push(col_vals.map_or(Scalar::Null(NullKind::Null), |vals| vals[i].clone()));
                }
                out.push(row);
            }
            out
        };
        const TORECORDS_PAR_MIN_ROWS: usize = 50_000;
        const TORECORDS_PAR_MIN_PER_WORKER: usize = 16_384;
        let workers = if n >= TORECORDS_PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism()
                .min(16)
                .min(n / TORECORDS_PAR_MIN_PER_WORKER)
                .max(1)
        } else {
            1
        };
        if workers >= 2 {
            let chunk = n.div_ceil(workers);
            let build = &build;
            let mut parts: Vec<Vec<Vec<Scalar>>> = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(workers);
                let mut start = 0;
                while start < n {
                    let end = (start + chunk).min(n);
                    handles.push(scope.spawn(move || build(start, end)));
                    start = end;
                }
                handles
                    .into_iter()
                    .map(|h| h.join().expect("to_records thread"))
                    .collect()
            });
            let mut records = Vec::with_capacity(n);
            for p in &mut parts {
                records.append(p);
            }
            records
        } else {
            build(0, n)
        }
    }

    /// Convert numeric columns to a 2D `Vec<Vec<f64>>`.
    ///
    /// Matches `df.to_numpy()`. Rows are outer, columns are inner.
    /// Non-numeric values become `f64::NAN`.
    pub fn to_numpy_2d(&self) -> Vec<Vec<f64>> {
        let n = self.len();
        let num_cols: Vec<&str> = self
            .column_order
            .iter()
            .filter(|c| {
                let dt = self.columns[*c].dtype();
                dt == DType::Int64 || dt == DType::Float64
            })
            .map(|c| c.as_str())
            .collect();

        // Typed fast path: when every numeric column is an all-valid Float64 (borrow
        // its slice) or an all-valid Int64 (materialize the `v as f64` view once),
        // build each row by direct indexing instead of the per-cell `.values()`
        // Scalar materialization + `to_f64` dispatch. Bit-identical: this copies each
        // value (no fold), so `col[i]` == `to_f64(Int64(v)) == v as f64` for Int64,
        // == the stored f64 (including a valid NaN, which `to_f64().unwrap_or(NaN)`
        // also yields) for Float64. A nullable column (as_f64_slice/as_i64_slice
        // decline) breaks to the generic per-cell path, which maps its missing cells
        // to NaN.
        'typed: {
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(num_cols.len());
            for &c in &num_cols {
                let col = &self.columns[c];
                if col.as_f64_slice().is_some() {
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'typed;
                }
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = num_cols
                .iter()
                .zip(&is_owned)
                .map(|(&c, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[c]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            let mut result = Vec::with_capacity(n);
            for i in 0..n {
                result.push(col_f64.iter().map(|c| c[i]).collect());
            }
            return result;
        }

        let mut result = Vec::with_capacity(n);
        for i in 0..n {
            let row: Vec<f64> = num_cols
                .iter()
                .map(|&col_name| {
                    let val = &self.columns[col_name].values()[i];
                    val.to_f64().unwrap_or(f64::NAN)
                })
                .collect();
            result.push(row);
        }
        result
    }

    /// Iterate over columns as `(column_name, Series)` pairs.
    ///
    /// Matches `df.items()` / `df.iteritems()`.
    ///
    /// # Panics
    ///
    /// Panics if `self.column_order` references a column that is absent from
    /// `self.columns`, which indicates internal DataFrame metadata corruption.
    pub fn items(&self) -> Result<Vec<(String, Series)>, FrameError> {
        let mut result = Vec::with_capacity(self.column_order.len());
        for col_name in &self.column_order {
            let col = self
                .columns
                .get(col_name)
                .expect("column in order must exist");
            let series = Series::new(col_name.clone(), self.index.clone(), col.clone())?;
            result.push((col_name.clone(), series));
        }
        Ok(result)
    }

    /// Alias for items (deprecated in pandas but kept for compatibility).
    #[deprecated(note = "use items() instead")]
    pub fn iteritems(&self) -> Result<Vec<(String, Series)>, FrameError> {
        self.items()
    }

    /// Assign new or overwrite existing columns.
    ///
    /// Matches `df.assign(**kwargs)`. Takes a list of (column_name, Column) pairs.
    /// Existing columns are replaced; new columns are appended.
    pub fn assign(&self, assignments: Vec<(&str, Column)>) -> Result<Self, FrameError> {
        let mut new_columns = self.columns.clone();
        let mut new_order = self.column_order.clone();

        for (name, col) in assignments {
            if col.len() != self.len() {
                return Err(FrameError::LengthMismatch {
                    index_len: self.len(),
                    column_len: col.len(),
                });
            }
            let name_str = name.to_owned();
            if !new_columns.contains_key(&name_str) {
                new_order.push(name_str.clone());
            }
            new_columns.insert(name_str, col);
        }

        Self::new_with_column_order(self.index.clone(), new_columns, new_order)
    }

    /// Assign new columns computed from the DataFrame via closures.
    ///
    /// Matches `df.assign(col=lambda df: ...)`. Each closure receives a
    /// reference to the *current* DataFrame (including previously-assigned
    /// columns in this call) and must return a `Column` of the correct length.
    #[allow(clippy::type_complexity)]
    pub fn assign_fn(
        &self,
        assignments: Vec<(&str, Box<dyn Fn(&DataFrame) -> Result<Column, FrameError>>)>,
    ) -> Result<Self, FrameError> {
        let mut current = self.clone();
        for (name, func) in assignments {
            let col = func(&current)?;
            if col.len() != current.len() {
                return Err(FrameError::LengthMismatch {
                    index_len: current.len(),
                    column_len: col.len(),
                });
            }
            let name_str = name.to_owned();
            if !current.columns.contains_key(&name_str) {
                current.column_order.push(name_str.clone());
            }
            current.columns.insert(name_str, col);
        }
        Ok(current)
    }

    /// Apply a transformation function to the DataFrame.
    ///
    /// Matches `df.pipe(func)`. The function receives a reference to `self`
    /// and returns a new DataFrame.
    pub fn pipe<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: FnOnce(&Self) -> Result<Self, FrameError>,
    {
        func(self)
    }

    /// Rank values in each column of the DataFrame.
    ///
    /// Applies `Series::rank` independently to each column.
    pub fn rank(&self, method: &str, ascending: bool, na_option: &str) -> Result<Self, FrameError> {
        self.rank_with_pct(method, ascending, na_option, false)
    }

    /// Rank values in each column of the DataFrame and optionally scale them to percentile ranks.
    pub fn rank_with_pct(
        &self,
        method: &str,
        ascending: bool,
        na_option: &str,
        pct: bool,
    ) -> Result<Self, FrameError> {
        // Column-parallel rank (br-frankenpandas-rank-par): each column ranks
        // INDEPENDENTLY (no cross-column state), so spreading the columns across
        // worker threads is bit-identical to the serial loop — every column is
        // ranked by the exact same `Series::rank_with_pct` and the results are
        // keyed by column name, so execution order cannot change the output.
        // Ranking is per-column O(n log n) / O(n) compute, the dominant cost at
        // scale; on a many-core box the serial loop left all but one core idle.
        // Gated so small frames keep the zero-overhead serial path.
        const RANK_PAR_MIN_COLS: usize = 2;
        const RANK_PAR_MIN_VALUES: usize = 16_384;

        let rank_one = |col_name: &str| -> Result<(String, Column), FrameError> {
            let col = self.columns.get(col_name).ok_or_else(|| {
                FrameError::CompatibilityRejected(format!("missing column: {col_name}"))
            })?;
            let series = Series::new(col_name, self.index.clone(), col.clone())?;
            let ranked = series.rank_with_pct(method, ascending, na_option, pct)?;
            Ok((col_name.to_string(), ranked.column().clone()))
        };

        let ncols = self.column_order.len();
        let worker_count = if ncols >= RANK_PAR_MIN_COLS
            && ncols.saturating_mul(self.len()) >= RANK_PAR_MIN_VALUES
        {
            fp_columnar::cached_available_parallelism().min(ncols)
        } else {
            1
        };

        let ranked_cols: BTreeMap<String, Column> = if worker_count >= 2 {
            let next = std::sync::atomic::AtomicUsize::new(0);
            std::thread::scope(|scope| -> Result<BTreeMap<String, Column>, FrameError> {
                let mut handles = Vec::with_capacity(worker_count);
                for _ in 0..worker_count {
                    let next = &next;
                    let rank_one = &rank_one;
                    handles.push(scope.spawn(
                        move || -> Result<Vec<(String, Column)>, FrameError> {
                            let mut out = Vec::new();
                            loop {
                                let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                if i >= self.column_order.len() {
                                    break;
                                }
                                out.push(rank_one(&self.column_order[i])?);
                            }
                            Ok(out)
                        },
                    ));
                }
                let mut ranked_cols = BTreeMap::new();
                for handle in handles {
                    let worker_out = handle.join().map_err(|_| {
                        FrameError::CompatibilityRejected("rank worker thread panicked".into())
                    })??;
                    ranked_cols.extend(worker_out);
                }
                Ok(ranked_cols)
            })?
        } else {
            let mut ranked_cols = BTreeMap::new();
            for col_name in &self.column_order {
                let (name, col) = rank_one(col_name)?;
                ranked_cols.insert(name, col);
            }
            ranked_cols
        };

        Ok(Self {
            columns: ranked_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Ranks values across columns for each row independently.
    ///
    /// Matches `pd.DataFrame.rank(axis=1)`.
    pub fn rank_axis1(
        &self,
        method: &str,
        ascending: bool,
        na_option: &str,
    ) -> Result<Self, FrameError> {
        self.rank_axis1_with_pct(method, ascending, na_option, false)
    }

    /// Rank values across columns for each row and optionally scale them to percentile ranks.
    pub fn rank_axis1_with_pct(
        &self,
        method: &str,
        ascending: bool,
        na_option: &str,
        pct: bool,
    ) -> Result<Self, FrameError> {
        let n_cols = self.column_order.len();
        let n_rows = self.len();

        if n_cols == 0 {
            return Ok(self.clone());
        }

        // Vectorized average-rank fast path: for the common case (method=
        // "average", not pct, all columns all-valid Float64 with no NaN), rank
        // each row's m values with NO per-row Series build. For value b among the
        // row's values: rank = count(a < b) + (count(a == b) + 1)/2 (the standard
        // average rank; a > b for ascending=false). One pass over rows, O(m^2) per
        // row in registers. Bit-identical to the per-row Series average rank
        // (integer less/equal counts -> the same fractional ranks; f64 < / ==
        // match the to_f64 comparator; no NaN => na_option moot; output is f64).
        'fast: {
            if pct || !matches!(method, "average" | "min" | "max" | "first") {
                break 'fast;
            }
            // Each column must be an all-valid Float64 (borrow its slice) or an
            // all-valid Int64 column (materialize the `v as f64` view once). Row rank
            // always outputs Float64, so an Int64 column is dtype-correct; the
            // less/equal pairwise counts over `v as f64` == over the Scalar values the
            // generic per-row Series-rank fallback would compare (`to_f64(Int64(v)) ==
            // v as f64`, all-valid ⇒ na_option moot), so the ranks are bit-identical —
            // this just skips that fallback's per-row Series build + Scalar dispatch.
            // Any other-dtype column (Utf8, nullable) breaks to the generic path.
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(n_cols);
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.as_f64_slice().is_some() {
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'fast;
                }
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = self
                .column_order
                .iter()
                .zip(&is_owned)
                .map(|(name, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[name]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            if col_f64.iter().any(|s| s.iter().any(|x| x.is_nan())) {
                break 'fast;
            }
            // average=less+(equal+1)/2, min=less+1, max=less+equal,
            // first=less+(equal at positions j<=i) — all from the per-row pairwise
            // counts. Verified vs pandas (incl ties).
            // Each output row's ranks depend ONLY on that row's m values — the row
            // loop is embarrassingly parallel and CPU-bound (O(n_rows * n_cols^2)
            // branchless pairwise counts over register-resident row values, tiny
            // output writes). Compute contiguous row ranges in per-thread column
            // buffers, then concatenate in row order. Bit-identical: each worker runs
            // the identical per-row kernel; ascending worker ranges preserve row order.
            // Same partition+concat lever as the parallelized reshape/to_dict builds;
            // CPU-bound but wins with core headroom (single-threaded below the gate).
            let rank_range = |lo: usize, hi: usize| -> Vec<Vec<f64>> {
                let mut out: Vec<Vec<f64>> =
                    (0..n_cols).map(|_| Vec::with_capacity(hi - lo)).collect();
                let mut rowvals = vec![0.0_f64; n_cols];
                for row in lo..hi {
                    for (i, c) in col_f64.iter().enumerate() {
                        rowvals[i] = c[row];
                    }
                    for i in 0..n_cols {
                        let b = rowvals[i];
                        let mut less = 0.0_f64;
                        let mut equal = 0.0_f64;
                        for &a in &rowvals {
                            let lt = if ascending { a < b } else { a > b };
                            less += f64::from(u8::from(lt));
                            equal += f64::from(u8::from(a == b));
                        }
                        let rank = match method {
                            "min" => less + 1.0,
                            "max" => less + equal,
                            // "first": ties ranked by position — count equals at j<=i.
                            // Only this (less common) method pays the extra inner pass.
                            "first" => {
                                let mut eli = 0.0_f64;
                                for (j, &a) in rowvals.iter().enumerate() {
                                    eli += f64::from(u8::from(a == b) & u8::from(j <= i));
                                }
                                less + eli
                            }
                            _ => less + (equal + 1.0) / 2.0,
                        };
                        out[i].push(rank);
                    }
                }
                out
            };
            const RANK_PAR_MIN_ROWS: usize = 50_000;
            const RANK_PAR_MIN_PER_WORKER: usize = 16_384;
            let rank_workers = if n_rows >= RANK_PAR_MIN_ROWS {
                fp_columnar::cached_available_parallelism()
                    .min(16)
                    .min(n_rows / RANK_PAR_MIN_PER_WORKER)
                    .max(1)
            } else {
                1
            };
            let mut out: Vec<Vec<f64>> = if rank_workers >= 2 {
                let chunk = n_rows.div_ceil(rank_workers);
                let rank_range = &rank_range;
                let parts: Vec<Vec<Vec<f64>>> = std::thread::scope(|scope| {
                    let mut handles = Vec::with_capacity(rank_workers);
                    let mut start = 0;
                    while start < n_rows {
                        let end = (start + chunk).min(n_rows);
                        handles.push(scope.spawn(move || rank_range(start, end)));
                        start = end;
                    }
                    handles
                        .into_iter()
                        .map(|h| h.join().expect("rank_axis1 thread"))
                        .collect()
                });
                let mut out: Vec<Vec<f64>> =
                    (0..n_cols).map(|_| Vec::with_capacity(n_rows)).collect();
                for part in &parts {
                    for (i, col) in part.iter().enumerate() {
                        out[i].extend_from_slice(col);
                    }
                }
                out
            } else {
                rank_range(0, n_rows)
            };
            let mut out_columns = BTreeMap::new();
            for (i, name) in self.column_order.iter().enumerate() {
                out_columns.insert(
                    name.clone(),
                    Column::from_f64_values(std::mem::take(&mut out[i])),
                );
            }
            return Ok(Self {
                columns: out_columns.into(),
                column_order: self.column_order.clone(),
                index: self.index.clone(),
                column_multiindex: self.column_multiindex.clone(),
                row_multiindex: self.row_multiindex.clone(),
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        let mut out_cols_data: Vec<Vec<Scalar>> =
            (0..n_cols).map(|_| Vec::with_capacity(n_rows)).collect();

        for row_idx in 0..n_rows {
            // Collect row values
            let mut row_vals = Vec::with_capacity(n_cols);
            for col_name in &self.column_order {
                row_vals.push(self.columns[col_name].values()[row_idx].clone());
            }

            // Rank the row (using a temporary Series to access the same logic)
            let row_idx_labels: Vec<fp_index::IndexLabel> = (0..n_cols as i64)
                .map(fp_index::IndexLabel::Int64)
                .collect();
            let row_series = Series::from_values("row", row_idx_labels, row_vals)?;
            let ranked_row_series = row_series.rank_with_pct(method, ascending, na_option, pct)?;

            // Scatter back to columns
            for (col_idx, val) in ranked_row_series.column().values().iter().enumerate() {
                out_cols_data[col_idx].push(val.clone());
            }
        }

        let mut out_columns = BTreeMap::new();
        for (i, name) in self.column_order.iter().enumerate() {
            let col = Column::from_values(std::mem::take(&mut out_cols_data[i]))?;
            out_columns.insert(name.clone(), col);
        }

        Ok(Self {
            columns: out_columns.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Unpivot (melt) a DataFrame from wide to long format.
    ///
    /// `id_vars`: columns to keep as identifiers
    /// `value_vars`: columns to unpivot (if empty, uses all non-id columns)
    /// `var_name`: name for the variable column (default "variable")
    /// `value_name`: name for the value column (default "value")
    pub fn melt(
        &self,
        id_vars: &[&str],
        value_vars: &[&str],
        var_name: Option<&str>,
        value_name: Option<&str>,
    ) -> Result<Self, FrameError> {
        let var_col_name = var_name.unwrap_or("variable");
        let val_col_name = value_name.unwrap_or("value");

        // Determine value_vars: if empty, use all non-id columns
        let actual_value_vars: Vec<String> = if value_vars.is_empty() {
            self.column_order
                .iter()
                .filter(|c| !id_vars.contains(&c.as_str()))
                .cloned()
                .collect()
        } else {
            value_vars.iter().map(|s| (*s).to_string()).collect()
        };

        // Validate columns exist
        for col in id_vars {
            if !self.columns.contains_key(col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "missing column: {col}"
                )));
            }
        }
        for col in &actual_value_vars {
            if !self.columns.contains_key(col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "missing column: {col}"
                )));
            }
        }

        let n_rows = self.index.len();
        let n_value_vars = actual_value_vars.len();
        let total_rows = n_rows * n_value_vars;

        // Build id columns (repeated for each value var)
        let mut result_cols: BTreeMap<String, Column> = BTreeMap::new();
        let mut col_order = Vec::new();

        for &id_col in id_vars {
            let src = &self.columns[id_col];
            // Typed repetition (br-frankenpandas-1q4q4): tile the contiguous
            // i64/f64 buffer `n_value_vars` times instead of materializing the
            // column to `Vec<Scalar>` (32 B/cell) and tiling that. Bit-identical
            // (`from_i64_values`/`from_f64_values` == `Column::new` over the same
            // typed Scalars); other dtypes keep the Scalar tiling.
            let col = if let Some(s) = src.as_i64_slice() {
                let mut rep = Vec::with_capacity(total_rows);
                for _ in 0..n_value_vars {
                    rep.extend_from_slice(s);
                }
                Column::from_i64_values_owned(rep)
            } else if let Some(s) = src.as_f64_slice() {
                let mut rep = Vec::with_capacity(total_rows);
                for _ in 0..n_value_vars {
                    rep.extend_from_slice(s);
                }
                Column::from_f64_values(rep)
            } else {
                let mut repeated = Vec::with_capacity(total_rows);
                for _ in 0..n_value_vars {
                    repeated.extend_from_slice(src.values());
                }
                Column::new(src.dtype(), repeated)?
            };
            result_cols.insert(id_col.to_string(), col);
            col_order.push(id_col.to_string());
        }

        // Build the "variable" column as a contiguous Utf8 buffer: each value-var
        // name repeated n_rows times. Avoids total_rows `Scalar::Utf8(String)`
        // allocations (one byte-append + offset per row instead). All-valid;
        // bit-identical values to the Scalar path.
        let var_bytes_cap: usize =
            actual_value_vars.iter().map(String::len).sum::<usize>() * n_rows;
        let mut var_bytes = Vec::with_capacity(var_bytes_cap);
        let mut var_offsets = Vec::with_capacity(total_rows + 1);
        var_offsets.push(0usize);
        // Each value-var name is simply repeated n_rows times, so the old per-row
        // `extend_from_slice + push` (total_rows tiny interleaved memcpies + pushes) is
        // wasteful: build each segment's bytes by DOUBLING (`extend_from_within` — a
        // few large memcpies, no temp alloc) and emit its offsets ARITHMETICALLY
        // (`seg_start + k*l`, a tight dependency-free loop). Bit-identical: the bytes
        // are `vb` repeated n_rows times and offset k is where row k's name ends
        // (`seg_start + k*l`), exactly what the per-row form produced.
        for vv in &actual_value_vars {
            let vb = vv.as_bytes();
            let l = vb.len();
            let seg_start = var_bytes.len();
            let seg_len = l * n_rows;
            // GUARD ON seg_len, NOT ON `l`. br-frankenpandas-sn8l4.
            //
            // The old guard was `if l == 0`, which misses n_rows == 0: an EMPTY
            // frame still reached the code below, where `extend_from_slice(vb)`
            // writes `l` bytes unconditionally while `(1..=n_rows)` is an empty
            // range that pushes NO offsets. The column then had bytes.len() == l
            // with offsets still [0], violating the contiguous-Utf8 invariant
            // `*offsets.last() == bytes.len()` and tripping the debug_assert in
            // ScalarValues::lazy_contiguous_utf8 — which compiles OUT of release,
            // so a release build shipped the malformed column silently.
            //
            // `seg_len == 0` covers both degenerate cases: an empty variable name
            // (l == 0) and an empty frame (n_rows == 0). In both the segment
            // contributes zero bytes, and the loop below pushes exactly n_rows
            // offsets — which is zero when there are no rows.
            if seg_len == 0 {
                for _ in 0..n_rows {
                    var_offsets.push(seg_start);
                }
                continue;
            }
            var_bytes.extend_from_slice(vb);
            while var_bytes.len() - seg_start < seg_len {
                let have = var_bytes.len() - seg_start;
                let take = have.min(seg_len - have);
                var_bytes.extend_from_within(seg_start..seg_start + take);
            }
            var_offsets.extend((1..=n_rows).map(|k| seg_start + k * l));
        }
        result_cols.insert(
            var_col_name.to_string(),
            Column::from_utf8_contiguous(var_bytes, var_offsets),
        );
        col_order.push(var_col_name.to_string());

        // Build the "value" column. Typed NUMERIC fast path: when every value var
        // is a dense all-valid numeric slice, concatenate the raw buffers (f64
        // direct, i64 promoted to f64 when any value var is Float64) and MOVE the
        // result out — no per-cell Scalar clone/cast that the generic path pays.
        // Bit-identical: for numeric columns `common_dtype` is Float64 iff any is
        // Float64 (else Int64), and `i as f64` is exactly Column::new's Int64→
        // Float64 cast; all-valid slices mean nothing is skipped. Mixed i64/f64 and
        // all-i64 value_vars previously fell to the Vec<Scalar> path (32 B/cell).
        enum NumSlice<'a> {
            F64(&'a [f64]),
            I64(&'a [i64]),
        }
        let numeric_slices: Option<Vec<NumSlice>> = actual_value_vars
            .iter()
            .map(|name| {
                let c = &self.columns[name];
                if let Some(s) = c.as_f64_slice() {
                    Some(NumSlice::F64(s))
                } else {
                    c.as_i64_slice().map(NumSlice::I64)
                }
            })
            .collect();
        let value_column = if let Some(slices) = numeric_slices {
            if slices.iter().any(|s| matches!(s, NumSlice::F64(_))) {
                let mut value_vals: Vec<f64> = Vec::with_capacity(total_rows);
                for s in &slices {
                    match s {
                        NumSlice::F64(x) => value_vals.extend_from_slice(x),
                        NumSlice::I64(x) => value_vals.extend(x.iter().map(|&i| i as f64)),
                    }
                }
                Column::from_f64_values_owned(value_vals)
            } else {
                let mut value_vals: Vec<i64> = Vec::with_capacity(total_rows);
                for s in &slices {
                    if let NumSlice::I64(x) = s {
                        value_vals.extend_from_slice(x);
                    }
                }
                Column::from_i64_values_owned(value_vals)
            }
        } else {
            let mut value_vals = Vec::with_capacity(total_rows);
            for vv in &actual_value_vars {
                let src = &self.columns[vv];
                value_vals.extend_from_slice(src.values());
            }
            // Determine a common dtype across all melted value columns so mixed
            // numeric inputs promote the same way pandas does.
            let value_dtype = if actual_value_vars.is_empty() {
                DType::Float64
            } else {
                actual_value_vars
                    .iter()
                    .map(|name| self.columns[name].dtype())
                    .try_fold(DType::Null, common_dtype)
                    .map_err(|err| FrameError::CompatibilityRejected(err.to_string()))?
            };
            Column::new(value_dtype, value_vals)?
        };
        result_cols.insert(val_col_name.to_string(), value_column);
        col_order.push(val_col_name.to_string());

        // Build the new index (0..total_rows) as a lazy unit-range Int64 backing
        // instead of materializing total_rows IndexLabel::Int64 allocations.
        let new_index = Index::new_known_unique_int64_unit_range(0, total_rows);

        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index: new_index,
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Pivot table: aggregate values grouped by index and column keys.
    ///
    /// `values`: column containing values to aggregate
    /// `index_col`: column to use as the new row index
    /// `columns_col`: column whose unique values become new columns
    /// `aggfunc`: aggregation function ("mean", "sum", "count", "size", "min", "max", "first", "last")
    pub fn pivot_table(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
    ) -> Result<Self, FrameError> {
        self.pivot_table_with_dropna(values, index_col, columns_col, aggfunc, true)
    }

    /// Pivot table with explicit control over whether missing index/column
    /// keys are dropped before aggregation.
    ///
    /// Matches `df.pivot_table(..., dropna=...)` for the core single-value
    /// case. The default `pivot_table()` wrapper uses `dropna=true`.
    pub fn pivot_table_with_dropna(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        dropna: bool,
    ) -> Result<Self, FrameError> {
        // Validate columns
        for col in [values, index_col, columns_col] {
            if !self.columns.contains_key(col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "missing column: {col}"
                )));
            }
        }

        let val_col = &self.columns[values];
        let idx_col = &self.columns[index_col];
        let cols_col = &self.columns[columns_col];
        let n_rows = self.index.len();

        // Typed dense fast path (br-frankenpandas-1q4q4): all-valid axis keys
        // (Int64 / Datetime64 / Utf8, independently per axis so MIXED axes work)
        // + all-valid Float64 values + an online aggfunc (sum/mean/count/size/
        // min/max). Each axis is factorized to dense sorted-rank u32 codes once,
        // then rows scatter-accumulate into a dense R×C buffer in ROW ORDER —
        // bit-identical to the generic per-cell `vals.iter()` fold — bypassing
        // the three per-row `values()` Scalar materializations, the
        // `(ScalarKey,ScalarKey)->Vec<f64>` groups map, and the per-cell
        // re-aggregate. All-valid keys/values make `dropna` a no-op.
        if matches!(
            aggfunc,
            "sum" | "mean" | "count" | "size" | "min" | "max" | "var" | "std" | "median"
        ) && let Some(val_f64) = pivot_value_f64(val_col)
            && let Some((ri_codes, idx_labels, _)) = pivot_axis_dense_codes(idx_col)
            && let Some((ci_codes, _, col_names)) = pivot_axis_dense_codes(cols_col)
        {
            let val_f64 = val_f64.as_ref();
            let n_idx = idx_labels.len();
            let (result_cols, result_col_order) = if aggfunc == "median" {
                // Holistic: scatter each cell's values (skipping the 3 Scalar
                // materializations + ScalarKey tuple-hash of the generic path),
                // then sort per cell — bit-identical multiset/formula.
                pivot_dense_build_median(&ri_codes, &ci_codes, val_f64, n_idx, col_names)
            } else {
                pivot_dense_build(&ri_codes, &ci_codes, val_f64, aggfunc, n_idx, col_names)
            };
            return Ok(Self {
                columns: result_cols.into(),
                column_order: result_col_order.into(),
                index: Index::new(idx_labels).rename_index(Some(index_col)),
                column_multiindex: None,
                row_multiindex: None,
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        // Hoist the key Scalar slices ONCE — values() was called per-row across
        // the unique-collection AND scatter loops (n_rows*~2 calls). The value
        // slice is materialized lazily per branch below: the online-aggfunc
        // dense path borrows it typed via `as_f64_slice` when possible and
        // only falls back to `values()` for nullable/non-Float64 value columns.
        let idx_vals = idx_col.values();
        let cols_vals = cols_col.values();

        // Collect unique index values (preserving first-seen order)
        let mut idx_order_keys: Vec<ScalarKey<'_>> = Vec::new();
        let mut idx_labels: Vec<IndexLabel> = Vec::new();
        let mut idx_seen: FxHashSet<ScalarKey<'_>> = FxHashSet::default();
        for val in idx_vals.iter().take(n_rows) {
            let Some(key) = (if dropna {
                scalar_key_skip_missing(val)
            } else {
                Some(scalar_key_allow_missing(val))
            }) else {
                continue;
            };
            if idx_seen.insert(key) {
                idx_order_keys.push(key);
                // br-frankenpandas-9m9zf: pivot ROW labels are an index, and
                // pandas keeps them typed (measured: pivot_table index float,
                // columns bool). The COLUMN side still goes through
                // scalar_to_pivot_column_name -> the stringifying mapper, because
                // FP column names are String.
                idx_labels.push(scalar_to_typed_index_label(val));
            }
        }

        // Collect unique column values (preserving first-seen order)
        let mut col_order_keys: Vec<ScalarKey<'_>> = Vec::new();
        let mut col_names: Vec<String> = Vec::new();
        let mut col_seen: FxHashSet<ScalarKey<'_>> = FxHashSet::default();
        for val in cols_vals.iter().take(n_rows) {
            let Some(key) = (if dropna {
                scalar_key_skip_missing(val)
            } else {
                Some(scalar_key_allow_missing(val))
            }) else {
                continue;
            };
            if col_seen.insert(key) {
                col_order_keys.push(key);
                let label = scalar_to_value_counts_index_label(val);
                let name = match label {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => s,
                    IndexLabel::Timedelta64(ns) => Timedelta::format(ns),
                    IndexLabel::Datetime64(ns) => format_datetime_ns(ns),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    null @ IndexLabel::Null(_) => null.to_string(),
                };
                col_names.push(name);
            }
        }

        // pandas pivot_table sorts BOTH axes ascending with nulls last
        // (sort=True default; verified live 2.2.3: rows ['z','a'] -> ['a','z'],
        // numeric [3, nan, 1] -> [1.0, 3.0, nan]) — first-seen order is only
        // pandas' sort=False behavior (br-frankenpandas-s3x7k). Co-sort each
        // axis's keys with their labels/names so the positional
        // correspondence the scatter relies on is preserved; the stable sort
        // keeps first-seen order for cross-type ties, and scalar_key_cmp
        // already ranks Null greater than every concrete key.
        let mut idx_pairs: Vec<(ScalarKey<'_>, IndexLabel)> =
            idx_order_keys.into_iter().zip(idx_labels).collect();
        idx_pairs.sort_by(|a, b| scalar_key_cmp(&a.0, &b.0));
        let (idx_order_keys, idx_labels): (Vec<_>, Vec<_>) = idx_pairs.into_iter().unzip();
        let mut col_pairs: Vec<(ScalarKey<'_>, String)> =
            col_order_keys.into_iter().zip(col_names).collect();
        col_pairs.sort_by(|a, b| scalar_key_cmp(&a.0, &b.0));
        let (col_order_keys, col_names): (Vec<_>, Vec<_>) = col_pairs.into_iter().unzip();

        let n_idx = idx_order_keys.len();
        let n_col = col_order_keys.len();
        let row_idx_of: HashMap<ScalarKey<'_>, usize> = idx_order_keys
            .iter()
            .enumerate()
            .map(|(i, k)| (*k, i))
            .collect();
        let col_idx_of: HashMap<ScalarKey<'_>, usize> = col_order_keys
            .iter()
            .enumerate()
            .map(|(i, k)| (*k, i))
            .collect();

        let mut result_cols = BTreeMap::new();
        let mut result_col_order = Vec::with_capacity(n_col);

        // Online-aggfunc dense scatter (sum/mean/count/size for ANY key dtype):
        // skip the `(ScalarKey,ScalarKey)->Vec<f64>` groups map (one heap Vec
        // per cell + 1M pushes) and the per-cell re-aggregate. Each row scatters
        // straight into a dense column-major R×C accumulator in ROW ORDER, so
        // the per-cell f64 sum is folded left-to-right exactly as the generic
        // `vals.iter().sum()` — bit-identical. `size` counts every keyed row;
        // sum/mean/count gate on a non-null value (matching the generic
        // `val.to_f64()` push). Absent cell -> Null(NullKind::NaN) via
        // from_f64_values_with_validity (== the generic Scalar::Null(NaN) fill).
        // The Int64-keyed all-valid case already returned via the typed path
        // above; this widens the win to Utf8/Float64/Datetime keys.
        if matches!(aggfunc, "sum" | "mean" | "count" | "size") {
            let cells = n_idx.saturating_mul(n_col);
            let needs_sum = matches!(aggfunc, "sum" | "mean");
            let is_size = aggfunc == "size";
            let val_f64 = val_col.as_f64_slice();
            let val_vals_fallback = if is_size || val_f64.is_some() {
                None
            } else {
                Some(val_col.values())
            };
            let mut sums = if needs_sum {
                vec![0.0f64; cells]
            } else {
                Vec::new()
            };
            let mut counts = vec![0u64; cells];
            for i in 0..n_rows {
                let Some(ik) = (if dropna {
                    scalar_key_skip_missing(&idx_vals[i])
                } else {
                    Some(scalar_key_allow_missing(&idx_vals[i]))
                }) else {
                    continue;
                };
                let Some(ck) = (if dropna {
                    scalar_key_skip_missing(&cols_vals[i])
                } else {
                    Some(scalar_key_allow_missing(&cols_vals[i]))
                }) else {
                    continue;
                };
                let cell = col_idx_of[&ck] * n_idx + row_idx_of[&ik];
                if is_size {
                    counts[cell] += 1;
                    continue;
                }
                // sum/mean/count: only non-null values contribute (mirrors the
                // generic `val_vals[i].to_f64()` push gate).
                let v = match val_f64 {
                    Some(slice) => Some(slice[i]),
                    None => val_vals_fallback
                        .as_ref()
                        .and_then(|vv| vv[i].to_f64().ok()),
                };
                if let Some(v) = v {
                    if needs_sum {
                        sums[cell] += v;
                    }
                    counts[cell] += 1;
                }
            }

            for (ci, col_name) in col_names.iter().enumerate() {
                let base = ci * n_idx;
                let mut data = vec![0.0f64; n_idx];
                let mut validity = ValidityMask::all_invalid(n_idx);
                for ri in 0..n_idx {
                    let c = counts[base + ri];
                    if c == 0 {
                        continue;
                    }
                    data[ri] = if needs_sum {
                        if aggfunc == "sum" {
                            sums[base + ri]
                        } else {
                            sums[base + ri] / c as f64
                        }
                    } else {
                        c as f64 // count / size
                    };
                    validity.set(ri, true);
                }
                result_cols.insert(
                    col_name.clone(),
                    Column::from_f64_values_with_validity(data, validity),
                );
                result_col_order.push(col_name.clone());
            }

            return Ok(Self {
                columns: result_cols.into(),
                column_order: result_col_order.into(),
                index: Index::new(idx_labels).rename_index(Some(index_col)),
                column_multiindex: None,
                row_multiindex: None,
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        // Build groups: (idx_key, col_key) -> Vec<f64>
        let val_vals = val_col.values();
        let mut groups: FxHashMap<(ScalarKey<'_>, ScalarKey<'_>), Vec<f64>> = FxHashMap::default();
        for i in 0..n_rows {
            let Some(ik) = (if dropna {
                scalar_key_skip_missing(&idx_vals[i])
            } else {
                Some(scalar_key_allow_missing(&idx_vals[i]))
            }) else {
                continue;
            };
            let Some(ck) = (if dropna {
                scalar_key_skip_missing(&cols_vals[i])
            } else {
                Some(scalar_key_allow_missing(&cols_vals[i]))
            }) else {
                continue;
            };
            if pivot_table_counts_rows(aggfunc) {
                groups.entry((ik, ck)).or_default().push(0.0);
            } else if let Ok(v) = val_vals[i].to_f64() {
                groups.entry((ik, ck)).or_default().push(v);
            }
        }

        // Aggregate + build result columns by SCATTER: the dense R×C table is
        // mostly empty, so instead of looking up every cell in `groups`
        // (O(R·C) (ScalarKey,ScalarKey) hashes) start every cell at NaN/Null and
        // write only the (<= n) observed groups into place. Each cell's value is
        // the aggregate of its own (unchanged, row-order) value list, so this is
        // bit-identical to the per-cell lookup. Kept Scalar-based so a present
        // cell whose aggregate is NaN stays Float64(NaN), distinct from the
        // Null(NaN) of an absent cell (a typed f64 column would conflate them).
        let mut mat: Vec<Vec<Scalar>> = (0..n_col)
            .map(|_| vec![Scalar::Null(NullKind::NaN); n_idx])
            .collect();
        for ((ik, ck), vals) in &groups {
            let ci = col_idx_of[ck];
            let ri = row_idx_of[ik];
            mat[ci][ri] = Scalar::Float64(pivot_table_agg_value(aggfunc, vals)?);
        }

        for (idx, _ck) in col_order_keys.iter().enumerate() {
            let col_name = col_names[idx].clone();
            let col_vals = std::mem::take(&mut mat[idx]);
            result_cols.insert(col_name.clone(), Column::new(DType::Float64, col_vals)?);
            result_col_order.push(col_name);
        }

        // Build index from idx_order
        let new_labels = idx_labels;

        // Per br-frankenpandas-15kfm: pandas pivot_table sets index name
        // to the pivot index column name. Sister to br-xb0ra (pivot).
        Ok(Self {
            columns: result_cols.into(),
            column_order: result_col_order.into(),
            index: Index::new(new_labels).rename_index(Some(index_col)),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Create a pivot table with a fill_value for missing cells.
    ///
    /// Matches `df.pivot_table(values, index, columns, aggfunc, fill_value=v)`.
    pub fn pivot_table_fill(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        fill_value: f64,
    ) -> Result<Self, FrameError> {
        let mut result = self.pivot_table(values, index_col, columns_col, aggfunc)?;
        // Replace NaN cells with fill_value
        for col_name in &result.column_order {
            let col = &result.columns[col_name];
            let filled: Vec<Scalar> = col
                .values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        Scalar::Float64(fill_value)
                    } else {
                        v.clone()
                    }
                })
                .collect();
            result
                .columns
                .insert(col_name.clone(), Column::new(DType::Float64, filled)?);
        }
        Ok(result)
    }

    /// Create a pivot table with multiple value columns.
    ///
    /// Matches `df.pivot_table(values=['col1','col2'], index=..., columns=..., aggfunc=...)`.
    /// Column names in the result are formatted as "value_column_pivot_value"
    /// (e.g. "sales_East", "profit_East").
    ///
    /// ⚠️ THE VALUE GROUPS COME OUT IN NAME ORDER, NOT ARGUMENT ORDER, and that
    /// is pandas' rule rather than a convenience. br-frankenpandas-eay9h.
    /// MEASURED, live pandas 2.2.3, one frame, both spellings of `values`:
    ///
    /// | call | result |
    /// |---|---|
    /// | `values=["sales","profit"]  sort=True`  | `profit_A profit_B sales_A sales_B` |
    /// | `values=["profit","sales"]  sort=True`  | `profit_A profit_B sales_A sales_B` |
    /// | `values=["sales","profit"]  sort=False` | `sales_A sales_B profit_A profit_B` |
    /// | `values=["profit","sales"]  sort=False` | `sales_A sales_B profit_A profit_B` |
    ///
    /// pandas DOES NOT MOVE when the caller reorders `values`: `sort=True` (its
    /// DEFAULT) is alphabetical by value name and `sort=False` preserves the
    /// FRAME's column order. This method exposes no `sort` knob, so it implements
    /// the default. Iterating `values` in argument order -- what this did until
    /// eay9h -- agrees with pandas only when the caller happens to pass the value
    /// names already sorted.
    pub fn pivot_table_multi_values(
        &self,
        values: &[&str],
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
    ) -> Result<Self, FrameError> {
        if values.len() == 1 {
            return self.pivot_table(values[0], index_col, columns_col, aggfunc);
        }

        // Build individual pivot tables and merge columns
        let mut combined_cols = BTreeMap::new();
        let mut combined_order = Vec::new();
        let mut shared_index = None;

        // pandas' `sort=True` default orders the value level by NAME. See the
        // measured table on this method. br-frankenpandas-eay9h.
        let mut by_name = values.to_vec();
        by_name.sort_unstable();

        for &val_col in &by_name {
            let pt = self.pivot_table(val_col, index_col, columns_col, aggfunc)?;
            if shared_index.is_none() {
                shared_index = Some(pt.index.clone());
            }
            for col_name in &pt.column_order {
                let prefixed = format!("{val_col}_{col_name}");
                combined_cols.insert(prefixed.clone(), pt.columns[col_name].clone());
                combined_order.push(prefixed);
            }
        }

        Ok(Self {
            columns: combined_cols.into(),
            column_order: combined_order.into(),
            index: shared_index.unwrap_or_else(|| Index::new(Vec::new())),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Create a pivot table where each value column uses its own aggregation.
    ///
    /// Matches `df.pivot_table(values=[...], index=..., columns=..., aggfunc={'col1':'sum','col2':'mean'})`.
    /// Each `(value_col, aggfunc)` entry is pivoted independently and the
    /// result columns are prefixed with the value column name
    /// (`{value_col}_{pivot_column}`), matching the layout of
    /// `pivot_table_multi_values` -- including its NAME ordering. Duplicate value
    /// column names are rejected (a dict has unique keys). Missing columns and
    /// unsupported aggfuncs propagate from the single-value `pivot_table` call.
    ///
    /// ⚠️ Same rule, measured separately on live pandas 2.2.3 because the dict
    /// form does NOT follow the list form when `sort=False` (there it keeps the
    /// dict's own key order, where the list form takes the frame's column order).
    /// Under pandas' `sort=True` DEFAULT, which is what this implements, both are
    /// alphabetical and neither moves when the caller reorders the argument:
    ///
    /// | call | result |
    /// |---|---|
    /// | `aggfunc={"zeta":"sum","alpha":"mean"}` | `alpha_A alpha_B zeta_A zeta_B` |
    /// | `aggfunc={"alpha":"mean","zeta":"sum"}` | `alpha_A alpha_B zeta_A zeta_B` |
    ///
    /// br-frankenpandas-eay9h.
    pub fn pivot_table_aggfunc_dict(
        &self,
        value_aggs: &[(&str, &str)],
        index_col: &str,
        columns_col: &str,
    ) -> Result<Self, FrameError> {
        if value_aggs.is_empty() {
            return Err(FrameError::CompatibilityRejected(
                "pivot_table_aggfunc_dict: value_aggs must be non-empty".to_owned(),
            ));
        }

        let mut seen: HashSet<&str> = HashSet::new();
        for (val_col, _) in value_aggs {
            if !seen.insert(*val_col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "pivot_table_aggfunc_dict: duplicate value column '{val_col}'"
                )));
            }
        }

        let mut combined_cols = BTreeMap::new();
        let mut combined_order = Vec::new();
        let mut shared_index: Option<Index> = None;

        // pandas' `sort=True` default orders the value level by NAME, not by the
        // dict's key order. br-frankenpandas-eay9h.
        let mut by_name = value_aggs.to_vec();
        by_name.sort_unstable_by_key(|(val_col, _)| *val_col);

        for (val_col, aggfunc) in &by_name {
            let pt = self.pivot_table(val_col, index_col, columns_col, aggfunc)?;
            if shared_index.is_none() {
                shared_index = Some(pt.index.clone());
            }
            for col_name in &pt.column_order {
                let prefixed = format!("{val_col}_{col_name}");
                combined_cols.insert(prefixed.clone(), pt.columns[col_name].clone());
                combined_order.push(prefixed);
            }
        }

        Ok(Self {
            columns: combined_cols.into(),
            column_order: combined_order.into(),
            index: shared_index.unwrap_or_else(|| Index::new(Vec::new())),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    fn pivot_table_margin_source_values(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        row_label: Option<&IndexLabel>,
        column_name: Option<&str>,
    ) -> Vec<f64> {
        let val_col = &self.columns[values];
        let idx_col = &self.columns[index_col];
        let cols_col = &self.columns[columns_col];
        let mut out = Vec::new();

        for row_idx in 0..self.len() {
            let idx_value = &idx_col.values()[row_idx];
            let cols_value = &cols_col.values()[row_idx];
            if scalar_key_skip_missing(idx_value).is_none()
                || scalar_key_skip_missing(cols_value).is_none()
            {
                continue;
            }

            if let Some(expected_row) = row_label
                && scalar_to_value_counts_index_label(idx_value) != *expected_row
            {
                continue;
            }

            if let Some(expected_column) = column_name
                && scalar_to_pivot_column_name(cols_value) != expected_column
            {
                continue;
            }

            if pivot_table_counts_rows(aggfunc) {
                out.push(0.0);
            } else if let Ok(value) = val_col.values()[row_idx].to_f64() {
                out.push(value);
            }
        }

        out
    }

    /// O(n) dense margins backend for [`Self::pivot_table_with_margins_impl`]
    /// (see the gate there). `base` is the already-built R×C dense pivot;
    /// `ri_codes`/`ci_codes` map each raw row to its sorted-rank row/column
    /// position (identical to `base`'s sorted axis order); `val_f64` is the
    /// all-valid Float64 value slice. Two passes compute the "All" column
    /// (per-row totals), the "All" row (per-column totals), and the grand total
    /// — each accumulating raw values in ROW ORDER, bit-identical to the generic
    /// per-margin `pivot_table_agg_value(aggfunc, margin_source_values(..))`.
    /// Online aggfuncs only (sum/mean/count/size/min/max). Every base label has
    /// ≥1 source row, so margins are always `Float64` (never the empty→Null
    /// case the generic path guards).
    fn pivot_margins_dense(
        &self,
        base: Self,
        ri_codes: &[u32],
        ci_codes: &[u32],
        value_slices: (&[f64], Option<&[i64]>),
        aggfunc: &str,
        margins_name: &str,
    ) -> Result<Self, FrameError> {
        let (val_f64, int_values) = value_slices;
        let n_idx = base.index.len();
        let n_col = base.column_order.len();
        let (row_margins, col_margins, overall) =
            pivot_compute_margins(ri_codes, ci_codes, val_f64, aggfunc, n_idx, n_col);

        // Assemble: append the "All" total row to every base column, then add
        // the "All" total column ([per-row totals…, grand total]).
        let mut new_cols = BTreeMap::new();
        let mut new_col_order = base.column_order.clone();
        for (c, name) in base.column_order.iter().enumerate() {
            let mut col_vals: Vec<Scalar> = base.columns[name].values().to_vec();
            col_vals.push(Scalar::Float64(col_margins[c]));
            new_cols.insert(name.clone(), Column::new(DType::Float64, col_vals)?);
        }
        let mut all_col_vals = Vec::with_capacity(n_idx + 1);
        for &rm in &row_margins {
            all_col_vals.push(Scalar::Float64(rm));
        }
        all_col_vals.push(Scalar::Float64(overall));
        // A sparse pivot body must widen its affected cells to Float64 for the
        // invented gaps, but the sum margin column has no gaps of its own. For
        // an all-valid Int64 source pandas therefore retains Int64 in that
        // column rather than promoting it along with the sparse body.
        let all_col = if aggfunc == "sum" {
            if let Some(values) = int_values {
                debug_assert_eq!(values.len(), ri_codes.len());
                let mut sums = vec![0_i64; n_idx];
                let mut overall = 0_i64;
                for (row, &value) in values.iter().enumerate() {
                    let idx = ri_codes[row] as usize;
                    sums[idx] = sums[idx].wrapping_add(value);
                    overall = overall.wrapping_add(value);
                }
                sums.push(overall);
                Column::from_i64_values(sums)
            } else {
                Column::new(DType::Float64, all_col_vals)?
            }
        } else {
            Column::new(DType::Float64, all_col_vals)?
        };
        new_cols.insert(margins_name.to_owned(), all_col);
        new_col_order.push(margins_name.to_owned());

        let mut new_labels = base.index.labels().to_vec();
        new_labels.push(IndexLabel::Utf8(margins_name.to_owned()));
        Ok(Self {
            columns: new_cols.into(),
            column_order: new_col_order,
            index: Index::new(new_labels).rename_index(base.index.name()),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    fn pivot_table_with_margins_impl(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        margins: bool,
        margins_name: &str,
    ) -> Result<Self, FrameError> {
        let base = self.pivot_table(values, index_col, columns_col, aggfunc)?;
        if !margins {
            return Ok(base);
        }

        // Fast O(n) margins (br-frankenpandas-1q4q4): the generic path below
        // calls `pivot_table_margin_source_values` ONCE PER row-label AND ONCE
        // PER column — each a full O(n) scan — so margins cost
        // O(n·(n_idx+n_col)) (≈1 billion ops at 1M×1000). When the keys are
        // dense-eligible (same gate as the typed pivot) and the aggregate is
        // online, compute every margin in TWO passes instead. Bit-identical:
        // each margin accumulates its raw values in ROW ORDER exactly as
        // `pivot_table_agg_value` folds `margin_source_values`, and the overall
        // total is summed in raw row order (NOT by reducing per-bucket sums, so
        // the float fold order is preserved).
        if matches!(
            aggfunc,
            "sum" | "mean" | "count" | "size" | "min" | "max" | "var" | "std" | "median"
        ) && let Some(val_f64) = pivot_value_f64(&self.columns[values])
            && let Some((ri_codes, _, _)) = pivot_axis_dense_codes(&self.columns[index_col])
            && let Some((ci_codes, _, _)) = pivot_axis_dense_codes(&self.columns[columns_col])
        {
            return self.pivot_margins_dense(
                base,
                &ri_codes,
                &ci_codes,
                (val_f64.as_ref(), self.columns[values].as_i64_slice()),
                aggfunc,
                margins_name,
            );
        }

        let n_rows = base.len();
        let col_names = base.column_order.clone();

        let mut all_col_vals = Vec::with_capacity(n_rows + 1);
        for row_label in base.index.labels() {
            let source_vals = self.pivot_table_margin_source_values(
                values,
                index_col,
                columns_col,
                aggfunc,
                Some(row_label),
                None,
            );
            all_col_vals.push(if source_vals.is_empty() {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Float64(pivot_table_agg_value(aggfunc, &source_vals)?)
            });
        }

        let mut new_cols = BTreeMap::new();
        let mut new_col_order = col_names.clone();
        for name in &col_names {
            let col = &base.columns[name];
            let mut col_vals: Vec<Scalar> = col.values().to_vec();
            let source_vals = self.pivot_table_margin_source_values(
                values,
                index_col,
                columns_col,
                aggfunc,
                None,
                Some(name),
            );
            col_vals.push(if source_vals.is_empty() {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Float64(pivot_table_agg_value(aggfunc, &source_vals)?)
            });
            new_cols.insert(name.clone(), Column::new(DType::Float64, col_vals)?);
        }

        let overall_vals = self.pivot_table_margin_source_values(
            values,
            index_col,
            columns_col,
            aggfunc,
            None,
            None,
        );
        all_col_vals.push(if overall_vals.is_empty() {
            Scalar::Null(NullKind::NaN)
        } else {
            Scalar::Float64(pivot_table_agg_value(aggfunc, &overall_vals)?)
        });
        new_cols.insert(
            margins_name.to_owned(),
            Column::new(DType::Float64, all_col_vals)?,
        );
        new_col_order.push(margins_name.to_owned());

        let mut new_labels = base.index.labels().to_vec();
        new_labels.push(IndexLabel::Utf8(margins_name.to_owned()));

        // Per br-frankenpandas-jhrer: pandas pivot_table with margins
        // preserves the base index axis name.
        Ok(Self {
            columns: new_cols.into(),
            column_order: new_col_order,
            index: Index::new(new_labels).rename_index(base.index.name()),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Create a pivot table with optional margin totals.
    ///
    /// Matches `df.pivot_table(values, index, columns, aggfunc, margins=True)`.
    /// When `margins` is `true`, appends an "All" row and "All" column with
    /// totals computed using the same aggregation function.
    pub fn pivot_table_with_margins(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        margins: bool,
    ) -> Result<Self, FrameError> {
        self.pivot_table_with_margins_impl(values, index_col, columns_col, aggfunc, margins, "All")
    }

    /// Pivot table with margins and a customizable margin label.
    ///
    /// Like `pivot_table_with_margins` but allows specifying the label used
    /// for the margin row/column (default is "All" in pandas).
    pub fn pivot_table_with_margins_name(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfunc: &str,
        margins: bool,
        margins_name: &str,
    ) -> Result<Self, FrameError> {
        self.pivot_table_with_margins_impl(
            values,
            index_col,
            columns_col,
            aggfunc,
            margins,
            margins_name,
        )
    }

    /// Aggregate using one or more operations over the specified axis.
    ///
    /// `funcs`: mapping of column_name → list of aggregation function names.
    /// Returns a DataFrame with index = function names and columns = original column names.
    pub fn agg(
        &self,
        funcs: &std::collections::HashMap<String, Vec<String>>,
    ) -> Result<Self, FrameError> {
        // Collect all unique function names in insertion order
        let mut all_funcs: Vec<String> = Vec::new();
        let mut seen = std::collections::HashSet::new();
        for fns in funcs.values() {
            for f in fns {
                if seen.insert(f.clone()) {
                    all_funcs.push(f.clone());
                }
            }
        }

        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::new();

        for col_name in &self.column_order {
            if let Some(col_funcs) = funcs.get(col_name) {
                let col = &self.columns[col_name];
                let series = Series::new(col_name, self.index.clone(), col.clone())?;
                let mut vals = Vec::with_capacity(all_funcs.len());
                for func_name in &all_funcs {
                    if col_funcs.contains(func_name) {
                        // Delegate each per-function value to Series.agg so dict-style
                        // DataFrame.agg supports the full reduction set (prod/sem/skew/
                        // kurt/kurtosis/nunique/first/last/size/any/all), matching
                        // Series.agg rather than only the basic moments.
                        // br-frankenpandas-w46mr.
                        let single = series.agg(&[func_name.as_str()])?;
                        vals.push(single.values()[0].clone());
                    } else {
                        vals.push(Scalar::Null(NullKind::NaN));
                    }
                }
                result_cols.insert(col_name.clone(), Column::from_values(vals)?);
                col_order.push(col_name.clone());
            }
        }

        let labels: Vec<IndexLabel> = all_funcs
            .iter()
            .map(|f| IndexLabel::Utf8(f.clone()))
            .collect();

        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index: Index::new(labels),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// pandas alias for [`Self::agg`].
    ///
    /// Matches `pd.DataFrame.aggregate(...)` for dict-style column
    /// aggregation specifications.
    pub fn aggregate(
        &self,
        funcs: &std::collections::HashMap<String, Vec<String>>,
    ) -> Result<Self, FrameError> {
        self.agg(funcs)
    }

    /// Apply a function element-wise to every value in the DataFrame.
    ///
    /// Returns a new DataFrame with the same shape and index.
    pub fn applymap<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar) -> Scalar,
    {
        let mut result_cols = BTreeMap::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let new_vals: Vec<Scalar> = col.values().iter().map(&func).collect();
            result_cols.insert(col_name.clone(), Column::from_values(new_vals)?);
        }
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// pandas-2.1+ alias for [`Self::applymap`]. Matches `df.map(func)`.
    ///
    /// Per br-frankenpandas-nk54a. pandas 2.1 deprecated `applymap` in
    /// favor of `map`; this alias supports the new spelling so users
    /// migrating from pandas 2.x don't need to rename.
    pub fn map<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar) -> Scalar,
    {
        self.applymap(func)
    }

    /// Apply a function element-wise, skipping missing values.
    ///
    /// Matches `df.applymap(func, na_action='ignore')`. Missing values
    /// (Null/NaN) are passed through unchanged; `func` is only called on
    /// non-missing values.
    pub fn applymap_na_action<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar) -> Scalar,
    {
        let mut result_cols = BTreeMap::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let new_vals: Vec<Scalar> = col
                .values()
                .iter()
                .map(|v| if v.is_missing() { v.clone() } else { func(v) })
                .collect();
            result_cols.insert(col_name.clone(), Column::from_values(new_vals)?);
        }
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Apply a function element-wise (pandas 2.0 name for `applymap`).
    ///
    /// Matches `pd.DataFrame.map(func)`.
    pub fn map_elements<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar) -> Scalar,
    {
        self.applymap(func)
    }

    /// Apply a function element-wise, preserving the shape of the DataFrame.
    ///
    /// Similar to `applymap` but validates that the output has the same shape.
    pub fn transform<F>(&self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar) -> Scalar,
    {
        self.applymap(func)
    }

    /// Create a pivot table applying multiple aggregation functions.
    ///
    /// Matches `df.pivot_table(values, index, columns, aggfunc=['sum','mean'])`.
    /// Returns a DataFrame with columns named `"{col}_{func}"` for each
    /// combination of pivot column value and aggregation function.
    pub fn pivot_table_multi_agg(
        &self,
        values: &str,
        index_col: &str,
        columns_col: &str,
        aggfuncs: &[&str],
    ) -> Result<Self, FrameError> {
        if aggfuncs.is_empty() {
            return Err(FrameError::CompatibilityRejected(
                "pivot_table_multi_agg: at least one aggfunc required".into(),
            ));
        }

        // Build individual pivot tables and merge their columns
        let first = self.pivot_table(values, index_col, columns_col, aggfuncs[0])?;
        let mut combined_cols = BTreeMap::new();
        let mut combined_order = Vec::new();

        for &func in aggfuncs {
            let pt = self.pivot_table(values, index_col, columns_col, func)?;
            for col_name in &pt.column_order {
                let new_name = format!("{col_name}_{func}");
                combined_cols.insert(new_name.clone(), pt.columns[col_name].clone());
                combined_order.push(new_name);
            }
        }

        Ok(Self {
            columns: combined_cols.into(),
            column_order: combined_order.into(),
            index: first.index.clone(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Compute the Pearson correlation matrix between numeric columns.
    pub fn corr(&self) -> Result<Self, FrameError> {
        self.corr_with_numeric_only(false)
    }

    /// Compute the Pearson correlation matrix, optionally restricting to numeric dtypes.
    ///
    /// Matches `df.corr(numeric_only=...)`. Boolean columns are treated as numeric,
    /// and non-numeric columns are excluded from the result.
    pub fn corr_with_numeric_only(&self, numeric_only: bool) -> Result<Self, FrameError> {
        self.pairwise_corr_stat_min("corr", 1, numeric_only)
    }

    /// Compute pairwise Pearson correlation with a minimum-observations threshold.
    ///
    /// Matches `df.corr(min_periods=n)`. Pairs with fewer than `min_periods`
    /// valid (non-NaN) observations yield NaN.
    pub fn corr_min_periods(&self, min_periods: usize) -> Result<Self, FrameError> {
        self.corr_min_periods_with_numeric_only(min_periods, false)
    }

    /// Compute pairwise Pearson correlation with a minimum-observations threshold.
    ///
    /// Matches `df.corr(min_periods=n, numeric_only=...)`.
    pub fn corr_min_periods_with_numeric_only(
        &self,
        min_periods: usize,
        numeric_only: bool,
    ) -> Result<Self, FrameError> {
        self.pairwise_corr_stat_min("corr", min_periods, numeric_only)
    }

    /// Compute correlation matrix using the specified method.
    ///
    /// Supported methods: "pearson", "spearman", "kendall".
    pub fn corr_method(&self, method: &str) -> Result<Self, FrameError> {
        self.corr_method_with_numeric_only(method, false)
    }

    /// Compute correlation matrix using the specified method and numeric_only policy.
    ///
    /// Supported methods: "pearson", "spearman", "kendall".
    pub fn corr_method_with_numeric_only(
        &self,
        method: &str,
        numeric_only: bool,
    ) -> Result<Self, FrameError> {
        match method {
            "pearson" => self.pairwise_corr_stat_min("corr", 1, numeric_only),
            "spearman" => self.pairwise_rank_corr("spearman", numeric_only),
            "kendall" => self.pairwise_rank_corr("kendall", numeric_only),
            other => Err(FrameError::CompatibilityRejected(format!(
                "unsupported correlation method: '{other}'"
            ))),
        }
    }

    /// Compute the pairwise covariance matrix between numeric columns.
    pub fn cov(&self) -> Result<Self, FrameError> {
        self.pairwise_stat_min("cov", 1)
    }

    /// Compute pairwise covariance with a minimum-observations threshold.
    ///
    /// Matches `df.cov(min_periods=n)`. Pairs with fewer than `min_periods`
    /// valid (non-NaN) observations yield NaN.
    pub fn cov_min_periods(&self, min_periods: usize) -> Result<Self, FrameError> {
        self.pairwise_stat_min("cov", min_periods)
    }

    fn corr_candidate_columns(&self, _numeric_only: bool) -> Vec<String> {
        // Per br-frankenpandas-qk3s0: include Timedelta64 columns. pandas
        // df.corr() / df.cov() returns f64 statistics for Timedelta cols
        // by treating their ns counts as ordered numerics.
        self.column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Bool | DType::Int64 | DType::Float64 | DType::Timedelta64
                )
            })
            .cloned()
            .collect()
    }

    fn pairwise_numeric_column_values(col: &Column, len: usize) -> std::borrow::Cow<'_, [f64]> {
        if let Some(data) = col.as_f64_slice()
            && data.len() == len
        {
            return std::borrow::Cow::Borrowed(data);
        }

        // Typed NULLABLE Float64 fast path (corr-null vein): the all-valid
        // `as_f64_slice` above bails on any missing, so a nullable Float64 column
        // fell to the generic `col.values()` loop below — which materializes the
        // ENTIRE column as a `Vec<Scalar>` (one boxed enum per row, ~3× the raw
        // f64 bytes) once per column. For few-columns×many-rows corr/cov that
        // O(n·m) Scalar materialization dominates the whole matrix. Read the raw
        // `(&[f64], &ValidityMask)` instead and emit `NaN` at invalid slots —
        // bit-identical to the generic path: a valid slot yields `data[i]` (the
        // stored f64, == `Scalar::Float64(v).to_f64()`), an invalid slot yields
        // `NaN` (== `Scalar::Null.to_f64().unwrap_or(NaN)`), which the pairwise
        // NaN-skip then drops exactly as before.
        if col.dtype() == DType::Float64
            && let Some((data, validity)) = col.as_f64_slice_with_validity()
            && data.len() == len
        {
            return std::borrow::Cow::Owned(
                (0..len)
                    .map(|i| if validity.get(i) { data[i] } else { f64::NAN })
                    .collect(),
            );
        }

        // Typed all-valid Int64 fast path (sister to the Float64 arms): map `v as f64`
        // off the raw `&[i64]` instead of materializing `col.values()` (Vec<Scalar>)
        // + per-element `to_f64`. Bit-identical to the generic path below on an
        // all-valid Int64 column: `as_i64_slice` implies `validity.all()` (no missing
        // → no NaN slot), and `to_f64(Int64(v)) == v as f64`, so the pairwise NaN-skip
        // sees the identical finite f64 sequence. (Timedelta64's ns special-case is
        // moot — `as_i64_slice` is Int64-dtype-gated and declines Timedelta.)
        if let Some(data) = col.as_i64_slice()
            && data.len() == len
        {
            return std::borrow::Cow::Owned(data.iter().map(|&v| v as f64).collect());
        }

        std::borrow::Cow::Owned(
            (0..len)
                .map(|i| match &col.values()[i] {
                    // Per br-frankenpandas-qk3s0: extract ns for
                    // Timedelta64 before falling through to to_f64.
                    Scalar::Timedelta64(ns) if *ns != Timedelta::NAT => *ns as f64,
                    Scalar::Timedelta64(_) => f64::NAN,
                    other => other.to_f64().unwrap_or(f64::NAN),
                })
                .collect(),
        )
    }

    fn pairwise_numeric_column_arc_values(col: &Column, len: usize) -> (Arc<[f64]>, usize) {
        if let Some((data, start)) = col.as_f64_arc_view_source()
            && start.checked_add(len).is_some_and(|end| end <= data.len())
        {
            return (data, start);
        }

        match Self::pairwise_numeric_column_values(col, len) {
            std::borrow::Cow::Borrowed(data) => (Arc::from(data.to_vec()), 0),
            std::borrow::Cow::Owned(data) => (Arc::from(data), 0),
        }
    }

    fn pairwise_stat_lazy_result_columns(
        numeric_cols: &[String],
        col_data: &[(Arc<[f64]>, usize)],
        stat: PairwiseFloat64Stat,
        min_periods: usize,
        len: usize,
    ) -> Option<BTreeMap<String, Column>> {
        if numeric_cols.len() != col_data.len() {
            return None;
        }
        if numeric_cols.is_empty() {
            return Some(BTreeMap::new());
        }
        if len < min_periods.max(2) {
            return None;
        }

        let mut min_corr_var = f64::INFINITY;
        for (data, start) in col_data {
            let end = start.checked_add(len)?;
            let slice = data.get(*start..end)?;
            let k = *slice.first()?;

            let mut sum = 0.0_f64;
            let mut sum2 = 0.0_f64;
            for &x in slice {
                if !x.is_finite() {
                    return None;
                }
                let shifted = x - k;
                if !shifted.is_finite() {
                    return None;
                }
                sum += shifted;
                sum2 += shifted * shifted;
            }
            if !sum.is_finite() || !sum2.is_finite() {
                return None;
            }

            if stat == PairwiseFloat64Stat::Corr {
                let n_f = len as f64;
                let mean = sum / n_f;
                let var = (sum2 - n_f * mean * mean) / (n_f - 1.0);
                if !var.is_finite() || var < f64::EPSILON {
                    return None;
                }
                min_corr_var = min_corr_var.min(var);
            }
        }
        if stat == PairwiseFloat64Stat::Corr && min_corr_var < f64::EPSILON {
            return None;
        }

        let columns = Column::from_f64_all_valid_pairwise_stat_matrix_columns(
            col_data.to_vec(),
            len,
            stat,
            min_periods,
        );
        let mut result_cols = BTreeMap::new();
        for (name, column) in numeric_cols.iter().cloned().zip(columns) {
            result_cols.insert(name, column);
        }
        Some(result_cols)
    }

    /// Finalize a pairwise cov/corr cell from accumulated moments.
    ///
    /// Arithmetic is bit-identical to the historical per-pair inline form.
    #[allow(clippy::too_many_arguments)] // moment accumulators; bundling into a
    // struct would obscure the bit-identical per-pair arithmetic.
    fn finalize_pairwise_stat(
        stat: &str,
        min_periods: usize,
        count: usize,
        sum_x: f64,
        sum_y: f64,
        sum_xy: f64,
        sum_x2: f64,
        sum_y2: f64,
    ) -> f64 {
        let threshold = min_periods.max(2);
        if count < threshold {
            return f64::NAN;
        }
        let n_f = count as f64;
        let mean_x = sum_x / n_f;
        let mean_y = sum_y / n_f;
        let cov_xy = (sum_xy - n_f * mean_x * mean_y) / (n_f - 1.0);
        match stat {
            "cov" => cov_xy,
            "corr" => {
                let var_x = (sum_x2 - n_f * mean_x * mean_x) / (n_f - 1.0);
                let var_y = (sum_y2 - n_f * mean_y * mean_y) / (n_f - 1.0);
                let denom = (var_x * var_y).sqrt();
                if denom < f64::EPSILON {
                    f64::NAN
                } else {
                    cov_xy / denom
                }
            }
            _ => f64::NAN,
        }
    }

    /// Pairwise cov/corr matrix over already-extracted f64 columns.
    ///
    /// The expensive `O(M)` moment accumulation is run **once per unordered
    /// pair** `{i, j}` (`i <= j`) instead of once per ordered pair, halving the
    /// `O(N^2 · M)` pairwise work. Both the `(i, j)` and `(j, i)` cells are then
    /// finalized from that single set of moments — the `(j, i)` cell with the
    /// marginals swapped (`x <-> y`), which reproduces the historical
    /// independent `(j, i)` computation **bit-for-bit**.
    ///
    /// The swap is necessary, not cosmetic: the matrix is *not* exactly
    /// symmetric in IEEE-754. `cov_xy` contains `n * mean_x * mean_y`, which
    /// parses as `(n * mean_x) * mean_y`; multiplication is commutative but not
    /// associative, so `(n*mean_i)*mean_j` and `(n*mean_j)*mean_i` can differ by
    /// one ULP. Feeding `finalize` the swapped marginals replays the exact
    /// association the old `(j, i)` pass used, so the golden output is unchanged
    /// to the last bit. Our own safe-Rust Gram-matrix kernel (no C BLAS).
    /// `min_periods` semantics are preserved unchanged.
    fn pairwise_stat_matrix(
        numeric_cols: &[String],
        col_data: &[std::borrow::Cow<'_, [f64]>],
        stat: &str,
        min_periods: usize,
    ) -> Result<BTreeMap<String, Column>, FrameError> {
        let n = numeric_cols.len();
        let len = col_data.first().map_or(0, |c| c.len());

        // Numerical-stability shift (br-frankenpandas-dnz2a): cov/corr are
        // EXACTLY shift-invariant — cov(X, Y) == cov(X - Kx, Y - Ky) — so subtract
        // a per-column constant (the first finite observation) from every column
        // before the moment/Gram accumulation. This brings the accumulators to
        // range-scale, eliminating the catastrophic cancellation of the one-pass
        // `(sum_xy - n*mx*my)` / `(sum_x2 - n*mx^2)` finalize for large-magnitude
        // columns (e.g. epoch-ns or large financial values, where var_x cancels
        // to 0.0 -> NaN while pandas returns a finite value). NaN slots are
        // preserved (NaN - K = NaN), so both the complete Gram path and the
        // per-pair NaN path run UNCHANGED on the shifted data, and
        // `finalize_pairwise_stat` is algebraically identical to the unshifted
        // form. Matches NumPy/pandas, which mean-center (two-pass) for the same
        // reason. O(n*m) pre-pass, negligible beside the O(n^2*m) Gram.
        let shift_storage: Vec<Vec<f64>> = col_data
            .iter()
            .map(|c| {
                let k = c.iter().copied().find(|x| x.is_finite()).unwrap_or(0.0);
                c.iter().map(|&x| x - k).collect()
            })
            .collect();
        let shifted: Vec<std::borrow::Cow<'_, [f64]>> = shift_storage
            .iter()
            .map(|v| std::borrow::Cow::Borrowed(v.as_slice()))
            .collect();
        let col_data: &[std::borrow::Cow<'_, [f64]>] = &shifted;

        let mut mat = vec![0.0_f64; n * n];

        // Complete-columns fast path. When no column has a NaN, the per-pair
        // NaN-skip never fires, so for EVERY pair count == len, and the five
        // moments separate:
        //   - sum_x / sum_x2 depend only on column i (not the partner j), so
        //     they are computed ONCE per column instead of N times.
        //   - sum_xy is the Gram matrix G = Xᵀ·X. Its upper triangle is built
        //     with the register-blocked, packed-panel micro-kernel (same lever
        //     as DataFrame::dot): a 4×4 tile of INDEPENDENT accumulators, each
        //     folding r = 0..len left-to-right exactly as the scalar
        //     `sum_xy += x*y` loop did — no reassociation, just interleaved
        //     chains hiding FP-add latency, with the dj FMAs vectorized.
        // G is symmetric to the bit (x*y == y*x, same fold order), so the
        // single computed G[i][j] feeds BOTH the (i,j) and (j,i) finalize calls
        // — identical to the old code reusing one `sum_xy` for the mirror cell.
        // Any NaN anywhere falls through to the exact per-pair path below.
        let complete = len > 0 && col_data.iter().all(|c| !c.iter().any(|x| x.is_nan()));
        if complete {
            let mut sum = vec![0.0_f64; n];
            let mut sum2 = vec![0.0_f64; n];
            let moment = |col: &[f64]| -> (f64, f64) {
                let mut s = 0.0_f64;
                let mut s2 = 0.0_f64;
                for &x in col {
                    s += x;
                    s2 += x * x;
                }
                (s, s2)
            };
            // Per-column moments are independent; fan them out when the volume
            // (~len·n) pays for thread spin-up. Bit-identical: each column's
            // s/s2 fold is r-ascending exactly as the in-line loop.
            let moment_workers = fp_columnar::cached_available_parallelism()
                .min(64)
                .min(n.max(1));
            if moment_workers >= 2 && (len as u128) * (n as u128) >= (1u128 << 20) {
                let next_col = std::sync::atomic::AtomicUsize::new(0);
                let col_data_ref: &[std::borrow::Cow<'_, [f64]>] = col_data;
                let parts = std::thread::scope(|scope| {
                    let mut handles = Vec::with_capacity(moment_workers);
                    for _ in 0..moment_workers {
                        let next_col = &next_col;
                        handles.push(scope.spawn(move || {
                            let mut out: Vec<(usize, f64, f64)> = Vec::new();
                            loop {
                                let idx =
                                    next_col.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                if idx >= col_data_ref.len() {
                                    break;
                                }
                                let (s, s2) = moment(col_data_ref[idx].as_ref());
                                out.push((idx, s, s2));
                            }
                            out
                        }));
                    }
                    let mut all = Vec::with_capacity(handles.len());
                    for handle in handles {
                        all.push(handle.join().unwrap_or_default());
                    }
                    all
                });
                for part in parts {
                    for (idx, s, s2) in part {
                        sum[idx] = s;
                        sum2[idx] = s2;
                    }
                }
            } else {
                for (idx, col) in col_data.iter().enumerate() {
                    let (s, s2) = moment(col.as_ref());
                    sum[idx] = s;
                    sum2[idx] = s2;
                }
            }

            // Upper-triangle Gram G = XᵀX, gram[i*n+j] for i <= j, computed by a
            // communication-avoiding ROW-PARTITIONED scheme (br-frankenpandas-fbav3):
            // each worker owns a disjoint contiguous band of rows and accumulates
            // that band's partial Gram, reading its slice of every column EXACTLY
            // ONCE. X is thus streamed from DRAM once total instead of being
            // re-read per output tile — breaking the memory-bandwidth wall that
            // capped the prior bit-identical tj-block version at ~1.5x. The band
            // partials are summed in fixed (ascending-band) order, which
            // reassociates each cell's fold by ~1 ULP vs a single r=0..len sweep
            // — within the 1e-9 live-oracle tolerance (conformance is the parity
            // gate) and deterministic, so the regenerated goldens stay stable.
            const BT: usize = 4;
            // FIXED band count (independent of the machine's core count) so the
            // reassociated fold — and therefore the regenerated goldens — are
            // deterministic and portable. Threads work-steal bands, but each
            // band's partial is summed back in fixed band order.
            const BAND_COUNT: usize = 64;
            let mut gram = vec![0.0_f64; n * n];
            // Gate parallelism on total Gram MAC volume (~len·n²/2) so small
            // matrices keep the zero-overhead single-band pass.
            let big_enough = (len as u128) * (n as u128) * (n as u128) >= (1u128 << 23);
            let band_count = BAND_COUNT.min(len);
            if band_count >= 2 && big_enough {
                let band = len.div_ceil(band_count);
                let bands: Vec<(usize, usize)> = (0..band_count)
                    .map(|b| (b * band, ((b + 1) * band).min(len)))
                    .filter(|&(a, b)| a < b)
                    .collect();
                let worker_count = fp_columnar::cached_available_parallelism()
                    .min(64)
                    .min(bands.len());
                let next_band = std::sync::atomic::AtomicUsize::new(0);
                let bands_ref: &[(usize, usize)] = &bands;
                let cols: Vec<&[f64]> = col_data.iter().map(|col| col.as_ref()).collect();
                let cols_ref: &[&[f64]] = &cols;
                // Each band writes its own partial slot (disjoint), so the fold
                // order is the fixed band index — not the thread schedule.
                let mut partials: Vec<Vec<f64>> = Vec::new();
                std::thread::scope(|scope| {
                    let mut handles = Vec::with_capacity(worker_count);
                    for _ in 0..worker_count {
                        let next_band = &next_band;
                        handles.push(scope.spawn(move || {
                            let mut out: Vec<(usize, Vec<f64>)> = Vec::new();
                            loop {
                                let b =
                                    next_band.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                if b >= bands_ref.len() {
                                    break;
                                }
                                let (r0, r1) = bands_ref[b];
                                let mut panel = vec![0.0_f64; (r1 - r0) * BT];
                                let mut gram_out = vec![0.0_f64; n * n];
                                gram_partial_rows(cols_ref, n, r0, r1, &mut panel, &mut gram_out);
                                out.push((b, gram_out));
                            }
                            out
                        }));
                    }
                    let mut indexed: Vec<(usize, Vec<f64>)> = Vec::with_capacity(bands.len());
                    for handle in handles {
                        if let Ok(mut part) = handle.join() {
                            indexed.append(&mut part);
                        }
                    }
                    indexed.sort_by_key(|(b, _)| *b);
                    partials = indexed.into_iter().map(|(_, g)| g).collect();
                });
                // Sum band partials in ascending-band order (deterministic fold).
                for partial in &partials {
                    if partial.len() != n * n {
                        continue;
                    }
                    for j in 0..n {
                        for i in 0..=j {
                            gram[i * n + j] += partial[i * n + j];
                        }
                    }
                }
            } else {
                let cols: Vec<&[f64]> = col_data.iter().map(|col| col.as_ref()).collect();
                let mut panel = vec![0.0_f64; len.max(1) * BT];
                gram_partial_rows(&cols, n, 0, len, &mut panel, &mut gram);
            }

            for j in 0..n {
                for i in 0..=j {
                    let g = gram[i * n + j];
                    mat[i * n + j] = Self::finalize_pairwise_stat(
                        stat,
                        min_periods,
                        len,
                        sum[i],
                        sum[j],
                        g,
                        sum2[i],
                        sum2[j],
                    );
                    if i != j {
                        mat[j * n + i] = Self::finalize_pairwise_stat(
                            stat,
                            min_periods,
                            len,
                            sum[j],
                            sum[i],
                            g,
                            sum2[j],
                            sum2[i],
                        );
                    }
                }
            }
        } else {
            // Exact per-pair (NaN-skipping) path. Each (i, j) pair is an
            // independent O(len) reduction over the two columns, so fan the
            // upper-triangle pairs across worker threads (br-frankenpandas-4j56s):
            // a worker computes a pair's five moments + both finalized cells and
            // the main thread scatters them. Bit-identical — each cell keeps the
            // same NaN-skip, same left-fold, same finalize as the serial loop;
            // only the owning thread differs.
            let compute_pair = |i: usize, j: usize| -> (f64, f64) {
                let mut sum_x = 0.0_f64;
                let mut sum_y = 0.0_f64;
                let mut sum_xy = 0.0_f64;
                let mut sum_x2 = 0.0_f64;
                let mut sum_y2 = 0.0_f64;
                let mut count = 0_usize;
                for (&x, &y) in col_data[i].iter().zip(col_data[j].iter()) {
                    if x.is_nan() || y.is_nan() {
                        continue;
                    }
                    sum_x += x;
                    sum_y += y;
                    sum_xy += x * y;
                    sum_x2 += x * x;
                    sum_y2 += y * y;
                    count += 1;
                }
                // Cell (i, j): col i is "x", col j is "y".
                let v_ij = Self::finalize_pairwise_stat(
                    stat,
                    min_periods,
                    count,
                    sum_x,
                    sum_y,
                    sum_xy,
                    sum_x2,
                    sum_y2,
                );
                // Cell (j, i): swap marginals so the (n·mean_x·mean_y) association
                // matches the old pass.
                let v_ji = if i != j {
                    Self::finalize_pairwise_stat(
                        stat,
                        min_periods,
                        count,
                        sum_y,
                        sum_x,
                        sum_xy,
                        sum_y2,
                        sum_x2,
                    )
                } else {
                    v_ij
                };
                (v_ij, v_ji)
            };

            let pairs: Vec<(usize, usize)> =
                (0..n).flat_map(|j| (0..=j).map(move |i| (i, j))).collect();
            let worker_count = fp_columnar::cached_available_parallelism()
                .min(64)
                .min(pairs.len().max(1));
            let big_enough = (pairs.len() as u128) * (len as u128) >= (1u128 << 20);
            if worker_count >= 2 && big_enough {
                const MORSEL: usize = 8;
                let pairs_ref: &[(usize, usize)] = &pairs;
                let compute_ref = &compute_pair;
                let next = std::sync::atomic::AtomicUsize::new(0);
                let cells: Vec<(usize, usize, f64, f64)> = std::thread::scope(|scope| {
                    let mut handles = Vec::with_capacity(worker_count);
                    for _ in 0..worker_count {
                        let next = &next;
                        handles.push(scope.spawn(move || {
                            let mut out: Vec<(usize, usize, f64, f64)> = Vec::new();
                            loop {
                                let start =
                                    next.fetch_add(MORSEL, std::sync::atomic::Ordering::Relaxed);
                                if start >= pairs_ref.len() {
                                    break;
                                }
                                let end = (start + MORSEL).min(pairs_ref.len());
                                for &(i, j) in &pairs_ref[start..end] {
                                    let (v_ij, v_ji) = compute_ref(i, j);
                                    out.push((i, j, v_ij, v_ji));
                                }
                            }
                            out
                        }));
                    }
                    let mut all: Vec<(usize, usize, f64, f64)> = Vec::new();
                    for handle in handles {
                        if let Ok(mut part) = handle.join() {
                            all.append(&mut part);
                        }
                    }
                    all
                });
                for (i, j, v_ij, v_ji) in cells {
                    mat[i * n + j] = v_ij;
                    if i != j {
                        mat[j * n + i] = v_ji;
                    }
                }
            } else {
                for &(i, j) in &pairs {
                    let (v_ij, v_ji) = compute_pair(i, j);
                    mat[i * n + j] = v_ij;
                    if i != j {
                        mat[j * n + i] = v_ji;
                    }
                }
            }
        }

        // Result column `j` holds stat(i, j) at row i — matching the historical
        // `vals[i]` / insert(col_j) layout exactly.
        let mut result_cols = BTreeMap::new();
        for (j, name) in numeric_cols.iter().enumerate() {
            let mut vals = Vec::with_capacity(n);
            for i in 0..n {
                vals.push(Scalar::Float64(mat[i * n + j]));
            }
            result_cols.insert(name.clone(), Column::new(DType::Float64, vals)?);
        }
        Ok(result_cols)
    }

    fn pairwise_corr_stat_min(
        &self,
        stat: &str,
        min_periods: usize,
        numeric_only: bool,
    ) -> Result<Self, FrameError> {
        let len = self.index.len();
        let numeric_cols = self.corr_candidate_columns(numeric_only);

        let col_arcs: Vec<(Arc<[f64]>, usize)> = numeric_cols
            .iter()
            .map(|name| Self::pairwise_numeric_column_arc_values(&self.columns[name], len))
            .collect();

        let lazy_stat = match stat {
            "corr" => Some(PairwiseFloat64Stat::Corr),
            "cov" => Some(PairwiseFloat64Stat::Cov),
            _ => None,
        };
        let result_cols = if let Some(lazy_stat) = lazy_stat {
            if let Some(result_cols) = Self::pairwise_stat_lazy_result_columns(
                &numeric_cols,
                &col_arcs,
                lazy_stat,
                min_periods,
                len,
            ) {
                result_cols
            } else {
                let col_data: Vec<std::borrow::Cow<'_, [f64]>> = col_arcs
                    .iter()
                    .map(|(data, start)| std::borrow::Cow::Borrowed(&data[*start..*start + len]))
                    .collect();
                Self::pairwise_stat_matrix(&numeric_cols, &col_data, stat, min_periods)?
            }
        } else {
            let col_data: Vec<std::borrow::Cow<'_, [f64]>> = col_arcs
                .iter()
                .map(|(data, start)| std::borrow::Cow::Borrowed(&data[*start..*start + len]))
                .collect();
            Self::pairwise_stat_matrix(&numeric_cols, &col_data, stat, min_periods)?
        };

        let labels: Vec<IndexLabel> = numeric_cols
            .iter()
            .map(|s| IndexLabel::Utf8(s.clone()))
            .collect();

        Ok(Self {
            columns: result_cols.into(),
            column_order: numeric_cols.into(),
            index: Index::new(labels),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Internal helper for corr/cov pairwise matrix computation.
    fn pairwise_stat_min(&self, stat: &str, min_periods: usize) -> Result<Self, FrameError> {
        let len = self.index.len();
        let numeric_cols: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Bool | DType::Int64 | DType::Float64 | DType::Timedelta64
                )
            })
            .cloned()
            .collect();

        let col_arcs: Vec<(Arc<[f64]>, usize)> = numeric_cols
            .iter()
            .map(|name| Self::pairwise_numeric_column_arc_values(&self.columns[name], len))
            .collect();

        let lazy_stat = match stat {
            "corr" => Some(PairwiseFloat64Stat::Corr),
            "cov" => Some(PairwiseFloat64Stat::Cov),
            _ => None,
        };
        let result_cols = if let Some(lazy_stat) = lazy_stat {
            if let Some(result_cols) = Self::pairwise_stat_lazy_result_columns(
                &numeric_cols,
                &col_arcs,
                lazy_stat,
                min_periods,
                len,
            ) {
                result_cols
            } else {
                let col_data: Vec<std::borrow::Cow<'_, [f64]>> = col_arcs
                    .iter()
                    .map(|(data, start)| std::borrow::Cow::Borrowed(&data[*start..*start + len]))
                    .collect();
                Self::pairwise_stat_matrix(&numeric_cols, &col_data, stat, min_periods)?
            }
        } else {
            let col_data: Vec<std::borrow::Cow<'_, [f64]>> = col_arcs
                .iter()
                .map(|(data, start)| std::borrow::Cow::Borrowed(&data[*start..*start + len]))
                .collect();
            Self::pairwise_stat_matrix(&numeric_cols, &col_data, stat, min_periods)?
        };

        let labels: Vec<IndexLabel> = numeric_cols
            .iter()
            .map(|s| IndexLabel::Utf8(s.clone()))
            .collect();

        Ok(Self {
            columns: result_cols.into(),
            column_order: numeric_cols.into(),
            index: Index::new(labels),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Compute pairwise Spearman or Kendall correlation matrix between numeric columns.
    fn pairwise_rank_corr(&self, method: &str, numeric_only: bool) -> Result<Self, FrameError> {
        let len = self.index.len();
        let numeric_cols = self.corr_candidate_columns(numeric_only);

        let n = numeric_cols.len();

        // Build Series for each numeric column. The row index is the default
        // 0..len RangeIndex, identical for every column; build it LAZILY via the
        // unit-range constructor (br-frankenpandas-uza04.99) instead of
        // materializing a fresh `Vec<IndexLabel>` of `len` Int64 labels per
        // column (n·len allocations — ~65ms of the spearman path at n=64,
        // len=100000). Correlation operates on column VALUES by position, so the
        // index labels never enter any cell — bit-identical output.
        let series_list: Vec<Series> = numeric_cols
            .iter()
            .map(|name| {
                let col = &self.columns[name];
                Series::new(
                    name,
                    Index::new_known_unique_int64_unit_range(0, len),
                    col.clone(),
                )
            })
            .collect::<Result<Vec<_>, _>>()?;

        // Spearman fast path: precompute each fully-numeric column's average
        // ranks once (O(N) rankings) instead of re-ranking both columns inside
        // every pair (O(N^2) rankings). For a complete column the dropped-row
        // set is empty regardless of the partner, so its ranks are reusable;
        // `pearson_on_slices` on the precomputed ranks is bit-identical to
        // `corr_spearman`, which ranks the same full columns and runs the same
        // Pearson. Columns with any missing cell yield `None` and fall back to
        // the exact per-pair `corr_spearman` (where ranks depend on both
        // columns). Kendall keeps the per-pair path.
        let spearman_centered: Vec<Option<SpearmanCenteredRankVector>> = if method == "spearman" {
            complete_spearman_centered_parallel(&series_list, len).unwrap_or_else(|| {
                series_list
                    .iter()
                    .map(|series| {
                        series
                            .spearman_ranks_if_complete()
                            .map(|ranks| spearman_centered_from_ranks(&ranks))
                    })
                    .collect()
            })
        } else {
            Vec::new()
        };
        // Per-column Kendall prep — extract the complete-finite f64 values,
        // argsort them into `order`, and invert that into `rank_by_row` — is
        // INDEPENDENT across columns and dominated the kendall path (~117ms of
        // serial O(n log n) argsorts at n=32, len=100000), while the pair matrix
        // below was already parallel. Fan the per-column prep across workers
        // (br-frankenpandas-uza04.99). Each column's (values, order, rank) is
        // computed exactly as the serial chain, then placed back at its column
        // index, so `kendall_values` / `kendall_orders` / `kendall_rank_by_row`
        // are bit-identical to the serial maps.
        let mut kendall_values: Vec<Option<Vec<f64>>> = Vec::new();
        let mut kendall_orders: Vec<Option<Vec<u32>>> = Vec::new();
        let mut kendall_rank_by_row: Vec<Option<Vec<u32>>> = Vec::new();
        if method == "kendall" {
            type KendallPrep = (Option<Vec<f64>>, Option<Vec<u32>>, Option<Vec<u32>>);
            let prep_one = |series: &Series| -> KendallPrep {
                let values = series.kendall_values_if_complete_finite();
                let order = values.as_deref().and_then(Series::kendall_no_tie_order);
                let rank = order.as_deref().map(Series::kendall_rank_by_row_from_order);
                (values, order, rank)
            };
            let workers = fp_columnar::cached_available_parallelism()
                .min(64)
                .min(n.max(1));
            let mut prepped: Vec<KendallPrep> = Vec::with_capacity(n);
            if workers >= 2 && n >= 2 {
                let next = std::sync::atomic::AtomicUsize::new(0);
                let series_ref: &[Series] = &series_list;
                let mut slots: Vec<Option<KendallPrep>> = (0..n).map(|_| None).collect();
                let parts = std::thread::scope(|scope| {
                    let mut handles = Vec::with_capacity(workers);
                    for _ in 0..workers {
                        let next = &next;
                        handles.push(scope.spawn(move || {
                            let mut out: Vec<(usize, KendallPrep)> = Vec::new();
                            loop {
                                let idx = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                if idx >= series_ref.len() {
                                    break;
                                }
                                out.push((idx, prep_one(&series_ref[idx])));
                            }
                            out
                        }));
                    }
                    handles
                        .into_iter()
                        .map(|h| h.join().unwrap_or_default())
                        .collect::<Vec<_>>()
                });
                for part in parts {
                    for (idx, prep) in part {
                        slots[idx] = Some(prep);
                    }
                }
                prepped.extend(slots.into_iter().map(|s| s.expect("every column prepped")));
            } else {
                prepped.extend(series_list.iter().map(prep_one));
            }
            kendall_values.reserve(n);
            kendall_orders.reserve(n);
            kendall_rank_by_row.reserve(n);
            for (values, order, rank) in prepped {
                kendall_values.push(values);
                kendall_orders.push(order);
                kendall_rank_by_row.push(rank);
            }
        }

        // Spearman and Kendall correlation matrices are exactly symmetric to the
        // last bit: spearman routes through `pearson_on_slices`, whose covariance
        // is the deviation sum `Σ(x-x̄)(y-ȳ)` (a single commutative product per
        // term, no non-associative `n·mean_x·mean_y` triple), and kendall's
        // concordant/discordant counts plus the `tied_x`/`tied_y` swap are
        // symmetric under `x <-> y`. So compute only the upper triangle and copy
        // each value to its transpose — halving the expensive O(M log M) /
        // O(M^2) per-pair work with zero change to output bits. The diagonal is
        // the self-correlation 1.0, exactly as before.
        let mat = match method {
            "spearman" => complete_spearman_gram_matrix(&spearman_centered)
                .or_else(|| complete_spearman_parallel_matrix(&spearman_centered)),
            "kendall" => {
                complete_kendall_no_tie_parallel_matrix(&kendall_orders, &kendall_rank_by_row)
            }
            _ => None,
        }
        .unwrap_or_else(|| {
            let mut mat = vec![0.0_f64; n * n];
            for i in 0..n {
                mat[i * n + i] = 1.0; // self-correlation
                for j in (i + 1)..n {
                    let val = match method {
                        "spearman" => match (
                            spearman_centered.get(i).and_then(Option::as_ref),
                            spearman_centered.get(j).and_then(Option::as_ref),
                        ) {
                            (Some(ri), Some(rj)) => spearman_centered_corr(ri, rj),
                            _ => series_list[i]
                                .corr_spearman(&series_list[j])
                                .unwrap_or(f64::NAN),
                        },
                        "kendall" => match (
                            kendall_values.get(i).and_then(Option::as_ref),
                            kendall_values.get(j).and_then(Option::as_ref),
                            kendall_orders.get(i).and_then(Option::as_ref),
                            kendall_rank_by_row.get(j).and_then(Option::as_ref),
                        ) {
                            (
                                Some(_left),
                                Some(_right),
                                Some(left_order),
                                Some(right_rank_by_row),
                            ) => Series::kendall_no_tie_fast_with_ordered_ranks(
                                left_order,
                                right_rank_by_row,
                            )
                            .unwrap_or_else(|| {
                                series_list[i]
                                    .corr_kendall(&series_list[j])
                                    .unwrap_or(f64::NAN)
                            }),
                            (Some(left), Some(right), _, _) => Series::kendall_no_tie_fast_slices(
                                left, right,
                            )
                            .unwrap_or_else(|| {
                                series_list[i]
                                    .corr_kendall(&series_list[j])
                                    .unwrap_or(f64::NAN)
                            }),
                            _ => series_list[i]
                                .corr_kendall(&series_list[j])
                                .unwrap_or(f64::NAN),
                        },
                        _ => f64::NAN,
                    };
                    mat[i * n + j] = val;
                    mat[j * n + i] = val;
                }
            }
            mat
        });

        let mut result_cols = BTreeMap::new();
        for (j, col_j_name) in numeric_cols.iter().enumerate() {
            let mut vals = Vec::with_capacity(n);
            for i in 0..n {
                vals.push(Scalar::Float64(mat[i * n + j]));
            }
            result_cols.insert(col_j_name.clone(), Column::new(DType::Float64, vals)?);
        }

        let labels: Vec<IndexLabel> = numeric_cols
            .iter()
            .map(|s| IndexLabel::Utf8(s.clone()))
            .collect();

        Ok(Self {
            columns: result_cols.into(),
            column_order: numeric_cols.into(),
            index: Index::new(labels),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Column-wise correlation with another DataFrame.
    ///
    /// Matches `df.corrwith(other)`. Returns a Series of Pearson correlations
    /// for each shared numeric column.
    pub fn corrwith(&self, other: &Self) -> Result<Series, FrameError> {
        // Each shared column's Pearson r is independent — a clone + two-pass
        // cov_components (~4 f64 passes over n), well above the thread-spawn
        // floor at scale — so the per-column work spreads across columns cleanly
        // (like abs/describe). par_map_columns returns results in column_order,
        // so the (label, value) sequence is byte-identical to the serial loop;
        // a Timedelta column yields the same CompatibilityRejected variant +
        // message regardless of which thread hits it first.
        let per_col = |name: &str| -> Result<Option<(IndexLabel, Scalar)>, FrameError> {
            let sc = match self.columns.get(name) {
                Some(c) => c,
                None => return Ok(None),
            };
            let oc = match other.columns.get(name) {
                Some(c) => c,
                None => return Ok(None),
            };
            let dt_s = sc.dtype();
            let dt_o = oc.dtype();
            if matches!(dt_s, DType::Timedelta64) || matches!(dt_o, DType::Timedelta64) {
                return Err(FrameError::CompatibilityRejected(
                    "corrwith: pandas rejects shared Timedelta64 columns".into(),
                ));
            }
            let numeric = |dt: DType| matches!(dt, DType::Int64 | DType::Float64);
            if !numeric(dt_s) || !numeric(dt_o) {
                return Ok(None);
            }
            let ss = Series::new(name.to_string(), self.index.clone(), sc.clone())?;
            let so = Series::new(name.to_string(), other.index.clone(), oc.clone())?;
            let r = ss.corr(&so)?;
            Ok(Some((
                IndexLabel::Utf8(name.to_string()),
                Scalar::Float64(r),
            )))
        };

        // par_map_columns keeps small/single-column frames serial (16384-cell,
        // >=2-col floor), so this only threads once the per-column corr amortizes
        // the spawn. Measured 200k×8: 14.85 ms serial -> 3.92 ms threaded (3.79x).
        let results: Vec<Option<(IndexLabel, Scalar)>> =
            self.par_map_columns(&self.column_order, |name| per_col(name))?;

        let mut labels = Vec::new();
        let mut values = Vec::new();
        for (label, value) in results.into_iter().flatten() {
            labels.push(label);
            values.push(value);
        }

        Series::from_values("corrwith".to_string(), labels, values)
    }

    /// Compute pairwise correlation with another DataFrame along the given axis.
    ///
    /// Matches `df.corrwith(other, axis=...)`.
    /// - `axis=0` (default): correlate matching columns
    /// - `axis=1`: correlate matching rows
    pub fn corrwith_axis(&self, other: &Self, axis: usize) -> Result<Series, FrameError> {
        match axis {
            0 => self.corrwith(other),
            1 => {
                // Row-wise correlation: for each row index present in both,
                // compute correlation across numeric columns
                for name in &self.column_order {
                    let Some(other_col) = other.columns.get(name) else {
                        continue;
                    };
                    let self_dtype = self.columns[name.as_str()].dtype();
                    let other_dtype = other_col.dtype();
                    if matches!(self_dtype, DType::Timedelta64)
                        || matches!(other_dtype, DType::Timedelta64)
                    {
                        return Err(FrameError::CompatibilityRejected(
                            "corrwith axis=1: pandas rejects shared Timedelta64 columns".into(),
                        ));
                    }
                }
                let shared_cols: Vec<String> = self
                    .column_order
                    .iter()
                    .filter(|name| {
                        other.columns.contains_key(name.as_str())
                            && matches!(
                                self.columns[name.as_str()].dtype(),
                                DType::Int64 | DType::Float64
                            )
                            && matches!(
                                other.columns[name.as_str()].dtype(),
                                DType::Int64 | DType::Float64
                            )
                    })
                    .cloned()
                    .collect();

                if shared_cols.len() < 2 {
                    return Err(FrameError::CompatibilityRejected(
                        "corrwith axis=1: need at least 2 shared numeric columns".into(),
                    ));
                }

                let mut labels = Vec::new();
                let mut values = Vec::new();

                // Build other's first-occurrence label->row map once (O(n))
                // instead of rescanning other's index per self-row. The old
                // `other.index.position(label)` is a linear scan for any index
                // that is not ascending-Int64, making this O(n·m). Bit-identical:
                // position_map_first records the FIRST occurrence, exactly what
                // Index::position returns.
                let other_pos = other.index.position_map_first();
                for (row_idx, label) in self.index.labels().iter().enumerate() {
                    // Find matching row in other
                    if let Some(&other_row_idx) = other_pos.get(label) {
                        let mut xs = Vec::new();
                        let mut ys = Vec::new();
                        for col_name in &shared_cols {
                            let xv = self.columns[col_name].values()[row_idx].to_f64();
                            let yv = other.columns[col_name].values()[other_row_idx].to_f64();
                            if let (Ok(x), Ok(y)) = (xv, yv)
                                && !x.is_nan()
                                && !y.is_nan()
                            {
                                xs.push(x);
                                ys.push(y);
                            }
                        }

                        let corr = if xs.len() < 2 {
                            f64::NAN
                        } else {
                            let n = xs.len() as f64;
                            let mx = xs.iter().sum::<f64>() / n;
                            let my = ys.iter().sum::<f64>() / n;
                            let cov: f64 =
                                xs.iter().zip(&ys).map(|(x, y)| (x - mx) * (y - my)).sum();
                            let vx: f64 = xs.iter().map(|x| (x - mx).powi(2)).sum();
                            let vy: f64 = ys.iter().map(|y| (y - my).powi(2)).sum();
                            let denom = (vx * vy).sqrt();
                            if denom < f64::EPSILON {
                                f64::NAN
                            } else {
                                cov / denom
                            }
                        };

                        labels.push(label.clone());
                        values.push(Scalar::Float64(corr));
                    }
                }

                // Per br-frankenpandas-hrsc3: pandas df.corrwith(other, axis=1)
                // preserves df.index.name on the row-wise correlation result.
                let index = Index::new(labels).rename_index(self.index.name());
                let column = Column::from_values(values)?;
                Series::new("corrwith".to_string(), index, column)
            }
            _ => Err(FrameError::CompatibilityRejected(format!(
                "corrwith: axis must be 0 or 1, got {axis}"
            ))),
        }
    }

    /// Matrix dot product with another DataFrame.
    ///
    /// Matches `df.dot(other)`. Computes matrix multiplication where
    /// self's columns are matched to other's index.
    pub fn dot(&self, other: &Self) -> Result<Self, FrameError> {
        // self: (m x k), other: (k x n) → result: (m x n)
        let m = self.len();
        let k = self.num_columns();

        if k != other.len() {
            return Err(FrameError::CompatibilityRejected(format!(
                "dot: self has {k} columns but other has {} rows",
                other.len()
            )));
        }

        let n = other.num_columns();

        // A finite `(Arc<[f64]>, start)` view for one column: an all-valid no-NaN/
        // inf Float64 column exposes a zero-copy arc view; an all-valid Int64 column
        // materializes the `v as f64` view once (always finite). This lets the typed
        // SIMD `from_f64_all_valid_dot_product` path also serve Int64 (and mixed)
        // frames — bit-identical to the all-Float64 typed path it already runs, since
        // `to_f64(Int64(v)) == v as f64` and the products/summation are the same.
        let finite_f64_view = |col: &Column, len: usize| -> Option<(Arc<[f64]>, usize)> {
            if let Some(view) = col.as_f64_finite_arc_view_source(len) {
                Some(view)
            } else if let Some(d) = col.as_i64_slice() {
                let owned: Arc<[f64]> = d.iter().map(|&v| v as f64).collect();
                Some((owned, 0))
            } else {
                None
            }
        };

        let collect_finite_float64_views =
            |frame: &Self, row_len: usize| -> Option<Vec<(Arc<[f64]>, usize)>> {
                let mut views = Vec::with_capacity(frame.num_columns());
                for name in &frame.column_order {
                    let col = frame.columns.get(name)?;
                    let (data, start) = finite_f64_view(col, row_len)?;
                    views.push((data, start));
                }
                Some(views)
            };

        if let Some(a_views) = collect_finite_float64_views(self, m) {
            let mut result_cols = BTreeMap::new();
            let mut col_order = Vec::with_capacity(n);
            let mut b_values_by_column: Vec<Arc<[f64]>> = Vec::with_capacity(n);
            let mut all_b_finite = true;
            // Build the shared left (A) panel ONCE and clone its inner Arc per
            // output column, instead of rebuilding the k Float64DotInputs +
            // a fresh Arc<[..]> for every one of the n columns (an O(n·k)
            // construction tax).
            let a_panel = fp_columnar::Float64DotAPanel::new(a_views, m);
            for name in &other.column_order {
                let col = &other.columns[name];
                let Some((data, start)) = finite_f64_view(col, k) else {
                    all_b_finite = false;
                    break;
                };
                let Some(end) = start.checked_add(k) else {
                    all_b_finite = false;
                    break;
                };
                let Some(slice) = data.get(start..end) else {
                    all_b_finite = false;
                    break;
                };
                let b_values: Arc<[f64]> = if start == 0 && data.len() == k {
                    data
                } else {
                    Arc::from(slice.to_vec())
                };
                b_values_by_column.push(b_values);
                col_order.push(name.clone());
            }

            if all_b_finite {
                // PERSISTENT POOL, NOT A SCOPE PER CALL (br-frankenpandas-03fp5).
                // The scoped path spawned one thread per worker on EVERY `dot`
                // — 63 of them per call at `dim = 1000` — and the mid-slot clock
                // sampler measured the consequence directly: FrankenPandas' own
                // cores span 2.8892x mid-flight against the incumbent's 1.0463x,
                // because at any instant some are between scopes. `str_worker_pool`
                // already solves this safely for the string kernels, with
                // per-worker channels and threads spawned once per process.
                //
                // Everything a column needs is `Arc`-backed, so each job clones
                // handles and is `'static`. Bit-identical: every column runs the
                // same `materialize_float64_dot` over the same operands in the
                // same `j = 0..k` order; only which thread calls it changes, and
                // the result is assembled in `col_order` order regardless of
                // completion order.
                // ONE JOB PER WORKER, NOT ONE PER COLUMN. The pool dispatches
                // job i to worker i and documents that a caller exceeding its
                // width degrades to caller-side execution — handing it 1000
                // column-jobs for 64 workers ran 936 of them serially and
                // measured 175 ms against the scoped path's 21 ms. Chunking to
                // the pool's width is how the scoped path already grouped
                // columns; only the thread mechanism changes.
                // Chunk count from the SAME work rule the scoped path used, so
                // `FP_DOT_WORK_PER_WORKER` still governs and a tiny dot does not
                // dispatch 64 channel jobs to multiply a handful of numbers. The
                // constant it defaults to was calibrated against ~60us-per-spawn
                // scoped dispatch; the pool makes dispatch far cheaper, which is
                // why it is a knob and not a literal here.
                let width = str_worker_pool::pool().threads().max(1);
                let total_work = (b_values_by_column.len() as u128) * (k as u128) * (m as u128);
                let workers = Column::dot_chunk_count(
                    total_work,
                    width,
                    b_values_by_column.len(),
                    pooled_work_per_chunk(),
                )
                .max(1);
                let chunk = b_values_by_column.len().div_ceil(workers).max(1);
                // br-frankenpandas-mti15. ONE PASS OVER A PER CHUNK, not one per
                // column. `dot_column_data` re-streams the whole A panel for
                // EVERY column it is handed, so a chunk of 16 columns read
                // `m * k * 8` bytes 16 times; the blocked kernel holds an 8x6
                // output tile in vector registers across the whole `k` loop and
                // reads it `n / 6` times instead. Bit-identical — each output
                // still accumulates `j = 0..k` in the same order — and the
                // per-column entry remains the fallback inside
                // `dot_columns_data_blocked` for a chunk of one or a pre-AVX2
                // CPU.
                //
                // The panel is packed ONCE here, outside the jobs, and shared by
                // `Arc`: packing inside each job would repeat `m * k` copies per
                // worker, which is the redundancy this hoist exists to remove.
                // Only worth packing when some job actually gets a batch: with
                // `chunk == 1` every job takes the per-column fallback and the
                // pack would be `m * k * 8` bytes of pure waste.
                let packed_panel: Arc<[f64]> = if chunk >= 2 {
                    Arc::from(Column::pack_dot_panel(&a_panel, m))
                } else {
                    Arc::from(Vec::new())
                };
                let jobs: Vec<_> = b_values_by_column
                    .chunks(chunk)
                    .map(|group| {
                        let panel = a_panel.clone();
                        let packed = Arc::clone(&packed_panel);
                        let group: Vec<Arc<[f64]>> = group.to_vec();
                        move || {
                            let b_cols: Vec<&[f64]> =
                                group.iter().map(|b_values| &b_values[..]).collect();
                            Column::dot_columns_data_blocked(&panel, &packed, &b_cols, m)
                        }
                    })
                    .collect();
                let produced: Vec<Vec<f64>> = str_worker_pool::pool()
                    .run(jobs)
                    .into_iter()
                    .flatten()
                    .collect();
                for (name, data) in col_order.iter().zip(produced) {
                    result_cols.insert(name.clone(), Column::from_f64_values(data));
                }

                // Materialize the n output columns in ONE scope, parallel
                // across columns (br-frankenpandas-1hjgz).
                //
                // Each output column is lazy behind its own `OnceLock`, and the
                // consumer reads them one at a time — which is why a `df.dot`
                // row records `thread_count_actually_used = 1` and why the
                // measured ratio is 0.136x (FP 209ms vs pandas 28ms at 1M).
                // Per-thread throughput is already competitive; the kernel was
                // simply running on one core.
                //
                // Doing it HERE rather than leaving it to the first reader is
                // the whole point: at this moment all n columns are known and
                // independent, so one scope covers the entire result. A reader
                // arriving column-by-column can never recover that.
                //
                // Bit-identical: no column's arithmetic changes, only which
                // thread calls its unchanged materializer. `OnceLock` keeps
                // exactly-once semantics, so a concurrent reader sees the same
                // bytes either way — which also means this is safe to skip
                // (`FP_DOT_SERIAL=1`) without changing any result.
                let pending: Vec<&Column> = col_order
                    .iter()
                    .filter_map(|name| result_cols.get(name))
                    .collect();
                Column::materialize_dot_columns_parallel(&pending);

                return Ok(Self {
                    columns: result_cols.into(),
                    column_order: col_order.into(),
                    index: self.index.clone(),
                    column_multiindex: None,
                    row_multiindex: None,
                    allows_duplicate_labels: self.allows_duplicate_labels,
                });
            }
        }

        // Register-blocked GEMM. Two structural changes over the naive triple
        // loop, both bit-identical to it:
        //   1. Typed extraction: pull each all-valid Float64 column as a
        //      contiguous &[f64] (as_f64_slice) instead of per-element Scalar
        //      to_f64 dispatch; non-typed / nullable columns fall back to the
        //      identical Scalar path, so every C[i][j] sees the same operands.
        //   2. A 4x4 micro-kernel runs 16 INDEPENDENT accumulators over one
        //      shared l-loop. Each accumulator C[i][j] starts at 0.0 and does
        //      `acc += a[i][l] * b[j][l]` for l = 0..k — the exact same
        //      left-fold (and the same f64 products) as the scalar
        //      `row.zip(col).map(a*b).sum()`. Interleaving 16 chains hides the
        //      FP-add latency that bottlenecks the single sequential reduction,
        //      without reassociating any one cell's sum. Bit-identical.
        //
        // b: row-major-by-other-column (n x k), b[j*k + l] = other[l][j]
        //
        // A stays COLUMN-MAJOR (br-frankenpandas-uza04.98): the prior row-major
        // `a[i*k+l] = self[i][l]` build was a scattered column->row transpose —
        // 25.6M stride-k (one-per-cache-line) writes that cost ~300ms (>2x the
        // GEMM compute itself). Borrow each all-valid Float64 column as its
        // contiguous `&[f64]` (free) and let the kernel read `a_cols[l][row]`
        // directly: for a 4-row tile the `di` loop walks 4 CONSECUTIVE rows of
        // column `l` (contiguous), so column-major is cache-friendly here and
        // the transpose vanishes. Non-f64 / nullable columns materialize once
        // (identical operands). `a_cols[l][i] == old a[i*k+l] == self[i][l]`, so
        // every C[i][j] fold is byte-identical.
        let a_cols: Vec<std::borrow::Cow<'_, [f64]>> = self
            .column_order
            .iter()
            .map(|name| {
                let col = &self.columns[name];
                if let Some(s) = col.as_f64_slice() {
                    std::borrow::Cow::Borrowed(s)
                } else {
                    let vals = col.values();
                    std::borrow::Cow::Owned(
                        (0..m)
                            .map(|i| vals[i].to_f64().unwrap_or(f64::NAN))
                            .collect(),
                    )
                }
            })
            .collect();
        let a_cols_ref: &[std::borrow::Cow<'_, [f64]>] = &a_cols;
        let mut b = vec![0.0_f64; n * k];
        for (j, name) in other.column_order.iter().enumerate() {
            let col = &other.columns[name];
            if let Some(s) = col.as_f64_slice() {
                b[j * k..j * k + k].copy_from_slice(s);
            } else {
                let vals = col.values();
                for l in 0..k {
                    b[j * k + l] = vals[l].to_f64().unwrap_or(f64::NAN);
                }
            }
        }

        const BI: usize = 4;
        const BJ: usize = 4;
        // Communication-avoiding ROW-banded GEMM (br-frankenpandas-uza04.98):
        // the prior column-partitioned kernel (seti2) made EVERY worker
        // re-stream the whole A (m×k) matrix from DRAM — for n=100000,k=256
        // that is ~64×205MB ≈ 13GB of A traffic. Here each worker owns a
        // disjoint BAND OF OUTPUT ROWS and computes ALL n columns for it, so it
        // reads only its A-band with the 4×4 A-tile resident in L1 and the
        // packed B (n·k ≈ 512KB) streamed from L2. Bit-identical: every C[i][j]
        // is the same 4×4-tiled, l=0..k ascending left-fold with the same f64
        // products (separate `*` then `+=`, no FMA); only the owning thread and
        // loop nesting differ.
        //
        // Pack B once (shared, read-only): bpacked[jb*(k*BJ) + l*BJ + dj] holds
        // BJ output columns interleaved by depth l — one cache line per l.
        let n_blocks = n.div_ceil(BJ);
        let mut bpacked = vec![0.0_f64; n_blocks * k * BJ];
        for jb in 0..n_blocks {
            let jj = jb * BJ;
            let bj = BJ.min(n - jj);
            let base = jb * k * BJ;
            for dj in 0..bj {
                let bcol = &b[(jj + dj) * k..(jj + dj) * k + k];
                for l in 0..k {
                    bpacked[base + l * BJ + dj] = bcol[l];
                }
            }
        }
        let bpacked_ref: &[f64] = &bpacked;

        struct DotBand {
            i0: usize,
            bw: usize,
            values: Arc<[f64]>,
            column_has_nan: Vec<bool>,
        }

        // Compute global output rows [i0, i0+bw) for ALL n columns, returned
        // column-major-within-band: band[j*bw + i_local] = C[i0+i_local][j].
        // Row-tile (BI) is the outer loop so each 4-row A-tile is loaded once
        // (L1-resident) and reused across every column block.
        let compute_band = |i0: usize, bw: usize| -> DotBand {
            let mut band = vec![0.0_f64; bw * n];
            let mut column_has_nan = vec![false; n];
            let mut ii = 0;
            while ii < bw {
                let bi = BI.min(bw - ii);
                let mut jb = 0;
                while jb < n_blocks {
                    let jj = jb * BJ;
                    let bj = BJ.min(n - jj);
                    let bp_base = jb * k * BJ;
                    let mut acc = [[0.0_f64; BJ]; BI];
                    let row0 = i0 + ii;
                    if bi == BI && bj == BJ {
                        let mut acc0 = std::simd::Simd::<f64, BJ>::splat(0.0);
                        let mut acc1 = std::simd::Simd::<f64, BJ>::splat(0.0);
                        let mut acc2 = std::simd::Simd::<f64, BJ>::splat(0.0);
                        let mut acc3 = std::simd::Simd::<f64, BJ>::splat(0.0);
                        for l in 0..k {
                            let bp_slice = &bpacked_ref[bp_base + l * BJ..bp_base + l * BJ + BJ];
                            let bp = std::simd::Simd::<f64, BJ>::from_array([
                                bp_slice[0],
                                bp_slice[1],
                                bp_slice[2],
                                bp_slice[3],
                            ]);
                            let col_l = &a_cols_ref[l];
                            let av0 = std::simd::Simd::<f64, BJ>::splat(col_l[row0]);
                            let av1 = std::simd::Simd::<f64, BJ>::splat(col_l[row0 + 1]);
                            let av2 = std::simd::Simd::<f64, BJ>::splat(col_l[row0 + 2]);
                            let av3 = std::simd::Simd::<f64, BJ>::splat(col_l[row0 + 3]);
                            acc0 += av0 * bp;
                            acc1 += av1 * bp;
                            acc2 += av2 * bp;
                            acc3 += av3 * bp;
                        }
                        acc[0] = acc0.to_array();
                        acc[1] = acc1.to_array();
                        acc[2] = acc2.to_array();
                        acc[3] = acc3.to_array();
                    } else {
                        for l in 0..k {
                            let col_l = &a_cols_ref[l];
                            for (di, acc_row) in acc.iter_mut().enumerate().take(bi) {
                                let av = col_l[row0 + di];
                                for (dj, slot) in acc_row.iter_mut().enumerate().take(bj) {
                                    *slot += av * bpacked_ref[bp_base + l * BJ + dj];
                                }
                            }
                        }
                    }
                    for (di, acc_row) in acc.iter().enumerate().take(bi) {
                        for (dj, slot) in acc_row.iter().enumerate().take(bj) {
                            let value = *slot;
                            let j = jj + dj;
                            column_has_nan[j] |= value.is_nan();
                            band[j * bw + (ii + di)] = value;
                        }
                    }
                    jb += 1;
                }
                ii += BI;
            }
            DotBand {
                i0,
                bw,
                values: Arc::from(band),
                column_has_nan,
            }
        };

        let worker_count = fp_columnar::cached_available_parallelism()
            .min(64)
            .min(m.div_ceil(BI).max(1));
        let big_enough = (m as u128) * (k as u128) * (n as u128) >= (1u128 << 20);

        // Compute the output as row-banded `band` buffers (column-major-within-
        // band: band[j*bw + local]).
        let mut bands: Vec<DotBand> = if worker_count >= 2 && big_enough && m > 0 {
            let band_rows = m.div_ceil(worker_count);
            let compute_ref = &compute_band;
            std::thread::scope(|scope| {
                let mut handles = Vec::new();
                let mut i0 = 0;
                while i0 < m {
                    let bw = band_rows.min(m - i0);
                    handles.push(scope.spawn(move || compute_ref(i0, bw)));
                    i0 += band_rows;
                }
                handles
                    .into_iter()
                    .map(|h| h.join().expect("dot worker panicked"))
                    .collect()
            })
        } else if m > 0 {
            vec![compute_band(0, m)]
        } else {
            Vec::new()
        };

        // Assemble each output column j as the concatenation, in ascending
        // row-band order, of every band's column-j slice (br-frankenpandas-uza04.101).
        // The prior path allocated and ZEROED an n×m `cols` buffer (~205MB at
        // n=256,m=100000) and then scatter-copied the bands into it — a serial
        // double-touch of the whole output that DOMINATED the op (~95ms vs ~52ms
        // compute). Here each column is built once via `Vec::with_capacity` +
        // `extend_from_slice` (no zero-fill, no second pass), and the columns —
        // independent — are fanned across workers. Byte-identical: column j is
        // the same C[*][j] values in the same row order.
        // Build the final `Column` for output column j directly inside the
        // worker. For all-valid outputs, each column adopts immutable views
        // into the private row-band buffers instead of copying every band slice
        // into a second contiguous column buffer. A per-band NaN witness keeps
        // pandas missing-value semantics exact: if any output cell is NaN, the
        // column falls back to the existing concat + `from_f64_values` path.
        bands.sort_by_key(|band| band.i0);
        let bands_ref: &[DotBand] = &bands;
        let build_col = |j: usize| -> Column {
            let mut has_nan = false;
            let mut chunks = Vec::with_capacity(bands_ref.len());
            for band in bands_ref {
                has_nan |= band.column_has_nan[j];
                chunks.push((Arc::clone(&band.values), j * band.bw, band.bw));
            }
            if !has_nan {
                return Column::from_f64_all_valid_chunks(chunks, m);
            }

            let mut col = Vec::with_capacity(m);
            for band in bands_ref {
                col.extend_from_slice(&band.values[j * band.bw..j * band.bw + band.bw]);
            }
            Column::from_f64_values(col)
        };
        let mut columns: Vec<Column> = Vec::with_capacity(n);
        if worker_count >= 2 && big_enough && n >= 2 {
            let next = std::sync::atomic::AtomicUsize::new(0);
            let build_ref = &build_col;
            let mut slots: Vec<Option<Column>> = (0..n).map(|_| None).collect();
            let parts = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(worker_count);
                for _ in 0..worker_count {
                    let next = &next;
                    handles.push(scope.spawn(move || {
                        let mut out: Vec<(usize, Column)> = Vec::new();
                        loop {
                            let j = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            if j >= n {
                                break;
                            }
                            out.push((j, build_ref(j)));
                        }
                        out
                    }));
                }
                handles
                    .into_iter()
                    .map(|h| h.join().expect("dot assembly worker panicked"))
                    .collect::<Vec<_>>()
            });
            for part in parts {
                for (j, col) in part {
                    slots[j] = Some(col);
                }
            }
            columns.extend(
                slots
                    .into_iter()
                    .map(|s| s.expect("every output column built")),
            );
        } else {
            columns.extend((0..n).map(build_col));
        }

        // Assemble result columns in `other.column_order`.
        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::with_capacity(n);
        for (col, other_col_name) in columns.into_iter().zip(other.column_order.iter()) {
            result_cols.insert(other_col_name.clone(), col);
            col_order.push(other_col_name.clone());
        }

        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index: self.index.clone(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Compute the number of unique values per column.
    pub fn value_counts_per_column(&self) -> Result<Self, FrameError> {
        let mut labels = Vec::new();
        let mut counts = Vec::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let mut seen: FxHashSet<ScalarKey<'_>> = FxHashSet::default();
            for v in col.values() {
                if let Some(key) = scalar_key_skip_missing(v) {
                    seen.insert(key);
                }
            }
            labels.push(IndexLabel::Utf8(col_name.clone()));
            counts.push(Scalar::Int64(seen.len() as i64));
        }
        let mut result_cols = BTreeMap::new();
        result_cols.insert("nunique".to_string(), Column::new(DType::Int64, counts)?);
        Ok(Self {
            columns: result_cols.into(),
            column_order: vec!["nunique".to_string()].into(),
            index: Index::new(labels),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Single-cell access by integer (row_pos, col_pos).
    ///
    /// Matches `pd.DataFrame.iat[i, j]`. Negative positions count
    /// from the end (pandas convention). Returns
    /// `CompatibilityRejected` for out-of-range row or column
    /// positions.
    pub fn iat(&self, row_pos: i64, col_pos: i64) -> Result<Scalar, FrameError> {
        let n_rows = self.index.labels().len();
        let row_idx = if row_pos < 0 {
            (n_rows as i64 + row_pos) as usize
        } else {
            row_pos as usize
        };
        if row_idx >= n_rows {
            return Err(FrameError::CompatibilityRejected(format!(
                "DataFrame.iat: row position {row_pos} out of bounds for length {n_rows}"
            )));
        }
        let n_cols = self.column_order.len();
        let col_idx = if col_pos < 0 {
            (n_cols as i64 + col_pos) as usize
        } else {
            col_pos as usize
        };
        if col_idx >= n_cols {
            return Err(FrameError::CompatibilityRejected(format!(
                "DataFrame.iat: column position {col_pos} out of bounds for width {n_cols}"
            )));
        }
        let col_name = &self.column_order[col_idx];
        Ok(self.columns[col_name].values()[row_idx].clone())
    }

    /// Replace the row index or column names without touching data.
    ///
    /// Matches `pd.DataFrame.set_axis(labels, axis=0|1)`:
    /// - `axis=0`: replace the row index with `labels`.
    /// - `axis=1`: replace column names with stringified `labels`.
    ///
    /// Returns `LengthMismatch` when `labels.len()` doesn't match the
    /// chosen axis; returns `CompatibilityRejected` for unknown axis.
    pub fn set_axis(&self, labels: Vec<IndexLabel>, axis: usize) -> Result<Self, FrameError> {
        match axis {
            0 => {
                if labels.len() != self.index.labels().len() {
                    return Err(FrameError::LengthMismatch {
                        index_len: labels.len(),
                        column_len: self.index.labels().len(),
                    });
                }
                // Per br-frankenpandas-gyej0: pandas df.set_axis(labels, axis=0)
                // preserves index name (metadata separate from labels).
                let new_index = Index::new(labels).rename_index(self.index.name());
                Self::validate_duplicate_label_policy(
                    self.allows_duplicate_labels,
                    &new_index,
                    None,
                    "set_axis",
                )?;
                Ok(Self {
                    columns: self.columns.clone(),
                    column_order: self.column_order.clone(),
                    index: new_index,
                    column_multiindex: self.column_multiindex.clone(),
                    row_multiindex: None,
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
            1 => {
                if labels.len() != self.column_order.len() {
                    return Err(FrameError::LengthMismatch {
                        index_len: labels.len(),
                        column_len: self.column_order.len(),
                    });
                }
                let new_names: Vec<String> = labels.iter().map(IndexLabel::to_string).collect();
                let mut new_columns = BTreeMap::new();
                for (old, new) in self.column_order.iter().zip(new_names.iter()) {
                    new_columns.insert(new.clone(), self.columns[old].clone());
                }
                Ok(Self {
                    columns: new_columns.into(),
                    column_order: new_names.into(),
                    index: self.index.clone(),
                    column_multiindex: None,
                    row_multiindex: None,
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
            other => Err(FrameError::CompatibilityRejected(format!(
                "set_axis: axis must be 0 or 1, got {other}"
            ))),
        }
    }

    /// Single-cell access by (row label, column name).
    ///
    /// Matches `pd.DataFrame.at[label, col]`. Returns `None` when the
    /// row label is not present in the index or the column name is
    /// unknown. Use `.iloc` / `iat`-style positional access on the
    /// underlying Index+Column for integer positions.
    pub fn at(&self, label: &IndexLabel, column: &str) -> Result<Scalar, FrameError> {
        let row = self.index.position(label).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!(
                "DataFrame.at: label {label:?} not found in index"
            ))
        })?;
        let col = self.columns.get(column).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("DataFrame.at: column {column:?} not found"))
        })?;
        Ok(col.values()[row].clone())
    }

    /// Per-column value counts as a map of Series.
    ///
    /// Returns `{column_name → Series}` where each Series is the
    /// `value_counts()` result for that column. This is distinct from
    /// both `value_counts()` (counts unique full-row tuples) and
    /// `value_counts_per_column()` (returns a nunique summary
    /// DataFrame). Callers who want the pandas idiom
    /// `{col: df[col].value_counts() for col in df.columns}` get it
    /// in one pass here.
    pub fn value_counts_map(&self) -> Result<BTreeMap<String, Series>, FrameError> {
        let mut out = BTreeMap::new();
        for name in &self.column_order {
            let series = self.column_as_series(name)?;
            let counts = series.value_counts()?;
            out.insert(name.clone(), counts);
        }
        Ok(out)
    }

    /// Count unique rows in the DataFrame.
    ///
    /// Matches `pd.DataFrame.value_counts()`. Returns a Series indexed by
    /// composite row values, with counts as values, sorted descending.
    pub fn value_counts(&self) -> Result<Series, FrameError> {
        if self.column_order.is_empty() {
            return Series::from_values("count".to_string(), Vec::new(), Vec::new());
        }

        // Typed dense fast path: when every column is bounded-Int64 or contiguous-
        // Utf8 (all-valid) with a bounded combined cardinality, factorize + dense
        // gid-count instead of the per-row Vec<ScalarKey> + per-cell Scalar/to_string.
        if let Some(typed) = self.value_counts_dense_contiguous()? {
            return Ok(typed);
        }

        // Per br-frankenpandas-62849: O(n) HashMap-driven counter with
        // parallel insertion-ordered Vec for stable first-seen ordering
        // (same shape as br-7c7d0 Series::value_counts fix). Vec<ScalarKey>
        // is Hash + Eq via the ScalarKey derive; using it as a HashMap key
        // gives O(1) lookup per row instead of O(n) linear scan.
        let mut key_counts: Vec<(Vec<ScalarKey<'_>>, String, i64)> = Vec::new();
        let mut idx_map: HashMap<Vec<ScalarKey<'_>>, usize> = HashMap::new();

        for i in 0..self.len() {
            // pandas DataFrame.value_counts defaults to dropna=TRUE, and it
            // drops a row if ANY subset column is missing — not just the ones
            // that are entirely null. MEASURED, live pandas 2.2.3, on
            // DataFrame({'a':[1,1,2,None], 'b':[1,None,2,1]}):
            //   df.value_counts()             -> {(1.0,1.0): 1, (2.0,2.0): 1}
            //   df.value_counts(dropna=False) -> adds (1.0,nan) and (nan,1.0)
            // FrankenPandas counted every row, so it returned four rows where
            // pandas returns two. (br-frankenpandas-2a8yn)
            //
            // The dense fast path above cannot reach this: it is gated on
            // as_i64_slice / contiguous-Utf8 backings, which are all-valid by
            // construction, so a null-bearing frame always lands here.
            if self
                .column_order
                .iter()
                .any(|col_name| self.columns[col_name].values()[i].is_missing())
            {
                continue;
            }
            let mut parts = Vec::with_capacity(self.column_order.len());
            let mut key_parts = Vec::with_capacity(self.column_order.len());
            for col_name in &self.column_order {
                let value = &self.columns[col_name].values()[i];
                parts.push(value.to_string());
                key_parts.push(scalar_key_allow_missing(value));
            }
            let key_label = parts.join(", ");

            match idx_map.get(&key_parts) {
                Some(&idx) => key_counts[idx].2 += 1,
                None => {
                    idx_map.insert(key_parts.clone(), key_counts.len());
                    key_counts.push((key_parts, key_label, 1));
                }
            }
        }
        drop(idx_map);

        // Sort by count descending; pandas breaks count ties by the row's
        // composite key ASCENDING (numeric-aware), NOT by first occurrence —
        // verified vs live pandas 2.2.3: value_counts of rows [10,10,2,2,5]
        // orders (2)=2, (10)=2, (5)=1. composite_key_cmp gives the same
        // numeric tuple ordering used by groupby key sorting.
        key_counts.sort_by(|a, b| b.2.cmp(&a.2).then_with(|| composite_key_cmp(&a.0, &b.0)));

        let labels: Vec<IndexLabel> = key_counts
            .iter()
            .map(|(_, label, _)| IndexLabel::Utf8(label.clone()))
            .collect();
        let values: Vec<Scalar> = key_counts
            .iter()
            .map(|(_, _, count)| Scalar::Int64(*count))
            .collect();

        Series::from_values("count".to_string(), labels, values)
    }

    /// Dense fast path for [`value_counts`]: every column bounded-Int64 or
    /// contiguous-Utf8 (all-valid) with bounded combined cardinality. Factorizes
    /// each column, counts distinct row-tuples via a dense gid table, then emits
    /// the same `count desc, composite_key_cmp asc` ordering and `", "`-joined
    /// labels as the generic path. Bit-identical: MixedKey::cmp == composite_key_cmp
    /// and MixedKey Display == Scalar Display for Int64/Utf8; all-valid backings mean
    /// no missing key class. Returns None (→ generic path) on any other dtype, a
    /// missing-bearing column, or a cardinality past the dense gate.
    fn value_counts_dense_contiguous(&self) -> Result<Option<Series>, FrameError> {
        let n = self.len();
        if n == 0 {
            return Ok(None);
        }
        enum ColKey<'a> {
            Int(&'a [i64], i64),
            Str(Vec<u32>, Vec<&'a str>),
        }
        let mut cols: Vec<ColKey<'_>> = Vec::with_capacity(self.column_order.len());
        let mut ranges: Vec<usize> = Vec::with_capacity(self.column_order.len());
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            if let Some(s) = col.as_i64_slice() {
                if s.len() != n {
                    return Ok(None);
                }
                let mut mn = s[0];
                let mut mx = s[0];
                for &v in s {
                    if v < mn {
                        mn = v;
                    } else if v > mx {
                        mx = v;
                    }
                }
                ranges.push((mx as i128 - mn as i128 + 1) as usize);
                cols.push(ColKey::Int(s, mn));
            } else if let Some((bytes, offsets)) = col.as_utf8_contiguous() {
                let nr = offsets.len() - 1;
                if nr != n {
                    return Ok(None);
                }
                let mut map: FxHashMap<&[u8], u32> = FxHashMap::default();
                let mut codes: Vec<u32> = Vec::with_capacity(nr);
                let mut inverse: Vec<&str> = Vec::new();
                let mut card: u32 = 0;
                for row in 0..nr {
                    let span = &bytes[offsets[row]..offsets[row + 1]];
                    let code = *map.entry(span).or_insert_with(|| {
                        let c = card;
                        card += 1;
                        c
                    });
                    if code as usize == inverse.len() {
                        inverse.push(
                            std::str::from_utf8(span)
                                .expect("contiguous utf8 buffer is valid by construction"),
                        );
                    }
                    codes.push(code);
                }
                ranges.push(card as usize);
                cols.push(ColKey::Str(codes, inverse));
            } else {
                return Ok(None);
            }
        }
        let combined: u128 = ranges
            .iter()
            .fold(1u128, |acc, &r| acc.saturating_mul(r as u128));
        if combined > (1u128 << 24) || combined > (n as u128).saturating_mul(16) {
            return Ok(None);
        }
        let combined = combined as usize;
        let ncol = ranges.len();
        let mut strides = vec![1usize; ncol];
        for c in (0..ncol - 1).rev() {
            strides[c] = strides[c + 1] * ranges[c + 1];
        }
        let mut gid_table = vec![usize::MAX; combined];
        let mut count: Vec<i64> = Vec::new();
        let mut key_of_gid: Vec<Vec<MixedKey>> = Vec::new();
        for row in 0..n {
            let mut slot = 0usize;
            for c in 0..ncol {
                let code = match &cols[c] {
                    ColKey::Int(s, min) => (s[row] as i128 - *min as i128) as usize,
                    ColKey::Str(codes, _) => codes[row] as usize,
                };
                slot += code * strides[c];
            }
            if gid_table[slot] == usize::MAX {
                gid_table[slot] = count.len();
                key_of_gid.push(
                    (0..ncol)
                        .map(|c| match &cols[c] {
                            ColKey::Int(s, _) => MixedKey::Int64(s[row]),
                            ColKey::Str(codes, inverse) => {
                                MixedKey::Utf8(inverse[codes[row] as usize].to_string())
                            }
                        })
                        .collect(),
                );
                count.push(1);
            } else {
                count[gid_table[slot]] += 1;
            }
        }
        let d = count.len();
        let mut order: Vec<usize> = (0..d).collect();
        order.sort_by(|&a, &b| {
            count[b]
                .cmp(&count[a])
                .then_with(|| key_of_gid[a].cmp(&key_of_gid[b]))
        });
        let labels: Vec<IndexLabel> = order
            .iter()
            .map(|&g| {
                let parts: Vec<String> = key_of_gid[g].iter().map(ToString::to_string).collect();
                IndexLabel::Utf8(parts.join(", "))
            })
            .collect();
        let values: Vec<Scalar> = order.iter().map(|&g| Scalar::Int64(count[g])).collect();
        Ok(Some(Series::from_values(
            "count".to_string(),
            labels,
            values,
        )?))
    }

    /// Count unique value combinations for a subset of columns.
    ///
    /// Matches `df.value_counts(subset=['col1','col2'])`. Counts
    /// combinations of values in the specified columns only.
    pub fn value_counts_subset(&self, subset: &[&str]) -> Result<Series, FrameError> {
        for name in subset {
            if !self.columns.contains_key(name) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "column not found: '{name}'"
                )));
            }
        }
        let selected = self.select_columns(subset)?;
        selected.value_counts()
    }

    /// Infer better dtypes for object columns.
    ///
    /// Matches `pd.DataFrame.infer_objects()`. Attempts to convert Utf8
    /// columns to numeric types. Delegates to per-column convert_dtypes.
    pub fn infer_objects(&self) -> Result<Self, FrameError> {
        self.convert_dtypes()
    }

    /// Get the top N rows ordered by a column.
    pub fn nlargest(&self, n: usize, column: &str) -> Result<Self, FrameError> {
        self.nlargest_or_smallest(n, column, false)
    }

    /// Get the bottom N rows ordered by a column.
    pub fn nsmallest(&self, n: usize, column: &str) -> Result<Self, FrameError> {
        self.nlargest_or_smallest(n, column, true)
    }

    /// Shared top/bottom-N. For small `n` on dense typed keys, select only the
    /// top/bottom prefix positions and sort that prefix with the same value plus
    /// input-position comparator as `sort_values(column, asc).head(n)`. Large
    /// `n` and semantic edge cases fall back to the full typed sort or the
    /// generic sort path.
    fn nlargest_or_smallest(
        &self,
        n: usize,
        column: &str,
        ascending: bool,
    ) -> Result<Self, FrameError> {
        let col = self.columns.get(column).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("column '{column}' not found"))
        })?;
        let take = n.min(self.len());
        if let Some(order) = typed_dense_topk_order(col.values(), col.dtype(), take, ascending) {
            return self.take_rows_by_positions_unchecked(&order);
        }
        if take < self.len()
            && let Some(order) = typed_dense_sort_order(col.values(), col.dtype(), ascending)
        {
            return self.take_rows_by_positions_unchecked(&order[..take]);
        }
        let sorted = self.sort_values(column, ascending)?;
        sorted.head(n as i64)
    }

    /// Get the top N rows ordered by multiple columns.
    ///
    /// Matches `df.nlargest(n, columns=[...])`.
    pub fn nlargest_multi(&self, n: usize, columns: &[&str]) -> Result<Self, FrameError> {
        let ascending: Vec<bool> = columns.iter().map(|_| false).collect();
        let sorted = self.sort_values_multi(columns, &ascending, "last")?;
        sorted.head(n as i64)
    }

    /// Get the bottom N rows ordered by multiple columns.
    ///
    /// Matches `df.nsmallest(n, columns=[...])`.
    pub fn nsmallest_multi(&self, n: usize, columns: &[&str]) -> Result<Self, FrameError> {
        let ascending: Vec<bool> = columns.iter().map(|_| true).collect();
        let sorted = self.sort_values_multi(columns, &ascending, "last")?;
        sorted.head(n as i64)
    }

    /// Get the top N rows with keep parameter.
    ///
    /// Matches `pd.DataFrame.nlargest(n, columns, keep)`.
    /// - "first": keep first occurrence (default)
    /// - "last": keep last occurrence
    /// - "all": keep all tied values (may return more than n rows)
    pub fn nlargest_keep(&self, n: usize, column: &str, keep: &str) -> Result<Self, FrameError> {
        match keep {
            "first" => self.nlargest(n, column),
            "last" => {
                // Reverse, take first n, reverse back
                let sorted = self.sort_values(column, false)?;
                // For "last", we need to reverse ties. Use stable sort and reverse.
                let len = sorted.len();
                if len <= n {
                    return Ok(sorted);
                }
                // Get the nth value as the cutoff
                let col = sorted.columns.get(column).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "nlargest_keep: column '{column}' not found"
                    ))
                })?;
                let cutoff = col.values()[n - 1].to_f64().unwrap_or(f64::NEG_INFINITY);
                // Count how many values are tied at the cutoff
                let tied: usize = col
                    .values()
                    .iter()
                    .filter(|v| v.to_f64().ok() == Some(cutoff))
                    .count();
                let above: usize = col
                    .values()
                    .iter()
                    .filter(|v| v.to_f64().ok().is_some_and(|f| f > cutoff))
                    .count();
                let need_tied = n - above;
                // Take the last `need_tied` of the tied values
                let mut indices = Vec::new();
                let mut tied_indices = Vec::new();
                for (i, v) in col.values().iter().enumerate() {
                    if let Ok(f) = v.to_f64() {
                        if f > cutoff {
                            indices.push(i);
                        } else if f == cutoff {
                            tied_indices.push(i);
                        }
                    }
                }
                // Take last `need_tied` ties
                let skip = tied.saturating_sub(need_tied);
                indices.extend_from_slice(&tied_indices[skip..]);
                self.take_rows(&indices)
            }
            "all" => {
                let sorted = self.sort_values(column, false)?;
                if sorted.len() <= n {
                    return Ok(sorted);
                }
                let col = sorted.columns.get(column).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "nlargest_keep: column '{column}' not found"
                    ))
                })?;
                let cutoff = col.values()[n - 1].to_f64().unwrap_or(f64::NEG_INFINITY);
                // Include all values >= cutoff
                let indices: Vec<usize> = col
                    .values()
                    .iter()
                    .enumerate()
                    .filter(|(_, v)| v.to_f64().ok().is_some_and(|f| f >= cutoff))
                    .map(|(i, _)| i)
                    .collect();
                sorted.take_rows(&indices)
            }
            _ => Err(FrameError::CompatibilityRejected(format!(
                "nlargest_keep: invalid keep='{keep}', must be 'first', 'last', or 'all'"
            ))),
        }
    }

    /// Get the bottom N rows with keep parameter.
    ///
    /// Matches `pd.DataFrame.nsmallest(n, columns, keep)`.
    pub fn nsmallest_keep(&self, n: usize, column: &str, keep: &str) -> Result<Self, FrameError> {
        match keep {
            "first" => self.nsmallest(n, column),
            "last" => {
                let sorted = self.sort_values(column, true)?;
                let len = sorted.len();
                if len <= n {
                    return Ok(sorted);
                }
                let col = sorted.columns.get(column).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "nsmallest_keep: column '{column}' not found"
                    ))
                })?;
                let cutoff = col.values()[n - 1].to_f64().unwrap_or(f64::INFINITY);
                let tied: usize = col
                    .values()
                    .iter()
                    .filter(|v| v.to_f64().ok() == Some(cutoff))
                    .count();
                let below: usize = col
                    .values()
                    .iter()
                    .filter(|v| v.to_f64().ok().is_some_and(|f| f < cutoff))
                    .count();
                let need_tied = n - below;
                let mut indices = Vec::new();
                let mut tied_indices = Vec::new();
                for (i, v) in col.values().iter().enumerate() {
                    if let Ok(f) = v.to_f64() {
                        if f < cutoff {
                            indices.push(i);
                        } else if f == cutoff {
                            tied_indices.push(i);
                        }
                    }
                }
                let skip = tied.saturating_sub(need_tied);
                indices.extend_from_slice(&tied_indices[skip..]);
                self.take_rows(&indices)
            }
            "all" => {
                let sorted = self.sort_values(column, true)?;
                if sorted.len() <= n {
                    return Ok(sorted);
                }
                let col = sorted.columns.get(column).ok_or_else(|| {
                    FrameError::CompatibilityRejected(format!(
                        "nsmallest_keep: column '{column}' not found"
                    ))
                })?;
                let cutoff = col.values()[n - 1].to_f64().unwrap_or(f64::INFINITY);
                let indices: Vec<usize> = col
                    .values()
                    .iter()
                    .enumerate()
                    .filter(|(_, v)| v.to_f64().ok().is_some_and(|f| f <= cutoff))
                    .map(|(i, _)| i)
                    .collect();
                sorted.take_rows(&indices)
            }
            _ => Err(FrameError::CompatibilityRejected(format!(
                "nsmallest_keep: invalid keep='{keep}', must be 'first', 'last', or 'all'"
            ))),
        }
    }

    fn normalize_take_indices(
        indices: &[i64],
        len: usize,
        axis: usize,
    ) -> Result<Vec<usize>, FrameError> {
        let len_i64 = i64::try_from(len).map_err(|_| {
            FrameError::CompatibilityRejected(format!(
                "take: axis {axis} is too large to index safely"
            ))
        })?;
        let mut normalized = Vec::with_capacity(indices.len());
        for &idx in indices {
            let resolved = if idx < 0 {
                len_i64.checked_add(idx).unwrap_or(-1)
            } else {
                idx
            };
            if resolved < 0 || resolved >= len_i64 {
                return Err(FrameError::CompatibilityRejected(format!(
                    "take: index {idx} out of bounds for axis {axis} with size {len}"
                )));
            }
            normalized.push(usize::try_from(resolved).unwrap_or(usize::MAX));
        }
        Ok(normalized)
    }

    /// Return the elements in the given positional indices along an axis.
    ///
    /// Matches `df.take(indices, axis=0|1)`, including negative indices from the end.
    pub fn take(&self, indices: &[i64], axis: usize) -> Result<Self, FrameError> {
        match axis {
            0 => {
                let normalized = Self::normalize_take_indices(indices, self.len(), 0)?;
                self.take_rows(&normalized)
            }
            1 => {
                let normalized = Self::normalize_take_indices(indices, self.column_order.len(), 1)?;
                self.take_columns(&normalized)
            }
            _ => Err(FrameError::CompatibilityRejected(format!(
                "take: axis must be 0 or 1 (got {axis})"
            ))),
        }
    }

    /// Helper for selecting rows by normalized non-negative positional indices.
    ///
    /// Used by `df.take(indices, axis=0)` after negative indices have been resolved.
    pub fn take_rows(&self, indices: &[usize]) -> Result<Self, FrameError> {
        let n = self.len();
        for &idx in indices {
            if idx >= n {
                return Err(FrameError::CompatibilityRejected(format!(
                    "take: index {} out of bounds for axis 0 with size {}",
                    idx, n
                )));
            }
        }
        let labels = self.index.labels();
        let new_labels: Vec<IndexLabel> = indices.iter().map(|&i| labels[i].clone()).collect();
        let row_multiindex = self
            .row_multiindex
            .as_ref()
            .map(|multiindex| Self::project_row_multiindex(multiindex, indices))
            .transpose()?;
        // Typed positional gather (see iloc_with_columns). Column-parallel
        // (br-frankenpandas-take-par): each column's gather is independent and a
        // random-permutation gather is memory-latency-bound, so spread the
        // columns across par_map_columns scope workers. Bit-identical — same
        // take_positions per column, reassembled in column_order.
        let gathered = self.par_map_columns(&self.column_order, |col_name| {
            Ok(self.columns[col_name].take_positions(indices))
        })?;
        let mut result_cols = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(gathered) {
            result_cols.insert(name.clone(), column);
        }
        // Per br-frankenpandas-9kbnz: pandas df.take(indices) preserves
        // row-axis name.
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: Index::new(new_labels).rename_index(self.index.name()),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Fill missing values using a method ('ffill' or 'bfill').
    ///
    /// Matches `pd.DataFrame.fillna(method='ffill')` / `method='bfill'`.
    pub fn fillna_method(&self, method: &str) -> Result<Self, FrameError> {
        match method {
            "ffill" | "pad" => self.ffill(None),
            "bfill" | "backfill" => self.bfill(None),
            _ => Err(FrameError::CompatibilityRejected(format!(
                "fillna: unknown method '{method}', use 'ffill' or 'bfill'"
            ))),
        }
    }

    /// Reindex the DataFrame to a new set of index labels.
    ///
    /// Missing rows are filled with NaN.
    pub fn reindex(&self, new_labels: Vec<IndexLabel>) -> Result<Self, FrameError> {
        if self.index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "reindex cannot handle duplicate index labels".to_owned(),
            ));
        }
        // Build old label -> first row index ONCE with FxHash (br-frankenpandas-uza04.110):
        // the prior code re-resolved every new label inside the per-column loop
        // (cols × new_len SipHash lookups) AND called `col.values()` per column,
        // materializing a `Vec<Scalar>` of the whole source each time — for a
        // 100k×10 reindex that was ~58x slower than pandas. Resolve each new
        // label to `Some(row)`/`None` ONCE, shared across all columns.
        let new_len = new_labels.len();
        // Per br-frankenpandas-1lo93: pandas preserves the index name when
        // reindexing with a flat label list. Built here (not just at the end) so
        // the fallback resolver can borrow it for `get_indexer`, which needs the
        // target's typed backing + sort_order.
        let new_index = Index::new(new_labels).rename_index(self.index.name());
        let positions: Vec<Option<usize>> =
            if let Some((start, len)) = self.index.int64_unit_range_labels() {
                // Unit-range Int64 index (the pandas RangeIndex default): a label
                // Int64(v) maps to position v-start arithmetically — O(1) per label,
                // NO hashmap build/probe (br-frankenpandas-uza04.112). The unit range
                // is strictly unique, so this matches the `or_insert` first-seen map
                // exactly; a non-Int64 / out-of-range label is absent (None), same as
                // a hashmap miss against an all-Int64 index.
                new_index
                    .labels()
                    .iter()
                    .map(|label| match label {
                        IndexLabel::Int64(v) => {
                            let off = v.wrapping_sub(start);
                            if off >= 0 && (off as u64) < len as u64 {
                                Some(off as usize)
                            } else {
                                None
                            }
                        }
                        _ => None,
                    })
                    .collect()
            } else {
                // Non-unit-range fallback: route through `get_indexer` instead of
                // rebuilding a pointer-key `FxHashMap<&IndexLabel, usize>` every
                // call (2 cache misses per probe chasing into the 24-byte enum —
                // the fp-index pointer-key pathology). Duplicates were rejected
                // above ⇒ `self.index` is unique ⇒ get_indexer reaches the typed,
                // identity-cached resolvers (unique_datetime64_positions /
                // unsorted_unique_int64_positions / unique_utf8_positions —
                // FxHashMap<i64>/<&str>, 8-byte/borrowed keys, cached by source
                // label_identity) or a hash-free binary-search when self is sorted.
                // Bit-identical: unique self ⇒ first-occurrence == only-occurrence
                // == the old `or_insert`/`get`; a Bool/Float64/mixed self falls
                // through get_indexer to the SAME pointer-key map (no regression).
                self.index.get_indexer(&new_index)
            };

        // Gather each output column from the shared `positions`. The per-column
        // gather is the reindex hot phase (10 cols × new_len); columns are
        // INDEPENDENT, so fan them across workers (br-frankenpandas-uza04.112).
        // Typed all-valid Float64 gather: pull present values straight from the
        // contiguous `&[f64]` and emit a typed nullable column, skipping the
        // per-column `.values()` Scalar materialization + `Column::new` re-scan.
        // Bit-identical: a present slot stores `data[idx]` with the validity bit
        // SET (⇒ `Float64(data[idx])` == the old `values()[idx].clone()`); a
        // missing slot stores 0.0 (NOT NaN) with the bit CLEARED (⇒
        // `Null(NullKind::NaN)` == the old fill); dtype stays Float64.
        let positions_ref: &[Option<usize>] = &positions;
        let build_col = |col: &Column| -> Result<Column, FrameError> {
            if let Some(data) = col.as_f64_slice() {
                let mut out = Vec::with_capacity(new_len);
                let mut words = vec![0_u64; new_len.div_ceil(64)];
                for (oi, p) in positions_ref.iter().enumerate() {
                    match p {
                        Some(idx) => {
                            words[oi / 64] |= 1_u64 << (oi % 64);
                            out.push(data[*idx]);
                        }
                        None => out.push(0.0),
                    }
                }
                Ok(Column::from_f64_values_with_validity(
                    out,
                    fp_columnar::ValidityMask::from_words(words, new_len),
                ))
            } else {
                // A row reindex INVENTS is NaN (already the case here), and an
                // all-valid int64 column widens to float64 to hold it — numpy
                // int64 has no NaN. Measured on pandas 2.2.3:
                //   pd.Series([1,2]).reindex([0,1,2]) -> [1.0, 2.0, nan] float64
                //   pd.DataFrame({'a':[1,2]}).reindex(columns=['a','z'])
                //     -> a int64 (no gap), z all-NaN float64
                // A column that ALREADY carried a missing value is nullable, can
                // hold the gap, and keeps its dtype with a Null gap — the same
                // condition as the concat/constructor sites.
                // (br-frankenpandas-nywa8)
                reindex_column_with_invented_gaps(col, positions_ref)
            }
        };

        let col_refs: Vec<&Column> = self
            .column_order
            .iter()
            .map(|name| &self.columns[name])
            .collect();
        let ncols = col_refs.len();
        let worker_count = fp_columnar::cached_available_parallelism()
            .min(64)
            .min(ncols.max(1));
        let big_enough = (new_len as u128) * (ncols as u128) >= (1u128 << 18);
        let built: Vec<Column> = if worker_count >= 2 && big_enough && ncols >= 2 {
            let next = std::sync::atomic::AtomicUsize::new(0);
            let col_refs = &col_refs;
            let build_ref = &build_col;
            let mut slots: Vec<Option<Result<Column, FrameError>>> =
                (0..ncols).map(|_| None).collect();
            let parts = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(worker_count);
                for _ in 0..worker_count {
                    let next = &next;
                    handles.push(scope.spawn(move || {
                        let mut out: Vec<(usize, Result<Column, FrameError>)> = Vec::new();
                        loop {
                            let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            if i >= col_refs.len() {
                                break;
                            }
                            out.push((i, build_ref(col_refs[i])));
                        }
                        out
                    }));
                }
                handles
                    .into_iter()
                    .map(|h| h.join().expect("reindex worker panicked"))
                    .collect::<Vec<_>>()
            });
            for part in parts {
                for (i, r) in part {
                    slots[i] = Some(r);
                }
            }
            slots
                .into_iter()
                .map(|s| s.expect("every column built"))
                .collect::<Result<Vec<_>, _>>()?
        } else {
            col_refs
                .iter()
                .map(|c| build_col(c))
                .collect::<Result<Vec<_>, _>>()?
        };

        let mut result_cols = BTreeMap::new();
        for (name, col) in self.column_order.iter().zip(built) {
            result_cols.insert(name.clone(), col);
        }

        let index = new_index;
        Self::validate_duplicate_label_policy(
            self.allows_duplicate_labels,
            &index,
            None,
            "reindex",
        )?;
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index,
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Reindex this DataFrame to match another DataFrame's row index.
    ///
    /// Matches `pd.DataFrame.reindex_like(other)` for row-index alignment.
    pub fn reindex_like(&self, other: &Self) -> Result<Self, FrameError> {
        // Per br-frankenpandas-yu31z: pandas reindex_like adopts OTHER's
        // index — labels AND name. The inner reindex(labels) call preserves
        // self.index.name, so apply rename_index(other.index.name()) after.
        let result = self.reindex(other.index.labels().to_vec())?;
        let new_index = result.index.clone().rename_index(other.index.name());
        Ok(Self {
            columns: result.columns,
            column_order: result.column_order,
            index: new_index,
            column_multiindex: result.column_multiindex,
            row_multiindex: result.row_multiindex,
            allows_duplicate_labels: result.allows_duplicate_labels,
        })
    }

    /// Conform DataFrame to new index or columns.
    ///
    /// Matches `pd.DataFrame.reindex(labels, axis=...)`.
    pub fn reindex_axis(&self, labels: Vec<IndexLabel>, axis: usize) -> Result<Self, FrameError> {
        match axis {
            0 => self.reindex(labels),
            1 => {
                let mut result_cols = BTreeMap::new();
                let mut col_order = Vec::new();
                for label in &labels {
                    let col_name = label.to_string();
                    if let Some(col) = self.columns.get(&col_name) {
                        result_cols.insert(col_name.clone(), col.clone());
                    } else {
                        let nans = vec![Scalar::Null(NullKind::NaN); self.len()];
                        result_cols.insert(col_name.clone(), Column::from_values(nans)?);
                    }
                    col_order.push(col_name);
                }
                // Per br-frankenpandas-hn794: reindex_axis(axis=1) rebuilds
                // only the column set — the rows (and row_multiindex) are
                // untouched and should pass through. column_multiindex is
                // dropped because the column set is entirely rebuilt with
                // new labels, leaving any prior column MultiIndex
                // size-mismatched.
                Ok(Self {
                    columns: result_cols.into(),
                    column_order: col_order.into(),
                    index: self.index.clone(),
                    column_multiindex: None,
                    row_multiindex: self.row_multiindex.clone(),
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
            _ => Err(FrameError::CompatibilityRejected(format!(
                "reindex: axis must be 0 or 1 (got {axis})"
            ))),
        }
    }

    /// Reindex with a static fill_value for missing labels.
    ///
    /// Matches `df.reindex(new_labels, fill_value=X)`. Labels not found
    /// in the current index are filled with `fill_value` instead of NaN.
    pub fn reindex_fill(
        &self,
        new_labels: Vec<IndexLabel>,
        fill_value: Scalar,
    ) -> Result<Self, FrameError> {
        if self.index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "reindex cannot handle duplicate index labels".to_owned(),
            ));
        }
        let mut old_lookup: std::collections::HashMap<&IndexLabel, usize> =
            std::collections::HashMap::new();
        for (i, label) in self.index.labels().iter().enumerate() {
            old_lookup.entry(label).or_insert(i);
        }
        let new_len = new_labels.len();
        let mut result_cols = BTreeMap::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let mut new_vals = Vec::with_capacity(new_len);
            for label in &new_labels {
                if let Some(&idx) = old_lookup.get(label) {
                    new_vals.push(col.values()[idx].clone());
                } else {
                    new_vals.push(fill_value.clone());
                }
            }
            result_cols.insert(col_name.clone(), Column::from_values(new_vals)?);
        }
        // Per br-frankenpandas-1lo93: pandas preserves the index name when
        // reindexing with a flat label list.
        let index = Index::new(new_labels).rename_index(self.index.name());
        Self::validate_duplicate_label_policy(
            self.allows_duplicate_labels,
            &index,
            None,
            "reindex",
        )?;
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index,
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Reindex to new labels with a fill method for introduced NaN.
    ///
    /// Matches `df.reindex(new_labels, method='ffill'|'bfill')`.
    ///
    /// Single-pass, label-presence driven: only labels ABSENT from the source
    /// index are filled from the nearest source label in the fill direction;
    /// labels PRESENT in the source keep their own values, INCLUDING source
    /// NaNs. A two-pass `reindex(...).ffill()` would instead fill every NaN
    /// slot, overwriting original source NaNs that pandas leaves untouched.
    pub fn reindex_with_method(
        &self,
        new_labels: Vec<IndexLabel>,
        method: &str,
    ) -> Result<Self, FrameError> {
        if self.index.has_duplicates() {
            return Err(FrameError::CompatibilityRejected(
                "reindex cannot handle duplicate index labels".to_owned(),
            ));
        }
        // br-frankenpandas-reindex-nearest: 'nearest' is pandas' third method and
        // was rejected here as unsupported. It is not a direction, so it cannot be
        // folded into `forward` — it resolves each absent label to the CLOSEST
        // source label instead of the closest one in a direction.
        let forward = match method {
            "ffill" | "pad" => Some(true),
            "bfill" | "backfill" => Some(false),
            "nearest" => None,
            other => {
                return Err(FrameError::CompatibilityRejected(format!(
                    "unsupported reindex method: '{other}'"
                )));
            }
        };
        // Preserve the index name on a flat label list (mirrors `reindex`).
        let new_index = Index::new(new_labels).rename_index(self.index.name());
        // Resolve each new label to its source row position (`None` = absent),
        // using the same unit-range fast path / fallback resolver as `reindex`.
        let positions: Vec<Option<usize>> =
            if let Some((start, len)) = self.index.int64_unit_range_labels() {
                new_index
                    .labels()
                    .iter()
                    .map(|label| match label {
                        IndexLabel::Int64(v) => {
                            let off = v.wrapping_sub(start);
                            if off >= 0 && (off as u64) < len as u64 {
                                Some(off as usize)
                            } else {
                                None
                            }
                        }
                        _ => None,
                    })
                    .collect()
            } else {
                self.index.get_indexer(&new_index)
            };
        // Absent labels inherit the nearest present source position in the fill
        // direction; present labels (incl. source NaNs) keep their own position.
        let filled = match forward {
            Some(direction) => carry_reindex_positions(&positions, direction),
            None => nearest_reindex_positions(self.index.labels(), new_index.labels(), &positions)?,
        };
        // Gather each column from the carried positions. Remaining `None` slots
        // (leading gap for ffill / trailing gap for bfill) become the column's
        // dtype-appropriate missing sentinel — `Null(NaN)` for Float64, but
        // `Null(Null)` for Int64/Utf8/Bool and `NaT` for temporal — exactly as
        // plain `reindex` and the `Series` variant do (both use
        // `reindex_by_positions`, which fills `None` via `missing_for_dtype`).
        // Hardcoding `Null(NaN)` here diverged from those paths on non-Float64
        // columns.
        let mut result_cols = BTreeMap::new();
        for name in &self.column_order {
            let col = self.columns[name].reindex_by_positions(&filled)?;
            result_cols.insert(name.clone(), col);
        }
        Self::validate_duplicate_label_policy(
            self.allows_duplicate_labels,
            &new_index,
            None,
            "reindex",
        )?;
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: new_index,
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Reindex columns: reorder, filter, or add columns.
    ///
    /// Matches `df.reindex(columns=[...])`. Columns present in the new list
    /// but missing from the DataFrame are filled with NaN. Columns not in the
    /// new list are dropped. Order follows the provided list.
    pub fn reindex_columns(&self, new_columns: &[&str]) -> Result<Self, FrameError> {
        let n = self.len();
        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::new();

        for &col_name in new_columns {
            let name = col_name.to_string();
            if let Some(col) = self.columns.get(&name) {
                result_cols.insert(name.clone(), col.clone());
            } else {
                // Add a NaN-filled column
                let nans = vec![Scalar::Null(NullKind::NaN); n];
                result_cols.insert(name.clone(), Column::new(DType::Float64, nans)?);
            }
            col_order.push(name);
        }

        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index: self.index.clone(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Update values using non-null values from another DataFrame.
    ///
    /// Analogous to `pandas.DataFrame.update(other)`. Only updates values
    /// at matching index labels and column names where `other` has non-null
    /// values. Retains self's index and columns (no new labels/columns
    /// added from other).
    pub fn update(&self, other: &Self) -> Result<Self, FrameError> {
        // Typed fast path (identical unique index, every self column Float64 and
        // every shared column Float64 on `other`): out[i] = other-present-and-
        // non-NaN ? other : self, straight from the f64+validity slices — skipping
        // the O(n log n) pointer-key BTreeMap + both .values() Scalar Vecs + the
        // per-cell clone (df.update was 0.16x pandas). Bit-identical to the general
        // path: a slot is overwritten iff `!other_val.is_missing()` (== other valid
        // and not NaN); a column absent from `other` keeps self unchanged.
        if self.index == other.index
            && self.index.is_unique()
            && self.row_multiindex.is_none()
            && self.column_order.iter().all(|name| {
                self.columns[name].as_f64_slice_with_validity().is_some()
                    && self.columns[name].len() == self.index.len()
                    && other
                        .columns
                        .get(name)
                        .is_none_or(|c| c.as_f64_slice_with_validity().is_some())
            })
        {
            let n = self.index.len();
            let computed = self.par_map_columns(&self.column_order, |name| {
                let (sd, sv) = self.columns[name].as_f64_slice_with_validity().unwrap();
                match other
                    .columns
                    .get(name)
                    .and_then(|c| c.as_f64_slice_with_validity())
                {
                    Some((od, ov)) if od.len() == n => {
                        let mut out = vec![0.0_f64; n];
                        let mut valid = fp_columnar::ValidityMask::all_valid(n);
                        for i in 0..n {
                            if ov.get(i) && !od[i].is_nan() {
                                out[i] = od[i];
                            } else {
                                out[i] = sd[i];
                                if !sv.get(i) {
                                    valid.set(i, false);
                                }
                            }
                        }
                        Ok(Column::from_f64_values_with_validity(out, valid))
                    }
                    _ => Ok(self.columns[name].clone()),
                }
            })?;
            let mut result_cols = BTreeMap::new();
            for (name, column) in self.column_order.iter().zip(computed) {
                result_cols.insert(name.clone(), column);
            }
            return Ok(Self {
                columns: result_cols.into(),
                column_order: self.column_order.clone(),
                index: self.index.clone(),
                column_multiindex: self.column_multiindex.clone(),
                row_multiindex: self.row_multiindex.clone(),
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        let other_idx_map: BTreeMap<&IndexLabel, usize> = other
            .index
            .labels()
            .iter()
            .enumerate()
            .map(|(i, l)| (l, i))
            .collect();

        let mut result_cols = BTreeMap::new();

        for col_name in &self.column_order {
            let self_col = &self.columns[col_name];
            let new_vals: Vec<Scalar> = if let Some(other_col) = other.columns.get(col_name) {
                self.index
                    .labels()
                    .iter()
                    .enumerate()
                    .map(|(i, label)| {
                        if let Some(&other_i) = other_idx_map.get(label) {
                            let other_val = &other_col.values()[other_i];
                            if !other_val.is_missing() {
                                return other_val.clone();
                            }
                        }
                        self_col.values()[i].clone()
                    })
                    .collect()
            } else {
                self_col.values().to_vec()
            };
            result_cols.insert(col_name.clone(), Column::from_values(new_vals)?);
        }

        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Combine two DataFrames, preferring non-null values from self.
    ///
    /// Analogous to `pandas.DataFrame.combine_first(other)`. Uses union
    /// of indices and columns. For overlapping positions, uses self's value
    /// if non-null, else other's value.
    pub fn combine_first(&self, other: &Self) -> Result<Self, FrameError> {
        // Build the union of columns. pandas combine_first sorts the column
        // union (e.g. [b, a] -> [a, b]). Verified vs live pandas 2.2.3.
        let mut col_order = Vec::new();
        let mut col_set = std::collections::HashSet::new();
        for name in &self.column_order {
            if col_set.insert(name.clone()) {
                col_order.push(name.clone());
            }
        }
        for name in &other.column_order {
            if col_set.insert(name.clone()) {
                col_order.push(name.clone());
            }
        }
        col_order.sort();

        // Positional fast path is valid only when the two indexes are identical
        // (so union order == self order and label i maps to row i on both sides)
        // and unique (the per-cell `self_idx.get` / `other_idx.get` BTreeMap
        // lookups resolve to position i, matching positional iteration).
        let positional = self.index == other.index && self.index.is_unique();
        // When every output column is two-sided Float64, all of them take the
        // typed positional fast path below, so the O(n log n) per-cell label
        // maps are never consulted — skip building them (br-frankenpandas-apyf4).
        let all_typed = positional
            && col_order.iter().all(|name| {
                matches!((self.columns.get(name), other.columns.get(name)),
                    (Some(sc), Some(oc))
                        if matches!(sc.dtype(), DType::Float64)
                            && matches!(oc.dtype(), DType::Float64)
                            && sc.as_f64_slice_with_validity().is_some()
                            && oc.as_f64_slice_with_validity().is_some())
            });

        // Typed UNALIGNED fast path (br-frankenpandas-combinefirst-unaligned):
        // indexes DIFFER (so the positional path bails) but both are unique and
        // every column is two-sided Float64 (same column set). Reindex each column
        // to the sorted union via the TYPED reindex_by_positions, then apply the
        // SAME typed first-non-null coalesce the positional arm uses — bypassing
        // the per-cell BTreeMap label lookups + Scalar select of the general path
        // (combine_first unaligned was 0.25x pandas). Bit-identical to the general
        // path: a union row keeps self's value iff self is present-and-valid there
        // (a reindexed absent/null slot has a cleared validity bit), else other's;
        // result valid iff self-valid || other-valid, with the same
        // LazyNullableFloat64 missing convention.
        if !positional
            && self.index.is_unique()
            && other.index.is_unique()
            && self.row_multiindex.is_none()
            && other.row_multiindex.is_none()
            && col_order.len() == self.column_order.len()
            && col_order.iter().all(|name| {
                matches!((self.columns.get(name), other.columns.get(name)),
                    (Some(sc), Some(oc))
                        if matches!(sc.dtype(), DType::Float64)
                            && matches!(oc.dtype(), DType::Float64)
                            && sc.as_f64_slice_with_validity().is_some()
                            && oc.as_f64_slice_with_validity().is_some())
            })
        {
            let AlignmentPlan {
                union_index,
                left_positions,
                right_positions,
            } = align_union_sorted_plan(&self.index, &other.index);
            let computed = self.par_map_columns(&col_order, |name| {
                // Gather TYPED straight from the source f64+validity slices via the
                // union position vectors (reindex_by_positions would go Scalar for a
                // nullable source). A union row takes self's value iff its self
                // position is present-and-valid, else other's (present/missing) —
                // same first-non-null coalesce as the positional arm.
                let (sx, sv) = self.columns[name]
                    .as_f64_slice_with_validity()
                    .expect("gated to two-sided Float64 with f64+validity");
                let (ox, ov) = other.columns[name]
                    .as_f64_slice_with_validity()
                    .expect("gated to two-sided Float64 with f64+validity");
                let len = left_positions.len();
                let mut out = vec![0.0_f64; len];
                let mut validity = fp_columnar::ValidityMask::all_valid(len);
                for i in 0..len {
                    let self_present = match left_positions[i] {
                        Some(p) if sv.get(p) => {
                            out[i] = sx[p];
                            true
                        }
                        _ => false,
                    };
                    if !self_present {
                        match right_positions[i] {
                            Some(p) => {
                                out[i] = ox[p];
                                if !ov.get(p) {
                                    validity.set(i, false);
                                }
                            }
                            None => validity.set(i, false),
                        }
                    }
                }
                Ok(Column::from_f64_values_with_validity(out, validity))
            })?;
            let mut result_cols = BTreeMap::new();
            for (name, column) in col_order.iter().zip(computed) {
                result_cols.insert(name.clone(), column);
            }
            return Ok(Self {
                columns: result_cols.into(),
                column_order: col_order.into(),
                index: union_index,
                column_multiindex: self.column_multiindex.clone(),
                row_multiindex: None,
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        // Build the union of index labels. pandas combine_first returns the
        // SORTED union when the indexes differ, but keeps the original order
        // when they are identical (Index.union). Verified vs live pandas 2.2.3.
        //
        // br-frankenpandas-combine-first-union: when the indexes are identical
        // AND unique (`positional`), the HashSet union collapses to exactly
        // `self.index.labels()` (every self label is distinct so the first loop
        // pushes them all in order; the second loop inserts nothing; no sort
        // since the indexes are equal) and the output index is reused directly
        // from `self.index` below — so skip the ~2n label clones + SipHash
        // inserts AND the `Index::new` rehash entirely. When all columns are
        // additionally two-sided Float64 (`all_typed`) the per-cell loop that
        // consumes `union_labels` never runs, so we need no label vector at all.
        let union_labels: Vec<IndexLabel> = if positional {
            if all_typed {
                Vec::new()
            } else {
                self.index.labels().to_vec()
            }
        } else {
            let mut seen = std::collections::HashSet::new();
            let mut union_labels = Vec::new();
            for label in self.index.labels() {
                if seen.insert(label.clone()) {
                    union_labels.push(label.clone());
                }
            }
            for label in other.index.labels() {
                if seen.insert(label.clone()) {
                    union_labels.push(label.clone());
                }
            }
            if self.index != other.index {
                union_labels.sort();
            }
            union_labels
        };

        // Build lookup maps for self and other (only when some column needs the
        // general per-cell select).
        let self_idx: BTreeMap<&IndexLabel, usize> = if all_typed {
            BTreeMap::new()
        } else {
            self.index
                .labels()
                .iter()
                .enumerate()
                .map(|(i, l)| (l, i))
                .collect()
        };
        let other_idx: BTreeMap<&IndexLabel, usize> = if all_typed {
            BTreeMap::new()
        } else {
            other
                .index
                .labels()
                .iter()
                .enumerate()
                .map(|(i, l)| (l, i))
                .collect()
        };

        // Column-parallel (br-frankenpandas-combinefirst-par): each output
        // column is selected independently, so spread the columns across
        // par_map_columns scope workers. Bit-identical — identical per-column
        // typed/Scalar select arms, reassembled in col_order.
        let computed = self.par_map_columns(&col_order, |col_name| {
            let self_col = self.columns.get(col_name);
            let other_col = other.columns.get(col_name);

            // Typed Float64 fast path (br-frankenpandas-apyf4): identical+unique
            // index and both sides Float64 — select positionally from raw f64 +
            // validity into a typed output, skipping the per-cell label lookups,
            // Scalar clones, and Column::new revalidation. Bit-identical to the
            // general select: a row keeps self's value when self is valid, else
            // other's value (present or missing) — so the result datum is
            // `self.valid ? self_data : other_data` and the result is valid iff
            // `self.valid || other.valid`. A cleared bit with a non-NaN datum
            // materialises Null(NaN) and with a NaN datum materialises
            // Float64(NaN), exactly the LazyNullableFloat64 / Column::from_values
            // convention the general path produces.
            if positional
                && let (Some(sc), Some(oc)) = (self_col, other_col)
                && matches!(sc.dtype(), DType::Float64)
                && matches!(oc.dtype(), DType::Float64)
                && let (Some((sx, sv)), Some((ox, ov))) = (
                    sc.as_f64_slice_with_validity(),
                    oc.as_f64_slice_with_validity(),
                )
                && sx.len() == ox.len()
            {
                let len = sx.len();
                let mut out = vec![0.0_f64; len];
                let mut validity = fp_columnar::ValidityMask::all_valid(len);
                for i in 0..len {
                    if sv.get(i) {
                        out[i] = sx[i];
                    } else {
                        out[i] = ox[i];
                        if !ov.get(i) {
                            validity.set(i, false);
                        }
                    }
                }
                return Ok(Column::from_f64_values_with_validity(out, validity));
            }

            // Compute common dtype upfront for associativity (br-frankenpandas-1uw2u):
            // The result dtype must be the common dtype of BOTH source columns,
            // not inferred from which values happen to be selected. This ensures
            // (A.combine_first(B)).combine_first(C) == A.combine_first(B.combine_first(C))
            let target_dtype = match (self_col, other_col) {
                (Some(sc), Some(oc)) => {
                    fp_types::common_dtype(sc.dtype(), oc.dtype()).unwrap_or(DType::Float64)
                }
                (Some(sc), None) => sc.dtype(),
                (None, Some(oc)) => oc.dtype(),
                (None, None) => DType::Float64,
            };

            let vals: Vec<Scalar> = union_labels
                .iter()
                .map(|label| {
                    // Prefer self value if non-null
                    if let Some(sc) = self_col
                        && let Some(&i) = self_idx.get(label)
                    {
                        let v = &sc.values()[i];
                        if !v.is_missing() {
                            return v.clone();
                        }
                    }
                    // Fall back to other
                    if let Some(oc) = other_col
                        && let Some(&i) = other_idx.get(label)
                    {
                        return oc.values()[i].clone();
                    }
                    Scalar::Null(NullKind::NaN)
                })
                .collect();

            // Create column with explicit target dtype to ensure associativity
            Ok(Column::new(target_dtype, vals)?)
        })?;
        let mut result_cols = BTreeMap::new();
        for (name, column) in col_order.iter().zip(computed) {
            result_cols.insert(name.clone(), column);
        }

        // Per br-frankenpandas-25zlp: pandas combine_first preserves shared
        // index name (preserved when both operands agree, None otherwise).
        let shared_name = if self.index.name() == other.index.name() {
            self.index.name()
        } else {
            None
        };
        // Identical+unique index: reuse self.index (cheap clone of the existing
        // backing + maps) instead of rebuilding it from union_labels via
        // Index::new (which re-hashes all n labels). Observably identical — the
        // union order equals self's label order here, and rename_index applies
        // the same shared-name resolution either way.
        let index = if positional {
            self.index.clone().rename_index(shared_name)
        } else {
            Index::new(union_labels).rename_index(shared_name)
        };
        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index,
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Combine two DataFrames element-wise using a binary function.
    ///
    /// Matches `df.combine(other, func)`. Aligns on both index and columns
    /// (union), filling missing positions with NaN before applying `func`.
    pub fn combine_elementwise<F>(&self, other: &Self, func: F) -> Result<Self, FrameError>
    where
        F: Fn(&Scalar, &Scalar) -> Scalar,
    {
        // pandas df.combine returns the SORTED union of the indexes (and of the
        // columns). Verified vs live pandas 2.2.3.
        let plan = align_union_sorted_plan(&self.index, &other.index);
        validate_alignment_plan(&plan)?;

        // Union of columns, sorted (pandas combine sorts the column union).
        let mut col_order = self.column_order.clone();
        for name in &other.column_order {
            if !self.columns.contains_key(name) {
                col_order.push(name.clone());
            }
        }
        col_order.sort();

        let null = Scalar::Null(NullKind::NaN);
        let mut result_cols = BTreeMap::new();
        for col_name in &col_order {
            let self_col = self.columns.get(col_name);
            let other_col = other.columns.get(col_name);
            let vals: Vec<Scalar> = plan
                .left_positions
                .iter()
                .zip(plan.right_positions.iter())
                .map(|(lp, rp)| {
                    let left = self_col
                        .and_then(|c| lp.map(|i| &c.values()[i]))
                        .unwrap_or(&null);
                    let right = other_col
                        .and_then(|c| rp.map(|i| &c.values()[i]))
                        .unwrap_or(&null);
                    func(left, right)
                })
                .collect();
            result_cols.insert(col_name.clone(), Column::from_values(vals)?);
        }

        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order,
            index: plan.union_index,
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Combine the DataFrame with another DataFrame using a column-wise function.
    ///
    /// Matches `pd.DataFrame.combine(other, func, fill_value=None, overwrite=True)`.
    pub fn combine<F>(
        &self,
        other: &Self,
        func: F,
        fill_value: Option<&Scalar>,
        overwrite: bool,
    ) -> Result<Self, FrameError>
    where
        F: Fn(&Series, &Series) -> Result<Series, FrameError>,
    {
        // Align columns (union)
        let mut seen_cols = std::collections::HashSet::new();
        let mut union_cols = Vec::new();
        for c in &self.column_order {
            if seen_cols.insert(c.clone()) {
                union_cols.push(c.clone());
            }
        }
        for c in &other.column_order {
            if seen_cols.insert(c.clone()) {
                union_cols.push(c.clone());
            }
        }

        // Align indexes (union)
        let mut seen_idx = std::collections::HashSet::new();
        let mut union_labels = Vec::new();
        for l in self.index.labels() {
            if seen_idx.insert(l.clone()) {
                union_labels.push(l.clone());
            }
        }
        for l in other.index.labels() {
            if seen_idx.insert(l.clone()) {
                union_labels.push(l.clone());
            }
        }
        // Per br-frankenpandas-hnawi: pandas DataFrame.combine preserves
        // shared index name on the union axis.
        let shared_name = if self.index.name() == other.index.name() {
            self.index.name()
        } else {
            None
        };
        let union_index = Index::new(union_labels).rename_index(shared_name);

        let mut result_cols = BTreeMap::new();
        for name in &union_cols {
            let left_s = if let Some(col) = self.columns.get(name) {
                Series::new(name, self.index.clone(), col.clone())?
                    .reindex(union_index.labels().to_vec())?
            } else {
                let vals = vec![
                    fill_value.cloned().unwrap_or(Scalar::Null(NullKind::NaN));
                    union_index.len()
                ];
                Series::from_values(name, union_index.labels().to_vec(), vals)?
            };

            let right_s = if let Some(col) = other.columns.get(name) {
                Series::new(name, other.index.clone(), col.clone())?
                    .reindex(union_index.labels().to_vec())?
            } else {
                let vals = vec![
                    fill_value.cloned().unwrap_or(Scalar::Null(NullKind::NaN));
                    union_index.len()
                ];
                Series::from_values(name, union_index.labels().to_vec(), vals)?
            };

            let mut combined = func(&left_s, &right_s)?;
            if !overwrite {
                combined = left_s.combine_first(&combined)?;
            }
            result_cols.insert(name.clone(), combined.column().clone());
        }

        Ok(Self {
            index: union_index,
            columns: result_cols.into(),
            column_order: union_cols.into(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Create a rolling window view over all numeric columns.
    ///
    /// Matches `df.rolling(window)` semantics.
    pub fn rolling(&self, window: usize, min_periods: Option<usize>) -> DataFrameRolling<'_> {
        DataFrameRolling {
            df: self,
            window,
            min_periods: min_periods.unwrap_or(window),
        }
    }

    /// Create an expanding window view over all numeric columns.
    ///
    /// Matches `df.expanding(min_periods)` semantics.
    pub fn expanding(&self, min_periods: Option<usize>) -> DataFrameExpanding<'_> {
        DataFrameExpanding {
            df: self,
            min_periods: min_periods.unwrap_or(1),
        }
    }

    /// Create an exponentially weighted moving window view over all numeric columns.
    ///
    /// Matches `df.ewm(span=...)` semantics.
    pub fn ewm(&self, span: Option<f64>, alpha: Option<f64>) -> DataFrameEwm<'_> {
        DataFrameEwm {
            df: self,
            span,
            alpha,
        }
    }

    /// Create a time-based resampler view for the DataFrame.
    ///
    /// Matches `df.resample(freq)`. The DataFrame must have Utf8 datetime-like
    /// index labels. Applies aggregation to each numeric column per time bucket.
    pub fn resample(&self, freq: &str) -> DataFrameResample<'_> {
        DataFrameResample {
            df: self,
            freq: freq.to_string(),
        }
    }

    /// Conform the row index to a datetime frequency.
    ///
    /// Matches the row-axis default of `pd.DataFrame.asfreq(freq)` for flat,
    /// strictly increasing datetime-like indexes. Missing rows introduced by
    /// the new frequency are filled with NaN.
    pub fn asfreq(&self, freq: &str) -> Result<Self, FrameError> {
        self.asfreq_with_options(freq, None, None)
    }

    /// Conform the row index to a datetime frequency with optional fill.
    ///
    /// `method` accepts pandas spellings `"ffill"`/`"pad"` and
    /// `"bfill"`/`"backfill"` for labels introduced by the frequency grid.
    /// `fill_value`, when present, fills any remaining missing values after
    /// reindexing/method fill.
    pub fn asfreq_with_options(
        &self,
        freq: &str,
        method: Option<&str>,
        fill_value: Option<Scalar>,
    ) -> Result<Self, FrameError> {
        if self.row_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "asfreq currently supports flat row indexes only".to_owned(),
            ));
        }

        let labels = asfreq_target_labels(&self.index, freq)?;
        let mut result = match method {
            Some(method) => self.reindex_with_method(labels, method)?,
            None => self.reindex(labels)?,
        };
        if let Some(fill_value) = fill_value {
            // ⚠️ The fill happens AFTER reindex, which invents NaN gaps and
            // widens an all-valid int64 column to float64 (nywa8). pandas does
            // NOT widen when a fill_value or method is supplied, because no NaN
            // ever lands. Measured on 2.2.3 over a gapped daily index:
            //   df.asfreq('D', fill_value=0) -> [10, 0, 30]    int64
            //   df.asfreq('D', method='ffill')-> [10, 10, 30]  int64
            //   df.asfreq('D')                -> [10.0, nan, 30.0] float64
            // So restore the source dtype for any column the fill leaves with no
            // missing values. Only columns whose dtype the reindex widened are
            // touched, and only when the fill actually removed every gap.
            result = result.fillna(&fill_value)?;
            result = result.restore_dtypes_after_gapless_fill(self)?;
        }
        result.index = result.index.set_names(self.index.name());
        Ok(result)
    }

    /// Restore each column's dtype from `source` where a fill has left the column
    /// with no missing values.
    ///
    /// Undoes the int64 -> float64 widening that `reindex` applies when it
    /// invents a NaN gap, for the case where the caller immediately fills every
    /// gap and pandas therefore never widens at all. Only columns that are now
    /// gapless AND whose source dtype differs are cast, so a column that keeps a
    /// genuine missing value stays widened. (br-frankenpandas-nywa8)
    fn restore_dtypes_after_gapless_fill(&self, source: &Self) -> Result<Self, FrameError> {
        let mut out = self.clone();
        for name in &self.column_order {
            let Some(original) = source.columns.get(name) else {
                continue;
            };
            let current = &self.columns[name];
            if current.dtype() == original.dtype() {
                continue;
            }
            if current.values().iter().any(fp_types::Scalar::is_missing) {
                continue;
            }
            let restored = current.astype(original.dtype())?;
            out.columns.insert(name.clone(), restored);
        }
        Ok(out)
    }

    /// Select rows where the time component of the index is between two times.
    ///
    /// Matches `df.between_time(start_time, end_time)`.
    /// Index labels should be datetime-like strings with time component (HH:MM or HH:MM:SS).
    pub fn between_time(&self, start: &str, end: &str) -> Result<Self, FrameError> {
        // Per br-frankenpandas-g3jqn: pandas raises TypeError on non-DatetimeIndex.
        require_datetime_index(self.index.labels(), "between_time")?;
        let labels = self.index.labels();
        let mut keep = Vec::new();

        for (i, label) in labels.iter().enumerate() {
            if let IndexLabel::Utf8(s) = label {
                let time_part = Self::extract_time(s);
                if let Some(ref t) = time_part
                    && t.as_str() >= start
                    && t.as_str() <= end
                {
                    keep.push(i);
                }
            }
        }

        let mut selected = self.take_rows_by_positions(&keep)?;
        selected.index = canonicalize_datetime_index_labels(&selected.index);
        Ok(selected)
    }

    /// Select rows where the time component exactly matches the given time.
    ///
    /// Matches `df.at_time(time)`.
    pub fn at_time(&self, time: &str) -> Result<Self, FrameError> {
        // Per br-frankenpandas-g3jqn: pandas raises TypeError on non-DatetimeIndex.
        require_datetime_index(self.index.labels(), "at_time")?;
        let labels = self.index.labels();
        let mut keep = Vec::new();

        for (i, label) in labels.iter().enumerate() {
            if let IndexLabel::Utf8(s) = label {
                let time_part = Self::extract_time(s);
                if let Some(ref t) = time_part
                    && t.as_str() == time
                {
                    keep.push(i);
                }
            }
        }

        let mut selected = self.take_rows_by_positions(&keep)?;
        selected.index = canonicalize_datetime_index_labels(&selected.index);
        Ok(selected)
    }

    /// Extract the time portion from a datetime string.
    fn extract_time(s: &str) -> Option<String> {
        // Try "YYYY-MM-DDTHH:MM:SS" or "YYYY-MM-DD HH:MM:SS"
        if let Some(pos) = s.find('T').or_else(|| {
            // Find space that separates date from time
            let parts: Vec<&str> = s.splitn(2, ' ').collect();
            if parts.len() == 2 && parts[0].contains('-') {
                Some(parts[0].len())
            } else {
                None
            }
        }) {
            let time_str = &s[pos + 1..];
            Some(time_str.to_string())
        } else {
            None
        }
    }

    /// Render the DataFrame as a LaTeX table.
    ///
    /// Matches `df.to_latex()`.
    pub fn to_latex(&self, include_index: bool) -> String {
        fn format_scalar(val: &Scalar) -> String {
            match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => s.clone(),
                Scalar::Timedelta64(v) => Timedelta::format(*v),
                Scalar::Datetime64(v) => format_datetime_ns(*v),
                Scalar::Period(v) => v.calendar_string(),
                Scalar::Interval(interval) => format!("{interval}"),
            }
        }

        let ncols = self.column_order.len() + if include_index { 1 } else { 0 };
        let col_spec = "r".repeat(ncols);

        let mut out = String::new();
        out.push_str(&format!("\\begin{{tabular}}{{{col_spec}}}\n"));
        out.push_str("\\toprule\n");

        // Header
        let mut headers: Vec<String> = Vec::new();
        if include_index {
            headers.push(String::new());
        }
        for name in &self.column_order {
            headers.push(name.clone());
        }
        out.push_str(&headers.join(" & "));
        out.push_str(" \\\\\n");
        out.push_str("\\midrule\n");

        // Data rows
        for (row_idx, label) in self.index.labels().iter().enumerate() {
            let mut cells: Vec<String> = Vec::new();
            if include_index {
                cells.push(match label {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => s.clone(),
                    IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                    IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    IndexLabel::Null(_) => label.to_string(),
                });
            }
            for name in &self.column_order {
                cells.push(format_scalar(&self.columns[name].values()[row_idx]));
            }
            out.push_str(&cells.join(" & "));
            out.push_str(" \\\\\n");
        }

        out.push_str("\\bottomrule\n");
        out.push_str("\\end{tabular}\n");
        out
    }

    /// Return the number of dimensions.
    ///
    /// Matches `pd.DataFrame.ndim`. Always returns 2.
    #[must_use]
    pub fn ndim(&self) -> usize {
        2
    }

    /// Return a list of the row axis labels and column axis labels.
    ///
    /// Matches `pd.DataFrame.axes`.
    #[must_use]
    pub fn axes(&self) -> (Vec<IndexLabel>, Vec<String>) {
        (self.index.labels().to_vec(), self.column_order.to_vec())
    }

    /// Total number of cells in the DataFrame (rows × columns).
    ///
    /// Matches `pd.DataFrame.size`. Equivalent to
    /// `len() * num_columns()`, but follows pandas' property naming so
    /// callers can write size-generic code that works on both Series
    /// and DataFrame.
    #[must_use]
    pub fn size(&self) -> usize {
        self.index.len() * self.column_order.len()
    }

    /// Render the DataFrame as an HTML table.
    ///
    /// Matches `pd.DataFrame.to_html()`.
    pub fn to_html(&self, include_index: bool) -> String {
        fn escape_html(s: &str) -> String {
            s.replace('&', "&amp;")
                .replace('<', "&lt;")
                .replace('>', "&gt;")
        }

        fn format_scalar(val: &Scalar) -> String {
            match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else if v.fract() == 0.0 {
                        format!("{v:.1}")
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => escape_html(s),
                Scalar::Timedelta64(v) => escape_html(&Timedelta::format(*v)),
                Scalar::Datetime64(v) => escape_html(&format_datetime_ns(*v)),
                Scalar::Period(v) => v.calendar_string(),
                Scalar::Interval(interval) => escape_html(&format!("{interval}")),
            }
        }

        let mut out = String::new();
        out.push_str("<table border=\"1\" class=\"dataframe\">\n");
        out.push_str("  <thead>\n    <tr style=\"text-align: right;\">\n");

        if include_index {
            out.push_str("      <th></th>\n");
        }
        for name in &self.column_order {
            out.push_str(&format!("      <th>{}</th>\n", escape_html(name)));
        }
        out.push_str("    </tr>\n  </thead>\n  <tbody>\n");

        for (row_idx, label) in self.index.labels().iter().enumerate() {
            out.push_str("    <tr>\n");
            if include_index {
                let idx_str = match label {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => escape_html(s),
                    IndexLabel::Timedelta64(ns) => escape_html(&Timedelta::format(*ns)),
                    IndexLabel::Datetime64(ns) => escape_html(&format_datetime_ns(*ns)),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    IndexLabel::Null(_) => label.to_string(),
                };
                out.push_str(&format!("      <th>{idx_str}</th>\n"));
            }
            for name in &self.column_order {
                out.push_str(&format!(
                    "      <td>{}</td>\n",
                    format_scalar(&self.columns[name].values()[row_idx])
                ));
            }
            out.push_str("    </tr>\n");
        }

        out.push_str("  </tbody>\n</table>");
        out
    }

    /// Group by one or more columns and aggregate.
    ///
    /// Returns a `DataFrameGroupBy` for deferred aggregation.
    pub fn groupby(&self, by: &[&str]) -> Result<DataFrameGroupBy<'_>, FrameError> {
        self.groupby_full(by, true, true)
    }

    /// Group the DataFrame by one or more columns with explicit `as_index`.
    ///
    /// When `as_index` is `true` (default), group keys become the index.
    /// When `as_index` is `false`, group keys become regular columns and the
    /// index is a default integer range. Matches `df.groupby(by, as_index=...)`.
    pub fn groupby_with_as_index(
        &self,
        by: &[&str],
        as_index: bool,
    ) -> Result<DataFrameGroupBy<'_>, FrameError> {
        self.groupby_full(by, as_index, true)
    }

    /// Group the DataFrame with full parameter control.
    ///
    /// Matches `df.groupby(by, as_index=..., sort=...)`.
    /// When `sort` is `true` (default), groups are sorted by key.
    /// When `sort` is `false`, groups appear in first-seen order.
    pub fn groupby_full(
        &self,
        by: &[&str],
        as_index: bool,
        sort: bool,
    ) -> Result<DataFrameGroupBy<'_>, FrameError> {
        self.groupby_full_options(by, as_index, sort, true)
    }

    /// Group with all options including `dropna`.
    ///
    /// When `dropna` is `true` (default), rows with NaN in any group key column
    /// are excluded. When `false`, NaN keys form their own group.
    /// Matches `df.groupby(by, dropna=False)`.
    pub fn groupby_full_options(
        &self,
        by: &[&str],
        as_index: bool,
        sort: bool,
        dropna: bool,
    ) -> Result<DataFrameGroupBy<'_>, FrameError> {
        self.groupby_full_options_with_observed(by, as_index, sort, dropna, true)
    }

    /// Group with explicit `observed` control for categorical inputs.
    ///
    /// The current DataFrame storage model materializes categorical columns to
    /// their labels, so `observed=true` matches the pandas-observable result
    /// surface for categorical groupers. `observed=false` still requires
    /// DataFrame-level category metadata and is rejected for now.
    pub fn groupby_full_options_with_observed(
        &self,
        by: &[&str],
        as_index: bool,
        sort: bool,
        dropna: bool,
        observed: bool,
    ) -> Result<DataFrameGroupBy<'_>, FrameError> {
        if !observed {
            return Err(FrameError::CompatibilityRejected(
                "groupby(..., observed=false) requires dataframe categorical metadata".to_owned(),
            ));
        }

        // Per br-frankenpandas-tm5xu: pandas raises ValueError when by is
        // empty ("You have to supply one of by and level"). Was silently
        // succeeding with an empty by-list before.
        if by.is_empty() {
            return Err(FrameError::CompatibilityRejected(
                "groupby: must specify at least one column".to_owned(),
            ));
        }
        // Validate columns exist
        for col in by {
            if !self.columns.contains_key(col) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "missing column: {col}"
                )));
            }
        }
        Ok(DataFrameGroupBy {
            df: self,
            by: by.iter().map(|s| (*s).to_string()).collect(),
            as_index,
            sort,
            dropna,
        })
    }

    /// Get summary info about the DataFrame: dtypes, non-null counts, memory.
    pub fn info(&self) -> String {
        let mut lines = Vec::new();
        lines.push(format!(
            "DataFrame: {} rows x {} columns",
            self.len(),
            self.column_order.len()
        ));
        lines.push(format!("Index: {} entries", self.index.len()));
        lines.push(String::new());
        lines.push(format!(
            "{:<20} {:<10} {:<10}",
            "Column", "Non-Null", "Dtype"
        ));
        lines.push(format!(
            "{:<20} {:<10} {:<10}",
            "------", "--------", "-----"
        ));
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let non_null = col.values().iter().filter(|v| !v.is_missing()).count();
            lines.push(format!(
                "{:<20} {:<10} {:?}",
                col_name,
                non_null,
                col.dtype()
            ));
        }
        let memory_usage = index_memory_usage_bytes(&self.index)
            + self
                .column_order
                .iter()
                .map(|name| column_memory_usage_bytes(&self.columns[name]))
                .sum::<usize>();
        lines.push(String::new());
        lines.push(format!("Memory usage: {memory_usage} bytes"));
        lines.join("\n")
    }

    /// Convert DataFrame to a nested dictionary.
    ///
    /// Matches `pd.DataFrame.to_dict(orient=...)`.
    ///
    /// Supported orients:
    /// - `"dict"`: `{column -> {index -> value}}` (default)
    /// - `"list"`: `{column -> [values]}`
    /// - `"records"`: `[{column -> value}, ...]`
    /// - `"index"`: `{index -> {column -> value}}`
    /// - `"series"`: `{column -> Series}`
    /// - `"split"`: `{index, columns, data}`
    pub fn to_dict(&self, orient: &str) -> Result<DataFrameDictResult, FrameError> {
        match orient {
            "dict" => {
                // pandas rejects duplicate index for orient='dict' — the
                // inner {index -> value} mapping would collide and drop
                // rows.
                if self.index.has_duplicates() {
                    return Err(FrameError::CompatibilityRejected(
                        "to_dict orient 'dict' does not support duplicate index labels".to_owned(),
                    ));
                }
                // Shared-key: the index label strings are carried ONCE as `keys`
                // (was `label_str.clone()` per cell = n*m String allocations, the
                // dominant cost — the labels are identical across every column). Each
                // column stores only its bare values, aligned to `keys`.
                // The per-label `to_string()` is n independent String allocations —
                // once the per-column values gather below was parallelized, THIS serial
                // key build became the Amdahl bottleneck. Parallelize it across row
                // ranges too (per-thread arenas, same lever as to_dict records); each
                // worker formats a contiguous label range, concat preserves order →
                // bit-identical.
                let index_labels = self.index.labels();
                let nkeys = index_labels.len();
                let build_keys = |lo: usize, hi: usize| -> Vec<String> {
                    index_labels[lo..hi].iter().map(|l| l.to_string()).collect()
                };
                const KEYS_PAR_MIN_ROWS: usize = 50_000;
                const KEYS_PAR_MIN_PER_WORKER: usize = 16_384;
                let key_workers = if nkeys >= KEYS_PAR_MIN_ROWS {
                    fp_columnar::cached_available_parallelism()
                        .min(16)
                        .min(nkeys / KEYS_PAR_MIN_PER_WORKER)
                        .max(1)
                } else {
                    1
                };
                let keys: Vec<String> = if key_workers >= 2 {
                    let chunk = nkeys.div_ceil(key_workers);
                    let build = &build_keys;
                    let mut parts: Vec<Vec<String>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(key_workers);
                        let mut start = 0;
                        while start < nkeys {
                            let end = (start + chunk).min(nkeys);
                            handles.push(scope.spawn(move || build(start, end)));
                            start = end;
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("to_dict dict keys thread"))
                            .collect()
                    });
                    let mut keys = Vec::with_capacity(nkeys);
                    for part in &mut parts {
                        keys.append(part);
                    }
                    keys
                } else {
                    build_keys(0, nkeys)
                };
                let col_values: Vec<(&String, &[Scalar])> = self
                    .column_order
                    .iter()
                    .map(|name| (name, self.columns[name].values()))
                    .collect();
                let build_columns = |lo: usize, hi: usize| -> Vec<(String, Vec<Scalar>)> {
                    col_values[lo..hi]
                        .iter()
                        .map(|(name, values)| ((*name).clone(), values.to_vec()))
                        .collect()
                };
                const MAPPING_PAR_MIN_CELLS: usize = 150_000;
                const MAPPING_PAR_MIN_COLS: usize = 2;
                let ncols = col_values.len();
                let total_cells = keys.len().saturating_mul(ncols);
                let workers =
                    if ncols >= MAPPING_PAR_MIN_COLS && total_cells >= MAPPING_PAR_MIN_CELLS {
                        fp_columnar::cached_available_parallelism()
                            .min(16)
                            .min(ncols)
                            .max(1)
                    } else {
                        1
                    };
                let pairs = if workers >= 2 {
                    let chunk = ncols.div_ceil(workers);
                    let build = &build_columns;
                    let mut parts: Vec<Vec<(String, Vec<Scalar>)>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(workers);
                        let mut start = 0;
                        while start < ncols {
                            let end = (start + chunk).min(ncols);
                            handles.push(scope.spawn(move || build(start, end)));
                            start = end;
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("to_dict dict thread"))
                            .collect()
                    });
                    let mut pairs = Vec::with_capacity(ncols);
                    for part in &mut parts {
                        pairs.append(part);
                    }
                    pairs
                } else {
                    build_columns(0, ncols)
                };
                let values: BTreeMap<String, Vec<Scalar>> = pairs.into_iter().collect();
                Ok(DataFrameDictResult::Mapping { keys, values })
            }
            "list" => {
                let mut result = BTreeMap::new();
                for col_name in &self.column_order {
                    let col = &self.columns[col_name];
                    result.insert(col_name.clone(), col.values().to_vec());
                }
                Ok(DataFrameDictResult::List(result))
            }
            "records" => {
                // Shared-key build: carry the column names ONCE and store only the row
                // values (`rows[i][j]`). Hoist the per-column `values()` once.
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                let columns = self.column_order.to_vec();
                let n = self.len();
                // Parallelize the per-row gather. The ORIGINAL `Vec<Vec<(String,
                // Scalar)>>` form did NOT parallelize (0.91x no-ship) — it was
                // allocation-bound on n*m per-CELL `String` clones. The shared-key form
                // removed those: it now does only n per-ROW `Vec<Scalar>` allocations
                // (10x fewer, one per row not per cell) + cheap `Scalar` value clones,
                // which mimalloc's per-thread arenas scale, and the concat just MOVES
                // the inner row-Vec pointers (no per-cell copy). Each worker builds a
                // contiguous row range; concatenation preserves order → bit-identical.
                let build_rows = |lo: usize, hi: usize| -> Vec<Vec<Scalar>> {
                    let mut out = Vec::with_capacity(hi - lo);
                    for row_idx in lo..hi {
                        out.push(
                            col_values
                                .iter()
                                .map(|col_vals| col_vals[row_idx].clone())
                                .collect(),
                        );
                    }
                    out
                };
                const RECORDS_PAR_MIN_ROWS: usize = 50_000;
                const RECORDS_PAR_MIN_PER_WORKER: usize = 16_384;
                let workers = if n >= RECORDS_PAR_MIN_ROWS {
                    fp_columnar::cached_available_parallelism()
                        .min(16)
                        .min(n / RECORDS_PAR_MIN_PER_WORKER)
                        .max(1)
                } else {
                    1
                };
                let rows: Vec<Vec<Scalar>> = if workers >= 2 {
                    let chunk = n.div_ceil(workers);
                    let build = &build_rows;
                    let mut parts: Vec<Vec<Vec<Scalar>>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(workers);
                        let mut start = 0;
                        while start < n {
                            let end = (start + chunk).min(n);
                            handles.push(scope.spawn(move || build(start, end)));
                            start = end;
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("to_dict records thread"))
                            .collect()
                    });
                    let mut rows = Vec::with_capacity(n);
                    for p in &mut parts {
                        rows.append(p);
                    }
                    rows
                } else {
                    build_rows(0, n)
                };
                Ok(DataFrameDictResult::Records { columns, rows })
            }
            "index" => {
                // pandas raises ValueError when the index has duplicates
                // because the resulting dict cannot round-trip without
                // losing rows; match that behavior with an explicit reject.
                if self.index.has_duplicates() {
                    return Err(FrameError::CompatibilityRejected(
                        "to_dict orient 'index' does not support duplicate index labels".to_owned(),
                    ));
                }
                // Shared-key: the column names are carried ONCE as `keys` (was
                // `col_name.clone()` per cell = n*m String allocations); each label
                // bucket stores only its bare row values, aligned to `keys`.
                let keys: Vec<String> = self.column_order.to_vec();
                let labels: Vec<String> =
                    if let Some((start, len)) = self.index.int64_unit_range_labels() {
                        (0..len)
                            .map(|row_idx| (start + row_idx as i64).to_string())
                            .collect()
                    } else {
                        self.index
                            .labels()
                            .iter()
                            .map(ToString::to_string)
                            .collect()
                    };
                let columns: Vec<Column> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].clone())
                    .collect();
                Ok(DataFrameDictResult::IndexMappingLazy {
                    keys,
                    labels,
                    columns,
                    values: OnceLock::new(),
                })
            }
            "series" => {
                let result = self.to_series_dict();
                Ok(DataFrameDictResult::Series(result))
            }
            "split" => {
                let columns = self
                    .column_order
                    .iter()
                    .map(|name| Scalar::Utf8(name.clone()))
                    .collect();
                let index = self
                    .index
                    .labels()
                    .iter()
                    .map(Self::index_label_to_scalar)
                    .collect();
                let data = self.row_major_values();
                Ok(DataFrameDictResult::Split(DataFrameDictSplit {
                    columns,
                    index,
                    data,
                }))
            }
            "tight" => {
                // Tight orient: pandas 2.2 payload = {index, columns,
                // data (row-major nested list), index_names, column_names}.
                let columns = self.tight_column_labels()?;
                let index: Vec<Scalar> = self
                    .index
                    .labels()
                    .iter()
                    .map(|label| match label {
                        IndexLabel::Int64(v) => Scalar::Int64(*v),
                        IndexLabel::Float64(v) => Scalar::Float64(v.0),
                        IndexLabel::Bool(b) => Scalar::Bool(*b),
                        IndexLabel::Utf8(s) => Scalar::Utf8(s.clone()),
                        IndexLabel::Timedelta64(ns) => Scalar::Timedelta64(*ns),
                        IndexLabel::Datetime64(ns) => Scalar::Utf8(format_datetime_ns(*ns)),
                        IndexLabel::Null(kind) => Scalar::Null(*kind),
                    })
                    .collect();
                let data: Vec<Vec<Scalar>> = (0..self.index.labels().len())
                    .map(|row_idx| {
                        self.column_order
                            .iter()
                            .map(|col_name| self.columns[col_name].values()[row_idx].clone())
                            .collect()
                    })
                    .collect();
                let index_names = vec![self.index.name().map(str::to_owned)];
                let column_names = self
                    .column_multiindex
                    .as_ref()
                    .map_or_else(|| vec![None], |multiindex| multiindex.names().to_vec());
                Ok(DataFrameDictResult::Tight(DataFrameDictTight {
                    index,
                    columns,
                    data,
                    index_names,
                    column_names,
                }))
            }
            other => Err(FrameError::CompatibilityRejected(format!(
                "unsupported to_dict orient: {other:?}"
            ))),
        }
    }

    /// Convert DataFrame to a dict of Series (one per column).
    ///
    /// Matches `pd.DataFrame.to_dict(orient='series')`.
    /// Returns `{column_name -> Series}` where each Series has the
    /// DataFrame's index.
    ///
    /// # Panics
    ///
    /// Panics if any column length no longer matches the DataFrame index
    /// length, which indicates internal DataFrame corruption.
    pub fn to_series_dict(&self) -> BTreeMap<String, Series> {
        let mut result = BTreeMap::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let series = Series::new(col_name.clone(), self.index.clone(), col.clone())
                .expect("column length matches index");
            result.insert(col_name.clone(), series);
        }
        result
    }

    /// Convert a flat-index DataFrame into an xarray-like Dataset snapshot.
    ///
    /// Matches the practical `pd.DataFrame.to_xarray()` shape for scalar
    /// columns: the row index becomes the single coordinate/dimension, and
    /// each DataFrame column becomes one 1-D data variable.
    pub fn to_xarray(&self) -> Result<DataFrameXArrayDataset, FrameError> {
        if self.row_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "to_xarray does not yet support row MultiIndex dimensional metadata".to_owned(),
            ));
        }
        if self.column_multiindex.is_some() {
            return Err(FrameError::CompatibilityRejected(
                "to_xarray does not yet support column MultiIndex dimensional metadata".to_owned(),
            ));
        }

        let dim_name = self.index.name().unwrap_or("index").to_owned();
        if self.columns.contains_key(&dim_name) {
            return Err(FrameError::CompatibilityRejected(format!(
                "to_xarray index coordinate name {dim_name:?} collides with a column label"
            )));
        }

        let coords = BTreeMap::from([(
            dim_name.clone(),
            self.index
                .labels()
                .iter()
                .map(Self::index_label_to_scalar)
                .collect(),
        )]);
        let mut data_vars = BTreeMap::new();
        for name in &self.column_order {
            let column = self
                .columns
                .get(name)
                .expect("column name listed in order must exist");
            data_vars.insert(
                name.clone(),
                DataFrameXArrayVariable {
                    dims: vec![dim_name.clone()],
                    data: column.values().to_vec(),
                    dtype: column.dtype(),
                },
            );
        }

        Ok(DataFrameXArrayDataset {
            dim_name,
            coords,
            data_vars,
            data_var_order: self.column_order.to_vec(),
        })
    }

    /// Export DataFrame to CSV string.
    ///
    /// Matches `df.to_csv()` returning a string representation.
    pub fn to_csv(&self, sep: char, include_index: bool) -> String {
        let mut out = String::new();

        // Header
        if include_index {
            // Use the index name if set, otherwise empty string (pandas behavior)
            if let Some(idx_name) = self.index.name() {
                out.push_str(&csv_escape(idx_name, sep));
            }
            out.push(sep);
        }
        for (i, name) in self.column_order.iter().enumerate() {
            if i > 0 {
                out.push(sep);
            }
            out.push_str(&csv_escape(name, sep));
        }
        out.push('\n');

        // Rows
        for (row_idx, label) in self.index.labels().iter().enumerate() {
            if include_index {
                match label {
                    IndexLabel::Int64(v) => out.push_str(&v.to_string()),
                    IndexLabel::Utf8(s) => out.push_str(&csv_escape(s, sep)),
                    IndexLabel::Timedelta64(ns) => {
                        out.push_str(&csv_escape(&Timedelta::format(*ns), sep))
                    }
                    IndexLabel::Datetime64(ns) => {
                        out.push_str(&csv_escape(&format_datetime_ns(*ns), sep))
                    }
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => {
                        out.push_str(&csv_escape(&f.to_string(), sep))
                    }
                    // pandas to_csv writes a missing index label as EMPTY.
                    IndexLabel::Null(_) => {}
                }
                out.push(sep);
            }
            for (col_idx, name) in self.column_order.iter().enumerate() {
                if col_idx > 0 {
                    out.push(sep);
                }
                let val = &self.columns[name].values()[row_idx];
                match val {
                    Scalar::Null(_) => {}
                    Scalar::Bool(b) => out.push_str(if *b { "True" } else { "False" }),
                    Scalar::Int64(v) => out.push_str(&v.to_string()),
                    // Per br-frankenpandas-41edff: whole-number Float64 needs
                    // pandas-canonical `.0` suffix.
                    Scalar::Float64(v) => out.push_str(&format_pandas_csv_float(*v)),
                    Scalar::Utf8(s) => out.push_str(&csv_escape(s, sep)),
                    Scalar::Timedelta64(v) if *v == Timedelta::NAT => {}
                    Scalar::Timedelta64(v) => out.push_str(&Timedelta::format(*v)),
                    Scalar::Datetime64(v) if *v == Timedelta::NAT => {}
                    Scalar::Datetime64(v) => out.push_str(&format_datetime_ns(*v)),
                    Scalar::Period(v) if v.ordinal == i64::MIN => {}
                    Scalar::Period(v) => out.push_str(&v.calendar_string()),
                    Scalar::Interval(interval) => out.push_str(&format!("{interval}")),
                }
            }
            out.push('\n');
        }

        out
    }

    /// Export DataFrame to CSV string with additional formatting options.
    ///
    /// Matches `df.to_csv(sep, index, na_rep, columns)`.
    /// - `na_rep`: string to represent missing values (default empty)
    /// - `columns`: optional subset of columns to include
    pub fn to_csv_options(
        &self,
        sep: char,
        include_index: bool,
        na_rep: &str,
        columns: Option<&[&str]>,
    ) -> Result<String, FrameError> {
        let col_order: Vec<&str> = match columns {
            Some(cols) => {
                for &c in cols {
                    if !self.columns.contains_key(c) {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "column '{c}' not found"
                        )));
                    }
                }
                cols.to_vec()
            }
            None => self.column_order.iter().map(|s| s.as_str()).collect(),
        };

        let mut out = String::new();
        let na_rep_escaped = csv_escape(na_rep, sep);

        // Header
        if include_index {
            // Use the index name if set, otherwise empty string (pandas behavior)
            if let Some(idx_name) = self.index.name() {
                out.push_str(&csv_escape(idx_name, sep));
            }
            out.push(sep);
        }
        for (i, name) in col_order.iter().enumerate() {
            if i > 0 {
                out.push(sep);
            }
            out.push_str(&csv_escape(name, sep));
        }
        out.push('\n');

        // Rows
        for (row_idx, label) in self.index.labels().iter().enumerate() {
            if include_index {
                match label {
                    IndexLabel::Int64(v) => out.push_str(&v.to_string()),
                    IndexLabel::Utf8(s) => out.push_str(&csv_escape(s, sep)),
                    IndexLabel::Timedelta64(ns) => {
                        out.push_str(&csv_escape(&Timedelta::format(*ns), sep))
                    }
                    IndexLabel::Datetime64(ns) => {
                        out.push_str(&csv_escape(&format_datetime_ns(*ns), sep))
                    }
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => {
                        out.push_str(&csv_escape(&f.to_string(), sep))
                    }
                    // pandas to_csv writes a missing index label as EMPTY.
                    IndexLabel::Null(_) => {}
                }
                out.push(sep);
            }
            for (col_idx, name) in col_order.iter().enumerate() {
                if col_idx > 0 {
                    out.push(sep);
                }
                let val = &self.columns[*name].values()[row_idx];
                match val {
                    Scalar::Null(_) => out.push_str(&na_rep_escaped),
                    Scalar::Bool(b) => out.push_str(if *b { "True" } else { "False" }),
                    Scalar::Int64(v) => out.push_str(&v.to_string()),
                    // Per br-frankenpandas-41edff: whole-number Float64 needs
                    // pandas-canonical `.0` suffix.
                    Scalar::Float64(v) => out.push_str(&format_pandas_csv_float(*v)),
                    Scalar::Utf8(s) => out.push_str(&csv_escape(s, sep)),
                    Scalar::Timedelta64(v) if *v == Timedelta::NAT => out.push_str(&na_rep_escaped),
                    Scalar::Timedelta64(v) => out.push_str(&Timedelta::format(*v)),
                    Scalar::Datetime64(v) if *v == Timedelta::NAT => out.push_str(&na_rep_escaped),
                    Scalar::Datetime64(v) => out.push_str(&format_datetime_ns(*v)),
                    Scalar::Period(v) if v.ordinal == i64::MIN => out.push_str(&na_rep_escaped),
                    Scalar::Period(v) => out.push_str(&v.calendar_string()),
                    Scalar::Interval(interval) => out.push_str(&format!("{interval}")),
                }
            }
            out.push('\n');
        }

        Ok(out)
    }

    /// Export DataFrame to CSV string with quoting control.
    ///
    /// Matches `df.to_csv(..., quoting=csv.QUOTE_*)`.
    /// - `CsvQuoting::Minimal`: Quote only when necessary (default pandas behavior)
    /// - `CsvQuoting::All`: Quote all fields including headers, index, and values
    /// - `CsvQuoting::NonNumeric`: Quote all non-numeric fields
    /// - `CsvQuoting::None`: Never quote fields
    /// - `header`: if true (default), write column names as first row
    pub fn to_csv_with_quoting(
        &self,
        sep: char,
        include_index: bool,
        na_rep: &str,
        columns: Option<&[&str]>,
        quoting: CsvQuoting,
    ) -> Result<String, FrameError> {
        self.to_csv_with_header(sep, include_index, na_rep, columns, quoting, true)
    }

    /// Export DataFrame to CSV string with full control over quoting and header.
    ///
    /// - `header`: if true, write column names as first row; if false, omit header
    pub fn to_csv_with_header(
        &self,
        sep: char,
        include_index: bool,
        na_rep: &str,
        columns: Option<&[&str]>,
        quoting: CsvQuoting,
        header: bool,
    ) -> Result<String, FrameError> {
        self.to_csv_full(sep, include_index, na_rep, columns, quoting, header, None)
    }

    /// Export DataFrame to CSV string with full control over all options.
    ///
    /// - `escapechar`: when using CsvQuoting::None, escape special characters with this
    #[allow(clippy::too_many_arguments)]
    pub fn to_csv_full(
        &self,
        sep: char,
        include_index: bool,
        na_rep: &str,
        columns: Option<&[&str]>,
        quoting: CsvQuoting,
        header: bool,
        escapechar: Option<char>,
    ) -> Result<String, FrameError> {
        let col_order: Vec<&str> = match columns {
            Some(cols) => {
                for &c in cols {
                    if !self.columns.contains_key(c) {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "column '{c}' not found"
                        )));
                    }
                }
                cols.to_vec()
            }
            None => self.column_order.iter().map(|s| s.as_str()).collect(),
        };

        let quote_str = |s: &str, is_numeric: bool| -> String {
            match quoting {
                CsvQuoting::Minimal => csv_escape(s, sep),
                CsvQuoting::All => csv_quote_always(s),
                CsvQuoting::NonNumeric if is_numeric => s.to_owned(),
                CsvQuoting::NonNumeric => csv_quote_always(s),
                CsvQuoting::None => match escapechar {
                    Some(esc) => csv_escape_with_char(s, sep, esc),
                    None => s.to_owned(),
                },
            }
        };

        let mut out = String::new();

        // Header (only if header=true)
        if header {
            if include_index {
                if let Some(idx_name) = self.index.name() {
                    out.push_str(&quote_str(idx_name, false));
                } else if quoting == CsvQuoting::All {
                    out.push_str("\"\"");
                }
                out.push(sep);
            }
            for (i, name) in col_order.iter().enumerate() {
                if i > 0 {
                    out.push(sep);
                }
                out.push_str(&quote_str(name, false));
            }
            out.push('\n');
        }

        // Rows
        for (row_idx, label) in self.index.labels().iter().enumerate() {
            if include_index {
                match label {
                    IndexLabel::Int64(v) => {
                        let s = v.to_string();
                        out.push_str(&quote_str(&s, true));
                    }
                    IndexLabel::Utf8(s) => out.push_str(&quote_str(s, false)),
                    IndexLabel::Timedelta64(ns) => {
                        out.push_str(&quote_str(&Timedelta::format(*ns), false))
                    }
                    IndexLabel::Datetime64(ns) => {
                        out.push_str(&quote_str(&format_datetime_ns(*ns), false))
                    }
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => {
                        out.push_str(&quote_str(&f.to_string(), false))
                    }
                    IndexLabel::Null(_) => out.push_str(&quote_str(&label.to_string(), false)),
                }
                out.push(sep);
            }
            for (col_idx, name) in col_order.iter().enumerate() {
                if col_idx > 0 {
                    out.push(sep);
                }
                let val = &self.columns[*name].values()[row_idx];
                match val {
                    Scalar::Null(_) => out.push_str(&quote_str(na_rep, false)),
                    Scalar::Bool(b) => {
                        let s = if *b { "True" } else { "False" };
                        out.push_str(&quote_str(s, false));
                    }
                    Scalar::Int64(v) => {
                        let s = v.to_string();
                        out.push_str(&quote_str(&s, true));
                    }
                    Scalar::Float64(v) => {
                        let s = format_pandas_csv_float(*v);
                        out.push_str(&quote_str(&s, true));
                    }
                    Scalar::Utf8(s) => out.push_str(&quote_str(s, false)),
                    Scalar::Timedelta64(v) if *v == Timedelta::NAT => {
                        out.push_str(&quote_str(na_rep, false))
                    }
                    Scalar::Timedelta64(v) => {
                        out.push_str(&quote_str(&Timedelta::format(*v), false))
                    }
                    Scalar::Datetime64(v) if *v == Timedelta::NAT => {
                        out.push_str(&quote_str(na_rep, false))
                    }
                    Scalar::Datetime64(v) => {
                        out.push_str(&quote_str(&format_datetime_ns(*v), false))
                    }
                    Scalar::Period(v) if v.ordinal == i64::MIN => {
                        out.push_str(&quote_str(na_rep, false))
                    }
                    Scalar::Period(v) => out.push_str(&quote_str(&v.calendar_string(), false)),
                    Scalar::Interval(interval) => {
                        out.push_str(&quote_str(&format!("{interval}"), false))
                    }
                }
            }
            out.push('\n');
        }

        Ok(out)
    }

    /// Export DataFrame to JSON string.
    ///
    /// Matches `pd.DataFrame.to_json(orient=...)`.
    pub fn to_json(&self, orient: &str) -> Result<String, FrameError> {
        match orient {
            "records" => {
                // Stream rows directly to the JSON buffer (RecordsJson), skipping
                // the Vec<Value::Object> tree: no n*m Value allocs, no n*m
                // column-name String clones, no n Map allocs. Bit-identical to the
                // old serialize_json_value(Value::Array(rows)).
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                let record = RecordsJson {
                    column_order: &self.column_order,
                    col_values: &col_values,
                    rows: self.len(),
                };
                let n = self.len();
                // Each row's `{...}` object is independent, and the serial
                // `serde_json::to_string(&RecordsJson)` walks all n rows on ONE thread
                // (the residual cost of records JSON, ~370ms@1M×10). `par_json_body`
                // splits the row range across workers and concats their buffers in row
                // order; wrapping in `[`..`]` reproduces SerializeSeq exactly.
                let body = par_json_body(n, &|buf, row| {
                    serde_json::to_writer(
                        &mut *buf,
                        &RowJson {
                            record: &record,
                            row_idx: row,
                        },
                    )
                    .map_err(|_| ())
                })
                .map_err(|()| json_ser_err())?;
                wrap_json_body(b'[', &body, b']')
            }
            "columns" => {
                if self.index.has_duplicates() {
                    return Err(FrameError::CompatibilityRejected(
                        "to_json orient 'columns' does not support duplicate index labels"
                            .to_owned(),
                    ));
                }
                // Stream {col: {index_key: value}} directly (ColumnsJson),
                // skipping the nested Value tree + name/key clones. Index keys
                // precomputed once. Bit-identical.
                let index_keys: Vec<String> = self
                    .index
                    .labels()
                    .iter()
                    .map(index_label_to_json_key)
                    .collect();
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                // Column-major: the outer map has only `m` entries, so parallelize
                // WITHIN each column — its n `"key":value` entries are independent.
                // Reproduces ColumnsJson/ColumnValuesJson byte-for-byte: the outer
                // `{` "name" `:` {inner} `,` ... `}` and the inner comma-joined
                // entries are exactly what SerializeMap emits.
                let n = self.len();
                let mut out: Vec<u8> = Vec::new();
                out.push(b'{');
                for (ci, (name, col_vals)) in
                    self.column_order.iter().zip(col_values.iter()).enumerate()
                {
                    if ci > 0 {
                        out.push(b',');
                    }
                    serde_json::to_writer(&mut out, name).map_err(|_| json_ser_err())?;
                    out.push(b':');
                    let inner = par_json_body(n, &|buf, row| {
                        serde_json::to_writer(&mut *buf, &index_keys[row]).map_err(|_| ())?;
                        buf.push(b':');
                        serde_json::to_writer(&mut *buf, &CellJson(&col_vals[row])).map_err(|_| ())
                    })
                    .map_err(|()| json_ser_err())?;
                    out.push(b'{');
                    out.extend_from_slice(&inner);
                    out.push(b'}');
                }
                out.push(b'}');
                String::from_utf8(out).map_err(|_| json_ser_err())
            }
            "index" => {
                if self.index.has_duplicates() {
                    return Err(FrameError::CompatibilityRejected(
                        "to_json orient 'index' does not support duplicate index labels".to_owned(),
                    ));
                }
                // Stream {index_key: {col: value}} directly (IndexJson, reusing
                // RowJson for the inner column map). Bit-identical.
                let index_keys: Vec<String> = self
                    .index
                    .labels()
                    .iter()
                    .map(index_label_to_json_key)
                    .collect();
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                let record = RecordsJson {
                    column_order: &self.column_order,
                    col_values: &col_values,
                    rows: self.len(),
                };
                // Each `"index_key":{col:value}` entry is independent. The key is
                // written with `to_writer(&String)`, which emits the same quoted+
                // escaped bytes serde's map-key serializer produces, then `:` then
                // the RowJson object — exactly SerializeMap's entry encoding.
                let body = par_json_body(self.len(), &|buf, row| {
                    serde_json::to_writer(&mut *buf, &index_keys[row]).map_err(|_| ())?;
                    buf.push(b':');
                    serde_json::to_writer(
                        &mut *buf,
                        &RowJson {
                            record: &record,
                            row_idx: row,
                        },
                    )
                    .map_err(|_| ())
                })
                .map_err(|()| json_ser_err())?;
                wrap_json_body(b'{', &body, b'}')
            }
            "split" => {
                // Stream the big `data` array (DataArrayJson), keep the small
                // per-row index vec. Skips the n*m data Value tree + per-cell
                // values(). Columns are serialized directly from column_order.
                let index: Vec<Value> = self
                    .index
                    .labels()
                    .iter()
                    .map(index_label_to_json_value)
                    .collect();
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                // Only `data` is O(n*m); `columns`/`index` stay serial. Emitting the
                // three entries in SplitJson's order with literal `"columns":` /
                // `,"index":` / `,"data":` keys (no escapes) reproduces SerializeMap
                // byte-for-byte.
                let body = par_json_body(self.len(), &|buf, row| {
                    serde_json::to_writer(
                        &mut *buf,
                        &RowArrayJson {
                            col_values: &col_values,
                            row_idx: row,
                        },
                    )
                    .map_err(|_| ())
                })
                .map_err(|()| json_ser_err())?;
                let mut out: Vec<u8> = Vec::with_capacity(body.len() + 64);
                out.push(b'{');
                out.extend_from_slice(b"\"columns\":");
                serde_json::to_writer(&mut out, &self.column_order).map_err(|_| json_ser_err())?;
                out.extend_from_slice(b",\"index\":");
                serde_json::to_writer(&mut out, &index).map_err(|_| json_ser_err())?;
                out.extend_from_slice(b",\"data\":[");
                out.extend_from_slice(&body);
                out.extend_from_slice(b"]}");
                String::from_utf8(out).map_err(|_| json_ser_err())
            }
            "values" => {
                // Stream rows-of-arrays directly (DataArrayJson), skipping the
                // n*m Value tree + the per-cell columns[name].values() lookup.
                let col_values: Vec<&[Scalar]> = self
                    .column_order
                    .iter()
                    .map(|name| self.columns[name].values())
                    .collect();
                // Each row's `[...]` array is independent; wrapping the comma-joined
                // bodies in `[`..`]` reproduces DataArrayJson's SerializeSeq exactly.
                let body = par_json_body(self.len(), &|buf, row| {
                    serde_json::to_writer(
                        &mut *buf,
                        &RowArrayJson {
                            col_values: &col_values,
                            row_idx: row,
                        },
                    )
                    .map_err(|_| ())
                })
                .map_err(|()| json_ser_err())?;
                wrap_json_body(b'[', &body, b']')
            }
            "table" => {
                if self.column_multiindex.is_some() {
                    return Err(FrameError::CompatibilityRejected(
                        "orient='table' is not supported for MultiIndex columns".to_owned(),
                    ));
                }

                let index_name = match self.index.name() {
                    Some(name) => {
                        if self.columns.contains_key(name) {
                            return Err(FrameError::CompatibilityRejected(format!(
                                "to_json orient 'table' cannot serialize index name {name:?} because it collides with a column label"
                            )));
                        }
                        name.to_owned()
                    }
                    None => self.reset_index_column_name()?,
                };

                let mut fields = Vec::with_capacity(self.column_order.len() + 1);
                fields.push(Value::Object(Map::from_iter([
                    ("name".to_owned(), Value::String(index_name.clone())),
                    (
                        "type".to_owned(),
                        Value::String(
                            index_labels_to_table_schema_type(self.index.labels()).to_owned(),
                        ),
                    ),
                ])));
                for (col_idx, name) in self.column_order.iter().enumerate() {
                    let column = &self.columns[name];
                    fields.push(Value::Object(Map::from_iter([
                        (
                            "name".to_owned(),
                            Value::String(self.table_column_name(col_idx)?),
                        ),
                        (
                            "type".to_owned(),
                            Value::String(dtype_to_table_schema_type(column.dtype()).to_owned()),
                        ),
                    ])));
                }

                let data = (0..self.len())
                    .map(|row_idx| {
                        let mut row = Map::new();
                        row.insert(
                            index_name.clone(),
                            index_label_to_json_value(&self.index.labels()[row_idx]),
                        );
                        for (col_idx, name) in self.column_order.iter().enumerate() {
                            row.insert(
                                self.table_column_name(col_idx)?,
                                scalar_to_json_value(&self.columns[name].values()[row_idx]),
                            );
                        }
                        Ok(Value::Object(row))
                    })
                    .collect::<Result<Vec<_>, FrameError>>()?;

                serialize_json_value(&Value::Object(Map::from_iter([
                    (
                        "schema".to_owned(),
                        Value::Object(Map::from_iter([
                            ("fields".to_owned(), Value::Array(fields)),
                            (
                                "primaryKey".to_owned(),
                                Value::Array(vec![Value::String(index_name)]),
                            ),
                            (
                                "pandas_version".to_owned(),
                                Value::String("1.4.0".to_owned()),
                            ),
                        ])),
                    ),
                    ("data".to_owned(), Value::Array(data)),
                ])))
            }
            other => Err(FrameError::CompatibilityRejected(format!(
                "unsupported to_json orient: {other:?}"
            ))),
        }
    }

    /// Return the DataFrame values as a row-major 2D vector of f64.
    ///
    /// Matches `pd.DataFrame.to_numpy()`. Non-numeric values become NaN.
    /// Each inner vector is one row.
    pub fn to_numpy(&self) -> Vec<Vec<f64>> {
        let n = self.len();
        // Resolve each column ONCE (the old code did a BTreeMap lookup + values()
        // per cell, n*m times) and pre-extract its contiguous typed buffer when
        // it is an all-valid Int64/Float64 column. Bit-identical: for those the
        // old per-cell path returned `val.to_f64()` for the non-missing scalar —
        // exactly `data[r]` (Float64) / `data[r] as f64` (Int64, matching
        // Scalar::Int64::to_f64). Any other/nullable column keeps the exact
        // Scalar path. (br-frankenpandas-tonp1)
        enum NumpyCol<'a> {
            F(&'a [f64]),
            I(&'a [i64]),
            Scalars(&'a [Scalar]),
        }
        let cols: Vec<NumpyCol<'_>> = self
            .column_order
            .iter()
            .map(|name| {
                let col = &self.columns[name];
                match col.as_f64_slice() {
                    Some(s) if s.len() == n => NumpyCol::F(s),
                    _ => match col.as_i64_slice() {
                        Some(s) if s.len() == n => NumpyCol::I(s),
                        _ => NumpyCol::Scalars(col.values()),
                    },
                }
            })
            .collect();
        (0..n)
            .map(|row_idx| {
                cols.iter()
                    .map(|col| match col {
                        NumpyCol::F(s) => s[row_idx],
                        NumpyCol::I(s) => s[row_idx] as f64,
                        NumpyCol::Scalars(v) => {
                            let val = &v[row_idx];
                            if val.is_missing() {
                                f64::NAN
                            } else {
                                val.to_f64().unwrap_or(f64::NAN)
                            }
                        }
                    })
                    .collect()
            })
            .collect()
    }

    /// Numeric-coerced values as a single **row-major contiguous** `Vec<f64>`
    /// plus `(rows, cols)`, i.e. numpy C-order.
    ///
    /// Unlike [`to_numpy`](Self::to_numpy) — which returns a nested
    /// `Vec<Vec<f64>>` and pays one heap allocation per row (allocation-bound at
    /// large row counts) — this materializes into ONE buffer, matching numpy's
    /// contiguous 2-D layout and making the result usable directly by BLAS /
    /// interop. Values are identical to `to_numpy` (`flat[i*cols + j] ==
    /// to_numpy()[i][j]`): all-valid Int64/Float64 columns copy/cast from their
    /// typed slice, everything else takes the exact `Scalar` `to_f64`/NaN path.
    #[must_use]
    pub fn to_numpy_flat(&self) -> (Vec<f64>, usize, usize) {
        let n = self.len();
        let ncols = self.column_order.len();
        enum NumpyCol<'a> {
            F(&'a [f64]),
            I(&'a [i64]),
            Scalars(&'a [Scalar]),
        }
        let cols: Vec<NumpyCol<'_>> = self
            .column_order
            .iter()
            .map(|name| {
                let col = &self.columns[name];
                match col.as_f64_slice() {
                    Some(s) if s.len() == n => NumpyCol::F(s),
                    _ => match col.as_i64_slice() {
                        Some(s) if s.len() == n => NumpyCol::I(s),
                        _ => NumpyCol::Scalars(col.values()),
                    },
                }
            })
            .collect();
        let mut out = vec![0.0_f64; n.saturating_mul(ncols)];
        // Column-outer fill: sequential source read of each typed slice, strided
        // (stride = ncols) write into the row-major buffer.
        for (j, col) in cols.iter().enumerate() {
            match col {
                NumpyCol::F(s) => {
                    for i in 0..n {
                        out[i * ncols + j] = s[i];
                    }
                }
                NumpyCol::I(s) => {
                    for i in 0..n {
                        out[i * ncols + j] = s[i] as f64;
                    }
                }
                NumpyCol::Scalars(v) => {
                    for i in 0..n {
                        let val = &v[i];
                        out[i * ncols + j] = if val.is_missing() {
                            f64::NAN
                        } else {
                            val.to_f64().unwrap_or(f64::NAN)
                        };
                    }
                }
            }
        }
        (out, n, ncols)
    }

    /// Render the DataFrame as a formatted plain-text table.
    ///
    /// Matches `df.to_string()` with pandas' default `index=True` behavior.
    #[allow(clippy::inherent_to_string_shadow_display)]
    pub fn to_string(&self) -> String {
        self.to_string_table(true)
    }

    /// Render the DataFrame as a formatted plain-text table with explicit
    /// index-column control.
    ///
    /// Matches `df.to_string()`. Columns are right-aligned for numeric data,
    /// left-aligned for strings. Includes index column on the left.
    pub fn to_string_table(&self, include_index: bool) -> String {
        fn format_scalar(val: &Scalar) -> String {
            match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else if *v == v.round() && v.abs() < 1e15 {
                        format!("{v:.1}")
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => s.clone(),
                Scalar::Timedelta64(v) => Timedelta::format(*v),
                Scalar::Datetime64(v) => format_datetime_ns(*v),
                Scalar::Period(v) => v.calendar_string(),
                Scalar::Interval(interval) => format!("{interval}"),
            }
        }

        let nrows = self.len();

        // Compute column widths
        let mut col_data: Vec<(&str, Vec<String>)> = Vec::new();

        if include_index {
            let idx_cells: Vec<String> = self
                .index
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => s.clone(),
                    IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                    IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    IndexLabel::Null(_) => l.to_string(),
                })
                .collect();
            col_data.push(("", idx_cells));
        }

        for name in &self.column_order {
            let col = &self.columns[name];
            let cells: Vec<String> = col.values().iter().map(format_scalar).collect();
            col_data.push((name.as_str(), cells));
        }

        // Compute max width per column (including header)
        let widths: Vec<usize> = col_data
            .iter()
            .map(|(header, cells)| {
                let max_cell = cells.iter().map(|c| c.len()).max().unwrap_or(0);
                header.len().max(max_cell)
            })
            .collect();

        let mut out = String::new();

        // Header row
        let header_parts: Vec<String> = col_data
            .iter()
            .zip(&widths)
            .map(|((header, _), w)| format!("{:>width$}", header, width = *w))
            .collect();
        out.push_str(&header_parts.join("  "));
        out.push('\n');

        // Data rows
        for row_idx in 0..nrows {
            let row_parts: Vec<String> = col_data
                .iter()
                .zip(&widths)
                .map(|((_, cells), w)| format!("{:>width$}", cells[row_idx], width = *w))
                .collect();
            out.push_str(&row_parts.join("  "));
            if row_idx + 1 < nrows {
                out.push('\n');
            }
        }

        out
    }

    /// Render the DataFrame as a string table with truncation.
    ///
    /// Matches `df.to_string(max_rows=N, max_cols=M)`. When the number
    /// of rows exceeds `max_rows`, shows the first and last `max_rows/2`
    /// rows with "..." in between. Similarly truncates columns.
    pub fn to_string_truncated(
        &self,
        include_index: bool,
        max_rows: Option<usize>,
        max_cols: Option<usize>,
    ) -> String {
        let need_row_trunc = max_rows.is_some_and(|m| self.len() > m);
        let need_col_trunc = max_cols.is_some_and(|m| self.column_order.len() > m);

        // If no truncation needed, delegate
        if !need_row_trunc && !need_col_trunc {
            return self.to_string_table(include_index);
        }

        // Truncate columns if needed
        let col_order = if let Some(max_c) = max_cols {
            if self.column_order.len() > max_c {
                let half = max_c / 2;
                let mut cols: Vec<String> = self.column_order[..half].to_vec();
                cols.push("...".to_string());
                cols.extend_from_slice(&self.column_order[self.column_order.len() - half..]);
                cols
            } else {
                self.column_order.to_vec()
            }
        } else {
            self.column_order.to_vec()
        };

        // Determine row indices to show
        let row_indices: Vec<usize> = if let Some(max_r) = max_rows {
            if self.len() > max_r {
                let half = max_r / 2;
                let mut indices: Vec<usize> = (0..half).collect();
                indices.push(usize::MAX); // sentinel for "..."
                indices.extend((self.len() - half)..self.len());
                indices
            } else {
                (0..self.len()).collect()
            }
        } else {
            (0..self.len()).collect()
        };

        fn format_scalar(val: &Scalar) -> String {
            match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else if *v == v.round() && v.abs() < 1e15 {
                        format!("{v:.1}")
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => s.clone(),
                Scalar::Timedelta64(v) => Timedelta::format(*v),
                Scalar::Datetime64(v) => format_datetime_ns(*v),
                Scalar::Period(v) => v.calendar_string(),
                Scalar::Interval(interval) => format!("{interval}"),
            }
        }

        let mut out = String::new();
        // Header
        let mut header_parts: Vec<String> = Vec::new();
        if include_index {
            header_parts.push(String::new());
        }
        for c in &col_order {
            header_parts.push(c.clone());
        }
        out.push_str(&header_parts.join("  "));
        out.push('\n');

        // Rows
        for &row_idx in &row_indices {
            if row_idx == usize::MAX {
                out.push_str("...\n");
                continue;
            }
            let mut parts: Vec<String> = Vec::new();
            if include_index {
                parts.push(match &self.index.labels()[row_idx] {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => s.clone(),
                    IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                    IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    null @ IndexLabel::Null(_) => null.to_string(),
                });
            }
            for c in &col_order {
                if c == "..." {
                    parts.push("...".to_string());
                } else if let Some(col) = self.columns.get(c) {
                    parts.push(format_scalar(&col.values()[row_idx]));
                }
            }
            out.push_str(&parts.join("  "));
            if row_idx != *row_indices.last().unwrap_or(&0) {
                out.push('\n');
            }
        }
        out
    }

    /// Render the DataFrame as a Markdown table.
    ///
    /// Matches `df.to_markdown()`.
    pub fn to_markdown(
        &self,
        include_index: bool,
        tablefmt: Option<&str>,
    ) -> Result<String, FrameError> {
        fn format_scalar(val: &Scalar) -> String {
            match val {
                Scalar::Null(_) => "NaN".to_string(),
                Scalar::Bool(b) => if *b { "True" } else { "False" }.to_string(),
                Scalar::Int64(v) => v.to_string(),
                Scalar::Float64(v) => {
                    if v.is_nan() {
                        "NaN".to_string()
                    } else if *v == v.round() && v.abs() < 1e15 {
                        format!("{v:.1}")
                    } else {
                        v.to_string()
                    }
                }
                Scalar::Utf8(s) => s.clone(),
                Scalar::Timedelta64(v) => Timedelta::format(*v),
                Scalar::Datetime64(v) => format_datetime_ns(*v),
                Scalar::Period(v) => v.calendar_string(),
                Scalar::Interval(interval) => format!("{interval}"),
            }
        }

        let nrows = self.len();
        let mut headers: Vec<String> = Vec::new();
        let mut col_cells: Vec<Vec<String>> = Vec::new();

        if include_index {
            headers.push(String::new());
            let idx_cells: Vec<String> = self
                .index
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Int64(v) => v.to_string(),
                    IndexLabel::Utf8(s) => s.clone(),
                    IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                    IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                    IndexLabel::Null(_) => l.to_string(),
                })
                .collect();
            col_cells.push(idx_cells);
        }

        for name in &self.column_order {
            headers.push(name.clone());
            let col = &self.columns[name];
            let cells: Vec<String> = col.values().iter().map(format_scalar).collect();
            col_cells.push(cells);
        }

        // Compute widths
        let widths: Vec<usize> = headers
            .iter()
            .zip(&col_cells)
            .map(|(h, cells)| {
                let max_cell = cells.iter().map(|c| c.len()).max().unwrap_or(0);
                h.len().max(max_cell).max(3) // min width 3 for separator ---
            })
            .collect();

        fn render_markdown_row(cells: &[String], widths: &[usize]) -> String {
            let mut out = String::new();
            out.push('|');
            for (cell, width) in cells.iter().zip(widths) {
                out.push_str(&format!(" {:width$} |", cell, width = *width));
            }
            out
        }

        fn render_markdown_separator(widths: &[usize]) -> String {
            let mut out = String::new();
            out.push('|');
            for width in widths {
                out.push(' ');
                out.push_str(&"-".repeat(*width));
                out.push_str(" |");
            }
            out
        }

        fn render_grid_border(
            widths: &[usize],
            left: char,
            join: char,
            right: char,
            ch: char,
        ) -> String {
            let mut out = String::new();
            out.push(left);
            for width in widths {
                out.push_str(&ch.to_string().repeat(*width + 2));
                out.push(join);
            }
            out.pop();
            out.push(right);
            out
        }

        fn render_box_row(cells: &[String], widths: &[usize], edge: char, divider: char) -> String {
            let mut out = String::new();
            out.push(edge);
            for (cell, width) in cells.iter().zip(widths) {
                out.push_str(&format!(" {:width$} ", cell, width = *width));
                out.push(divider);
            }
            out.pop();
            out.push(edge);
            out
        }

        fn render_plain_row(cells: &[String], widths: &[usize]) -> String {
            cells
                .iter()
                .zip(widths)
                .map(|(cell, width)| format!("{cell:width$}", width = *width))
                .collect::<Vec<_>>()
                .join("  ")
        }

        fn render_plain_rule(widths: &[usize], ch: char) -> String {
            widths
                .iter()
                .map(|width| ch.to_string().repeat(*width))
                .collect::<Vec<_>>()
                .join("  ")
        }

        fn render_psql_row(cells: &[String], widths: &[usize]) -> String {
            let mut out = String::new();
            out.push('|');
            for (cell, width) in cells.iter().zip(widths) {
                out.push_str(&format!(" {:width$} |", cell, width = *width));
            }
            out
        }

        fn render_psql_header_rule(widths: &[usize]) -> String {
            let mut out = String::new();
            out.push('|');
            for (idx, width) in widths.iter().enumerate() {
                out.push_str(&"-".repeat(*width + 2));
                out.push('|');
                if idx + 1 == widths.len() {
                    break;
                }
            }
            out
        }

        let rows = (0..nrows)
            .map(|row_idx| {
                col_cells
                    .iter()
                    .map(|cells| cells[row_idx].clone())
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();

        let format = tablefmt.unwrap_or("github");
        match format {
            "github" | "pipe" => {
                let mut lines = Vec::with_capacity(nrows + 2);
                lines.push(render_markdown_row(&headers, &widths));
                lines.push(render_markdown_separator(&widths));
                for row in rows {
                    lines.push(render_markdown_row(&row, &widths));
                }
                Ok(lines.join("\n"))
            }
            "grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let border = render_grid_border(&widths, '+', '+', '+', '-');
                let header_border = render_grid_border(&widths, '+', '+', '+', '=');
                lines.push(border.clone());
                lines.push(render_markdown_row(&headers, &widths));
                lines.push(header_border);
                for row in rows {
                    lines.push(render_markdown_row(&row, &widths));
                    lines.push(border.clone());
                }
                Ok(lines.join("\n"))
            }
            "plain" => {
                let mut lines = Vec::with_capacity(nrows + 1);
                lines.push(render_plain_row(&headers, &widths));
                for row in rows {
                    lines.push(render_plain_row(&row, &widths));
                }
                Ok(lines.join("\n"))
            }
            "simple" => {
                let mut lines = Vec::with_capacity(nrows + 2);
                lines.push(render_plain_row(&headers, &widths));
                lines.push(render_plain_rule(&widths, '-'));
                for row in rows {
                    lines.push(render_plain_row(&row, &widths));
                }
                Ok(lines.join("\n"))
            }
            "psql" => {
                let mut lines = Vec::with_capacity(nrows + 4);
                let border = render_grid_border(&widths, '+', '+', '+', '-');
                lines.push(border.clone());
                lines.push(render_psql_row(&headers, &widths));
                lines.push(render_psql_header_rule(&widths));
                for row in rows {
                    lines.push(render_psql_row(&row, &widths));
                }
                lines.push(border);
                Ok(lines.join("\n"))
            }
            "simple_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '┌', '┬', '┐', '─');
                let row_border = render_grid_border(&widths, '├', '┼', '┤', '─');
                let bottom_border = render_grid_border(&widths, '└', '┴', '┘', '─');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '│', '│'));
                lines.push(row_border.clone());
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '│', '│'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "rounded_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '╭', '┬', '╮', '─');
                let row_border = render_grid_border(&widths, '├', '┼', '┤', '─');
                let bottom_border = render_grid_border(&widths, '╰', '┴', '╯', '─');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '│', '│'));
                lines.push(row_border.clone());
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '│', '│'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "heavy_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '┏', '┳', '┓', '━');
                let row_border = render_grid_border(&widths, '┣', '╋', '┫', '━');
                let bottom_border = render_grid_border(&widths, '┗', '┻', '┛', '━');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '┃', '┃'));
                lines.push(row_border.clone());
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '┃', '┃'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "fancy_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '╒', '╤', '╕', '═');
                let header_border = render_grid_border(&widths, '╞', '╪', '╡', '═');
                let row_border = render_grid_border(&widths, '├', '┼', '┤', '─');
                let bottom_border = render_grid_border(&widths, '╘', '╧', '╛', '═');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '│', '│'));
                lines.push(header_border);
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '│', '│'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "mixed_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '┍', '┯', '┑', '━');
                let header_border = render_grid_border(&widths, '┝', '┿', '┥', '━');
                let row_border = render_grid_border(&widths, '├', '┼', '┤', '─');
                let bottom_border = render_grid_border(&widths, '┕', '┷', '┙', '━');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '│', '│'));
                lines.push(header_border);
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '│', '│'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "double_grid" => {
                let mut lines = Vec::with_capacity(nrows * 2 + 3);
                let top_border = render_grid_border(&widths, '╔', '╦', '╗', '═');
                let row_border = render_grid_border(&widths, '╠', '╬', '╣', '═');
                let bottom_border = render_grid_border(&widths, '╚', '╩', '╝', '═');
                lines.push(top_border);
                lines.push(render_box_row(&headers, &widths, '║', '║'));
                lines.push(row_border.clone());
                for (idx, row) in rows.into_iter().enumerate() {
                    lines.push(render_box_row(&row, &widths, '║', '║'));
                    if idx + 1 != nrows {
                        lines.push(row_border.clone());
                    }
                }
                lines.push(bottom_border);
                Ok(lines.join("\n"))
            }
            "outline" => {
                let mut lines = Vec::with_capacity(nrows + 3);
                let border = render_grid_border(&widths, '+', '+', '+', '-');
                let header_border = render_grid_border(&widths, '+', '+', '+', '=');
                lines.push(border.clone());
                lines.push(render_markdown_row(&headers, &widths));
                lines.push(header_border);
                for row in rows {
                    lines.push(render_markdown_row(&row, &widths));
                }
                lines.push(border);
                Ok(lines.join("\n"))
            }
            "rst" => {
                let mut lines = Vec::with_capacity(nrows + 4);
                let rule = render_plain_rule(&widths, '=');
                lines.push(rule.clone());
                lines.push(render_plain_row(&headers, &widths));
                lines.push(rule.clone());
                for row in rows {
                    lines.push(render_plain_row(&row, &widths));
                }
                lines.push(rule);
                Ok(lines.join("\n"))
            }
            other => Err(FrameError::CompatibilityRejected(format!(
                "unsupported to_markdown tablefmt '{other}'"
            ))),
        }
    }

    /// Randomly sample rows from the DataFrame.
    ///
    /// `n`: number of rows to sample (mutually exclusive with `frac`).
    /// `frac`: fraction of rows to sample.
    /// `replace`: whether to sample with replacement.
    /// `seed`: optional deterministic seed.
    pub fn sample(
        &self,
        n: Option<usize>,
        frac: Option<f64>,
        replace: bool,
        seed: Option<u64>,
    ) -> Result<Self, FrameError> {
        let total = self.len();
        // Per br-frankenpandas-380a0: same frac validation as
        // Series::sample (br-c1db4). Cross-API consistency: pandas
        // raises ValueError on the same invalid frac inputs for both
        // Series.sample and DataFrame.sample.
        if let Some(f) = frac {
            if !f.is_finite() {
                return Err(FrameError::CompatibilityRejected(format!(
                    "sample: frac must be finite, got {f}"
                )));
            }
            if f < 0.0 {
                return Err(FrameError::CompatibilityRejected(format!(
                    "sample: frac must be >= 0, got {f}"
                )));
            }
            if !replace && f > 1.0 {
                return Err(FrameError::CompatibilityRejected(format!(
                    "sample: frac must be <= 1 when replace=false, got {f}"
                )));
            }
        }
        let sample_n = match (n, frac) {
            (Some(count), None) => count,
            (None, Some(f)) => (total as f64 * f).round() as usize,
            (None, None) => 1,
            (Some(_), Some(_)) => {
                return Err(FrameError::CompatibilityRejected(
                    "cannot specify both n and frac".to_string(),
                ));
            }
        };

        if !replace && sample_n > total {
            return Err(FrameError::CompatibilityRejected(format!(
                "cannot sample {sample_n} rows from {total} without replacement"
            )));
        }

        // Simple LCG for deterministic sampling
        let mut rng_state = seed.unwrap_or(42);
        let mut next_rand = || -> usize {
            rng_state = rng_state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1);
            (rng_state >> 33) as usize
        };

        let indices: Vec<usize> = if replace {
            (0..sample_n).map(|_| next_rand() % total).collect()
        } else {
            // Fisher-Yates shuffle on index array, take first sample_n
            let mut pool: Vec<usize> = (0..total).collect();
            for i in 0..sample_n {
                let j = i + (next_rand() % (total - i));
                pool.swap(i, j);
            }
            pool[..sample_n].to_vec()
        };

        // Build result
        let mut result_cols = BTreeMap::new();
        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            // Typed positional gather (see iloc_with_columns).
            result_cols.insert(col_name.clone(), col.take_positions(&indices));
        }

        let new_labels: Vec<IndexLabel> =
            indices.iter().map(|&i| label_at(&self.index, i)).collect();

        // Per br-frankenpandas-omjaw: pandas preserves the index name
        // through sample. Was lost via Index::new without rename_index.
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: Index::new(new_labels).rename_index(self.index.name()),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Weighted sampling of rows.
    ///
    /// Matches `df.sample(n, weights=...)`. The `weights` slice must have the
    /// same length as the DataFrame. Weights are normalized to sum to 1.
    pub fn sample_weights(
        &self,
        n: usize,
        weights: &[f64],
        replace: bool,
        seed: Option<u64>,
    ) -> Result<Self, FrameError> {
        let total = self.len();
        if weights.len() != total {
            return Err(FrameError::LengthMismatch {
                index_len: total,
                column_len: weights.len(),
            });
        }
        if !replace && n > total {
            return Err(FrameError::CompatibilityRejected(format!(
                "cannot sample {n} rows from {total} without replacement"
            )));
        }

        // Per br-frankenpandas-s7o17: pandas raises ValueError on any
        // negative weight (regardless of whether positives dominate the
        // sum). The sum-check below only catches all-zero or negative-sum
        // cases.
        if let Some(neg) = weights.iter().find(|w| **w < 0.0 || w.is_nan()) {
            return Err(FrameError::CompatibilityRejected(format!(
                "sample_weights: weights cannot include negative or NaN values (got {neg})"
            )));
        }
        // Normalize weights to cumulative distribution
        let w_sum: f64 = weights.iter().sum();
        if w_sum <= 0.0 {
            return Err(FrameError::CompatibilityRejected(
                "weights must sum to a positive value".to_string(),
            ));
        }
        let mut cumulative = Vec::with_capacity(total);
        let mut acc = 0.0;
        for &w in weights {
            acc += w / w_sum;
            cumulative.push(acc);
        }

        // LCG for deterministic RNG
        let mut rng_state = seed.unwrap_or(42);
        let mut next_f64 = || -> f64 {
            rng_state = rng_state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1);
            (rng_state >> 11) as f64 / ((1_u64 << 53) as f64)
        };

        let mut indices = Vec::with_capacity(n);
        let mut used = vec![false; total];

        for _ in 0..n {
            let r = next_f64();
            // Binary search the (ascending) cumulative distribution instead of
            // a linear scan: O(log total) vs O(total) per draw. `cumulative` is
            // non-decreasing, and `partition_point(|c| c < r)` returns the first
            // index where `c >= r`, i.e. `r <= c` — exactly what the linear
            // `position(|c| r <= c)` found (bit-identical; `c < r` is the strict
            // negation of `r <= c` for the finite values here). `min(total-1)`
            // reproduces the old `unwrap_or(total - 1)` when `r` exceeds the
            // last cumulative value.
            let idx = cumulative.partition_point(|&c| c < r).min(total - 1);
            if !replace && used[idx] {
                // Find next available
                let mut found = None;
                for offset in 1..total {
                    let candidate = (idx + offset) % total;
                    if !used[candidate] {
                        found = Some(candidate);
                        break;
                    }
                }
                let Some(actual) = found else {
                    break;
                };
                used[actual] = true;
                indices.push(actual);
            } else {
                used[idx] = true;
                indices.push(idx);
            }
        }

        self.take_rows_by_positions(&indices)
    }

    /// Stack: pivot columns into rows (wide-to-long).
    ///
    /// Converts a DataFrame with columns [A, B, ...] into a two-column
    /// DataFrame with a multi-level index (original_index, column_name)
    /// and a single value column. Similar to pandas `DataFrame.stack()`.
    pub fn stack(&self) -> Result<Self, FrameError> {
        let n_rows = self.len();
        let n_cols = self.column_order.len();
        let total = n_rows * n_cols;

        // Hoist the row labels and per-column references out of the nested loop
        // (the old code re-fetched self.columns[col_name] for every (row, col)
        // cell). Composite labels stay format!-per-cell (each is unique — pandas
        // dodges this with a MultiIndex; see the structural note below).
        let labels = self.index.labels();
        let col_refs: Vec<&Column> = self
            .column_order
            .iter()
            .map(|name| &self.columns[name])
            .collect();

        // Build the n*m composite labels into ONE contiguous Utf8 buffer +
        // offsets, instead of n*m separate `IndexLabel::Utf8(String)` allocations
        // (the structural composite-string cost noted above — n*m String allocs
        // dominated stack at 0.32x vs pandas). The row part is formatted ONCE per
        // row and reused across the m columns. The composite bytes are identical
        // to the old `format!("{row}|{col}")` per cell, and
        // `Index::from_utf8_contiguous` yields the same `labels()` — bit-identical
        // output (still the flat composite-string model, NO MultiIndex change).
        // The n*m composite-byte assembly is CPU-bound (30M+ extend/push ops + a
        // per-row label format, NOT the ~120MB raw write — 120MB/10GB/s is ~12ms), and
        // each row's composite bytes are independent, so build it in PARALLEL: each
        // worker fills its own LOCAL byte buffer (one growing Vec per thread — no
        // shared-allocator contention, the reason to_dict-parallel lost), then the
        // chunk buffers are concatenated in row order with offsets shifted by the
        // running byte base. Bit-identical to the serial build (same rows, same column
        // order, same bytes, same offsets).
        let col_names: &[String] = &self.column_order;
        let build_label_range = |lo: usize, hi: usize| -> (Vec<u8>, Vec<usize>) {
            let mut bytes: Vec<u8> = Vec::with_capacity((hi - lo) * n_cols * 8);
            let mut offs: Vec<usize> = Vec::with_capacity((hi - lo) * n_cols);
            let mut row_part = String::new();
            for label in &labels[lo..hi] {
                row_part.clear();
                match label {
                    IndexLabel::Int64(v) => row_part.push_str(&v.to_string()),
                    IndexLabel::Utf8(v) => row_part.push_str(v),
                    IndexLabel::Timedelta64(ns) => row_part.push_str(&Timedelta::format(*ns)),
                    IndexLabel::Datetime64(ns) => row_part.push_str(&format_datetime_ns(*ns)),
                    f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => {
                        row_part.push_str(&format!("{f}"))
                    }
                    l @ IndexLabel::Null(_) => row_part.push_str(&format!("{l}")),
                }
                for col_name in col_names {
                    bytes.extend_from_slice(row_part.as_bytes());
                    bytes.push(b'|');
                    bytes.extend_from_slice(col_name.as_bytes());
                    offs.push(bytes.len());
                }
            }
            (bytes, offs)
        };
        const STACK_LABEL_PAR_MIN_ROWS: usize = 50_000;
        const STACK_LABEL_PAR_MIN_PER_WORKER: usize = 16_384;
        let label_workers = if n_rows >= STACK_LABEL_PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism()
                .min(16)
                .min(n_rows / STACK_LABEL_PAR_MIN_PER_WORKER)
                .max(1)
        } else {
            1
        };
        let (label_bytes, label_offsets) = if label_workers >= 2 {
            let chunk = n_rows.div_ceil(label_workers);
            let build = &build_label_range;
            let parts: Vec<(Vec<u8>, Vec<usize>)> = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(label_workers);
                let mut start = 0;
                while start < n_rows {
                    let end = (start + chunk).min(n_rows);
                    handles.push(scope.spawn(move || build(start, end)));
                    start = end;
                }
                handles
                    .into_iter()
                    .map(|h| h.join().expect("stack label thread"))
                    .collect()
            });
            let total_bytes: usize = parts.iter().map(|(b, _)| b.len()).sum();
            let mut label_bytes: Vec<u8> = Vec::with_capacity(total_bytes);
            let mut label_offsets: Vec<usize> = Vec::with_capacity(total + 1);
            label_offsets.push(0);
            let mut base = 0usize;
            for (b, offs) in &parts {
                for &o in offs {
                    label_offsets.push(base + o);
                }
                base += b.len();
                label_bytes.extend_from_slice(b);
            }
            (label_bytes, label_offsets)
        } else {
            let (bytes, offs) = build_label_range(0, n_rows);
            let mut label_offsets: Vec<usize> = Vec::with_capacity(total + 1);
            label_offsets.push(0);
            label_offsets.extend_from_slice(&offs);
            (bytes, label_offsets)
        };

        // Value column, row-major (cell order = for each row, each col). Typed
        // NUMERIC fast path: when every column is a dense all-valid numeric slice,
        // gather row-major into a raw buffer (i64→f64 when any column is Float64,
        // matching pandas' promotion; else all-i64) and MOVE out — no per-cell
        // Scalar clone/cast. Previously only all-f64 was typed; MIXED numeric and
        // all-i64 fell to the Vec<Scalar> path (mixed stack was 0.62× pandas).
        // Bit-identical: `common_dtype`/`from_values` promotes numerics to Float64
        // iff any is Float64 (else Int64), and `i as f64` == its Int64→Float64 cast.
        enum NumSlice<'a> {
            F64(&'a [f64]),
            I64(&'a [i64]),
        }
        let numeric_cols: Option<Vec<NumSlice>> = col_refs
            .iter()
            .map(|c| {
                if let Some(s) = c.as_f64_slice() {
                    Some(NumSlice::F64(s))
                } else {
                    c.as_i64_slice().map(NumSlice::I64)
                }
            })
            .collect();
        // Parallelize the row-major value gather the same way as the label build: the
        // strided per-cell reads (`x[row]` across m columns) are memory-latency-bound,
        // which more memory-level parallelism across workers hides; each worker gathers
        // its row range into a LOCAL buffer, then concat in row order. Bit-identical
        // (same cell order). Reuses the label build's worker count / gate.
        let value_col = if let Some(slices) = numeric_cols {
            if slices.iter().any(|s| matches!(s, NumSlice::F64(_))) {
                let build_f64 = |lo: usize, hi: usize| -> Vec<f64> {
                    let mut v: Vec<f64> = Vec::with_capacity((hi - lo) * n_cols);
                    for row in lo..hi {
                        for s in &slices {
                            v.push(match s {
                                NumSlice::F64(x) => x[row],
                                NumSlice::I64(x) => x[row] as f64,
                            });
                        }
                    }
                    v
                };
                let vals: Vec<f64> = if label_workers >= 2 {
                    let chunk = n_rows.div_ceil(label_workers);
                    let build = &build_f64;
                    let parts: Vec<Vec<f64>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(label_workers);
                        let mut start = 0;
                        while start < n_rows {
                            let end = (start + chunk).min(n_rows);
                            handles.push(scope.spawn(move || build(start, end)));
                            start = end;
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("stack value thread"))
                            .collect()
                    });
                    let mut vals = Vec::with_capacity(total);
                    for p in &parts {
                        vals.extend_from_slice(p);
                    }
                    vals
                } else {
                    build_f64(0, n_rows)
                };
                Column::from_f64_values_owned(vals)
            } else {
                let build_i64 = |lo: usize, hi: usize| -> Vec<i64> {
                    let mut v: Vec<i64> = Vec::with_capacity((hi - lo) * n_cols);
                    for row in lo..hi {
                        for s in &slices {
                            if let NumSlice::I64(x) = s {
                                v.push(x[row]);
                            }
                        }
                    }
                    v
                };
                let vals: Vec<i64> = if label_workers >= 2 {
                    let chunk = n_rows.div_ceil(label_workers);
                    let build = &build_i64;
                    let parts: Vec<Vec<i64>> = std::thread::scope(|scope| {
                        let mut handles = Vec::with_capacity(label_workers);
                        let mut start = 0;
                        while start < n_rows {
                            let end = (start + chunk).min(n_rows);
                            handles.push(scope.spawn(move || build(start, end)));
                            start = end;
                        }
                        handles
                            .into_iter()
                            .map(|h| h.join().expect("stack value thread"))
                            .collect()
                    });
                    let mut vals = Vec::with_capacity(total);
                    for p in &parts {
                        vals.extend_from_slice(p);
                    }
                    vals
                } else {
                    build_i64(0, n_rows)
                };
                Column::from_i64_values_owned(vals)
            }
        } else {
            let mut values = Vec::with_capacity(total);
            for row in 0..n_rows {
                for c in &col_refs {
                    values.push(c.values()[row].clone());
                }
            }
            Column::from_values(values)?
        };
        let mut cols = BTreeMap::new();
        cols.insert("value".to_string(), value_col);

        // Per br-frankenpandas-ecl0a: preserve the source row-index name.
        // pandas's stack returns a MultiIndex (level0 = original rows,
        // level1 = original columns); our flat-composite model can still
        // preserve the source axis name on the composite Index.
        Ok(Self {
            columns: cols.into(),
            column_order: vec!["value".to_string()].into(),
            index: Index::from_utf8_contiguous(
                std::sync::Arc::from(label_bytes),
                std::sync::Arc::from(label_offsets),
            )
            .rename_index(self.index.name()),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Unstack: pivot rows into columns (long-to-wide).
    ///
    /// Assumes the index contains composite labels in "row|col" format
    /// (as produced by `stack()`). Produces a DataFrame with unique row
    /// keys as index and unique column keys as columns.
    pub fn unstack(&self) -> Result<Self, FrameError> {
        if self.column_order.len() != 1 {
            return Err(FrameError::CompatibilityRejected(
                "unstack requires exactly one value column".to_string(),
            ));
        }
        let val_col_name = &self.column_order[0];
        let val_col = &self.columns[val_col_name];

        // Parse composite keys
        let mut row_order: Vec<String> = Vec::new();
        let mut row_set = std::collections::HashSet::new();
        let mut col_order: Vec<String> = Vec::new();
        let mut col_set = std::collections::HashSet::new();
        let mut entries: Vec<(String, String, Scalar)> = Vec::new();

        for (i, label) in self.index.labels().iter().enumerate() {
            let label_str = match label {
                IndexLabel::Utf8(s) => s.clone(),
                IndexLabel::Int64(v) => v.to_string(),
                IndexLabel::Timedelta64(ns) => Timedelta::format(*ns),
                IndexLabel::Datetime64(ns) => format_datetime_ns(*ns),
                f @ (IndexLabel::Float64(_) | IndexLabel::Bool(_)) => f.to_string(),
                IndexLabel::Null(_) => label.to_string(),
            };
            let sep_pos = label_str.rfind('|').ok_or_else(|| {
                FrameError::CompatibilityRejected(format!(
                    "unstack: index label '{label_str}' missing '|' separator"
                ))
            })?;
            let row_key = label_str[..sep_pos].to_string();
            let col_key = label_str[sep_pos + 1..].to_string();
            if row_set.insert(row_key.clone()) {
                row_order.push(row_key.clone());
            }
            if col_set.insert(col_key.clone()) {
                col_order.push(col_key.clone());
            }
            entries.push((row_key, col_key, val_col.values()[i].clone()));
        }

        // Build lookup
        let mut lookup: std::collections::HashMap<(String, String), Scalar> =
            std::collections::HashMap::new();
        for (rk, ck, val) in entries {
            lookup.insert((rk, ck), val);
        }

        // Build result columns
        let mut result_cols = BTreeMap::new();
        for ck in &col_order {
            let mut vals = Vec::with_capacity(row_order.len());
            for rk in &row_order {
                if let Some(val) = lookup.get(&(rk.clone(), ck.clone())) {
                    vals.push(val.clone());
                } else {
                    vals.push(Scalar::Null(NullKind::NaN));
                }
            }
            result_cols.insert(ck.clone(), Column::from_values(vals)?);
        }

        let new_labels: Vec<IndexLabel> = row_order
            .iter()
            .map(|s| {
                if let Ok(i) = s.parse::<i64>() {
                    IndexLabel::Int64(i)
                } else {
                    IndexLabel::Utf8(s.clone())
                }
            })
            .collect();

        // Per br-frankenpandas-yh08x: preserve source index name through unstack.
        Ok(Self {
            columns: result_cols.into(),
            column_order: col_order.into(),
            index: Index::new(new_labels).rename_index(self.index.name()),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Apply a closure to each column (axis=0) or each row (axis=1).
    ///
    /// Unlike the string-based `apply()`, this takes a Rust closure.
    pub fn apply_fn<F>(&self, func: F, axis: usize) -> Result<Self, FrameError>
    where
        F: Fn(&[Scalar]) -> Scalar,
    {
        if axis == 0 {
            // Column-wise: apply func to each column's values
            let mut labels = Vec::new();
            let mut values = Vec::new();
            for name in &self.column_order {
                let col = &self.columns[name];
                labels.push(IndexLabel::Utf8(name.clone()));
                values.push(func(col.values()));
            }
            let s = Series::from_values("result", labels, values)?;
            // Return as single-column DataFrame
            let mut cols = BTreeMap::new();
            cols.insert("result".to_string(), s.column().clone());
            Ok(Self {
                columns: cols.into(),
                column_order: vec!["result".to_string()].into(),
                index: s.index().clone(),
                column_multiindex: None,
                row_multiindex: None,
                allows_duplicate_labels: self.allows_duplicate_labels,
            })
        } else {
            // Row-wise: apply func to each row. Hoist the per-cell
            // columns[name].values() (n*m BTreeMap lookups) to once-per-column.
            let col_values: Vec<&[Scalar]> = self
                .column_order
                .iter()
                .map(|name| self.columns[name].values())
                .collect();
            // Reuse ONE row buffer across all rows (br-frankenpandas-applyrow-reuse):
            // the old form `collect()`-ed a fresh `Vec<Scalar>` per row — n heap
            // allocations (+ n frees) just to hand `func` a `&[Scalar]`. Clear+extend a
            // single buffer instead; `func` sees the identical slice contents each row,
            // so the result is unchanged. Only the transient per-row Vec is elided.
            let mut values = Vec::with_capacity(self.len());
            let mut row_vals: Vec<Scalar> = Vec::with_capacity(col_values.len());
            for row_idx in 0..self.len() {
                row_vals.clear();
                row_vals.extend(col_values.iter().map(|vals| vals[row_idx].clone()));
                values.push(func(&row_vals));
            }
            let s = Series::from_values("result", self.index.labels().to_vec(), values)?;
            let mut cols = BTreeMap::new();
            cols.insert("result".to_string(), s.column().clone());
            Ok(Self {
                columns: cols.into(),
                column_order: vec!["result".to_string()].into(),
                index: self.index.clone(),
                column_multiindex: None,
                row_multiindex: None,
                allows_duplicate_labels: self.allows_duplicate_labels,
            })
        }
    }

    /// Row-wise apply with `result_type` control.
    ///
    /// Matches `pd.DataFrame.apply(func, axis=1, result_type=...)`.
    ///
    /// - `"reduce"`: Each row produces a single scalar → returns a Series (default).
    /// - `"expand"`: Each row produces a Vec of scalars → columns of the output DataFrame.
    /// - `"broadcast"`: Each row produces a scalar → broadcast to all columns, preserving shape.
    pub fn apply_with_result_type<F>(&self, func: F, result_type: &str) -> Result<Self, FrameError>
    where
        F: Fn(&[Scalar]) -> Vec<Scalar>,
    {
        match result_type {
            "expand" => {
                // Each row's result becomes a row of the output DataFrame.
                // Number of columns is determined by the first row's result length.
                let mut all_rows: Vec<Vec<Scalar>> = Vec::with_capacity(self.len());
                for row_idx in 0..self.len() {
                    let row_vals: Vec<Scalar> = self
                        .column_order
                        .iter()
                        .map(|name| self.columns[name].values()[row_idx].clone())
                        .collect();
                    all_rows.push(func(&row_vals));
                }
                let n_cols = all_rows.first().map_or(0, Vec::len);
                let mut cols = BTreeMap::new();
                let mut col_order = Vec::with_capacity(n_cols);
                for col_idx in 0..n_cols {
                    let col_name = col_idx.to_string();
                    let values: Vec<Scalar> = all_rows
                        .iter()
                        .map(|row| {
                            row.get(col_idx)
                                .cloned()
                                .unwrap_or(Scalar::Null(NullKind::NaN))
                        })
                        .collect();
                    cols.insert(col_name.clone(), Column::from_values(values)?);
                    col_order.push(col_name);
                }
                Ok(Self {
                    columns: cols.into(),
                    column_order: col_order.into(),
                    index: self.index.clone(),
                    column_multiindex: None,
                    row_multiindex: None,
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
            "broadcast" => {
                // Each row produces values that are broadcast to all columns.
                // Result must have same number of elements as columns.
                let mut all_rows: Vec<Vec<Scalar>> = Vec::with_capacity(self.len());
                for row_idx in 0..self.len() {
                    let row_vals: Vec<Scalar> = self
                        .column_order
                        .iter()
                        .map(|name| self.columns[name].values()[row_idx].clone())
                        .collect();
                    let result = func(&row_vals);
                    if result.len() == 1 {
                        // Broadcast scalar to all columns
                        all_rows.push(
                            std::iter::repeat_n(
                                result.into_iter().next().unwrap(),
                                self.column_order.len(),
                            )
                            .collect(),
                        );
                    } else {
                        all_rows.push(result);
                    }
                }
                let mut cols = BTreeMap::new();
                for (col_idx, col_name) in self.column_order.iter().enumerate() {
                    let values: Vec<Scalar> = all_rows
                        .iter()
                        .map(|row| {
                            row.get(col_idx)
                                .cloned()
                                .unwrap_or(Scalar::Null(NullKind::NaN))
                        })
                        .collect();
                    cols.insert(col_name.clone(), Column::from_values(values)?);
                }
                Ok(Self {
                    columns: cols.into(),
                    column_order: self.column_order.clone(),
                    index: self.index.clone(),
                    column_multiindex: self.column_multiindex.clone(),
                    row_multiindex: self.row_multiindex.clone(),
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
            _ => {
                // Default: each row returns a single scalar → Series wrapped in 1-col DataFrame.
                let mut values = Vec::with_capacity(self.len());
                for row_idx in 0..self.len() {
                    let row_vals: Vec<Scalar> = self
                        .column_order
                        .iter()
                        .map(|name| self.columns[name].values()[row_idx].clone())
                        .collect();
                    let result = func(&row_vals);
                    values.push(
                        result
                            .into_iter()
                            .next()
                            .unwrap_or(Scalar::Null(NullKind::NaN)),
                    );
                }
                let s = Series::from_values("result", self.index.labels().to_vec(), values)?;
                let mut cols = BTreeMap::new();
                cols.insert("result".to_string(), s.column().clone());
                Ok(Self {
                    columns: cols.into(),
                    column_order: vec!["result".to_string()].into(),
                    index: self.index.clone(),
                    column_multiindex: None,
                    row_multiindex: None,
                    allows_duplicate_labels: self.allows_duplicate_labels,
                })
            }
        }
    }

    /// Row-wise apply returning a Series (one value per row).
    ///
    /// Convenience wrapper for `apply_fn(func, 1)` that directly returns
    /// a Series instead of a single-column DataFrame.
    pub fn apply_row<F>(&self, name: &str, func: F) -> Result<Series, FrameError>
    where
        F: Fn(&[Scalar]) -> Scalar,
    {
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let row_vals: Vec<Scalar> = self
                .column_order
                .iter()
                .map(|col_name| self.columns[col_name].values()[row_idx].clone())
                .collect();
            values.push(func(&row_vals));
        }
        // Per br-frankenpandas-82yra: pandas df row-wise apply preserves
        // df.index.name.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new(name, index, column)
    }

    /// Row-wise apply with failable closure returning a Series.
    ///
    /// Like `apply_row` but the closure can return errors.
    pub fn apply_row_fn<F>(&self, name: &str, func: F) -> Result<Series, FrameError>
    where
        F: Fn(&[Scalar]) -> Result<Scalar, FrameError>,
    {
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let row_vals: Vec<Scalar> = self
                .column_order
                .iter()
                .map(|col_name| self.columns[col_name].values()[row_idx].clone())
                .collect();
            values.push(func(&row_vals)?);
        }
        // Per br-frankenpandas-jye65: pandas df row-wise apply preserves
        // df.index.name. Sister to apply_row fix.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new(name, index, column)
    }

    /// Simple pivot: reshape long to wide using column values.
    ///
    /// Matches `pd.DataFrame.pivot(index, columns, values)`.
    /// Unlike `pivot_table`, no aggregation is performed; duplicate entries error.
    pub fn pivot(
        &self,
        index_col: &str,
        columns_col: &str,
        values_col: &str,
    ) -> Result<Self, FrameError> {
        let idx_vals = self.columns.get(index_col).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("pivot: column '{index_col}' not found"))
        })?;
        let col_vals = self.columns.get(columns_col).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("pivot: column '{columns_col}' not found"))
        })?;
        let val_vals = self.columns.get(values_col).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("pivot: column '{values_col}' not found"))
        })?;

        // Typed Int64-keys + Float64-values fast path (br-frankenpandas-pvtdk):
        // the generic path below calls `.values()` on all three columns, each
        // materializing a 1M-element `Vec<Scalar>` (3M boxed scalars @1M rows),
        // and hashes a `ScalarKey` per row for the row/col position maps + cell
        // scatter. When the index and columns columns are all-valid Int64
        // (`as_i64_slice`) and the values column is all-valid no-NaN Float64
        // (`as_f64_slice`), every key/value is read straight off the typed slice
        // and probed with raw `i64` keys — no Scalar materialization, no
        // ScalarKey hashing. Bit-identical to the generic path: first-seen unique
        // i64 keys sorted ascending match `scalar_key_cmp` on Int64; row labels
        // are `IndexLabel::Int64(k)`, column labels are the decimal string the
        // generic `format!("{v:?}")`+strip produced; present cells carry
        // `Scalar::Float64(slice[pos])` (== the original) and missing cells the
        // same `Null(NaN)`; an all-present output column uses the all-valid
        // `from_f64_values_owned` (== `from_values` for no-NaN Float64). pandas
        // pivot errors on duplicate (row, col) pairs identically.
        if let (Some(iv), Some(cv), Some(vv)) = (
            idx_vals.as_i64_slice(),
            col_vals.as_i64_slice(),
            val_vals.as_f64_slice(),
        ) {
            return self.pivot_int64_keys_f64_values(iv, cv, vv, index_col);
        }

        // Collect unique index and column values in order of appearance
        let mut row_keys: Vec<ScalarKey<'_>> = Vec::new();
        let mut row_labels: Vec<IndexLabel> = Vec::new();
        let mut seen_rows: FxHashSet<ScalarKey<'_>> = FxHashSet::default();
        for v in idx_vals.values() {
            let key = scalar_key_allow_missing(v);
            if seen_rows.insert(key) {
                let label = match v {
                    Scalar::Utf8(s) => s.as_str().into(),
                    Scalar::Int64(n) => (*n).into(),
                    other => format!("{other:?}").as_str().into(),
                };
                row_keys.push(key);
                row_labels.push(label);
            }
        }

        let mut col_keys: Vec<ScalarKey<'_>> = Vec::new();
        let mut col_labels: Vec<String> = Vec::new();
        let mut seen_cols: FxHashSet<ScalarKey<'_>> = FxHashSet::default();
        for v in col_vals.values() {
            let key = scalar_key_allow_missing(v);
            if seen_cols.insert(key) {
                let raw = format!("{v:?}");
                let clean_name = raw
                    .strip_prefix("Utf8(\"")
                    .and_then(|s| s.strip_suffix("\")"))
                    .or_else(|| raw.strip_prefix("Int64(").and_then(|s| s.strip_suffix(")")))
                    .or_else(|| {
                        raw.strip_prefix("Float64(")
                            .and_then(|s| s.strip_suffix(")"))
                    })
                    .unwrap_or(raw.as_str());
                col_keys.push(key);
                col_labels.push(clean_name.to_string());
            }
        }

        // pandas pivot sorts BOTH axes ascending with nulls last, exactly
        // like pivot_table's sort=True default (br-frankenpandas-r0t9l,
        // verified live 2.2.3: rows ['z','a'] -> ['a','z']). Co-sort each
        // axis's first-seen (key, label) pairs with the same typed
        // comparator; the stable sort keeps first-seen order for
        // cross-type ties.
        let mut row_pairs: Vec<(ScalarKey<'_>, IndexLabel)> =
            row_keys.into_iter().zip(row_labels).collect();
        row_pairs.sort_by(|a, b| scalar_key_cmp(&a.0, &b.0));
        let (row_keys, row_labels): (Vec<_>, Vec<_>) = row_pairs.into_iter().unzip();
        let mut col_pairs: Vec<(ScalarKey<'_>, String)> =
            col_keys.into_iter().zip(col_labels).collect();
        col_pairs.sort_by(|a, b| scalar_key_cmp(&a.0, &b.0));
        let (col_keys, col_labels): (Vec<_>, Vec<_>) = col_pairs.into_iter().unzip();

        // Build a map of (row_key, col_key) -> value. FxHashMap (not std
        // SipHash) for the per-row scatter AND the per-output-cell lookups
        // below; hoist the Scalar slices out of the per-row loop (cf zngxi /
        // pivot_table). Bit-identical: output order is set by the sorted
        // row_keys/col_keys, cells is only probed by get/contains.
        let iv = idx_vals.values();
        let cv = col_vals.values();
        let vv = val_vals.values();
        let nrows = row_keys.len();
        let ncols = col_keys.len();
        // Map each (already-sorted) row/col key to its output position, then build
        // a DENSE col-major grid (cell -> source row index, sentinel u32::MAX) when
        // bounded — direct indexing + sequential per-column output replaces the
        // per-cell FxHashMap<(ScalarKey,ScalarKey),_> whose PAIR hash + cache miss
        // (1M inserts + nrows*ncols lookups) was 0.27x@1M (5x worse than unstack's
        // (usize,usize) map). Sparse grids fall back to the pair map. Bit-identical:
        // same sorted order, same first-write/duplicate-error, same cell values.
        let mut row_ri_of: FxHashMap<ScalarKey<'_>, u32> = FxHashMap::default();
        for (ri, rk) in row_keys.iter().enumerate() {
            row_ri_of.insert(*rk, ri as u32);
        }
        let mut col_ci_of: FxHashMap<ScalarKey<'_>, u32> = FxHashMap::default();
        for (ci, ck) in col_keys.iter().enumerate() {
            col_ci_of.insert(*ck, ci as u32);
        }
        const NONE_POS: u32 = u32::MAX;
        let nlen = self.len();
        let dup_err = || {
            FrameError::CompatibilityRejected(
                "pivot: duplicate entries, use pivot_table for aggregation".to_owned(),
            )
        };
        let grid_cells = nrows.checked_mul(ncols);
        let use_grid = nlen < NONE_POS as usize
            && grid_cells.is_some_and(|g| g <= nlen.saturating_mul(2).max(1 << 16));
        let mut grid: Vec<u32> = Vec::new();
        let mut cells: FxHashMap<(ScalarKey<'_>, ScalarKey<'_>), u32> = FxHashMap::default();
        if use_grid {
            grid = vec![NONE_POS; grid_cells.unwrap()];
            for i in 0..nlen {
                let ri = row_ri_of[&scalar_key_allow_missing(&iv[i])] as usize;
                let ci = col_ci_of[&scalar_key_allow_missing(&cv[i])] as usize;
                let idx = ci * nrows + ri;
                if grid[idx] != NONE_POS {
                    return Err(dup_err());
                }
                grid[idx] = i as u32;
            }
        } else {
            for i in 0..nlen {
                let rk = scalar_key_allow_missing(&iv[i]);
                let ck = scalar_key_allow_missing(&cv[i]);
                if cells.insert((rk, ck), i as u32).is_some() {
                    return Err(dup_err());
                }
            }
        }

        // Build output columns
        let mut data = Vec::new();
        for (ci, (ck, label)) in col_keys.iter().zip(col_labels.iter()).enumerate() {
            let mut col_data = Vec::with_capacity(nrows);
            for (ri, rk) in row_keys.iter().enumerate() {
                let pos = if use_grid {
                    let p = grid[ci * nrows + ri];
                    (p != NONE_POS).then_some(p)
                } else {
                    cells.get(&(*rk, *ck)).copied()
                };
                let val = pos
                    .map(|k| vv[k as usize].clone())
                    .unwrap_or(Scalar::Null(NullKind::NaN));
                col_data.push(val);
            }
            data.push((label.clone(), col_data));
        }

        let column_order: Vec<String> = data.iter().map(|(n, _)| n.clone()).collect();
        let mut columns = BTreeMap::new();
        for (name, vals) in data {
            columns.insert(name, Column::from_values(vals)?);
        }

        // Per br-frankenpandas-xb0ra: pandas sets the result's index.name
        // to the name of the source column used as the pivot index.
        let index = Index::new(row_labels).rename_index(Some(index_col));
        Ok(Self {
            index,
            column_order: column_order.into(),
            columns: columns.into(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Typed pivot for all-valid `Int64` index/columns keys + all-valid no-NaN
    /// `Float64` values. See the gate and bit-identity argument in [`Self::pivot`].
    fn pivot_int64_keys_f64_values(
        &self,
        iv: &[i64],
        cv: &[i64],
        vv: &[f64],
        index_col: &str,
    ) -> Result<Self, FrameError> {
        let nlen = iv.len();

        // First-seen unique row/col keys, then sort ascending (pandas pivot
        // sorts both axes; `scalar_key_cmp` on Int64 == numeric i64 order, and
        // the keys are distinct so stable vs unstable is irrelevant).
        let mut seen_rows: FxHashSet<i64> = FxHashSet::default();
        let mut row_keys: Vec<i64> = Vec::new();
        for &v in iv {
            if seen_rows.insert(v) {
                row_keys.push(v);
            }
        }
        row_keys.sort_unstable();
        let mut seen_cols: FxHashSet<i64> = FxHashSet::default();
        let mut col_keys: Vec<i64> = Vec::new();
        for &v in cv {
            if seen_cols.insert(v) {
                col_keys.push(v);
            }
        }
        col_keys.sort_unstable();

        let nrows = row_keys.len();
        let ncols = col_keys.len();

        let mut row_pos: FxHashMap<i64, u32> = FxHashMap::default();
        for (ri, &rk) in row_keys.iter().enumerate() {
            row_pos.insert(rk, ri as u32);
        }
        let mut col_pos: FxHashMap<i64, u32> = FxHashMap::default();
        for (ci, &ck) in col_keys.iter().enumerate() {
            col_pos.insert(ck, ci as u32);
        }

        const NONE_POS: u32 = u32::MAX;
        let dup_err = || {
            FrameError::CompatibilityRejected(
                "pivot: duplicate entries, use pivot_table for aggregation".to_owned(),
            )
        };

        // Dense col-major grid of source row indices (cell -> i, sentinel) when
        // bounded; else an (output-row, output-col)-keyed map. Mirrors the gate
        // and duplicate-detection of the generic path.
        let grid_cells = nrows.checked_mul(ncols);
        let use_grid = nlen < NONE_POS as usize
            && grid_cells.is_some_and(|g| g <= nlen.saturating_mul(2).max(1 << 16));
        let mut grid: Vec<u32> = Vec::new();
        let mut cells: FxHashMap<(u32, u32), u32> = FxHashMap::default();
        if use_grid {
            grid = vec![NONE_POS; grid_cells.unwrap()];
            for i in 0..nlen {
                let ri = row_pos[&iv[i]] as usize;
                let ci = col_pos[&cv[i]] as usize;
                let cell = ci * nrows + ri;
                if grid[cell] != NONE_POS {
                    return Err(dup_err());
                }
                grid[cell] = i as u32;
            }
        } else {
            for i in 0..nlen {
                let ri = row_pos[&iv[i]];
                let ci = col_pos[&cv[i]];
                if cells.insert((ri, ci), i as u32).is_some() {
                    return Err(dup_err());
                }
            }
        }

        // Build output columns: a fully-present column moves a typed Vec<f64> in
        // (all-valid `from_f64_values_owned` == `from_values` for no-NaN Float64);
        // a column with gaps takes the generic Scalar path with the same
        // `Null(NaN)` fill. `vv` is all-valid no-NaN, so a NaN in `buf` is always
        // a true missing cell.
        let mut column_order: Vec<String> = Vec::with_capacity(ncols);
        let mut columns: BTreeMap<String, Column> = BTreeMap::new();
        let mut buf = vec![0.0_f64; nrows];
        for ci in 0..ncols {
            let mut any_missing = false;
            for ri in 0..nrows {
                let pos = if use_grid {
                    grid[ci * nrows + ri]
                } else {
                    cells
                        .get(&(ri as u32, ci as u32))
                        .copied()
                        .unwrap_or(NONE_POS)
                };
                if pos == NONE_POS {
                    any_missing = true;
                    buf[ri] = f64::NAN;
                } else {
                    buf[ri] = vv[pos as usize];
                }
            }
            let label = col_keys[ci].to_string();
            let column = if any_missing {
                let vals: Vec<Scalar> = buf
                    .iter()
                    .map(|&x| {
                        if x.is_nan() {
                            Scalar::Null(NullKind::NaN)
                        } else {
                            Scalar::Float64(x)
                        }
                    })
                    .collect();
                Column::from_values(vals)?
            } else {
                Column::from_f64_values_owned(buf.clone())
            };
            column_order.push(label.clone());
            columns.insert(label, column);
        }

        let row_labels: Vec<IndexLabel> = row_keys.iter().map(|&k| IndexLabel::Int64(k)).collect();
        let index = Index::new(row_labels).rename_index(Some(index_col));
        Ok(Self {
            index,
            column_order: column_order.into(),
            columns: columns.into(),
            column_multiindex: None,
            row_multiindex: None,
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Squeeze a single-column DataFrame to a Series, or single-row to a Series.
    ///
    /// Matches `pd.DataFrame.squeeze(axis)`.
    /// - axis=1 (default): if single column, return as Series
    /// - axis=0: if single row, return as Series
    ///
    /// # Panics
    ///
    /// Panics if the squeezed output cannot be represented as a valid Series
    /// because the DataFrame's internal index or column metadata has already
    /// diverged from its column storage.
    #[allow(clippy::result_large_err)]
    pub fn squeeze_to_series(&self, axis: usize) -> Result<Series, Self> {
        if axis == 1 && self.column_order.len() == 1 {
            let col_name = &self.column_order[0];
            let col = &self.columns[col_name];
            Ok(Series::new(col_name.clone(), self.index.clone(), col.clone()).unwrap())
        } else if axis == 0 && self.len() == 1 {
            let labels: Vec<IndexLabel> = self
                .column_order
                .iter()
                .map(|n| n.as_str().into())
                .collect();
            let values: Vec<Scalar> = self
                .column_order
                .iter()
                .map(|n| self.columns[n].values()[0].clone())
                .collect();
            // Per br-frankenpandas-6xd34: pandas uses the row's index label
            // as the resulting Series name when squeezing axis=0.
            // Per br-frankenpandas-g5168: guard the labels[0] access — len()
            // checks the column length; if labels is shorter (corrupted
            // state), surface a recoverable Err via the Result branch.
            let series_name = self
                .index
                .labels()
                .first()
                .map(|l| l.to_string())
                .unwrap_or_default();
            Ok(Series::from_values(series_name, labels, values).unwrap())
        } else {
            Err(self.clone())
        }
    }

    /// Approximate memory usage per column.
    ///
    /// Matches `pd.DataFrame.memory_usage()`. Returns a Series with column
    /// names as index and byte estimates as values. Includes the index.
    pub fn memory_usage(&self) -> Result<Series, FrameError> {
        self.memory_usage_with_options(true, false)
    }

    /// Matches `pd.DataFrame.memory_usage(index=..., deep=...)`.
    pub fn memory_usage_with_options(&self, index: bool, deep: bool) -> Result<Series, FrameError> {
        let mut labels = Vec::with_capacity(self.column_order.len() + usize::from(index));
        let mut values = Vec::with_capacity(self.column_order.len() + usize::from(index));

        if index {
            let index_bytes = index_memory_usage_bytes_with_deep(&self.index, deep);
            labels.push(IndexLabel::from("Index"));
            values.push(Scalar::Int64(index_bytes as i64));
        }

        for col_name in &self.column_order {
            let col = &self.columns[col_name];
            let bytes = column_memory_usage_bytes_with_deep(col, deep);
            labels.push(IndexLabel::from(col_name.as_str()));
            values.push(Scalar::Int64(bytes as i64));
        }

        Series::from_values("memory_usage".to_owned(), labels, values)
    }

    // ── DataFrame column-wise aggregation stats ──

    /// Count of unique non-null values per column.
    ///
    /// Matches `pd.DataFrame.nunique()`.
    pub fn nunique(&self) -> Result<Series, FrameError> {
        self.nunique_with_dropna(true)
    }

    /// Count of unique values per column with explicit null counting control.
    ///
    /// Matches `pd.DataFrame.nunique(dropna=...)`.
    pub fn nunique_with_dropna(&self, dropna: bool) -> Result<Series, FrameError> {
        // Per br-frankenpandas-6ce89: per-column HashMap-based dedup
        // (O(n) per column). Each column is homogeneous in dtype
        // (Column::new validation), so ScalarKey equivalence matches
        // grouped_scalar_eq for in-column pairs. The cross-dtype helper
        // distinct_values is still used by DataFrame::nunique_axis1.
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|n| n.as_str().into())
            .collect();
        // Column-parallel (br-frankenpandas-nunique-par): each column's distinct
        // count is independent, so spread the columns across par_map_columns
        // scope workers. Bit-identical — identical per-column typed/hashed arms,
        // reassembled in column_order.
        let values: Vec<Scalar> = self.par_map_columns(&self.column_order, |n| {
            let col = &self.columns[n];
            // Typed Float64 fast path (br-frankenpandas-zl16n): dedup the
            // present values straight from the f64 + validity slices into an
            // Fx-hashed set of normalized bits, skipping the col.values()
            // Vec<Scalar> materialization and the ScalarKey SipHash map.
            // Bit-identical to scalar_key_skip_missing's Float64 arm: a present
            // slot is validity-set AND datum-not-NaN (Float64(NaN)/Null are
            // missing), keyed by FloatBits of the -0.0->+0.0 normalized datum;
            // every other slot is a missing value (one shared bucket, counted
            // iff !dropna).
            if let Some((data, validity)) = col.as_f64_slice_with_validity() {
                let mut seen: FxHashSet<u64> = FxHashSet::with_capacity_and_hasher(
                    data.len().min(1 << 18),
                    Default::default(),
                );
                let mut missing_seen = false;
                for (i, &v) in data.iter().enumerate() {
                    if validity.get(i) && !v.is_nan() {
                        let normalized = if v == 0.0 { 0.0 } else { v };
                        seen.insert(normalized.to_bits());
                    } else if !dropna {
                        missing_seen = true;
                    }
                }
                return Ok(Scalar::Int64(
                    (seen.len() + usize::from(missing_seen)) as i64,
                ));
            }
            // Hash-free direct-address fast path (br-frankenpandas-zf96l):
            // an all-valid bounded-range Int64 column counts distinct via a
            // dense seen-bit table (same helper Series::nunique uses), skipping
            // the col.values() materialization + ScalarKey SipHash. All-valid
            // (as_i64_slice) => no missing, so dropna is moot and the distinct
            // count is bit-identical to the HashMap distinct count.
            if let Some(data) = col.as_i64_slice()
                && let Some((min, range)) = i64_dense_histogram_range(data)
            {
                let mut seen_slot = vec![false; range];
                let mut distinct = 0usize;
                for &v in data {
                    let slot = (v as i128 - min as i128) as usize;
                    if !seen_slot[slot] {
                        seen_slot[slot] = true;
                        distinct += 1;
                    }
                }
                return Ok(Scalar::Int64(distinct as i64));
            }
            // br-frankenpandas-rh1od: an OBJECT bucket holding only numeric
            // scalars (the bool+numeric constructor mix) dedups under PYTHON
            // numeric equality — True ≡ 1 ≡ 1.0 collapse to one entry.
            // MEASURED live 2.2.3: pd.DataFrame({'a': [True, 1, 1.0, False]})
            // .nunique() -> 2 for that column. Same canonical-f64-bits keying
            // as the Series::nunique arm; ints beyond 2^53 lose exactness by
            // documented design note.
            if col.dtype() == DType::Utf8
                && col.values().iter().all(|value| {
                    value.is_missing()
                        || matches!(
                            value,
                            Scalar::Bool(_) | Scalar::Int64(_) | Scalar::Float64(_)
                        )
                })
            {
                let mut seen_num: FxHashSet<u64> =
                    FxHashSet::with_capacity_and_hasher(col.len().min(1 << 18), Default::default());
                let mut obj_missing = false;
                for value in col.values() {
                    if value.is_missing() {
                        if !dropna {
                            obj_missing = true;
                        }
                        continue;
                    }
                    let numeric = match value {
                        Scalar::Bool(b) => f64::from(*b),
                        #[allow(clippy::cast_precision_loss)]
                        Scalar::Int64(v) => *v as f64,
                        Scalar::Float64(v) => *v,
                        _ => unreachable!("bucket pre-checked all-numeric"),
                    };
                    let normalized = if numeric == 0.0 { 0.0 } else { numeric };
                    seen_num.insert(normalized.to_bits());
                }
                return Ok(Scalar::Int64(
                    (seen_num.len() + usize::from(obj_missing)) as i64,
                ));
            }
            let mut seen: FxHashMap<ScalarKey<'_>, ()> = FxHashMap::default();
            let mut missing_seen = false;
            for v in col.values() {
                if v.is_missing() {
                    if dropna {
                        continue;
                    }
                    missing_seen = true;
                    continue;
                }
                if let Some(key) = scalar_key_skip_missing(v) {
                    seen.insert(key, ());
                }
            }
            Ok(Scalar::Int64(
                (seen.len() + usize::from(missing_seen)) as i64,
            ))
        })?;
        Series::from_values("nunique".to_string(), labels, values)
    }

    /// Count unique non-null values with axis parameter.
    ///
    /// Matches `pd.DataFrame.nunique(axis)`.
    /// - axis=0 (default): unique count per column (same as `nunique()`)
    /// - axis=1: unique count per row
    pub fn nunique_axis(&self, axis: usize) -> Result<Series, FrameError> {
        self.nunique_axis_with_dropna(axis, true)
    }

    /// Count unique values with axis parameter and explicit null counting control.
    ///
    /// Matches `pd.DataFrame.nunique(axis=..., dropna=...)`.
    pub fn nunique_axis_with_dropna(
        &self,
        axis: usize,
        dropna: bool,
    ) -> Result<Series, FrameError> {
        if axis == 0 {
            return self.nunique_with_dropna(dropna);
        }
        if axis != 1 {
            return Err(FrameError::CompatibilityRejected(format!(
                "axis must be 0 or 1, got {axis}"
            )));
        }
        // axis=1: count unique values per row. Resolve each column's value slice
        // ONCE (br-frankenpandas-nuax1) — the old inner map did a per-cell
        // `self.columns[col_name]` BTreeMap-by-name lookup (n*m lookups) — and,
        // since each row's distinct count is independent, spread the rows across
        // worker threads (chunks_mut hands each a disjoint output slice). The
        // per-row `distinct_values` (cross-dtype grouped_scalar_eq) is unchanged,
        // so the result is bit-identical.
        let n = self.len();
        let col_values: Vec<&[Scalar]> = self
            .column_order
            .iter()
            .map(|name| self.columns[name].values())
            .collect();
        let compute = |row: usize| -> Scalar {
            let row_values: Vec<Scalar> = col_values.iter().map(|cv| cv[row].clone()).collect();
            Scalar::Int64(distinct_values(&row_values, dropna).len() as i64)
        };

        let mut values = vec![Scalar::Int64(0); n];
        let worker_count = if n >= 16_384 && !self.column_order.is_empty() {
            fp_columnar::cached_available_parallelism().min(16)
        } else {
            1
        };
        if worker_count >= 2 {
            let chunk = n.div_ceil(worker_count);
            let compute = &compute;
            std::thread::scope(|scope| {
                for (w, slot) in values.chunks_mut(chunk).enumerate() {
                    let base = w * chunk;
                    scope.spawn(move || {
                        for (k, s) in slot.iter_mut().enumerate() {
                            *s = compute(base + k);
                        }
                    });
                }
            });
        } else {
            for (row, s) in values.iter_mut().enumerate() {
                *s = compute(row);
            }
        }

        // Per br-frankenpandas-ngoic: pandas df.nunique(axis=1) preserves
        // df.index.name on the per-row unique-count result.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("nunique".to_owned(), index, column)
    }

    /// Count unique non-null values per row (axis=1).
    ///
    /// Matches `pd.DataFrame.nunique(axis=1)`.
    pub fn nunique_axis1(&self) -> Result<Series, FrameError> {
        self.nunique_axis_with_dropna(1, true)
    }

    /// Count unique values per row with explicit null counting control.
    ///
    /// Matches `pd.DataFrame.nunique(axis=1, dropna=...)`.
    pub fn nunique_axis1_with_dropna(&self, dropna: bool) -> Result<Series, FrameError> {
        self.nunique_axis_with_dropna(1, dropna)
    }

    /// Index label of the minimum value per numeric column.
    ///
    /// Matches `pd.DataFrame.idxmin()`.
    /// Can `idxmin`/`idxmax` order this column at all?
    ///
    /// pandas answers for any HOMOGENEOUS comparable column — numeric, bool,
    /// datetime, timedelta, and object-of-strings (lexicographically) — and
    /// raises `TypeError` when the values are not mutually orderable, which for
    /// an object column includes a `nan` sitting among strings. See the
    /// measurements on [`Self::idxmin`].
    /// An all-missing column yields `nan` rather than refusing.
    ///
    /// MEASURED, live pandas 2.2.3, index `['r0','r1']`:
    ///
    /// ```text
    /// {'a': [nan, nan]}   float64   idxmax -> {'a': nan}
    /// {'a': [None, None]} object    idxmax -> {'a': nan}
    /// {'a': [1.0, nan]}   float64   idxmax -> {'a': 'r0'}   nan is SKIPPED
    /// ```
    ///
    /// (pandas emits a FutureWarning that the all-NA case will raise in a later
    /// version; it does not raise in 2.2.3, so neither do we.) Checked BEFORE
    /// comparability, because an all-missing column has nothing to compare and
    /// would otherwise be refused. The metamorphic properties caught this — the
    /// generator emits all-null columns, exactly as they did for the
    /// numeric_only flip. (br-frankenpandas-fixture-divergence-triage-9s0c4)
    fn idx_extreme_is_all_missing(column: &Column) -> bool {
        column.values().iter().all(Scalar::is_missing)
    }

    fn idx_extreme_is_comparable(column: &Column) -> bool {
        match column.dtype() {
            DType::Bool
            | DType::Int64
            | DType::Float64
            | DType::Timedelta64
            | DType::Datetime64 => true,
            // A string column orders lexicographically, but only if EVERY value
            // is a string: pandas compares the raw objects, so a nan among them
            // raises rather than being skipped.
            DType::Utf8 => column
                .values()
                .iter()
                .all(|value| matches!(value, Scalar::Utf8(_))),
            _ => false,
        }
    }

    pub fn idxmin(&self) -> Result<Series, FrameError> {
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|n| n.as_str().into())
            .collect();
        let mut values = Vec::with_capacity(labels.len());
        for name in &self.column_order {
            // The claim previously here — "pandas treats non-numeric
            // (object/Utf8) columns as having no computable idxmin and returns
            // NaN for them ... Match the oracle behavior (FP-P2D-148)" — is
            // FALSE, and it was written against the oracle rather than pandas.
            // MEASURED, live pandas 2.2.3, index ['r0','r1','r2']:
            //   {'c': ['x','z','y']}          idxmin -> 'r0'   idxmax -> 'r1'
            //   {'c': [False,True,False]}     idxmin -> 'r0'   idxmax -> 'r1'
            //   {'c': datetimes}              idxmin -> 'r0'   idxmax -> 'r1'
            //   {'c': ['x', 2, 'y']}          RAISES TypeError (mixed types)
            //   {'c': ['x', nan, 'y']}        RAISES TypeError (nan vs str)
            // A homogeneous comparable column IS answered, lexicographically
            // for strings. Only an incomparable one refuses, and it refuses
            // rather than yielding NaN. Datetime64 was excluded by the old gate
            // too, which was a second miss.
            // (br-frankenpandas-fixture-divergence-triage-9s0c4)
            if Self::idx_extreme_is_all_missing(&self.columns[name]) {
                values.push(Scalar::Null(NullKind::NaN));
                continue;
            }
            if !Self::idx_extreme_is_comparable(&self.columns[name]) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "idxmin cannot compare column '{name}': its values are not \
                     mutually orderable"
                )));
            }
            let s = self.column_as_series(name)?;
            match s.idxmin() {
                Ok(label) => values.push(index_label_to_scalar(&label)),
                Err(_) => values.push(Scalar::Null(NullKind::NaN)),
            }
        }
        Series::from_values("idxmin".to_string(), labels, values)
    }

    /// Index label of the maximum value per numeric column.
    ///
    /// Matches `pd.DataFrame.idxmax()`.
    pub fn idxmax(&self) -> Result<Series, FrameError> {
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|n| n.as_str().into())
            .collect();
        let mut values = Vec::with_capacity(labels.len());
        for name in &self.column_order {
            // Sister to idxmin above, same measured rule.
            if Self::idx_extreme_is_all_missing(&self.columns[name]) {
                values.push(Scalar::Null(NullKind::NaN));
                continue;
            }
            if !Self::idx_extreme_is_comparable(&self.columns[name]) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "idxmax cannot compare column '{name}': its values are not \
                     mutually orderable"
                )));
            }
            let s = self.column_as_series(name)?;
            match s.idxmax() {
                Ok(label) => values.push(index_label_to_scalar(&label)),
                Err(_) => values.push(Scalar::Null(NullKind::NaN)),
            }
        }
        Series::from_values("idxmax".to_string(), labels, values)
    }

    /// Parallel CONTIGUOUS-Utf8 builder for the typed-f64 axis=1 arg-extrema fast
    /// paths (idxmin/idxmax/argmax_axis1). Output is a per-row Utf8 column of the
    /// winning column NAME. The serial form's dominant cost is NOT the per-row
    /// compare but the serial `Column::from_values` that materializes n
    /// `Scalar::Utf8` into a contiguous Utf8 buffer (measured: parallelizing only
    /// the compare+clone was ~1.00x — see NEGATIVE_EVIDENCE). Here each worker, over
    /// its row range, runs `find_best` AND appends the winning name's bytes into a
    /// local buffer with per-row end offsets — parallelizing the compare AND the
    /// Utf8 materialization — then the chunks concat with a running byte base into
    /// ONE `from_utf8_contiguous` (no `Scalar` round-trip). `find_best` carries each
    /// caller's EXACT comparison, so the bytes/offsets are bit-identical to the
    /// `Scalar` + `from_values` path for the all-valid case. If any row has no winner
    /// (all-NaN row -> Null), the contiguous path can't hold the null, so it falls
    /// back to the serial `Scalar` + `from_values` path (rare; exact). 50k-row gated.
    fn arg_axis1_names_parallel(
        &self,
        col_f64: &[&[f64]],
        label: &str,
        find_best: impl Fn(&[&[f64]], usize) -> Option<usize> + Sync,
    ) -> Result<Series, FrameError> {
        let n = self.index.labels().len();
        let column_order = &self.column_order;
        // Exact original behavior (handles Null rows) — used below the gate and as
        // the fallback when any row has no winner.
        let serial_scalar = || -> Result<Series, FrameError> {
            let mut values = Vec::with_capacity(n);
            for row in 0..n {
                values.push(match find_best(col_f64, row) {
                    Some(ci) => Scalar::Utf8(column_order[ci].clone()),
                    None => Scalar::Null(NullKind::NaN),
                });
            }
            let column = Column::from_values(values)?;
            Series::new(label, self.index.clone(), column)
        };
        const ARG_PAR_MIN_ROWS: usize = 50_000;
        const ARG_PAR_MIN_PER_WORKER: usize = 16_384;
        let workers = if n >= ARG_PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism()
                .min(16)
                .min(n / ARG_PAR_MIN_PER_WORKER)
                .max(1)
        } else {
            1
        };
        if workers < 2 {
            return serial_scalar();
        }
        // Each worker: (name bytes, per-row END offsets relative to its own buffer,
        // had_null). had_null forces the fallback (contiguous-Utf8 can't hold nulls).
        let build = |lo: usize, hi: usize| -> (Vec<u8>, Vec<usize>, bool) {
            let mut bytes = Vec::new();
            let mut ends = Vec::with_capacity(hi - lo);
            let mut had_null = false;
            for row in lo..hi {
                match find_best(col_f64, row) {
                    Some(ci) => bytes.extend_from_slice(column_order[ci].as_bytes()),
                    None => had_null = true,
                }
                ends.push(bytes.len());
            }
            (bytes, ends, had_null)
        };
        let chunk = n.div_ceil(workers);
        let build = &build;
        let parts: Vec<(Vec<u8>, Vec<usize>, bool)> = std::thread::scope(|scope| {
            let mut handles = Vec::with_capacity(workers);
            let mut start = 0;
            while start < n {
                let end = (start + chunk).min(n);
                handles.push(scope.spawn(move || build(start, end)));
                start = end;
            }
            handles
                .into_iter()
                .map(|h| h.join().expect("arg_axis1 thread"))
                .collect()
        });
        if parts.iter().any(|(_, _, had_null)| *had_null) {
            return serial_scalar();
        }
        // Concat into ONE (bytes, offsets): offsets has n+1 entries (leading 0), each
        // worker's per-row end offsets shifted by the running byte base.
        let total_bytes: usize = parts.iter().map(|(b, _, _)| b.len()).sum();
        let mut bytes = Vec::with_capacity(total_bytes);
        let mut offsets = Vec::with_capacity(n + 1);
        offsets.push(0usize);
        let mut base = 0usize;
        for (b, ends, _) in &parts {
            for &e in ends {
                offsets.push(base + e);
            }
            bytes.extend_from_slice(b);
            base += b.len();
        }
        let column = Column::from_utf8_contiguous(bytes, offsets);
        Series::new(label, self.index.clone(), column)
    }

    /// Column label of the minimum value per row (axis=1).
    ///
    /// Matches `pd.DataFrame.idxmin(axis=1)`. Returns a Series with one
    /// entry per row, containing the column name of the minimum value.
    pub fn idxmin_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-dvzw1: Timedelta-DataFrame axis=1 idxmin
        // compares ns directly. to_f64 below errors on every Timedelta
        // value so best_col stays None and all rows would be NaN.
        // Typed-f64 fast path (sister to idxmax_axis1): all all-valid Float64
        // columns -> raw f64 compare over hoisted slices, first-min-wins, NaN
        // skipped. Bit-identical to the generic to_f64 path.
        'f64: {
            // Each column is an all-valid Float64 (borrow its slice; the per-row
            // kernel below skips NaN inline, so a valid NaN is handled exactly as the
            // generic `is_missing()` skip) or an all-valid Int64 (materialize `v as
            // f64` once — never NaN). The winning column (hence the emitted label) is
            // chosen by the same comparisons the generic to_f64 path makes, so it is
            // bit-identical; the Utf8/label output is independent of input dtype.
            // Nullable / Timedelta / other-dtype columns break to the generic path.
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(self.column_order.len());
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.as_f64_slice().is_some() {
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'f64;
                }
            }
            if is_owned.is_empty() {
                break 'f64;
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = self
                .column_order
                .iter()
                .zip(&is_owned)
                .map(|(name, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[name]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            // Bit-identical per-row kernel (v < best, best=+INF, first-min-wins,
            // NaN skipped), now parallel contiguous-Utf8 build via the shared builder.
            return self.arg_axis1_names_parallel(&col_f64, "idxmin", |cols, row| {
                let mut best = f64::INFINITY;
                let mut best_col: Option<usize> = None;
                for (ci, c) in cols.iter().enumerate() {
                    let v = c[row];
                    if v.is_nan() {
                        continue;
                    }
                    if v < best {
                        best = v;
                        best_col = Some(ci);
                    }
                }
                best_col
            });
        }
        let all_td = self.all_columns_timedelta();
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let mut best_col: Option<&str> = None;
            if all_td {
                let mut best_ns: i64 = i64::MAX;
                for col_name in &self.column_order {
                    if let Scalar::Timedelta64(ns) = &self.columns[col_name].values()[row_idx] {
                        if *ns == Timedelta::NAT {
                            continue;
                        }
                        if best_col.is_none() || *ns < best_ns {
                            best_ns = *ns;
                            best_col = Some(col_name);
                        }
                    }
                }
            } else {
                let mut best_val = f64::INFINITY;
                for col_name in &self.column_order {
                    let val = &self.columns[col_name].values()[row_idx];
                    if val.is_missing() {
                        continue;
                    }
                    if let Ok(v) = val.to_f64()
                        && v < best_val
                    {
                        best_val = v;
                        best_col = Some(col_name);
                    }
                }
            }
            match best_col {
                Some(name) => values.push(Scalar::Utf8(name.to_string())),
                None => values.push(Scalar::Null(NullKind::NaN)),
            }
        }
        // Per br-frankenpandas-bt0kp: pandas df.idxmin(axis=1) preserves
        // df.index.name on the per-row result.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("idxmin", index, column)
    }

    /// Column label of the maximum value per row (axis=1).
    ///
    /// Matches `pd.DataFrame.idxmax(axis=1)`. Returns a Series with one
    /// entry per row, containing the column name of the maximum value.
    pub fn idxmax_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-dvzw1: sister to idxmin_axis1 above.
        // Typed-f64 fast path: all columns all-valid Float64 -> compare raw f64
        // over hoisted &[f64] views (no per-cell BTreeMap lookup, no Scalar +
        // to_f64 dispatch). First (earliest-column) max wins on ties (strict >),
        // NaN skipped — bit-identical to the generic to_f64 path below.
        'f64: {
            // Sister to idxmin_axis1's widened gather: all-valid Float64 columns
            // borrow (the kernel skips NaN inline), all-valid Int64 columns take a
            // `v as f64` view (never NaN); the label output is dtype-independent and
            // bit-identical. Nullable / Timedelta / other-dtype columns break out.
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(self.column_order.len());
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.as_f64_slice().is_some() {
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'f64;
                }
            }
            if is_owned.is_empty() {
                break 'f64;
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = self
                .column_order
                .iter()
                .zip(&is_owned)
                .map(|(name, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[name]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            // Bit-identical per-row kernel (v > best, best=-INF, first-max-wins,
            // NaN skipped), now parallel contiguous-Utf8 build via the shared builder.
            return self.arg_axis1_names_parallel(&col_f64, "idxmax", |cols, row| {
                let mut best = f64::NEG_INFINITY;
                let mut best_col: Option<usize> = None;
                for (ci, c) in cols.iter().enumerate() {
                    let v = c[row];
                    if v.is_nan() {
                        continue;
                    }
                    if v > best {
                        best = v;
                        best_col = Some(ci);
                    }
                }
                best_col
            });
        }
        let all_td = self.all_columns_timedelta();
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let mut best_col: Option<&str> = None;
            if all_td {
                let mut best_ns: i64 = i64::MIN;
                for col_name in &self.column_order {
                    if let Scalar::Timedelta64(ns) = &self.columns[col_name].values()[row_idx] {
                        if *ns == Timedelta::NAT {
                            continue;
                        }
                        if best_col.is_none() || *ns > best_ns {
                            best_ns = *ns;
                            best_col = Some(col_name);
                        }
                    }
                }
            } else {
                let mut best_val = f64::NEG_INFINITY;
                for col_name in &self.column_order {
                    let val = &self.columns[col_name].values()[row_idx];
                    if val.is_missing() {
                        continue;
                    }
                    if let Ok(v) = val.to_f64()
                        && v > best_val
                    {
                        best_val = v;
                        best_col = Some(col_name);
                    }
                }
            }
            match best_col {
                Some(name) => values.push(Scalar::Utf8(name.to_string())),
                None => values.push(Scalar::Null(NullKind::NaN)),
            }
        }
        // Per br-frankenpandas-bt0kp: pandas df.idxmax(axis=1) preserves
        // df.index.name on the per-row result.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("idxmax", index, column)
    }

    /// Whether all non-null values are truthy, per column.
    ///
    /// Matches `pd.DataFrame.all()`.
    pub fn all(&self) -> Result<Series, FrameError> {
        let labels: Vec<IndexLabel> = self
            .column_order
            .iter()
            .map(|n| n.as_str().into())
            .collect();
        let mut values = Vec::with_capacity(labels.len());
        for name in &self.column_order {
            let s = self.column_as_series(name)?;
            values.push(Scalar::Bool(s.all()?));
        }
        Series::from_values("all".to_string(), labels, values)
    }

