    /// Mode per column.
    ///
    /// Matches `pd.DataFrame.mode()`. Returns a DataFrame where each column
    /// contains its mode values, padded with `NaN` when columns have fewer modes.
    pub fn mode(&self) -> Result<Self, FrameError> {
        self.mode_with_options(0, false, true)
    }

    /// Mode over columns or rows with pandas-compatible options.
    ///
    /// Matches `pd.DataFrame.mode(axis=..., numeric_only=..., dropna=...)`.
    pub fn mode_with_options(
        &self,
        axis: usize,
        numeric_only: bool,
        dropna: bool,
    ) -> Result<Self, FrameError> {
        match axis {
            0 => self.mode_axis0(numeric_only, dropna),
            1 => self.mode_axis1(numeric_only, dropna),
            _ => Err(FrameError::CompatibilityRejected(format!(
                "axis must be 0 or 1, got {axis}"
            ))),
        }
    }

    fn mode_axis0(&self, numeric_only: bool, dropna: bool) -> Result<Self, FrameError> {
        // Per br-frankenpandas-uy9z2: include Timedelta64 in numeric_only.
        // pandas df.mode(numeric_only=True) covers Timedelta — it's a
        // numeric-style dtype, not object.
        let selected_columns = self
            .column_order
            .iter()
            .filter(|name| {
                !numeric_only
                    || matches!(
                        self.columns[name.as_str()].dtype(),
                        DType::Bool | DType::Int64 | DType::Float64 | DType::Timedelta64
                    )
            })
            .cloned()
            .collect::<Vec<_>>();

        // Column-parallel mode (br-frankenpandas-mode-par): each column's mode
        // (a value tally over independent data) is computed by the EXACT same
        // Series::mode_with_dropna, so spreading columns across std::thread::scope
        // workers is bit-identical — results are reassembled in selected_columns
        // order and the downstream max_modes/padding is order-independent. The
        // serial loop left all but one of the box's cores idle. Gated so small
        // frames keep the zero-overhead serial path.
        const MODE_PAR_MIN_COLS: usize = 2;
        const MODE_PAR_MIN_VALUES: usize = 16_384;

        let mode_one = |name: &str| -> Result<(String, Series), FrameError> {
            let series = self.column_as_series(name)?;
            let modes = series.mode_with_dropna(dropna)?;
            Ok((name.to_string(), modes))
        };

        let ncols = selected_columns.len();
        let worker_count = if ncols >= MODE_PAR_MIN_COLS
            && ncols.saturating_mul(self.len()) >= MODE_PAR_MIN_VALUES
        {
            fp_columnar::cached_available_parallelism().min(ncols)
        } else {
            1
        };

        let column_modes: Vec<(String, Series)> = if worker_count >= 2 {
            let next = std::sync::atomic::AtomicUsize::new(0);
            std::thread::scope(|scope| -> Result<Vec<(String, Series)>, FrameError> {
                let mut handles = Vec::with_capacity(worker_count);
                for _ in 0..worker_count {
                    let next = &next;
                    let mode_one = &mode_one;
                    let selected = &selected_columns;
                    handles.push(scope.spawn(
                        move || -> Result<Vec<(usize, String, Series)>, FrameError> {
                            let mut out = Vec::new();
                            loop {
                                let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                if i >= selected.len() {
                                    break;
                                }
                                let (name, modes) = mode_one(&selected[i])?;
                                out.push((i, name, modes));
                            }
                            Ok(out)
                        },
                    ));
                }
                let mut slots: Vec<Option<(String, Series)>> = (0..ncols).map(|_| None).collect();
                for handle in handles {
                    let worker_out = handle.join().map_err(|_| {
                        FrameError::CompatibilityRejected("mode worker thread panicked".into())
                    })??;
                    for (i, name, modes) in worker_out {
                        slots[i] = Some((name, modes));
                    }
                }
                Ok(slots
                    .into_iter()
                    .map(|slot| slot.expect("every column index is assigned to exactly one worker"))
                    .collect())
            })?
        } else {
            let mut v = Vec::with_capacity(ncols);
            for name in &selected_columns {
                v.push(mode_one(name)?);
            }
            v
        };

        let max_modes = column_modes
            .iter()
            .map(|(_, modes)| modes.len())
            .max()
            .unwrap_or(0);

        let mut result_cols = BTreeMap::new();
        if max_modes == 0 {
            for name in &selected_columns {
                let dtype = self.columns[name.as_str()].dtype();
                result_cols.insert(name.clone(), Column::new(dtype, Vec::new())?);
            }
            return Self::new_with_column_order(
                Index::new(Vec::new()),
                result_cols,
                selected_columns,
            );
        }

        for (name, modes) in column_modes {
            // No-padding passthrough: a column whose mode count already equals
            // max_modes needs no NaN padding and no dtype change, so reuse its
            // typed column directly instead of round-tripping through
            // `values().to_vec()` + `build_mode_column` (which re-boxes every mode
            // as a Scalar and rebuilds the column). Bit-identical: for a
            // full-length column the padded branch would rebuild the very same
            // (dtype, values) it started from. This is the common df.mode() shape
            // for high-cardinality columns (every column contributes max_modes
            // modes), where the re-materialization dominated.
            if modes.len() == max_modes {
                result_cols.insert(name, modes.column().clone());
                continue;
            }
            let mut values = modes.column().values().to_vec();
            let needs_padding = values.len() < max_modes;
            while values.len() < max_modes {
                values.push(Scalar::Null(NullKind::NaN));
            }
            // Per pandas parity: when NaN padding is added to Int64 columns,
            // the result dtype should be Float64 (pandas uses NaN which
            // requires floating-point representation).
            if needs_padding && modes.column().dtype() == DType::Int64 {
                let float_values: Vec<Scalar> = values
                    .into_iter()
                    .map(|v| match v {
                        Scalar::Int64(i) => Scalar::Float64(i as f64),
                        other => other,
                    })
                    .collect();
                result_cols.insert(name, Column::new(DType::Float64, float_values)?);
            } else {
                result_cols.insert(name, build_mode_column(values)?);
            }
        }

        let labels: Vec<IndexLabel> = (0..max_modes).map(|i| (i as i64).into()).collect();
        Self::new_with_column_order(Index::new(labels), result_cols, selected_columns)
    }

    fn mode_axis1(&self, numeric_only: bool, dropna: bool) -> Result<Self, FrameError> {
        // Per br-frankenpandas-uy9z2: include Timedelta64 in numeric_only.
        let selected_columns = self
            .column_order
            .iter()
            .filter(|name| {
                !numeric_only
                    || matches!(
                        self.columns[name.as_str()].dtype(),
                        DType::Bool | DType::Int64 | DType::Float64 | DType::Timedelta64
                    )
            })
            .cloned()
            .collect::<Vec<_>>();

        if selected_columns.is_empty() {
            return Self::new_with_column_order(self.index.clone(), BTreeMap::new(), Vec::new());
        }

        let mut row_modes = Vec::with_capacity(self.len());
        let mut max_modes = 0;
        for row_idx in 0..self.len() {
            let row_values = selected_columns
                .iter()
                .map(|name| self.columns[name.as_str()].values()[row_idx].clone())
                .collect::<Vec<_>>();
            let modes = mode_values(&row_values, dropna);
            max_modes = max_modes.max(modes.len());
            row_modes.push(modes);
        }

        if max_modes == 0 {
            return Self::new_with_column_order(self.index.clone(), BTreeMap::new(), Vec::new());
        }

        let mode_columns = (0..max_modes).map(|i| i.to_string()).collect::<Vec<_>>();
        let padded_rows = row_modes
            .into_iter()
            .map(|mut modes| {
                while modes.len() < max_modes {
                    modes.push(Scalar::Null(NullKind::NaN));
                }
                modes
            })
            .collect::<Vec<_>>();

        // axis=1 output columns span rows whose source columns may have
        // different dtypes. Pandas treats the per-row numeric slice as a
        // single dtype-promoted Series, so any Float64 source column
        // promotes the whole output column to Float64 (matching
        // row-wise broadcast semantics). Without this, an Int64 mode
        // value landing beside NaN padding would keep the column at
        // Int64, diverging from pandas for numeric_only row-mode.
        let any_source_is_float = selected_columns
            .iter()
            .any(|name| matches!(self.columns[name.as_str()].dtype(), DType::Float64));

        let mut result_cols = BTreeMap::new();
        for (col_idx, name) in mode_columns.iter().enumerate() {
            let mut values: Vec<Scalar> =
                padded_rows.iter().map(|row| row[col_idx].clone()).collect();
            if any_source_is_float {
                for value in &mut values {
                    if let Scalar::Int64(v) = *value {
                        *value = Scalar::Float64(v as f64);
                    }
                }
            }
            result_cols.insert(name.clone(), build_mode_column(values)?);
        }

        Self::new_with_column_order(self.index.clone(), result_cols, mode_columns)
    }

    /// Internal: reduce each numeric column to a single scalar via the named function.
    /// Map a per-column closure across `names` in order, running columns in
    /// parallel across `std::thread::scope` workers (atomic work-stealing, the
    /// project's parallel idiom) when there are enough of them. Each closure
    /// call reduces ONE column independently, so the result vector is identical
    /// to the serial map regardless of execution order — bit-identical. Small
    /// inputs keep the zero-overhead serial path. The shared lever behind the
    /// whole per-column reduction family (sum/mean/min/max/std/var/median/prod/
    /// skew/kurtosis/sem) — the serial loop left all but one core idle.
    fn par_map_columns<T, F>(&self, names: &[String], f: F) -> Result<Vec<T>, FrameError>
    where
        T: Send,
        F: Fn(&str) -> Result<T, FrameError> + Sync,
    {
        // Default threshold suits compute-bound per-column work (round/clip/
        // sqrt/exp/log/trig/...), where even a few thousand cells amortize the
        // thread::scope spawn. Pure-bandwidth ops (abs) pass a higher floor via
        // `par_map_columns_min` — see `DataFrame::abs`.
        self.par_map_columns_min(names, 16_384, f)
    }

    /// `par_map_columns` with an explicit minimum total-cell count before the
    /// per-column work is spread across threads. Bandwidth-bound elementwise
    /// ops set this high: when the whole frame is L3-resident, one core already
    /// saturates the available bandwidth, so the thread-spawn overhead is pure
    /// loss (measured: abs over 100k×10 is ~1.9x faster serial than threaded).
    fn par_map_columns_min<T, F>(
        &self,
        names: &[String],
        par_min_values: usize,
        f: F,
    ) -> Result<Vec<T>, FrameError>
    where
        T: Send,
        F: Fn(&str) -> Result<T, FrameError> + Sync,
    {
        const PAR_MIN_COLS: usize = 2;

        let ncols = names.len();
        let worker_count =
            if ncols >= PAR_MIN_COLS && ncols.saturating_mul(self.len()) >= par_min_values {
                fp_columnar::cached_available_parallelism().min(ncols)
            } else {
                1
            };

        if worker_count < 2 {
            return names.iter().map(|name| f(name)).collect();
        }

        let next = std::sync::atomic::AtomicUsize::new(0);
        std::thread::scope(|scope| -> Result<Vec<T>, FrameError> {
            let mut handles = Vec::with_capacity(worker_count);
            for _ in 0..worker_count {
                let next = &next;
                let f = &f;
                handles.push(scope.spawn(move || -> Result<Vec<(usize, T)>, FrameError> {
                    let mut out = Vec::new();
                    loop {
                        let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        if i >= names.len() {
                            break;
                        }
                        out.push((i, f(&names[i])?));
                    }
                    Ok(out)
                }));
            }
            let mut slots: Vec<Option<T>> = (0..ncols).map(|_| None).collect();
            for handle in handles {
                let worker_out = handle.join().map_err(|_| {
                    FrameError::CompatibilityRejected(
                        "column reduction worker thread panicked".into(),
                    )
                })??;
                for (i, value) in worker_out {
                    slots[i] = Some(value);
                }
            }
            Ok(slots
                .into_iter()
                .map(|slot| slot.expect("every column index is assigned to exactly one worker"))
                .collect())
        })
    }

    fn reduce_numeric(&self, func: &str) -> Result<Series, FrameError> {
        // THE DEFAULT IS numeric_only=FALSE, matching pandas 2.x
        // (br-frankenpandas-reductions-numeric-only-default-zx21n). It was TRUE
        // — pandas 1.x's behaviour, which silently dropped object columns from
        // `df.sum()`. MEASURED, live pandas 2.2.3, on a frame with a float `b`,
        // an object `label` and an int `a`:
        //
        //   df.sum()   -> {'b': -4.0, 'label': 'azm', 'a': 5}   object INCLUDED
        //                                                       and 'a' stays int64
        //   df.sum(numeric_only=True)
        //              -> {'b': -4.0,                'a': 5.0}  'a' PROMOTED
        //
        // The flip was blocked until the 13 fixtures that pin the
        // numeric_only=TRUE result could SAY so; they now carry
        // `<op>_numeric_only: true` and are honoured on both the oracle and the
        // harness side, so they no longer depend on whatever the default is.
        self.reduce_with_numeric_only(func, false)
    }

    /// Reduce each column, optionally restricting to numeric columns.
    ///
    /// `numeric_only=true` reproduces the historical behaviour: non-numeric
    /// columns are skipped entirely, and the numeric ones are promoted to
    /// float64. `numeric_only=false` is pandas 2.x's DEFAULT and splits the
    /// family in two, measured on live pandas 2.2.3 over a frame with a float
    /// 'b', an object 'label' and an int 'a':
    ///
    /// ```text
    /// INCLUDE the object column (5 ops):
    ///   sum     {'b': -1.0, 'label': 'azm', 'a': 7}   <- CONCATENATED, 'a' int64
    ///   min     {'b': -7.5, 'label': 'a',   'a': -1}  <- LEXICOGRAPHIC
    ///   max     {'b':  4.0, 'label': 'z',   'a': 5}
    ///   count   {'b': 3, 'label': 3, 'a': 3}
    ///   nunique {'b': 3, 'label': 3, 'a': 3}
    ///
    /// RAISE TypeError (8 ops):
    ///   mean prod median std var sem skew kurt
    ///     e.g. "could not convert string to float: 'a'"
    /// ```
    ///
    /// ⚠️ The two paths differ in OUTPUT DTYPE for the numeric columns too, not
    /// just in column selection: under `numeric_only=true` pandas returns column
    /// 'a' as float64, under the 2.x default it stays int64. Both must be
    /// individually correct, which is why this is a parameter rather than a
    /// filter tweak.
    ///
    /// ⚠️ THE DEFAULT IS NOT FLIPPED YET, on purpose. Flipping it turns 13
    /// fixtures red at once: 3 conceal the numeric_only=true result for the
    /// include-ops, and 10 (`..._skips_nonnumeric_...`) pin values for ops that
    /// would then RAISE. Those 10 exist to pin the skipping behaviour, so their
    /// correct repair is to say `numeric_only: true` in the fixture and thread
    /// it through the oracle — not to convert them to error fixtures. That needs
    /// the oracle work (zx21n scope 4) and a reconciliation with the strict
    /// raise-arm story in br-frankenpandas-fyr1z-strict-raise-arms-t7ht2 before
    /// the raise arms are written. Landing the capability without the flip keeps
    /// the default UNIFORM across the family rather than half-applied.
    fn reduce_with_numeric_only(
        &self,
        func: &str,
        numeric_only: bool,
    ) -> Result<Series, FrameError> {
        // Per br-frankenpandas-vpeoh: Series sum/mean/min/max/std/var/median/prod
        // preserve Timedelta64 dtype (br-28lgk/edmsd/erobu/7iz85/j0ilf/yy0ks/
        // rbt10). Allow Timedelta64 columns through for those funcs;
        // skew/kurtosis/sem still return f64 and remain restricted to numeric.
        let timedelta_safe = matches!(
            func,
            "sum" | "mean" | "min" | "max" | "std" | "var" | "median" | "prod"
        );
        let includes_non_numeric = matches!(func, "sum" | "min" | "max");
        let allowed: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                let dt = self.columns[name.as_str()].dtype();
                if matches!(dt, DType::Int64 | DType::Float64)
                    || (timedelta_safe && matches!(dt, DType::Timedelta64))
                {
                    return true;
                }
                // pandas 2.x keeps non-numeric columns for the ops that can
                // answer for them, and RAISES for the rest (handled below).
                !numeric_only
            })
            .cloned()
            .collect();

        if !numeric_only && !includes_non_numeric {
            // The 8 raise-ops. pandas surfaces the engine's own conversion
            // failure; FrankenPandas names the column so the message is
            // actionable, and the harness compares FP's wording anyway.
            //
            // ⚠️ A column with NO PRESENT VALUES DOES NOT RAISE. pandas' refusal
            // comes from converting the actual values, so an all-missing object
            // column converts vacuously and reduces to nan. MEASURED, live
            // pandas 2.2.3, on pd.DataFrame({'a': [None, None], 'b': [1.0, 2.0]})
            // where 'a' is dtype object:
            //
            //   mean / median / std / var  ->  {'a': nan, 'b': ...}   NO raise
            //   sum                        ->  {'a': 0,   'b': ...}
            //   min / max                  ->  {'a': None,'b': ...}
            //
            // Gating the raise on dtype alone therefore over-refuses. Caught by
            // the metamorphic properties, whose generator produces all-null
            // columns that infer DType::Null — 14 of them went red on the first
            // version of this flip. (br-frankenpandas-reductions-numeric-only-default-zx21n)
            if let Some(offender) = allowed.iter().find(|name| {
                let column = &self.columns[name.as_str()];
                !matches!(
                    column.dtype(),
                    DType::Int64 | DType::Float64 | DType::Timedelta64
                ) && column.values().iter().any(|v| !v.is_missing())
            }) {
                return Err(FrameError::CompatibilityRejected(format!(
                    "could not convert column '{offender}' to numeric for {func}"
                )));
            }
        }

        let values = self.par_map_columns(&allowed, |name| {
            let column = &self.columns[name];
            let is_numeric = matches!(
                column.dtype(),
                DType::Int64 | DType::Float64 | DType::Timedelta64
            );
            // Object-column semantics for the include-ops, measured on pandas
            // 2.2.3: `sum` CONCATENATES the strings in row order and min/max
            // compare LEXICOGRAPHICALLY. Nulls are skipped, as they are for the
            // numeric path.
            if !is_numeric && !numeric_only {
                let present: Vec<&Scalar> =
                    column.values().iter().filter(|v| !v.is_missing()).collect();
                return Ok(match func {
                    // An all-missing column sums to the integer 0, NOT to the
                    // empty concatenation. MEASURED, live pandas 2.2.3, on
                    // pd.DataFrame({'a': [None, None]}) with 'a' object:
                    //   df.sum() -> {'a': 0}
                    // pandas' empty sum is the additive identity even in an
                    // object column; it does not become "". Caught by
                    // prop_dataframe_sum_is_translation_covariant, which
                    // rejected the Utf8("") this arm produced.
                    // (br-frankenpandas-reductions-numeric-only-default-zx21n)
                    "sum" if present.is_empty() => Scalar::Int64(0),
                    "sum" => {
                        let mut joined = String::new();
                        for value in &present {
                            match value {
                                Scalar::Utf8(text) => joined.push_str(text),
                                other => joined.push_str(&other.to_string()),
                            }
                        }
                        Scalar::Utf8(joined)
                    }
                    "min" | "max" => {
                        let mut best: Option<&Scalar> = None;
                        for value in &present {
                            let take = match best {
                                None => true,
                                Some(current) => {
                                    // Nulls are already filtered out, so the
                                    // na_position argument cannot bite here;
                                    // for Utf8 this is String's own Ord, i.e.
                                    // pandas' lexicographic comparison.
                                    let ord = compare_scalars_with_na_last(value, current, true);
                                    if func == "min" {
                                        ord == std::cmp::Ordering::Less
                                    } else {
                                        ord == std::cmp::Ordering::Greater
                                    }
                                }
                            };
                            if take {
                                best = Some(value);
                            }
                        }
                        best.cloned().unwrap_or(Scalar::Null(NullKind::NaN))
                    }
                    // An all-missing non-numeric column reduces to NaN rather
                    // than refusing — pandas' refusal comes from converting the
                    // VALUES, and there are none. Measured on
                    // pd.DataFrame({'a': [None, None]}) with 'a' object:
                    // mean/median/std/var all give nan. The dtype-only gate
                    // above already let this column through; this arm is what
                    // actually answers for it.
                    // (br-frankenpandas-reductions-numeric-only-default-zx21n)
                    _ if present.is_empty() => Scalar::Null(NullKind::NaN),
                    _ => {
                        return Err(FrameError::CompatibilityRejected(format!(
                            "{func} cannot reduce non-numeric column '{name}'"
                        )));
                    }
                });
            }

            let s = self.column_as_series(name)?;
            Ok(match func {
                "sum" => s.sum()?,
                "mean" => s.mean()?,
                "min" => s.min()?,
                "max" => s.max()?,
                "std" => s.std()?,
                "var" => s.var()?,
                "median" => s.median()?,
                "prod" => s.prod()?,
                "skew" => Scalar::Float64(s.skew()?),
                "kurtosis" => Scalar::Float64(s.kurtosis()?),
                "sem" => Scalar::Float64(s.sem()?),
                _ => {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "unknown reduce function: {func}"
                    )));
                }
            })
        })?;
        let labels: Vec<IndexLabel> = allowed
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        Series::from_values(func.to_string(), labels, values)
    }

    /// Internal: reduce each numeric column with skipna control.
    fn reduce_numeric_skipna(&self, func: &str, skipna: bool) -> Result<Series, FrameError> {
        // Per br-frankenpandas-4zg55: skipna variants delegate to sum/mean/etc
        // which now preserve Timedelta64 (br-28lgk family). Allow Timedelta64
        // columns through. Sister to br-vpeoh and br-qin9h.
        let allowed: Vec<String> = self
            .column_order
            .iter()
            .filter(|name| {
                matches!(
                    self.columns[name.as_str()].dtype(),
                    DType::Int64 | DType::Float64 | DType::Timedelta64
                )
            })
            .cloned()
            .collect();

        let values = self.par_map_columns(&allowed, |name| {
            let s = self.column_as_series(name)?;
            Ok(match func {
                "sum" => s.sum_skipna(skipna)?,
                "mean" => s.mean_skipna(skipna)?,
                "min" => s.min_skipna(skipna)?,
                "max" => s.max_skipna(skipna)?,
                "std" => s.std_skipna(skipna)?,
                "var" => s.var_skipna(skipna)?,
                "median" => s.median_skipna(skipna)?,
                "prod" => s.prod_skipna(skipna)?,
                _ => {
                    return Err(FrameError::CompatibilityRejected(format!(
                        "unknown reduce function: {func}"
                    )));
                }
            })
        })?;
        let labels: Vec<IndexLabel> = allowed
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        Series::from_values(func.to_string(), labels, values)
    }

    /// Sum per column with skipna control.
    ///
    /// Matches `pd.DataFrame.sum(skipna=True|False)`.
    pub fn sum_skipna(&self, skipna: bool) -> Result<Series, FrameError> {
        self.reduce_numeric_skipna("sum", skipna)
    }

    /// Mean per column with skipna control.
    pub fn mean_skipna(&self, skipna: bool) -> Result<Series, FrameError> {
        self.reduce_numeric_skipna("mean", skipna)
    }

    /// Std per column with skipna control.
    pub fn std_agg_skipna(&self, skipna: bool) -> Result<Series, FrameError> {
        self.reduce_numeric_skipna("std", skipna)
    }

    /// Var per column with skipna control.
    pub fn var_agg_skipna(&self, skipna: bool) -> Result<Series, FrameError> {
        self.reduce_numeric_skipna("var", skipna)
    }

    /// Prod per column with skipna control.
    pub fn prod_agg_skipna(&self, skipna: bool) -> Result<Series, FrameError> {
        self.reduce_numeric_skipna("prod", skipna)
    }

    /// Skewness of non-null values per column.
    ///
    /// Matches `pd.DataFrame.skew()`.
    pub fn skew_agg(&self) -> Result<Series, FrameError> {
        self.reduce_numeric("skew")
    }

    /// Kurtosis of non-null values per column.
    ///
    /// Matches `pd.DataFrame.kurtosis()`.
    pub fn kurtosis_agg(&self) -> Result<Series, FrameError> {
        self.reduce_numeric("kurtosis")
    }

    /// Alias for `kurtosis_agg()` — pandas exposes `df.kurt()` and
    /// `df.kurtosis()` as equivalents at the column-aggregate level.
    pub fn kurt_agg(&self) -> Result<Series, FrameError> {
        self.kurtosis_agg()
    }

    /// Standard error of the mean per column.
    ///
    /// Matches `pd.DataFrame.sem()`.
    pub fn sem_agg(&self) -> Result<Series, FrameError> {
        self.reduce_numeric("sem")
    }

