    // ── Row-axis (axis=1) aggregations ──

    fn numeric_row_reduction_columns(&self) -> Vec<&str> {
        self.column_order
            .iter()
            .filter(|c| {
                let dt = self.columns[c.as_str()].dtype();
                dt == DType::Int64 || dt == DType::Float64 || dt == DType::Bool
            })
            .map(|s| s.as_str())
            .collect()
    }

    fn reduce_rows_int64<F>(
        &self,
        name: &str,
        empty: i64,
        op: F,
    ) -> Result<Option<Series>, FrameError>
    where
        F: Fn(i64, i64) -> i64,
    {
        let numeric_cols = self.numeric_row_reduction_columns();
        if numeric_cols.is_empty() {
            return Ok(None);
        }

        let Some(int_cols) = numeric_cols
            .iter()
            .map(|&col_name| {
                let column = &self.columns[col_name];
                if column.dtype() == DType::Int64 {
                    column.as_i64_slice()
                } else {
                    None
                }
            })
            .collect::<Option<Vec<_>>>()
        else {
            return Ok(None);
        };

        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let mut acc = empty;
            for col in &int_cols {
                acc = op(acc, col[row_idx]);
            }
            values.push(acc);
        }

        let index = self.index.clone();
        let column = Column::from_i64_values_owned(values);
        Series::new(name.to_owned(), index, column).map(Some)
    }

    /// Internal: typed Float64 row reduction (sister to `reduce_rows_int64`,
    /// br-frankenpandas-rrf64). When every row-reduction column is an all-valid no-NaN
    /// Float64 (`as_f64_slice`), reduce across the contiguous f64 buffers directly —
    /// `acc = op(acc, col[row])` in column order, identical to the generic `reduce_rows`'
    /// `func(&[f64])` over the same column-ordered values (no missing to skip, same
    /// left-to-right association ⇒ bit-identical f64 result) — skipping the per-row Scalar
    /// gather. Returns None (fall back to `reduce_rows`) if any column isn't no-NaN Float64.
    fn reduce_rows_f64<F>(
        &self,
        name: &str,
        empty: f64,
        op: F,
    ) -> Result<Option<Series>, FrameError>
    where
        F: Fn(f64, f64) -> f64,
    {
        let numeric_cols = self.numeric_row_reduction_columns();
        if numeric_cols.is_empty() {
            return Ok(None);
        }
        // Each numeric column must be an all-valid Float64 (borrow its slice) or an
        // all-valid Int64 column (materialize the `v as f64` view once). This method
        // is only reached AFTER `reduce_rows_int64` declines — i.e. NOT an all-Int64
        // frame (which stays Int64-typed there) — so the only Int64 columns that
        // arrive here are in a MIXED Int64+Float64 frame, whose sum/min/max/prod
        // axis=1 output is Float64 (pandas widens mixed int+float rows to float64).
        // Bit-identical to the generic `reduce_rows` fallback: the fold `op(acc,
        // v as f64)` in column order == its `func(&[f64])` over the same values
        // (`to_f64(Int64(v)) == v as f64`, all-valid ⇒ no missing to skip). Nullable
        // / other-dtype columns return None (generic path).
        let mut owned: Vec<Vec<f64>> = Vec::new();
        let mut is_owned: Vec<bool> = Vec::with_capacity(numeric_cols.len());
        for &col_name in &numeric_cols {
            let column = &self.columns[col_name];
            if column.dtype() == DType::Float64 {
                if column.as_f64_slice().is_none() {
                    return Ok(None);
                }
                is_owned.push(false);
            } else if column.dtype() == DType::Int64 {
                let Some(d) = column.as_i64_slice() else {
                    return Ok(None);
                };
                owned.push(d.iter().map(|&v| v as f64).collect());
                is_owned.push(true);
            } else {
                return Ok(None);
            }
        }
        let mut owned_iter = owned.iter();
        let f64_cols: Vec<&[f64]> = numeric_cols
            .iter()
            .zip(&is_owned)
            .map(|(&col_name, &owned_flag)| {
                if owned_flag {
                    owned_iter
                        .next()
                        .expect("one owned vec per Int64 column")
                        .as_slice()
                } else {
                    self.columns[col_name]
                        .as_f64_slice()
                        .expect("Float64 column checked all-valid above")
                }
            })
            .collect();

        // Tiled column-streaming reduction (axis=1 f64 row reducers): the naive
        // row-at-a-time fold touches k separate multi-MB column arrays per row
        // (column-strided) and does NOT vectorize — the inner loop has a runtime
        // trip count over `&[&[f64]]` with a per-element deref, so it runs scalar
        // at ~5 GB/s (latency-bound, far below memory bandwidth). Instead sweep a
        // row TILE across all columns: the per-tile accumulator stays L1-resident
        // and each column's tile slice is a sequential, autovectorizable
        // `dst op= src` pass (addpd / maxpd / minpd / mulpd on baseline SSE2).
        // BIT-IDENTICAL: for a fixed row r the columns are folded left-to-right in
        // the same order with the same `op` and `empty` seed — vectorization
        // parallelizes across DISTINCT rows (lanes), never reassociating a single
        // row's fold. Measured 2.2–2.75x fp-side on 1M x 10 f64 (mean/max/min/prod
        // axis=1), 0 bit-diffs vs the row loop.
        let n = self.len();
        let mut values = vec![empty; n];
        const TILE: usize = 4096;
        let mut start = 0;
        while start < n {
            let end = (start + TILE).min(n);
            for col in &f64_cols {
                let src = &col[start..end];
                let dst = &mut values[start..end];
                for (o, &v) in dst.iter_mut().zip(src) {
                    *o = op(*o, v);
                }
            }
            start = end;
        }

        let index = self.index.clone();
        let column = Column::from_f64_values(values);
        Series::new(name.to_owned(), index, column).map(Some)
    }

    /// Internal: typed Float64 per-row `Fn(&[f64])` reduction (br-frankenpandas-rrf64).
    /// When every row-reduction column is all-valid no-NaN Float64, gather each row's k
    /// values into a REUSED buffer from the contiguous f64 slices and apply `func` — instead
    /// of the generic `reduce_rows`' per-row `Vec<f64>` allocation + per-cell Scalar `to_f64`.
    /// BIT-IDENTICAL for no-NaN Float64: nothing is filtered (no missing), the row buffer is
    /// the same k values in column order, `func` is the same, and the output Scalars are built
    /// the same way. Returns None (→ fall back to `reduce_rows`) if any column isn't no-NaN
    /// Float64 (the missing/empty-row path the generic version handles stays on that path).
    fn reduce_rows_func_f64<F>(&self, func: F, name: &str) -> Result<Option<Series>, FrameError>
    where
        F: Fn(&[f64]) -> f64,
    {
        let numeric_cols = self.numeric_row_reduction_columns();
        if numeric_cols.is_empty() {
            return Ok(None);
        }
        // Each numeric column must be an all-valid Float64 (borrow its slice) or an
        // all-valid Int64 column (materialize the `v as f64` view once). std/var/sem/
        // skew/kurt axis=1 all output Float64 (the moment funcs coerce), so an Int64
        // column is dtype-correct here; the reduction over `v as f64` == over the
        // Scalar values the generic `reduce_rows` fallback would have built, so the
        // output is bit-identical — this just skips that fallback's per-cell Scalar
        // dispatch. Any nullable/other-dtype column returns None (generic path).
        let mut owned: Vec<Vec<f64>> = Vec::new();
        let mut is_owned: Vec<bool> = Vec::with_capacity(numeric_cols.len());
        for &c in &numeric_cols {
            let col = &self.columns[c];
            if col.dtype() == DType::Float64 {
                if col.as_f64_slice().is_none() {
                    return Ok(None);
                }
                is_owned.push(false);
            } else if col.dtype() == DType::Int64 {
                let Some(d) = col.as_i64_slice() else {
                    return Ok(None);
                };
                owned.push(d.iter().map(|&v| v as f64).collect());
                is_owned.push(true);
            } else {
                return Ok(None);
            }
        }
        let mut owned_iter = owned.iter();
        let f64_cols: Vec<&[f64]> = numeric_cols
            .iter()
            .zip(&is_owned)
            .map(|(&c, &owned_flag)| {
                if owned_flag {
                    owned_iter
                        .next()
                        .expect("one owned vec per Int64 column")
                        .as_slice()
                } else {
                    self.columns[c]
                        .as_f64_slice()
                        .expect("Float64 column checked all-valid above")
                }
            })
            .collect();
        let k = f64_cols.len();
        // Typed f64 output (sister to reduce_rows_f64): collect each row's reduced
        // value into a Vec<f64> and ingest via from_f64_values, instead of boxing a
        // Vec<Scalar::Float64> (32B/elem) then re-inferring dtype in from_values.
        // Bit-identical: from_f64_values marks NaN rows missing exactly as
        // from_values does for a Scalar::Float64(NaN) (both => missing), and present
        // rows store the same Float64(v). Serves std/var/sem/skew/kurt axis=1.
        let mut out = Vec::with_capacity(self.len());
        let mut buf = vec![0.0_f64; k];
        for row_idx in 0..self.len() {
            for (j, col) in f64_cols.iter().enumerate() {
                buf[j] = col[row_idx];
            }
            out.push(func(&buf));
        }
        let index = self.index.clone();
        let column = Column::from_f64_values(out);
        Series::new(name, index, column).map(Some)
    }

    /// All-valid Float64 fast path for the two-pass axis=1 moment family.
    ///
    /// Finish one 4096-row tile before advancing, so the row means stay
    /// L1-sized instead of occupying a second output-sized buffer. For each
    /// row, both the mean fold and the M2 fold retain the exact left-to-right
    /// column order used by `row_sample_var`; SIMD lanes operate only across
    /// independent rows, so variance/std/sem remain bit-identical.
    fn reduce_rows_moment_f64<F>(&self, finish: F, name: &str) -> Result<Option<Series>, FrameError>
    where
        F: Fn(f64, f64) -> f64 + Sync,
    {
        let numeric_cols = self.numeric_row_reduction_columns();
        if numeric_cols.is_empty() {
            return Ok(None);
        }
        let Some(f64_cols) = numeric_cols
            .iter()
            .map(|&column_name| {
                let column = &self.columns[column_name];
                if column.dtype() == DType::Float64 {
                    column.as_f64_slice()
                } else {
                    None
                }
            })
            .collect::<Option<Vec<_>>>()
        else {
            return Ok(None);
        };

        const TILE: usize = 4096;
        let count = f64_cols.len() as f64;
        let mut moments = vec![0.0_f64; self.len()];
        let reduce_range = |global_start: usize, output: &mut [f64]| {
            let mut means = vec![0.0_f64; TILE.min(output.len())];
            let mut local_start = 0;
            while local_start < output.len() {
                let local_end = (local_start + TILE).min(output.len());
                let global_end = global_start + local_end;
                let tile_means = &mut means[..local_end - local_start];
                tile_means.fill(0.0);
                for column in &f64_cols {
                    for (mean, value) in tile_means
                        .iter_mut()
                        .zip(&column[global_start + local_start..global_end])
                    {
                        *mean += *value;
                    }
                }
                for mean in tile_means.iter_mut() {
                    *mean /= count;
                }

                let tile_moments = &mut output[local_start..local_end];
                for column in &f64_cols {
                    for ((m2, mean), value) in tile_moments
                        .iter_mut()
                        .zip(tile_means.iter())
                        .zip(&column[global_start + local_start..global_end])
                    {
                        *m2 += (*value - *mean).powi(2);
                    }
                }
                for moment in tile_moments {
                    *moment = finish(*moment, count);
                }
                local_start = local_end;
            }
        };

        // Rows are independent, while each worker retains the exact serial
        // left-to-right column folds within its disjoint output range. Moments
        // are light enough that thread launch only pays on large frames.
        const PAR_MIN_ROWS: usize = 200_000;
        const PAR_MIN_PER_WORKER: usize = 65_536;
        let workers = if self.len() >= PAR_MIN_ROWS {
            fp_columnar::cached_available_parallelism()
                .min(16)
                .min(self.len() / PAR_MIN_PER_WORKER)
                .max(1)
        } else {
            1
        };
        if workers >= 2 {
            let chunk = self.len().div_ceil(workers);
            let reduce_range = &reduce_range;
            std::thread::scope(|scope| {
                for (worker, output) in moments.chunks_mut(chunk).enumerate() {
                    let global_start = worker * chunk;
                    scope.spawn(move || reduce_range(global_start, output));
                }
            });
        } else {
            reduce_range(0, &mut moments);
        }

        let index = self.index.clone();
        let column = Column::from_f64_values(moments);
        Series::new(name, index, column).map(Some)
    }

    /// Internal: reduce each row across numeric columns using a closure.
    fn reduce_rows<F>(&self, func: F, name: &str, empty: Scalar) -> Result<Series, FrameError>
    where
        F: Fn(&[f64]) -> f64,
    {
        // Per br-frankenpandas-d3tdy: pandas treats Bool columns as 0/1
        // numerics in row-axis reductions. Excluding Bool silently dropped
        // valid contributions; Bool.to_f64() already returns Ok(0.0/1.0),
        // so allowing the dtype through the filter is sufficient.
        let numeric_cols = self.numeric_row_reduction_columns();

        // Typed all-valid fast path INCLUDING Int64: when every numeric column is an
        // all-valid Float64 (borrow its &[f64]) or all-valid Int64 (materialize the
        // `v as f64` view once) — and at least one is Int64 (a pure-Float64 frame
        // keeps the Float64-only path below, which also serves nullable Float64) —
        // gather each row's PRESENT values and reduce. `!x.is_nan()` is the skipna
        // filter: it drops a Float64 NaN cell (== the generic `is_missing()` drop for
        // an all-valid-but-NaN Float64) and is a no-op for an Int64-derived value
        // (never NaN, always present). Bit-identical to the generic per-cell loop:
        // `to_f64(Int64(v)) == v as f64`, same skipna drop, same empty-row -> `empty`,
        // same `Float64(func(present))`. A nullable / other-dtype (incl. Bool) column
        // sets `ok=false` and falls through to the paths below.
        if !numeric_cols.is_empty() {
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(numeric_cols.len());
            let mut has_i64 = false;
            let mut ok = true;
            for &c in &numeric_cols {
                let col = &self.columns[c];
                if col.dtype() == DType::Float64 {
                    if col.as_f64_slice().is_none() {
                        ok = false;
                        break;
                    }
                    is_owned.push(false);
                } else if col.dtype() == DType::Int64 {
                    match col.as_i64_slice() {
                        Some(d) => {
                            owned.push(d.iter().map(|&v| v as f64).collect());
                            is_owned.push(true);
                            has_i64 = true;
                        }
                        None => {
                            ok = false;
                            break;
                        }
                    }
                } else {
                    ok = false;
                    break;
                }
            }
            if ok && has_i64 {
                let mut owned_iter = owned.iter();
                let f64_cols: Vec<&[f64]> = numeric_cols
                    .iter()
                    .zip(&is_owned)
                    .map(|(&c, &owned_flag)| {
                        if owned_flag {
                            owned_iter
                                .next()
                                .expect("one owned vec per Int64 column")
                                .as_slice()
                        } else {
                            self.columns[c]
                                .as_f64_slice()
                                .expect("Float64 column checked all-valid above")
                        }
                    })
                    .collect();
                let mut values = Vec::with_capacity(self.len());
                let mut buf: Vec<f64> = Vec::with_capacity(f64_cols.len());
                for row_idx in 0..self.len() {
                    buf.clear();
                    for col in &f64_cols {
                        let x = col[row_idx];
                        if !x.is_nan() {
                            buf.push(x);
                        }
                    }
                    if buf.is_empty() {
                        values.push(empty.clone());
                    } else {
                        values.push(Scalar::Float64(func(&buf)));
                    }
                }
                let index = self.index.clone();
                let column = Column::from_values(values)?;
                return Series::new(name.to_owned(), index, column);
            }
        }

        // Typed Float64 fast path: when every numeric column is Float64 (the
        // common all-numeric frame, INCLUDING nullable — the all-valid axis=1
        // accumulators bail on any NaN, so a nullable frame fell to this method's
        // per-cell `values()[idx]` Scalar materialization, ~3x slower than pandas).
        // Gather each row's PRESENT values (validity-set AND not-NaN == the
        // `is_missing()` skipna filter below) from the raw &[f64] + validity.
        // Bit-identical: same skipna drop, same empty-row -> `empty`, same
        // `Float64(func(present))`.
        if !numeric_cols.is_empty()
            && numeric_cols
                .iter()
                .all(|&c| self.columns[c].dtype() == DType::Float64)
            && let Some(typed) = numeric_cols
                .iter()
                .map(|&c| self.columns[c].as_f64_slice_with_validity())
                .collect::<Option<Vec<_>>>()
        {
            let mut values = Vec::with_capacity(self.len());
            let mut buf: Vec<f64> = Vec::with_capacity(typed.len());
            for row_idx in 0..self.len() {
                buf.clear();
                for (data, valid) in &typed {
                    if valid.get(row_idx) && !data[row_idx].is_nan() {
                        buf.push(data[row_idx]);
                    }
                }
                if buf.is_empty() {
                    values.push(empty.clone());
                } else {
                    values.push(Scalar::Float64(func(&buf)));
                }
            }
            let index = self.index.clone();
            let column = Column::from_values(values)?;
            return Series::new(name.to_owned(), index, column);
        }

        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            // pandas df.<reducer>(axis=1) defaults to skipna=True: every NaN /
            // missing cell is dropped before the reduction. `to_f64().ok()` alone
            // only drops Null — a stored `Float64(NaN)` (validity-set but NaN, e.g.
            // from `0.0/0.0` or an explicit np.nan) returns `Ok(NaN)` and would
            // poison the row to NaN. Gate on `is_missing()` (true for both Null AND
            // Float64(NaN)) so the NaN is skipped, matching pandas — a row of
            // `[1.0, NaN, 2.0]` sums to 3.0, not NaN. An all-missing row reduces to
            // `empty` (sum -> 0, prod -> 1, every other reducer -> NaN, matching
            // pandas' min_count=0 identity / all-NaN-yields-NaN behavior).
            let row_vals: Vec<f64> = numeric_cols
                .iter()
                .filter_map(|&col_name| {
                    let v = &self.columns[col_name].values()[row_idx];
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect();
            if row_vals.is_empty() {
                values.push(empty.clone());
            } else {
                values.push(Scalar::Float64(func(&row_vals)));
            }
        }
        // Per br-frankenpandas-8no14: pandas df.<reducer>(axis=1) preserves
        // df.index.name on the per-row result. Covers sum_axis1, mean_axis1,
        // min_axis1, max_axis1, std_axis1, var_axis1, etc.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new(name.to_owned(), index, column)
    }

    fn row_sample_var(vals: &[f64]) -> f64 {
        let n = vals.len() as f64;
        if n < 2.0 {
            return f64::NAN;
        }
        let mean = vals.iter().sum::<f64>() / n;
        vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (n - 1.0)
    }

    fn row_sem(vals: &[f64]) -> f64 {
        let n = vals.len() as f64;
        if n < 2.0 {
            return f64::NAN;
        }
        Self::row_sample_var(vals).sqrt() / n.sqrt()
    }

    fn row_skew(vals: &[f64]) -> f64 {
        let count = vals.len();
        if count < 3 {
            return f64::NAN;
        }
        let n = count as f64;
        let mean = vals.iter().sum::<f64>() / n;
        let m2 = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>();
        let m3 = vals.iter().map(|v| (v - mean).powi(3)).sum::<f64>();
        let s2 = m2 / (n - 1.0);
        if s2 == 0.0 {
            return 0.0;
        }
        let s3 = s2.powf(1.5);
        (n / ((n - 1.0) * (n - 2.0))) * (m3 / s3)
    }

    fn row_kurtosis(vals: &[f64]) -> f64 {
        let count = vals.len();
        if count < 4 {
            return f64::NAN;
        }
        let n = count as f64;
        let mean = vals.iter().sum::<f64>() / n;
        let m2 = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>();
        let m4 = vals.iter().map(|v| (v - mean).powi(4)).sum::<f64>();
        let s2 = m2 / (n - 1.0);
        if s2 == 0.0 {
            return 0.0;
        }
        let adj = (n * (n + 1.0)) / ((n - 1.0) * (n - 2.0) * (n - 3.0));
        let sub = (3.0 * (n - 1.0).powi(2)) / ((n - 2.0) * (n - 3.0));
        adj * (m4 / (s2 * s2)) - sub
    }

    /// Sum across columns per row.
    ///
    /// Matches `pd.DataFrame.sum(axis=1)`.
    pub fn sum_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-c0g3x: reduce_rows filters out Timedelta64
        // columns. For uniformly-Timedelta DataFrames, route to a
        // Timedelta-typed row reducer.
        if self.all_columns_timedelta() {
            return self.reduce_rows_timedelta(
                |ns_vals| {
                    let mut acc: i64 = 0;
                    for v in ns_vals {
                        acc = Timedelta::add(acc, *v);
                    }
                    if ns_vals.is_empty() {
                        Timedelta::NAT
                    } else {
                        acc
                    }
                },
                "sum",
            );
        }
        if let Some(series) =
            self.reduce_rows_int64("sum", 0, |acc, value| acc.wrapping_add(value))?
        {
            return Ok(series);
        }
        if let Some(series) = self.reduce_rows_f64("sum", 0.0, |acc, v| acc + v)? {
            return Ok(series);
        }
        self.reduce_rows(|vals| vals.iter().sum(), "sum", Scalar::Float64(0.0))
    }

    /// Mean across columns per row.
    ///
    /// Matches `pd.DataFrame.mean(axis=1)`.
    pub fn mean_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-c0g3x: sister to sum_axis1 above.
        if self.all_columns_timedelta() {
            return self.reduce_rows_timedelta(
                |ns_vals| {
                    if ns_vals.is_empty() {
                        return Timedelta::NAT;
                    }
                    let sum: f64 = ns_vals.iter().map(|v| *v as f64).sum();
                    let mean = sum / ns_vals.len() as f64;
                    if !mean.is_finite() {
                        Timedelta::NAT
                    } else {
                        mean.clamp(i64::MIN as f64, i64::MAX as f64) as i64
                    }
                },
                "mean",
            );
        }
        // Typed Float64 row-mean (br-frankenpandas-rrf64): when every row-reduction column
        // is all-valid no-NaN Float64, the per-row count is exactly the column count, so
        // mean = (Σ col[row]) / k — bit-identical to the Scalar path's `sum/len` (same
        // column-order left-to-right sum, same divisor) — skipping the per-row Scalar gather.
        let numeric_cols = self.numeric_row_reduction_columns();
        if !numeric_cols.is_empty()
            && let Some(f64_cols) = numeric_cols
                .iter()
                .map(|&c| {
                    let col = &self.columns[c];
                    if col.dtype() == DType::Float64 {
                        col.as_f64_slice()
                    } else {
                        None
                    }
                })
                .collect::<Option<Vec<_>>>()
        {
            let k = f64_cols.len() as f64;
            let n = self.len();
            // Tiled column-streaming row-sum then /k (see reduce_rows_f64's
            // tiled-reduction note). Each row's sum is folded in the
            // identical left-to-right column order, so bit-identical to the
            // row-at-a-time `acc += col[r]; acc / k`; the tiled sweep just lets the
            // `dst += src` and `dst /= k` passes vectorize with an L1-resident
            // accumulator instead of the column-strided scalar row loop.
            let mut values = vec![0.0_f64; n];
            const TILE: usize = 4096;
            let mut start = 0;
            while start < n {
                let end = (start + TILE).min(n);
                for col in &f64_cols {
                    let src = &col[start..end];
                    let dst = &mut values[start..end];
                    for (o, &v) in dst.iter_mut().zip(src) {
                        *o += v;
                    }
                }
                for o in &mut values[start..end] {
                    *o /= k;
                }
                start = end;
            }
            let index = self.index.clone();
            return Series::new("mean", index, Column::from_f64_values(values));
        }
        self.reduce_rows(
            |vals| vals.iter().sum::<f64>() / vals.len() as f64,
            "mean",
            Scalar::Null(NullKind::NaN),
        )
    }

    /// Minimum across columns per row.
    ///
    /// Matches `pd.DataFrame.min(axis=1)`.
    pub fn min_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-c0g3x: sister to sum_axis1 above.
        if self.all_columns_timedelta() {
            return self.reduce_rows_timedelta(
                |ns_vals| ns_vals.iter().copied().min().unwrap_or(Timedelta::NAT),
                "min",
            );
        }
        if let Some(series) =
            self.reduce_rows_int64("min", i64::MAX, |acc, value| acc.min(value))?
        {
            return Ok(series);
        }
        // Typed Float64 row-min (br-frankenpandas-rrf64): same fold as the Scalar path
        // (start INFINITY, f64::min, column order), bit-identical for no-NaN Float64.
        if let Some(series) = self.reduce_rows_f64("min", f64::INFINITY, f64::min)? {
            return Ok(series);
        }
        self.reduce_rows(
            |vals| vals.iter().copied().fold(f64::INFINITY, f64::min),
            "min",
            Scalar::Null(NullKind::NaN),
        )
    }

    /// Apply a custom function to each row of the DataFrame.
    ///
    /// Matches `pd.DataFrame.apply(func, axis=1)`. The function receives
    /// a slice of `Scalar` values representing the row (in `column_order`)
    /// and should return a single `Scalar` result.
    pub fn apply_rows<F>(&self, func: F, name: &str) -> Result<Series, FrameError>
    where
        F: Fn(&[Scalar]) -> Scalar,
    {
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let row: Vec<Scalar> = self
                .column_order
                .iter()
                .map(|col_name| self.columns[col_name].values()[row_idx].clone())
                .collect();
            values.push(func(&row));
        }
        // Per br-frankenpandas-4oeba: pandas df.apply(func, axis=1) preserves
        // df.index.name on the row-wise result.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new(name, index, column)
    }

    /// Maximum across columns per row.
    ///
    /// Matches `pd.DataFrame.max(axis=1)`.
    pub fn max_axis1(&self) -> Result<Series, FrameError> {
        // Per br-frankenpandas-c0g3x: sister to sum_axis1 above.
        if self.all_columns_timedelta() {
            return self.reduce_rows_timedelta(
                |ns_vals| ns_vals.iter().copied().max().unwrap_or(Timedelta::NAT),
                "max",
            );
        }
        if let Some(series) =
            self.reduce_rows_int64("max", i64::MIN, |acc, value| acc.max(value))?
        {
            return Ok(series);
        }
        // Typed Float64 row-max (br-frankenpandas-rrf64): bit-identical fold (NEG_INFINITY, f64::max).
        if let Some(series) = self.reduce_rows_f64("max", f64::NEG_INFINITY, f64::max)? {
            return Ok(series);
        }
        self.reduce_rows(
            |vals| vals.iter().copied().fold(f64::NEG_INFINITY, f64::max),
            "max",
            Scalar::Null(NullKind::NaN),
        )
    }

    /// Per br-frankenpandas-c0g3x: Timedelta-typed row reducer for axis=1
    /// sum/mean/min/max. Collects ns from Timedelta64 columns per row
    /// (skipping NaT), applies the op, emits Scalar::Timedelta64.
    fn reduce_rows_timedelta<F>(&self, op: F, name: &str) -> Result<Series, FrameError>
    where
        F: Fn(&[i64]) -> i64,
    {
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let mut ns_vals: Vec<i64> = Vec::with_capacity(self.column_order.len());
            for col_name in &self.column_order {
                if let Scalar::Timedelta64(ns) = &self.columns[col_name].values()[row_idx]
                    && *ns != Timedelta::NAT
                {
                    ns_vals.push(*ns);
                }
            }
            values.push(Scalar::Timedelta64(op(&ns_vals)));
        }
        let index = self.index.clone();
        let column = Column::new(DType::Timedelta64, values)?;
        Series::new(name.to_owned(), index, column)
    }

    /// Standard deviation across columns per row.
    ///
    /// Matches `pd.DataFrame.std(axis=1)`.
    pub fn std_axis1(&self) -> Result<Series, FrameError> {
        if let Some(s) = self.reduce_rows_moment_f64(|m2, n| (m2 / (n - 1.0)).sqrt(), "std")? {
            return Ok(s);
        }
        if let Some(s) =
            self.reduce_rows_func_f64(|vals| Self::row_sample_var(vals).sqrt(), "std")?
        {
            return Ok(s);
        }
        self.reduce_rows(
            |vals| Self::row_sample_var(vals).sqrt(),
            "std",
            Scalar::Null(NullKind::NaN),
        )
    }

    /// Variance across columns per row.
    ///
    /// Matches `pd.DataFrame.var(axis=1)`.
    pub fn var_axis1(&self) -> Result<Series, FrameError> {
        if let Some(s) = self.reduce_rows_moment_f64(|m2, n| m2 / (n - 1.0), "var")? {
            return Ok(s);
        }
        if let Some(s) = self.reduce_rows_func_f64(Self::row_sample_var, "var")? {
            return Ok(s);
        }
        self.reduce_rows(Self::row_sample_var, "var", Scalar::Null(NullKind::NaN))
    }

    /// Standard error of the mean across columns per row.
    ///
    /// Matches `pd.DataFrame.sem(axis=1)`.
    pub fn sem_axis1(&self) -> Result<Series, FrameError> {
        if let Some(s) =
            self.reduce_rows_moment_f64(|m2, n| (m2 / (n - 1.0)).sqrt() / n.sqrt(), "sem")?
        {
            return Ok(s);
        }
        if let Some(s) = self.reduce_rows_func_f64(Self::row_sem, "sem")? {
            return Ok(s);
        }
        self.reduce_rows(Self::row_sem, "sem", Scalar::Null(NullKind::NaN))
    }

    /// Skewness across columns per row.
    ///
    /// Matches `pd.DataFrame.skew(axis=1)`.
    pub fn skew_axis1(&self) -> Result<Series, FrameError> {
        if let Some(s) = self.reduce_rows_func_f64(Self::row_skew, "skew")? {
            return Ok(s);
        }
        self.reduce_rows(Self::row_skew, "skew", Scalar::Null(NullKind::NaN))
    }

    /// Excess kurtosis across columns per row.
    ///
    /// Matches `pd.DataFrame.kurtosis(axis=1)`.
    pub fn kurtosis_axis1(&self) -> Result<Series, FrameError> {
        if let Some(s) = self.reduce_rows_func_f64(Self::row_kurtosis, "kurtosis")? {
            return Ok(s);
        }
        self.reduce_rows(Self::row_kurtosis, "kurtosis", Scalar::Null(NullKind::NaN))
    }

    /// Alias for `kurtosis_axis1()` — pandas exposes
    /// `df.kurt(axis=1)` and `df.kurtosis(axis=1)` as equivalents.
    pub fn kurt_axis1(&self) -> Result<Series, FrameError> {
        self.kurtosis_axis1()
    }

    /// Count of non-null values across columns per row.
    ///
    /// Matches `pd.DataFrame.count(axis=1)`.
    pub fn count_axis1(&self) -> Result<Series, FrameError> {
        // Typed all-present fast path (br-frankenpandas-cntf): if every column exposes a
        // typed all-valid slice (`as_f64_slice` ⇒ no NaN, `as_i64_slice`/`as_bool_slice` ⇒
        // all valid), then NO cell is missing, so every row's non-missing count is exactly
        // the column count — return a constant Int64 column. Bit-identical to the per-cell
        // `is_missing` scan below (same value for every row), skipping 5M is_missing checks.
        if !self.column_order.is_empty()
            && self.column_order.iter().all(|c| {
                let col = &self.columns[c.as_str()];
                col.as_f64_slice().is_some()
                    || col.as_i64_slice().is_some()
                    || col.as_bool_slice().is_some()
            })
        {
            let cnt = self.column_order.len() as i64;
            let index = self.index.clone();
            let column = Column::from_i64_values_owned(vec![cnt; self.len()]);
            return Series::new("count".to_owned(), index, column);
        }
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let cnt = self
                .column_order
                .iter()
                .filter(|col_name| !self.columns[col_name.as_str()].values()[row_idx].is_missing())
                .count();
            values.push(Scalar::Int64(cnt as i64));
        }
        // Per br-frankenpandas-wgkw9: pandas df.count(axis=1) preserves row index name.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("count".to_owned(), index, column)
    }

    /// Whether all non-null values are truthy across columns per row.
    ///
    /// Matches `pd.DataFrame.all(axis=1)`.
    pub fn all_axis1(&self) -> Result<Series, FrameError> {
        // Typed all-Float64 fast path (br-frankenpandas-allf): every column an all-valid
        // no-NaN Float64 (`as_f64_slice`) ⇒ the Scalar truthy arm `v != 0.0 && !v.is_nan()`
        // reduces to `v != 0.0` (no NaN, no missing) — bit-identical — reading contiguous f64
        // buffers instead of materializing 5M Scalars via per-cell `values()`.
        if !self.column_order.is_empty()
            && let Some(f64_cols) = self
                .column_order
                .iter()
                .map(|c| {
                    let col = &self.columns[c.as_str()];
                    if col.dtype() == DType::Float64 {
                        col.as_f64_slice()
                    } else {
                        None
                    }
                })
                .collect::<Option<Vec<_>>>()
        {
            let mut values = Vec::with_capacity(self.len());
            for row_idx in 0..self.len() {
                values.push(f64_cols.iter().all(|col| col[row_idx] != 0.0));
            }
            let index = self.index.clone();
            let column = Column::from_bool_values(values);
            return Series::new("all".to_owned(), index, column);
        }
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let result = self.column_order.iter().all(|col_name| {
                let val = &self.columns[col_name.as_str()].values()[row_idx];
                match val {
                    Scalar::Null(_) => true, // NaN is ignored in all()
                    Scalar::Bool(b) => *b,
                    Scalar::Int64(v) => *v != 0,
                    Scalar::Float64(v) => *v != 0.0 && !v.is_nan(),
                    Scalar::Utf8(s) => !s.is_empty(),
                    Scalar::Timedelta64(v) => *v != 0 && *v != Timedelta::NAT,
                    Scalar::Datetime64(v) => *v != 0 && *v != Timedelta::NAT,
                    Scalar::Period(v) => v.ordinal != 0 && v.ordinal != i64::MIN,
                    Scalar::Interval(_) => true,
                }
            });
            values.push(Scalar::Bool(result));
        }
        // Per br-frankenpandas-tpwlx: pandas df.all(axis=1) preserves row index name.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("all".to_owned(), index, column)
    }

    /// Whether any non-null value is truthy across columns per row.
    ///
    /// Matches `pd.DataFrame.any(axis=1)`.
    pub fn any_axis1(&self) -> Result<Series, FrameError> {
        // Typed all-Float64 fast path (br-frankenpandas-allf): every column all-valid no-NaN
        // Float64 (`as_f64_slice`) ⇒ the Scalar truthy arm `v != 0.0 && !v.is_nan()` reduces
        // to `v != 0.0` (no NaN, no missing) — bit-identical — reading contiguous f64 buffers
        // instead of materializing 5M Scalars via per-cell `values()`.
        if !self.column_order.is_empty()
            && let Some(f64_cols) = self
                .column_order
                .iter()
                .map(|c| {
                    let col = &self.columns[c.as_str()];
                    if col.dtype() == DType::Float64 {
                        col.as_f64_slice()
                    } else {
                        None
                    }
                })
                .collect::<Option<Vec<_>>>()
        {
            let mut values = Vec::with_capacity(self.len());
            for row_idx in 0..self.len() {
                values.push(f64_cols.iter().any(|col| col[row_idx] != 0.0));
            }
            let index = self.index.clone();
            let column = Column::from_bool_values(values);
            return Series::new("any".to_owned(), index, column);
        }
        let mut values = Vec::with_capacity(self.len());
        for row_idx in 0..self.len() {
            let result = self.column_order.iter().any(|col_name| {
                let val = &self.columns[col_name.as_str()].values()[row_idx];
                match val {
                    Scalar::Null(_) => false,
                    Scalar::Bool(b) => *b,
                    Scalar::Int64(v) => *v != 0,
                    Scalar::Float64(v) => *v != 0.0 && !v.is_nan(),
                    Scalar::Utf8(s) => !s.is_empty(),
                    Scalar::Timedelta64(v) => *v != 0 && *v != Timedelta::NAT,
                    Scalar::Datetime64(v) => *v != 0 && *v != Timedelta::NAT,
                    Scalar::Period(v) => v.ordinal != 0 && v.ordinal != i64::MIN,
                    Scalar::Interval(_) => true,
                }
            });
            values.push(Scalar::Bool(result));
        }
        // Per br-frankenpandas-29wua: pandas df.any(axis=1) preserves row index name.
        let index = self.index.clone();
        let column = Column::from_values(values)?;
        Series::new("any".to_owned(), index, column)
    }

    /// Median across columns per row.
    ///
    /// Matches `pd.DataFrame.median(axis=1)`.
    /// Per-row quantile across numeric columns (axis=1).
    ///
    /// Matches `pd.DataFrame.quantile(q, axis=1)`. For each row the
    /// numeric column values are collected (skipping non-numeric and
    /// missing entries) and their linear-interpolation quantile is
    /// returned. `q` must lie in `[0.0, 1.0]`. Rows with no numeric
    /// entries emit `Null(NaN)`.
    pub fn quantile_axis1(&self, q: f64) -> Result<Series, FrameError> {
        if !(0.0..=1.0).contains(&q) {
            return Err(FrameError::CompatibilityRejected(format!(
                "quantile must be between 0 and 1, got {q}"
            )));
        }
        let len = self.index.labels().len();
        // pandas df.quantile(q, axis=1) on a uniformly-Timedelta DataFrame
        // returns Timedelta per row. The numeric-only Int64/Float64 filter
        // silently drops Timedelta columns, leaving each row's nums empty
        // and emitting Null(NaN). Sister to the cum*_axis1 (br-bktp1) and
        // sum/mean/min/max_axis1 (br-c0g3x) Timedelta surgeries.
        let all_td = self.all_columns_timedelta();
        let mut out = Vec::with_capacity(len);
        for row_idx in 0..len {
            if all_td {
                let mut td_vals: Vec<f64> = Vec::new();
                for name in &self.column_order {
                    if let Scalar::Timedelta64(ns) = &self.columns[name].values()[row_idx]
                        && *ns != Timedelta::NAT
                    {
                        td_vals.push(*ns as f64);
                    }
                }
                if td_vals.is_empty() {
                    out.push(Scalar::Timedelta64(Timedelta::NAT));
                    continue;
                }
                td_vals.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                let n = td_vals.len();
                let qns = if n == 1 {
                    td_vals[0]
                } else {
                    let pos = q * (n - 1) as f64;
                    let lo = pos.floor() as usize;
                    let hi = pos.ceil() as usize;
                    if lo == hi {
                        td_vals[lo]
                    } else {
                        let weight = pos - lo as f64;
                        td_vals[lo] + (td_vals[hi] - td_vals[lo]) * weight
                    }
                };
                let clamped = qns.clamp(i64::MIN as f64, i64::MAX as f64);
                out.push(Scalar::Timedelta64(clamped as i64));
                continue;
            }
            let mut nums: Vec<f64> = Vec::new();
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.dtype() != DType::Int64 && col.dtype() != DType::Float64 {
                    continue;
                }
                let v = &col.values()[row_idx];
                if v.is_missing() {
                    continue;
                }
                if let Ok(f) = v.to_f64()
                    && !f.is_nan()
                {
                    nums.push(f);
                }
            }
            if nums.is_empty() {
                out.push(Scalar::Null(NullKind::NaN));
                continue;
            }
            nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let n = nums.len();
            if n == 1 {
                out.push(Scalar::Float64(nums[0]));
                continue;
            }
            let pos = q * (n - 1) as f64;
            let lo = pos.floor() as usize;
            let hi = pos.ceil() as usize;
            let value = if lo == hi {
                nums[lo]
            } else {
                let weight = pos - lo as f64;
                nums[lo] + (nums[hi] - nums[lo]) * weight
            };
            out.push(Scalar::Float64(value));
        }
        // Per br-frankenpandas-jhhml: pandas df.quantile(q, axis=1) preserves row index name.
        let index = self.index.clone();
        let column = Column::from_values(out)?;
        Series::new("quantile", index, column)
    }

    /// Per-row index label of the first smallest numeric value.
    ///
    /// Matches `pd.DataFrame.idxmin(axis=1)` combined with positional
    /// column lookup. Returns the column-name Series entry for each
    /// row's argmin; rows with no numeric entries emit Null(NaN).
    pub fn argmin_axis1(&self) -> Result<Series, FrameError> {
        self.arg_extrema_axis1(false)
    }

    /// Per-row index label of the first largest numeric value.
    ///
    /// Matches `pd.DataFrame.idxmax(axis=1)`.
    pub fn argmax_axis1(&self) -> Result<Series, FrameError> {
        self.arg_extrema_axis1(true)
    }

    fn arg_extrema_axis1(&self, largest: bool) -> Result<Series, FrameError> {
        // Typed-f64 fast path (same lever as idxmax/idxmin_axis1): all all-valid
        // Float64 columns -> raw f64 compare over hoisted &[f64] slices (no
        // per-cell BTreeMap + Scalar + to_f64). First-wins on ties, NaN skipped.
        // Bit-identical to the generic numeric path (all-Float64 => nothing
        // skipped as non-numeric).
        'f64: {
            // Each column is an all-valid Float64 (borrow; the kernel skips NaN
            // inline, matching the generic `is_missing()` skip) or an all-valid Int64
            // (materialize `v as f64` once — never NaN). The winning column (hence the
            // emitted label) is chosen by the same comparisons the generic to_f64 path
            // makes, so it is bit-identical; the label output is dtype-independent.
            // Nullable / other-dtype columns break to the generic path.
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(self.column_order.len());
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.as_f64_slice().is_some() {
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'f64;
                }
            }
            if is_owned.is_empty() {
                break 'f64;
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = self
                .column_order
                .iter()
                .zip(&is_owned)
                .map(|(name, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[name]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            // Branchless: track max(sign*v) — for min, sign=-1 flips it (the col
            // with the smallest v has the largest -v). 1.0*v optimizes to v, so
            // the common argmax path matches idxmax's speed. First-wins on ties
            // (strict >), NaN skipped — bit-identical. Now parallel contiguous-Utf8
            // build via the shared builder (same kernel, row order preserved).
            let sign = if largest { 1.0_f64 } else { -1.0_f64 };
            let label = if largest { "idxmax" } else { "idxmin" };
            return self.arg_axis1_names_parallel(&col_f64, label, move |cols, row| {
                let mut best = f64::NEG_INFINITY;
                let mut best_col: Option<usize> = None;
                for (ci, c) in cols.iter().enumerate() {
                    let v = sign * c[row];
                    if v.is_nan() {
                        continue;
                    }
                    if v > best {
                        best = v;
                        best_col = Some(ci);
                    }
                }
                best_col
            });
        }
        let len = self.index.labels().len();
        let mut out = Vec::with_capacity(len);
        for row_idx in 0..len {
            let mut best: Option<(&str, f64)> = None;
            for name in &self.column_order {
                let col = &self.columns[name];
                if col.dtype() != DType::Int64 && col.dtype() != DType::Float64 {
                    continue;
                }
                let v = &col.values()[row_idx];
                if v.is_missing() {
                    continue;
                }
                if let Ok(f) = v.to_f64()
                    && !f.is_nan()
                {
                    let take = match best {
                        None => true,
                        Some((_, cur)) if largest => f > cur,
                        Some((_, cur)) => f < cur,
                    };
                    if take {
                        best = Some((name.as_str(), f));
                    }
                }
            }
            match best {
                Some((name, _)) => out.push(Scalar::Utf8(name.to_owned())),
                None => out.push(Scalar::Null(NullKind::NaN)),
            }
        }
        let label = if largest { "idxmax" } else { "idxmin" };
        // Per br-frankenpandas-nbpsb: pandas df.idxmin(axis=1)/idxmax(axis=1)
        // preserve row-axis name.
        let index = self.index.clone();
        let column = Column::from_values(out)?;
        Series::new(label, index, column)
    }

    pub fn median_axis1(&self) -> Result<Series, FrameError> {
        // Sorting-network fast path (all-Float64, no-NaN, small column count): take
        // each row's median via a branchless Batcher odd-even sorting network — a
        // FIXED sequence of min/max compare-exchanges over a stack buffer — instead of
        // the per-row `Vec::to_vec()` heap alloc + `select_nth_unstable_by` closure
        // quickselect below. The network's compare-exchanges pipeline (no data-
        // dependent branches, no allocation, no comparator indirection); for a small
        // column count k that beats quickselect-with-alloc by 2-3.6x. Bit-identical to
        // the quickselect path for no-NaN rows: a full sort yields the SAME two middle
        // order statistics (buf[mid] for odd k, (buf[mid-1]+buf[mid])/2 for even k).
        if let Some(series) = self.median_axis1_sort_network()? {
            return Ok(series);
        }
        // Typed all-Float64 fast path (sister to std/var/skew axis=1): gather the
        // column f64 slices once (no per-row Scalar gather) and take the median by
        // QUICKSELECT — median needs only the middle order statistic(s), not a full
        // per-row sort. `select_nth_unstable_by` is O(k) avg vs O(k log k); for an
        // even count the lower-middle is the max of the left partition. Bit-
        // identical to the full-sort closure below for non-NaN rows (same two
        // middle values); a NaN/missing-bearing or non-Float64 frame returns None
        // and keeps the generic per-row path. Handles the large-k tail where the
        // network's O(k log^2 k) comparators overtake select_nth's O(k) (crossover ~k=26).
        if let Some(series) = self.reduce_rows_func_f64(
            |vals| {
                let n = vals.len();
                if n == 0 {
                    return f64::NAN;
                }
                let mut v = vals.to_vec();
                let mid = n / 2;
                let cmp = |a: &f64, b: &f64| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal);
                let (_, upper, _) = v.select_nth_unstable_by(mid, cmp);
                let upper = *upper;
                if n % 2 == 1 {
                    upper
                } else {
                    let lower = v[..mid].iter().copied().fold(f64::NEG_INFINITY, f64::max);
                    (lower + upper) / 2.0
                }
            },
            "median",
        )? {
            return Ok(series);
        }
        self.reduce_rows(
            |vals| {
                let mut sorted = vals.to_vec();
                sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                let n = sorted.len();
                if n % 2 == 0 {
                    (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
                } else {
                    sorted[n / 2]
                }
            },
            "median",
            Scalar::Null(NullKind::NaN),
        )
    }

    /// Sorting-network median for `median_axis1` (see its doc). Returns `None` (caller
    /// falls back to the quickselect path) unless every row-reduction column is a
    /// no-NaN all-valid Float64 slice and the column count `k` is in `[2, 20]` — the
    /// range where the fixed Batcher network measured 2-3.6x faster than the per-row
    /// `to_vec()` + `select_nth_unstable_by` quickselect. Bit-identical to that path
    /// for the rows it handles: a full sort exposes the same middle order statistics
    /// (odd k → `buf[mid]`; even k → `(buf[mid-1] + buf[mid]) / 2`).
    fn median_axis1_sort_network(&self) -> Result<Option<Series>, FrameError> {
        let numeric_cols = self.numeric_row_reduction_columns();
        if numeric_cols.is_empty() {
            return Ok(None);
        }
        // Each numeric column must be an all-valid Float64 (borrow its slice) or an
        // all-valid Int64 column (materialize the `v as f64` view once). Row median
        // always outputs Float64 (nanmedian coerces via to_f64), so an Int64 column
        // is dtype-correct; the sorting network over `v as f64` exposes the same
        // middle order statistics as the generic quickselect over the Scalar values
        // (`to_f64(Int64(v)) == v as f64`, order stats depend only on values), so the
        // output is bit-identical — this just skips the generic path's per-cell Scalar
        // dispatch. Nullable / other-dtype columns return None (generic path).
        let mut owned: Vec<Vec<f64>> = Vec::new();
        let mut is_owned: Vec<bool> = Vec::with_capacity(numeric_cols.len());
        for &c in &numeric_cols {
            let col = &self.columns[c];
            if col.dtype() == DType::Float64 {
                if col.as_f64_slice().is_none() {
                    return Ok(None);
                }
                is_owned.push(false);
            } else if col.dtype() == DType::Int64 {
                let Some(d) = col.as_i64_slice() else {
                    return Ok(None);
                };
                owned.push(d.iter().map(|&v| v as f64).collect());
                is_owned.push(true);
            } else {
                return Ok(None);
            }
        }
        let mut owned_iter = owned.iter();
        let f64_cols: Vec<&[f64]> = numeric_cols
            .iter()
            .zip(&is_owned)
            .map(|(&c, &owned_flag)| {
                if owned_flag {
                    owned_iter
                        .next()
                        .expect("one owned vec per Int64 column")
                        .as_slice()
                } else {
                    self.columns[c]
                        .as_f64_slice()
                        .expect("Float64 column checked all-valid above")
                }
            })
            .collect();
        let k = f64_cols.len();
        const NETWORK_MAX_K: usize = 20;
        if !(2..=NETWORK_MAX_K).contains(&k) {
            return Ok(None);
        }
        let net = median_sort_network(k);
        let n = self.len();
        let mid = k / 2;
        let odd = k % 2 == 1;
        let mut values = vec![0.0_f64; n];
        let mut buf = [0.0_f64; NETWORK_MAX_K];
        for row in 0..n {
            for (j, col) in f64_cols.iter().enumerate() {
                buf[j] = col[row];
            }
            // Branchless compare-exchange sort of buf[..k] (min/max lower to
            // minsd/maxsd on baseline SSE2). Comparators are independent within a
            // Batcher layer, so the exchanges pipeline instead of forming the serial
            // dependency chain a bubble sort would.
            for &(i, j) in &net {
                let (i, j) = (i as usize, j as usize);
                let lo = buf[i].min(buf[j]);
                let hi = buf[i].max(buf[j]);
                buf[i] = lo;
                buf[j] = hi;
            }
            values[row] = if odd {
                buf[mid]
            } else {
                (buf[mid - 1] + buf[mid]) / 2.0
            };
        }
        let index = self.index.clone();
        let column = Column::from_f64_values(values);
        Series::new("median", index, column).map(Some)
    }

    /// Product across columns per row.
    ///
    /// Matches `pd.DataFrame.prod(axis=1)`.
    pub fn prod_axis1(&self) -> Result<Series, FrameError> {
        if let Some(series) =
            self.reduce_rows_int64("prod", 1, |acc, value| acc.wrapping_mul(value))?
        {
            return Ok(series);
        }
        // Typed Float64 row-prod (br-frankenpandas-rrf64): bit-identical to vals.iter().product()
        // (start 1.0, multiply in column order).
        if let Some(series) = self.reduce_rows_f64("prod", 1.0, |acc, v| acc * v)? {
            return Ok(series);
        }
        self.reduce_rows(|vals| vals.iter().product(), "prod", Scalar::Float64(1.0))
    }

    /// Internal: extract a named column as a Series.
    fn column_as_series(&self, name: &str) -> Result<Series, FrameError> {
        let col = self.column(name).ok_or_else(|| {
            FrameError::CompatibilityRejected(format!("column not found: {name}"))
        })?;
        Series::new(name.to_string(), self.index.clone(), col.clone())
    }

    // ── DataFrame element-wise operations ──

    /// Cumulative sum per column.
    ///
    /// Matches `pd.DataFrame.cumsum()`.
    pub fn cumsum(&self) -> Result<Self, FrameError> {
        self.apply_cum_f64("cumsum", 0.0, |a, v| a + v, |s| s.cumsum())
    }

    /// Cumulative product per column.
    ///
    /// Matches `pd.DataFrame.cumprod()`.
    pub fn cumprod(&self) -> Result<Self, FrameError> {
        self.apply_cum_f64("cumprod", 1.0, |a, v| a * v, |s| s.cumprod())
    }

    /// Cumulative maximum per column.
    ///
    /// Matches `pd.DataFrame.cummax()`.
    pub fn cummax(&self) -> Result<Self, FrameError> {
        self.apply_cum_f64(
            "cummax",
            f64::NEG_INFINITY,
            |a, v| if v > a { v } else { a },
            |s| s.cummax(),
        )
    }

    /// Cumulative minimum per column.
    ///
    /// Matches `pd.DataFrame.cummin()`.
    pub fn cummin(&self) -> Result<Self, FrameError> {
        self.apply_cum_f64(
            "cummin",
            f64::INFINITY,
            |a, v| if v < a { v } else { a },
            |s| s.cummin(),
        )
    }

    /// Per-column cumulative sum with an explicit `skipna`, matching
    /// `pd.DataFrame.cumsum(axis=0, skipna=...)`. `skipna=false` propagates the
    /// first NaN/NaT down each column (br-frankenpandas-tlhd6 follow-up).
    pub fn cumsum_with_skipna(&self, skipna: bool) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.cumsum_with_skipna(skipna))
    }

    /// Per-column cumulative product with an explicit `skipna`
    /// (see [`cumsum_with_skipna`](Self::cumsum_with_skipna)).
    pub fn cumprod_with_skipna(&self, skipna: bool) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.cumprod_with_skipna(skipna))
    }

    /// Per-column cumulative maximum with an explicit `skipna`
    /// (see [`cumsum_with_skipna`](Self::cumsum_with_skipna)).
    pub fn cummax_with_skipna(&self, skipna: bool) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.cummax_with_skipna(skipna))
    }

    /// Per-column cumulative minimum with an explicit `skipna`
    /// (see [`cumsum_with_skipna`](Self::cumsum_with_skipna)).
    pub fn cummin_with_skipna(&self, skipna: bool) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.cummin_with_skipna(skipna))
    }

    fn cumulative_axis1<F>(&self, init: f64, op: F) -> Result<Self, FrameError>
    where
        F: Fn(f64, f64) -> f64 + Copy,
    {
        // Typed fast path: when EVERY column is an all-valid no-NaN Float64 (borrow
        // its slice) or an all-valid Int64 (materialize the `v as f64` view once),
        // there is nothing missing, so each output column is a typed row-cumulative
        // `Vec<f64>` (same column-order `op`, same `init` per row) ingested via
        // `from_f64_values` — skipping the per-cell `.values()` Scalar dispatch, the
        // `Scalar::Float64(acc)` boxing, and `Column::new`'s re-inference. Output
        // stays Float64 (this helper always emits Float64), so it is dtype-correct.
        // Bit-identical: for all-valid cells the generic branch always takes its
        // `else` arm (`acc = op(acc, to_f64); push Float64(acc)`), and `to_f64(
        // Int64(v)) == v as f64`. A Float64 column WITH a NaN must NOT use this path —
        // `is_missing()` treats a valid NaN as missing (pushes Null + does NOT advance
        // acc), so any NaN breaks to the generic path. Bool/Utf8/nullable columns
        // likewise break to the generic path.
        'typed: {
            let mut owned: Vec<Vec<f64>> = Vec::new();
            let mut is_owned: Vec<bool> = Vec::with_capacity(self.column_order.len());
            for name in &self.column_order {
                let col = &self.columns[name];
                if let Some(f) = col.as_f64_slice() {
                    if f.iter().any(|x| x.is_nan()) {
                        break 'typed;
                    }
                    is_owned.push(false);
                } else if let Some(d) = col.as_i64_slice() {
                    owned.push(d.iter().map(|&v| v as f64).collect());
                    is_owned.push(true);
                } else {
                    break 'typed;
                }
            }
            let mut owned_iter = owned.iter();
            let col_f64: Vec<&[f64]> = self
                .column_order
                .iter()
                .zip(&is_owned)
                .map(|(name, &owned_flag)| {
                    if owned_flag {
                        owned_iter
                            .next()
                            .expect("one owned vec per Int64 column")
                            .as_slice()
                    } else {
                        self.columns[name]
                            .as_f64_slice()
                            .expect("Float64 column checked all-valid above")
                    }
                })
                .collect();
            let n = self.len();
            let k = col_f64.len();
            let mut out_cols: Vec<Vec<f64>> = (0..k).map(|_| Vec::with_capacity(n)).collect();
            for row in 0..n {
                let mut acc = init;
                for (col_idx, col) in col_f64.iter().enumerate() {
                    acc = op(acc, col[row]);
                    out_cols[col_idx].push(acc);
                }
            }
            let mut columns = BTreeMap::new();
            for (name, vals) in self.column_order.iter().cloned().zip(out_cols) {
                columns.insert(name, Column::from_f64_values(vals));
            }
            return Ok(Self {
                columns: columns.into(),
                column_order: self.column_order.clone(),
                index: self.index.clone(),
                column_multiindex: self.column_multiindex.clone(),
                row_multiindex: self.row_multiindex.clone(),
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }

        let mut per_column: Vec<Vec<Scalar>> = self
            .column_order
            .iter()
            .map(|_| Vec::with_capacity(self.len()))
            .collect();

        for row_idx in 0..self.len() {
            let mut acc = init;
            for (col_idx, col_name) in self.column_order.iter().enumerate() {
                let value = &self.columns[col_name].values()[row_idx];
                if value.is_missing() {
                    per_column[col_idx].push(Scalar::Null(NullKind::NaN));
                } else {
                    let x = value.to_f64().map_err(ColumnError::from)?;
                    acc = op(acc, x);
                    per_column[col_idx].push(Scalar::Float64(acc));
                }
            }
        }

        let mut columns = BTreeMap::new();
        for (name, values) in self.column_order.iter().cloned().zip(per_column) {
            columns.insert(name, Column::new(DType::Float64, values)?);
        }

        Ok(Self {
            columns: columns.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Per br-frankenpandas-bktp1: detect uniformly-Timedelta64 DataFrame.
    /// The f64 cumulative_axis1 helper errors via to_f64() on Timedelta64
    /// columns.
    fn all_columns_timedelta(&self) -> bool {
        !self.column_order.is_empty()
            && self
                .column_order
                .iter()
                .all(|name| matches!(self.columns[name].dtype(), DType::Timedelta64))
    }

    /// Per br-frankenpandas-bktp1: typed-i64 cumulative axis=1 reducer for
    /// uniformly-Timedelta DataFrames. Op operates on i64 ns; missing
    /// positions don't advance the accumulator. Emits Scalar::Timedelta64.
    fn cumulative_axis1_timedelta<Op>(&self, init: i64, op: Op) -> Result<Self, FrameError>
    where
        Op: Fn(i64, i64) -> i64,
    {
        let mut per_column: Vec<Vec<Scalar>> = self
            .column_order
            .iter()
            .map(|_| Vec::with_capacity(self.len()))
            .collect();
        for row_idx in 0..self.len() {
            let mut acc = init;
            let mut started = false;
            for (col_idx, col_name) in self.column_order.iter().enumerate() {
                let value = &self.columns[col_name].values()[row_idx];
                match value {
                    Scalar::Timedelta64(ns) if *ns != Timedelta::NAT => {
                        acc = if started { op(acc, *ns) } else { *ns };
                        started = true;
                        per_column[col_idx].push(Scalar::Timedelta64(acc));
                    }
                    _ => per_column[col_idx].push(Scalar::Timedelta64(Timedelta::NAT)),
                }
            }
        }
        let mut columns = BTreeMap::new();
        for (name, values) in self.column_order.iter().cloned().zip(per_column) {
            columns.insert(name, Column::new(DType::Timedelta64, values)?);
        }
        Ok(Self {
            columns: columns.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Cumulative sum across columns, computed row-wise.
    ///
    /// Matches `pd.DataFrame.cumsum(axis=1, skipna=True)`.
    pub fn cumsum_axis1(&self) -> Result<Self, FrameError> {
        if self.all_columns_timedelta() {
            return self.cumulative_axis1_timedelta(0, Timedelta::add);
        }
        self.cumulative_axis1(0.0, |acc, x| acc + x)
    }

    /// Cumulative product across columns, computed row-wise.
    ///
    /// Matches `pd.DataFrame.cumprod(axis=1, skipna=True)`.
    pub fn cumprod_axis1(&self) -> Result<Self, FrameError> {
        // Per br-frankenpandas-bktp1: pandas raises TypeError on
        // td_df.cumprod(axis=1); mirror Series::cumprod br-v36qy by emitting
        // all-NaT for uniformly-Timedelta DataFrames.
        if self.all_columns_timedelta() {
            let mut columns = BTreeMap::new();
            for name in &self.column_order {
                let len = self.len();
                let vals: Vec<Scalar> = (0..len)
                    .map(|_| Scalar::Timedelta64(Timedelta::NAT))
                    .collect();
                columns.insert(name.clone(), Column::new(DType::Timedelta64, vals)?);
            }
            return Ok(Self {
                columns: columns.into(),
                column_order: self.column_order.clone(),
                index: self.index.clone(),
                column_multiindex: self.column_multiindex.clone(),
                row_multiindex: self.row_multiindex.clone(),
                allows_duplicate_labels: self.allows_duplicate_labels,
            });
        }
        self.cumulative_axis1(1.0, |acc, x| acc * x)
    }

    /// Cumulative minimum across columns, computed row-wise.
    ///
    /// Matches `pd.DataFrame.cummin(axis=1, skipna=True)`.
    pub fn cummin_axis1(&self) -> Result<Self, FrameError> {
        // Per br-frankenpandas-bktp1: sister to cumsum_axis1 above.
        if self.all_columns_timedelta() {
            return self.cumulative_axis1_timedelta(i64::MAX, |a, b| a.min(b));
        }
        self.cumulative_axis1(f64::INFINITY, f64::min)
    }

    /// Cumulative maximum across columns, computed row-wise.
    ///
    /// Matches `pd.DataFrame.cummax(axis=1, skipna=True)`.
    pub fn cummax_axis1(&self) -> Result<Self, FrameError> {
        // Per br-frankenpandas-bktp1: sister to cumsum_axis1 above.
        if self.all_columns_timedelta() {
            return self.cumulative_axis1_timedelta(i64::MIN, |a, b| a.max(b));
        }
        self.cumulative_axis1(f64::NEG_INFINITY, f64::max)
    }

    /// First-order difference per column.
    ///
    /// Matches `pd.DataFrame.diff(periods)`.
    pub fn diff(&self, periods: i64) -> Result<Self, FrameError> {
        // Direct-typed-column fast path for Float64 (see apply_cum_f64): the
        // `apply_per_column` clone de-types nullable Float64 columns, dropping them
        // to the generic Scalar diff (DataFrame diff on nullable f64 was ~6x slower
        // than pandas). Positional NaN-propagating diff off the STORED column's
        // `(&[f64], &ValidityMask)`: `out = v - v_{periods-back}`, valid iff BOTH
        // endpoints present. Bit-identical to Series::diff's nullable path (and the
        // generic diff, which emits Null(NaN) for any boundary/missing-operand slot).
        // Non-Float64 columns delegate to Series::diff (Timedelta/Bool/Int64 dtype
        // rules preserved).
        let transformed = self.par_map_columns_min(&self.column_order, 16_384, |name| {
            let col = &self.columns[name];
            if col.dtype() == DType::Float64
                && let Some((data, validity)) = col.as_f64_slice_with_validity()
            {
                let n = data.len();
                let mut out = vec![0.0_f64; n];
                let mut words = vec![0u64; n.div_ceil(64)];
                let p = periods.unsigned_abs().min(n as u64) as usize;
                if periods >= 0 {
                    for i in p..n {
                        let j = i - p;
                        if validity.get(i) && validity.get(j) {
                            out[i] = data[i] - data[j];
                            words[i / 64] |= 1u64 << (i % 64);
                        }
                    }
                } else {
                    for i in 0..n - p {
                        let j = i + p;
                        if validity.get(i) && validity.get(j) {
                            out[i] = data[i] - data[j];
                            words[i / 64] |= 1u64 << (i % 64);
                        }
                    }
                }
                Ok(Column::from_f64_values_with_validity(
                    out,
                    fp_columnar::ValidityMask::from_words(words, n),
                ))
            } else if matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) {
                Ok(self.column_as_series(name)?.diff(periods)?.column().clone())
            } else {
                Ok(col.clone())
            }
        })?;
        let mut result_cols = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(transformed) {
            result_cols.insert(name.clone(), column);
        }
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// First-order difference across columns per row.
    ///
    /// Matches `pd.DataFrame.diff(periods, axis=1)`.
    pub fn diff_axis1(&self, periods: i64) -> Result<Self, FrameError> {
        let n_cols = self.column_order.len();
        let n_rows = self.len();
        let mut out_cols = BTreeMap::new();

        // Per br-frankenpandas-r82bc: detect uniformly-Timedelta64 column and
        // preserve dtype. Sister surgery to pct_change_axis1's
        // br-frankenpandas-dj6rv Timedelta64 branch — but for diff the result
        // is Timedelta64 (delta of deltas), not f64 (dimensionless ratio).
        let all_timedelta = self.column_order.iter().all(|name| {
            let col = &self.columns[name];
            matches!(col.dtype(), DType::Timedelta64)
                || col.values().iter().all(|v| {
                    matches!(v, Scalar::Timedelta64(_))
                        || matches!(v, Scalar::Null(NullKind::NaT))
                        || v.is_missing()
                })
        }) && self.column_order.iter().any(|name| {
            self.columns[name]
                .values()
                .iter()
                .any(|v| matches!(v, Scalar::Timedelta64(ns) if *ns != Timedelta::NAT))
        });

        for (j, name) in self.column_order.iter().enumerate() {
            let mut vals = Vec::with_capacity(n_rows);
            let prev_idx = if periods >= 0 {
                j.checked_sub(periods as usize)
            } else {
                let p = periods.unsigned_abs() as usize;
                match j.checked_add(p) {
                    Some(p_idx) if p_idx < n_cols => Some(p_idx),
                    _ => None,
                }
            };

            if let Some(p_idx) = prev_idx {
                let prev_name = &self.column_order[p_idx];
                let current_col = &self.columns[name];
                let prev_col = &self.columns[prev_name];

                for i in 0..n_rows {
                    let curr_val = &current_col.values()[i];
                    let prev_val = &prev_col.values()[i];
                    if curr_val.is_missing() || prev_val.is_missing() {
                        if all_timedelta {
                            vals.push(Scalar::Timedelta64(Timedelta::NAT));
                        } else {
                            vals.push(Scalar::Null(NullKind::NaN));
                        }
                        continue;
                    }
                    if let (Scalar::Timedelta64(c_ns), Scalar::Timedelta64(p_ns)) =
                        (curr_val, prev_val)
                    {
                        vals.push(Scalar::Timedelta64(Timedelta::sub(*c_ns, *p_ns)));
                        continue;
                    }
                    match (curr_val.to_f64(), prev_val.to_f64()) {
                        (Ok(c), Ok(p)) => vals.push(Scalar::Float64(c - p)),
                        _ => vals.push(Scalar::Null(NullKind::NaN)),
                    }
                }
            } else if all_timedelta {
                vals.resize(n_rows, Scalar::Timedelta64(Timedelta::NAT));
            } else {
                vals.resize(n_rows, Scalar::Null(NullKind::NaN));
            }
            let out_dtype = if all_timedelta {
                DType::Timedelta64
            } else {
                DType::Float64
            };
            out_cols.insert(name.clone(), Column::new(out_dtype, vals)?);
        }
        Self::new_with_column_order(self.index.clone(), out_cols, self.column_order.clone())
    }

    /// Percentage change across columns per row.
    ///
    /// Matches `pd.DataFrame.pct_change(periods, axis=1)`.
    pub fn pct_change_axis1(&self, periods: i64) -> Result<Self, FrameError> {
        let n_cols = self.column_order.len();
        let n_rows = self.len();
        let mut out_cols = BTreeMap::new();
        // pandas pct_change(axis=1) default fill_method='pad' forward-fills
        // across columns (per row) before computing. (br-frankenpandas-c3zld)
        let src = self.ffill_axis1(None)?;

        for (j, name) in self.column_order.iter().enumerate() {
            let mut vals = Vec::with_capacity(n_rows);
            let prev_idx = if periods >= 0 {
                j.checked_sub(periods as usize)
            } else {
                let p = periods.unsigned_abs() as usize;
                match j.checked_add(p) {
                    Some(p_idx) if p_idx < n_cols => Some(p_idx),
                    _ => None,
                }
            };

            if let Some(p_idx) = prev_idx {
                let prev_name = &self.column_order[p_idx];
                let current_col = &src.columns[name];
                let prev_col = &src.columns[prev_name];

                for i in 0..n_rows {
                    let curr_val = &current_col.values()[i];
                    let prev_val = &prev_col.values()[i];
                    if curr_val.is_missing() || prev_val.is_missing() {
                        vals.push(Scalar::Null(NullKind::NaN));
                        continue;
                    }
                    // Per br-frankenpandas-dj6rv: Timedelta64 pct_change
                    // ratio is dimensionless f64.
                    if let (Scalar::Timedelta64(c_ns), Scalar::Timedelta64(p_ns)) =
                        (curr_val, prev_val)
                    {
                        if *c_ns == Timedelta::NAT || *p_ns == Timedelta::NAT {
                            vals.push(Scalar::Null(NullKind::NaN));
                        } else {
                            vals.push(Scalar::Float64(
                                (*c_ns as f64 - *p_ns as f64) / (*p_ns as f64),
                            ));
                        }
                        continue;
                    }
                    match (curr_val.to_f64(), prev_val.to_f64()) {
                        (Ok(c), Ok(p)) => vals.push(Scalar::Float64((c - p) / p)),
                        _ => vals.push(Scalar::Null(NullKind::NaN)),
                    }
                }
            } else {
                vals.resize(n_rows, Scalar::Null(NullKind::NaN));
            }
            out_cols.insert(name.clone(), Column::new(DType::Float64, vals)?);
        }

        Self::new_with_column_order(self.index.clone(), out_cols, self.column_order.clone())
    }

    /// Shift values per column.
    ///
    /// Matches `pd.DataFrame.shift(periods)`.
    pub fn shift(&self, periods: i64) -> Result<Self, FrameError> {
        // Like abs (br-frankenpandas-qmajv): per-column shift is a fresh output
        // Vec + validity-memmove + typed Column construction — dominated by the
        // alloc/construction, NOT memory bandwidth, so it threads across columns
        // cleanly. Direct A/B (cols=8, min-of-3, this host): 1.6M cells 9.45 ms
        // serial -> 1.11 ms threaded (8.5x); crossover ~80k cells (100k: 0.526
        // serial vs 0.359 threaded — threaded wins; 50k: 0.112 vs 0.372 — serial,
        // pays the ~0.33 ms spawn floor). The prior 4 M floor left the whole
        // 80k–4M range stuck serial. Fan out at >=131 072 cells (2^17, matching
        // abs/neg — conservative for shift, which crosses over near 80k, but
        // never regresses vs the old 4M floor and captures the 1.6M+ win).
        //
        // Direct-typed-column fast path for Float64 (see apply_cum_f64 / df.diff):
        // `apply_per_column` clones each column via `column_as_series`, and
        // `Column::clone` drops the ColumnData::Float64 cache (NullKind invariant),
        // so a nullable Float64 column de-typed to the generic per-element Scalar
        // shift (~8-26x slower than pandas). Shift the STORED column's
        // `(&[f64], &ValidityMask)` directly (validity-carrying memmove; vacated
        // slots missing = Null(NaN)). Bit-identical to the generic path for a typed
        // Float64 column: its missing slots render as Null(NaN) (the Float64-missing
        // convention Series::shift already relies on), so carrying `data[src]` +
        // `validity[src]` reproduces `vals[src].clone()`. Non-Float64 columns keep
        // the exact `apply_per_column` gate (numeric → Series shift, non-numeric →
        // clone passthrough).
        let transformed = self.par_map_columns_min(&self.column_order, 131_072, |name| {
            let col = &self.columns[name];
            if col.dtype() == DType::Float64
                && let Some((data, validity)) = col.as_f64_slice_with_validity()
            {
                let n = data.len();
                let mut out = vec![0.0_f64; n];
                let mut words = vec![0u64; n.div_ceil(64)];
                let p = periods.unsigned_abs().min(n as u64) as usize;
                if periods >= 0 {
                    for i in p..n {
                        let src = i - p;
                        out[i] = data[src];
                        if validity.get(src) {
                            words[i / 64] |= 1u64 << (i % 64);
                        }
                    }
                } else {
                    for i in 0..n - p {
                        let src = i + p;
                        out[i] = data[src];
                        if validity.get(src) {
                            words[i / 64] |= 1u64 << (i % 64);
                        }
                    }
                }
                Ok(Column::from_f64_values_with_validity(
                    out,
                    fp_columnar::ValidityMask::from_words(words, n),
                ))
            } else if matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) {
                Ok(self
                    .column_as_series(name)?
                    .shift(periods)?
                    .column()
                    .clone())
            } else {
                Ok(col.clone())
            }
        })?;
        let mut result_cols = BTreeMap::new();
        for (name, column) in self.column_order.iter().zip(transformed) {
            result_cols.insert(name.clone(), column);
        }
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Shift values per column, filling the vacated positions with `fill_value`
    /// instead of NaN. Matches `pd.DataFrame.shift(periods, fill_value=...)`. An
    /// `Int64` fill on an `Int64` column keeps that column `Int64` (no widening
    /// to Float64), exactly as the Series variant (br-frankenpandas-twqkf).
    pub fn shift_with_fill_value(
        &self,
        periods: i64,
        fill_value: Scalar,
    ) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.shift_with_fill_value(periods, fill_value.clone()))
    }

    /// Shift index horizontally by desired number of periods.
    ///
    /// Matches `pd.DataFrame.shift(periods, axis=1)`.
    pub fn shift_axis1(&self, periods: i64) -> Result<Self, FrameError> {
        let n_cols = self.column_order.len();
        if n_cols == 0 {
            return Ok(self.clone());
        }

        let mut out_cols = std::collections::BTreeMap::new();
        let missing_val = fp_types::Scalar::Null(fp_types::NullKind::NaN);

        for (i, name) in self.column_order.iter().enumerate() {
            let src_idx = i as i64 - periods;
            let col = if src_idx >= 0 && (src_idx as usize) < n_cols {
                let src_name = &self.column_order[src_idx as usize];
                self.columns[src_name].clone()
            } else {
                Column::from_values(vec![missing_val.clone(); self.len()])?
            };
            out_cols.insert(name.clone(), col);
        }

        Ok(Self {
            index: self.index.clone(),
            column_order: self.column_order.clone(),
            columns: out_cols.into(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Absolute value per column.
    ///
    /// Matches `pd.DataFrame.abs()`.
    pub fn abs(&self) -> Result<Self, FrameError> {
        // Per-column abs is NOT bandwidth-bound — it is dominated by the output
        // Vec<f64>/Vec<i64> allocation + typed Column construction, which spread
        // cleanly across columns. Direct serial-vs-threaded A/B at cols=8
        // (min-of-3, this host) put the crossover near ~110k total cells, where
        // the ~0.33 ms fixed thread-spawn cost equals the serial ~3 ns/cell:
        //   cells   serial    threaded
        //   800k    2.607 ms  0.419 ms  (6.2x threaded)
        //   200k    0.626 ms  0.340 ms  (1.8x threaded)
        //   100k    0.290 ms  0.318 ms  (serial, marginal)
        //    50k    0.014 ms  0.338 ms  (serial, threaded pays pure spawn)
        // The prior 4 M floor (from a since-invalidated "one core saturates
        // bandwidth" reading) left the whole 110k–4M range stuck serial — a
        // 200k×8 frame ran 13x slower than threaded. Fan out at >=131 072 cells
        // (2^17, safely past the crossover) so small L1/L2-resident frames stay
        // serial and avoid the spawn floor. Bit-identical either way (pure
        // scheduling; each column runs the identical Column::abs).
        self.apply_per_column_min(131_072, |s| s.abs())
    }

    /// Clip values per column.
    ///
    /// Matches `pd.DataFrame.clip(lower, upper)`.
    pub fn clip(&self, lower: Option<f64>, upper: Option<f64>) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.clip(lower, upper))
    }

    /// Clip values below a threshold across all numeric columns.
    ///
    /// Matches `pd.DataFrame.clip(lower=threshold)`.
    pub fn clip_lower(&self, threshold: f64) -> Result<Self, FrameError> {
        self.clip(Some(threshold), None)
    }

    /// Clip values above a threshold across all numeric columns.
    ///
    /// Matches `pd.DataFrame.clip(upper=threshold)`.
    pub fn clip_upper(&self, threshold: f64) -> Result<Self, FrameError> {
        self.clip(None, Some(threshold))
    }

    /// Clip each column to its own bound, matching `df.clip(lower=s, upper=s,
    /// axis=1)` where `lower`/`upper` are Series indexed by column name.
    ///
    /// Each numeric column is clipped to the scalar bound looked up by its name.
    /// Following pandas' where-based broadcast, a column whose *provided* lower
    /// or upper bound is absent from the Series (i.e. NaN) becomes all-NaN —
    /// distinct from the scalar `clip`, where a NaN bound means "no clip".
    /// A bound Series passed as `None` applies no clipping on that side.
    /// (Per-row bounds, `axis=0`, are tracked under br-frankenpandas-l4wfl.)
    pub fn clip_with_column_bounds(
        &self,
        lower: Option<&Series>,
        upper: Option<&Series>,
    ) -> Result<Self, FrameError> {
        // Resolve a column's bound: (was the bound Series provided?, finite value).
        // Provided-but-NaN/absent collapses to `(true, None)` -> NaN broadcast.
        let resolve = |bounds: Option<&Series>, label: &IndexLabel| -> (bool, Option<f64>) {
            match bounds {
                None => (false, None),
                Some(series) => match series.get(label).and_then(|s| s.to_f64().ok()) {
                    Some(v) if !v.is_nan() => (true, Some(v)),
                    _ => (true, None),
                },
            }
        };

        let mut result_cols = BTreeMap::new();
        for name in &self.column_order {
            let col = &self.columns[name];
            if !matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) {
                result_cols.insert(name.clone(), col.clone());
                continue;
            }
            let label = IndexLabel::Utf8(name.clone());
            let (lo_provided, lo) = resolve(lower, &label);
            let (hi_provided, hi) = resolve(upper, &label);

            let clipped = if (lo_provided && lo.is_none()) || (hi_provided && hi.is_none()) {
                // A provided bound is NaN for this column -> the whole column
                // becomes NaN (pandas where-broadcast; data nulls stay null too).
                Column::new(DType::Float64, vec![Scalar::Null(NullKind::NaN); col.len()])?
            } else {
                // No NaN bounds in play, so the scalar clip's dtype-preserving
                // path (Int64 kept when bounds are integral) applies cleanly.
                self.column_as_series(name)?.clip(lo, hi)?.column().clone()
            };
            result_cols.insert(name.clone(), clipped);
        }
        Self::new_with_column_order(self.index.clone(), result_cols, self.column_order.clone())
    }

    /// Clip each row to its own bound, matching `df.clip(lower=s, upper=s,
    /// axis=0)` where `lower`/`upper` are Series indexed by row label.
    ///
    /// Every numeric value in row `i` is clipped to the bound looked up by that
    /// row's label. Semantics verified against live pandas 2.2.3
    /// (br-frankenpandas-l4wfl):
    /// - A row label *present* in the bound Series with a finite value clips
    ///   that whole row to the value; dtype is preserved when the input is
    ///   `Int64` and every resulting value is integral (an integral float bound
    ///   such as `3.0` keeps `Int64`; a fractional bound that actually clips
    ///   demotes the column to `Float64`).
    /// - A row label present but *NaN* applies no clipping on that side (NaN
    ///   comparisons are false), leaving the value and dtype untouched.
    /// - A row label *absent* from any provided bound Series forces that entire
    ///   row to NaN and demotes every column to `Float64` — pandas reindexes the
    ///   bound to the frame's axis, and the introduced NaN propagates through
    ///   the where-broadcast. This is distinct from a present-but-NaN bound.
    /// - Pre-existing data nulls are preserved (and, like pandas, keep the
    ///   column in `Float64`).
    ///
    /// A bound Series passed as `None` applies no clipping on that side.
    /// (Per-column bounds, `axis=1`, are [`Self::clip_with_column_bounds`].)
    pub fn clip_with_row_bounds(
        &self,
        lower: Option<&Series>,
        upper: Option<&Series>,
    ) -> Result<Self, FrameError> {
        let row_labels = self.index.labels();
        let nrows = row_labels.len();

        // Resolve each provided bound Series to a per-row `Option<f64>` and
        // record rows whose label is absent from a provided bound (those rows
        // are forced to NaN, matching pandas' reindex-then-where broadcast).
        // present + finite -> Some(v); present + NaN -> None (no clip);
        // absent           -> None and `force_nan[i] = true`.
        let mut force_nan = vec![false; nrows];
        let resolve_side = |bounds: Option<&Series>, force: &mut [bool]| -> Vec<Option<f64>> {
            let mut per_row = Vec::with_capacity(nrows);
            for (i, label) in row_labels.iter().enumerate() {
                match bounds {
                    None => per_row.push(None),
                    Some(series) => match series.get(label) {
                        None => {
                            force[i] = true;
                            per_row.push(None);
                        }
                        Some(scalar) => match scalar.to_f64() {
                            Ok(v) if !v.is_nan() => per_row.push(Some(v)),
                            _ => per_row.push(None),
                        },
                    },
                }
            }
            per_row
        };
        let lo_per_row = resolve_side(lower, &mut force_nan);
        let hi_per_row = resolve_side(upper, &mut force_nan);

        let mut result_cols = BTreeMap::new();
        for name in &self.column_order {
            let col = &self.columns[name];
            if !matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) {
                result_cols.insert(name.clone(), col.clone());
                continue;
            }
            let input_is_int = matches!(col.dtype(), DType::Int64);
            let values = col.values();
            let mut clipped = Vec::with_capacity(nrows);
            let mut all_integral = true;
            let mut any_null = false;
            for (i, val) in values.iter().enumerate() {
                if force_nan[i] {
                    clipped.push(Scalar::Null(NullKind::NaN));
                    any_null = true;
                    continue;
                }
                if val.is_missing() {
                    clipped.push(val.clone());
                    any_null = true;
                    continue;
                }
                let mut x = val.to_f64().map_err(ColumnError::from)?;
                if let Some(lo) = lo_per_row[i]
                    && x < lo
                {
                    x = lo;
                }
                if let Some(hi) = hi_per_row[i]
                    && x > hi
                {
                    x = hi;
                }
                if x.fract() != 0.0 {
                    all_integral = false;
                }
                clipped.push(Scalar::Float64(x));
            }

            let column = if input_is_int && !any_null && all_integral {
                let ints = clipped
                    .into_iter()
                    .map(|s| match s {
                        Scalar::Float64(x) => Scalar::Int64(x as i64),
                        other => other,
                    })
                    .collect();
                Column::new(DType::Int64, ints)?
            } else {
                Column::new(DType::Float64, clipped)?
            };
            result_cols.insert(name.clone(), column);
        }
        Self::new_with_column_order(self.index.clone(), result_cols, self.column_order.clone())
    }

    /// Round numeric columns to specified decimal places.
    ///
    /// Matches `pd.DataFrame.round(decimals)`.
    pub fn round(&self, decimals: i32) -> Result<Self, FrameError> {
        self.apply_per_column(|s| s.round(decimals))
    }

    /// Round each named column to its own number of decimal places.
    ///
    /// Matches `pd.DataFrame.round(decimals)` where `decimals` is a dict/Series
    /// mapping column name -> decimals. Columns absent from the map are left
    /// UNCHANGED (pandas only rounds the listed columns); a listed non-numeric
    /// column is also left unchanged (rounding is a no-op on object dtype).
    pub fn round_columns(&self, decimals: &BTreeMap<String, i32>) -> Result<Self, FrameError> {
        let mut result_cols = BTreeMap::new();
        for name in &self.column_order {
            let col = &self.columns[name];
            let new_col = match decimals.get(name) {
                Some(&d) if matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) => {
                    self.column_as_series(name)?.round(d)?.column().clone()
                }
                _ => col.clone(),
            };
            result_cols.insert(name.clone(), new_col);
        }
        Ok(Self {
            columns: result_cols.into(),
            column_order: self.column_order.clone(),
            index: self.index.clone(),
            column_multiindex: self.column_multiindex.clone(),
            row_multiindex: self.row_multiindex.clone(),
            allows_duplicate_labels: self.allows_duplicate_labels,
        })
    }

    /// Floor each numeric element (round toward negative infinity).
    ///
    /// Matches `np.floor(df)`. NaN values pass through.
    pub fn floor(&self) -> Result<Self, FrameError> {
        // NB: floor/ceil/trunc are NOT pure bandwidth like abs/neg — the per-
        // element `roundsd` is compute-heavy enough that threading wins even at
        // L3-resident sizes (measured: serial 100k×10 is ~2.4x SLOWER), so they
        // keep the default parallel floor. (The Column-level rescan removal still
        // applies via `typed_float_unary_finite_preserving`.)
        self.apply_per_column(|s| s.floor())
    }

