    /// Dense sequential all/any for typed (Bool/Int64/Float64) value columns
    /// keyed by bounded Int64 or dense mixed multi-keys (br-frankenpandas-1q4q4)
    /// — the multi-col sibling of `SeriesGroupBy::group_bool_reduce_dense`.
    /// `all`/`any` aren't in `aggregate_named_func`'s dense set, so they fell to
    /// `build_groups` and a per-group `Vec<Scalar>` (DataFrameGroupBy all/any
    /// were 0.30× pandas on the original single-key lane).
    ///
    /// One shared `int64_dense_grouping` pass + a SEQUENTIAL per-column AND/OR fold
    /// over the typed truthy values. BIT-IDENTICAL: boolean AND/OR is
    /// order-independent (seeded with the identity), the slices are all-valid so
    /// the truthy predicate is exactly `bool` / `!=0` / `!=0.0`, and
    /// `int64_dense_grouping` matches `build_groups`' group order. Bails to
    /// `aggregate_named_func` for `as_index=false` / multi-key / non-typed cols.
    fn try_bool_reduce_dense(&self, want_all: bool) -> Result<Option<DataFrame>, FrameError> {
        if !self.as_index || self.by.is_empty() {
            return Ok(None);
        }
        let value_cols: Vec<String> = self
            .df
            .column_order
            .iter()
            .filter(|c| !self.by.contains(c))
            .cloned()
            .collect();
        if value_cols.is_empty()
            || !value_cols.iter().all(|c| {
                let col = &self.df.columns[c];
                col.as_bool_slice().is_some()
                    || col.as_i64_slice().is_some()
                    || col.as_f64_slice().is_some()
            })
        {
            return Ok(None);
        }
        // Single-key bounded-Int64 grouping, or the composite multi-key grouping
        // with a row-MultiIndex output. The mixed-key branch is the Utf8 sibling
        // of the Int64 bypass and skips build_groups for contiguous Utf8 keys.
        let (gid_per_row, ng, order, out_index, row_multiindex) = if self.by.len() == 1 {
            let key_col = &self.df.columns[&self.by[0]];
            if let Some(keys) = key_col.as_i64_slice() {
                let Some((min, range)) = i64_dense_histogram_range(keys) else {
                    return Ok(None);
                };
                let (g, n, o, idx) = self.int64_dense_grouping(keys, min, range);
                (g, n, o, idx, None)
            } else if key_col.dtype() == DType::Utf8 && key_col.validity().all() {
                let (g, n, o, idx) = self.single_utf8_key_dense_grouping(key_col);
                (g, n, o, idx, None)
            } else {
                return Ok(None);
            }
        } else if let Some(grouping) = self.multi_int64_dense_grouping() {
            let (idx, mi) = self.multi_dense_index(&grouping)?;
            (
                grouping.gid_per_row,
                grouping.ngroups,
                grouping.order,
                idx,
                Some(mi),
            )
        } else if let Some(grouping) = self.multi_mixed_dense_grouping() {
            let (idx, mi) = self.multi_dense_index_mixed(&grouping)?;
            (
                grouping.gid_per_row,
                grouping.ngroups,
                grouping.order,
                idx,
                Some(mi),
            )
        } else {
            return Ok(None);
        };
        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::with_capacity(value_cols.len());
        for col_name in &value_cols {
            let col = &self.df.columns[col_name];
            let bool_d = col.as_bool_slice();
            let i64_d = if bool_d.is_none() {
                col.as_i64_slice()
            } else {
                None
            };
            let f64_d = if bool_d.is_none() && i64_d.is_none() {
                col.as_f64_slice()
            } else {
                None
            };
            let mut acc = vec![want_all; ng];
            for (row, &g) in gid_per_row.iter().enumerate() {
                let truthy = if let Some(d) = bool_d {
                    d[row]
                } else if let Some(d) = i64_d {
                    d[row] != 0
                } else {
                    f64_d.unwrap()[row] != 0.0
                };
                if want_all {
                    acc[g] = acc[g] && truthy;
                } else {
                    acc[g] = acc[g] || truthy;
                }
            }
            let out: Vec<bool> = order.iter().map(|&g| acc[g]).collect();
            result_cols.insert(col_name.clone(), Column::from_bool_values(out));
            col_order.push(col_name.clone());
        }
        Ok(Some(DataFrame::new_with_axes(
            out_index,
            row_multiindex,
            result_cols,
            col_order,
            None,
        )?))
    }

    /// GroupBy any (returns True if any value is truthy per group).
    pub fn any(&self) -> Result<DataFrame, FrameError> {
        if let Some(df) = self.try_bool_reduce_dense(false)? {
            return Ok(df);
        }
        self.aggregate_named_func("any")
    }

    /// GroupBy all (returns True if all values are truthy per group).
    pub fn all(&self) -> Result<DataFrame, FrameError> {
        if let Some(df) = self.try_bool_reduce_dense(true)? {
            return Ok(df);
        }
        self.aggregate_named_func("all")
    }

    /// GroupBy quantile.
    pub fn quantile(&self, q: f64) -> Result<DataFrame, FrameError> {
        if !(0.0..=1.0).contains(&q) {
            return Err(FrameError::CompatibilityRejected(format!(
                "quantile must be between 0 and 1, got {q}"
            )));
        }

        let (group_order, groups) = self.build_groups();
        let value_cols: Vec<String> = self
            .df
            .column_order
            .iter()
            .filter(|c| !self.by.contains(c))
            .cloned()
            .collect();
        let n_groups = group_order.len();

        let mut labels = Vec::with_capacity(n_groups);
        for gkey in &group_order {
            let first_row = groups[gkey][0];
            labels.push(self.group_key_label(first_row));
        }

        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::new();

        for col_name in &value_cols {
            let col = &self.df.columns[col_name];
            // Typed per-group quantile (br-frankenpandas-gqcsr): an all-valid,
            // non-nullable Float64/Int64 column gathers each group's finite
            // values into one reused f64 buffer and quickselects
            // (group_nanquantile_f64) — no per-group Vec<Scalar> clone, no
            // per-element to_f64. Bit-identical to fp_types::nanquantile (same
            // collect_finite + lo-th select + interpolation). Timedelta64 /
            // nullable / non-numeric columns keep the Scalar path (preserving
            // Timedelta dtype per br-v61uo).
            let f64s = col.as_f64_slice();
            let i64s = col.as_i64_slice();
            let agg_vals: Vec<Scalar> =
                if !col.dtype().is_nullable() && (f64s.is_some() || i64s.is_some()) {
                    let mut buf: Vec<f64> = Vec::new();
                    let mut out = Vec::with_capacity(n_groups);
                    for gkey in &group_order {
                        buf.clear();
                        if let Some(s) = f64s {
                            for &i in &groups[gkey] {
                                let v = s[i];
                                if v.is_finite() {
                                    buf.push(v);
                                }
                            }
                        } else if let Some(s) = i64s {
                            for &i in &groups[gkey] {
                                buf.push(s[i] as f64);
                            }
                        }
                        out.push(if buf.is_empty() {
                            Scalar::Null(NullKind::NaN)
                        } else {
                            Scalar::Float64(group_nanquantile_f64(&mut buf, q))
                        });
                    }
                    out
                } else {
                    let mut agg_vals = Vec::with_capacity(n_groups);
                    for gkey in &group_order {
                        let row_indices = &groups[gkey];
                        // Per br-frankenpandas-v61uo: route through fp_types::
                        // nanquantile so Timedelta64 columns preserve dtype
                        // (br-5djk7). The previous inline f64 path filtered out
                        // Timedelta values via to_f64().ok().
                        let group_scalars: Vec<Scalar> = row_indices
                            .iter()
                            .map(|&i| col.values()[i].clone())
                            .collect();
                        agg_vals.push(fp_types::nanquantile(&group_scalars, q));
                    }
                    agg_vals
                };

            result_cols.insert(col_name.clone(), Column::from_values(agg_vals)?);
            col_order.push(col_name.clone());
        }

        self.format_output(result_cols, col_order, labels, &group_order, &groups)
    }

    /// GroupBy sum.
    pub fn sum(&self) -> Result<DataFrame, FrameError> {
        self.aggregate_named_func("sum")
    }

    /// GroupBy mean.
    pub fn mean(&self) -> Result<DataFrame, FrameError> {
        self.aggregate_named_func("mean")
    }

    /// GroupBy count.
    /// Dense GroupBy.count when every value column is all-valid: count == group
    /// size (count is the non-null tally, and all-valid ⇒ no nulls), which needs
    /// only the grouping — NO value materialization the generic path forces to
    /// check is_missing per row. Bit-identical: same sorted-key group order / Multi-
    /// Index, Int64 counts. Falls back for a null-bearing value column or non-dense
    /// (non-Int64/Utf8) key. Value-type-agnostic (covers Utf8/Int64/Float64 values).
    fn try_count_dense(&self) -> Result<Option<DataFrame>, FrameError> {
        if !self.as_index || self.by.is_empty() {
            return Ok(None);
        }
        let value_cols: Vec<String> = self
            .df
            .column_order
            .iter()
            .filter(|c| !self.by.contains(c))
            .cloned()
            .collect();
        // All-valid columns count == group size; a nullable NUMERIC column
        // (Int64/Float64 with validity) counts present values per group off the
        // raw mask. A nullable non-numeric column (e.g. Utf8/Bool with nulls) has
        // no typed validity accessor here, so bail it to the generic path.
        if value_cols.is_empty()
            || !value_cols.iter().all(|c| {
                let col = &self.df.columns[c];
                !col.has_nulls()
                    || col.as_i64_slice_with_validity().is_some()
                    || col.as_f64_slice_with_validity().is_some()
            })
        {
            return Ok(None);
        }
        let (gid_per_row, ng, order, out_index, row_mi) = if self.by.len() == 1 {
            let key_col = &self.df.columns[&self.by[0]];
            let (g, n, o, idx) = if let Some(keys) = key_col.as_i64_slice() {
                let Some((min, range)) = i64_dense_histogram_range(keys) else {
                    return Ok(None);
                };
                self.int64_dense_grouping(keys, min, range)
            } else if key_col.dtype() == DType::Utf8 && key_col.validity().all() {
                // Contiguous OR Scalar-backed Utf8 key (the prior inline block only
                // handled the contiguous backing, so a from_values key fell to the
                // generic build_groups path).
                self.single_utf8_key_dense_grouping(key_col)
            } else {
                return Ok(None);
            };
            (g, n, o, idx, None)
        } else if let Some(grouping) = self.multi_int64_dense_grouping() {
            let (idx, mi) = self.multi_dense_index(&grouping)?;
            (
                grouping.gid_per_row,
                grouping.ngroups,
                grouping.order,
                idx,
                Some(mi),
            )
        } else if let Some(grouping) = self.multi_mixed_dense_grouping() {
            let (idx, mi) = self.multi_dense_index_mixed(&grouping)?;
            (
                grouping.gid_per_row,
                grouping.ngroups,
                grouping.order,
                idx,
                Some(mi),
            )
        } else {
            return Ok(None);
        };
        let mut sizes = vec![0i64; ng];
        for &g in &gid_per_row {
            sizes[g] += 1;
        }
        let all_valid_counts: Vec<i64> = order.iter().map(|&g| sizes[g]).collect();
        let mut result_cols = BTreeMap::new();
        let mut col_order = Vec::with_capacity(value_cols.len());
        for col_name in &value_cols {
            let col = &self.df.columns[col_name];
            // All-valid: count == group size (shared vec). Nullable numeric: tally
            // PRESENT values per group (skipna) — `validity.get` for Int64, and
            // `validity.get && !is_nan` for Float64 (a valid-but-NaN slot is
            // is_missing, matching the generic per-row `!is_missing()` count).
            let col_counts: Vec<i64> = if !col.has_nulls() {
                all_valid_counts.clone()
            } else if let Some((_d, v)) = col.as_i64_slice_with_validity() {
                let mut c = vec![0i64; ng];
                for (row, &g) in gid_per_row.iter().enumerate() {
                    c[g] += v.get(row) as i64;
                }
                order.iter().map(|&g| c[g]).collect()
            } else {
                let (d, v) = col
                    .as_f64_slice_with_validity()
                    .expect("gate admits only all-valid / nullable-numeric columns");
                let mut c = vec![0i64; ng];
                for (row, &g) in gid_per_row.iter().enumerate() {
                    c[g] += (v.get(row) && !d[row].is_nan()) as i64;
                }
                order.iter().map(|&g| c[g]).collect()
            };
            result_cols.insert(col_name.clone(), Column::from_i64_values_owned(col_counts));
            col_order.push(col_name.clone());
        }
        Ok(Some(DataFrame::new_with_axes(
            out_index,
            row_mi,
            result_cols,
            col_order,
            None,
        )?))
    }

    pub fn count(&self) -> Result<DataFrame, FrameError> {
        if let Some(df) = self.try_count_dense()? {
            return Ok(df);
        }
        self.aggregate_named_func("count")
    }

