    fn assert_text_golden(golden_name: &str, actual: &str) {
        let golden_path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("goldens")
            .join(golden_name);

        if std::env::var_os("UPDATE_GOLDENS").is_some() {
            let parent = golden_path
                .parent()
                .expect("golden path should have a parent directory");
            std::fs::create_dir_all(parent).expect("golden directory should be creatable");
            std::fs::write(&golden_path, actual).expect("golden file should be writable");
            return;
        }

        let mut expected =
            std::fs::read_to_string(&golden_path).expect("golden file should be readable");
        if expected.ends_with('\n') {
            expected.pop();
        }
        let mut actual_normalized = actual.to_string();
        if actual_normalized.ends_with('\n') {
            actual_normalized.pop();
        }
        // Normalize runtime-only / internal-representation fields that carry
        // no observable meaning, so optimizations to those internals never
        // red these Debug goldens (br-frankenpandas-esj4i — this had recurred
        // 3x: label_identity counter, OnceLock cache pre-seeding (arr72), and
        // the all-valid ValidityMask word-bitmap repr (f9b4d259)).
        let actual_normalized = normalize_volatile_debug_repr(&actual_normalized);
        let expected = normalize_volatile_debug_repr(&expected);
        assert_eq!(
            actual_normalized,
            expected,
            "golden mismatch for {}",
            golden_path.display()
        );
    }

    fn assert_nonnegative_f64_values_within_ulps(
        actual_values: &[Scalar],
        expected_values: &[f64],
        max_ulps: u64,
    ) {
        assert_eq!(actual_values.len(), expected_values.len());
        for (row, (actual, expected)) in actual_values.iter().zip(expected_values).enumerate() {
            let Scalar::Float64(actual) = actual else {
                panic!("row {row} should contain Float64, got {actual:?}");
            };
            assert!(
                actual.is_finite() && actual.is_sign_positive(),
                "row {row} should contain a finite nonnegative result, got {actual}"
            );
            assert!(
                expected.is_finite() && expected.is_sign_positive(),
                "test expectation at row {row} should be finite and nonnegative, got {expected}"
            );
            assert!(
                actual.to_bits().abs_diff(expected.to_bits()) <= max_ulps,
                "row {row} differs by more than {max_ulps} ULPs: actual={actual:.17}, expected={expected:.17}"
            );
        }
    }

    /// Remove every `label_identity: <digits>, ` occurrence (fp-index Index
    /// Debug's runtime-only counter) so golden comparisons are deterministic.
    fn strip_volatile_label_identity(s: &str) -> String {
        const MARKER: &str = "label_identity: ";
        let mut out = String::with_capacity(s.len());
        let mut rest = s;
        while let Some(pos) = rest.find(MARKER) {
            out.push_str(&rest[..pos]);
            let after = &rest[pos + MARKER.len()..];
            let digits_end = after
                .find(|c: char| !c.is_ascii_digit())
                .unwrap_or(after.len());
            let tail = &after[digits_end..];
            rest = tail.strip_prefix(", ").unwrap_or(tail);
        }
        out.push_str(rest);
        out
    }

    /// Canonicalize the runtime-only / internal-representation fields of
    /// struct Debug output so optimizations that change them (without
    /// changing observable values) never break Debug-format goldens
    /// (br-frankenpandas-esj4i). Normalizes, in order:
    ///   1. `label_identity: <n>` — fp-index's global atomic counter.
    ///   2. `<cache>: OnceLock(...)` for the three runtime memoization caches
    ///      (duplicate_cache / sort_order_cache / semantic_fingerprint_cache)
    ///      — pre-seeding them (arr72) changed `OnceLock(<uninit>)` to a
    ///      concrete value with no observable effect.
    ///   3. `validity: ValidityMask { words: [...], len: N }` — the all-valid
    ///      bitmap optimization (f9b4d259) toggled `words` between a full
    ///      bitmap and `[]`; only `len` (kept) is observable here. No golden
    ///      asserts a partial-validity bit pattern via Debug (every
    ///      ValidityMask in the golden corpus is all-valid); a test that
    ///      needs to assert missing-row positions must use observable
    ///      accessors, not the struct Debug string.
    fn normalize_volatile_debug_repr(s: &str) -> String {
        let stripped = strip_volatile_label_identity(s);
        let cached = normalize_oncelock_caches(&stripped);
        normalize_validity_mask_words(&cached)
    }

    /// Replace each `<cache>: OnceLock(...)` value with a canonical
    /// `OnceLock(_)` for the three runtime memoization caches, so pre-seeding
    /// them (or leaving them uninit) does not change the golden text.
    fn normalize_oncelock_caches(s: &str) -> String {
        const CACHES: [&str; 3] = [
            "duplicate_cache: OnceLock(",
            "sort_order_cache: OnceLock(",
            "semantic_fingerprint_cache: OnceLock(",
        ];
        let mut out = s.to_string();
        for marker in CACHES {
            let mut next = String::with_capacity(out.len());
            let mut rest = out.as_str();
            while let Some(pos) = rest.find(marker) {
                next.push_str(&rest[..pos]);
                next.push_str(marker);
                // Skip the balanced `(...)` payload (OnceLock Debug holds a
                // single value with no nested unbalanced parens in practice;
                // matches up to the first ')').
                let after = &rest[pos + marker.len()..];
                let close = after.find(')').unwrap_or(after.len());
                next.push_str("_)");
                rest = after[close..].strip_prefix(')').unwrap_or(&after[close..]);
            }
            next.push_str(rest);
            out = next;
        }
        out
    }

    /// Collapse `ValidityMask { words: [...], len: N }` to
    /// `ValidityMask { len: N }`, so the all-valid bitmap optimization
    /// (full bitmap vs empty) does not change the golden text. `len` (the
    /// only observable field here) is preserved.
    fn normalize_validity_mask_words(s: &str) -> String {
        const MARKER: &str = "ValidityMask { words: [";
        let mut out = String::with_capacity(s.len());
        let mut rest = s;
        while let Some(pos) = rest.find(MARKER) {
            out.push_str(&rest[..pos]);
            out.push_str("ValidityMask { ");
            // Skip `words: [...], ` up to the `len:` field.
            let after = &rest[pos + MARKER.len()..];
            match after.find("len:") {
                Some(i) => rest = &after[i..],
                None => {
                    // Malformed — emit verbatim and stop.
                    out.push_str(MARKER);
                    rest = after;
                }
            }
        }
        out.push_str(rest);
        out
    }

    fn expect_float64(value: &Scalar) -> f64 {
        if let Scalar::Float64(v) = value {
            *v
        } else {
            assert!(
                matches!(value, Scalar::Float64(_)),
                "expected Float64, got {value:?}"
            );
            0.0
        }
    }

    fn expect_int64(value: &Scalar) -> i64 {
        if let Scalar::Int64(v) = value {
            *v
        } else {
            assert!(
                matches!(value, Scalar::Int64(_)),
                "expected Int64, got {value:?}"
            );
            0
        }
    }

