    #[test]
    fn int64_unit_range_alignment_rejects_non_unit_mixed_and_gapped_labels() {
        let unit = Index::new((0..3_i64).map(IndexLabel::Int64).collect());
        let non_unit = Index::new(vec![IndexLabel::Int64(0), IndexLabel::Int64(2)]);
        let mixed = Index::new(vec![
            IndexLabel::Int64(0),
            IndexLabel::Utf8("1".to_string()),
        ]);
        let gapped = Index::new(vec![IndexLabel::Int64(5), IndexLabel::Int64(6)]);
        let duplicate = Index::new(vec![IndexLabel::Int64(0), IndexLabel::Int64(0)]);

        assert!(int64_unit_range_alignment(&non_unit, &unit).is_none());
        assert!(int64_unit_range_alignment(&mixed, &unit).is_none());
        assert!(int64_unit_range_alignment(&unit, &gapped).is_none());
        assert!(int64_unit_range_alignment(&duplicate, &unit).is_none());
    }

    #[test]
    fn sorted_unique_union_alignment_preserves_positions_and_name() {
        let left =
            Index::new(vec![0_i64.into(), 2_i64.into(), 4_i64.into()]).rename_index(Some("idx"));
        let right =
            Index::new(vec![1_i64.into(), 2_i64.into(), 5_i64.into()]).rename_index(Some("idx"));

        let plan = align_union_sorted_unique(&left, &right);

        assert_eq!(
            plan.union_index.labels(),
            &[
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                4_i64.into(),
                5_i64.into()
            ]
        );
        assert_eq!(
            plan.left_positions,
            vec![Some(0), None, Some(1), Some(2), None]
        );
        assert_eq!(
            plan.right_positions,
            vec![None, Some(0), Some(1), None, Some(2)]
        );
        assert_eq!(plan.union_index.name(), Some("idx"));
    }

    #[test]
    fn sorted_unique_union_alignment_drops_mismatched_names() {
        let left = Index::new(vec![0_i64.into(), 2_i64.into()]).rename_index(Some("left_idx"));
        let right = Index::new(vec![1_i64.into(), 2_i64.into()]).rename_index(Some("right_idx"));

        let plan = align_union_sorted_unique(&left, &right);

        assert_eq!(
            plan.union_index.labels(),
            &[0_i64.into(), 1_i64.into(), 2_i64.into()]
        );
        assert_eq!(plan.union_index.name(), None);
    }

    #[test]
    fn semantic_integer_label_fingerprint_matches_serde_json() {
        let labels = vec![
            IndexLabel::Int64(i64::MIN),
            IndexLabel::Timedelta64(-7),
            IndexLabel::Datetime64(42),
            IndexLabel::Int64(i64::MAX),
        ];
        let fast =
            semantic_integer_index_labels_fingerprint(&labels).expect("integer labels fast path");
        let payload = serde_json::to_vec(&labels).expect("serialize labels");
        let reference = fp_runtime::semantic_fingerprint_bytes(&payload);
        assert_eq!(fast, reference);

        let string_labels = vec![IndexLabel::Utf8("x".to_owned())];
        assert!(semantic_integer_index_labels_fingerprint(&string_labels).is_none());
    }

    #[test]
    fn semantic_range_index_fingerprint_matches_materialized_labels() {
        let range_index = Index::new_known_unique_int64_unit_range(-2, 4).rename_index(Some("idx"));
        let materialized = Index::new(vec![
            IndexLabel::Int64(-2),
            IndexLabel::Int64(-1),
            IndexLabel::Int64(0),
            IndexLabel::Int64(1),
        ])
        .rename_index(Some("idx"));

        assert_eq!(
            semantic_index_identity("output", &range_index),
            semantic_index_identity("output", &materialized)
        );
        assert_eq!(
            semantic_int64_unit_range_labels_fingerprint(-2, 4),
            semantic_integer_index_labels_fingerprint(materialized.labels())
                .expect("materialized integer fingerprint")
        );
    }

    #[test]
    fn sorted_unique_union_fingerprint_cache_preserves_output_identity() {
        let left =
            Index::new(vec![0_i64.into(), 2_i64.into(), 4_i64.into()]).rename_index(Some("idx"));
        let right =
            Index::new(vec![1_i64.into(), 2_i64.into(), 5_i64.into()]).rename_index(Some("idx"));
        let plan = align_union_sorted_unique(&left, &right);
        let left_identity = semantic_index_identity("left", &left);
        let right_identity = semantic_index_identity("right", &right);
        let reference = semantic_index_identity("output", &plan.union_index);

        let first = semantic_sorted_unique_union_output_fingerprint(
            &left,
            &right,
            &plan.union_index,
            &left_identity.fingerprint,
            &right_identity.fingerprint,
        )
        .expect("sorted unique fingerprint");
        let second_plan = align_union_sorted_unique(&left, &right);
        let second = semantic_sorted_unique_union_output_fingerprint(
            &left,
            &right,
            &second_plan.union_index,
            &left_identity.fingerprint,
            &right_identity.fingerprint,
        )
        .expect("cached sorted unique fingerprint");

        assert_eq!(first, reference.fingerprint);
        assert_eq!(second, reference.fingerprint);
    }

    #[test]
    fn sorted_unique_union_fingerprint_rejects_mismatched_input_fingerprints() {
        let left = Index::new(vec![0_i64.into(), 2_i64.into(), 4_i64.into()]);
        let right = Index::new(vec![1_i64.into(), 2_i64.into(), 5_i64.into()]);
        let plan = align_union_sorted_unique(&left, &right);
        let left_identity = semantic_index_identity("left", &left);
        let right_identity = semantic_index_identity("right", &right);

        assert!(
            semantic_sorted_unique_union_output_fingerprint(
                &left,
                &right,
                &plan.union_index,
                "fake-left-fingerprint",
                &right_identity.fingerprint,
            )
            .is_none()
        );
        assert!(
            semantic_sorted_unique_union_output_fingerprint(
                &left,
                &right,
                &plan.union_index,
                &left_identity.fingerprint,
                "fake-right-fingerprint",
            )
            .is_none()
        );
    }

    #[test]
    fn alignment_semantic_witness_uses_exact_output_identity_with_cache() {
        let left =
            Index::new(vec![0_i64.into(), 2_i64.into(), 4_i64.into()]).rename_index(Some("left"));
        let right =
            Index::new(vec![1_i64.into(), 2_i64.into(), 5_i64.into()]).rename_index(Some("right"));
        let plan = align_union_sorted_unique(&left, &right);

        let mut ledger = EvidenceLedger::new();
        record_alignment_semantic_witness(
            &mut ledger,
            "series.add",
            AlignMode::Outer,
            &left,
            &right,
            &plan.union_index,
            "series_binary_arithmetic_materialization",
        );
        let first = ledger
            .semantic_witnesses()
            .first()
            .expect("semantic witness");

        let mut cached_ledger = EvidenceLedger::new();
        record_alignment_semantic_witness(
            &mut cached_ledger,
            "series.add",
            AlignMode::Outer,
            &left,
            &right,
            &plan.union_index,
            "series_binary_arithmetic_materialization",
        );
        let cached = cached_ledger
            .semantic_witnesses()
            .first()
            .expect("semantic witness");
        let direct_output = semantic_index_identity("output", &plan.union_index);

        assert_eq!(first.output_index_identity, direct_output);
        assert_eq!(cached.output_index_identity, direct_output);
        assert_eq!(first.operation, cached.operation);
        assert_eq!(first.materialization_reason, cached.materialization_reason);
        assert_eq!(first.alignment_mode, cached.alignment_mode);
        assert_eq!(first.input_index_identity, cached.input_index_identity);
        assert_eq!(first.null_nan_policy, cached.null_nan_policy);
        assert_eq!(
            first.output_ordering_contract,
            cached.output_ordering_contract
        );
    }

    #[test]
    fn alignment_semantic_witness_falls_back_for_duplicate_or_unsorted_indexes() {
        let duplicate_left = Index::new(vec![0_i64.into(), 0_i64.into(), 2_i64.into()]);
        let duplicate_right = Index::new(vec![1_i64.into(), 2_i64.into()]);
        let (duplicate_output, _, _) =
            align_union_duplicate_aware(&duplicate_left, &duplicate_right);
        assert!(
            semantic_sorted_unique_union_output_fingerprint(
                &duplicate_left,
                &duplicate_right,
                &duplicate_output,
                &semantic_index_identity("left", &duplicate_left).fingerprint,
                &semantic_index_identity("right", &duplicate_right).fingerprint,
            )
            .is_none()
        );

        let unsorted_left = Index::new(vec![2_i64.into(), 0_i64.into()]);
        let unsorted_right = Index::new(vec![1_i64.into(), 3_i64.into()]);
        let unsorted_plan = align_union(&unsorted_left, &unsorted_right);
        assert!(
            semantic_sorted_unique_union_output_fingerprint(
                &unsorted_left,
                &unsorted_right,
                &unsorted_plan.union_index,
                &semantic_index_identity("left", &unsorted_left).fingerprint,
                &semantic_index_identity("right", &unsorted_right).fingerprint,
            )
            .is_none()
        );
    }

    #[test]
    fn sorted_unique_union_fingerprint_cache_eviction_preserves_identity() {
        let cache =
            SORTED_UNIQUE_UNION_FINGERPRINT_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
        {
            let mut guard = cache
                .lock()
                .expect("sorted unique union fingerprint cache poisoned");
            guard.clear();
            for i in 0..SORTED_UNIQUE_UNION_FINGERPRINT_CACHE_MAX {
                guard.insert(
                    SortedUniqueUnionFingerprintKey {
                        left_fingerprint: format!("left-{i}"),
                        right_fingerprint: format!("right-{i}"),
                        left_len: i,
                        right_len: i + 1,
                    },
                    format!("out-{i}"),
                );
            }
        }

        let left = Index::new(vec![10_i64.into(), 20_i64.into()]);
        let right = Index::new(vec![15_i64.into(), 25_i64.into()]);
        let plan = align_union_sorted_unique(&left, &right);
        let reference = semantic_index_identity("output", &plan.union_index);
        let got = semantic_sorted_unique_union_output_fingerprint(
            &left,
            &right,
            &plan.union_index,
            &semantic_index_identity("left", &left).fingerprint,
            &semantic_index_identity("right", &right).fingerprint,
        )
        .expect("eviction miss should recompute output fingerprint");

        assert_eq!(got, reference.fingerprint);
    }

    #[test]
    fn sorted_unique_union_fingerprint_cache_is_thread_safe() {
        let left = Index::new(vec![0_i64.into(), 2_i64.into(), 4_i64.into()]);
        let right = Index::new(vec![1_i64.into(), 3_i64.into(), 5_i64.into()]);
        let plan = align_union_sorted_unique(&left, &right);
        let left_identity = semantic_index_identity("left", &left);
        let right_identity = semantic_index_identity("right", &right);
        let reference = semantic_index_identity("output", &plan.union_index);

        std::thread::scope(|scope| {
            let mut handles = Vec::new();
            for _ in 0..8 {
                handles.push(scope.spawn(|| {
                    semantic_sorted_unique_union_output_fingerprint(
                        &left,
                        &right,
                        &plan.union_index,
                        &left_identity.fingerprint,
                        &right_identity.fingerprint,
                    )
                    .expect("sorted unique fingerprint")
                }));
            }
            for handle in handles {
                assert_eq!(handle.join().expect("thread"), reference.fingerprint);
            }
        });
    }

    #[test]
    fn series_add_emits_alignment_semantic_witness_tn6qb3() {
        let left = Series::from_values(
            "left",
            vec![1_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(10), Scalar::Int64(30)],
        )
        .expect("left");
        let right = Series::from_values(
            "right",
            vec![2_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(2), Scalar::Int64(4)],
        )
        .expect("right");
        let mut ledger = EvidenceLedger::new();

        let out = left
            .add_with_policy(&right, &RuntimePolicy::hardened(Some(100)), &mut ledger)
            .expect("add should pass");

        assert_eq!(
            out.index().labels(),
            &[1_i64.into(), 2_i64.into(), 3_i64.into()]
        );
        let witnesses = ledger.semantic_witnesses();
        assert_eq!(witnesses.len(), 1);
        let witness = &witnesses[0];
        assert_eq!(witness.operation, "series.add");
        assert_eq!(
            witness.materialization_reason,
            "series_binary_arithmetic_materialization"
        );
        assert_eq!(witness.alignment_mode, "outer");
        assert_eq!(witness.input_index_identity.len(), 2);
        assert_eq!(witness.input_index_identity[0].role, "left");
        assert_eq!(witness.input_index_identity[0].len, 2);
        assert!(!witness.input_index_identity[0].has_duplicates);
        assert_eq!(witness.input_index_identity[1].role, "right");
        assert_eq!(witness.output_index_identity.role, "output");
        assert_eq!(witness.output_index_identity.len, 3);
        assert!(
            witness
                .input_index_identity
                .iter()
                .all(|identity| identity.fingerprint.starts_with("sha256:"))
        );
        assert!(witness.null_nan_policy.contains("nulls/NaNs"));
        assert!(witness.output_ordering_contract.contains("unique outer"));
    }

