    #[test]
    fn dataframe_from_records_sparse_keys_null_fill() {
        let records = vec![
            BTreeMap::from([
                ("a".to_owned(), Scalar::Int64(1)),
                ("b".to_owned(), Scalar::Int64(10)),
            ]),
            BTreeMap::from([("a".to_owned(), Scalar::Int64(2))]),
            BTreeMap::from([("b".to_owned(), Scalar::Int64(30))]),
        ];

        let df = DataFrame::from_record_maps(records, None, None).unwrap();
        assert_eq!(
            df.index().labels(),
            &[0_i64.into(), 1_i64.into(), 2_i64.into()]
        );
        // A key absent from a record is a gap the CONSTRUCTOR invents, so pandas
        // fills NaN and widens the column to float64. Measured on 2.2.3:
        //   pd.DataFrame.from_records([{'a':1,'b':10},{'a':2},{'b':30}])
        //     a: [1.0, 2.0, NaN]   b: [10.0, NaN, 30.0]   both float64
        // Previously pinned Int64 + Null(Null) (br-frankenpandas-nywa8).
        assert_eq!(
            df.column("a").unwrap().values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
            ]
        );
        assert_eq!(
            df.column("b").unwrap().values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(30.0),
            ]
        );
    }

    #[test]
    fn dataframe_from_records_column_order_allows_new_null_column() {
        let records = vec![
            BTreeMap::from([("a".to_owned(), Scalar::Int64(1))]),
            BTreeMap::from([("a".to_owned(), Scalar::Int64(2))]),
        ];
        let order = vec!["a".to_owned(), "z".to_owned()];

        let df = DataFrame::from_record_maps(records, Some(&order), None).unwrap();
        let names = df
            .column_names()
            .into_iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        assert_eq!(names, vec!["a", "z"]);
        // 'z' is named in `columns=` but supplied by no record, so every cell is
        // invented. Measured: from_records([{'a':1},{'a':2}], columns=['a','z'])
        // gives z as an all-NaN float64 column while 'a' stays int64
        // (br-frankenpandas-nywa8).
        assert_eq!(
            df.column("z").unwrap().values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)]
        );
        assert_eq!(
            df.column("a").unwrap().values(),
            &[Scalar::Int64(1), Scalar::Int64(2)]
        );
    }

