    /// `dtype='int64'` REFUSES a missing value; `dtype='Int64'` keeps it.
    /// br-frankenpandas-v1zy1. MEASURED, live pandas 2.2.3, on
    /// `[[True, None], [False, True]]`: `int64` -> TypeError, `Int64` ->
    /// `[[1, <NA>], [0, 1]]`. Before the fix FrankenPandas returned `[1, Null]`
    /// for both, so the two dtypes were behaviourally identical here.
    /// The timedelta64 constructor refuses a non-finite float where `astype`
    /// accepts one — the constructor-only strictness `float_to_temporal_nanos`
    /// documents and deliberately leaves to this layer. From live pandas 2.2.3.
    #[test]
    fn constructor_dtype_timedelta64_refuses_a_non_finite_float() {
        let one_value = |v: f64| {
            DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Float64(v)])]).expect("frame")
        };

        for (value, fragment) in [
            (f64::INFINITY, "infinity"),
            (f64::NEG_INFINITY, "infinity"),
            (1e30, "too large"),
            (-1e30, "too large"),
            (9_223_372_036_854_775_808.0, "too large"), // exactly 2^63
        ] {
            let err = one_value(value)
                .with_constructor_dtype(DType::Timedelta64)
                .expect_err("timedelta64 must refuse a non-finite float");
            assert!(
                format!("{err}").contains(fragment),
                "expected pandas' {fragment} message for {value}, got: {err}"
            );
        }

        // ⚠️ NaN IS ACCEPTED (it is a missing value, not an overflow), and so is
        // exactly -2^63, because that IS the NaT sentinel — Python's int
        // conversion succeeds and lands on NaT. The two 2^63 ends disagree.
        for value in [f64::NAN, -9_223_372_036_854_775_808.0] {
            let built = one_value(value)
                .with_constructor_dtype(DType::Timedelta64)
                .expect("NaN and -2^63 are accepted");
            assert!(built.column("a").expect("column").values()[0].is_missing());
        }

        // A finite float still truncates to nanoseconds.
        let finite = one_value(1.5)
            .with_constructor_dtype(DType::Timedelta64)
            .expect("finite float");
        assert_eq!(
            finite.column("a").expect("column").values()[0],
            Scalar::Timedelta64(1)
        );

        // ⚠️ datetime64 HAS NO SUCH REFUSAL: its constructor yields NaT for inf.
        let datetime = one_value(f64::INFINITY)
            .with_constructor_dtype(DType::Datetime64)
            .expect("datetime64 accepts inf");
        assert!(datetime.column("a").expect("column").values()[0].is_missing());
    }

    #[test]
    fn constructor_dtype_int64_refuses_a_missing_value_but_nullable_int64_keeps_it_v1zy1() {
        use fp_types::NullKind;
        let with_missing = || {
            DataFrame::from_dict(
                &["a"],
                vec![("a", vec![Scalar::Bool(true), Scalar::Null(NullKind::Null)])],
            )
            .expect("frame")
        };

        // numpy int64 cannot hold NA -> the construction is refused outright.
        let err = with_missing()
            .with_constructor_dtype(DType::Int64)
            .expect_err("int64 must refuse a missing value");
        assert!(
            format!("{err}").contains("not 'NoneType'"),
            "expected pandas' int(None) message, got: {err}"
        );

        // The nullable extension dtype accepts it, and the null SURVIVES.
        let kept = with_missing()
            .with_constructor_dtype(DType::Int64Nullable)
            .expect("Int64 accepts a missing value");
        assert_eq!(
            kept.columns["a"].values(),
            &[Scalar::Int64(1), Scalar::Null(NullKind::Null)]
        );

        // NON-VACUITY: the refusal is about the MISSING VALUE, not about int64
        // itself. Without this arm, a check that rejected every int64 cast would
        // pass the assertions above.
        let clean = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Bool(true), Scalar::Bool(false)])],
        )
        .expect("frame")
        .with_constructor_dtype(DType::Int64)
        .expect("int64 accepts a column with no missing value");
        assert_eq!(
            clean.columns["a"].values(),
            &[Scalar::Int64(1), Scalar::Int64(0)]
        );

        // float64 is NOT restricted: NaN is float64's own missing value.
        with_missing()
            .with_constructor_dtype(DType::Float64)
            .expect("float64 represents a missing value as NaN");
    }

    /// `dtype='bool'` COERCES a missing value by truthiness; `dtype='boolean'`
    /// keeps it. br-frankenpandas-constructor-bool-null-not-coerced-sgugy.
    ///
    /// MEASURED, live pandas 2.2.3 — note the two directions, which is the part a
    /// "coerce missing to false" rule would get wrong:
    ///   pd.DataFrame([[True, None], [False, True]], dtype='bool')  -> [[True, False], ...]
    ///   pd.DataFrame([[1.0, nan], [0.0, 1.0]],      dtype='bool')  -> [[True, True],  ...]
    ///   bool(None) is False; bool(float('nan')) and bool(pd.NaT) are True.
    ///
    /// FrankenPandas normalizes a float column's missing value to `NullKind::NaN`
    /// on construction, so the kind is a faithful proxy for pandas' rule.
    #[test]
    fn constructor_dtype_bool_coerces_missing_by_truthiness_sgugy() {
        use fp_types::NullKind;
        let cast = |v: Vec<Scalar>| {
            DataFrame::from_dict(&["a"], vec![("a", v)])
                .expect("frame")
                .with_constructor_dtype(DType::Bool)
                .expect("bool coerces rather than raising")
                .columns["a"]
                .values()
                .to_vec()
        };

        // None is FALSY.
        assert_eq!(
            cast(vec![Scalar::Bool(true), Scalar::Null(NullKind::Null)]),
            vec![Scalar::Bool(true), Scalar::Bool(false)]
        );

        // NaN and NaT are TRUTHY — the opposite direction, from the same code.
        assert_eq!(
            cast(vec![Scalar::Float64(1.0), Scalar::Null(NullKind::NaN)]),
            vec![Scalar::Bool(true), Scalar::Bool(true)]
        );
        assert_eq!(
            cast(vec![Scalar::Bool(true), Scalar::Null(NullKind::NaT)]),
            vec![Scalar::Bool(true), Scalar::Bool(true)]
        );

        // The NULLABLE dtype is untouched: it can represent NA, so it keeps it.
        let kept = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Bool(true), Scalar::Null(NullKind::Null)])],
        )
        .expect("frame")
        .with_constructor_dtype(DType::BoolNullable)
        .expect("boolean accepts a missing value");
        assert_eq!(
            kept.columns["a"].values(),
            &[Scalar::Bool(true), Scalar::Null(NullKind::Null)],
            "the nullable bool dtype must NOT coerce"
        );
    }

    /// `dtype='str'` at the CONSTRUCTOR preserves a missing value; `astype(str)`
    /// stringifies it. Both are pandas 2.2.3, measured:
    ///   pd.DataFrame([[True, None]], dtype='str')      -> [['True', None]]
    ///   pd.Series([True, None]).astype(str)            -> ['True', 'None']
    /// FrankenPandas used to give `Utf8("None")` for the constructor too, which
    /// made a genuine "None" string and a missing value indistinguishable.
    /// br-frankenpandas-constructor-utf8-null-stringified-r1bbv.
    #[test]
    fn constructor_dtype_str_preserves_a_missing_value_r1bbv() {
        use fp_types::NullKind;
        let cast = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Bool(true), Scalar::Null(NullKind::Null)])],
        )
        .expect("frame")
        .with_constructor_dtype(DType::Utf8)
        .expect("str accepts a missing value");

        assert_eq!(
            cast.columns["a"].values(),
            &[
                Scalar::Utf8("True".to_string()),
                Scalar::Null(NullKind::Null)
            ],
            "the missing value must survive, and true must render as pandas' 'True'"
        );

        // NON-VACUITY: a real "None" STRING must stay an ordinary string, so the
        // two are distinguishable. This is the whole point of the bead - a fix
        // that turned every "None" into a null would pass the assertion above.
        let literal = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Utf8("None".to_string()),
                    Scalar::Null(NullKind::Null),
                ],
            )],
        )
        .expect("frame")
        .with_constructor_dtype(DType::Utf8)
        .expect("str cast");
        assert_eq!(
            literal.columns["a"].values(),
            &[
                Scalar::Utf8("None".to_string()),
                Scalar::Null(NullKind::Null)
            ],
            "a literal \"None\" string and a missing value must stay distinct"
        );
    }

    /// The constructor's `dtype=` REFUSES a lossy float->int; pandas' `astype`
    /// truncates. Measured on pandas 2.2.3:
    ///   pd.DataFrame([[1.5]], dtype='int64')  -> ValueError: Trying to coerce
    ///                                            float values to integers
    ///   pd.DataFrame([[1.5]]).astype('int64') -> [[1]]
    ///   pd.DataFrame([[2.0]], dtype='int64')  -> [[2]]
    /// (br-frankenpandas-oxodo)
    #[test]
    fn dataframe_with_constructor_dtype_refuses_lossy_float_to_int() {
        let lossy =
            DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Float64(1.5)])]).expect("frame");
        lossy
            .with_constructor_dtype(DType::Int64)
            .expect_err("constructor dtype= refuses a lossy float->int");

        // A lossless float is accepted and lands as int64.
        let lossless =
            DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Float64(2.0)])]).expect("frame");
        let cast = lossless
            .with_constructor_dtype(DType::Int64)
            .expect("2.0 is representable as int64");
        assert_eq!(cast.columns["a"].values(), &[Scalar::Int64(2)]);

        // int -> float64 is the ordinary widening case.
        let widened = DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Int64(1)])])
            .expect("frame")
            .with_constructor_dtype(DType::Float64)
            .expect("int64 widens to float64");
        assert_eq!(widened.columns["a"].values(), &[Scalar::Float64(1.0)]);
    }

    /// The frame shape the zx21n baseline was measured on: float 'b', object
    /// 'label', int 'a'.
    fn numeric_only_probe_frame() -> DataFrame {
        DataFrame::from_dict(
            &["b", "label", "a"],
            vec![
                (
                    "b",
                    vec![
                        Scalar::Float64(-7.5),
                        Scalar::Float64(4.0),
                        Scalar::Float64(2.5),
                    ],
                ),
                (
                    "label",
                    vec![
                        Scalar::Utf8("a".into()),
                        Scalar::Utf8("z".into()),
                        Scalar::Utf8("m".into()),
                    ],
                ),
                (
                    "a",
                    vec![Scalar::Int64(-1), Scalar::Int64(5), Scalar::Int64(3)],
                ),
            ],
        )
        .expect("probe frame")
    }

    /// pandas 2.x `numeric_only=False` INCLUDES the object column for sum/min/max.
    /// Measured on live pandas 2.2.3 with this exact frame:
    ///   df.sum() -> {'b': -1.0, 'label': 'azm', 'a': 7}
    ///   df.min() -> {'b': -7.5, 'label': 'a',   'a': -1}
    ///   df.max() -> {'b':  4.0, 'label': 'z',   'a': 5}
    /// sum CONCATENATES in row order; min/max compare LEXICOGRAPHICALLY.
    /// (br-frankenpandas-reductions-numeric-only-default-zx21n)
    #[test]
    fn dataframe_reductions_numeric_only_false_includes_object_column() {
        let df = numeric_only_probe_frame();

        let sum = df.sum_with_numeric_only(false).expect("sum");
        let at = |s: &Series, label: &str| -> Scalar {
            let pos = s
                .index()
                .labels()
                .iter()
                .position(|l| matches!(l, IndexLabel::Utf8(t) if t == label))
                .unwrap_or_else(|| panic!("label {label} missing"));
            s.column().values()[pos].clone()
        };
        assert_eq!(at(&sum, "label"), Scalar::Utf8("azm".into()));

        let min = df.min_agg_with_numeric_only(false).expect("min");
        assert_eq!(at(&min, "label"), Scalar::Utf8("a".into()));

        let max = df.max_agg_with_numeric_only(false).expect("max");
        assert_eq!(at(&max, "label"), Scalar::Utf8("z".into()));
    }

    /// The other half of the split: pandas 2.x RAISES for these eight when a
    /// non-numeric column is present, e.g.
    ///   df.mean() -> TypeError: Could not convert ['azm'] to numeric
    /// A wrong choice here throws rather than producing a plausible number,
    /// which is why FuchsiaBass called this family the negative control.
    #[test]
    fn dataframe_reductions_numeric_only_false_raises_for_the_eight() {
        let df = numeric_only_probe_frame();
        df.mean_with_numeric_only(false).expect_err("mean raises");
        df.prod_with_numeric_only(false).expect_err("prod raises");
        df.median_with_numeric_only(false)
            .expect_err("median raises");
        df.std_agg_with_numeric_only(false).expect_err("std raises");
        df.var_agg_with_numeric_only(false).expect_err("var raises");
        df.sem_agg_with_numeric_only(false).expect_err("sem raises");
        df.skew_agg_with_numeric_only(false)
            .expect_err("skew raises");
        df.kurtosis_agg_with_numeric_only(false)
            .expect_err("kurt raises");
    }

    /// `numeric_only=true` must remain EXACTLY what it is today — it is the path
    /// the existing corpus pins, float64 promotion included. This is the
    /// regression guard for the capability being added without moving the
    /// default: `df.sum()` and `df.sum_with_numeric_only(true)` must agree, and
    /// neither may mention the object column.
    #[test]
    fn dataframe_reductions_numeric_only_true_still_skips_the_object_column() {
        let df = numeric_only_probe_frame();
        let has_label = |s: &Series| {
            s.index()
                .labels()
                .iter()
                .any(|l| matches!(l, IndexLabel::Utf8(t) if t == "label"))
        };

        // numeric_only=TRUE still skips the object column and still promotes
        // the int column to float64 — the path the 13 corrected fixtures pin.
        for explicit in [
            df.sum_with_numeric_only(true).unwrap(),
            df.mean_with_numeric_only(true).unwrap(),
            df.min_agg_with_numeric_only(true).unwrap(),
            df.std_agg_with_numeric_only(true).unwrap(),
        ] {
            assert!(
                !has_label(&explicit),
                "numeric_only=true must skip the object column"
            );
        }
    }

    /// `convert_dtypes()` and `infer_objects()` do NOT parse numeric-looking
    /// STRINGS. They retype what is already numeric; they never re-read text.
    ///
    /// MEASURED, live pandas 2.2.3:
    ///
    /// ```text
    /// pd.Series(['1','2','3'], dtype=object)
    ///   .infer_objects()  -> object  ['1','2','3']
    ///   .convert_dtypes() -> string  ['1','2','3']     STILL STRINGS
    ///
    /// pd.Series([1,2,3], dtype=object)      the objects ARE numbers
    ///   .infer_objects()  -> int64  [1,2,3]
    ///   .convert_dtypes() -> Int64  [1,2,3]
    ///
    /// pd.to_numeric(pd.Series(['1','2','3']))  -> int64 [1,2,3]
    /// ```
    ///
    /// Only `to_numeric` parses. FrankenPandas' `convert_dtypes` walked a Utf8
    /// column and `parse::<i64>()` / `parse::<f64>()`'d every cell, so
    /// `['1.5','2.7','3.14']` came back as float64 — a conversion pandas offers
    /// under a DIFFERENT function name. `infer_objects` delegates to the same
    /// code and inherited it.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn convert_dtypes_does_not_parse_numeric_looking_strings() {
        let strings = |vals: &[&str]| {
            Series::from_values(
                "x",
                (0..vals.len() as i64).map(IndexLabel::Int64).collect(),
                vals.iter().map(|v| Scalar::Utf8((*v).to_owned())).collect(),
            )
            .unwrap()
        };

        for vals in [["1", "2", "3"], ["1.5", "2.7", "3.14"]] {
            let subject = strings(&vals);
            let want: Vec<Scalar> = vals.iter().map(|v| Scalar::Utf8((*v).to_owned())).collect();
            assert_eq!(
                subject.convert_dtypes().unwrap().values(),
                want.as_slice(),
                "convert_dtypes retypes, it does not re-read text — only to_numeric parses"
            );
            assert_eq!(
                subject.infer_objects().unwrap().values(),
                want.as_slice(),
                "infer_objects likewise leaves strings as strings"
            );
        }

        // A non-Utf8 column is unaffected either way.
        let ints = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        assert_eq!(
            ints.convert_dtypes().unwrap().values(),
            &[Scalar::Int64(1), Scalar::Int64(2)]
        );
    }

    /// A NULL in the condition of `where`/`mask` behaves as FALSE — it selects
    /// the other operand rather than propagating a NaN.
    ///
    /// MEASURED, live pandas 2.2.3, with `df = [10.0, 20.0]`,
    /// `other = [100.0, 200.0]` and a condition of `[<NA>, False]`:
    ///
    /// ```text
    /// df.where(cond, other) -> [100.0, 200.0]   NA acts False -> take other
    /// df.mask(cond, other)  -> [100.0,  20.0]   mask is where(~cond), so the
    ///                                           NA row still takes other
    /// ```
    ///
    /// FrankenPandas produced `[nan, 200.0]` and `[nan, 20.0]`: it propagated
    /// the condition's missingness into the RESULT, which pandas never does —
    /// the condition is a selector, and an undecidable selector falls to the
    /// else-branch. Note the two disagree on row 1 (200.0 vs 20.0) exactly
    /// because `mask` inverts, which is the control that this is about the
    /// selector and not about the data.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn where_and_mask_treat_a_null_condition_as_false() {
        let frame = |name: &str, values: [f64; 2]| {
            DataFrame::from_dict_with_index(
                vec![(name, values.iter().map(|v| Scalar::Float64(*v)).collect())],
                (0..2_i64).map(IndexLabel::Int64).collect(),
            )
            .unwrap()
        };
        let subject = frame("a", [10.0, 20.0]);
        let other = frame("a", [100.0, 200.0]);
        let cond = DataFrame::from_dict_with_index(
            vec![("a", vec![Scalar::Null(NullKind::Null), Scalar::Bool(false)])],
            (0..2_i64).map(IndexLabel::Int64).collect(),
        )
        .unwrap();

        assert_eq!(
            subject
                .where_cond_df(&cond, &other)
                .unwrap()
                .column("a")
                .unwrap()
                .values(),
            &[Scalar::Float64(100.0), Scalar::Float64(200.0)],
            "a null condition is FALSE, so where takes `other` at that row"
        );
        assert_eq!(
            subject
                .mask_df_other(&cond, &other)
                .unwrap()
                .column("a")
                .unwrap()
                .values(),
            &[Scalar::Float64(100.0), Scalar::Float64(20.0)],
            "mask inverts, so the null row still takes `other` but row 1 keeps 20.0"
        );
    }

    /// The SCALAR-`other` sibling of `where_and_mask_treat_a_null_condition_as_false`
    /// above, which the 9s0c4 fix missed (br-frankenpandas-yf758).
    ///
    /// That test covers `where_cond_df` / `mask_df_other`. The scalar-`other`
    /// entry points reach `where_mask_typed_f64`, a separate typed fast path that
    /// still propagated the condition's missingness into the result and, in mask
    /// mode, kept self on a non-Bool condition where the general path takes
    /// `other`.
    ///
    /// MEASURED, live pandas 2.2.3, nullable-boolean cond `[NA, True, False]`
    /// over `[1.0, 2.0, 3.0]` with `other=99.0`:
    ///
    /// ```text
    ///   df.where(cond, 99.0) -> [99.0, 2.0, 99.0]
    ///   df.mask (cond, 99.0) -> [99.0, 99.0, 3.0]
    /// ```
    ///
    /// Row 0 is the NA-cond cell: it takes 99.0 in BOTH modes and is never NaN.
    /// Rows 1-2 disagree between the modes, which is the control proving this is
    /// about the SELECTOR and not about the data.
    #[test]
    fn scalar_where_and_mask_take_other_on_a_null_condition_yf758() {
        let index = || (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>();
        let subject = DataFrame::from_dict_with_index(
            vec![(
                "a",
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                ],
            )],
            index(),
        )
        .unwrap();
        let cond = DataFrame::from_dict_with_index(
            vec![(
                "a",
                vec![
                    Scalar::Null(NullKind::Null),
                    Scalar::Bool(true),
                    Scalar::Bool(false),
                ],
            )],
            index(),
        )
        .unwrap();
        let fill = Scalar::Float64(99.0);

        let got = |df: &DataFrame| df.column("a").unwrap().values().to_vec();

        assert_eq!(
            got(&subject.where_cond(&cond, Some(&fill)).unwrap()),
            vec![
                Scalar::Float64(99.0),
                Scalar::Float64(2.0),
                Scalar::Float64(99.0)
            ],
            "a null condition is not a null RESULT: where takes `other` there"
        );
        assert_eq!(
            got(&subject.mask(&cond, Some(&fill)).unwrap()),
            vec![
                Scalar::Float64(99.0),
                Scalar::Float64(99.0),
                Scalar::Float64(3.0)
            ],
            "mask inverts rows 1-2 but the null row still takes `other`"
        );
    }

    /// The property br-frankenpandas-yf758's proptests actually assert, reduced
    /// to its cause: the answer must not depend on which internal path ran.
    ///
    /// `where_mask_typed_f64` engages only for Float64 columns, so an Int64 frame
    /// took the general Scalar path and a Float64 frame took the typed path. The
    /// two disagreed on a null condition, so translating the data (Int64 -> f64)
    /// changed the answer and `where(x + c, cond, fill + c)` stopped equalling
    /// `where(x, cond, fill) + c`.
    ///
    /// A naive implementation that fixes only the Float64 path in isolation still
    /// passes the test above; this one fails unless BOTH paths agree.
    #[test]
    fn typed_and_scalar_where_paths_agree_on_a_null_condition_yf758() {
        let index = || (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>();
        let cond = DataFrame::from_dict_with_index(
            vec![("a", vec![Scalar::Null(NullKind::Null), Scalar::Bool(true)])],
            index(),
        )
        .unwrap();
        let fill = Scalar::Float64(7.5);

        // Same values, two dtypes: Int64 takes the general path, Float64 takes
        // the typed path.
        let int_frame = DataFrame::from_dict_with_index(
            vec![("a", vec![Scalar::Int64(1), Scalar::Int64(2)])],
            index(),
        )
        .unwrap();
        let float_frame = DataFrame::from_dict_with_index(
            vec![("a", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)])],
            index(),
        )
        .unwrap();
        assert_eq!(int_frame.column("a").unwrap().dtype(), DType::Int64);
        assert_eq!(float_frame.column("a").unwrap().dtype(), DType::Float64);

        for mask_mode in [false, true] {
            let run = |df: &DataFrame| {
                let out = if mask_mode {
                    df.mask(&cond, Some(&fill)).unwrap()
                } else {
                    df.where_cond(&cond, Some(&fill)).unwrap()
                };
                out.column("a")
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| v.to_f64().ok())
                    .collect::<Vec<_>>()
            };
            assert_eq!(
                run(&int_frame),
                run(&float_frame),
                "mask_mode={mask_mode}: the general and typed paths must agree, \
                 or translating an Int64 frame to Float64 changes the answer"
            );
            // And the null row is `other` in both modes, not a missing cell.
            assert_eq!(
                run(&float_frame)[0],
                Some(7.5),
                "mask_mode={mask_mode}: null condition takes `other`"
            );
        }
    }

    /// `pct_change()` FORWARD-FILLS before differencing — that is pandas 2.2.3's
    /// default, and it is what makes the interior rows finite.
    ///
    /// MEASURED, live pandas 2.2.3, on `pd.Series([10.0, None, 30.0, 40.0, 50.0])`:
    ///
    /// ```text
    /// .pct_change()                   -> [nan, 0.0, 2.0, 0.333333, 0.25]
    /// .pct_change(fill_method=None)   -> [nan, nan, nan, 0.333333, 0.25]
    /// ```
    ///
    /// The default pads the gap to 10.0 first, so row 1 is `(10-10)/10 = 0.0`
    /// and row 2 is `(30-10)/10 = 2.0`. With no fill both propagate NaN. The two
    /// differ only at the rows adjacent to the gap, which is exactly where a
    /// fixture pinning the no-fill answer looks plausible.
    ///
    /// ⚠️ pandas 2.2 DEPRECATES this default and warns that `fill_method` will
    /// become `None` in a future version. FrankenPandas targets the pinned
    /// 2.2.3 behaviour, so `pad` stays the default here; `pct_change_with_fill`
    /// reaches the other path. Revisit if the pandas pin moves to 3.x.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn pct_change_forward_fills_by_default_like_pandas_2x() {
        let subject = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Float64(10.0),
                Scalar::Null(NullKind::Null),
                Scalar::Float64(30.0),
                Scalar::Float64(40.0),
                Scalar::Float64(50.0),
            ],
        )
        .unwrap();

        let got: Vec<Option<f64>> = subject
            .pct_change(1)
            .unwrap()
            .values()
            .iter()
            .map(|v| {
                if v.is_missing() {
                    None
                } else {
                    v.to_f64().ok()
                }
            })
            .collect();
        let want = [None, Some(0.0), Some(2.0), Some(1.0 / 3.0), Some(0.25)];
        for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            match (g, w) {
                (None, None) => {}
                (Some(g), Some(w)) => assert!(
                    (g - w).abs() < 1e-12,
                    "pct_change row {i}: got {g}, pandas gives {w} (full {got:?})"
                ),
                _ => panic!("pct_change row {i}: got {g:?}, pandas gives {w:?}"),
            }
        }

        // The no-fill path is still reachable and is what a fixture pinning
        // [nan, nan, nan, ...] would have been describing.
        let no_fill: Vec<bool> = subject
            .pct_change_with_fill(1, None, None)
            .unwrap()
            .values()
            .iter()
            .map(fp_types::Scalar::is_missing)
            .collect();
        assert_eq!(no_fill, vec![true, true, true, false, false]);
    }

    /// `pd.DataFrame(dict, columns=[...])` aligns only the SELECTED columns, so
    /// the row count depends on which columns were asked for.
    ///
    /// MEASURED, live pandas 2.2.3, `a` indexed `[1,2]` and `b` indexed `[2,3]`:
    ///
    /// ```text
    /// pd.DataFrame({'a': a, 'b': b})                 index [1, 2, 3]
    /// pd.DataFrame({'a': a, 'b': b}, columns=['b'])  index [2, 3]
    ///     b -> [30, 40]  int64      no gap invented, so no widening
    /// pd.DataFrame({'a': a, 'b': b}, columns=['a','z'])
    ///                                               index [1, 2]
    ///     a -> [10, 20]  int64
    ///     z -> [nan, nan] object    absent name contributes NO labels
    /// ```
    ///
    /// FrankenPandas built the full union and projected afterwards, giving
    /// THREE rows where pandas gives two and null-filling columns pandas leaves
    /// intact. The row count is the observable, which is why this shows up in
    /// the corpus as a SHAPE divergence rather than a value one.
    /// (br-frankenpandas-oxodo, br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn dataframe_from_series_with_columns_aligns_only_the_selected_columns() {
        let mk = |name: &str, labels: [i64; 2], values: [i64; 2]| {
            Series::from_values(
                name,
                labels.iter().map(|l| IndexLabel::Int64(*l)).collect(),
                values.iter().map(|v| Scalar::Int64(*v)).collect(),
            )
            .unwrap()
        };
        let inputs = || vec![mk("a", [1, 2], [10, 20]), mk("b", [2, 3], [30, 40])];

        // Baseline: no selection is the plain union.
        assert_eq!(
            DataFrame::from_series_with_columns(inputs(), None)
                .unwrap()
                .index()
                .len(),
            3
        );

        // Selecting only 'b' narrows the index to b's own labels.
        let only_b =
            DataFrame::from_series_with_columns(inputs(), Some(&["b".to_owned()])).unwrap();
        assert_eq!(
            only_b.index().labels(),
            &[IndexLabel::Int64(2), IndexLabel::Int64(3)],
            "the index spans the SELECTED columns, not every dict entry"
        );
        assert_eq!(
            only_b.column("b").unwrap().values(),
            &[Scalar::Int64(30), Scalar::Int64(40)],
            "no gap is invented, so b stays int64"
        );

        // An absent name contributes no labels and becomes all-missing.
        let with_absent =
            DataFrame::from_series_with_columns(inputs(), Some(&["a".to_owned(), "z".to_owned()]))
                .unwrap();
        assert_eq!(
            with_absent.index().labels(),
            &[IndexLabel::Int64(1), IndexLabel::Int64(2)]
        );
        assert_eq!(
            with_absent.column("a").unwrap().values(),
            &[Scalar::Int64(10), Scalar::Int64(20)]
        );
        assert_eq!(
            with_absent.column("z").unwrap().values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)],
            "an absent name is an INVENTED all-missing column, so its gap is NaN"
        );
    }

    /// The dict-of-VALUES sibling of the test above: `pd.DataFrame(dict,
    /// columns=[...])` is a SELECTOR, not an ordering hint.
    ///
    /// MEASURED, live pandas 2.2.3, `d = {"a": [1, 2], "b": [3, 4]}`:
    ///
    /// ```text
    /// pd.DataFrame(d, columns=["a", "z"])   a=[1,2]  z=[nan,nan] object
    /// pd.DataFrame(d, columns=["b"])        ONLY b — 'a' is DROPPED
    /// pd.DataFrame(d, columns=["z", "y"])   shape (0, 2), empty index
    /// pd.DataFrame(d, columns=[])           shape (0, 0)
    /// pd.DataFrame(d, columns=[], index=[10, 20])     shape (2, 0)
    /// pd.DataFrame(d, columns=["a"], index=[1, 2, 3]) ValueError (length)
    /// pd.DataFrame({"a":[1,2],"b":[3]}, columns=["a"]) OK — an UNSELECTED
    ///     ragged column is dropped before the equal-length check
    /// ```
    ///
    /// Each assertion below is one a naive implementation gets wrong, and three
    /// of them are what `DataFrame::from_dict` does today (it is a different
    /// operation and stays as it is): from_dict REJECTS the absent name, APPENDS
    /// the unlisted key instead of dropping it, and would give an all-absent
    /// selector two missing ROWS instead of none.
    /// (br-frankenpandas-oxodo)
    #[test]
    fn dataframe_from_dict_with_columns_is_a_selector_not_an_ordering() {
        let data = || {
            vec![
                ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("b", vec![Scalar::Int64(3), Scalar::Int64(4)]),
            ]
        };
        let cols =
            |names: &[&str]| -> Vec<String> { names.iter().map(|n| (*n).to_owned()).collect() };

        // An absent name is accepted and becomes all-missing — pandas does NOT
        // raise here, and `from_dict` does.
        let with_absent =
            DataFrame::from_dict_with_columns(data(), Some(&cols(&["a", "z"])), None).unwrap();
        assert_eq!(with_absent.column_names(), vec!["a", "z"]);
        assert_eq!(
            with_absent.column("a").unwrap().values(),
            &[Scalar::Int64(1), Scalar::Int64(2)]
        );
        assert_eq!(
            with_absent.column("z").unwrap().values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)]
        );
        assert!(
            DataFrame::from_dict(&["a", "z"], data()).is_err(),
            "from_dict is the ordering-hint operation and still rejects an \
             absent name; the two must not be collapsed"
        );

        // An unlisted key is DROPPED, not appended.
        let only_b = DataFrame::from_dict_with_columns(data(), Some(&cols(&["b"])), None).unwrap();
        assert_eq!(only_b.column_names(), vec!["b"]);
        assert_eq!(
            only_b.column("b").unwrap().values(),
            &[Scalar::Int64(3), Scalar::Int64(4)]
        );

        // No requested name exists -> no index to take a length from, so the
        // frame is 0 rows wide rather than 2 rows of nulls.
        let none_present =
            DataFrame::from_dict_with_columns(data(), Some(&cols(&["z", "y"])), None).unwrap();
        assert_eq!(none_present.column_names(), vec!["z", "y"]);
        assert_eq!(none_present.index().len(), 0);
        assert!(none_present.column("z").unwrap().values().is_empty());

        // An empty selector keeps the explicit index but no columns.
        let no_columns = DataFrame::from_dict_with_columns(data(), Some(&[]), None).unwrap();
        assert_eq!(no_columns.index().len(), 0);
        assert!(no_columns.column_names().is_empty());
        let no_columns_indexed = DataFrame::from_dict_with_columns(
            data(),
            Some(&[]),
            Some(vec![IndexLabel::Int64(10), IndexLabel::Int64(20)]),
        )
        .unwrap();
        assert_eq!(no_columns_indexed.index().len(), 2);
        assert!(no_columns_indexed.column_names().is_empty());

        // An explicit index sets the row count, and a selected column that does
        // not match it is a length error.
        let indexed = DataFrame::from_dict_with_columns(
            data(),
            Some(&cols(&["a", "z"])),
            Some(vec![IndexLabel::Int64(10), IndexLabel::Int64(20)]),
        )
        .unwrap();
        assert_eq!(
            indexed.index().labels(),
            &[IndexLabel::Int64(10), IndexLabel::Int64(20)]
        );
        assert_eq!(
            indexed.column("z").unwrap().values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)]
        );
        assert!(
            DataFrame::from_dict_with_columns(
                data(),
                Some(&cols(&["a"])),
                Some(vec![
                    IndexLabel::Int64(1),
                    IndexLabel::Int64(2),
                    IndexLabel::Int64(3),
                ]),
            )
            .is_err(),
            "a selected column whose length does not match an explicit index is \
             a ValueError in pandas"
        );

        // An UNSELECTED ragged column is dropped before the length check.
        let ragged = vec![
            ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ("b", vec![Scalar::Int64(3)]),
        ];
        let dropped_ragged =
            DataFrame::from_dict_with_columns(ragged, Some(&cols(&["a"])), None).unwrap();
        assert_eq!(dropped_ragged.index().len(), 2);
        assert_eq!(
            dropped_ragged.column("a").unwrap().values(),
            &[Scalar::Int64(1), Scalar::Int64(2)]
        );

        // A repeated selector would need duplicate column labels, which the
        // column store cannot represent (br-frankenpandas-ih4t0).
        assert!(DataFrame::from_dict_with_columns(data(), Some(&cols(&["a", "a"])), None).is_err());

        // No selector at all is the plain dict constructor.
        let unselected = DataFrame::from_dict_with_columns(data(), None, None).unwrap();
        assert_eq!(unselected.column_names(), vec!["a", "b"]);
        assert_eq!(unselected.index().len(), 2);
    }

    /// `idxmin`/`idxmax` return the index LABEL with its own dtype, and they
    /// answer for an OBJECT column too.
    ///
    /// MEASURED, live pandas 2.2.3:
    ///
    /// ```text
    /// d = DataFrame({'grp': ['x','x','x'], 'val': [30,10,20]}, index=[0,1,2])
    /// d.groupby('grp').idxmin()
    ///   -> {'val': [1]}   dtype int64   the LABEL, still an integer
    ///
    /// d2 = DataFrame({'num': [1.0,5.0,2.0], 'txt': ['x','z','y']},
    ///                index=['r0','r1','r2'])
    /// d2.idxmax()
    ///   -> {'num': 'r1', 'txt': 'r1'}   the object column IS answered for
    /// d2.idxmax(numeric_only=True)
    ///   -> {'num': 'r1'}
    /// ```
    ///
    /// Two separate defects: FrankenPandas STRINGIFIED the label (returning
    /// `'1'` for an Int64 index), and it emitted a null for the object column
    /// instead of the label of its lexicographic max. The second is the same
    /// numeric_only=False default settled for the reductions in
    /// br-frankenpandas-reductions-numeric-only-default-zx21n, which did not
    /// cover idxmin/idxmax — they were not among its 13 fixtures.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn idxmin_idxmax_keep_the_label_dtype_and_answer_for_object_columns() {
        let grouped = DataFrame::from_dict_with_index(
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("x".into()),
                        Scalar::Utf8("x".into()),
                        Scalar::Utf8("x".into()),
                    ],
                ),
                (
                    "val",
                    vec![Scalar::Int64(30), Scalar::Int64(10), Scalar::Int64(20)],
                ),
            ],
            (0..3_i64).map(IndexLabel::Int64).collect(),
        )
        .unwrap();
        assert_eq!(
            grouped
                .groupby(&["grp"])
                .unwrap()
                .idxmin()
                .unwrap()
                .column("val")
                .unwrap()
                .values(),
            &[Scalar::Int64(1)],
            "the label of an Int64 index stays Int64; stringifying it gives '1'"
        );

        let frame = DataFrame::from_dict_with_index(
            vec![
                (
                    "num",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(5.0),
                        Scalar::Float64(2.0),
                    ],
                ),
                (
                    "txt",
                    vec![
                        Scalar::Utf8("x".into()),
                        Scalar::Utf8("z".into()),
                        Scalar::Utf8("y".into()),
                    ],
                ),
            ],
            ["r0", "r1", "r2"]
                .iter()
                .map(|l| IndexLabel::Utf8((*l).to_owned()))
                .collect(),
        )
        .unwrap();
        assert_eq!(
            frame.idxmax().unwrap().values(),
            &[Scalar::Utf8("r1".into()), Scalar::Utf8("r1".into())],
            "idxmax answers for the object column too — 'z' is its max, at label r1"
        );
    }

    /// The rest of the Unicode case family, measured together so the
    /// titlecase fix cannot be over-generalised.
    ///
    /// MEASURED, live pandas 2.2.3 (and CPython):
    ///
    /// ```text
    /// swapcase   'straße' -> 'STRASSE'    ß is LOWERCASE, so it UPPERCASES to "SS"
    ///            'Ssharp' -> 'sSHARP'
    ///            'Élan'   -> 'éLAN'
    ///
    /// istitle    'Ssharp' -> True         titlecased word initial
    ///            'SSharp' -> False        second S must be lowercase
    ///            'Élan'   -> True
    ///            'straße' -> False
    ///            'o’neill'-> False        ’ ends the word, so 'n' must be upper
    /// ```
    ///
    /// ⚠️ `swapcase` is the CONTROL, and it is why the titlecase change stops
    /// at `capitalize`/`title`. Swapping the case of a lowercase `ß` gives the
    /// UPPERCASE mapping `SS`, not the titlecase `Ss` — so `char::to_uppercase`
    /// is correct there and must not be "fixed" to match its siblings. Three
    /// functions share the same shape and only two of them titlecase.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn swapcase_uppercases_where_title_titlecases_and_istitle_agrees() {
        let words = [
            "straße",
            "ßharp",
            "Ssharp",
            "SSharp",
            "Élan",
            "MAÑANA",
            "o’neill",
        ];
        let subject = Series::from_values(
            "x",
            (0..words.len() as i64).map(IndexLabel::Int64).collect(),
            words
                .iter()
                .map(|w| Scalar::Utf8((*w).to_owned()))
                .collect(),
        )
        .unwrap();

        assert_eq!(
            subject.str().swapcase().unwrap().values(),
            &[
                Scalar::Utf8("STRASSE".into()),
                Scalar::Utf8("SSHARP".into()),
                Scalar::Utf8("sSHARP".into()),
                Scalar::Utf8("ssHARP".into()),
                Scalar::Utf8("éLAN".into()),
                Scalar::Utf8("mañana".into()),
                Scalar::Utf8("O’NEILL".into()),
            ],
            "swapcase UPPERCASES a lowercase ß to 'SS' — it must NOT titlecase"
        );

        assert_eq!(
            subject.str().istitle().unwrap().values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(false),
            ],
            "istitle: 'Ssharp' is titled, 'SSharp' is not, and ’ ends a word"
        );

        // upper / lower / casefold complete the family. These EXPAND — the
        // output is longer than the input in codepoints — which is the property
        // a byte-wise or same-length implementation would get wrong. MEASURED:
        //   'straße'.upper()   == 'STRASSE'    (6 chars -> 7)
        //   'İstanbul'.lower() == 'i̇stanbul'   (8 -> 9, dot above is kept)
        //   'ﬁre'.upper()      == 'FIRE'       ligature expands
        //   'straße'.casefold()== 'strasse'
        let expanding = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("straße".into()),
                Scalar::Utf8("İstanbul".into()),
                Scalar::Utf8("ﬁre".into()),
            ],
        )
        .unwrap();
        assert_eq!(
            expanding.str().upper().unwrap().values(),
            &[
                Scalar::Utf8("STRASSE".into()),
                Scalar::Utf8("İSTANBUL".into()),
                Scalar::Utf8("FIRE".into()),
            ]
        );
        assert_eq!(
            expanding.str().lower().unwrap().values(),
            &[
                Scalar::Utf8("straße".into()),
                Scalar::Utf8("i\u{307}stanbul".into()),
                Scalar::Utf8("ﬁre".into()),
            ]
        );
    }

    /// `str.title()` titlecases each WORD's first character — same
    /// titlecase-not-uppercase rule as `capitalize`, applied per word.
    ///
    /// MEASURED, live pandas 2.2.3 (and CPython):
    ///
    /// ```text
    /// pd.Series(['straße hbf','ßharp note','élan VITAL']).str.title()
    ///   -> ['Straße Hbf', 'Ssharp Note', 'Élan Vital']
    /// ```
    ///
    /// `'ßharp note'.title() == 'Ssharp Note'` — the WORD-INITIAL ß titlecases
    /// to `Ss`, while the interior ß in `'straße hbf'` stays lowercase and is
    /// untouched. So the fix is exactly the one `capitalize` needed, applied at
    /// each word boundary rather than only at position 0, and it must NOT
    /// disturb interior characters. (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn str_title_titlecases_each_word_initial_not_uppercases_it() {
        let subject = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("straße hbf".into()),
                Scalar::Utf8("ßharp note".into()),
                Scalar::Utf8("élan VITAL".into()),
            ],
        )
        .unwrap();
        assert_eq!(
            subject.str().title().unwrap().values(),
            &[
                Scalar::Utf8("Straße Hbf".into()),
                Scalar::Utf8("Ssharp Note".into()),
                Scalar::Utf8("Élan Vital".into()),
            ],
            "a word-initial ß titlecases to 'Ss'; the interior ß in 'straße' must not change"
        );

        // The ASCII fast path must keep agreeing with the Unicode arm.
        let ascii = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("hELLO wORLD".into())],
        )
        .unwrap();
        assert_eq!(
            ascii.str().title().unwrap().values(),
            &[Scalar::Utf8("Hello World".into())]
        );
    }

    /// `str.capitalize()` TITLECASES the first character; it does not uppercase
    /// it. The two differ for the expanding cases.
    ///
    /// MEASURED, live pandas 2.2.3 (and CPython, which pandas defers to):
    ///
    /// ```text
    /// pd.Series(['straße','élan','ßharp','MAÑANA']).str.capitalize()
    ///   -> ['Straße', 'Élan', 'Ssharp', 'Mañana']
    ///
    /// 'ßharp'.capitalize() == 'Ssharp'      titlecase of 'ß' is 'Ss'
    /// 'ß'.upper()          == 'SS'          uppercase is BOTH letters
    /// ```
    ///
    /// FrankenPandas used `char::to_uppercase` for the first character, which
    /// Rust maps to `"SS"`, so it produced `'SSharp'`. Unicode gives `ß` a
    /// Titlecase_Mapping of `Ss` distinct from its Uppercase_Mapping of `SS`,
    /// and CPython's `capitalize` uses the titlecase one. The `ucd` crate
    /// already in this crate's dependencies exposes the full mapping.
    ///
    /// `str.title()` is deliberately NOT changed here: it is a different
    /// transform over word boundaries and no fixture flags it. The pinned
    /// values above are only about the first character of the whole string.
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn str_capitalize_titlecases_the_first_char_not_uppercases_it() {
        let subject = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("straße".into()),
                Scalar::Utf8("élan".into()),
                Scalar::Utf8("ßharp".into()),
                Scalar::Utf8("MAÑANA".into()),
            ],
        )
        .unwrap();
        assert_eq!(
            subject.str().capitalize().unwrap().values(),
            &[
                Scalar::Utf8("Straße".into()),
                Scalar::Utf8("Élan".into()),
                Scalar::Utf8("Ssharp".into()),
                Scalar::Utf8("Mañana".into()),
            ],
            "the leading ß titlecases to 'Ss'; uppercasing it would give 'SS'"
        );

        // The ASCII fast path must keep agreeing with the Unicode arm.
        let ascii = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("hELLO wORLD".into())],
        )
        .unwrap();
        assert_eq!(
            ascii.str().capitalize().unwrap().values(),
            &[Scalar::Utf8("Hello world".into())]
        );
    }

    /// `ewm(span=3).mean()` over a gap: the gap still DECAYS the prior weight,
    /// it does not restart or average.
    ///
    /// MEASURED, live pandas 2.2.3, on `pd.Series([1.0, None, 3.0, 4.0, 5.0])`
    /// with `span=3` (so `alpha = 2/(span+1) = 0.5`):
    ///
    /// ```text
    /// .ewm(span=3).mean()                  -> [1.0, 1.0, 2.6, 3.461538, 4.310345]
    /// .ewm(span=3, ignore_na=True).mean()  -> [1.0, 1.0, 2.333333, 3.285714, 4.2]
    /// ```
    ///
    /// The default is `ignore_na=False`, and index 2 is the discriminator. Hand
    /// check: the surviving observations are x0 at t=0 and x2 at t=2, so with
    /// two periods elapsed x0 carries weight `(1-a)^2 = 0.25`:
    /// `(0.25*1 + 1*3) / (0.25 + 1) = 2.6`. Under `ignore_na=True` the gap is
    /// skipped entirely and x0 weighs `(1-a)^1 = 0.5`, giving `2.333…`. An
    /// unweighted `(1+3)/2 = 2.0` is neither, and is the value the fixture
    /// pinned. (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn ewm_mean_decays_the_prior_weight_across_a_gap() {
        let subject = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::Null),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        let got: Vec<f64> = subject
            .ewm(Some(3.0), None)
            .mean()
            .unwrap()
            .values()
            .iter()
            .map(|v| v.to_f64().expect("ewm emits floats"))
            .collect();
        let want = [
            1.0,
            1.0,
            2.6,
            3.461_538_461_538_461_5,
            4.310_344_827_586_207,
        ];
        for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            assert!(
                (g - w).abs() < 1e-12,
                "ewm index {i}: got {g}, pandas gives {w} (full output {got:?})"
            );
        }
    }

    /// `get_dummies` SORTS its categories, and the DataFrame form APPENDS the
    /// encoded columns rather than leaving them in place.
    ///
    /// MEASURED, live pandas 2.2.3:
    ///
    /// ```text
    /// pd.Series(['b|a', 'a', '']).str.get_dummies()
    ///   columns -> ['a', 'b']            SORTED, not first-seen ('b' appears first)
    ///
    /// df = DataFrame({'id': [1,2,3], 'color': ['red','blue','red'],
    ///                 'size': ['S','M','S']})
    /// pd.get_dummies(df, columns=['color'], dtype=bool)
    ///   columns -> ['id', 'size', 'color_blue', 'color_red']
    ///              ^^^^^^^^^^^^^^  untouched columns keep their order
    ///                              ^^^^^^^^^^^^^^^^^^^^^^^^^ encoded ones are
    ///                              APPENDED, and sorted among themselves
    /// ```
    ///
    /// FrankenPandas used first-occurrence order for the categories and
    /// substituted the encoded columns IN PLACE, so it produced
    /// `['id', 'color_red', 'color_blue', 'size']` — wrong on both axes. A null
    /// in the source does not change either rule (measured: the same four
    /// columns, with `dummy_na=False` simply producing no indicator for it).
    /// (br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn get_dummies_sorts_categories_and_appends_the_encoded_columns() {
        let subject = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("b|a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8(String::new()),
            ],
        )
        .unwrap();
        assert_eq!(
            subject.str().get_dummies("|").unwrap().column_names(),
            vec!["a", "b"],
            "tokens are SORTED; 'b' appearing first must not put it first"
        );

        let frame = DataFrame::from_dict_with_index(
            vec![
                (
                    "id",
                    vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
                ),
                (
                    "color",
                    vec![
                        Scalar::Utf8("red".into()),
                        Scalar::Utf8("blue".into()),
                        Scalar::Utf8("red".into()),
                    ],
                ),
                (
                    "size",
                    vec![
                        Scalar::Utf8("S".into()),
                        Scalar::Utf8("M".into()),
                        Scalar::Utf8("S".into()),
                    ],
                ),
            ],
            (0..3_i64).map(IndexLabel::Int64).collect(),
        )
        .unwrap();
        assert_eq!(
            frame.get_dummies(&["color"]).unwrap().column_names(),
            vec!["id", "size", "color_blue", "color_red"],
            "untouched columns keep their order; encoded ones are APPENDED and sorted"
        );
    }

    /// `str.split(...).str.get(n)` carries BOTH null rules in ONE column: a
    /// supplied `None` survives, while an out-of-bounds index invents a `nan`.
    ///
    /// MEASURED, live pandas 2.2.3, on
    /// `pd.Series(['a_b_c', None, 'single', 'a_b_c_d_e_f'], dtype=object)`:
    ///
    /// ```text
    /// s.str.split('_').str.get(5)  -> [nan, None, nan, 'f']
    ///                                  kinds ['float', 'NoneType', 'float', 'str']
    ///                                  dtype object
    /// ```
    ///
    /// Index 1 is the caller's `None` and stays `None` (Rule 2, and what
    /// br-frankenpandas-str-null-kind-identity-lufpu established). Indices 0
    /// and 2 are positions the OPERATION could not fill, and those are float
    /// `nan` (Rule 1). The same column holds both markers, which is the
    /// sharpest available statement that the two rules are distinct and that
    /// collapsing either one onto the other is wrong.
    ///
    /// The `rsplit` sibling is the control: with `n = 0` nothing is out of
    /// bounds, so the only missing is the supplied one and it stays `None` —
    /// measured `['a', None, '', 'no_slash']`. (br-frankenpandas-nywa8)
    #[test]
    fn str_split_get_keeps_a_supplied_none_but_invents_nan_out_of_bounds() {
        let subject = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("a_b_c".into()),
                Scalar::Null(NullKind::Null),
                Scalar::Utf8("single".into()),
                Scalar::Utf8("a_b_c_d_e_f".into()),
            ],
        )
        .unwrap();

        assert_eq!(
            subject.str().split_get("_", 5).unwrap().values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::Null),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("f".into()),
            ],
            "out-of-bounds is an INVENTED gap (nan); the caller's None at index 1 must survive"
        );

        // Control: n = 0 puts nothing out of bounds, so the supplied None is
        // the only missing and no nan is invented.
        let slashed = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect(),
            vec![
                Scalar::Utf8("a/b/c".into()),
                Scalar::Null(NullKind::Null),
                Scalar::Utf8(String::new()),
                Scalar::Utf8("no_slash".into()),
            ],
        )
        .unwrap();
        assert_eq!(
            slashed.str().rsplit_get("/", 0).unwrap().values(),
            &[
                Scalar::Utf8("a".into()),
                Scalar::Null(NullKind::Null),
                Scalar::Utf8(String::new()),
                Scalar::Utf8("no_slash".into()),
            ]
        );
    }

    /// An UNMAPPED key makes `Series.map` invent a gap, so an int-valued
    /// mapping widens the whole result to float64 — Rule 1.
    ///
    /// MEASURED, live pandas 2.2.3:
    ///
    /// ```text
    /// pd.Series([1, 2, 99]).map({1: 10, 2: 20})
    ///   -> [10.0, 20.0, nan]   dtype float64   kinds ['float','float','float']
    /// ```
    ///
    /// The source is all-present int64 and every mapped value is an int, so the
    /// ONLY reason the column is float64 is the gap the unmapped `99` invents —
    /// a numpy int64 array cannot hold it. FrankenPandas emitted
    /// `[Int64(10), Int64(20), Null(NaN)]`: the marker was already right, the
    /// dtype was not, because `infer_dtype` ignores nulls and saw a pure-Int64
    /// column. Same shape as the `.str`/`.dt` accessor promotions.
    ///
    /// The control matters as much as the case: with FULL coverage no gap is
    /// invented and the result stays Int64, so the promotion must be caused by
    /// the gap and not by the operation.
    /// (br-frankenpandas-nywa8)
    #[test]
    fn series_map_promotes_to_float64_when_a_key_is_unmapped() {
        let subject = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(99)],
        )
        .unwrap();
        let mapping = vec![
            (Scalar::Int64(1), Scalar::Int64(10)),
            (Scalar::Int64(2), Scalar::Int64(20)),
        ];

        let mapped = subject.map(&mapping).unwrap();
        assert_eq!(
            mapped.values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Null(NullKind::NaN)
            ],
            "the unmapped key invents a gap, so the whole column widens to float64"
        );

        // Control: full coverage invents nothing, so nothing widens.
        let full = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap()
        .map(&mapping)
        .unwrap();
        assert_eq!(
            full.values(),
            &[Scalar::Int64(10), Scalar::Int64(20)],
            "with every key mapped there is no gap and the result stays int64"
        );

        // A Utf8-valued mapping has no int to widen: pandas keeps the column
        // object and renders the gap as nan.
        let utf8_mapping = vec![
            (Scalar::Int64(1), Scalar::Utf8("ten".into())),
            (Scalar::Int64(2), Scalar::Utf8("twenty".into())),
        ];
        let strings = subject.map(&utf8_mapping).unwrap();
        assert_eq!(
            strings.values(),
            &[
                Scalar::Utf8("ten".into()),
                Scalar::Utf8("twenty".into()),
                Scalar::Null(NullKind::NaN)
            ]
        );
    }

    /// `DataFrame::from_series` invents a gap wherever a series is absent from
    /// the union index, and that gap is a NaN — Rule 1.
    ///
    /// MEASURED, live pandas 2.2.3, with
    /// `a = Series([10,30], index=[1,3])` and `b = Series([20,300], index=[2,3])`:
    ///
    /// ```text
    /// pd.DataFrame({'a': a, 'b': b})
    ///   index  -> [1, 2, 3]                   the SORTED union
    ///   a      -> float64 [10.0, nan, 30.0]   int64 widened by the gap
    ///   b      -> float64 [nan, 20.0, 300.0]
    /// ```
    ///
    /// The index is worth pinning alongside the marker: the conformance oracle
    /// modelled this operation as `pd.concat(axis=1, sort=False)`, which gives
    /// discovery order `[1, 3, 2]` instead, and that mismatch was being read as
    /// a FrankenPandas value divergence. Fixed in `op_dataframe_from_series`.
    /// (br-frankenpandas-nywa8, br-frankenpandas-fixture-divergence-triage-9s0c4)
    #[test]
    fn dataframe_from_series_union_gap_is_nan_over_the_sorted_union() {
        let mk = |name: &str, labels: [i64; 2], values: [i64; 2]| {
            Series::from_values(
                name,
                labels.iter().map(|l| IndexLabel::Int64(*l)).collect(),
                values.iter().map(|v| Scalar::Int64(*v)).collect(),
            )
            .unwrap()
        };
        let df =
            DataFrame::from_series(vec![mk("a", [1, 3], [10, 30]), mk("b", [2, 3], [20, 300])])
                .unwrap();

        assert_eq!(
            df.index().labels(),
            &[
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3)
            ],
            "the constructor aligns on the SORTED union, not concat's discovery order"
        );
        for (name, expected) in [
            ("a", [Some(10.0), None, Some(30.0)]),
            ("b", [None, Some(20.0), Some(300.0)]),
        ] {
            let values = df.column(name).unwrap().values().to_vec();
            for (i, want) in expected.iter().enumerate() {
                match want {
                    Some(number) => assert_eq!(
                        values[i],
                        Scalar::Float64(*number),
                        "{name}[{i}]: the gap widens the whole column to float64"
                    ),
                    None => assert_eq!(
                        values[i],
                        Scalar::Null(NullKind::NaN),
                        "{name}[{i}]: an INVENTED gap is a NaN, never a generic Null"
                    ),
                }
            }
        }
    }

    /// The CUMULATIVE forms accumulate an object column too — they do not pass
    /// it through untouched, and they have no `numeric_only` option at all.
    ///
    /// This is the sibling sweep the bead asked for. MEASURED, live pandas
    /// 2.2.3, on a frame with a float `b`, an object `label` = ['a','z','m']
    /// and an int `a`:
    ///
    /// ```text
    /// df.cumsum()   label -> ['a', 'az', 'azm']   RUNNING CONCATENATION
    /// df.cummin()   label -> ['a', 'a',  'a'  ]   running LEXICOGRAPHIC min
    /// df.cummax()   label -> ['a', 'z',  'z'  ]   running LEXICOGRAPHIC max
    /// df.cumprod()  -> TypeError: can't multiply sequence by non-int of type 'str'
    ///
    /// df.cumsum(numeric_only=True)
    ///   -> TypeError: cumsum() got an unexpected keyword argument 'numeric_only'
    /// ```
    ///
    /// and the int column stays int64 in all three — no promotion, because no
    /// gap is introduced. So the family splits the same way the plain
    /// reductions do (three accumulate, one raises), but WITHOUT the
    /// numeric_only escape hatch: like `nunique`, these four simply have no
    /// such parameter.
    /// (br-frankenpandas-reductions-numeric-only-default-zx21n)
    #[test]
    fn dataframe_cumulative_forms_accumulate_an_object_column() {
        let df = numeric_only_probe_frame();
        let label =
            |frame: &DataFrame| -> Vec<Scalar> { frame.column("label").unwrap().values().to_vec() };
        let utf8 = |parts: [&str; 3]| -> Vec<Scalar> {
            parts
                .iter()
                .map(|s| Scalar::Utf8((*s).to_owned()))
                .collect()
        };

        assert_eq!(
            label(&df.cumsum().unwrap()),
            utf8(["a", "az", "azm"]),
            "cumsum runs a CONCATENATION down an object column; passing the \
             column through unchanged returns the input and is a silent wrong \
             answer"
        );
        assert_eq!(label(&df.cummin().unwrap()), utf8(["a", "a", "a"]));
        assert_eq!(label(&df.cummax().unwrap()), utf8(["a", "z", "z"]));

        let err = df.cumprod().unwrap_err().to_string();
        assert!(
            err.contains("label"),
            "cumprod must refuse an object column and name it; got {err}"
        );

        // The numeric columns are untouched by all of this, and the int column
        // keeps its dtype — a cumulative op introduces no gap, so nothing
        // widens.
        let cumsum = df.cumsum().unwrap();
        assert_eq!(
            cumsum.column("a").unwrap().values(),
            &[Scalar::Int64(-1), Scalar::Int64(4), Scalar::Int64(7)]
        );
    }

    /// The DEFAULT is pandas 2.x's `numeric_only=False`, and this is the test
    /// that would have caught the old behaviour.
    ///
    /// MEASURED, live pandas 2.2.3, on a frame with a float `b`, an object
    /// `label` and an int `a`:
    ///
    /// ```text
    /// df.sum()   -> {'b': -4.0, 'label': 'azm', 'a': 5}   object CONCATENATED,
    ///                                                     'a' stays int64
    /// df.min()   -> {'b': -7.5, 'label': 'a',   'a': -1}  object LEXICOGRAPHIC
    /// df.max()   -> {'b':  2.0, 'label': 'z',   'a': 5}
    /// df.mean()  -> TypeError: Could not convert ['azm'] to numeric
    /// ```
    ///
    /// and the same TypeError for prod / median / std / var / sem / skew /
    /// kurt. `df.sum()` is one of the most-used calls in the API, so this was
    /// not an edge case: FrankenPandas silently returned the pandas-1.x answer.
    /// (br-frankenpandas-reductions-numeric-only-default-zx21n)
    #[test]
    fn dataframe_reductions_default_to_numeric_only_false_like_pandas_2x() {
        let df = numeric_only_probe_frame();
        let cell = |s: &Series, want: &str| -> Option<Scalar> {
            s.index()
                .labels()
                .iter()
                .position(|l| matches!(l, IndexLabel::Utf8(t) if t == want))
                .map(|i| s.column().values()[i].clone())
        };

        // The three that INCLUDE the object column.
        let sum = df.sum().unwrap();
        assert_eq!(
            cell(&sum, "label"),
            Some(Scalar::Utf8("azm".to_owned())),
            "sum CONCATENATES an object column in row order"
        );
        assert!(
            matches!(cell(&sum, "a"), Some(Scalar::Int64(_))),
            "under the default the int column stays int64 — the float64 the old \
             fixtures pinned is specifically the numeric_only=true path"
        );
        assert_eq!(
            cell(&df.min_agg().unwrap(), "label"),
            Some(Scalar::Utf8("a".to_owned())),
            "min compares an object column lexicographically"
        );
        assert_eq!(
            cell(&df.max_agg().unwrap(), "label"),
            Some(Scalar::Utf8("z".to_owned()))
        );

        // The eight that RAISE. These are the negative control: a wrong default
        // on sum/min/max still yields a plausible number, but here it yields an
        // exception, so they cannot pass by accident.
        for (op, result) in [
            ("mean", df.mean().unwrap_err()),
            ("prod", df.prod_agg().unwrap_err()),
            ("median", df.median_agg().unwrap_err()),
            ("std", df.std_agg().unwrap_err()),
            ("var", df.var_agg().unwrap_err()),
            ("sem", df.sem_agg().unwrap_err()),
            ("skew", df.skew_agg().unwrap_err()),
            ("kurtosis", df.kurtosis_agg().unwrap_err()),
        ] {
            let message = result.to_string();
            assert!(
                message.contains("label"),
                "df.{op}() must refuse the object column and name it; got {message}"
            );
        }
    }

    /// `pd.DataFrame(scalar, index=..., columns=...)` broadcasts. Measured on
    /// pandas 2.2.3 — the dtype follows the scalar, and an empty index keeps the
    /// columns (br-frankenpandas-oxodo).
    #[test]
    fn dataframe_from_scalar_broadcasts_like_pandas() {
        let columns = vec!["a".to_owned(), "b".to_owned()];
        let df = DataFrame::from_scalar(
            &Scalar::Int64(5),
            vec![0_i64.into(), 1_i64.into()],
            Some(&columns),
        )
        .expect("scalar broadcast");
        assert_eq!(df.column_names(), vec!["a", "b"]);
        assert_eq!(df.index().len(), 2);
        assert_eq!(
            df.columns["a"].values(),
            &[Scalar::Int64(5), Scalar::Int64(5)]
        );
        assert_eq!(
            df.columns["b"].values(),
            &[Scalar::Int64(5), Scalar::Int64(5)]
        );

        // Utf8 broadcasts as object, matching pandas' dtype=object.
        let one = vec!["a".to_owned()];
        let text = DataFrame::from_scalar(
            &Scalar::Utf8("x".into()),
            vec![0_i64.into(), 1_i64.into()],
            Some(&one),
        )
        .expect("utf8 broadcast");
        assert_eq!(
            text.columns["a"].values(),
            &[Scalar::Utf8("x".into()), Scalar::Utf8("x".into())]
        );

        // An empty index keeps the columns: pandas gives shape (0, 1).
        let empty = DataFrame::from_scalar(&Scalar::Int64(5), Vec::new(), Some(&one))
            .expect("empty index keeps columns");
        assert_eq!(empty.index().len(), 0);
        assert_eq!(empty.column_names(), vec!["a"]);
        assert!(empty.columns["a"].values().is_empty());
    }

    /// The distinction a bare slice cannot express, and the reason `columns` is
    /// an Option. Measured on pandas 2.2.3:
    ///   `pd.DataFrame(5, index=[1,2], columns=[])` -> shape (2, 0), LEGAL
    ///   `pd.DataFrame(5, index=[1,2])`             -> ValueError:
    ///        DataFrame constructor not properly called!
    /// Conflating them makes one of the two unreachable — which is exactly what
    /// an earlier draft of this constructor did, turning the green fixture
    /// fp_p2d_020_dataframe_constructor_scalar_empty_columns_strict red.
    #[test]
    fn dataframe_from_scalar_empty_columns_is_legal_but_omitted_is_not() {
        let explicit_empty = DataFrame::from_scalar(
            &Scalar::Int64(9),
            vec![0_i64.into(), 1_i64.into()],
            Some(&[]),
        )
        .expect("columns=[] is legal and gives shape (2, 0)");
        assert_eq!(explicit_empty.index().len(), 2);
        assert!(explicit_empty.column_names().is_empty());

        DataFrame::from_scalar(&Scalar::Int64(5), vec![0_i64.into(), 1_i64.into()], None)
            .expect_err("OMITTING columns is pandas' ValueError");
    }

    /// pandas lets the index win when there are NO rows. Measured on 2.2.3:
    ///   `pd.DataFrame([], index=[0])`            -> shape (1, 0), index [0]
    ///   `pd.DataFrame([], index=[0, 1])`         -> shape (2, 0), index [0, 1]
    ///   `pd.DataFrame([], index=[0], columns=['a'])` -> shape (1, 1), [[nan]]
    /// FrankenPandas rejected all three with "index length 1 does not match row
    /// count 0" (br-frankenpandas-fp-stricter-than-pandas-rejections-gtkz1).
    #[test]
    fn dataframe_from_records_empty_rows_lets_index_win_like_pandas() {
        let df = DataFrame::from_records(vec![], None, Some(vec![0_i64.into()]))
            .expect("pandas accepts empty rows with a non-empty index");
        assert_eq!(df.index().len(), 1);
        assert!(df.column_names().is_empty());

        let df2 = DataFrame::from_records(vec![], None, Some(vec![0_i64.into(), 1_i64.into()]))
            .expect("two index labels, still no columns");
        assert_eq!(df2.index().len(), 2);
        assert!(df2.column_names().is_empty());

        // With explicit columns the frame is null-filled to the index length
        // rather than being built to the (zero) row count.
        let columns = vec!["a".to_owned()];
        let df3 = DataFrame::from_records(vec![], Some(&columns), Some(vec![0_i64.into()]))
            .expect("empty rows + explicit columns null-fills");
        assert_eq!(df3.index().len(), 1);
        assert_eq!(df3.column_names(), vec!["a"]);
        assert_eq!(df3.columns["a"].values(), &[Scalar::Null(NullKind::Null)]);
    }

    /// The negative control: a NON-empty row set that disagrees with the index
    /// is still an error, exactly as pandas raises "Length of values (2) does
    /// not match length of index (1)". Without this the fix above would read as
    /// "drop the length check", which is not what pandas does.
    #[test]
    fn dataframe_from_records_nonempty_rows_still_check_index_length() {
        let err = DataFrame::from_records(
            vec![vec![Scalar::Int64(1)], vec![Scalar::Int64(2)]],
            None,
            Some(vec![0_i64.into()]),
        )
        .expect_err("2 rows against a 1-label index must still be rejected");

        assert_eq!(
            err.to_string(),
            "compatibility gate rejected operation: dataframe_from_records index length 1 does not match row count 2"
        );
    }

    #[test]
    fn dataframe_list_like_broadcasts_one_row_to_a_longer_index_ic87j() {
        let index = vec![10_i64.into(), 20_i64.into(), 30_i64.into()];
        let frame =
            DataFrame::from_list_like(vec![vec![Scalar::Int64(7)]], None, Some(index.clone()))
                .expect("pandas repeats one list-like row for a longer index");

        assert_eq!(frame.index().labels(), index.as_slice());
        assert_eq!(frame.column_names(), vec!["0"]);
        assert_eq!(
            frame.column("0").expect("broadcast column").values(),
            &[Scalar::Int64(7), Scalar::Int64(7), Scalar::Int64(7)]
        );

        let short_index =
            DataFrame::from_list_like(vec![vec![Scalar::Int64(7)]], None, Some(Vec::new()))
                .expect_err("a shorter explicit index does not truncate the row");
        assert_eq!(
            short_index.to_string(),
            "compatibility gate rejected operation: dataframe_constructor_list_like index length 0 does not match row count 1"
        );

        let multiple_rows = DataFrame::from_list_like(
            vec![vec![Scalar::Int64(7)], vec![Scalar::Int64(8)]],
            None,
            Some(vec![10_i64.into()]),
        )
        .expect_err("only one row broadcasts");
        assert_eq!(
            multiple_rows.to_string(),
            "compatibility gate rejected operation: dataframe_constructor_list_like index length 1 does not match row count 2"
        );
    }

