    #[test]
    fn concat_dataframes_axis1_aligns_and_fills_nulls() {
        let left = DataFrame::from_dict_with_index(
            vec![("a", vec![Scalar::Int64(1), Scalar::Int64(2)])],
            vec![0_i64.into(), 1_i64.into()],
        )
        .unwrap();
        let right = DataFrame::from_dict_with_index(
            vec![("b", vec![Scalar::Int64(10), Scalar::Int64(20)])],
            vec![1_i64.into(), 2_i64.into()],
        )
        .unwrap();

        let out = concat_dataframes_with_axis(&[&left, &right], 1).unwrap();
        assert_eq!(
            out.index().labels(),
            &[0_i64.into(), 1_i64.into(), 2_i64.into()]
        );
        // Both columns gain a row the ALIGNMENT invents, so both widen to
        // float64 with NaN gaps. Measured on pandas 2.2.3 with these exact
        // inputs — pd.concat([DataFrame({'a':[1,2]}, index=[0,1]),
        //                     DataFrame({'b':[10,20]}, index=[1,2])], axis=1):
        //        a     b          dtypes: a float64, b float64
        //   0  1.0   NaN
        //   1  2.0  10.0
        //   2  NaN  20.0
        // This test previously pinned Int64 + Null(Null), which is what
        // FrankenPandas used to produce (br-frankenpandas-nywa8).
        assert_eq!(
            out.column("a").unwrap().values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN)
            ]
        );
        assert_eq!(
            out.column("b").unwrap().values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0)
            ]
        );
    }

