    #[test]
    fn null_nan_metamorphic_series_reindex_dropna_identity_tn6qb6() -> Result<(), FrameError> {
        let original = Series::from_values(
            "v",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(-0.0),
            ],
        )?;

        let expanded = original.reindex(vec![
            "ghost".into(),
            "a".into(),
            "ghost".into(),
            "b".into(),
            "c".into(),
        ])?;
        let compacted = expanded.dropna()?;
        let baseline = original.dropna()?;

        assert_eq!(compacted.index().labels(), baseline.index().labels());
        assert_eq!(compacted.column().values(), baseline.column().values());
        assert!(matches!(
            compacted.column().values()[1],
            Scalar::Float64(v) if v.to_bits() == (-0.0_f64).to_bits()
        ));

        Ok(())
    }

    #[test]
    fn null_nan_metamorphic_concat_axis1_matches_outer_alignment_tn6qb6() -> Result<(), FrameError>
    {
        let left = DataFrame::from_dict_with_index(
            vec![("left", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)])],
            vec![0_i64.into(), 1_i64.into()],
        )?;
        let right = DataFrame::from_dict_with_index(
            vec![(
                "right",
                vec![Scalar::Float64(10.0), Scalar::Null(NullKind::NaN)],
            )],
            vec![1_i64.into(), 2_i64.into()],
        )?;

        let concatenated = concat_dataframes_with_axis(&[&left, &right], 1)?;
        let (aligned_left, aligned_right) = left.align_on_index(&right, AlignMode::Outer)?;
        let concatenated_left = concatenated.column("left").ok_or_else(|| {
            FrameError::CompatibilityRejected("concat output missing 'left' column".to_owned())
        })?;
        let concatenated_right = concatenated.column("right").ok_or_else(|| {
            FrameError::CompatibilityRejected("concat output missing 'right' column".to_owned())
        })?;
        let aligned_left_col = aligned_left.column("left").ok_or_else(|| {
            FrameError::CompatibilityRejected(
                "aligned left output missing 'left' column".to_owned(),
            )
        })?;
        let aligned_right_col = aligned_right.column("right").ok_or_else(|| {
            FrameError::CompatibilityRejected(
                "aligned right output missing 'right' column".to_owned(),
            )
        })?;

        assert_eq!(concatenated.index().labels(), aligned_left.index().labels());
        assert_eq!(
            concatenated.index().labels(),
            aligned_right.index().labels()
        );
        assert_eq!(concatenated_left.values(), aligned_left_col.values());
        assert_eq!(concatenated_right.values(), aligned_right_col.values());
        assert!(concatenated_left.values()[2].is_missing());
        assert!(concatenated_right.values()[0].is_missing());
        assert!(concatenated_right.values()[2].is_missing());

        Ok(())
    }

    #[test]
    fn null_nan_metamorphic_series_groupby_missing_key_isolation_tn6qb6() -> Result<(), FrameError>
    {
        let base_values = Series::from_values(
            "v",
            (0_i64..3).map(Into::into).collect(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(10.0),
                Scalar::Float64(3.0),
            ],
        )?;
        let base_keys = Series::from_values(
            "key",
            (0_i64..3).map(Into::into).collect(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
            ],
        )?;
        let base_sum = base_values.groupby(&base_keys)?.sum()?;

        let mutated_values = Series::from_values(
            "v",
            (0_i64..5).map(Into::into).collect(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(1000.0),
                Scalar::Float64(10.0),
                Scalar::Float64(3.0),
                Scalar::Null(NullKind::NaN),
            ],
        )?;
        let mutated_keys = Series::from_values(
            "key",
            (0_i64..5).map(Into::into).collect(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Float64(f64::NAN),
            ],
        )?;
        let mutated_sum = mutated_values.groupby(&mutated_keys)?.sum()?;

        assert_eq!(
            base_sum.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("b".into())]
        );
        // SeriesGroupBy drops missing-key rows (pandas `dropna=True` default), so
        // inserting a Null-key row AND a NaN-float-key row leaves ONLY the present
        // keys a/b — no spurious "NaN" group (this previously kept one, diverging
        // from pandas). The metamorphic invariant is that the present groups are
        // isolated from the dropped missing-key rows: a and b are unchanged.
        assert_eq!(
            mutated_sum.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("b".into())]
        );
        assert_eq!(
            base_sum.column().values()[0],
            mutated_sum.column().values()[0]
        );
        assert_eq!(
            base_sum.column().values()[1],
            mutated_sum.column().values()[1]
        );

        Ok(())
    }

    #[test]
    fn reshape_null_nan_metamorphic_melt_auto_matches_explicit_tn6qb9() -> Result<(), FrameError> {
        let frame = DataFrame::from_series(vec![
            Series::from_values(
                "id",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Utf8("a".into()),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Null(NullKind::Null),
                ],
            )?,
            Series::from_values(
                "x",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Int64(1),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(-0.0),
                ],
            )?,
            Series::from_values(
                "y",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Float64(10.5),
                    Scalar::Float64(20.5),
                    Scalar::Float64(30.5),
                ],
            )?,
        ])?;

        let explicit = frame.melt(&["id"], &["x", "y"], None, None)?;
        let automatic = frame.melt(&["id"], &[], None, None)?;

        assert_eq!(automatic.column_order, explicit.column_order);
        assert_eq!(
            automatic.column("id").ok_or_else(|| {
                FrameError::CompatibilityRejected("melt output missing 'id'".to_owned())
            })?,
            explicit.column("id").ok_or_else(|| {
                FrameError::CompatibilityRejected("melt output missing explicit 'id'".to_owned())
            })?
        );
        assert_eq!(
            automatic.column("variable").ok_or_else(|| {
                FrameError::CompatibilityRejected("melt output missing 'variable'".to_owned())
            })?,
            explicit.column("variable").ok_or_else(|| {
                FrameError::CompatibilityRejected(
                    "melt output missing explicit 'variable'".to_owned(),
                )
            })?
        );
        assert_eq!(
            automatic.column("value").ok_or_else(|| {
                FrameError::CompatibilityRejected("melt output missing 'value'".to_owned())
            })?,
            explicit.column("value").ok_or_else(|| {
                FrameError::CompatibilityRejected("melt output missing explicit 'value'".to_owned())
            })?
        );
        let value_column = automatic.column("value").ok_or_else(|| {
            FrameError::CompatibilityRejected("melt output missing 'value'".to_owned())
        })?;
        assert!(matches!(
            value_column.values()[2],
            Scalar::Float64(v) if v.to_bits() == (-0.0_f64).to_bits()
        ));

        Ok(())
    }

    #[test]
    fn reshape_null_nan_metamorphic_pivot_table_missing_keys_do_not_disturb_default_tn6qb9()
    -> Result<(), FrameError> {
        let baseline = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                ],
            )?,
            Series::from_values(
                "col",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Utf8("c1".into()),
                ],
            )?,
            Series::from_values(
                "val",
                (0_i64..3).map(Into::into).collect(),
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                ],
            )?,
        ])?;
        let with_missing_keys = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                (0_i64..7).map(Into::into).collect(),
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Null(NullKind::Null),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                ],
            )?,
            Series::from_values(
                "col",
                (0_i64..7).map(Into::into).collect(),
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Null(NullKind::Null),
                ],
            )?,
            Series::from_values(
                "val",
                (0_i64..7).map(Into::into).collect(),
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(100.0),
                    Scalar::Float64(200.0),
                    Scalar::Float64(400.0),
                    Scalar::Float64(500.0),
                ],
            )?,
        ])?;

        let baseline_pivot = baseline.pivot_table("val", "row", "col", "sum")?;
        let missing_key_pivot = with_missing_keys.pivot_table("val", "row", "col", "sum")?;

        assert_eq!(missing_key_pivot.index(), baseline_pivot.index());
        assert_eq!(missing_key_pivot.column_order, baseline_pivot.column_order);
        assert_eq!(
            missing_key_pivot.column("c1").ok_or_else(|| {
                FrameError::CompatibilityRejected("pivot output missing 'c1'".to_owned())
            })?,
            baseline_pivot.column("c1").ok_or_else(|| {
                FrameError::CompatibilityRejected("baseline pivot output missing 'c1'".to_owned())
            })?
        );
        assert_eq!(
            missing_key_pivot.column("c2").ok_or_else(|| {
                FrameError::CompatibilityRejected("pivot output missing 'c2'".to_owned())
            })?,
            baseline_pivot.column("c2").ok_or_else(|| {
                FrameError::CompatibilityRejected("baseline pivot output missing 'c2'".to_owned())
            })?
        );

        Ok(())
    }

    #[test]
    fn reshape_null_nan_metamorphic_concat_keys_preserve_value_projection_tn6qb9()
    -> Result<(), FrameError> {
        let left = DataFrame::from_dict_with_index(
            vec![("v", vec![Scalar::Float64(1.0), Scalar::Null(NullKind::NaN)])],
            vec!["dup".into(), "dup".into()],
        )?;
        let right = DataFrame::from_dict_with_index(
            vec![(
                "v",
                vec![Scalar::Float64(3.0), Scalar::Null(NullKind::Null)],
            )],
            vec!["tail".into(), "tail".into()],
        )?;

        let plain = concat_dataframes(&[&left, &right])?;
        let keyed = concat_dataframes_with_keys(&[&left, &right], &["L", "R"])?;

        assert_eq!(plain.column_order, keyed.column_order);
        assert_eq!(
            keyed.column("v").ok_or_else(|| {
                FrameError::CompatibilityRejected("keyed concat output missing 'v'".to_owned())
            })?,
            plain.column("v").ok_or_else(|| {
                FrameError::CompatibilityRejected("plain concat output missing 'v'".to_owned())
            })?
        );
        assert_eq!(
            keyed.index().labels(),
            &[
                IndexLabel::Utf8("L|dup".to_owned()),
                IndexLabel::Utf8("L|dup".to_owned()),
                IndexLabel::Utf8("R|tail".to_owned()),
                IndexLabel::Utf8("R|tail".to_owned()),
            ]
        );
        assert_eq!(
            plain.index().labels(),
            &[
                IndexLabel::Utf8("dup".to_owned()),
                IndexLabel::Utf8("dup".to_owned()),
                IndexLabel::Utf8("tail".to_owned()),
                IndexLabel::Utf8("tail".to_owned()),
            ]
        );

        Ok(())
    }

    #[test]
    fn concat_dataframes_axis0_inner_uses_column_intersection() {
        let left = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("b", vec![Scalar::Int64(10), Scalar::Int64(20)]),
            ],
        )
        .unwrap();
        let right = DataFrame::from_dict(
            &["b", "c"],
            vec![
                ("b", vec![Scalar::Int64(100), Scalar::Int64(200)]),
                ("c", vec![Scalar::Int64(7), Scalar::Int64(8)]),
            ],
        )
        .unwrap();

        let out = concat_dataframes_with_axis_join(&[&left, &right], 0, ConcatJoin::Inner).unwrap();
        let column_names = out.column_names();
        assert_eq!(column_names.len(), 1);
        assert_eq!(column_names[0], "b");
        assert_eq!(
            out.column("b").unwrap().values(),
            &[
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(100),
                Scalar::Int64(200)
            ]
        );
        assert_eq!(out.index().labels().len(), 4);
    }

