    #[test]
    fn series_reindex_with_method_ffill() {
        let s = Series::from_values(
            "x",
            vec![1_i64.into(), 3_i64.into(), 5_i64.into()],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(30.0),
                Scalar::Float64(50.0),
            ],
        )
        .unwrap();

        let result = s
            .reindex_with_method(
                vec![
                    1_i64.into(),
                    2_i64.into(),
                    3_i64.into(),
                    4_i64.into(),
                    5_i64.into(),
                ],
                "ffill",
            )
            .unwrap();
        assert_eq!(result.len(), 5);
        assert_eq!(result.values()[0], Scalar::Float64(10.0)); // exact match
        assert_eq!(result.values()[1], Scalar::Float64(10.0)); // ffill from 1
        assert_eq!(result.values()[2], Scalar::Float64(30.0)); // exact match
        assert_eq!(result.values()[3], Scalar::Float64(30.0)); // ffill from 3
        assert_eq!(result.values()[4], Scalar::Float64(50.0)); // exact match
    }

    #[test]
    fn series_reindex_with_method_bfill() {
        let s = Series::from_values(
            "x",
            vec![1_i64.into(), 3_i64.into()],
            vec![Scalar::Float64(10.0), Scalar::Float64(30.0)],
        )
        .unwrap();

        let result = s
            .reindex_with_method(
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                "bfill",
            )
            .unwrap();
        assert_eq!(result.len(), 4);
        assert_eq!(result.values()[0], Scalar::Float64(10.0)); // bfill from 1
        assert_eq!(result.values()[1], Scalar::Float64(10.0)); // exact match
        assert_eq!(result.values()[2], Scalar::Float64(30.0)); // bfill from 3
        assert_eq!(result.values()[3], Scalar::Float64(30.0)); // exact match
    }

    #[test]
    fn series_reindex_with_method_invalid_rejected() {
        let s = Series::from_values("x", vec![1_i64.into()], vec![Scalar::Float64(1.0)]).unwrap();

        // ⚠️ "nearest" USED TO BE THE INVALID CASE HERE, and it is not one:
        // pandas accepts it, and FrankenPandas implements it now. MEASURED, live
        // pandas 2.2.3, on Series([1.0, 2.0], index=[0, 2]):
        //     reindex([1], method='nearest')  -> [2.0]   (ties go to the HIGHER label)
        //     reindex([1], method='pad')      -> [1.0]
        //     reindex([1], method='backfill') -> [2.0]
        //     reindex([1], method='bogus')    -> ValueError
        // So the refusal this test is for needs a method pandas ALSO refuses.
        assert!(
            s.reindex_with_method(vec![1_i64.into()], "nearest").is_ok(),
            "nearest is a supported method"
        );
        assert!(
            s.reindex_with_method(vec![1_i64.into()], "bogus").is_err(),
            "an unknown method is still refused"
        );
    }

