    #[test]
    fn dataframe_reindex_with_method_absent_uses_column_dtype_missing_sentinel() {
        // A genuinely-absent label (a leading gap under ffill) must be filled
        // with the column's dtype-appropriate missing sentinel, matching plain
        // `reindex` and the Series variant — NOT a hardcoded Float64 NaN. For an
        // Int64 column `missing_for_dtype` is `Null(NullKind::Null)`. The old
        // DataFrame path hardcoded `Null(NullKind::NaN)`, diverging on non-float
        // columns.
        let df = DataFrame::from_dict_with_index(
            vec![("n", vec![Scalar::Int64(10), Scalar::Int64(20)])],
            vec![18_i64.into(), 19_i64.into()],
        )
        .unwrap();

        // New label 17 is below the source min: a leading gap with no prior
        // source label, so it stays absent under ffill.
        let result = df
            .reindex_with_method(vec![17_i64.into(), 18_i64.into(), 19_i64.into()], "ffill")
            .unwrap();
        let v = result.column("n").unwrap().values();
        assert_eq!(v.len(), 3);
        // Dtype-appropriate missing sentinel for the absent slot, not NaN.
        assert_eq!(v[0], Scalar::Null(NullKind::Null));
        assert_ne!(v[0], Scalar::Null(NullKind::NaN));
        assert_eq!(v[1], Scalar::Int64(10));
        assert_eq!(v[2], Scalar::Int64(20));
    }

    // ---- Series comparison operator tests ----

    #[test]
    fn series_gt_basic() {
        let left = Series::from_values(
            "a",
            vec![1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(5), Scalar::Int64(3)],
        )
        .unwrap();
        let right = Series::from_values(
            "b",
            vec![1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(3), Scalar::Int64(3), Scalar::Int64(3)],
        )
        .unwrap();

        let result = left.gt(&right).unwrap();
        assert_eq!(result.values()[0], Scalar::Bool(false));
        assert_eq!(result.values()[1], Scalar::Bool(true));
        assert_eq!(result.values()[2], Scalar::Bool(false));
    }

    #[test]
    fn series_datetime_timedelta_col_vs_col_comparison_exact_and_masks_nat() {
        // Regression (fp-columnar temporal binary_comparison arm): element-wise
        // comparison between two Datetime64 (or Timedelta64) Series previously
        // ERRORED — the generic column path routed a present temporal pair through
        // scalar_compare -> to_f64, which rejects a temporal scalar. It must now
        // return exact i64-ns Bool results, with any NaT operand masked to Null.
        // Values near 1.6e18 >> 2^53 prove exactness: an f64 promotion would round
        // base and base+1 together, but they must compare distinctly.
        let base = 1_600_000_000_000_000_000_i64;
        let nat = fp_types::Timestamp::NAT;
        let idx = vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()];
        let left = Series::from_values(
            "l",
            idx.clone(),
            vec![
                Scalar::Datetime64(base),
                Scalar::Datetime64(base + 1),
                Scalar::Datetime64(base + 2),
                Scalar::Datetime64(nat),
            ],
        )
        .unwrap();
        let right = Series::from_values(
            "r",
            idx,
            vec![
                Scalar::Datetime64(base + 1),
                Scalar::Datetime64(base + 1),
                Scalar::Datetime64(base + 1),
                Scalar::Datetime64(base),
            ],
        )
        .unwrap();
        assert_eq!(
            left.lt(&right).unwrap().values(),
            &[
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(false),
                Scalar::Null(NullKind::Null),
            ]
        );
        assert_eq!(
            left.eq(&right).unwrap().values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Null(NullKind::Null),
            ]
        );

        // Timedelta64 sibling: 5ns < 10ns, 10ns == 10ns.
        let lt = Series::from_values(
            "l",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Timedelta64(5), Scalar::Timedelta64(10)],
        )
        .unwrap();
        let rt = Series::from_values(
            "r",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Timedelta64(10), Scalar::Timedelta64(10)],
        )
        .unwrap();
        assert_eq!(
            lt.lt(&rt).unwrap().values(),
            &[Scalar::Bool(true), Scalar::Bool(false)]
        );
    }

    #[test]
    fn series_compare_scalar_gt() {
        let s = Series::from_values(
            "vals",
            vec![1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(5), Scalar::Int64(3)],
        )
        .unwrap();

        let result = s
            .compare_scalar(&Scalar::Int64(3), fp_columnar::ComparisonOp::Gt)
            .unwrap();
        assert_eq!(result.values()[0], Scalar::Bool(false));
        assert_eq!(result.values()[1], Scalar::Bool(true));
        assert_eq!(result.values()[2], Scalar::Bool(false));
    }

    #[test]
    fn series_compare_scalar_datetime_timedelta_exact_and_masks_nat() {
        // Regression (fp-columnar compare_scalar temporal arm): `df["date"] > threshold`
        // — the canonical time-series filter — previously ERRORED (Column::compare_scalar
        // -> scalar_compare -> to_f64 rejects a temporal scalar). It must now return exact
        // i64-ns Bool results, with a NaT column row masked to Null. Values near 1.6e18 >>
        // 2^53 prove exactness: base and base+1 must compare distinctly, not round together.
        let base = 1_600_000_000_000_000_000_i64;
        let nat = fp_types::Timestamp::NAT;
        let s = Series::from_values(
            "date",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Datetime64(base),
                Scalar::Datetime64(base + 1),
                Scalar::Datetime64(base + 2),
                Scalar::Datetime64(nat),
            ],
        )
        .unwrap();
        assert_eq!(
            s.compare_scalar(&Scalar::Datetime64(base + 1), fp_columnar::ComparisonOp::Gt)
                .unwrap()
                .values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null),
            ]
        );
        assert_eq!(
            s.compare_scalar(&Scalar::Datetime64(base + 1), fp_columnar::ComparisonOp::Le)
                .unwrap()
                .values(),
            &[
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Null(NullKind::Null),
            ]
        );

        // Timedelta64 sibling: > 7ns.
        let td = Series::from_values(
            "dur",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Timedelta64(5),
                Scalar::Timedelta64(10),
                Scalar::Timedelta64(7),
            ],
        )
        .unwrap();
        assert_eq!(
            td.compare_scalar(&Scalar::Timedelta64(7), fp_columnar::ComparisonOp::Gt)
                .unwrap()
                .values(),
            &[Scalar::Bool(false), Scalar::Bool(true), Scalar::Bool(false)]
        );
    }

    #[test]
    fn series_comparison_with_alignment() {
        let left = Series::from_values(
            "a",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(10), Scalar::Int64(20)],
        )
        .unwrap();
        let right = Series::from_values(
            "b",
            vec![2_i64.into(), 3_i64.into()],
            vec![Scalar::Int64(15), Scalar::Int64(25)],
        )
        .unwrap();

        let result = left.gt(&right).unwrap();
        // Union index: [1, 2, 3]
        // Position 0 (label 1): left=10, right=null -> null
        // Position 1 (label 2): left=20, right=15 -> true
        // Position 2 (label 3): left=null, right=25 -> null
        assert!(result.values()[0].is_missing());
        assert_eq!(result.values()[1], Scalar::Bool(true));
        assert!(result.values()[2].is_missing());
    }

    #[test]
    fn series_eq_ne_basic() {
        let s1 = Series::from_values(
            "a",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(5), Scalar::Int64(10)],
        )
        .unwrap();
        let s2 = Series::from_values(
            "b",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(5), Scalar::Int64(20)],
        )
        .unwrap();

        let eq = s1.eq_series(&s2).unwrap();
        assert_eq!(eq.values()[0], Scalar::Bool(true));
        assert_eq!(eq.values()[1], Scalar::Bool(false));

        let ne = s1.ne_series(&s2).unwrap();
        assert_eq!(ne.values()[0], Scalar::Bool(false));
        assert_eq!(ne.values()[1], Scalar::Bool(true));
    }

    #[test]
    fn series_logical_ops_with_alignment_and_nulls() {
        let left = Series::from_values(
            "m1",
            vec![1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Null(NullKind::Null),
            ],
        )
        .unwrap();
        let right = Series::from_values(
            "m2",
            vec![2_i64.into(), 3_i64.into(), 4_i64.into()],
            vec![
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null),
                Scalar::Bool(false),
            ],
        )
        .unwrap();

        let and = left.and(&right).unwrap();
        assert_eq!(
            and.values(),
            &[
                Scalar::Null(NullKind::Null),
                Scalar::Bool(false),
                Scalar::Null(NullKind::Null),
                Scalar::Bool(false)
            ]
        );

        let or = left.or(&right).unwrap();
        assert_eq!(
            or.values(),
            &[
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null),
                Scalar::Null(NullKind::Null)
            ]
        );

        let not_left = left.not().unwrap();
        assert_eq!(
            not_left.values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null)
            ]
        );
    }

    #[test]
    fn series_and_or_sort_differing_union_index() {
        // pandas &/| return the SORTED union index when the indexes differ
        // (Index.union sorts), like arithmetic. Verified vs live pandas 2.2.3:
        // index [2,1] op [2,1,0] -> [0,1,2]. (Three-valued null handling for the
        // alignment-introduced gaps is FP's existing semantics, tested above;
        // here we lock the index ORDER only.)
        let left = Series::from_values(
            "m1",
            vec![2_i64.into(), 1_i64.into()],
            vec![Scalar::Bool(true), Scalar::Bool(false)],
        )
        .unwrap();
        let right = Series::from_values(
            "m2",
            vec![2_i64.into(), 1_i64.into(), 0_i64.into()],
            vec![Scalar::Bool(true), Scalar::Bool(true), Scalar::Bool(true)],
        )
        .unwrap();
        let sorted = vec![0_i64.into(), 1_i64.into(), 2_i64.into()];
        assert_eq!(left.and(&right).unwrap().index().labels(), &sorted);
        assert_eq!(left.or(&right).unwrap().index().labels(), &sorted);
    }

    #[test]
    fn series_logical_ops_reject_non_boolean_input() {
        let left = Series::from_values(
            "left",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(0)],
        )
        .unwrap();
        let right = Series::from_values(
            "right",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Bool(true), Scalar::Bool(false)],
        )
        .unwrap();

        let and_err = left.and(&right).unwrap_err();
        assert!(
            matches!(and_err, FrameError::CompatibilityRejected(msg) if msg.contains("boolean series required for and"))
        );

        let not_err = left.not().unwrap_err();
        assert!(
            matches!(not_err, FrameError::CompatibilityRejected(msg) if msg.contains("boolean series required for not"))
        );
    }

