    #[test]
    fn series_value_counts_nullable_float_unique_fast_path_matches_generic_s2i37_1() {
        let n = 512usize;
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let values: Vec<f64> = (0..n)
            .map(|row| {
                if row % 2 == 0 {
                    f64::NAN
                } else {
                    row as f64 + (row % 7) as f64 * 0.125
                }
            })
            .collect();
        let series = Series::new("v", Index::new(labels), Column::from_f64_values(values)).unwrap();

        let optimized = series.value_counts().unwrap();
        let generic = series
            .value_counts_with_options(false, true, false, true)
            .unwrap();

        assert_eq!(optimized.index().labels(), generic.index().labels());
        assert_eq!(optimized.values(), generic.values());
        assert_eq!(optimized.len(), n / 2);
        assert!(
            optimized
                .values()
                .iter()
                .all(|value| *value == Scalar::Int64(1))
        );
    }

    #[test]
    fn series_value_counts_null_bucket_at_first_seen_position_joeff() {
        // Per br-frankenpandas-joeff: the (collapsed) null bucket must sit at its
        // first-seen position, not pinned to the end. Verified vs live pandas
        // 2.2.3: pd.Series([1, nan, 2]).value_counts(sort=False, dropna=False)
        // -> [(1.0, 1), (nan, 1), (2.0, 1)] (null in the MIDDLE).
        let s = Series::from_values(
            "v",
            vec![
                IndexLabel::from("r1"),
                IndexLabel::from("r2"),
                IndexLabel::from("r3"),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();
        let unsorted = s
            .value_counts_with_options(false, false, false, false)
            .unwrap();
        assert_eq!(
            unsorted.index().labels(),
            &[
                // br-frankenpandas-8sxez: float Series value_counts_with_options
                // now returns a numeric Float64 index (pandas Float64Index), not
                // the FP-invented stringified "1.0"/"2.0".
                IndexLabel::Float64(fp_index::OrderedF64(1.0)),
                IndexLabel::Null(NullKind::NaN),
                IndexLabel::Float64(fp_index::OrderedF64(2.0)),
            ]
        );

        // sort=True breaks count ties by first-seen, so the null group (seen
        // first) sorts before a later, equally-counted value. pandas 2.2.3:
        // pd.Series([nan, 5, 5, 3]).value_counts(dropna=False)
        // -> [(5.0, 2), (nan, 1), (3.0, 1)].
        let s2 = Series::from_values(
            "v",
            vec![
                IndexLabel::from("a"),
                IndexLabel::from("b"),
                IndexLabel::from("c"),
                IndexLabel::from("d"),
            ],
            vec![
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(5.0),
                Scalar::Float64(5.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let sorted = s2
            .value_counts_with_options(false, true, false, false)
            .unwrap();
        assert_eq!(
            sorted.index().labels(),
            &[
                IndexLabel::Float64(fp_index::OrderedF64(5.0)),
                IndexLabel::Null(NullKind::NaN),
                IndexLabel::Float64(fp_index::OrderedF64(3.0)),
            ]
        );
        assert_eq!(
            sorted.values(),
            &[Scalar::Int64(2), Scalar::Int64(1), Scalar::Int64(1)]
        );
    }

    #[test]
    fn series_value_counts_keeps_distinct_null_kinds_joeff_phase2() {
        // Per br-frankenpandas-joeff phase 2 — differential vs live pandas
        // 2.2.3 (2026-06-07):
        //   pd.Series([None, nan, None, 1], dtype=object)
        //     .value_counts(dropna=False) -> {None: 2, nan: 1, 1: 1}
        // None and nan stay DISTINCT buckets; desc count order with
        // first-seen tiebreak (nan seen before 1).
        let s = Series::from_values(
            "v",
            vec![
                IndexLabel::from("r1"),
                IndexLabel::from("r2"),
                IndexLabel::from("r3"),
                IndexLabel::from("r4"),
            ],
            vec![
                Scalar::Null(NullKind::Null),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::Null),
                Scalar::Int64(1),
            ],
        )
        .unwrap();
        let out = s
            .value_counts_with_options(false, true, false, false)
            .unwrap();
        assert_eq!(
            out.index().labels(),
            &[
                IndexLabel::Null(NullKind::Null),
                IndexLabel::Null(NullKind::NaN),
                IndexLabel::Int64(1),
            ]
        );
        assert_eq!(
            out.values(),
            &[Scalar::Int64(2), Scalar::Int64(1), Scalar::Int64(1)]
        );

        //   pd.Series([nan, 1, nan, None], dtype=object)
        //     .value_counts(dropna=False) -> {nan: 2, 1: 1, None: 1}
        // (1 seen before None among the count-1 ties.)
        let s2 = Series::from_values(
            "v",
            vec![
                IndexLabel::from("r1"),
                IndexLabel::from("r2"),
                IndexLabel::from("r3"),
                IndexLabel::from("r4"),
            ],
            vec![
                Scalar::Null(NullKind::NaN),
                Scalar::Int64(1),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::Null),
            ],
        )
        .unwrap();
        let out2 = s2
            .value_counts_with_options(false, true, false, false)
            .unwrap();
        assert_eq!(
            out2.index().labels(),
            &[
                IndexLabel::Null(NullKind::NaN),
                IndexLabel::Int64(1),
                IndexLabel::Null(NullKind::Null),
            ]
        );
        assert_eq!(
            out2.values(),
            &[Scalar::Int64(2), Scalar::Int64(1), Scalar::Int64(1)]
        );

        // dropna=true (the default surface) still excludes every null kind.
        let dropped = s
            .value_counts_with_options(false, true, false, true)
            .unwrap();
        assert_eq!(dropped.index().labels(), &[IndexLabel::Int64(1)]);

        // The typed null labels render like pandas' repr (None / NaN).
        assert_eq!(IndexLabel::Null(NullKind::Null).to_string(), "None");
        assert_eq!(IndexLabel::Null(NullKind::NaN).to_string(), "NaN");
        assert_eq!(IndexLabel::Null(NullKind::NaT).to_string(), "NaT");
    }

    #[test]
    fn str_contains_whole_buffer_scan_boundary_shadow_2krr0() {
        // The whole-buffer SIMD scan's correctness crux: with rows
        // ["xa", "aa"] and needle "aa", the buffer is "xaaa" and a
        // non-overlapping left-to-right search finds the boundary-CROSSING
        // match at byte 1 first; naively skipping past it would shadow row
        // 2's genuine in-row hit at byte 2. The resume-at-start+1 rule must
        // recover it. Exercised through a chained op so the input is the
        // contiguous Utf8 representation (plain Scalar-backed input takes
        // the per-row path).
        let s = Series::from_values(
            "s",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Utf8("XA".into()),
                Scalar::Utf8("AA".into()),
                Scalar::Utf8("".into()),
                Scalar::Utf8("aAa".into()),
            ],
        )
        .unwrap();
        // lower() emits the contiguous representation: rows become
        // ["xa", "aa", "", "aaa"] over buffer "xaaaaaa".
        let lowered = s.str().lower().unwrap();
        assert!(
            lowered.column().as_utf8_contiguous().is_some(),
            "chained input must be contiguous for this test to bite"
        );
        let out = lowered.str().contains("aa").unwrap();
        assert_eq!(
            out.values(),
            &[
                Scalar::Bool(false), // "xa"
                Scalar::Bool(true),  // "aa" — the shadowable hit
                Scalar::Bool(false), // ""
                Scalar::Bool(true),  // "aaa"
            ]
        );
        // Cross-check against the per-row path on the eager input.
        let eager = s.str().lower().unwrap();
        let eager_vals: Vec<Scalar> = eager
            .column()
            .values()
            .iter()
            .map(|v| match v {
                Scalar::Utf8(st) => Scalar::Bool(st.contains("aa")),
                other => other.clone(),
            })
            .collect();
        assert_eq!(out.values(), eager_vals.as_slice());

        // Empty needle: true everywhere, including the empty row.
        let all = lowered.str().contains("").unwrap();
        assert!(all.values().iter().all(|v| *v == Scalar::Bool(true)));
    }

    #[test]
    fn str_parallel_kernels_preserve_order_and_values() {
        const ROWS: usize = 600_000;
        const WIDTH: usize = 16;
        let mut bytes = Vec::with_capacity(ROWS * WIDTH);
        let mut offsets = Vec::with_capacity(ROWS + 1);
        offsets.push(0);
        for row in 0..ROWS {
            if row % 3 == 0 {
                bytes.extend_from_slice(b"item_5xxxxxxxxxx");
            } else {
                bytes.extend_from_slice(b"item_xxxxxxxxxxx");
            }
            offsets.push(bytes.len());
        }
        let series = Series::new(
            "s",
            Index::new_known_unique_int64_unit_range(0, ROWS),
            Column::from_utf8_contiguous(bytes, offsets),
        )
        .unwrap();

        let contains = series.str().contains("5").unwrap();
        let contains_flags = contains
            .column()
            .as_bool_slice()
            .expect("literal contains must retain typed Bool output");
        let startswith = series.str().startswith("item_5").unwrap();
        let startswith_flags = startswith
            .column()
            .as_bool_slice()
            .expect("startswith must retain typed Bool output");
        let endswith = series.str().endswith("xxx").unwrap();
        let endswith_flags = endswith
            .column()
            .as_bool_slice()
            .expect("endswith must retain typed Bool output");
        let upper = series.str().upper().unwrap();
        let (upper_bytes, upper_offsets) = upper
            .column()
            .as_utf8_contiguous()
            .expect("upper must retain contiguous Utf8 output");
        let lengths = series.str().len().unwrap();
        let length_values = lengths
            .column()
            .as_i64_slice()
            .expect("len must retain typed Int64 output");
        assert_eq!(contains_flags.len(), ROWS);
        for row in 0..ROWS {
            assert_eq!(contains_flags[row], row % 3 == 0, "contains row {row}");
            assert_eq!(startswith_flags[row], row % 3 == 0, "startswith row {row}");
            assert!(endswith_flags[row], "endswith row {row}");
            let expected: &[u8] = if row % 3 == 0 {
                b"ITEM_5XXXXXXXXXX"
            } else {
                b"ITEM_XXXXXXXXXXX"
            };
            assert_eq!(
                &upper_bytes[upper_offsets[row]..upper_offsets[row + 1]],
                expected,
                "upper row {row}"
            );
            assert_eq!(length_values[row], WIDTH as i64, "len row {row}");
        }

        let unicode = Series::new(
            "u",
            Index::new_known_unique_int64_unit_range(0, 2),
            Column::from_utf8_contiguous("straßeΣ".as_bytes().to_vec(), vec![0, 7, 9]),
        )
        .unwrap();
        let unicode_upper = unicode.str().upper().unwrap();
        assert_eq!(
            unicode_upper.values(),
            &[Scalar::Utf8("STRASSE".into()), Scalar::Utf8("Σ".into()),]
        );
        assert_eq!(
            unicode.str().len().unwrap().values(),
            &[Scalar::Int64(6), Scalar::Int64(1)]
        );
    }

    #[test]
    fn series_value_counts_bool_labels_are_boolean_not_strings_6bqfr() {
        // CORRECTED br-frankenpandas-oracle-bool-label-stale-6bqfr. This test
        // was `..._use_python_style_strings` and asserted
        // `[IndexLabel::from("True"), IndexLabel::from("False")]`, i.e. Utf8.
        // It pinned a divergence rather than parity. Measured on the installed
        // oracle, pandas 2.2.3, using this test's exact input:
        //   s = pd.Series([True, False, True, True, None, False],
        //                 index=[f"r{i}" for i in range(1, 7)], name="vals")
        //   vc = s.value_counts()
        //   list(vc.index)                 -> [True, False]
        //   [type(x).__name__ for x in vc.index] -> ['bool', 'bool']
        // and the same for a pure bool-dtype Series (index dtype `bool`).
        // pandas never renders these labels as the strings "True"/"False".
        //
        // The correction makes the assertion STRICTER: `IndexLabel::Bool(true)`
        // and `IndexLabel::Utf8("True")` are distinct labels that no longer
        // compare equal, so a regression to stringification now fails here.
        // Same shape as the Float64 sibling pinned by
        // `series_value_counts_float_labels_are_numeric_8sxez`.
        let s = Series::from_values(
            "vals",
            vec![
                IndexLabel::from("r1"),
                IndexLabel::from("r2"),
                IndexLabel::from("r3"),
                IndexLabel::from("r4"),
                IndexLabel::from("r5"),
                IndexLabel::from("r6"),
            ],
            vec![
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null),
                Scalar::Bool(false),
            ],
        )
        .unwrap();

        let out = s.value_counts().unwrap();
        assert_eq!(
            out.index().labels(),
            &[IndexLabel::Bool(true), IndexLabel::Bool(false)]
        );
        assert_eq!(out.values(), &[Scalar::Int64(3), Scalar::Int64(2)]);

        // The stringified labels must NOT be what comes back — asserted
        // explicitly, because `IndexLabel::from("True")` is exactly what the
        // superseded expectation used and is the regression to catch.
        assert_ne!(
            out.index().labels(),
            &[IndexLabel::from("True"), IndexLabel::from("False")]
        );

        // pandas keeps the source Series name as the index name and calls the
        // result "count" (br-frankenpandas-nvglo); unchanged by this fix.
        assert_eq!(out.name(), "count");
        assert_eq!(out.index().name(), Some("vals"));
    }

    #[test]
    fn series_value_counts_with_options_bool_labels_are_boolean_6bqfr() {
        // The `value_counts_with_options` path builds its labels from its OWN
        // inline match, not the shared mapper, so fixing one arm does not fix
        // the other. dropna=false additionally exercises the null bucket
        // alongside the bool labels, which is where a mis-typed label would
        // collide with a genuine "True" string.
        let s = Series::from_values(
            "flag",
            vec![
                IndexLabel::from("r1"),
                IndexLabel::from("r2"),
                IndexLabel::from("r3"),
                IndexLabel::from("r4"),
            ],
            vec![
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Null(NullKind::Null),
            ],
        )
        .unwrap();

        let kept = s
            .value_counts_with_options(false, true, false, false)
            .unwrap();
        assert_eq!(
            kept.index().labels(),
            &[
                IndexLabel::Bool(true),
                IndexLabel::Bool(false),
                IndexLabel::Null(NullKind::Null),
            ]
        );
        assert_eq!(
            kept.values(),
            &[Scalar::Int64(2), Scalar::Int64(1), Scalar::Int64(1)]
        );

        // Dropping nulls leaves the bool labels typed and untouched.
        let dropped = s
            .value_counts_with_options(false, true, false, true)
            .unwrap();
        assert_eq!(
            dropped.index().labels(),
            &[IndexLabel::Bool(true), IndexLabel::Bool(false)]
        );
    }

