    #[test]
    fn series_shift_fill_value_preserves_int_dtype() {
        // pd.Series.shift(periods, fill_value=...) fills vacated slots with
        // fill_value instead of NaN; an Int64 fill on an Int64 column keeps the
        // column Int64 (no widening to Float64). Verified vs pandas 2.2.3:
        // [1,2,3,4].shift(1, fill_value=0) -> [0,1,2,3].
        let s = Series::from_values(
            "v",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Int64(4),
            ],
        )
        .unwrap();

        let fwd = s.shift_with_fill_value(1, Scalar::Int64(0)).unwrap();
        assert_eq!(fwd.dtype(), DType::Int64, "int fill keeps Int64 dtype");
        assert_eq!(
            fwd.values(),
            &[
                Scalar::Int64(0),
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3)
            ]
        );

        let back = s.shift_with_fill_value(-2, Scalar::Int64(99)).unwrap();
        assert_eq!(
            back.values(),
            &[
                Scalar::Int64(3),
                Scalar::Int64(4),
                Scalar::Int64(99),
                Scalar::Int64(99)
            ]
        );

        // Bare shift still introduces NaN (unchanged).
        let nan_shift = s.shift(1).unwrap();
        assert!(nan_shift.values()[0].is_missing());
        assert_eq!(nan_shift.values()[1], Scalar::Int64(1));
    }

    #[test]
    fn series_shift_ffill_float64_rebuild_fast_paths_preserve_semantics() {
        let index = Index::new_known_unique_int64_unit_range(0, 4);
        let s = Series::new(
            "v",
            index.clone(),
            fp_columnar::Column::from_f64_values(vec![1.0, 2.0, 3.0, 4.0]),
        )
        .unwrap();

        let shifted = s.shift(1).unwrap();
        let (shift_data, shift_validity) = shifted
            .column()
            .as_f64_slice_with_validity()
            .expect("shift keeps directly-addressable Float64 storage");
        assert_eq!(shift_data[0].to_bits(), f64::NAN.to_bits());
        assert!(!shift_validity.get(0));
        assert_eq!(&shift_data[1..], &[1.0, 2.0, 3.0]);
        assert_eq!(shifted.index().labels(), index.labels());

        let gappy = Series::new(
            "v",
            index,
            fp_columnar::Column::from_f64_values(vec![1.0, f64::NAN, 3.0, f64::NAN]),
        )
        .unwrap();
        let filled = gappy.ffill(None).unwrap();
        assert_eq!(
            filled
                .column()
                .as_f64_slice()
                .expect("all gaps filled into an all-valid Float64 buffer"),
            &[1.0, 1.0, 3.0, 3.0]
        );
        assert!(filled.column().validity().all());

        let leading = Series::new(
            "v",
            Index::new_known_unique_int64_unit_range(0, 4),
            fp_columnar::Column::from_f64_values(vec![f64::NAN, f64::NAN, 3.0, f64::NAN]),
        )
        .unwrap()
        .ffill(None)
        .unwrap();
        let (leading_data, leading_validity) = leading
            .column()
            .as_f64_slice_with_validity()
            .expect("leading gaps keep nullable Float64 storage");
        assert!(!leading_validity.get(0));
        assert!(!leading_validity.get(1));
        assert!(leading_validity.get(2));
        assert!(leading_validity.get(3));
        assert_eq!(&leading_data[2..], &[3.0, 3.0]);
    }

