    #[test]
    fn series_cum_skipna_false_propagates_nan() {
        // br-frankenpandas-tlhd6: skipna=False makes the first NaN and every
        // later position NaN. Expected values verified vs pandas 2.2.3.
        let labels = vec![
            IndexLabel::from("a"),
            IndexLabel::from("b"),
            IndexLabel::from("c"),
            IndexLabel::from("d"),
        ];
        let s = Series::from_values(
            "vals",
            labels.clone(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();

        // Each op: skipna=false poisons positions 2 & 3; the all-valid prefix
        // (positions 0 & 1) keeps the op's normal running value.
        let assert_poisoned = |out: &Series, p0: f64, p1: f64| {
            assert_eq!(out.values()[0], Scalar::Float64(p0));
            assert_eq!(out.values()[1], Scalar::Float64(p1));
            assert!(out.values()[2].is_missing(), "NaN position");
            assert!(out.values()[3].is_missing(), "poisoned after NaN");
        };
        assert_poisoned(&s.cumsum_with_skipna(false).unwrap(), 1.0, 3.0);
        assert_poisoned(&s.cumprod_with_skipna(false).unwrap(), 1.0, 2.0);
        assert_poisoned(&s.cummax_with_skipna(false).unwrap(), 1.0, 2.0);
        assert_poisoned(&s.cummin_with_skipna(false).unwrap(), 1.0, 1.0);
        // skipna=true keeps the default behavior (NaN does not poison row 3).
        assert!(!s.cumsum_with_skipna(true).unwrap().values()[3].is_missing());
        assert!(!s.cummax_with_skipna(true).unwrap().values()[3].is_missing());

        // First value missing -> entire output missing.
        let head_nan = Series::from_values(
            "v",
            vec![IndexLabel::from(0_i64), IndexLabel::from(1_i64)],
            vec![Scalar::Null(NullKind::NaN), Scalar::Float64(2.0)],
        )
        .unwrap();
        let out = head_nan.cumsum_with_skipna(false).unwrap();
        assert!(out.values()[0].is_missing());
        assert!(out.values()[1].is_missing());

        // No missing values -> skipna=false equals the default scan.
        let clean = Series::from_values(
            "v",
            vec![IndexLabel::from(0_i64), IndexLabel::from(1_i64)],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();
        assert_eq!(
            clean.cumsum_with_skipna(false).unwrap().values(),
            clean.cumsum().unwrap().values()
        );
    }

