    #[test]
    fn series_clip_bounds_values() {
        let s = Series::from_values(
            "vals",
            vec![
                IndexLabel::from("a"),
                IndexLabel::from("b"),
                IndexLabel::from("c"),
            ],
            vec![
                Scalar::Float64(-5.0),
                Scalar::Float64(3.0),
                Scalar::Float64(10.0),
            ],
        )
        .unwrap();

        let clipped = s.clip(Some(0.0), Some(5.0)).unwrap();
        assert_eq!(clipped.values()[0], Scalar::Float64(0.0));
        assert_eq!(clipped.values()[1], Scalar::Float64(3.0));
        assert_eq!(clipped.values()[2], Scalar::Float64(5.0));
    }

    /// A NULL in an int lane does not demote clip's output to Float64.
    ///
    /// MEASURED, live pandas 2.2.3, `s = [1, <missing>, 10, <missing>]`,
    /// `clip(2.0, 8.0)` — the bounds are FLOATS in both arms:
    ///
    /// ```text
    ///   dtype float64 -> float64 ['2.0', 'nan', '8.0', 'nan']
    ///   dtype Int64   -> Int64   ['2',   '<NA>', '8',  '<NA>']
    /// ```
    ///
    /// so clip preserves the INPUT dtype regardless of the bounds' dtype. An
    /// FP `Int64` column carrying a null IS the nullable `Int64` extension
    /// (DISCREPANCIES DISC-011), so it takes the second row.
    ///
    /// EACH ARM KILLS A SPECIFIC WRONG FIX:
    /// - the Int64-with-null arm, or the removed `!has_nulls` condition simply
    ///   comes back;
    /// - the FLOAT64-with-null arm, or "always preserve the input dtype" passes
    ///   while silently turning float lanes into ints;
    /// - the 2.5-bound arm, or dropping `is_integer_bound` passes and an
    ///   Int64 lane starts reporting 2 where pandas gives 2.5;
    /// - the null is asserted to SURVIVE as a null rather than being clamped to
    ///   a bound, which is what a naive "clamp every element" loop would do.
    ///
    /// (br-frankenpandas-p5nku; sibling of br-frankenpandas-vc6iu)
    #[test]
    fn series_clip_keeps_a_nullable_int64_lane_p5nku() {
        let idx = vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()];
        let int_lane = Series::from_values(
            "nums",
            idx.clone(),
            vec![
                Scalar::Int64(1),
                Scalar::Null(NullKind::Null),
                Scalar::Int64(10),
                Scalar::Null(NullKind::Null),
            ],
        )
        .unwrap();

        let clipped = int_lane.clip(Some(2.0), Some(8.0)).expect("clip");
        assert_eq!(clipped.column().dtype(), DType::Int64);
        assert_eq!(clipped.values()[0], Scalar::Int64(2));
        assert_eq!(clipped.values()[2], Scalar::Int64(8));
        assert!(
            clipped.values()[1].is_missing() && clipped.values()[3].is_missing(),
            "the null survives clip rather than being clamped to a bound"
        );

        // A FLOAT64 lane with nulls stays Float64.
        let float_lane = Series::from_values(
            "nums",
            idx.clone(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(10.0),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        let clipped_float = float_lane.clip(Some(2.0), Some(8.0)).expect("clip");
        assert_eq!(clipped_float.column().dtype(), DType::Float64);
        assert_eq!(clipped_float.values()[0], Scalar::Float64(2.0));

        // A NON-integer bound genuinely demands Float64, null or not.
        let widened = int_lane.clip(Some(2.5), Some(8.0)).expect("clip");
        assert_eq!(widened.column().dtype(), DType::Float64);
        assert_eq!(widened.values()[0], Scalar::Float64(2.5));
    }

    #[test]
    fn series_clip_nan_bound_preserves_int64_s0rt1() {
        // Per br-frankenpandas-s0rt1: pandas treats NaN bounds as "no
        // clipping" — they must NOT demote Int64 to Float64 and must
        // NOT participate in comparison.
        let s = Series::from_values(
            "v",
            vec![
                IndexLabel::from("a"),
                IndexLabel::from("b"),
                IndexLabel::from("c"),
            ],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();

        // NaN as lower → no clipping; dtype stays Int64
        let clipped = s.clip(Some(f64::NAN), None).unwrap();
        assert_eq!(clipped.values()[0], Scalar::Int64(1));
        assert_eq!(clipped.values()[1], Scalar::Int64(2));
        assert_eq!(clipped.values()[2], Scalar::Int64(3));

        // Real lower bound 2 → 1 clipped to 2; dtype stays Int64
        let clipped = s.clip(Some(2.0), Some(f64::NAN)).unwrap();
        assert_eq!(clipped.values()[0], Scalar::Int64(2));
        assert_eq!(clipped.values()[1], Scalar::Int64(2));
        assert_eq!(clipped.values()[2], Scalar::Int64(3));
    }

    #[test]
    fn series_clip_reversed_scalar_bounds_swap_gh2747() {
        // Per pandas GH 2747: scalar lower > upper is swapped, so clip(7, 3)
        // behaves as clip(3, 7). Verified vs live pandas 2.2.3:
        // pd.Series([1,5,9]).clip(7, 3) -> [3, 5, 7] (NOT numpy's [3, 3, 3]).
        let s = Series::from_values(
            "v",
            vec![
                IndexLabel::from("a"),
                IndexLabel::from("b"),
                IndexLabel::from("c"),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(5.0),
                Scalar::Float64(9.0),
            ],
        )
        .unwrap();
        let clipped = s.clip(Some(7.0), Some(3.0)).unwrap();
        assert_eq!(clipped.values()[0], Scalar::Float64(3.0));
        assert_eq!(clipped.values()[1], Scalar::Float64(5.0));
        assert_eq!(clipped.values()[2], Scalar::Float64(9.0_f64.min(7.0)));
        assert_eq!(clipped.values()[2], Scalar::Float64(7.0));

        // Int64 dtype is preserved through the swap (pandas keeps int64).
        let si = Series::from_values(
            "i",
            vec![
                IndexLabel::from("a"),
                IndexLabel::from("b"),
                IndexLabel::from("c"),
            ],
            vec![Scalar::Int64(1), Scalar::Int64(5), Scalar::Int64(9)],
        )
        .unwrap();
        let ci = si.clip(Some(7.0), Some(3.0)).unwrap();
        assert_eq!(ci.values()[0], Scalar::Int64(3));
        assert_eq!(ci.values()[1], Scalar::Int64(5));
        assert_eq!(ci.values()[2], Scalar::Int64(7));

        // A NaN bound is normalized to None and must NOT trigger a swap:
        // clip(7, NaN) stays a one-sided lower clip -> [7, 7, 9].
        let cn = s.clip(Some(7.0), Some(f64::NAN)).unwrap();
        assert_eq!(cn.values()[0], Scalar::Float64(7.0));
        assert_eq!(cn.values()[1], Scalar::Float64(7.0));
        assert_eq!(cn.values()[2], Scalar::Float64(9.0));
    }

    #[test]
    fn series_abs_and_round() {
        let neg_pi = -std::f64::consts::PI;
        let e = std::f64::consts::E;
        let s = Series::from_values(
            "vals",
            vec![IndexLabel::from("a"), IndexLabel::from("b")],
            vec![Scalar::Float64(neg_pi), Scalar::Float64(e)],
        )
        .unwrap();

        let a = s.abs().unwrap();
        assert!(
            matches!(a.values()[0], Scalar::Float64(v) if (v - std::f64::consts::PI).abs() < 1e-12)
        );

        let r = s.round(2).unwrap();
        let expected_neg_pi_2dp = (neg_pi * 100.0).round_ties_even() / 100.0;
        let expected_e_2dp = (e * 100.0).round_ties_even() / 100.0;
        assert!(
            matches!(r.values()[0], Scalar::Float64(v) if (v - expected_neg_pi_2dp).abs() < 1e-12)
        );
        assert!(matches!(r.values()[1], Scalar::Float64(v) if (v - expected_e_2dp).abs() < 1e-12));
    }

