    #[test]
    fn series_round_signed_decimals_match_oracle_amxym() {
        // Differential vs an independent half-even scaling oracle
        // (br-frankenpandas-amxym). Seeded LCG, no mocks.
        fn next(seed: &mut u64) -> u64 {
            *seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            *seed
        }

        fn round_oracle(value: f64, decimals: i32) -> f64 {
            if decimals >= 0 {
                let factor = 10_f64.powi(decimals);
                (value * factor).round_ties_even() / factor
            } else {
                let factor = 10_f64.powi(-decimals);
                (value / factor).round_ties_even() * factor
            }
        }

        let mut seed = 0x5eed_a11c_e0de_51a7_u64;
        for decimals in -3..=3 {
            for case in 0..180 {
                let len = (next(&mut seed) % 41 + 1) as usize;
                let mut labels = Vec::with_capacity(len);
                let mut values = Vec::with_capacity(len);

                for pos in 0..len {
                    labels.push(IndexLabel::from((case * 100 + pos) as i64));
                    let selector = next(&mut seed) % 29;
                    let raw = (next(&mut seed) % 2_000_001) as i64 - 1_000_000;
                    let frac = (next(&mut seed) % 10_000) as f64 / 10_000.0;
                    let signed_frac = if next(&mut seed) & 1 == 0 {
                        frac
                    } else {
                        -frac
                    };
                    let value = raw as f64 / 7.0 + signed_frac;
                    values.push(match selector {
                        0 => Scalar::Null(NullKind::Null),
                        1 => Scalar::Float64(f64::NAN),
                        _ => Scalar::Float64(value),
                    });
                }

                let input = Series::from_values("round", labels.clone(), values.clone()).unwrap();
                let rounded = input.round(decimals).unwrap();
                assert_eq!(rounded.index().labels(), labels.as_slice());
                assert_eq!(rounded.values().len(), values.len());

                for (pos, (before, after)) in values.iter().zip(rounded.values()).enumerate() {
                    if before.is_missing() {
                        assert!(
                            after.is_missing(),
                            "decimals={decimals} case={case} pos={pos}: missing became {after:?}"
                        );
                        continue;
                    }

                    let expected = match before {
                        Scalar::Float64(v) => round_oracle(*v, decimals),
                        other => panic!("unexpected non-float value: {other:?}"),
                    };
                    match after {
                        Scalar::Float64(got) => assert!(
                            (*got - expected).abs() <= 1e-9,
                            "decimals={decimals} case={case} pos={pos}: got {got}, expected {expected}"
                        ),
                        other => panic!(
                            "decimals={decimals} case={case} pos={pos}: expected Float64, got {other:?}"
                        ),
                    }
                }
            }
        }
    }

    #[test]
    fn series_floor_ceil_trunc_match_scalar_oracle_8yygi() {
        // Differential vs scalar f64 oracles (br-frankenpandas-8yygi).
        // Seeded LCG, no mocks.
        fn next(seed: &mut u64) -> u64 {
            *seed = seed
                .wrapping_mul(2862933555777941757)
                .wrapping_add(3037000493);
            *seed
        }

        fn floor_oracle(v: f64) -> f64 {
            v.floor()
        }

        fn ceil_oracle(v: f64) -> f64 {
            v.ceil()
        }

        fn trunc_oracle(v: f64) -> f64 {
            v.trunc()
        }

        let mut seed = 0x8f10_0ce1_7a11_cafe_u64;
        for case in 0..260 {
            let len = (next(&mut seed) % 53 + 1) as usize;
            let mut labels = Vec::with_capacity(len);
            let mut values = Vec::with_capacity(len);

            for pos in 0..len {
                labels.push(IndexLabel::from((case * 1000 + pos) as i64));
                let selector = next(&mut seed) % 31;
                let whole = (next(&mut seed) % 200_001) as i64 - 100_000;
                let frac = (next(&mut seed) % 10_000) as f64 / 10_000.0;
                let signed = if next(&mut seed) & 1 == 0 {
                    whole as f64 + frac
                } else {
                    -(whole as f64 + frac)
                };
                values.push(match selector {
                    0 => Scalar::Null(NullKind::Null),
                    1 => Scalar::Float64(f64::NAN),
                    _ => Scalar::Float64(signed / 11.0),
                });
            }

            let input = Series::from_values("unary", labels.clone(), values.clone()).unwrap();
            let outputs: [(&str, Series, fn(f64) -> f64); 3] = [
                ("floor", input.floor().unwrap(), floor_oracle),
                ("ceil", input.ceil().unwrap(), ceil_oracle),
                ("trunc", input.trunc().unwrap(), trunc_oracle),
            ];

            for (op, output, oracle) in outputs {
                assert_eq!(
                    output.index().labels(),
                    labels.as_slice(),
                    "{op} index drift"
                );
                assert_eq!(output.values().len(), values.len(), "{op} length drift");
                for (pos, (before, after)) in values.iter().zip(output.values()).enumerate() {
                    if before.is_missing() {
                        assert!(
                            after.is_missing(),
                            "{op} case={case} pos={pos}: missing became {after:?}"
                        );
                        continue;
                    }

                    let expected = match before {
                        Scalar::Float64(v) => oracle(*v),
                        other => panic!("{op} unexpected non-float value: {other:?}"),
                    };
                    match after {
                        Scalar::Float64(got) => assert_eq!(
                            *got, expected,
                            "{op} case={case} pos={pos}: got {got}, expected {expected}"
                        ),
                        other => {
                            panic!("{op} case={case} pos={pos}: expected Float64, got {other:?}")
                        }
                    }
                }
            }
        }
    }

