    #[test]
    fn series_loc_materialized_sorted_int64_preserves_order_and_typed_index_locfast() {
        let s = Series::from_values(
            "vals",
            vec![0_i64.into(), 2_i64.into(), 4_i64.into(), 6_i64.into()],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
                Scalar::Float64(40.0),
            ],
        )
        .unwrap();

        let selected = s.loc(&[6_i64.into(), 0_i64.into(), 6_i64.into()]).unwrap();
        match selected.index().cached_int64_label_values() {
            Some(Some(values)) => assert_eq!(values.as_ref().as_slice(), &[6, 0, 6]),
            other => panic!("loc fast path should emit a cached typed Int64 index, got {other:?}"),
        }
        assert_eq!(
            selected.index().labels(),
            &[
                IndexLabel::from(6_i64),
                IndexLabel::from(0_i64),
                IndexLabel::from(6_i64)
            ]
        );
        assert_eq!(
            selected.values(),
            &[
                Scalar::Float64(40.0),
                Scalar::Float64(10.0),
                Scalar::Float64(40.0)
            ]
        );

        let err = s.loc(&[8_i64.into()]).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("loc label not found"))
        );
    }

    #[test]
    fn series_loc_unsorted_unique_int64_uses_cached_lookup_locfast() {
        // Unsorted (not ascending) yet unique Int64 index ⇒ takes the
        // identity-cached i64->position hashtable path, not binary search.
        let s = Series::from_values(
            "vals",
            vec![4_i64.into(), 0_i64.into(), 6_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
                Scalar::Float64(40.0),
            ],
        )
        .unwrap();

        let selected = s.loc(&[6_i64.into(), 0_i64.into(), 6_i64.into()]).unwrap();
        match selected.index().cached_int64_label_values() {
            Some(Some(values)) => assert_eq!(values.as_ref().as_slice(), &[6, 0, 6]),
            other => panic!("loc fast path should emit a cached typed Int64 index, got {other:?}"),
        }
        assert_eq!(
            selected.values(),
            &[
                Scalar::Float64(30.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0)
            ]
        );

        // Result must match the duplicate-aware general path exactly.
        let err = s.loc(&[8_i64.into()]).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("loc label not found"))
        );
    }

