    #[test]
    fn dataframe_set_index_promotes_datetime_column_to_datetime_index() {
        // df.set_index('t') on a datetime column -> datetime64[ns] index with
        // values preserved and index name = column. Verified against live
        // pandas 2.2.3 (index.dtype == datetime64[ns]).
        let t0 = 1_704_067_200_000_000_000_i64; // 2024-01-01T00:00:00Z in ns
        let t1 = 1_704_153_600_000_000_000_i64; // 2024-01-02T00:00:00Z in ns
        let df = DataFrame::from_dict(
            &["t", "v"],
            vec![
                ("t", vec![Scalar::Datetime64(t0), Scalar::Datetime64(t1)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();

        let out = df.set_index("t", true).unwrap();
        assert_eq!(
            out.index().labels(),
            &[IndexLabel::Datetime64(t0), IndexLabel::Datetime64(t1)]
        );
        assert_eq!(out.index().dtype(), "datetime64[ns]");
        assert_eq!(out.index().name(), Some("t"));
        let names = out.column_names().into_iter().cloned().collect::<Vec<_>>();
        assert_eq!(names, vec!["v".to_owned()]);
        assert!(out.column("t").is_none());
    }

    #[test]
    fn dataframe_set_index_promotes_timedelta_column_to_timedelta_index() {
        // df.set_index('d') on a timedelta column -> timedelta64[ns] index.
        let d0 = 86_400_000_000_000_i64; // 1 day in ns
        let d1 = 172_800_000_000_000_i64; // 2 days in ns
        let df = DataFrame::from_dict(
            &["d", "v"],
            vec![
                ("d", vec![Scalar::Timedelta64(d0), Scalar::Timedelta64(d1)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();

        // drop=false keeps the source column too, matching pandas.
        let out = df.set_index("d", false).unwrap();
        assert_eq!(
            out.index().labels(),
            &[IndexLabel::Timedelta64(d0), IndexLabel::Timedelta64(d1)]
        );
        assert_eq!(out.index().dtype(), "timedelta64[ns]");
        assert_eq!(out.index().name(), Some("d"));
        assert_eq!(
            out.column("d").unwrap().values(),
            &[Scalar::Timedelta64(d0), Scalar::Timedelta64(d1)]
        );
    }

    #[test]
    fn dataframe_set_index_reset_index_datetime_roundtrips_typed() {
        // set_index('t').reset_index() must return a datetime64 column, not a
        // stringified one — pandas reset_index on a DatetimeIndex yields a
        // datetime64[ns] column. Guards the index_label_to_scalar symmetry fix.
        let t0 = 1_704_067_200_000_000_000_i64;
        let t1 = 1_704_153_600_000_000_000_i64;
        let df = DataFrame::from_dict(
            &["t", "v"],
            vec![
                ("t", vec![Scalar::Datetime64(t0), Scalar::Datetime64(t1)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();

        let indexed = df.set_index("t", true).unwrap();
        // reset_index restores the former index under its NAME ("t", pandas
        // parity) with the datetime dtype preserved.
        let restored = indexed.reset_index(false).unwrap();
        let restored_col = restored.column("t").unwrap();
        assert_eq!(
            restored_col.values(),
            &[Scalar::Datetime64(t0), Scalar::Datetime64(t1)]
        );
        assert_eq!(restored_col.dtype(), DType::Datetime64);
        assert!(
            restored.column("index").is_none(),
            "named index must reset to its name, not 'index'"
        );
    }

    #[test]
    fn dataframe_reset_index_uses_index_name_with_pandas_collision_rules() {
        let df = DataFrame::from_dict(
            &["a", "v"],
            vec![
                ("a", vec![Scalar::Int64(10), Scalar::Int64(20)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();

        // Named index -> restored column carries the index NAME ('a'), not 'index'.
        let named = df.set_index("a", true).unwrap().reset_index(false).unwrap();
        assert!(named.column("a").is_some());
        assert!(named.column("index").is_none());
        let order = named
            .column_names()
            .into_iter()
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(order, vec!["a".to_owned(), "v".to_owned()]);

        // Unnamed (default RangeIndex) -> 'index'.
        let unnamed = df.reset_index(false).unwrap();
        assert!(unnamed.column("index").is_some());

        // Collision: index named 'a' while the source 'a' column is kept
        // (drop=false) -> pandas ValueError "cannot insert a, already exists".
        let collide = df
            .set_index("a", false)
            .unwrap()
            .reset_index(false)
            .unwrap_err();
        assert!(
            matches!(collide, FrameError::CompatibilityRejected(msg) if msg.contains("cannot insert a, already exists"))
        );
    }

    #[test]
    fn dataframe_set_index_rejects_missing_or_unsupported_labels() {
        let df = DataFrame::from_dict(
            &["id", "v"],
            vec![
                ("id", vec![Scalar::Int64(10), Scalar::Int64(20)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();
        let err = df.set_index("missing", true).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("column 'missing' not found"))
        );

        // br-frankenpandas-i10en: set_index on a Float64 column now produces a
        // Float64Index (previously rejected).
        let df_float = DataFrame::from_dict(
            &["id", "v"],
            vec![
                ("id", vec![Scalar::Float64(1.5), Scalar::Float64(2.5)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();
        let indexed = df_float.set_index("id", true).unwrap();
        assert!(matches!(
            indexed.index().labels()[0],
            IndexLabel::Float64(_)
        ));

        // Period labels still have no IndexLabel variant and remain rejected.
        let df_period = DataFrame::from_dict(
            &["id", "v"],
            vec![
                (
                    "id",
                    vec![
                        Scalar::Period(Period::new(0, PeriodFreq::Daily)),
                        Scalar::Period(Period::new(1, PeriodFreq::Daily)),
                    ],
                ),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();
        let err = df_period.set_index("id", true).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("set_index currently supports"))
        );

        let df_null = DataFrame::from_dict(
            &["id", "v"],
            vec![
                ("id", vec![Scalar::Null(NullKind::Null), Scalar::Int64(2)]),
                ("v", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )
        .unwrap();
        let err = df_null.set_index("id", true).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("missing label values"))
        );
    }

    #[test]
    fn dataframe_set_index_verify_integrity_rejects_duplicate_labels() {
        let df = DataFrame::from_dict(
            &["id", "v"],
            vec![
                (
                    "id",
                    vec![Scalar::Int64(10), Scalar::Int64(10), Scalar::Int64(20)],
                ),
                (
                    "v",
                    vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
                ),
            ],
        )
        .unwrap();

        let err = df
            .set_index_with_verify_integrity("id", true, true)
            .unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("Index has duplicate keys"))
        );

        let out = df
            .set_index_with_verify_integrity("id", true, false)
            .unwrap();
        assert_eq!(
            out.index().labels(),
            &[
                IndexLabel::Int64(10),
                IndexLabel::Int64(10),
                IndexLabel::Int64(20),
            ]
        );
    }

