    #[test]
    fn typed_dense_values_already_sorted_matches_supported_dense_semantics() {
        let ascending_ints = vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(2)];
        assert_eq!(
            typed_dense_values_already_sorted(&ascending_ints, DType::Int64, true),
            Some(true)
        );
        assert_eq!(
            typed_dense_values_already_sorted(&ascending_ints, DType::Int64, false),
            Some(false)
        );

        let descending_floats = vec![
            Scalar::Float64(3.0),
            Scalar::Float64(2.0),
            Scalar::Float64(2.0),
            Scalar::Float64(-0.0),
        ];
        assert_eq!(
            typed_dense_values_already_sorted(&descending_floats, DType::Float64, false),
            Some(true)
        );
        assert_eq!(
            typed_dense_values_already_sorted(&descending_floats, DType::Float64, true),
            Some(false)
        );

        let with_nan = vec![Scalar::Float64(1.0), Scalar::Float64(f64::NAN)];
        assert_eq!(
            typed_dense_values_already_sorted(&with_nan, DType::Float64, true),
            None
        );
        let unsupported = vec![Scalar::Utf8("a".to_owned()), Scalar::Utf8("b".to_owned())];
        assert_eq!(
            typed_dense_values_already_sorted(&unsupported, DType::Utf8, true),
            None
        );
    }

    #[test]
    fn dataframe_sort_values_already_sorted_preserves_observable_state() {
        let df = DataFrame::from_dict_with_index(
            vec![
                (
                    "score",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Null(NullKind::NaN),
                    ],
                ),
                (
                    "tag",
                    vec![
                        Scalar::Utf8("first-one".to_owned()),
                        Scalar::Utf8("second-one".to_owned()),
                        Scalar::Utf8("two".to_owned()),
                        Scalar::Utf8("missing".to_owned()),
                    ],
                ),
            ],
            vec!["r1".into(), "r2".into(), "r3".into(), "r4".into()],
        )
        .unwrap();

        let out = df.sort_values("score", true).unwrap();
        assert_eq!(out.index().labels(), df.index().labels());
        assert_eq!(out.column_names(), df.column_names());
        assert_eq!(
            out.column("score").unwrap().values(),
            df.column("score").unwrap().values()
        );
        assert_eq!(
            out.column("tag").unwrap().values(),
            df.column("tag").unwrap().values()
        );

        let na_first = DataFrame::from_dict_with_index(
            vec![(
                "score",
                vec![
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                ],
            )],
            vec!["missing".into(), "one".into(), "two".into()],
        )
        .unwrap();
        let out = na_first.sort_values_na("score", true, "first").unwrap();
        assert_eq!(out.index().labels(), na_first.index().labels());
        assert_eq!(
            out.column("score").unwrap().values(),
            na_first.column("score").unwrap().values()
        );
    }

