    #[test]
    fn dataframe_loc_materialized_sorted_int64_preserves_order_and_typed_index_locfast() {
        let df = DataFrame::from_dict_with_index(
            vec![
                (
                    "a",
                    vec![
                        Scalar::Int64(10),
                        Scalar::Int64(20),
                        Scalar::Int64(30),
                        Scalar::Int64(40),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Int64(100),
                        Scalar::Int64(200),
                        Scalar::Int64(300),
                        Scalar::Int64(400),
                    ],
                ),
            ],
            vec![0_i64.into(), 2_i64.into(), 4_i64.into(), 6_i64.into()],
        )
        .unwrap();

        let selected = df.loc(&[6_i64.into(), 2_i64.into(), 6_i64.into()]).unwrap();
        match selected.index().cached_int64_label_values() {
            Some(Some(values)) => assert_eq!(values.as_ref().as_slice(), &[6, 2, 6]),
            other => panic!("loc fast path should emit a cached typed Int64 index, got {other:?}"),
        }
        assert_eq!(
            selected.index().labels(),
            &[
                IndexLabel::from(6_i64),
                IndexLabel::from(2_i64),
                IndexLabel::from(6_i64)
            ]
        );
        assert_eq!(
            selected.column("a").unwrap().values(),
            &[Scalar::Int64(40), Scalar::Int64(20), Scalar::Int64(40)]
        );
        assert_eq!(
            selected.column("b").unwrap().values(),
            &[Scalar::Int64(400), Scalar::Int64(200), Scalar::Int64(400)]
        );

        let err = df.loc(&[8_i64.into()]).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("loc label not found"))
        );
    }

