    #[test]
    fn boolean_mask_positions_tracks_affine_certificate() {
        let affine_mask = [false, true, false, false, true, false, false, true, false];
        let (positions, certificate) = super::boolean_mask_positions(&affine_mask);
        assert_eq!(positions, vec![1, 4, 7]);
        assert_eq!(
            certificate,
            Some(super::AffineSelectionCertificate {
                start: 1,
                step: 3,
                len: 3
            })
        );

        let (single_position, single_certificate) =
            super::boolean_mask_positions(&[false, false, true, false]);
        assert_eq!(single_position, vec![2]);
        assert_eq!(
            single_certificate,
            Some(super::AffineSelectionCertificate {
                start: 2,
                step: 1,
                len: 1
            })
        );

        let (empty_positions, empty_certificate) =
            super::boolean_mask_positions(&[false, false, false]);
        assert!(empty_positions.is_empty());
        assert_eq!(empty_certificate, None);

        let non_affine_mask = [true, false, true, true, false, false, true];
        let (non_affine_positions, non_affine_certificate) =
            super::boolean_mask_positions(&non_affine_mask);
        assert_eq!(non_affine_positions, vec![0, 2, 3, 6]);
        assert_eq!(non_affine_certificate, None);
    }

    #[test]
    fn boolean_mask_affine_certificate_recognizes_every_other_octets() {
        let even_mask = [
            true, false, true, false, true, false, true, false, true, false,
        ];
        assert_eq!(
            super::boolean_mask_affine_certificate(&even_mask),
            Some(super::AffineSelectionCertificate {
                start: 0,
                step: 2,
                len: 5
            })
        );

        let odd_mask = [
            false, true, false, true, false, true, false, true, false, true, false,
        ];
        assert_eq!(
            super::boolean_mask_affine_certificate(&odd_mask),
            Some(super::AffineSelectionCertificate {
                start: 1,
                step: 2,
                len: 5
            })
        );

        let non_periodic = [true, false, true, false, false, false, true, false];
        assert_eq!(super::boolean_mask_affine_certificate(&non_periodic), None);
    }

