    #[test]
    fn series_pct_change_timedelta64_matches_pandas_naeja() {
        // Per br-frankenpandas-naeja: pct_change on Timedelta64 returns
        // dimensionless f64 ratios; was silently NaN before via the
        // to_f64-else-NaN catch-all.
        let one_hour = 3_600 * 1_000_000_000_i64;
        let two_hours = 2 * one_hour;
        let four_hours = 4 * one_hour;
        let s = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(two_hours),
                Scalar::Timedelta64(four_hours),
            ],
        )
        .unwrap();

        let result = s.pct_change(1).unwrap();
        assert!(result.values()[0].is_missing()); // first is NaN
        let v1 = result.values()[1].to_f64().unwrap();
        assert!((v1 - 1.0).abs() < 1e-10); // (2h-1h)/1h = 1.0
        let v2 = result.values()[2].to_f64().unwrap();
        assert!((v2 - 1.0).abs() < 1e-10); // (4h-2h)/2h = 1.0
    }

    #[test]
    fn series_pct_change_timedelta64_nat_forward_fills_naeja() {
        // pandas 2.2.3 pct_change default fill_method='pad' forward-fills the
        // NaT before computing: [1h, NaT, 2h] -> filled [1h, 1h, 2h] ->
        // [NaN, (1h-1h)/1h=0, (2h-1h)/1h=1]. (br-frankenpandas-5ioai)
        let one_hour = 3_600 * 1_000_000_000_i64;
        let s = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(fp_types::Timedelta::NAT),
                Scalar::Timedelta64(2 * one_hour),
            ],
        )
        .unwrap();

        let result = s.pct_change(1).unwrap();
        assert!(result.values()[0].is_missing());
        assert!((result.values()[1].to_f64().unwrap() - 0.0).abs() < 1e-10);
        assert!((result.values()[2].to_f64().unwrap() - 1.0).abs() < 1e-10);
    }

    #[test]
    fn series_pct_change_forward_fills_interior_nan_5ioai() {
        // pandas default ffill: [1.0, nan, 4.0].pct_change() -> [NaN, 0.0, 3.0];
        // no-fill (fill_method=None) -> [NaN, NaN, NaN].
        let s = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();

        let filled = s.pct_change(1).unwrap();
        assert!(filled.values()[0].is_missing());
        assert!((filled.values()[1].to_f64().unwrap() - 0.0).abs() < 1e-10);
        assert!((filled.values()[2].to_f64().unwrap() - 3.0).abs() < 1e-10);

        let no_fill = s.pct_change_with_fill(1, None, None).unwrap();
        assert!(no_fill.values()[0].is_missing());
        assert!(no_fill.values()[1].is_missing());
        assert!(no_fill.values()[2].is_missing());
    }

    #[test]
    fn series_diff_timedelta64_returns_timedelta_q82t4() {
        // Per br-frankenpandas-q82t4: diff on Timedelta64 returns Timedelta64
        // differences (preserves dtype), not Float64. Was silently NaN before
        // via the to_f64-else-NaN catch-all.
        let one_hour = 3_600 * 1_000_000_000_i64;
        let s = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(3 * one_hour),
                Scalar::Timedelta64(2 * one_hour),
            ],
        )
        .unwrap();

        let result = s.diff(1).unwrap();
        assert!(result.values()[0].is_missing()); // first row → NaN
        match &result.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(*ns, 2 * one_hour),
            other => panic!("expected Timedelta64(2h), got {:?}", other),
        }
        match &result.values()[2] {
            Scalar::Timedelta64(ns) => assert_eq!(*ns, -one_hour),
            other => panic!("expected Timedelta64(-1h), got {:?}", other),
        }
    }

    #[test]
    fn series_diff_timedelta64_nat_propagates_q82t4() {
        let one_hour = 3_600 * 1_000_000_000_i64;
        let s = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(fp_types::Timedelta::NAT),
                Scalar::Timedelta64(2 * one_hour),
            ],
        )
        .unwrap();

        let result = s.diff(1).unwrap();
        assert!(result.values()[0].is_missing());
        assert!(result.values()[1].is_missing()); // NaT current → NaT
        assert!(result.values()[2].is_missing()); // NaT previous → NaT
    }

    #[test]
    fn series_diff_datetime64_returns_timedelta_exact() {
        // dt.diff() = elapsed time between consecutive timestamps -> Timedelta64. Was
        // SILENTLY all-null: the generic to_f64 cascade caught the Datetime64 Err and
        // emitted Null(NaN), so the whole series came back missing. Deterministic dtype +
        // value check, then an LCG differential over all-valid (typed arm) + nullable
        // (generic arm), periods +1/+2/-1; values near 1.6e18 >> 2^53 prove exactness.
        let base = 1_600_000_000_000_000_000_i64;
        let s = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Datetime64(base),
                Scalar::Datetime64(base + 5),
                Scalar::Datetime64(base + 2),
            ],
        )
        .unwrap();
        let d = s.diff(1).unwrap();
        assert_eq!(d.dtype(), DType::Timedelta64);
        assert!(d.values()[0].is_missing());
        assert_eq!(d.values()[1], Scalar::Timedelta64(5));
        assert_eq!(d.values()[2], Scalar::Timedelta64(-3));

        let mut state: u64 = 0xD1FF_C0DE_1234_9E37;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for nullable in [false, true] {
            for trial in 0..80 {
                let n = (next() % 60) as usize;
                let mut scalars = Vec::with_capacity(n);
                let mut opt: Vec<Option<i64>> = Vec::with_capacity(n);
                for _ in 0..n {
                    if nullable && next() % 4 == 0 {
                        scalars.push(Scalar::Null(NullKind::NaT));
                        opt.push(None);
                    } else {
                        let v = base + (next() % 1_000_000) as i64;
                        scalars.push(Scalar::Datetime64(v));
                        opt.push(Some(v));
                    }
                }
                let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
                let series = Series::from_values("ts", labels, scalars).unwrap();
                for periods in [1_i64, 2, -1] {
                    let vals = series.diff(periods).unwrap();
                    let vals = vals.values();
                    for i in 0..n {
                        let prev = if periods >= 0 {
                            i.checked_sub(periods as usize)
                        } else {
                            let j = i + periods.unsigned_abs() as usize;
                            if j < n { Some(j) } else { None }
                        };
                        match prev {
                            Some(j) if opt[i].is_some() && opt[j].is_some() => {
                                assert_eq!(
                                    vals[i],
                                    Scalar::Timedelta64(
                                        opt[i].unwrap().saturating_sub(opt[j].unwrap())
                                    ),
                                    "nullable={nullable} trial {trial} periods={periods} i={i}"
                                );
                            }
                            _ => assert!(
                                vals[i].is_missing(),
                                "nullable={nullable} trial {trial} periods={periods} i={i}: expected missing, got {:?}",
                                vals[i]
                            ),
                        }
                    }
                }
            }
        }
    }

