    #[test]
    fn series_rank_tie_methods_match_count_oracle_gjt0t() {
        // Differential tie-method oracle (br-frankenpandas-gjt0t). Small Int64
        // ranges force ties; the reference uses only count-strictly-less,
        // count-equal, and distinct-less formulas, independent of rank().
        let mut state: u64 = 0xa15e_d00d_5eed_1234;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };

        for iter in 0..1500u32 {
            let n = (next() % 13) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 7) as i64 - 3).collect();
            let mut distinct = vals.clone();
            distinct.sort_unstable();
            distinct.dedup();

            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().copied().map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap();

            for method in ["min", "max", "dense", "average"] {
                let ranked = series.rank(method, true, "keep").unwrap();
                for (idx, &value) in vals.iter().enumerate() {
                    let c_less = vals.iter().filter(|&&candidate| candidate < value).count();
                    let c_eq = vals.iter().filter(|&&candidate| candidate == value).count();
                    let expected = match method {
                        "min" => (c_less + 1) as f64,
                        "max" => (c_less + c_eq) as f64,
                        "dense" => {
                            (distinct
                                .iter()
                                .filter(|&&candidate| candidate < value)
                                .count()
                                + 1) as f64
                        }
                        "average" => c_less as f64 + (c_eq as f64 + 1.0) / 2.0,
                        _ => unreachable!("method list is fixed"),
                    };
                    assert_eq!(
                        ranked.values()[idx],
                        Scalar::Float64(expected),
                        "iter={iter} method={method} idx={idx} vals={vals:?}",
                    );
                }
            }
        }
    }

    #[test]
    fn series_rank_pct_average_scales_by_non_null_count() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(3.0),
                Scalar::Float64(1.0),
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();

        let ranked = s.rank_with_pct("average", true, "keep", true).unwrap();
        assert!(matches!(ranked.values()[0], Scalar::Float64(v) if (v - 1.0).abs() < 1e-12));
        assert!(matches!(ranked.values()[1], Scalar::Float64(v) if (v - 0.375).abs() < 1e-12));
        assert!(matches!(ranked.values()[2], Scalar::Float64(v) if (v - 0.375).abs() < 1e-12));
        assert!(matches!(ranked.values()[3], Scalar::Float64(v) if (v - 0.75).abs() < 1e-12));
    }

    #[test]
    fn series_rank_pct_dense_uses_distinct_non_null_count() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(3.0),
                Scalar::Float64(1.0),
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();

        let ranked = s.rank_with_pct("dense", true, "keep", true).unwrap();
        assert!(matches!(ranked.values()[0], Scalar::Float64(v) if (v - 1.0).abs() < 1e-12));
        assert!(
            matches!(ranked.values()[1], Scalar::Float64(v) if (v - (1.0 / 3.0)).abs() < 1e-12)
        );
        assert!(
            matches!(ranked.values()[2], Scalar::Float64(v) if (v - (1.0 / 3.0)).abs() < 1e-12)
        );
        assert!(
            matches!(ranked.values()[3], Scalar::Float64(v) if (v - (2.0 / 3.0)).abs() < 1e-12)
        );
    }

    #[test]
    fn series_rank_pct_top_includes_ranked_nulls_in_denominator() {
        // With na_option != "keep" the null is ranked, so the percentile
        // denominator is the full length (3), not the non-null count (2).
        // Verified against pandas 2.2.3: pd.Series([2.0, NaN, 1.0]).rank(
        //   method='average', na_option='top', pct=True) -> [1.0, 1/3, 2/3].
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(1.0),
            ],
        )
        .unwrap();

        let ranked = s.rank_with_pct("average", true, "top", true).unwrap();
        assert!(matches!(ranked.values()[0], Scalar::Float64(v) if (v - 1.0).abs() < 1e-12));
        assert!(matches!(ranked.values()[1], Scalar::Float64(v) if (v - 1.0 / 3.0).abs() < 1e-12));
        assert!(matches!(ranked.values()[2], Scalar::Float64(v) if (v - 2.0 / 3.0).abs() < 1e-12));
    }

    #[test]
    fn series_rank_pct_na_option_denominator_matches_pandas() {
        // pandas 2.2.3 ground truth for [3, 1, 1, NaN, 2]:
        //   average/top    -> [1.0, 0.5, 0.5, 0.2, 0.8]      (÷ 5 = full len)
        //   dense/top      -> [1.0, 0.5, 0.5, 0.25, 0.75]    (÷ 4 = distinct+1)
        //   average/bottom -> [0.8, 0.3, 0.3, 1.0, 0.6]      (÷ 5)
        //   dense/bottom   -> [0.75, 0.25, 0.25, 1.0, 0.5]   (÷ 4)
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(3.0),
                Scalar::Float64(1.0),
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();
        let f = |v: &Scalar| match v {
            Scalar::Float64(x) => *x,
            other => panic!("expected float, got {other:?}"),
        };
        let close = |got: Vec<f64>, want: [f64; 5]| {
            for (g, w) in got.iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-12, "got {got:?} want {want:?}");
            }
        };
        let collect = |s: Series| s.values().iter().map(f).collect::<Vec<_>>();
        close(
            collect(s.rank_with_pct("average", true, "top", true).unwrap()),
            [1.0, 0.5, 0.5, 0.2, 0.8],
        );
        close(
            collect(s.rank_with_pct("dense", true, "top", true).unwrap()),
            [1.0, 0.5, 0.5, 0.25, 0.75],
        );
        close(
            collect(s.rank_with_pct("average", true, "bottom", true).unwrap()),
            [0.8, 0.3, 0.3, 1.0, 0.6],
        );
        close(
            collect(s.rank_with_pct("dense", true, "bottom", true).unwrap()),
            [0.75, 0.25, 0.25, 1.0, 0.5],
        );
    }

    #[test]
    fn series_rank_na_option_multi_null_matches_pandas() {
        // Two nulls form ONE tied group; the method applies to that group.
        // pandas 2.2.3 ground truth for [3, NaN, 1, NaN, 2] (ascending):
        //   dense/top      -> [4, 1, 2, 1, 3]       (nulls share dense rank 1)
        //   dense/bottom   -> [3, 4, 1, 4, 2]       (nulls share dense rank distinct+1)
        //   average/top    -> [5, 1.5, 3, 1.5, 4]   (null group averaged over ranks 1..2)
        //   average/bottom -> [3, 4.5, 1, 4.5, 2]   (null group averaged over ranks 4..5)
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(3.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();
        let f = |v: &Scalar| match v {
            Scalar::Float64(x) => *x,
            other => panic!("expected float, got {other:?}"),
        };
        let collect = |s: Series| s.values().iter().map(f).collect::<Vec<_>>();
        let close = |got: Vec<f64>, want: [f64; 5]| {
            for (g, w) in got.iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-12, "got {got:?} want {want:?}");
            }
        };
        close(
            collect(s.rank("dense", true, "top").unwrap()),
            [4.0, 1.0, 2.0, 1.0, 3.0],
        );
        close(
            collect(s.rank("dense", true, "bottom").unwrap()),
            [3.0, 4.0, 1.0, 4.0, 2.0],
        );
        close(
            collect(s.rank("average", true, "top").unwrap()),
            [5.0, 1.5, 3.0, 1.5, 4.0],
        );
        close(
            collect(s.rank("average", true, "bottom").unwrap()),
            [3.0, 4.5, 1.0, 4.5, 2.0],
        );
    }

