    // ── pivot_table tests ──

    #[test]
    fn dataframe_pivot_table_sum() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df.pivot_table("val", "row", "col", "sum").unwrap();
        assert_eq!(pivoted.index.len(), 2); // r1, r2
        assert_eq!(pivoted.column_order.len(), 2); // c1, c2

        // r1, c1 → 1.0; r1, c2 → 2.0; r2, c1 → 3.0; r2, c2 → 4.0
        assert_eq!(pivoted.columns["c1"].values()[0], Scalar::Float64(1.0));
        assert_eq!(pivoted.columns["c2"].values()[0], Scalar::Float64(2.0));
        assert_eq!(pivoted.columns["c1"].values()[1], Scalar::Float64(3.0));
        assert_eq!(pivoted.columns["c2"].values()[1], Scalar::Float64(4.0));
    }

    #[test]
    fn dataframe_pivot_table_dense_int64_fast_path_1q4q4() {
        // Exercises the typed dense-Int64 fast path (all-valid Int64 axis keys,
        // all-valid Float64 values, online aggfunc). Includes a deliberately
        // MISSING cell (idx=20, col=2) to pin the absent-cell null repr to
        // Scalar::Null(NullKind::NaN) — bit-identical to the generic scatter.
        let idx: Vec<IndexLabel> = (0..4_i64).map(Into::into).collect();
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                idx.clone(),
                vec![10_i64.into(), 10_i64.into(), 10_i64.into(), 20_i64.into()],
            )
            .unwrap(),
            Series::from_values(
                "col",
                idx.clone(),
                vec![1_i64.into(), 1_i64.into(), 2_i64.into(), 1_i64.into()],
            )
            .unwrap(),
            Series::from_values(
                "val",
                idx,
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(7.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        // Sorted distinct: rows [10, 20]; cols named "1", "2".
        let null = Scalar::Null(NullKind::NaN);

        let s = df.pivot_table("val", "row", "col", "sum").unwrap();
        assert_eq!(s.index.len(), 2);
        assert_eq!(s.column_order, vec!["1".to_string(), "2".to_string()]);
        assert_eq!(
            s.columns["1"].values(),
            &[Scalar::Float64(4.0), Scalar::Float64(7.0)]
        );
        assert_eq!(
            s.columns["2"].values(),
            &[Scalar::Float64(5.0), null.clone()]
        );

        let m = df.pivot_table("val", "row", "col", "mean").unwrap();
        assert_eq!(
            m.columns["1"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(7.0)]
        );
        assert_eq!(
            m.columns["2"].values(),
            &[Scalar::Float64(5.0), null.clone()]
        );

        let c = df.pivot_table("val", "row", "col", "count").unwrap();
        assert_eq!(
            c.columns["1"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(1.0)]
        );
        assert_eq!(
            c.columns["2"].values(),
            &[Scalar::Float64(1.0), null.clone()]
        );

        let z = df.pivot_table("val", "row", "col", "size").unwrap();
        assert_eq!(
            z.columns["1"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(1.0)]
        );
        assert_eq!(
            z.columns["2"].values(),
            &[Scalar::Float64(1.0), null.clone()]
        );

        // min/max over the same cells: (10,1)=[1,3], (10,2)=[5], (20,1)=[7].
        let mn = df.pivot_table("val", "row", "col", "min").unwrap();
        assert_eq!(
            mn.columns["1"].values(),
            &[Scalar::Float64(1.0), Scalar::Float64(7.0)]
        );
        assert_eq!(
            mn.columns["2"].values(),
            &[Scalar::Float64(5.0), null.clone()]
        );
        let mx = df.pivot_table("val", "row", "col", "max").unwrap();
        assert_eq!(
            mx.columns["1"].values(),
            &[Scalar::Float64(3.0), Scalar::Float64(7.0)]
        );
        assert_eq!(
            mx.columns["2"].values(),
            &[Scalar::Float64(5.0), null.clone()]
        );

        // median: (10,1)=[1,3]→2.0, (20,1)=[7]→7.0; (10,2)=[5]→5.0, (20,2) absent.
        let md = df.pivot_table("val", "row", "col", "median").unwrap();
        assert_eq!(
            md.columns["1"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(7.0)]
        );
        assert_eq!(md.columns["2"].values(), &[Scalar::Float64(5.0), null]);

        // Index labels are the sorted distinct Int64 row keys, named "row".
        assert_eq!(
            s.index.labels(),
            &[IndexLabel::Int64(10), IndexLabel::Int64(20)]
        );
    }

    #[test]
    fn dataframe_pivot_table_dense_utf8_fast_path_1q4q4() {
        // Exercises the typed dense-Utf8 fast path (factorize axis keys + dense
        // row-order scatter). First-seen key order is "z","a"/"y","x" so the
        // assertions also pin the str::cmp ascending sort (rows a<z, cols x<y)
        // and the missing-cell null repr Scalar::Null(NullKind::NaN).
        let idx: Vec<IndexLabel> = (0..4_i64).map(Into::into).collect();
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                idx.clone(),
                vec![
                    Scalar::Utf8("z".into()),
                    Scalar::Utf8("z".into()),
                    Scalar::Utf8("z".into()),
                    Scalar::Utf8("a".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                idx.clone(),
                vec![
                    Scalar::Utf8("x".into()),
                    Scalar::Utf8("x".into()),
                    Scalar::Utf8("y".into()),
                    Scalar::Utf8("x".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                idx,
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(7.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        // Sorted distinct: rows [a, z]; cols ["x", "y"]. Cell (z,y)=5, (a,*)=7
        // only at x, so (a,y) and (z is row1)... rows order a(row1)=7, z(row0).
        let null = Scalar::Null(NullKind::NaN);

        let s = df.pivot_table("val", "row", "col", "sum").unwrap();
        assert_eq!(s.column_order, vec!["x".to_string(), "y".to_string()]);
        assert_eq!(
            s.index.labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("z".into())]
        );
        // row a: x=7, y=missing; row z: x=1+3=4, y=5
        assert_eq!(
            s.columns["x"].values(),
            &[Scalar::Float64(7.0), Scalar::Float64(4.0)]
        );
        assert_eq!(
            s.columns["y"].values(),
            &[null.clone(), Scalar::Float64(5.0)]
        );

        let m = df.pivot_table("val", "row", "col", "mean").unwrap();
        // row z, x: mean(1,3)=2
        assert_eq!(
            m.columns["x"].values(),
            &[Scalar::Float64(7.0), Scalar::Float64(2.0)]
        );
        assert_eq!(
            m.columns["y"].values(),
            &[null.clone(), Scalar::Float64(5.0)]
        );

        let c = df.pivot_table("val", "row", "col", "count").unwrap();
        assert_eq!(
            c.columns["x"].values(),
            &[Scalar::Float64(1.0), Scalar::Float64(2.0)]
        );
        assert_eq!(c.columns["y"].values(), &[null, Scalar::Float64(1.0)]);
    }

    #[test]
    fn pivot_table_aggfunc_kurt_jb7zy() {
        // br-frankenpandas-jb7zy: pivot_table now supports kurt/kurtosis,
        // delegating to fp_types::nankurt (matching the sem/skew wiring).
        let vals = [1.0_f64, 2.0, 2.0, 3.0, 8.0, 1.0];
        let idx: Vec<IndexLabel> = (0..vals.len() as i64).map(Into::into).collect();
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                idx.clone(),
                vec![Scalar::Utf8("r".into()); vals.len()],
            )
            .unwrap(),
            Series::from_values(
                "col",
                idx.clone(),
                vec![Scalar::Utf8("c".into()); vals.len()],
            )
            .unwrap(),
            Series::from_values(
                "val",
                idx,
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap(),
        ])
        .unwrap();

        let expected =
            fp_types::nankurt(&vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>())
                .to_f64()
                .unwrap();

        // Single (row=r, col=c) cell holds all six values.
        for name in ["kurt", "kurtosis"] {
            let pivoted = df.pivot_table("val", "row", "col", name).unwrap();
            let got = match &pivoted.columns["c"].values()[0] {
                Scalar::Float64(v) => *v,
                // Non-Float64 is unexpected; NaN sentinel fails the assert below.
                _ => f64::NAN,
            };
            assert!(
                (got - expected).abs() < 1e-9,
                "pivot {name}: got {got}, expected {expected}"
            );
        }
    }

    #[test]
    fn dataframe_pivot_table_mean() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df.pivot_table("val", "row", "col", "mean").unwrap();
        // r1, c1 → mean(10, 20) = 15.0; r1, c2 → 30.0
        assert_eq!(pivoted.columns["c1"].values()[0], Scalar::Float64(15.0));
        assert_eq!(pivoted.columns["c2"].values()[0], Scalar::Float64(30.0));
    }

