    #[test]
    fn dataframe_pivot_table_std_uses_sample_std() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![
                    0_i64.into(),
                    1_i64.into(),
                    2_i64.into(),
                    3_i64.into(),
                    4_i64.into(),
                    5_i64.into(),
                ],
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![
                    0_i64.into(),
                    1_i64.into(),
                    2_i64.into(),
                    3_i64.into(),
                    4_i64.into(),
                    5_i64.into(),
                ],
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Utf8("c2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![
                    0_i64.into(),
                    1_i64.into(),
                    2_i64.into(),
                    3_i64.into(),
                    4_i64.into(),
                    5_i64.into(),
                ],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(8.0),
                    Scalar::Float64(1.0),
                    Scalar::Float64(3.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df.pivot_table("val", "row", "col", "std").unwrap();
        let r1_c1 = pivoted.columns["c1"].values()[0].to_f64().unwrap();
        let r2_c1 = pivoted.columns["c1"].values()[1].to_f64().unwrap();
        let r2_c2 = pivoted.columns["c2"].values()[1].to_f64().unwrap();
        assert!((r1_c1 - 50.0_f64.sqrt()).abs() < 1e-10);
        assert!((r2_c1 - 8.0_f64.sqrt()).abs() < 1e-10);
        assert!((r2_c2 - 2.0_f64.sqrt()).abs() < 1e-10);
        assert!(pivoted.columns["c2"].values()[0].is_missing());
    }

    fn dataframe_pivot_agg_fixture(vals: Vec<Scalar>) -> DataFrame {
        let rows: Vec<Scalar> = vals
            .iter()
            .enumerate()
            .map(|(i, _)| Scalar::Utf8(if i < 3 { "g1" } else { "g2" }.into()))
            .collect();
        let positions: Vec<IndexLabel> = (0..vals.len() as i64).map(IndexLabel::from).collect();
        DataFrame::from_series(vec![
            Series::from_values("row", positions.clone(), rows).unwrap(),
            Series::from_values(
                "col",
                positions.clone(),
                vec![Scalar::Utf8("c".into()); vals.len()],
            )
            .unwrap(),
            Series::from_values("val", positions, vals).unwrap(),
        ])
        .unwrap()
    }

    #[test]
    fn dataframe_pivot_table_nunique_counts_distinct_values() {
        // g1=[1,2,4] -> 3 distinct; g2=[5,5] -> 1 distinct (live pandas 2.2.3).
        let df = dataframe_pivot_agg_fixture(vec![
            Scalar::Float64(1.0),
            Scalar::Float64(2.0),
            Scalar::Float64(4.0),
            Scalar::Float64(5.0),
            Scalar::Float64(5.0),
        ]);
        let pivoted = df.pivot_table("val", "row", "col", "nunique").unwrap();
        assert_eq!(pivoted.columns["c"].values()[0].to_f64().unwrap(), 3.0);
        assert_eq!(pivoted.columns["c"].values()[1].to_f64().unwrap(), 1.0);
    }

    #[test]
    fn dataframe_pivot_table_sem_matches_pandas() {
        // sem = std(ddof=1)/sqrt(n). g1=[1,2,4] -> 0.8819171036881968;
        // g2=[5,5] -> 0.0 (live pandas 2.2.3).
        let df = dataframe_pivot_agg_fixture(vec![
            Scalar::Float64(1.0),
            Scalar::Float64(2.0),
            Scalar::Float64(4.0),
            Scalar::Float64(5.0),
            Scalar::Float64(5.0),
        ]);
        let pivoted = df.pivot_table("val", "row", "col", "sem").unwrap();
        let g1 = pivoted.columns["c"].values()[0].to_f64().unwrap();
        let g2 = pivoted.columns["c"].values()[1].to_f64().unwrap();
        assert!((g1 - 0.881_917_103_688_196_8).abs() < 1e-12);
        assert_eq!(g2, 0.0);
    }

    #[test]
    fn dataframe_pivot_table_skew_matches_pandas() {
        // Adjusted Fisher-Pearson G1; scale/location invariant, so [1,2,4] and
        // [10,20,40] both give 0.9352195295828247 (live pandas 2.2.3). Both
        // groups kept at n>=3 so neither row is dropped by pivot dropna.
        let df = dataframe_pivot_agg_fixture(vec![
            Scalar::Float64(1.0),
            Scalar::Float64(2.0),
            Scalar::Float64(4.0),
            Scalar::Float64(10.0),
            Scalar::Float64(20.0),
            Scalar::Float64(40.0),
        ]);
        let pivoted = df.pivot_table("val", "row", "col", "skew").unwrap();
        let g1 = pivoted.columns["c"].values()[0].to_f64().unwrap();
        let g2 = pivoted.columns["c"].values()[1].to_f64().unwrap();
        assert!((g1 - 0.935_219_529_582_824_7).abs() < 1e-12);
        assert!((g2 - 0.935_219_529_582_824_7).abs() < 1e-12);
    }

    #[test]
    fn dataframe_pivot_table_missing_cell() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Utf8("r1".into()), Scalar::Utf8("r2".into())],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Utf8("c1".into()), Scalar::Utf8("c2".into())],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Float64(5.0), Scalar::Float64(10.0)],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df.pivot_table("val", "row", "col", "sum").unwrap();
        // r1 has c1 but not c2; r2 has c2 but not c1
        assert_eq!(pivoted.columns["c1"].values()[0], Scalar::Float64(5.0));
        assert!(pivoted.columns["c2"].values()[0].is_missing()); // missing cell → NaN
        assert!(pivoted.columns["c1"].values()[1].is_missing()); // missing cell → NaN
        assert_eq!(pivoted.columns["c2"].values()[1], Scalar::Float64(10.0));
    }

