    #[test]
    fn dataframe_pivot_table_with_dropna_false_keeps_missing_key_buckets() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Null(NullKind::Null),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r1".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Null(NullKind::Null),
                    Scalar::Null(NullKind::Null),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df
            .pivot_table_with_dropna("val", "row", "col", "sum", false)
            .unwrap();

        // Verified live pandas 2.2.3 (br-frankenpandas-8m6ay + s3x7k): the
        // missing row key is a real Null(NaN) label sorted LAST (pivot_table
        // sort=True default), the missing column key renders "NaN" (pandas'
        // display form in FP's string-keyed column model), and the cell
        // matrix matches pandas' table for rows [r1, r2, NaN]:
        //   c1  = [1.0, NaN, 2.0],  NaN-col = [4.0, 3.0, NaN].
        assert_eq!(
            pivoted.index.labels(),
            &[
                IndexLabel::Utf8("r1".into()),
                IndexLabel::Utf8("r2".into()),
                IndexLabel::Null(NullKind::NaN),
            ]
        );
        assert_eq!(
            pivoted.column_order,
            vec!["c1".to_owned(), "NaN".to_owned()]
        );
        assert_eq!(
            pivoted.columns["c1"].values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
            ]
        );
        assert_eq!(
            pivoted.columns["NaN"].values(),
            &[
                Scalar::Float64(4.0),
                Scalar::Float64(3.0),
                Scalar::Null(NullKind::NaN),
            ]
        );
    }

    #[test]
    fn dataframe_pivot_table_aggfunc_dict_per_column_agg() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "region",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("E".into()),
                    Scalar::Utf8("E".into()),
                    Scalar::Utf8("W".into()),
                    Scalar::Utf8("W".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "quarter",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("Q1".into()),
                    Scalar::Utf8("Q2".into()),
                    Scalar::Utf8("Q1".into()),
                    Scalar::Utf8("Q2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "amount",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                    Scalar::Float64(40.0),
                ],
            )
            .unwrap(),
            Series::from_values(
                "qty",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pivoted = df
            .pivot_table_aggfunc_dict(&[("amount", "sum"), ("qty", "mean")], "region", "quarter")
            .unwrap();

        // Columns: amount_Q1, amount_Q2, qty_Q1, qty_Q2 (in call order).
        assert_eq!(
            pivoted.column_order,
            vec![
                "amount_Q1".to_string(),
                "amount_Q2".to_string(),
                "qty_Q1".to_string(),
                "qty_Q2".to_string(),
            ]
        );
        // amount is summed
        assert_eq!(
            pivoted.columns["amount_Q1"].values()[0],
            Scalar::Float64(10.0)
        );
        assert_eq!(
            pivoted.columns["amount_Q2"].values()[0],
            Scalar::Float64(20.0)
        );
        assert_eq!(
            pivoted.columns["amount_Q1"].values()[1],
            Scalar::Float64(30.0)
        );
        assert_eq!(
            pivoted.columns["amount_Q2"].values()[1],
            Scalar::Float64(40.0)
        );
        // qty is averaged
        assert_eq!(pivoted.columns["qty_Q1"].values()[0], Scalar::Float64(1.0));
        assert_eq!(pivoted.columns["qty_Q2"].values()[0], Scalar::Float64(3.0));
        assert_eq!(pivoted.columns["qty_Q1"].values()[1], Scalar::Float64(2.0));
        assert_eq!(pivoted.columns["qty_Q2"].values()[1], Scalar::Float64(4.0));
    }

    #[test]
    fn dataframe_pivot_table_aggfunc_dict_rejects_empty() {
        let df = DataFrame::from_series(vec![
            Series::from_values("r", vec![0_i64.into()], vec![Scalar::Utf8("a".into())]).unwrap(),
            Series::from_values("c", vec![0_i64.into()], vec![Scalar::Utf8("x".into())]).unwrap(),
            Series::from_values("v", vec![0_i64.into()], vec![Scalar::Float64(1.0)]).unwrap(),
        ])
        .unwrap();

        let err = df.pivot_table_aggfunc_dict(&[], "r", "c").unwrap_err();
        assert!(matches!(err, FrameError::CompatibilityRejected(_)));
    }

