    #[test]
    fn dataframe_pivot_table_with_margins_sum() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "row",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r1".into()),
                    Scalar::Utf8("r2".into()),
                    Scalar::Utf8("r2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "col",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                    Scalar::Utf8("c1".into()),
                    Scalar::Utf8("c2".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let pt = df
            .pivot_table_with_margins("val", "row", "col", "sum", true)
            .unwrap();

        // Should have 3 rows (r1, r2, All) and 3 columns (c1, c2, All)
        assert_eq!(pt.len(), 3);
        assert_eq!(pt.column_names().len(), 3);

        // r1: c1=1, c2=2, All=3
        assert_eq!(pt.columns["c1"].values()[0], Scalar::Float64(1.0));
        assert_eq!(pt.columns["c2"].values()[0], Scalar::Float64(2.0));
        assert_eq!(pt.columns["All"].values()[0], Scalar::Float64(3.0));

        // r2: c1=3, c2=4, All=7
        assert_eq!(pt.columns["c1"].values()[1], Scalar::Float64(3.0));
        assert_eq!(pt.columns["c2"].values()[1], Scalar::Float64(4.0));
        assert_eq!(pt.columns["All"].values()[1], Scalar::Float64(7.0));

        // All row: c1=4, c2=6, All=10
        assert_eq!(pt.columns["c1"].values()[2], Scalar::Float64(4.0));
        assert_eq!(pt.columns["c2"].values()[2], Scalar::Float64(6.0));
        assert_eq!(pt.columns["All"].values()[2], Scalar::Float64(10.0));

        // Index should end with "All"
        assert_eq!(pt.index().labels()[2], IndexLabel::Utf8("All".to_owned()));
    }

    #[test]
    fn dataframe_pivot_table_sparse_int_sum_margin_stays_int64_ro5dy() {
        // pandas 2.2.3 widens the sparse A/B body columns for their invented
        // gaps, but the complete sum margin column remains int64.
        let df = DataFrame::from_dict(
            &["region", "product", "sales"],
            vec![
                (
                    "region",
                    vec![
                        Scalar::Utf8("east".into()),
                        Scalar::Utf8("east".into()),
                        Scalar::Utf8("west".into()),
                    ],
                ),
                (
                    "product",
                    vec![
                        Scalar::Utf8("A".into()),
                        Scalar::Utf8("B".into()),
                        Scalar::Utf8("A".into()),
                    ],
                ),
                (
                    "sales",
                    vec![Scalar::Int64(13), Scalar::Int64(5), Scalar::Int64(7)],
                ),
            ],
        )
        .expect("frame");

        let pivot = df
            .pivot_table_with_margins("sales", "region", "product", "sum", true)
            .expect("pivot with margins");

        assert_eq!(pivot.column("A").expect("A").dtype(), DType::Float64);
        assert_eq!(pivot.column("B").expect("B").dtype(), DType::Float64);
        assert_eq!(
            pivot.column("All").expect("All").dtype(),
            DType::Int64,
            "the all-present sum margin must not inherit the body gap's promotion"
        );
        assert_eq!(
            pivot.column("All").expect("All").values(),
            &[Scalar::Int64(18), Scalar::Int64(7), Scalar::Int64(25)]
        );
    }

