    #[test]
    fn series_corr_large_offset_no_cancellation_r3sfc() {
        // br-frankenpandas-r3sfc follow-up: large-magnitude near-equal data where
        // the one-pass `sum_x2 - n*mean_x^2` catastrophically cancels var_x to
        // 0.0 (-> NaN corr). The two-pass mean-centered form is stable and
        // matches pandas exactly: pd.Series(x).corr(pd.Series(y)) == -1.0.
        let a = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1e9 + 1.0),
                Scalar::Float64(1e9 + 2.0),
                Scalar::Float64(1e9 + 3.0),
                Scalar::Float64(1e9 + 1.0),
            ],
        )
        .unwrap();
        let b = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(5e9 - 1.0),
                Scalar::Float64(5e9 - 2.0),
                Scalar::Float64(5e9 - 3.0),
                Scalar::Float64(5e9 - 1.0),
            ],
        )
        .unwrap();
        let r = a.corr(&b).unwrap();
        assert!(
            (r - (-1.0)).abs() < 1e-10,
            "two-pass corr must be -1.0 (pandas parity), got {r}"
        );
    }

    #[test]
    fn series_cov_basic() {
        let a = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let b = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(2.0),
                Scalar::Float64(4.0),
                Scalar::Float64(6.0),
            ],
        )
        .unwrap();

        let c = a.cov_with(&b).unwrap();
        // cov(a,b) = sum((ai-mean_a)*(bi-mean_b))/(n-1) = ((-1)*(-2)+0*0+1*2)/2 = 4/2 = 2
        assert!((c - 2.0).abs() < 1e-10);
    }

    #[test]
    fn series_cov_self_equals_var_large_near_equal_r3sfc() {
        // br-frankenpandas-r3sfc: the one-pass (sum_xy - n*mean_x*mean_y)/(n-1)
        // form catastrophically cancels for large-magnitude near-equal data,
        // so cov(s, s) diverged from var(s) (which is two-pass). With the
        // two-pass mean-centered cross-sum, cov(s, s) == var(s) to f64 ULPs.
        let labels = vec![0_i64.into(), 1_i64.into()];
        let s = Series::from_values(
            "s",
            labels,
            vec![
                Scalar::Float64(-809259.015408116),
                Scalar::Float64(-808751.0970670774),
            ],
        )
        .unwrap();

        let cov_ss = s.cov_with(&s).unwrap();
        let var_s = match s.var().unwrap() {
            Scalar::Float64(v) => v,
            other => panic!("expected Float64 var, got {other:?}"),
        };
        // Was ~1e-9 relative apart under one-pass; now within tight tolerance.
        let rel = (cov_ss - var_s).abs() / var_s.abs().max(1.0);
        assert!(
            rel < 1e-12,
            "cov(s,s)={cov_ss} should equal var(s)={var_s} (rel={rel})"
        );
    }

