    #[test]
    fn dataframe_topk_ties_preserve_input_order_90qpl() {
        let idx: Vec<IndexLabel> = (0..6_i64).map(Into::into).collect();
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "hi",
                idx.clone(),
                [5_i64, 7, 7, 6, 7, 4]
                    .into_iter()
                    .map(Scalar::Int64)
                    .collect(),
            )
            .unwrap(),
            Series::from_values(
                "lo",
                idx.clone(),
                [3_i64, 1, 1, 2, 1, 4]
                    .into_iter()
                    .map(Scalar::Int64)
                    .collect(),
            )
            .unwrap(),
            Series::from_values(
                "row",
                idx,
                (0_i64..6).map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap(),
        ])
        .unwrap();

        let largest = df.nlargest(2, "hi").unwrap();
        let largest_rows: Vec<i64> = largest
            .column("row")
            .unwrap()
            .values()
            .iter()
            .map(|value| match value {
                Scalar::Int64(value) => *value,
                _ => panic!("row should stay Int64"),
            })
            .collect();
        assert_eq!(largest_rows, vec![1, 2]);

        let smallest = df.nsmallest(2, "lo").unwrap();
        let smallest_rows: Vec<i64> = smallest
            .column("row")
            .unwrap()
            .values()
            .iter()
            .map(|value| match value {
                Scalar::Int64(value) => *value,
                _ => panic!("row should stay Int64"),
            })
            .collect();
        assert_eq!(smallest_rows, vec![1, 2]);
    }

