    #[test]
    fn dataframe_groupby_bool_key_labels_are_pandas_style() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "grp",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![Scalar::Bool(true), Scalar::Bool(false), Scalar::Bool(true)],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let result = df.groupby(&["grp"]).unwrap().sum().unwrap();
        // br-frankenpandas-9m9zf: bool group keys stay TYPED. This asserted
        // Utf8("False")/Utf8("True"), and the test NAME claimed that was
        // pandas-style. MEASURED, live pandas 2.2.3:
        //   df.groupby("k").sum().index -> [False, True]
        //   index dtype                 -> bool
        //   [type(x).__name__ for x in index] -> ['bool', 'bool']
        // so the strings were never pandas' answer. sort=True (the default)
        // still gives sorted key order, False before True.
        assert_eq!(
            result.index().labels(),
            &[IndexLabel::Bool(false), IndexLabel::Bool(true)]
        );
        assert_eq!(result.columns["val"].values()[0], Scalar::Float64(2.0));
        assert_eq!(result.columns["val"].values()[1], Scalar::Float64(4.0));
    }

    #[test]
    fn dataframe_groupby_sort_false_preserves_first_seen_order() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "grp",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("b".into()),
                    Scalar::Utf8("a".into()),
                    Scalar::Utf8("b".into()),
                    Scalar::Utf8("a".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                    Scalar::Float64(40.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        // sort=False: groups in first-seen order (b first, then a)
        let unsorted = df
            .groupby_full(&["grp"], true, false)
            .unwrap()
            .sum()
            .unwrap();
        assert_eq!(
            unsorted.index().labels(),
            &[IndexLabel::Utf8("b".into()), IndexLabel::Utf8("a".into())]
        );
        assert_eq!(unsorted.columns["val"].values()[0], Scalar::Float64(40.0)); // b: 10+30
        assert_eq!(unsorted.columns["val"].values()[1], Scalar::Float64(60.0)); // a: 20+40

        // sort=True (default): groups sorted by key
        let sorted = df.groupby(&["grp"]).unwrap().sum().unwrap();
        assert_eq!(
            sorted.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("b".into())]
        );
        assert_eq!(sorted.columns["val"].values()[0], Scalar::Float64(60.0)); // a: 20+40
        assert_eq!(sorted.columns["val"].values()[1], Scalar::Float64(40.0)); // b: 10+30
    }

