    #[test]
    fn series_where_mask_conditional_dvxfw_wi1ce() {
        // Differential: where keeps self where cond true (else other); mask is the
        // inverse; where(None) NaN-fills the false slots (br-frankenpandas-wi1ce).
        let mut st: u64 = 0x3f1d_0a2b_4c5d_6e7f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let other = -999i64;
        for iter in 0..1000u32 {
            let n = (next() % 10) as usize + 1;
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 50) as i64).collect();
            let conds: Vec<bool> = (0..n).map(|_| next() % 2 == 0).collect();
            let series = Series::from_values(
                "x",
                idx.clone(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let cond = Series::from_values(
                "c",
                idx,
                conds.iter().map(|&b| Scalar::Bool(b)).collect::<Vec<_>>(),
            )
            .unwrap();

            let w = series.r#where(&cond, Some(&Scalar::Int64(other))).unwrap();
            let m = series.mask(&cond, Some(&Scalar::Int64(other))).unwrap();
            let wn = series.r#where(&cond, None).unwrap();
            for i in 0..n {
                let exp_w = if conds[i] { vals[i] } else { other };
                assert_eq!(
                    w.values()[i],
                    Scalar::Int64(exp_w),
                    "where iter={iter} i={i}"
                );
                let exp_m = if conds[i] { other } else { vals[i] };
                assert_eq!(
                    m.values()[i],
                    Scalar::Int64(exp_m),
                    "mask iter={iter} i={i}"
                );
                if conds[i] {
                    let g = match &wn.values()[i] {
                        Scalar::Int64(x) => *x as f64,
                        Scalar::Float64(x) => *x,
                        _ => f64::NAN,
                    };
                    assert!(
                        (g - vals[i] as f64).abs() < 1e-9,
                        "where-none kept iter={iter} i={i}"
                    );
                } else {
                    assert!(
                        wn.values()[i].is_missing(),
                        "where-none NaN iter={iter} i={i}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_add_fill_alignment_qxiah() {
        // Differential (br-frankenpandas-qxiah): add_fill replaces missing alignment
        // slots with fill_value before adding. a=label+100, b=label+1000, fill=0.
        let mut st: u64 = 0xadd0_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let pick = |n: &mut dyn FnMut() -> u32| -> Vec<i64> {
                (0..8i64).filter(|_| n() % 2 == 0).collect()
            };
            let a_labels = pick(&mut next);
            let b_labels = pick(&mut next);
            if a_labels.is_empty() || b_labels.is_empty() {
                continue;
            }
            let mk = |labels: &[i64], base: i64| {
                Series::from_values(
                    "s",
                    labels
                        .iter()
                        .map(|&l| IndexLabel::Int64(l))
                        .collect::<Vec<_>>(),
                    labels
                        .iter()
                        .map(|&l| Scalar::Int64(l + base))
                        .collect::<Vec<_>>(),
                )
                .unwrap()
            };
            let sa = mk(&a_labels, 100);
            let sb = mk(&b_labels, 1000);
            let amap: std::collections::HashMap<i64, i64> =
                a_labels.iter().map(|&l| (l, l + 100)).collect();
            let bmap: std::collections::HashMap<i64, i64> =
                b_labels.iter().map(|&l| (l, l + 1000)).collect();
            let union: std::collections::BTreeSet<i64> =
                a_labels.iter().chain(b_labels.iter()).copied().collect();

            let r = sa.add_fill(&sb, 0.0).unwrap();
            let rl = r.index().labels();
            assert_eq!(rl.len(), union.len(), "union iter={iter}");
            for i in 0..rl.len() {
                let label = match &rl[i] {
                    IndexLabel::Int64(k) => *k,
                    _ => i64::MIN,
                };
                let av = amap.get(&label).copied().unwrap_or(0) as f64;
                let bv = bmap.get(&label).copied().unwrap_or(0) as f64;
                let got = match &r.values()[i] {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                };
                assert!(
                    (got - (av + bv)).abs() < 1e-9,
                    "add_fill iter={iter} label={label}"
                );
            }
        }
    }

    #[test]
    fn series_add_index_alignment_dvxfw() {
        // Differential: Series.add aligns on index union, NaN-filling labels that
        // are not in both (br-frankenpandas-dvxfw). Order-independent oracle.
        let mut st: u64 = 0xa11a_0d2e_3f40_5162;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            // Distinct unique label subsets of 0..8.
            let pick = |n: &mut dyn FnMut() -> u32| -> Vec<i64> {
                (0..8i64).filter(|_| n() % 2 == 0).collect()
            };
            let a_labels = pick(&mut next);
            let b_labels = pick(&mut next);
            if a_labels.is_empty() || b_labels.is_empty() {
                continue;
            }
            let mk = |labels: &[i64], base: i64| {
                let vals: Vec<i64> = labels.iter().map(|&l| l + base).collect();
                Series::from_values(
                    "s",
                    labels
                        .iter()
                        .map(|&l| IndexLabel::Int64(l))
                        .collect::<Vec<_>>(),
                    vals.into_iter().map(Scalar::Int64).collect::<Vec<_>>(),
                )
                .unwrap()
            };
            let sa = mk(&a_labels, 100);
            let sb = mk(&b_labels, 1000);
            let a_map: std::collections::HashMap<i64, i64> =
                a_labels.iter().map(|&l| (l, l + 100)).collect();
            let b_map: std::collections::HashMap<i64, i64> =
                b_labels.iter().map(|&l| (l, l + 1000)).collect();
            let union: std::collections::BTreeSet<i64> =
                a_labels.iter().chain(b_labels.iter()).copied().collect();

            let r = sa.add(&sb).unwrap();
            let rl = r.index().labels();
            let rv = r.values();
            assert_eq!(rl.len(), union.len(), "union size iter={iter}");
            for i in 0..rl.len() {
                let label = match &rl[i] {
                    IndexLabel::Int64(k) => *k,
                    _ => i64::MIN,
                };
                assert!(union.contains(&label), "label {label} in union iter={iter}");
                let both = a_map.get(&label).zip(b_map.get(&label));
                match both {
                    Some((&av, &bv)) => {
                        let got = match &rv[i] {
                            Scalar::Int64(x) => *x as f64,
                            Scalar::Float64(x) => *x,
                            _ => f64::NAN,
                        };
                        assert!(
                            (got - (av + bv) as f64).abs() < 1e-9,
                            "sum at {label} iter={iter}"
                        );
                    }
                    None => assert!(rv[i].is_missing(), "missing at {label} iter={iter}"),
                }
            }
        }
    }

    #[test]
    fn series_mode_matches_tally_oracle_lyf0i() {
        // Differential vs BTreeMap tally oracle (br-frankenpandas-lyf0i): mode is
        // every value with the max frequency, sorted ascending. Seeded LCG.
        let mut st: u64 = 0x70de_0a1b_2c3d_4e5f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1200u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            let mut tally: std::collections::BTreeMap<i64, usize> =
                std::collections::BTreeMap::new();
            for &v in &vals {
                *tally.entry(v).or_default() += 1;
            }
            let maxc = tally.values().copied().max().unwrap();
            // BTreeMap iterates ascending, so this is already sorted.
            let exp: Vec<i64> = tally
                .iter()
                .filter_map(|(k, c)| if *c == maxc { Some(*k) } else { None })
                .collect();

            let got: Vec<i64> = series
                .mode()
                .unwrap()
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect();
            assert_eq!(got, exp, "mode iter={iter} vals={vals:?}");
        }
    }

    #[test]
    fn series_dt_calendar_known_answer_akbze() {
        // Known-answer (br-frankenpandas-akbze): dt calendar properties on
        // hand-verified dates. No mocks.
        let day_ns = 86_400i64 * 1_000_000_000;
        let d0 = 10_957 * day_ns; // 2000-01-01 (Saturday)
        let ts = [
            d0,                // 2000-01-01 Sat
            d0 + 60 * day_ns,  // 2000-03-01 Wed (leap year)
            d0 + 91 * day_ns,  // 2000-04-01 Sat
            d0 + 366 * day_ns, // 2001-01-01 Mon
        ];
        let series = Series::from_values(
            "t",
            (0..ts.len() as i64).map(Into::into).collect::<Vec<_>>(),
            ts.iter()
                .map(|&v| Scalar::Datetime64(v))
                .collect::<Vec<_>>(),
        )
        .unwrap();
        let coli = |s: Series| -> Vec<i64> {
            s.values()
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect()
        };
        let colb = |s: Series| -> Vec<bool> {
            s.values()
                .iter()
                .map(|v| matches!(v, Scalar::Bool(true)))
                .collect()
        };
        assert_eq!(
            coli(series.dt().quarter().unwrap()),
            vec![1, 1, 2, 1],
            "quarter"
        );
        assert_eq!(
            coli(series.dt().dayofweek().unwrap()),
            vec![5, 2, 5, 0],
            "dayofweek Mon=0"
        );
        assert_eq!(
            coli(series.dt().days_in_month().unwrap()),
            vec![31, 31, 30, 31],
            "days_in_month"
        );
        assert_eq!(
            coli(series.dt().dayofyear().unwrap()),
            vec![1, 61, 92, 1],
            "dayofyear"
        );
        assert_eq!(
            colb(series.dt().is_leap_year().unwrap()),
            vec![true, true, true, false],
            "is_leap_year"
        );
    }

    #[test]
    fn series_dt_components_known_answer_qg1ee() {
        // Known-answer datetime decomposition (br-frankenpandas-qg1ee), no mocks.
        let day_ns = 86_400i64 * 1_000_000_000;
        let t_2000 = 10_957 * day_ns; // 1970-01-01 -> 2000-01-01 is 10957 days
        let t_full = t_2000 + (13 * 3600 + 45 * 60 + 30) * 1_000_000_000; // 13:45:30
        let t_mar = t_2000 + 60 * day_ns; // 2000-03-01 (Jan 31 + Feb 29, leap year)
        let ts = [0i64, t_2000, t_full, t_mar];
        let series = Series::from_values(
            "t",
            (0..ts.len() as i64).map(Into::into).collect::<Vec<_>>(),
            ts.iter()
                .map(|&v| Scalar::Datetime64(v))
                .collect::<Vec<_>>(),
        )
        .unwrap();

        let col = |s: Series| -> Vec<i64> {
            s.values()
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect()
        };
        assert_eq!(
            col(series.dt().year().unwrap()),
            vec![1970, 2000, 2000, 2000],
            "year"
        );
        assert_eq!(col(series.dt().month().unwrap()), vec![1, 1, 1, 3], "month");
        assert_eq!(col(series.dt().day().unwrap()), vec![1, 1, 1, 1], "day");
        assert_eq!(col(series.dt().hour().unwrap()), vec![0, 0, 13, 0], "hour");
        assert_eq!(
            col(series.dt().minute().unwrap()),
            vec![0, 0, 45, 0],
            "minute"
        );
        assert_eq!(
            col(series.dt().second().unwrap()),
            vec![0, 0, 30, 0],
            "second"
        );
    }

    #[test]
    fn dataframe_sort_values_row_integrity_u24k1() {
        // Differential (br-frankenpandas-u24k1): distinct keys (no tie/stability
        // ambiguity), payload=key*100; sort must preserve the row pairing.
        let mut st: u64 = 0x503a_7c1d_2b3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 9) as usize + 1;
            // Fisher-Yates permutation of 0..n -> distinct keys.
            let mut keys: Vec<i64> = (0..n as i64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                keys.swap(i, j);
            }
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "k",
                    idx.clone(),
                    keys.iter().map(|&k| Scalar::Int64(k)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "p",
                    idx,
                    keys.iter()
                        .map(|&k| Scalar::Int64(k * 100))
                        .collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();

            let asc = df.sort_values("k", true).unwrap();
            for j in 0..n {
                assert_eq!(
                    asc.column("k").unwrap().values()[j],
                    Scalar::Int64(j as i64),
                    "asc k iter={iter} j={j}"
                );
                assert_eq!(
                    asc.column("p").unwrap().values()[j],
                    Scalar::Int64(j as i64 * 100),
                    "asc p iter={iter} j={j}"
                );
            }
            let desc = df.sort_values("k", false).unwrap();
            for j in 0..n {
                let want = (n - 1 - j) as i64;
                assert_eq!(
                    desc.column("k").unwrap().values()[j],
                    Scalar::Int64(want),
                    "desc k iter={iter} j={j}"
                );
                assert_eq!(
                    desc.column("p").unwrap().values()[j],
                    Scalar::Int64(want * 100),
                    "desc p iter={iter} j={j}"
                );
            }
        }
    }

    #[test]
    fn series_corr_cov_invariants_up0hr() {
        // Property test for corr/cov numerical invariants (br-frankenpandas-up0hr).
        // Seeded LCG, no mocks.
        let mut st: u64 = 0xc02f_0b1a_2c3d_4e5f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            let n = (next() % 8) as usize + 2;
            let xs: Vec<f64> = (0..n).map(|_| (next() % 200) as f64 / 7.0 - 14.0).collect();
            let ys: Vec<f64> = (0..n).map(|_| (next() % 200) as f64 / 5.0 - 20.0).collect();
            let mk = |v: &[f64]| {
                Series::from_values(
                    "s",
                    (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                    v.iter().map(|&x| Scalar::Float64(x)).collect::<Vec<_>>(),
                )
                .unwrap()
            };
            let sx = mk(&xs);
            let sy = mk(&ys);

            // Two-pass variance oracle (ddof=1).
            let var = |v: &[f64]| {
                let m = v.iter().sum::<f64>() / v.len() as f64;
                v.iter().map(|x| (x - m).powi(2)).sum::<f64>() / (v.len() as f64 - 1.0)
            };
            let var_x = var(&xs);

            let cov_xy = sx.cov(&sy).unwrap();
            let cov_yx = sy.cov(&sx).unwrap();
            assert!((cov_xy - cov_yx).abs() < 1e-9, "cov symmetry iter={iter}");
            let cov_xx = sx.cov(&sx).unwrap();
            assert!(
                (cov_xx - var_x).abs() < 1e-7,
                "cov(x,x)==var(x) iter={iter}: {cov_xx} vs {var_x}"
            );

            let corr_xy = sx.corr(&sy).unwrap();
            let corr_yx = sy.corr(&sx).unwrap();
            assert!(
                (corr_xy - corr_yx).abs() < 1e-9,
                "corr symmetry iter={iter}"
            );
            // |corr| <= 1 (allow tiny fp slack), when defined.
            if corr_xy.is_finite() {
                assert!(
                    corr_xy.abs() <= 1.0 + 1e-9,
                    "corr bound iter={iter}: {corr_xy}"
                );
            }
            // Self-correlation is 1 for non-constant x.
            if var_x > 1e-9 {
                let corr_xx = sx.corr(&sx).unwrap();
                assert!(
                    (corr_xx - 1.0).abs() < 1e-9,
                    "corr(x,x)==1 iter={iter}: {corr_xx}"
                );
            }
        }
    }

    #[test]
    fn series_clip_nan_passthrough_swap_qbr8j() {
        // Differential (br-frankenpandas-qbr8j): clip leaves NaN missing and clamps
        // finite values to [min(lo,hi), max(lo,hi)] (pandas reversed-bounds swap).
        let mut st: u64 = 0xc11b_5a4e_2b3c_4d5e;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 10) as usize + 1;
            let vals: Vec<f64> = (0..n)
                .map(|_| {
                    if next() % 4 == 0 {
                        f64::NAN
                    } else {
                        (next() % 200) as f64 / 10.0 - 10.0
                    }
                })
                .collect();
            let lo = (next() % 100) as f64 / 10.0 - 5.0;
            let hi = (next() % 100) as f64 / 10.0 - 5.0;
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let out = series.clip(Some(lo), Some(hi)).unwrap();
            let (elo, ehi) = if lo > hi { (hi, lo) } else { (lo, hi) };
            for i in 0..n {
                if vals[i].is_nan() {
                    assert!(out.values()[i].is_missing(), "clip NaN iter={iter} i={i}");
                } else {
                    let exp = vals[i].max(elo).min(ehi);
                    let got = match &out.values()[i] {
                        Scalar::Float64(x) => *x,
                        Scalar::Int64(x) => *x as f64,
                        _ => f64::NAN,
                    };
                    assert!(
                        (got - exp).abs() < 1e-9,
                        "clip iter={iter} i={i} v={} lo={lo} hi={hi}",
                        vals[i]
                    );
                }
            }
        }
    }

    #[test]
    fn series_idxmin_idxmax_skip_nan_sgalg() {
        // Differential (br-frankenpandas-sgalg): idxmin/idxmax skip NaN and return
        // the index LABEL of the min/max non-NaN value. Distinct values, offset
        // labels. Seeded LCG, no mocks.
        let mut st: u64 = 0x1d20_3a4b_5c6d_7e8f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 1;
            let mut pool: Vec<f64> = (0..n as i64).map(|i| i as f64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                pool.swap(i, j);
            }
            let vals: Vec<f64> = pool
                .iter()
                .map(|&v| if next() % 3 == 0 { f64::NAN } else { v })
                .collect();
            // Offset labels so label != position.
            let labels: Vec<i64> = (0..n as i64).map(|i| i * 10 + 5).collect();
            let series = Series::from_values(
                "x",
                labels
                    .iter()
                    .map(|&l| IndexLabel::Int64(l))
                    .collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            // Oracle over non-NaN positions (first occurrence of min/max).
            let finite_pos: Vec<usize> = (0..n).filter(|&i| !vals[i].is_nan()).collect();
            if finite_pos.is_empty() {
                continue;
            }
            let min_pos = *finite_pos
                .iter()
                .min_by(|&&a, &&b| vals[a].partial_cmp(&vals[b]).unwrap())
                .unwrap();
            let max_pos = *finite_pos
                .iter()
                .max_by(|&&a, &&b| vals[a].partial_cmp(&vals[b]).unwrap())
                .unwrap();
            assert_eq!(
                series.idxmin().unwrap(),
                IndexLabel::Int64(labels[min_pos]),
                "idxmin iter={iter} vals={vals:?}"
            );
            assert_eq!(
                series.idxmax().unwrap(),
                IndexLabel::Int64(labels[max_pos]),
                "idxmax iter={iter} vals={vals:?}"
            );
        }
    }

    #[test]
    fn series_rank_keep_nan_handling_1errg() {
        // Differential (br-frankenpandas-1errg): rank(min, asc, keep) gives NaN
        // ranks to NaN positions and ranks non-NaN by (count-strictly-less)+1.
        // Distinct values (no ties). Seeded LCG, no mocks.
        let mut st: u64 = 0x4a11_e7c0_2b3d_4e5f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 1;
            let mut pool: Vec<f64> = (0..n as i64).map(|i| i as f64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                pool.swap(i, j);
            }
            let vals: Vec<f64> = pool
                .iter()
                .map(|&v| if next() % 3 == 0 { f64::NAN } else { v })
                .collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let finite: Vec<f64> = vals.iter().copied().filter(|v| !v.is_nan()).collect();
            let r = series.rank("min", true, "keep").unwrap();
            for i in 0..n {
                if vals[i].is_nan() {
                    assert!(
                        r.values()[i].is_missing(),
                        "rank NaN-keep iter={iter} i={i}"
                    );
                } else {
                    let c_less = finite.iter().filter(|&&v| v < vals[i]).count();
                    let got = match &r.values()[i] {
                        Scalar::Float64(x) => *x,
                        Scalar::Int64(x) => *x as f64,
                        _ => f64::NAN,
                    };
                    assert!(
                        (got - (c_less + 1) as f64).abs() < 1e-9,
                        "rank iter={iter} i={i}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_nlargest_nsmallest_exclude_nan_ovpm9() {
        // Differential (br-frankenpandas-ovpm9): nlargest/nsmallest drop NaN and
        // return the top/bottom-n of the finite values. Distinct values (no ties).
        let mut st: u64 = 0x0a16_e57a_2b3c_4d5e;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 1;
            // Distinct values 0..n, shuffled, some replaced by NaN.
            let mut pool: Vec<f64> = (0..n as i64).map(|i| i as f64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                pool.swap(i, j);
            }
            let vals: Vec<f64> = pool
                .iter()
                .map(|&v| if next() % 3 == 0 { f64::NAN } else { v })
                .collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let finite: Vec<f64> = vals.iter().copied().filter(|v| !v.is_nan()).collect();
            let mut desc = finite.clone();
            desc.sort_by(|a, b| b.partial_cmp(a).unwrap());
            let mut asc = finite.clone();
            asc.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let as_f = |s: &[Scalar]| -> Vec<f64> {
                s.iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => *x,
                        Scalar::Int64(x) => *x as f64,
                        _ => f64::NAN,
                    })
                    .collect()
            };
            for k in [0usize, 1, 2, finite.len(), finite.len() + 2] {
                let m = k.min(finite.len());
                assert_eq!(
                    as_f(series.nlargest(k).unwrap().values()),
                    desc[..m].to_vec(),
                    "nlargest iter={iter} k={k}"
                );
                assert_eq!(
                    as_f(series.nsmallest(k).unwrap().values()),
                    asc[..m].to_vec(),
                    "nsmallest iter={iter} k={k}"
                );
            }
        }
    }

    #[test]
    fn series_value_counts_excludes_nan_09mlo() {
        // Guard (br-frankenpandas-09mlo): value_counts() default drops NaN, so total
        // counts == non-NaN count and label count == distinct non-NaN count.
        let mut st: u64 = 0x09c0_5a1b_2c3d_4e5f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            let n = (next() % 14) as usize + 1;
            let vals: Vec<f64> = (0..n)
                .map(|_| {
                    if next() % 3 == 0 {
                        f64::NAN
                    } else {
                        (next() % 4) as f64
                    }
                })
                .collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let vc = series.value_counts().unwrap();
            let total: i64 = vc
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Int64(c) => *c,
                    _ => 0,
                })
                .sum();
            let non_nan = vals.iter().filter(|v| !v.is_nan()).count() as i64;
            assert_eq!(
                total, non_nan,
                "value_counts total iter={iter} vals={vals:?}"
            );
            // Distinct non-NaN values (bit-keyed).
            let distinct: std::collections::HashSet<u64> = vals
                .iter()
                .filter(|v| !v.is_nan())
                .map(|v| v.to_bits())
                .collect();
            assert_eq!(
                vc.index().labels().len(),
                distinct.len(),
                "label count iter={iter}"
            );
        }
    }

    #[test]
    fn dataframe_nlargest_row_integrity_r5k8q() {
        // Differential (br-frankenpandas-r5k8q): nlargest(n, col) returns the n rows
        // with the largest key (desc), payload preserved. Distinct keys. Seeded LCG.
        let mut st: u64 = 0x4e1a_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let geti = |c: &[Scalar]| -> Vec<i64> {
            c.iter()
                .map(|s| match s {
                    Scalar::Int64(v) => *v,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..600u32 {
            let len = (next() % 8) as usize + 1;
            let mut keys: Vec<i64> = (0..len as i64).collect();
            for i in (1..len).rev() {
                let j = (next() as usize) % (i + 1);
                keys.swap(i, j);
            }
            let idx: Vec<IndexLabel> = (0..len as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "k",
                    idx.clone(),
                    keys.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "p",
                    idx,
                    keys.iter()
                        .map(|&v| Scalar::Int64(v * 10))
                        .collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();
            for n in [1usize, 2, len] {
                let k = n.min(len);
                let top = df.nlargest(n, "k").unwrap();
                let exp_k: Vec<i64> = (0..k).map(|j| (len - 1 - j) as i64).collect();
                let exp_p: Vec<i64> = exp_k.iter().map(|&v| v * 10).collect();
                assert_eq!(
                    geti(top.column("k").unwrap().values()),
                    exp_k,
                    "k iter={iter} n={n}"
                );
                assert_eq!(
                    geti(top.column("p").unwrap().values()),
                    exp_p,
                    "p iter={iter} n={n}"
                );
            }
        }
    }

    #[test]
    fn dataframe_clip_all_cells_f97xi() {
        // Differential (br-frankenpandas-f97xi): DataFrame.clip clamps every cell
        // to [lo,hi] per column (Series-level was e601i). Seeded LCG, no mocks.
        let mut st: u64 = 0xc11d_0f1e_2b3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Int64(x) => *x as f64,
                Scalar::Float64(x) => *x,
                _ => f64::NAN,
            }
        };
        for iter in 0..600u32 {
            let n = (next() % 8) as usize + 1;
            let a: Vec<i64> = (0..n).map(|_| (next() % 21) as i64 - 10).collect();
            let b: Vec<i64> = (0..n).map(|_| (next() % 21) as i64 - 10).collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "a",
                    idx.clone(),
                    a.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "b",
                    idx,
                    b.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();
            let (lo, hi) = (-3.0_f64, 4.0_f64);
            let c = df.clip(Some(lo), Some(hi)).unwrap();
            for (name, src) in [("a", &a), ("b", &b)] {
                for i in 0..n {
                    let exp = (src[i] as f64).max(lo).min(hi);
                    assert!(
                        (num(&c.column(name).unwrap().values()[i]) - exp).abs() < 1e-9,
                        "clip {name} iter={iter} i={i}"
                    );
                }
            }
        }
    }

