    #[test]
    fn series_reindex_nan_fill_tb9xg() {
        // Differential (br-frankenpandas-tb9xg): reindex maps each new label to the
        // original value if present, else missing. value=label*10. Seeded LCG, no mocks.
        let mut st: u64 = 0x4e1d_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let orig: Vec<i64> = (0..8i64).filter(|_| next() % 2 == 0).collect();
            if orig.is_empty() {
                continue;
            }
            let present: std::collections::HashSet<i64> = orig.iter().copied().collect();
            let series = Series::from_values(
                "x",
                orig.iter()
                    .map(|&l| IndexLabel::Int64(l))
                    .collect::<Vec<_>>(),
                orig.iter()
                    .map(|&l| Scalar::Int64(l * 10))
                    .collect::<Vec<_>>(),
            )
            .unwrap();
            let q = (next() % 8) as usize + 1;
            let new_labels: Vec<i64> = (0..q).map(|_| (next() % 10) as i64).collect();
            let r = series
                .reindex(new_labels.iter().map(|&l| IndexLabel::Int64(l)).collect())
                .unwrap();
            assert_eq!(r.len(), new_labels.len(), "reindex len iter={iter}");
            for (j, &nl) in new_labels.iter().enumerate() {
                if present.contains(&nl) {
                    let got = match &r.values()[j] {
                        Scalar::Int64(v) => *v,
                        Scalar::Float64(v) => *v as i64,
                        _ => i64::MIN,
                    };
                    assert_eq!(got, nl * 10, "reindex present iter={iter} j={j} label={nl}");
                } else {
                    assert!(
                        r.values()[j].is_missing(),
                        "reindex absent iter={iter} j={j} label={nl}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_sort_index_value_integrity_57b4x() {
        // Differential (br-frankenpandas-57b4x): sort_index reorders by label; each
        // value stays paired with its label (value==label*10). Seeded LCG, no mocks.
        let mut st: u64 = 0x5071_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 9) as usize + 1;
            let mut labels: Vec<i64> = (0..n as i64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                labels.swap(i, j);
            }
            let series = Series::from_values(
                "x",
                labels
                    .iter()
                    .map(|&l| IndexLabel::Int64(l))
                    .collect::<Vec<_>>(),
                labels
                    .iter()
                    .map(|&l| Scalar::Int64(l * 10))
                    .collect::<Vec<_>>(),
            )
            .unwrap();

            let asc = series.sort_index(true).unwrap();
            for j in 0..n {
                assert_eq!(
                    asc.index().labels()[j],
                    IndexLabel::Int64(j as i64),
                    "asc label iter={iter} j={j}"
                );
                assert_eq!(
                    asc.values()[j],
                    Scalar::Int64(j as i64 * 10),
                    "asc value iter={iter} j={j}"
                );
            }
            let desc = series.sort_index(false).unwrap();
            for j in 0..n {
                let want = (n - 1 - j) as i64;
                assert_eq!(
                    desc.index().labels()[j],
                    IndexLabel::Int64(want),
                    "desc label iter={iter} j={j}"
                );
                assert_eq!(
                    desc.values()[j],
                    Scalar::Int64(want * 10),
                    "desc value iter={iter} j={j}"
                );
            }
        }
    }

