    #[test]
    fn series_rank_average_sum_invariant_mfkz6() {
        // Invariant (br-frankenpandas-mfkz6): rank(average) sums to n(n+1)/2 even with
        // ties (average preserves total rank mass). Seeded LCG, no mocks.
        let mut st: u64 = 0x4a17_0b2c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 14) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect(); // ties
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let r = series
                .rank_with_pct("average", true, "keep", false)
                .unwrap();
            let sum: f64 = r
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                })
                .sum();
            let expected = (n as f64) * (n as f64 + 1.0) / 2.0;
            assert!(
                (sum - expected).abs() < 1e-6,
                "rank-sum iter={iter}: {sum} vs {expected}"
            );
        }
    }

