    #[test]
    fn series_rank_ties_0ib2i() {
        // Differential (br-frankenpandas-0ib2i): rank tie-handling across
        // average/min/max/dense vs value-count oracle. Forces ties. Seeded LCG.
        let mut st: u64 = 0x4a17_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let getf = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        for iter in 0..800u32 {
            let n = (next() % 10) as usize + 2;
            // Small value domain (0..4) forces many ties.
            let vals: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let r_avg = series
                .rank_with_pct("average", true, "keep", false)
                .unwrap();
            let r_min = series.rank_with_pct("min", true, "keep", false).unwrap();
            let r_max = series.rank_with_pct("max", true, "keep", false).unwrap();
            let r_dense = series.rank_with_pct("dense", true, "keep", false).unwrap();
            let distinct: std::collections::BTreeSet<i64> = vals.iter().copied().collect();
            for i in 0..n {
                let c_less = vals.iter().filter(|&&v| v < vals[i]).count();
                let c_eq = vals.iter().filter(|&&v| v == vals[i]).count();
                let distinct_less = distinct.iter().filter(|&&v| v < vals[i]).count();
                let min = (c_less + 1) as f64;
                let max = (c_less + c_eq) as f64;
                assert!(
                    (getf(&r_min.values()[i]) - min).abs() < 1e-9,
                    "min iter={iter} i={i}"
                );
                assert!(
                    (getf(&r_max.values()[i]) - max).abs() < 1e-9,
                    "max iter={iter} i={i}"
                );
                assert!(
                    (getf(&r_avg.values()[i]) - (min + max) / 2.0).abs() < 1e-9,
                    "avg iter={iter} i={i}"
                );
                assert!(
                    (getf(&r_dense.values()[i]) - (distinct_less + 1) as f64).abs() < 1e-9,
                    "dense iter={iter} i={i}"
                );
            }
        }
    }

