    #[test]
    fn series_rank_pct_89q73() {
        // Differential (br-frankenpandas-89q73): rank(min, pct=true)[i] ==
        // (count strictly less + 1)/n for distinct values. Seeded LCG, no mocks.
        let mut st: u64 = 0x9c70_3a1d_2b4e_5f60;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 1;
            let mut pool: Vec<i64> = (0..n as i64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                pool.swap(i, j);
            }
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                pool.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let r = series.rank_with_pct("min", true, "keep", true).unwrap();
            for i in 0..n {
                let c_less = pool.iter().filter(|&&v| v < pool[i]).count();
                let exp = (c_less + 1) as f64 / n as f64;
                let got = match &r.values()[i] {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                };
                assert!(
                    (got - exp).abs() < 1e-9,
                    "rank pct iter={iter} i={i}: {got} vs {exp}"
                );
            }
        }
    }

