    #[test]
    fn series_replace_multi_substitution_tyose() {
        use std::collections::HashMap;
        // Differential (br-frankenpandas-tyose): replace substitutes matched values,
        // leaves others. Seeded LCG, no mocks.
        let mut st: u64 = 0x4e57_0c1d_2d3e_4f51;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 5) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            // Replace 1->100, 3->300.
            let reps = vec![
                (Scalar::Int64(1), Scalar::Int64(100)),
                (Scalar::Int64(3), Scalar::Int64(300)),
            ];
            let map: HashMap<i64, i64> = [(1, 100), (3, 300)].into_iter().collect();
            let out = series.replace(&reps).unwrap();
            for i in 0..n {
                let got = match &out.values()[i] {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => i64::MIN,
                };
                let exp = map.get(&vals[i]).copied().unwrap_or(vals[i]);
                assert_eq!(got, exp, "replace iter={iter} i={i} v={}", vals[i]);
            }
        }
    }

    #[test]
    fn series_isin_edges_membership_a6h9k() {
        use std::collections::HashSet;
        // Differential (br-frankenpandas-a6h9k): isin([])==all-false, isin(superset)==
        // all-true, isin(subset)==HashSet membership. Seeded LCG, no mocks.
        let mut st: u64 = 0x4a6e_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 6) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let getb = |s: Series| -> Vec<bool> {
                s.values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect()
            };
            // Empty -> all false.
            assert!(
                getb(series.isin(&[]).unwrap()).iter().all(|&b| !b),
                "empty all-false iter={iter}"
            );
            // Superset (0..6) -> all true.
            let superset: Vec<Scalar> = (0..6).map(Scalar::Int64).collect();
            assert!(
                getb(series.isin(&superset).unwrap()).iter().all(|&b| b),
                "superset all-true iter={iter}"
            );
            // Subset {0,1,2} -> membership.
            let subset: HashSet<i64> = [0, 1, 2].into_iter().collect();
            let needle: Vec<Scalar> = subset.iter().map(|&v| Scalar::Int64(v)).collect();
            let got = getb(series.isin(&needle).unwrap());
            for i in 0..n {
                assert_eq!(
                    got[i],
                    subset.contains(&vals[i]),
                    "membership iter={iter} i={i}"
                );
            }
        }
    }

    #[test]
    fn series_between_inclusive_modes_x0zej() {
        // Differential (br-frankenpandas-x0zej): between across all 4 inclusive modes
        // vs oracle. Seeded LCG, no mocks.
        let mut st: u64 = 0x4be7_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 10) as i64).collect();
            let lo = (next() % 8) as i64;
            let hi = lo + (next() % 4) as i64;
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            for mode in ["both", "neither", "left", "right"] {
                let out = series
                    .between(&Scalar::Int64(lo), &Scalar::Int64(hi), mode)
                    .unwrap();
                for i in 0..n {
                    let v = vals[i];
                    let exp = match mode {
                        "both" => v >= lo && v <= hi,
                        "neither" => v > lo && v < hi,
                        "left" => v >= lo && v < hi,
                        _ => v > lo && v <= hi, // right
                    };
                    assert_eq!(
                        out.values()[i],
                        Scalar::Bool(exp),
                        "between {mode} iter={iter} i={i} v={v} lo={lo} hi={hi}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_mask_replaces_where_true_8apma() {
        // Differential (br-frankenpandas-8apma): mask(cond, fill)[i]==fill if cond[i]
        // else self[i] (inverse of where). Seeded LCG, no mocks.
        let mut st: u64 = 0x4d5a_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let fill = -77i64;
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 100) as i64).collect();
            let conds: Vec<bool> = (0..n).map(|_| next() % 2 == 0).collect();
            let series = Series::from_values(
                "x",
                idx.clone(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let cond = Series::from_values(
                "c",
                idx,
                conds.iter().map(|&b| Scalar::Bool(b)).collect::<Vec<_>>(),
            )
            .unwrap();
            let out = series.mask(&cond, Some(&Scalar::Int64(fill))).unwrap();
            for i in 0..n {
                let exp = if conds[i] { fill } else { vals[i] };
                assert_eq!(
                    out.values()[i],
                    Scalar::Int64(exp),
                    "mask iter={iter} i={i}"
                );
            }
        }
    }

    #[test]
    fn series_pct_change_periods_ptayl() {
        // Differential (br-frankenpandas-ptayl): pct_change(2)[i]==v[i]/v[i-2]-1 in
        // range else NaN (w28or was k=1). Seeded LCG, non-zero values. No mocks.
        let mut st: u64 = 0x4c70_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 8) as usize + 3;
            // Non-zero values (avoid div-by-zero in denominator).
            let vals: Vec<f64> = (0..n).map(|_| (next() % 50) as f64 + 1.0).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let k = 2i64;
            let pc = series.pct_change(k).unwrap();
            for i in 0..n {
                let src = i as i64 - k;
                if src >= 0 {
                    let got = match &pc.values()[i] {
                        Scalar::Float64(x) => *x,
                        Scalar::Int64(x) => *x as f64,
                        _ => f64::NAN,
                    };
                    let exp = vals[i] / vals[src as usize] - 1.0;
                    assert!((got - exp).abs() < 1e-9, "pct_change iter={iter} i={i}");
                } else {
                    assert!(
                        pc.values()[i].is_missing(),
                        "pct_change edge NaN iter={iter} i={i}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_cumprod_after_zero_stays_zero_on56e() {
        // Property (br-frankenpandas-on56e): once a 0 appears, cumprod stays 0 onward.
        // Seeded LCG, no mocks.
        let mut st: u64 = 0x4c0d_1455_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 8) as usize + 1;
            // Small magnitude with occasional zeros.
            let vals: Vec<i64> = (0..n)
                .map(|_| {
                    if next() % 3 == 0 {
                        0
                    } else {
                        (next() % 5) as i64 - 2
                    }
                })
                .collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let cp: Vec<i64> = series
                .cumprod()
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => i64::MIN,
                })
                .collect();
            let first_zero = vals.iter().position(|&v| v == 0);
            if let Some(z) = first_zero {
                for i in z..n {
                    assert_eq!(cp[i], 0, "cumprod after zero iter={iter} i={i}");
                }
            }
        }
    }

    #[test]
    fn series_cumulative_last_equals_reduction_3inul() {
        // Cross-op (br-frankenpandas-3inul): cumsum[-1]==sum, cumprod[-1]==prod.
        // Seeded LCG, small magnitudes avoid prod overflow. No mocks.
        let mut st: u64 = 0x4c50_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let f = |sc: Scalar| -> f64 { sc.to_f64().unwrap_or(f64::NAN) };
        for iter in 0..600u32 {
            let n = (next() % 8) as usize + 1;
            // Small magnitude so cumprod stays within i64/f64-exact.
            let vals: Vec<i64> = (0..n).map(|_| (next() % 7) as i64 - 3).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let cs = series.cumsum().unwrap();
            let cp = series.cumprod().unwrap();
            assert!(
                (f(cs.values()[n - 1].clone()) - f(series.sum().unwrap())).abs() < 1e-9,
                "cumsum[-1]==sum iter={iter}"
            );
            assert!(
                (f(cp.values()[n - 1].clone()) - f(series.prod().unwrap())).abs() < 1e-9,
                "cumprod[-1]==prod iter={iter}"
            );
        }
    }

    #[test]
    fn series_diff_equals_sub_shift_0o806() {
        // Cross-op (br-frankenpandas-0o806): diff(k) == s - s.shift(k) element-wise
        // (both NaN at the same edges). Seeded LCG, no mocks.
        let mut st: u64 = 0x4d05_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..400u32 {
            let n = (next() % 10) as usize + 2;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 81) as i64 - 40).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            for k in [1i64, 2] {
                let d = series.diff(k).unwrap();
                let sub = series.sub(&series.shift(k).unwrap()).unwrap();
                for i in 0..n {
                    let dm = d.values()[i].is_missing();
                    let sm = sub.values()[i].is_missing();
                    assert_eq!(dm, sm, "missing alignment k={k} iter={iter} i={i}");
                    if !dm {
                        let dv = match &d.values()[i] {
                            Scalar::Float64(x) => *x,
                            Scalar::Int64(x) => *x as f64,
                            _ => f64::NAN,
                        };
                        let sv = match &sub.values()[i] {
                            Scalar::Float64(x) => *x,
                            Scalar::Int64(x) => *x as f64,
                            _ => f64::NAN,
                        };
                        assert!(
                            (dv - sv).abs() < 1e-9,
                            "diff==sub-shift k={k} iter={iter} i={i}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn series_diff_arbitrary_periods_9dijl() {
        // Differential (br-frankenpandas-9dijl): diff(k)[i]==v[i]-v[i-k] in range else
        // NaN, for k in {2,-1} (2sjc3 was k=1). Seeded LCG, no mocks.
        let mut st: u64 = 0x4d1f_0b2c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 10) as usize + 2;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 81) as i64 - 40).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            for k in [2i64, -1] {
                let d = series.diff(k).unwrap();
                for i in 0..n {
                    let src = i as i64 - k;
                    if src >= 0 && (src as usize) < n {
                        let got = match &d.values()[i] {
                            Scalar::Float64(x) => *x,
                            Scalar::Int64(x) => *x as f64,
                            _ => f64::NAN,
                        };
                        assert!(
                            (got - (vals[i] - vals[src as usize]) as f64).abs() < 1e-9,
                            "diff k={k} iter={iter} i={i}"
                        );
                    } else {
                        assert!(
                            d.values()[i].is_missing(),
                            "diff edge NaN k={k} iter={iter} i={i}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn series_ffill_bfill_completeness_ty015() {
        // Property (br-frankenpandas-ty015): with >=1 valid value, ffill().bfill() has
        // no NaN, and every filled value comes from the input value-set. Seeded LCG.
        let mut st: u64 = 0x4ff0_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<f64> = (0..n)
                .map(|_| {
                    if next() % 3 == 0 {
                        f64::NAN
                    } else {
                        (next() % 50) as f64
                    }
                })
                .collect();
            if vals.iter().all(|v| v.is_nan()) {
                continue; // all-NaN: nothing to fill from
            }
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let filled = series.ffill(None).unwrap().bfill(None).unwrap();
            let valid: std::collections::HashSet<u64> = vals
                .iter()
                .filter(|v| !v.is_nan())
                .map(|v| v.to_bits())
                .collect();
            for i in 0..n {
                let v = filled.values()[i].clone();
                assert!(
                    !v.is_missing(),
                    "no NaN after ffill.bfill iter={iter} i={i}"
                );
                let bits = match v {
                    Scalar::Float64(x) => x.to_bits(),
                    Scalar::Int64(x) => (x as f64).to_bits(),
                    _ => 0,
                };
                assert!(
                    valid.contains(&bits),
                    "filled from valid set iter={iter} i={i}"
                );
            }
        }
    }

