    #[test]
    fn series_quantile_rejects_out_of_range_wsx66() {
        // Behavioral (br-frankenpandas-wsx66): quantile q must be in [0,1].
        let series = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        assert!(series.quantile(-0.1).is_err(), "q<0 rejected");
        assert!(series.quantile(1.1).is_err(), "q>1 rejected");
        assert!(series.quantile(0.0).is_ok(), "q=0 ok");
        assert!(series.quantile(1.0).is_ok(), "q=1 ok");
        assert!(series.quantile(0.5).is_ok(), "q=0.5 ok");
    }

