    #[test]
    fn series_pow_consistency_kzz4h() {
        // Property (br-frankenpandas-kzz4h): pow exp-2==x*x, exp-1==x, exp-0==1.
        // Seeded LCG, small bases. No mocks.
        let mut st: u64 = 0x4b0a_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let nf = |c: &[Scalar]| -> Vec<f64> {
            c.iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x as f64,
                    Scalar::Float64(x) => *x,
                    _ => f64::NAN,
                })
                .collect()
        };
        for iter in 0..400u32 {
            let n = (next() % 8) as usize + 1;
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let base: Vec<i64> = (0..n).map(|_| (next() % 13) as i64 - 6).collect();
            let series = Series::from_values(
                "x",
                idx.clone(),
                base.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let cst = |k: i64| {
                Series::from_values(
                    "e",
                    idx.clone(),
                    (0..n).map(|_| Scalar::Int64(k)).collect::<Vec<_>>(),
                )
                .unwrap()
            };
            let sq = nf(series.mul(&series).unwrap().values());
            let p2 = nf(series.pow(&cst(2)).unwrap().values());
            let p1 = nf(series.pow(&cst(1)).unwrap().values());
            let p0 = nf(series.pow(&cst(0)).unwrap().values());
            for i in 0..n {
                assert!((p2[i] - sq[i]).abs() < 1e-7, "x^2==x*x iter={iter} i={i}");
                assert!(
                    (p1[i] - base[i] as f64).abs() < 1e-7,
                    "x^1==x iter={iter} i={i}"
                );
                assert!((p0[i] - 1.0).abs() < 1e-7, "x^0==1 iter={iter} i={i}");
            }
        }
    }

