    #[test]
    fn series_clip_decomposition_vuinu() {
        // Property (br-frankenpandas-vuinu): clip(lo,hi)==clip(lo,None).clip(None,hi).
        // Seeded LCG, no mocks.
        let mut st: u64 = 0x4c1d_1253_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let geti = |c: &[Scalar]| -> Vec<i64> {
            c.iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 41) as i64 - 20).collect();
            let lo = (next() % 30) as f64 - 15.0;
            let hi = lo + (next() % 20) as f64;
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let two_sided = series.clip(Some(lo), Some(hi)).unwrap();
            let composed = series
                .clip(Some(lo), None)
                .unwrap()
                .clip(None, Some(hi))
                .unwrap();
            assert_eq!(
                geti(two_sided.values()),
                geti(composed.values()),
                "clip decomposition iter={iter}"
            );
        }
    }

    #[test]
    fn series_clip_bounded_idempotent_ffqkp() {
        // Property (br-frankenpandas-ffqkp): clip(lo,hi) result is in [lo,hi] and clip
        // is idempotent. Seeded LCG, no mocks.
        let mut s: u64 = 0x4c19_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let getf = |c: &[Scalar]| -> Vec<f64> {
            c.iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                })
                .collect()
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<f64> = (0..n).map(|_| (next() % 200) as f64 - 100.0).collect();
            let lo = (next() % 60) as f64 - 30.0;
            let hi = lo + (next() % 40) as f64; // hi >= lo
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let clipped = series.clip(Some(lo), Some(hi)).unwrap();
            let cv = getf(clipped.values());
            for (i, &v) in cv.iter().enumerate() {
                assert!(
                    v >= lo - 1e-9 && v <= hi + 1e-9,
                    "bounded iter={iter} i={i}: {v} not in [{lo},{hi}]"
                );
                // Exact: clamped value equals clamp(orig).
                assert!(
                    (v - vals[i].max(lo).min(hi)).abs() < 1e-9,
                    "clamp value iter={iter} i={i}"
                );
            }
            // Idempotent.
            let again = getf(clipped.clip(Some(lo), Some(hi)).unwrap().values());
            for i in 0..n {
                assert!(
                    (again[i] - cv[i]).abs() < 1e-12,
                    "idempotent iter={iter} i={i}"
                );
            }
        }
    }

