    #[test]
    fn series_nlargest_nsmallest_n_edges_cwjwe() {
        // Edge (br-frankenpandas-cwjwe): n=0 -> empty; n>len -> all rows
        // (nlargest desc, nsmallest asc). Distinct keys. Seeded LCG, no mocks.
        let mut st: u64 = 0x4c0e_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let geti = |c: &[Scalar]| -> Vec<i64> {
            c.iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..400u32 {
            let n = (next() % 8) as usize + 1;
            let mut vals: Vec<i64> = (0..n as i64).map(|i| i * 3 + 1).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                vals.swap(i, j);
            }
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            assert_eq!(
                series.nlargest(0).unwrap().len(),
                0,
                "nlargest(0) empty iter={iter}"
            );
            assert_eq!(
                series.nsmallest(0).unwrap().len(),
                0,
                "nsmallest(0) empty iter={iter}"
            );
            let mut desc = vals.clone();
            desc.sort_unstable_by(|a, b| b.cmp(a));
            let mut asc = vals.clone();
            asc.sort_unstable();
            assert_eq!(
                geti(series.nlargest(n + 5).unwrap().values()),
                desc,
                "nlargest(>len)==all desc iter={iter}"
            );
            assert_eq!(
                geti(series.nsmallest(n + 5).unwrap().values()),
                asc,
                "nsmallest(>len)==all asc iter={iter}"
            );
        }
    }

