    #[test]
    fn series_division_algorithm_4pfsa() {
        // Metamorphic (br-frankenpandas-4pfsa): a == (a//b)*b + (a%b) exactly for
        // integer floor-division (Python semantics, incl negative divisors). Guards
        // floordiv AND modulo together. Seeded LCG, no mocks.
        let mut s: u64 = 0x4d1a_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let geti = |c: &[Scalar]| -> Vec<i64> {
            c.iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..600u32 {
            let n = (next() % 10) as usize + 1;
            let a: Vec<i64> = (0..n).map(|_| (next() % 101) as i64 - 50).collect();
            let b: Vec<i64> = (0..n)
                .map(|_| {
                    let mag = (next() % 5) as i64 + 1; // 1..5
                    if next() % 2 == 0 { mag } else { -mag }
                })
                .collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let sa = Series::from_values(
                "a",
                idx.clone(),
                a.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let sb = Series::from_values(
                "b",
                idx,
                b.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let recon = sa
                .floordiv(&sb)
                .unwrap()
                .mul(&sb)
                .unwrap()
                .add(&sa.modulo(&sb).unwrap())
                .unwrap();
            assert_eq!(
                geti(recon.values()),
                a,
                "division algorithm iter={iter} b={b:?}"
            );
        }
    }

