    #[test]
    fn series_value_counts_ordering_7nk9z() {
        use std::collections::BTreeMap;
        // Differential (br-frankenpandas-7nk9z): value_counts sort ordering. sort=true
        // ascending=false -> non-increasing counts; ascending=true -> non-decreasing;
        // (value,count) multiset matches a BTreeMap oracle either way. Seeded LCG.
        let mut s: u64 = 0x4e57_0c2c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        for iter in 0..600u32 {
            let n = (next() % 16) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 6) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let mut oracle: BTreeMap<i64, i64> = BTreeMap::new();
            for &v in &vals {
                *oracle.entry(v).or_default() += 1;
            }
            let pairs = |asc: bool| -> Vec<(i64, i64)> {
                let vc = series
                    .value_counts_with_options(false, true, asc, true)
                    .unwrap();
                vc.index()
                    .labels()
                    .iter()
                    .zip(vc.values().iter())
                    .map(|(l, c)| {
                        let li = match l {
                            IndexLabel::Int64(k) => *k,
                            _ => i64::MIN,
                        };
                        let ci = match c {
                            Scalar::Int64(k) => *k,
                            Scalar::Float64(k) => *k as i64,
                            _ => i64::MIN,
                        };
                        (li, ci)
                    })
                    .collect()
            };
            for asc in [false, true] {
                let p = pairs(asc);
                // Multiset of (value,count) matches oracle.
                let mut got_sorted = p.clone();
                got_sorted.sort();
                let mut exp_sorted: Vec<(i64, i64)> =
                    oracle.iter().map(|(&k, &v)| (k, v)).collect();
                exp_sorted.sort();
                assert_eq!(got_sorted, exp_sorted, "vc multiset iter={iter} asc={asc}");
                // Counts are monotone in the requested direction.
                for w in p.windows(2) {
                    if asc {
                        assert!(w[0].1 <= w[1].1, "ascending counts iter={iter}: {:?}", p);
                    } else {
                        assert!(w[0].1 >= w[1].1, "descending counts iter={iter}: {:?}", p);
                    }
                }
            }
        }
    }

    #[test]
    fn series_value_counts_normalize_pme2e() {
        // Differential (br-frankenpandas-pme2e): value_counts(normalize=true) yields
        // proportions summing to 1.0, each == tally/total. Seeded LCG, no mocks.
        let mut st: u64 = 0x4e02_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            let n = (next() % 14) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 5) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let mut tally: std::collections::BTreeMap<i64, usize> =
                std::collections::BTreeMap::new();
            for &v in &vals {
                *tally.entry(v).or_default() += 1;
            }
            let total = n as f64;

            let vc = series
                .value_counts_with_options(true, true, false, true)
                .unwrap();
            let labels = vc.index().labels();
            let props = vc.values();
            let mut sum = 0.0_f64;
            for i in 0..labels.len() {
                let k = match &labels[i] {
                    IndexLabel::Int64(k) => *k,
                    _ => i64::MIN,
                };
                let p = match &props[i] {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                };
                let exp = *tally.get(&k).unwrap_or(&0) as f64 / total;
                assert!(
                    (p - exp).abs() < 1e-9,
                    "prop iter={iter} k={k}: {p} vs {exp}"
                );
                sum += p;
            }
            assert!((sum - 1.0).abs() < 1e-9, "proportions sum to 1 iter={iter}");
        }
    }

