    #[test]
    fn series_cov_pairwise_complete_nan_stbp0() {
        // Differential (br-frankenpandas-stbp0): cov drops rows where either value
        // is NaN (pairwise-complete), then two-pass cov; NaN when <2 pairs. Seeded LCG.
        let mut st: u64 = 0xc09a_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            let n = (next() % 10) as usize + 1;
            let g = |nn: &mut dyn FnMut() -> u32| -> Vec<f64> {
                (0..n)
                    .map(|_| {
                        if nn() % 4 == 0 {
                            f64::NAN
                        } else {
                            (nn() % 40) as f64 / 4.0 - 5.0
                        }
                    })
                    .collect()
            };
            let x = g(&mut next);
            let y = g(&mut next);
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let sx = Series::from_values(
                "x",
                idx.clone(),
                x.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let sy = Series::from_values(
                "y",
                idx,
                y.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            let pairs: Vec<(f64, f64)> = x
                .iter()
                .zip(y.iter())
                .filter(|(a, b)| !a.is_nan() && !b.is_nan())
                .map(|(a, b)| (*a, *b))
                .collect();
            let got = sx.cov(&sy).unwrap();
            if pairs.len() < 2 {
                assert!(got.is_nan(), "cov<2 pairs NaN iter={iter}");
            } else {
                let k = pairs.len() as f64;
                let mx = pairs.iter().map(|p| p.0).sum::<f64>() / k;
                let my = pairs.iter().map(|p| p.1).sum::<f64>() / k;
                let exp = pairs.iter().map(|(a, b)| (a - mx) * (b - my)).sum::<f64>() / (k - 1.0);
                assert!((got - exp).abs() < 1e-7, "cov iter={iter}: {got} vs {exp}");
            }
        }
    }

