    #[test]
    fn series_modulo_python_sign_xgz8f() {
        // Differential (br-frankenpandas-xgz8f): modulo follows Python/pandas
        // (result sign = divisor sign): a - floor(a/b)*b. Seeded LCG, no mocks.
        let mut st: u64 = 0x70d0_5a1b_2c3d_4e5f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        for iter in 0..1000u32 {
            let n = (next() % 8) as usize + 1;
            let a: Vec<i64> = (0..n).map(|_| (next() % 21) as i64 - 10).collect();
            let b: Vec<i64> = (0..n)
                .map(|_| {
                    let m = (next() % 6) as i64;
                    if m < 3 { m - 3 } else { m - 2 } // -3,-2,-1,1,2,3
                })
                .collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let sa = Series::from_values(
                "a",
                idx.clone(),
                a.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let sb = Series::from_values(
                "b",
                idx,
                b.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            let m = sa.modulo(&sb).unwrap();
            for i in 0..n {
                let (af, bf) = (a[i] as f64, b[i] as f64);
                let exp = af - (af / bf).floor() * bf;
                assert!(
                    (num(&m.values()[i]) - exp).abs() < 1e-9,
                    "modulo iter={iter} i={i} {}%{}",
                    a[i],
                    b[i]
                );
            }
        }
    }

    #[test]
    fn series_div_floordiv_semantics_5cppk() {
        // Differential (br-frankenpandas-5cppk): div is true division (Float64);
        // floordiv floors toward -inf (Python/pandas), not trunc-toward-zero.
        // Non-zero divisor. Seeded LCG, no mocks.
        let mut st: u64 = 0xd1f0_0a2b_3c4d_5e6f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        for iter in 0..1000u32 {
            let n = (next() % 8) as usize + 1;
            let a: Vec<i64> = (0..n).map(|_| (next() % 21) as i64 - 10).collect();
            // Non-zero divisor in {-3..-1, 1..3}.
            let b: Vec<i64> = (0..n)
                .map(|_| {
                    let m = (next() % 6) as i64; // 0..5
                    if m < 3 { m - 3 } else { m - 2 } // -3,-2,-1,1,2,3
                })
                .collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let sa = Series::from_values(
                "a",
                idx.clone(),
                a.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let sb = Series::from_values(
                "b",
                idx,
                b.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            let d = sa.div(&sb).unwrap();
            let fd = sa.floordiv(&sb).unwrap();
            for i in 0..n {
                let exp_div = a[i] as f64 / b[i] as f64;
                assert!(
                    (num(&d.values()[i]) - exp_div).abs() < 1e-9,
                    "div iter={iter} i={i} {}/{}",
                    a[i],
                    b[i]
                );
                let exp_fd = (a[i] as f64 / b[i] as f64).floor();
                assert!(
                    (num(&fd.values()[i]) - exp_fd).abs() < 1e-9,
                    "floordiv iter={iter} i={i} {}//{}",
                    a[i],
                    b[i]
                );
            }
        }
    }

