    #[test]
    fn dataframe_groupby_cumcount_within_group_d3sl5() {
        use std::collections::HashMap;
        // Differential (br-frankenpandas-d3sl5): groupby cumcount = 0-based within-
        // group ordinal aligned to original row order. Seeded LCG, no mocks.
        let mut s: u64 = 0x4cc7_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        for iter in 0..300u32 {
            let n = (next() % 14) as usize + 2;
            let k: Vec<i64> = (0..n).map(|_| (next() % 3) as i64).collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "k",
                    idx.clone(),
                    k.iter().map(|&x| Scalar::Int64(x)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "v",
                    idx,
                    (0..n).map(|i| Scalar::Int64(i as i64)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();
            let cc = df.groupby(&["k"]).unwrap().cumcount().unwrap();
            let mut cnt: HashMap<i64, i64> = HashMap::new();
            let mut exp: Vec<i64> = Vec::with_capacity(n);
            for i in 0..n {
                let e = cnt.entry(k[i]).or_default();
                exp.push(*e);
                *e += 1;
            }
            let got: Vec<i64> = cc
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect();
            assert_eq!(got, exp, "groupby cumcount iter={iter}");
        }
    }

