    #[test]
    fn dataframe_groupby_multikey_sum_oracle_ev7sk() {
        use std::collections::BTreeMap;
        // Differential (br-frankenpandas-ev7sk): multi-key int64 groupby sum vs an
        // independent (k0,k1) BTreeMap oracle (k3zcv oracle was single-key). Multi-key
        // result uses composite "k0, k1" Utf8 labels (sorted) + v_sum column via
        // agg_list. Seeded LCG, no mocks.
        let mut s: u64 = 0x4d17_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        for iter in 0..300u32 {
            let n = (next() % 14) as usize + 4;
            let k0: Vec<i64> = (0..n).map(|_| (next() % 3) as i64).collect();
            let k1: Vec<i64> = (0..n).map(|_| (next() % 3) as i64).collect();
            let v: Vec<f64> = (0..n).map(|_| (next() % 100) as f64).collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "k0",
                    idx.clone(),
                    k0.iter().map(|&x| Scalar::Int64(x)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "k1",
                    idx.clone(),
                    k1.iter().map(|&x| Scalar::Int64(x)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "v",
                    idx,
                    v.iter().map(|&x| Scalar::Float64(x)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();
            // Oracle: BTreeMap keyed by (k0,k1) => sum, naturally sorted.
            let mut oracle: BTreeMap<(i64, i64), f64> = BTreeMap::new();
            for i in 0..n {
                *oracle.entry((k0[i], k1[i])).or_default() += v[i];
            }
            let result = df
                .groupby(&["k0", "k1"])
                .unwrap()
                .agg_list(&["sum"])
                .unwrap();
            let labels = result.index().labels();
            let sums = result.column("v_sum").expect("v_sum").values();
            assert_eq!(labels.len(), oracle.len(), "group count iter={iter}");
            for (i, ((g0, g1), exp)) in oracle.iter().enumerate() {
                assert_eq!(
                    labels[i],
                    IndexLabel::Utf8(format!("{g0}, {g1}")),
                    "label iter={iter} i={i}"
                );
                let got = match &sums[i] {
                    Scalar::Float64(x) => *x,
                    Scalar::Int64(x) => *x as f64,
                    _ => f64::NAN,
                };
                assert!(
                    (got - exp).abs() < 1e-9,
                    "sum iter={iter} group=({g0},{g1})"
                );
            }
        }
    }

    #[test]
    fn dataframe_groupby_sum_totals_invariant_py92l() {
        // Metamorphic (br-frankenpandas-py92l): groupby partitions rows without
        // loss/duplication, so the sum of per-group sums == the overall column sum.
        let mut st: u64 = 0x6504_a1b2_c3d4_e5f6;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1000u32 {
            let n = (next() % 14) as usize + 1;
            let keys: Vec<i64> = (0..n).map(|_| (next() % 5) as i64).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 21) as i64 - 10).collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "k",
                    idx.clone(),
                    keys.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "v",
                    idx,
                    vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();

            let grouped = df.groupby(&["k"]).unwrap().sum().unwrap();
            let group_total: i64 = grouped
                .column("v")
                .unwrap()
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => 0,
                })
                .sum();
            let overall: i64 = vals.iter().sum();
            assert_eq!(
                group_total, overall,
                "groupby-sum totals iter={iter} keys={keys:?} vals={vals:?}"
            );
        }
    }

    #[test]
    fn series_replace_value_mapping_b049a() {
        // Differential (br-frankenpandas-b049a): replace maps matching values to
        // their replacement, leaving others unchanged. Non-chaining map. Seeded LCG.
        let mut st: u64 = 0x4e91_0a2b_3c4d_5e6f;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        // old values {0,2} -> new values {100,200} (disjoint, no chaining).
        let repl = [
            (Scalar::Int64(0), Scalar::Int64(100)),
            (Scalar::Int64(2), Scalar::Int64(200)),
        ];
        let map: std::collections::HashMap<i64, i64> =
            [(0i64, 100i64), (2, 200)].into_iter().collect();
        for iter in 0..1000u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 5) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let out = series.replace(&repl).unwrap();
            for i in 0..n {
                let exp = map.get(&vals[i]).copied().unwrap_or(vals[i]);
                assert_eq!(
                    out.values()[i],
                    Scalar::Int64(exp),
                    "replace iter={iter} i={i} v={}",
                    vals[i]
                );
            }
        }
    }

    #[test]
    fn dataframe_drop_duplicates_rows_eh5mv() {
        // Differential (br-frankenpandas-eh5mv): drop_duplicates(keep=First) keeps
        // the first occurrence of each (a,b) row tuple, in order. Seeded LCG, no mocks.
        let mut st: u64 = 0xd2ed_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..800u32 {
            let n = (next() % 12) as usize + 1;
            let a: Vec<i64> = (0..n).map(|_| (next() % 3) as i64).collect();
            let b: Vec<i64> = (0..n).map(|_| (next() % 3) as i64).collect();
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "a",
                    idx.clone(),
                    a.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "b",
                    idx,
                    b.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();

            let mut seen = std::collections::HashSet::new();
            let keep_rows: Vec<usize> = (0..n).filter(|&i| seen.insert((a[i], b[i]))).collect();
            let exp_a: Vec<i64> = keep_rows.iter().map(|&i| a[i]).collect();
            let exp_b: Vec<i64> = keep_rows.iter().map(|&i| b[i]).collect();

            let out = df
                .drop_duplicates(None, DuplicateKeep::First, false)
                .unwrap();
            let geti = |c: &Column| -> Vec<i64> {
                c.values()
                    .iter()
                    .map(|s| match s {
                        Scalar::Int64(x) => *x,
                        _ => i64::MIN,
                    })
                    .collect()
            };
            assert_eq!(
                geti(out.column("a").unwrap()),
                exp_a,
                "a iter={iter} a={a:?} b={b:?}"
            );
            assert_eq!(
                geti(out.column("b").unwrap()),
                exp_b,
                "b iter={iter} a={a:?} b={b:?}"
            );
        }
    }

    #[test]
    fn dataframe_fillna_all_columns_k1i8u() {
        // Differential (br-frankenpandas-k1i8u): fillna replaces every missing cell
        // with the scalar, leaving finite cells unchanged. Seeded LCG, no mocks.
        let mut st: u64 = 0xf11a_d00d_2b3c_4d5e;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        let fill = 99.0_f64;
        for iter in 0..800u32 {
            let n = (next() % 10) as usize + 1;
            let gen_col = |n: &mut dyn FnMut() -> u32, rows: usize| -> Vec<f64> {
                (0..rows)
                    .map(|_| {
                        if n() % 3 == 0 {
                            f64::NAN
                        } else {
                            (n() % 100) as f64 / 10.0
                        }
                    })
                    .collect()
            };
            let a = gen_col(&mut next, n);
            let b = gen_col(&mut next, n);
            let idx: Vec<IndexLabel> = (0..n as i64).map(Into::into).collect();
            let df = DataFrame::from_series(vec![
                Series::from_values(
                    "a",
                    idx.clone(),
                    a.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
                Series::from_values(
                    "b",
                    idx,
                    b.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap();

            let filled = df.fillna(&Scalar::Float64(fill)).unwrap();
            for (name, src) in [("a", &a), ("b", &b)] {
                let col = filled.column(name).unwrap();
                for i in 0..n {
                    let exp = if src[i].is_nan() { fill } else { src[i] };
                    assert!(
                        (num(&col.values()[i]) - exp).abs() < 1e-9,
                        "fillna {name} iter={iter} i={i}"
                    );
                }
            }
        }
    }

    #[test]
    fn dataframe_groupby_first_last_skip_nulls_iq9gz() {
        // br-frankenpandas-iq9gz: groupby first/last return the first/last NON-null
        // value per group (pandas skipna default), matching SeriesGroupBy.
        let idx: Vec<IndexLabel> = (0..5i64).map(Into::into).collect();
        let keys = Series::from_values(
            "k",
            idx.clone(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )
        .unwrap();
        // group a = [NaN, 5, 7] -> first 5, last 7; group b = [3, NaN] -> first/last 3.
        let val = Series::from_values(
            "val",
            idx,
            vec![
                Scalar::Float64(f64::NAN),
                Scalar::Float64(5.0),
                Scalar::Float64(7.0),
                Scalar::Float64(3.0),
                Scalar::Float64(f64::NAN),
            ],
        )
        .unwrap();
        let df = DataFrame::from_series(vec![keys, val]).unwrap();

        let check = |out: &DataFrame, exp: &[(&str, f64)]| {
            let labels = out.index.labels();
            let vals = out.column("val").unwrap().values();
            for (k, want) in exp {
                let pos = labels
                    .iter()
                    .position(|l| matches!(l, IndexLabel::Utf8(s) if s == k))
                    .expect("group label present");
                let got = match &vals[pos] {
                    Scalar::Float64(x) => *x,
                    _ => f64::NAN,
                };
                assert!(
                    (got - want).abs() < 1e-9,
                    "group {k}: got {got} want {want}"
                );
            }
        };
        check(
            &df.groupby(&["k"]).unwrap().first().unwrap(),
            &[("a", 5.0), ("b", 3.0)],
        );
        check(
            &df.groupby(&["k"]).unwrap().last().unwrap(),
            &[("a", 7.0), ("b", 3.0)],
        );
        // agg-dict first/last also skip nulls.
        let mut fm = std::collections::HashMap::new();
        fm.insert("val".to_string(), "first".to_string());
        check(
            &df.groupby(&["k"]).unwrap().agg(&fm).unwrap(),
            &[("a", 5.0), ("b", 3.0)],
        );
    }

    #[test]
    fn series_groupby_transform_agg_first_last_skip_nulls_iq9gz() {
        // br-frankenpandas-iq9gz remaining tracked sites: SeriesGroupBy.transform
        // and agg-dict "last" must also skip nulls, an all-null group must emit
        // null, and Utf8 (object) values must skip nulls too. pandas 2.2.3 on
        // keys [a,a,a,b,b,c] / vals [NaN,1,2,NaN,NaN,5]:
        //   first -> a=1 b=NaN c=5   last -> a=2 b=NaN c=5
        //   transform("first") -> [1,1,1,NaN,NaN,5]
        //   transform("last")  -> [2,2,2,NaN,NaN,5]
        let idx: Vec<IndexLabel> = (0..6i64).map(Into::into).collect();
        let key_scalars: Vec<Scalar> = ["a", "a", "a", "b", "b", "c"]
            .iter()
            .map(|k| Scalar::Utf8((*k).into()))
            .collect();
        let keys = Series::from_values("k", idx.clone(), key_scalars).unwrap();
        let vals = vec![
            Scalar::Null(NullKind::NaN),
            Scalar::Float64(1.0),
            Scalar::Float64(2.0),
            Scalar::Null(NullKind::NaN),
            Scalar::Null(NullKind::NaN),
            Scalar::Float64(5.0),
        ];
        let val = Series::from_values("val", idx.clone(), vals).unwrap();

        // `expected` uses None for "missing" (pandas NaN).
        let assert_col = |col: &Column, expected: &[Option<f64>], what: &str| {
            let got = col.values();
            assert_eq!(got.len(), expected.len(), "{what}: length");
            for (i, want) in expected.iter().enumerate() {
                match (want, &got[i]) {
                    (Some(w), Scalar::Float64(g)) => {
                        assert!((g - w).abs() < 1e-9, "{what}[{i}]: got {g} want {w}");
                    }
                    (None, g) => assert!(g.is_missing(), "{what}[{i}]: got {g:?} want missing"),
                    (Some(w), g) => panic!("{what}[{i}]: got {g:?} want {w}"),
                }
            }
        };
        let assert_f64 = |got: &Series, expected: &[Option<f64>], what: &str| {
            assert_col(got.column(), expected, what);
        };

        let sgb = val.groupby(&keys).unwrap();
        assert_f64(
            &sgb.first().unwrap(),
            &[Some(1.0), None, Some(5.0)],
            "SeriesGroupBy.first",
        );
        assert_f64(
            &sgb.last().unwrap(),
            &[Some(2.0), None, Some(5.0)],
            "SeriesGroupBy.last",
        );
        assert_f64(
            &sgb.transform("first").unwrap(),
            &[Some(1.0), Some(1.0), Some(1.0), None, None, Some(5.0)],
            "transform(first)",
        );
        assert_f64(
            &sgb.transform("last").unwrap(),
            &[Some(2.0), Some(2.0), Some(2.0), None, None, Some(5.0)],
            "transform(last)",
        );

        // agg-dict "last" (the "first" arm is covered above) + all-null group b.
        let df = DataFrame::from_series(vec![keys.clone(), val]).unwrap();
        let mut fm = std::collections::HashMap::new();
        fm.insert("val".to_string(), "last".to_string());
        let agg_last = df.groupby(&["k"]).unwrap().agg(&fm).unwrap();
        assert_col(
            agg_last.column("val").unwrap(),
            &[Some(2.0), None, Some(5.0)],
            "agg-dict(last)",
        );

        // Utf8 (object) values skip nulls the same way.
        let svals = vec![
            Scalar::Null(NullKind::NaN),
            Scalar::Utf8("x".into()),
            Scalar::Utf8("y".into()),
            Scalar::Null(NullKind::NaN),
            Scalar::Null(NullKind::NaN),
            Scalar::Utf8("z".into()),
        ];
        let sval = Series::from_values("val", idx, svals).unwrap();
        let sdf = DataFrame::from_series(vec![keys, sval]).unwrap();
        let out = sdf.groupby(&["k"]).unwrap().first().unwrap();
        let got = out.column("val").unwrap().values();
        assert!(matches!(&got[0], Scalar::Utf8(s) if s == "x"));
        assert!(got[1].is_missing(), "all-null group -> missing");
        assert!(matches!(&got[2], Scalar::Utf8(s) if s == "z"));
    }

    #[test]
    fn dataframe_groupby_agg_dict_moments_zge5s() {
        // br-frankenpandas-zge5s: groupby agg({col: 'skew'/'kurt'/'sem'}) now
        // works (string dispatch was rejecting them despite the methods existing).
        let idx: Vec<IndexLabel> = (0..8i64).map(Into::into).collect();
        let keys = Series::from_values(
            "k",
            idx.clone(),
            (0..8)
                .map(|i| Scalar::Utf8(if i < 4 { "a" } else { "b" }.into()))
                .collect::<Vec<_>>(),
        )
        .unwrap();
        let raw = [1i64, 2, 4, 8, 1, 1, 2, 10];
        let v = Series::from_values(
            "v",
            idx,
            raw.iter().map(|&x| Scalar::Int64(x)).collect::<Vec<_>>(),
        )
        .unwrap();
        let df = DataFrame::from_series(vec![keys, v]).unwrap();

        let mut fm = std::collections::HashMap::new();
        fm.insert("v".to_string(), "skew".to_string());
        let via = df.groupby(&["k"]).unwrap().agg(&fm).unwrap();
        let direct = df.groupby(&["k"]).unwrap().skew().unwrap();
        let g = |c: &Column, i: usize| match &c.values()[i] {
            Scalar::Float64(x) => *x,
            _ => f64::NAN,
        };
        for i in 0..direct.index.len() {
            let a = g(via.column("v").unwrap(), i);
            let b = g(direct.column("v").unwrap(), i);
            assert!(
                (a - b).abs() < 1e-9 || (a.is_nan() && b.is_nan()),
                "agg-dict skew row {i}: {a} vs {b}"
            );
        }
        // kurt/kurtosis/sem dict aggs must also resolve (previously rejected).
        for f in ["kurt", "kurtosis", "sem"] {
            let mut m = std::collections::HashMap::new();
            m.insert("v".to_string(), f.to_string());
            df.groupby(&["k"]).unwrap().agg(&m).unwrap();
        }
    }

    #[test]
    fn dataframe_groupby_prod_preserves_int64_j9w3s() {
        // pandas groupby.prod() preserves Int64 for integer input, mirroring sum
        // (br-frankenpandas-j9w3s; previously coerced to Float64).
        let mk = |grp: Vec<Scalar>, val: Vec<i64>| {
            DataFrame::from_series(vec![
                Series::from_values(
                    "grp",
                    (0..grp.len() as i64).map(Into::into).collect::<Vec<_>>(),
                    grp,
                )
                .unwrap(),
                Series::from_values(
                    "val",
                    (0..val.len() as i64).map(Into::into).collect::<Vec<_>>(),
                    val.into_iter().map(Scalar::Int64).collect::<Vec<_>>(),
                )
                .unwrap(),
            ])
            .unwrap()
        };

        // Utf8 keys -> generic aggregation path.
        let r = mk(
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
            vec![2, 3, 4, 5],
        )
        .groupby(&["grp"])
        .unwrap()
        .prod()
        .unwrap();
        assert_eq!(r.columns["val"].values()[0], Scalar::Int64(6)); // a: 2*3
        assert_eq!(r.columns["val"].values()[1], Scalar::Int64(20)); // b: 4*5

        // Int64 keys -> dense aggregation path.
        let r2 = mk(
            vec![
                Scalar::Int64(10),
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(20),
            ],
            vec![2, 3, 4, 5],
        )
        .groupby(&["grp"])
        .unwrap()
        .prod()
        .unwrap();
        assert_eq!(r2.columns["val"].values()[0], Scalar::Int64(6));
        assert_eq!(r2.columns["val"].values()[1], Scalar::Int64(20));
    }

    #[test]
    fn prod_dtype_preservation_family_985tj() {
        // Regression guard for the prod dtype contract (br-a52db + rl25i/j9w3s):
        // Series.prod / DataFrame.prod(axis=0) keep Int64 for integer/bool input.
        let si = |name: &str, v: Vec<i64>| {
            Series::from_values(
                name,
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.into_iter().map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        // Series.prod stays Int64.
        assert_eq!(si("x", vec![2, 3, 4]).prod().unwrap(), Scalar::Int64(24));
        assert_eq!(si("x", vec![5]).prod().unwrap(), Scalar::Int64(5));
        assert_eq!(si("x", vec![2, 0, 9]).prod().unwrap(), Scalar::Int64(0));
        assert_eq!(si("x", vec![-2, 3]).prod().unwrap(), Scalar::Int64(-6));

        // Bool.prod -> Int64.
        let sb = |v: Vec<bool>| {
            Series::from_values(
                "b",
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.into_iter().map(Scalar::Bool).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        assert_eq!(sb(vec![true, true]).prod().unwrap(), Scalar::Int64(1));
        assert_eq!(
            sb(vec![true, false, true]).prod().unwrap(),
            Scalar::Int64(0)
        );

        // DataFrame.prod(axis=0) keeps Int64 per column.
        let df = DataFrame::from_series(vec![si("a", vec![2, 3]), si("c", vec![4, 5])]).unwrap();
        let p = df.prod_agg().unwrap();
        assert_eq!(p.values(), &[Scalar::Int64(6), Scalar::Int64(20)]);
    }

    #[test]
    fn series_cumulative_ops_match_oracle_q4erv() {
        // Differential vs independent running reductions (br-frankenpandas-q4erv).
        // Small values (-4..4, len<=10) keep all results within i64 (no overflow),
        // so the comparison is dtype-robust. Deterministic seeded LCG, no mocks.
        let mut s: u64 = 0xc0ff_ee5e_a1b2_c3d4;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let num = |scalars: &[Scalar]| -> Vec<i64> {
            scalars
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..1500u32 {
            let n = (next() % 10) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 9) as i64 - 4).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            let (mut csum, mut cprod, mut cmax, mut cmin) =
                (Vec::new(), Vec::new(), Vec::new(), Vec::new());
            let (mut acc, mut prod, mut mx, mut mn) = (0i64, 1i64, i64::MIN, i64::MAX);
            for &v in &vals {
                acc += v;
                prod *= v;
                mx = mx.max(v);
                mn = mn.min(v);
                csum.push(acc);
                cprod.push(prod);
                cmax.push(mx);
                cmin.push(mn);
            }

            let ctx = format!("iter={iter} vals={vals:?}");
            assert_eq!(num(series.cumsum().unwrap().values()), csum, "cumsum {ctx}");
            assert_eq!(
                num(series.cumprod().unwrap().values()),
                cprod,
                "cumprod {ctx}"
            );
            assert_eq!(num(series.cummax().unwrap().values()), cmax, "cummax {ctx}");
            assert_eq!(num(series.cummin().unwrap().values()), cmin, "cummin {ctx}");
            assert_eq!(series.cumsum().unwrap().len(), n, "len preserved {ctx}");
        }
    }

    #[test]
    fn dataframe_agg_dict_full_reduction_set_dg98v() {
        use std::collections::HashMap;
        // br-frankenpandas-dg98v: validates w46mr — dict-style DataFrame.agg accepts
        // funcs beyond the basic moments (prod/nunique), delegating to Series.agg.
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![Scalar::Int64(2), Scalar::Int64(3), Scalar::Int64(4)],
            )],
        )
        .unwrap();
        let mut funcs: HashMap<String, Vec<String>> = HashMap::new();
        funcs.insert(
            "a".to_string(),
            vec!["prod".to_string(), "sum".to_string(), "nunique".to_string()],
        );
        let agg = df.agg(&funcs).unwrap();
        let col = agg.column("a").expect("a");
        // Rows indexed by function name (all_funcs order). Map label -> value.
        let labels = agg.index().labels();
        let geti = |name: &str| -> i64 {
            let pos = labels
                .iter()
                .position(|l| matches!(l, IndexLabel::Utf8(s) if s == name))
                .expect("func row");
            match &col.values()[pos] {
                Scalar::Int64(v) => *v,
                Scalar::Float64(v) => *v as i64,
                _ => i64::MIN,
            }
        };
        assert_eq!(geti("prod"), 24, "prod=2*3*4 (was rejected pre-w46mr)");
        assert_eq!(geti("sum"), 9);
        assert_eq!(geti("nunique"), 3);
    }

    #[test]
    fn series_agg_size_any_all_tt0bx() {
        // br-frankenpandas-tt0bx: validates the l9cn6 parity fill (size/any/all in agg).
        let series = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Bool(true), Scalar::Bool(false), Scalar::Bool(true)],
        )
        .unwrap();
        let out = series.agg(&["size", "any", "all", "count"]).unwrap();
        assert_eq!(
            out.index().labels(),
            &[
                IndexLabel::Utf8("size".into()),
                IndexLabel::Utf8("any".into()),
                IndexLabel::Utf8("all".into()),
                IndexLabel::Utf8("count".into()),
            ]
        );
        // any/all compute correctly (any=true, all=false). The agg result Column mixes
        // Int64(size/count) with Bool(any/all). pandas returns an object Series
        // [3, True, False, 3]; br-frankenpandas-rh1od's object-bucket preservation
        // now reproduces exactly that instead of coercing bools to 1/0 — the
        // dtype-fidelity gap this test used to document is closed.
        assert_eq!(
            out.values(),
            &[
                Scalar::Int64(3),
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Int64(3),
            ]
        );
    }

    #[test]
    fn series_quantile_interpolation_modes_xw415() {
        // Differential (br-frankenpandas-xw415): quantile across all 5 interpolation
        // modes vs numpy-semantics oracle. Seeded LCG, no mocks.
        let mut st: u64 = 0x40a7_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let getf = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        for iter in 0..500u32 {
            let n = (next() % 8) as usize + 2;
            // Distinct values: shuffled 0..n scaled, no exact data ties.
            let mut vals: Vec<f64> = (0..n).map(|i| i as f64 * 3.0 + 1.0).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                vals.swap(i, j);
            }
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let mut sorted = vals.clone();
            sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

            for &q in &[0.0_f64, 0.1, 0.25, 0.5, 0.75, 0.9, 1.0] {
                let h = q * (n as f64 - 1.0);
                let lo = h.floor() as usize;
                let hi = h.ceil() as usize;
                let frac = h - lo as f64;
                let qm = |m: &str| getf(&series.quantile_with_interpolation(q, m).unwrap());
                assert!(
                    (qm("lower") - sorted[lo]).abs() < 1e-9,
                    "lower iter={iter} q={q}"
                );
                assert!(
                    (qm("higher") - sorted[hi]).abs() < 1e-9,
                    "higher iter={iter} q={q}"
                );
                assert!(
                    (qm("midpoint") - (sorted[lo] + sorted[hi]) / 2.0).abs() < 1e-9,
                    "midpoint iter={iter} q={q}"
                );
                let lin = sorted[lo] + frac * (sorted[hi] - sorted[lo]);
                assert!(
                    (qm("linear") - lin).abs() < 1e-9,
                    "linear iter={iter} q={q}"
                );
                if (frac - 0.5).abs() > 1e-9 {
                    let near = if frac < 0.5 { sorted[lo] } else { sorted[hi] };
                    assert!(
                        (qm("nearest") - near).abs() < 1e-9,
                        "nearest iter={iter} q={q} frac={frac}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_kendall_sign_symmetry_ebao6() {
        // Metamorphic (br-frankenpandas-ebao6): kendall(x,y) == -kendall(x,-y)
        // (negating one variable flips every pair's concordance) and == kendall(y,x)
        // (symmetric). Guards the Knight tau-b impl. Distinct values. Seeded LCG.
        let mut s: u64 = 0x4e3d_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let mk = |v: &[f64]| {
            Series::from_values(
                "s",
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.iter().map(|&x| Scalar::Float64(x)).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        for iter in 0..400u32 {
            let n = (next() % 8) as usize + 3;
            // Distinct x and y to avoid tie-pair adjustments.
            let mut x: Vec<f64> = (0..n).map(|i| i as f64).collect();
            let mut y: Vec<f64> = (0..n).map(|i| i as f64 * 2.0 + 0.5).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                x.swap(i, j);
                let k = (next() as usize) % (i + 1);
                y.swap(i, k);
            }
            let base = mk(&x).corr_kendall(&mk(&y)).unwrap();
            if base.is_nan() {
                continue;
            }
            let yneg: Vec<f64> = y.iter().map(|&v| -v).collect();
            let flipped = mk(&x).corr_kendall(&mk(&yneg)).unwrap();
            let swapped = mk(&y).corr_kendall(&mk(&x)).unwrap();
            assert!(
                (base + flipped).abs() < 1e-9,
                "kendall sign-reversal iter={iter}: base={base} flipped={flipped}"
            );
            assert!(
                (base - swapped).abs() < 1e-9,
                "kendall symmetry iter={iter}: base={base} swapped={swapped}"
            );
        }
    }

    #[test]
    fn series_spearman_monotonic_invariance_jr8zo() {
        // Metamorphic (br-frankenpandas-jr8zo): spearman depends only on rank order,
        // so a strictly-monotonic transform of x (cube) leaves it unchanged (Pearson
        // would not). Distinct values avoid tie subtleties. Seeded LCG, no mocks.
        let mut s: u64 = 0x5be4_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let mk = |v: &[f64]| {
            Series::from_values(
                "s",
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.iter().map(|&x| Scalar::Float64(x)).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        for iter in 0..400u32 {
            let n = (next() % 8) as usize + 3;
            // Distinct x: shuffled centered integers (cube stays strictly monotonic).
            let mut x: Vec<f64> = (0..n).map(|i| i as f64 - (n as f64) / 2.0).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                x.swap(i, j);
            }
            let y: Vec<f64> = (0..n).map(|_| (next() % 100) as f64 / 9.0).collect();
            let base = mk(&x).corr_spearman(&mk(&y)).unwrap();
            if base.is_nan() {
                continue;
            }
            let xc: Vec<f64> = x.iter().map(|&v| v * v * v).collect();
            let trans = mk(&xc).corr_spearman(&mk(&y)).unwrap();
            assert!(
                (base - trans).abs() < 1e-9,
                "spearman monotonic-invariance iter={iter}: base={base} trans={trans}"
            );
        }
    }

