    #[test]
    fn series_corr_shift_invariance_02dmv() {
        // Metamorphic (br-frankenpandas-02dmv): corr is shift-invariant. A two-pass
        // mean-centered cov_components preserves this under a huge constant shift; a
        // one-pass sum(xy)-n*mx*my formula would diverge via catastrophic
        // cancellation. Seeded LCG, no mocks.
        let mut st: u64 = 0xc077_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let mk = |v: &[f64]| {
            Series::from_values(
                "s",
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.iter().map(|&x| Scalar::Float64(x)).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        for iter in 0..400u32 {
            let n = (next() % 8) as usize + 3;
            let x: Vec<f64> = (0..n).map(|_| (next() % 100) as f64 / 7.0).collect();
            // y correlated with x plus noise so corr is well-defined and not ±1 always.
            let y: Vec<f64> = x
                .iter()
                .map(|&xi| 2.0 * xi + ((next() % 40) as f64 / 13.0))
                .collect();
            let base = mk(&x).corr(&mk(&y)).unwrap();
            if base.is_nan() {
                continue;
            }
            let c = 1.0e9_f64;
            let xs: Vec<f64> = x.iter().map(|&v| v + c).collect();
            let ys: Vec<f64> = y.iter().map(|&v| v + c).collect();
            let shifted = mk(&xs).corr(&mk(&ys)).unwrap();
            assert!(
                base <= 1.0 + 1e-9 && base >= -1.0 - 1e-9,
                "corr bounded iter={iter}: {base}"
            );
            assert!(
                (base - shifted).abs() < 1e-6,
                "corr shift-invariance iter={iter}: base={base} shifted={shifted}"
            );
        }
    }

