    #[test]
    fn series_duplicated_keep_variants_d12vq() {
        use std::collections::HashMap;
        // Differential (br-frankenpandas-d12vq): duplicated_keep First/Last/None masks
        // vs oracle. Seeded LCG, no mocks.
        let mut st: u64 = 0x4d12_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let getb = |c: &[Scalar]| -> Vec<bool> {
            c.iter().map(|v| matches!(v, Scalar::Bool(true))).collect()
        };
        for iter in 0..400u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            // First occurrence indices and last occurrence indices + counts.
            let mut first: HashMap<i64, usize> = HashMap::new();
            let mut last: HashMap<i64, usize> = HashMap::new();
            let mut cnt: HashMap<i64, usize> = HashMap::new();
            for i in 0..n {
                first.entry(vals[i]).or_insert(i);
                last.insert(vals[i], i);
                *cnt.entry(vals[i]).or_default() += 1;
            }
            // First: true if not the first occurrence.
            let f = getb(
                series
                    .duplicated_keep(DuplicateKeep::First)
                    .unwrap()
                    .values(),
            );
            let l = getb(
                series
                    .duplicated_keep(DuplicateKeep::Last)
                    .unwrap()
                    .values(),
            );
            let no = getb(
                series
                    .duplicated_keep(DuplicateKeep::None)
                    .unwrap()
                    .values(),
            );
            for i in 0..n {
                assert_eq!(f[i], first[&vals[i]] != i, "dup First iter={iter} i={i}");
                assert_eq!(l[i], last[&vals[i]] != i, "dup Last iter={iter} i={i}");
                assert_eq!(no[i], cnt[&vals[i]] > 1, "dup None iter={iter} i={i}");
            }
        }
    }

    #[test]
    fn series_drop_duplicates_keep_variants_4tad5() {
        use std::collections::HashMap;
        // Differential (br-frankenpandas-4tad5): drop_duplicates_keep across
        // First/Last/None vs order-preserving oracles. Index labels (=positions)
        // verify WHICH rows are kept. Seeded LCG, no mocks.
        let mut s: u64 = 0x4d27_0b1c_2d3e_4f50;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        for iter in 0..400u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let pos_val = |r: &Series| -> Vec<(i64, i64)> {
                r.index()
                    .labels()
                    .iter()
                    .zip(r.values().iter())
                    .map(|(l, v)| {
                        let li = match l {
                            IndexLabel::Int64(k) => *k,
                            _ => i64::MIN,
                        };
                        let vi = match v {
                            Scalar::Int64(k) => *k,
                            _ => i64::MIN,
                        };
                        (li, vi)
                    })
                    .collect()
            };
            // First: keep first occurrence of each value.
            let mut seen = std::collections::HashSet::new();
            let exp_first: Vec<(i64, i64)> = (0..n)
                .filter(|&i| seen.insert(vals[i]))
                .map(|i| (i as i64, vals[i]))
                .collect();
            assert_eq!(
                pos_val(&series.drop_duplicates_keep(DuplicateKeep::First).unwrap()),
                exp_first,
                "First iter={iter}"
            );
            // Last: keep last occurrence (rows whose index is the last for their value).
            let mut last: HashMap<i64, usize> = HashMap::new();
            for i in 0..n {
                last.insert(vals[i], i);
            }
            let exp_last: Vec<(i64, i64)> = (0..n)
                .filter(|&i| last[&vals[i]] == i)
                .map(|i| (i as i64, vals[i]))
                .collect();
            assert_eq!(
                pos_val(&series.drop_duplicates_keep(DuplicateKeep::Last).unwrap()),
                exp_last,
                "Last iter={iter}"
            );
            // None: drop all values that appear more than once.
            let mut cnt: HashMap<i64, usize> = HashMap::new();
            for &v in &vals {
                *cnt.entry(v).or_default() += 1;
            }
            let exp_none: Vec<(i64, i64)> = (0..n)
                .filter(|&i| cnt[&vals[i]] == 1)
                .map(|i| (i as i64, vals[i]))
                .collect();
            assert_eq!(
                pos_val(&series.drop_duplicates_keep(DuplicateKeep::None).unwrap()),
                exp_none,
                "None iter={iter}"
            );
        }
    }

    #[test]
    fn series_argmax_argmin_value_consistency_sg55w() {
        // Cross-op (br-frankenpandas-sg55w): value at argmax==max, at argmin==min.
        // Seeded LCG, no mocks.
        let mut stt: u64 = 0x4a18_0c2d_2d3e_4f50;
        let mut next = || {
            stt = stt
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (stt >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Int64(x) => *x as f64,
                Scalar::Float64(x) => *x,
                _ => f64::NAN,
            }
        };
        for iter in 0..600u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 200) as i64 - 100).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let amax = series.argmax().unwrap() as usize;
            let amin = series.argmin().unwrap() as usize;
            assert!(
                (num(&series.values()[amax]) - num(&series.max().unwrap())).abs() < 1e-9,
                "val@argmax==max iter={iter}"
            );
            assert!(
                (num(&series.values()[amin]) - num(&series.min().unwrap())).abs() < 1e-9,
                "val@argmin==min iter={iter}"
            );
        }
    }

    #[test]
    fn series_min_max_value_skipna_bl04y() {
        // Differential (br-frankenpandas-bl04y): min/max VALUE skip NaN. Seeded LCG.
        let mut st: u64 = 0x4d11_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let num = |s: &Scalar| -> f64 {
            match s {
                Scalar::Float64(x) => *x,
                Scalar::Int64(x) => *x as f64,
                _ => f64::NAN,
            }
        };
        for iter in 0..1000u32 {
            let n = (next() % 10) as usize + 1;
            let vals: Vec<f64> = (0..n)
                .map(|_| {
                    if next() % 4 == 0 {
                        f64::NAN
                    } else {
                        (next() % 200) as f64 - 100.0
                    }
                })
                .collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Float64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let finite: Vec<f64> = vals.iter().copied().filter(|v| !v.is_nan()).collect();
            if finite.is_empty() {
                continue; // all-NaN: min/max undefined, skip
            }
            let exp_min = finite.iter().copied().fold(f64::INFINITY, f64::min);
            let exp_max = finite.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            assert!(
                (num(&series.min().unwrap()) - exp_min).abs() < 1e-9,
                "min iter={iter}"
            );
            assert!(
                (num(&series.max().unwrap()) - exp_max).abs() < 1e-9,
                "max iter={iter}"
            );
        }
    }

    #[test]
    fn series_argsort_permutation_3vpcn() {
        // Differential (br-frankenpandas-3vpcn): argsort returns the index
        // permutation that sorts values. Distinct values. Seeded LCG, no mocks.
        let mut st: u64 = 0xa650_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let geti = |c: &[Scalar]| -> Vec<i64> {
            c.iter()
                .map(|s| match s {
                    Scalar::Int64(v) => *v,
                    _ => i64::MIN,
                })
                .collect()
        };
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 1;
            let mut vals: Vec<i64> = (0..n as i64).collect();
            for i in (1..n).rev() {
                let j = (next() as usize) % (i + 1);
                vals.swap(i, j);
            }
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            let mut idx_asc: Vec<usize> = (0..n).collect();
            idx_asc.sort_by_key(|&i| vals[i]);
            let exp_asc: Vec<i64> = idx_asc.iter().map(|&i| i as i64).collect();
            assert_eq!(
                geti(series.argsort(true).unwrap().values()),
                exp_asc,
                "argsort asc iter={iter}"
            );

            let mut idx_desc: Vec<usize> = (0..n).collect();
            idx_desc.sort_by(|&x, &y| vals[y].cmp(&vals[x]));
            let exp_desc: Vec<i64> = idx_desc.iter().map(|&i| i as i64).collect();
            assert_eq!(
                geti(series.argsort(false).unwrap().values()),
                exp_desc,
                "argsort desc iter={iter}"
            );
        }
    }

    #[test]
    fn series_shift_with_fill_value_f81xx() {
        // Differential (br-frankenpandas-f81xx): shift_with_fill_value fills vacated
        // slots with the value (not NaN), Int64 preserved. Seeded LCG, no mocks.
        let mut st: u64 = 0x5417_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let fill = -99i64;
        for iter in 0..800u32 {
            let n = (next() % 9) as usize + 2;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 50) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            for k in [1i64, 2, -1] {
                let out = series
                    .shift_with_fill_value(k, Scalar::Int64(fill))
                    .unwrap();
                assert_eq!(out.len(), n, "len iter={iter} k={k}");
                for i in 0..n {
                    let src = i as i64 - k;
                    let exp = if src >= 0 && (src as usize) < n {
                        vals[src as usize]
                    } else {
                        fill
                    };
                    assert_eq!(
                        out.values()[i],
                        Scalar::Int64(exp),
                        "shift_fill iter={iter} k={k} i={i}"
                    );
                }
            }
        }
    }

    #[test]
    fn series_shift_diff_match_oracle_2sjc3() {
        // Differential vs index-shift oracle (br-frankenpandas-2sjc3). shift/diff
        // introduce nulls (upcasting Int64 -> Float64), so compare numerically and
        // assert missingness at the expected positions. Seeded LCG, no mocks.
        let mut s: u64 = 0x5b1f_7d1f_0a2b_3c4d;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let as_i64 = |v: &Scalar| -> i64 {
            match v {
                Scalar::Int64(x) => *x,
                Scalar::Float64(x) => *x as i64,
                _ => i64::MIN,
            }
        };
        for iter in 0..1500u32 {
            let n = (next() % 9) as usize + 2;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 11) as i64 - 5).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            // shift(k): out[i] == v[i - k] when in range, else missing.
            for k in [1i64, 2, -1, -2] {
                let out = series.shift(k).unwrap();
                assert_eq!(out.len(), n, "shift len iter={iter} k={k}");
                for i in 0..n {
                    let src = i as i64 - k;
                    let got = &out.values()[i];
                    if src >= 0 && (src as usize) < n {
                        assert!(!got.is_missing(), "shift non-null iter={iter} k={k} i={i}");
                        assert_eq!(
                            as_i64(got),
                            vals[src as usize],
                            "shift val iter={iter} k={k} i={i}"
                        );
                    } else {
                        assert!(got.is_missing(), "shift null iter={iter} k={k} i={i}");
                    }
                }
            }

            // diff(k): out[i] == v[i] - v[i-k] for i >= k, else missing.
            for k in [1i64, 2] {
                let out = series.diff(k).unwrap();
                assert_eq!(out.len(), n, "diff len iter={iter} k={k}");
                for i in 0..n {
                    let src = i as i64 - k;
                    let got = &out.values()[i];
                    if src >= 0 {
                        assert!(!got.is_missing(), "diff non-null iter={iter} k={k} i={i}");
                        assert_eq!(
                            as_i64(got),
                            vals[i] - vals[src as usize],
                            "diff val iter={iter} k={k} i={i}"
                        );
                    } else {
                        assert!(got.is_missing(), "diff null iter={iter} k={k} i={i}");
                    }
                }
            }
        }
    }

    #[test]
    fn series_clip_matches_clamp_oracle_e601i() {
        // Differential vs clamp oracle (br-frankenpandas-e601i). Integer-valued
        // bounds keep Int64 (br-aaa1e); compare numerically. Seeded LCG, no mocks.
        let mut s: u64 = 0xc11b_0a2b_3c4d_5e6f;
        let mut next = || {
            s = s
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (s >> 33) as u32
        };
        let as_i64 = |v: &Scalar| -> i64 {
            match v {
                Scalar::Int64(x) => *x,
                Scalar::Float64(x) => *x as i64,
                _ => i64::MIN,
            }
        };
        let bounds: [(Option<f64>, Option<f64>); 4] = [
            (Some(-2.0), Some(3.0)),
            (Some(0.0), None),
            (None, Some(2.0)),
            (None, None),
        ];
        for iter in 0..1500u32 {
            let n = (next() % 10) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 11) as i64 - 5).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();
            for (lo, hi) in bounds {
                let out = series.clip(lo, hi).unwrap();
                assert_eq!(out.len(), n, "clip len iter={iter} lo={lo:?} hi={hi:?}");
                for i in 0..n {
                    // pandas applies lower then upper.
                    let mut e = vals[i];
                    if let Some(l) = lo {
                        e = e.max(l as i64);
                    }
                    if let Some(u) = hi {
                        e = e.min(u as i64);
                    }
                    assert_eq!(
                        as_i64(&out.values()[i]),
                        e,
                        "clip val iter={iter} lo={lo:?} hi={hi:?} i={i} v={}",
                        vals[i]
                    );
                }
            }
        }
    }

    #[test]
    fn series_duplicated_dropdup_match_oracle_42324() {
        // Differential vs first-seen HashSet oracle (br-frankenpandas-42324).
        // keep='first'. Seeded LCG, no mocks.
        let mut st: u64 = 0xd0b1_1ca7_e2d3_f405;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for iter in 0..1200u32 {
            let n = (next() % 12) as usize + 1;
            let vals: Vec<i64> = (0..n).map(|_| (next() % 5) as i64).collect();
            let series = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                vals.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
            )
            .unwrap();

            // duplicated: true iff the value appeared at an earlier index.
            let dup = series.duplicated().unwrap();
            let mut seen = std::collections::HashSet::new();
            for i in 0..n {
                let is_dup = !seen.insert(vals[i]);
                assert_eq!(
                    dup.values()[i],
                    Scalar::Bool(is_dup),
                    "duplicated iter={iter} i={i} vals={vals:?}"
                );
            }

            // drop_duplicates: first occurrence of each value, in order.
            let dd = series.drop_duplicates().unwrap();
            let mut seen2 = std::collections::HashSet::new();
            let expected: Vec<i64> = vals.iter().copied().filter(|&v| seen2.insert(v)).collect();
            let got: Vec<i64> = dd
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Int64(x) => *x,
                    _ => i64::MIN,
                })
                .collect();
            assert_eq!(got, expected, "drop_duplicates iter={iter} vals={vals:?}");
        }
    }

    #[test]
    fn series_astype_numeric_bool_match_oracle_nks9r() {
        // Differential for Series.astype numeric/bool conversions (br-frankenpandas-nks9r),
        // mirroring cast_scalar rules. Seeded LCG, no mocks.
        let mut st: u64 = 0xa57e_0b1c_2d3e_4f50;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        let mk_i = |v: &[i64]| {
            Series::from_values(
                "x",
                (0..v.len() as i64).map(Into::into).collect::<Vec<_>>(),
                v.iter().map(|&x| Scalar::Int64(x)).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        for iter in 0..1200u32 {
            let n = (next() % 8) as usize + 1;
            let ints: Vec<i64> = (0..n).map(|_| (next() % 7) as i64 - 3).collect();
            let isr = mk_i(&ints);

            // Int64 -> Float64, Int64 -> Bool.
            let to_f = isr.astype(DType::Float64).unwrap();
            let to_b = isr.astype(DType::Bool).unwrap();
            for i in 0..n {
                assert_eq!(
                    to_f.values()[i],
                    Scalar::Float64(ints[i] as f64),
                    "i->f iter={iter} i={i}"
                );
                assert_eq!(
                    to_b.values()[i],
                    Scalar::Bool(ints[i] != 0),
                    "i->bool iter={iter} i={i}"
                );
            }

            // Float64 -> Int64 (truncation toward zero).
            let floats: Vec<f64> = (0..n)
                .map(|_| ((next() % 200) as f64 - 100.0) / 4.0)
                .collect();
            let fsr = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                floats
                    .iter()
                    .map(|&x| Scalar::Float64(x))
                    .collect::<Vec<_>>(),
            )
            .unwrap();
            let to_i = fsr.astype(DType::Int64).unwrap();
            for i in 0..n {
                assert_eq!(
                    to_i.values()[i],
                    Scalar::Int64(floats[i] as i64),
                    "f->i iter={iter} i={i} f={}",
                    floats[i]
                );
            }

            // Bool -> Int64.
            let bools: Vec<bool> = (0..n).map(|_| next() % 2 == 0).collect();
            let bsr = Series::from_values(
                "x",
                (0..n as i64).map(Into::into).collect::<Vec<_>>(),
                bools.iter().map(|&x| Scalar::Bool(x)).collect::<Vec<_>>(),
            )
            .unwrap();
            let b_to_i = bsr.astype(DType::Int64).unwrap();
            for i in 0..n {
                assert_eq!(
                    b_to_i.values()[i],
                    Scalar::Int64(bools[i] as i64),
                    "bool->i iter={iter} i={i}"
                );
            }
        }
    }

    #[test]
    fn series_str_strip_case_match_oracle_wwzve() {
        // Differential for StringAccessor whitespace/case ops (br-frankenpandas-wwzve).
        // ASCII + space only. Seeded LCG, no mocks.
        const ALPHA: [char; 6] = [' ', 'a', 'b', 'A', 'B', 'c'];
        let mut st: u64 = 0x577a_1c2b_3d4e_5f60;
        let mut next = || {
            st = st
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (st >> 33) as u32
        };
        for _iter in 0..1000u32 {
            let rows = (next() % 6) as usize + 1;
            let strs: Vec<String> = (0..rows)
                .map(|_| {
                    let slen = (next() % 7) as usize;
                    (0..slen)
                        .map(|_| ALPHA[(next() as usize) % ALPHA.len()])
                        .collect()
                })
                .collect();
            let series = Series::from_values(
                "s",
                (0..rows as i64).map(Into::into).collect::<Vec<_>>(),
                strs.iter()
                    .map(|s| Scalar::Utf8(s.clone()))
                    .collect::<Vec<_>>(),
            )
            .unwrap();

            let strip = series.str().strip().unwrap();
            let lstrip = series.str().lstrip().unwrap();
            let rstrip = series.str().rstrip().unwrap();
            let swap = series.str().swapcase().unwrap();
            let cap = series.str().capitalize().unwrap();
            for i in 0..rows {
                let s = &strs[i];
                assert_eq!(
                    strip.values()[i],
                    Scalar::Utf8(s.trim().to_string()),
                    "strip i={i} s={s:?}"
                );
                assert_eq!(
                    lstrip.values()[i],
                    Scalar::Utf8(s.trim_start().to_string()),
                    "lstrip i={i} s={s:?}"
                );
                assert_eq!(
                    rstrip.values()[i],
                    Scalar::Utf8(s.trim_end().to_string()),
                    "rstrip i={i} s={s:?}"
                );
                let sw: String = s
                    .chars()
                    .map(|c| {
                        if c.is_ascii_uppercase() {
                            c.to_ascii_lowercase()
                        } else if c.is_ascii_lowercase() {
                            c.to_ascii_uppercase()
                        } else {
                            c
                        }
                    })
                    .collect();
                assert_eq!(swap.values()[i], Scalar::Utf8(sw), "swapcase i={i} s={s:?}");
                let capexp = if s.is_empty() {
                    String::new()
                } else {
                    let mut it = s.chars();
                    let first = it.next().unwrap().to_ascii_uppercase();
                    let rest = it.collect::<String>().to_ascii_lowercase();
                    format!("{first}{rest}")
                };
                assert_eq!(
                    cap.values()[i],
                    Scalar::Utf8(capexp),
                    "capitalize i={i} s={s:?}"
                );
            }
        }
    }

