    #[test]
    fn kendall_word_blocked_rank_counter_matches_fenwick_boundaries() {
        fn shuffled_rows(len: usize, salt: u64) -> Vec<u32> {
            fn mix(mut z: u64) -> u64 {
                z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
                z ^ (z >> 31)
            }

            let mut rows: Vec<u32> = (0..len as u32).collect();
            rows.sort_by_key(|&row| mix(u64::from(row).wrapping_add(salt)));
            rows
        }

        for len in [0_usize, 1, 2, 63, 64, 65, 127, 128, 129, 257, 1024] {
            let x_order = shuffled_rows(len, 0x1234);
            let y_order = shuffled_rows(len, 0x9abc);
            let y_rank_by_row = Series::kendall_rank_by_row_from_order(&y_order);

            let word_blocked =
                Series::count_ordered_rank_inversions_word_blocks(&x_order, &y_rank_by_row)
                    .unwrap();
            let fenwick =
                Series::count_ordered_rank_inversions_fenwick(&x_order, &y_rank_by_row).unwrap();
            assert_eq!(word_blocked, fenwick, "len={len}");
        }

        let duplicate_rank = vec![0_u32, 0, 2];
        assert!(
            Series::count_ordered_rank_inversions_word_blocks(&[0, 1, 2], &duplicate_rank)
                .is_none()
        );
        assert_eq!(
            Series::count_ordered_rank_inversions(&[0, 1, 2], &duplicate_rank),
            Series::count_ordered_rank_inversions_fenwick(&[0, 1, 2], &duplicate_rank)
        );
    }

    #[test]
    fn complete_kendall_parallel_matrix_matches_serial_ordered_ranks() {
        let cols = 16_usize;
        let rows = 512_usize;
        let mut orders = Vec::with_capacity(cols);
        let mut ranks_by_row = Vec::with_capacity(cols);
        for col in 0..cols {
            let multiplier = 2 * col + 1;
            let values: Vec<f64> = (0..rows)
                .map(|row| ((row * multiplier + col * 17) % rows) as f64)
                .collect();
            let order = Series::kendall_no_tie_order(&values).unwrap();
            ranks_by_row.push(Some(Series::kendall_rank_by_row_from_order(&order)));
            orders.push(Some(order));
        }

        let Some(mat) = super::complete_kendall_no_tie_parallel_matrix(&orders, &ranks_by_row)
        else {
            return;
        };
        for i in 0..cols {
            assert_eq!(mat[i * cols + i].to_bits(), 1.0_f64.to_bits());
            for j in (i + 1)..cols {
                let serial = Series::kendall_no_tie_fast_with_ordered_ranks(
                    orders[i].as_deref().unwrap(),
                    ranks_by_row[j].as_deref().unwrap(),
                )
                .unwrap();
                assert_eq!(mat[i * cols + j].to_bits(), serial.to_bits());
                assert_eq!(mat[j * cols + i].to_bits(), serial.to_bits());
            }
        }
    }

    #[test]
    fn dataframe_corr_spearman() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "x",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                ],
            )
            .unwrap(),
            Series::from_values(
                "y",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let result = df.corr_method("spearman").unwrap();
        // Self-correlation = 1.0
        assert_eq!(result.columns["x"].values()[0], Scalar::Float64(1.0));
        assert_eq!(result.columns["y"].values()[1], Scalar::Float64(1.0));
        // Cross-correlation should be 1.0 for perfectly monotonic data
        let xy = expect_float64(&result.columns["y"].values()[0]);
        assert!((xy - 1.0).abs() < 1e-10);
    }

    #[test]
    fn dataframe_corr_kendall_dense_path_preserves_order_and_values() {
        let labels = vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()];
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "z",
                labels.clone(),
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
            Series::from_values(
                "a",
                labels.clone(),
                vec![
                    Scalar::Float64(40.0),
                    Scalar::Float64(30.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(10.0),
                ],
            )
            .unwrap(),
            Series::from_values(
                "m",
                labels,
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let result = df.corr_method("kendall").unwrap();
        let names: Vec<&str> = result
            .column_names()
            .into_iter()
            .map(String::as_str)
            .collect();
        assert_eq!(names, vec!["z", "a", "m"]);
        assert_eq!(result.columns["z"].values()[0], Scalar::Float64(1.0));
        assert_eq!(result.columns["a"].values()[1], Scalar::Float64(1.0));
        assert_eq!(result.columns["m"].values()[2], Scalar::Float64(1.0));
        assert_eq!(expect_float64(&result.columns["a"].values()[0]), -1.0);
        assert_eq!(expect_float64(&result.columns["z"].values()[1]), -1.0);

        let tau = expect_float64(&result.columns["m"].values()[0]);
        assert!((tau - (2.0 / 3.0)).abs() < 1e-12);
        assert_eq!(
            expect_float64(&result.columns["z"].values()[2]).to_bits(),
            tau.to_bits()
        );
    }

    #[test]
    fn dataframe_groupby_apply() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "grp",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("a".into()),
                    Scalar::Utf8("a".into()),
                    Scalar::Utf8("b".into()),
                    Scalar::Utf8("b".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                    Scalar::Float64(40.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        // Apply a function that returns the sum of each group as a single-row DataFrame
        let result = df
            .groupby(&["grp"])
            .unwrap()
            .apply(|group_df| {
                // Sum the 'val' column
                let col = &group_df.columns["val"];
                let total: f64 = col.values().iter().filter_map(|v| v.to_f64().ok()).sum();
                let mut cols = BTreeMap::new();
                cols.insert(
                    "val".to_string(),
                    super::Column::from_values(vec![Scalar::Float64(total)]).unwrap(),
                );
                Ok(DataFrame::new_with_column_order(
                    super::Index::new(vec![0_i64.into()]),
                    cols,
                    vec!["val".to_string()],
                )
                .unwrap())
            })
            .unwrap();

        assert_eq!(result.len(), 2);
        assert_eq!(result.columns["val"].values()[0], Scalar::Float64(30.0)); // 10+20
        assert_eq!(result.columns["val"].values()[1], Scalar::Float64(70.0)); // 30+40
    }

    #[test]
    fn dataframe_groupby_apply_expands_multirow_frames_with_group_index() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "grp",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Utf8("a".into()),
                    Scalar::Utf8("a".into()),
                    Scalar::Utf8("b".into()),
                    Scalar::Utf8("b".into()),
                ],
            )
            .unwrap(),
            Series::from_values(
                "val",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(20.0),
                    Scalar::Float64(30.0),
                    Scalar::Float64(40.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let result = df
            .groupby(&["grp"])
            .unwrap()
            .apply(|group_df| group_df.select_columns(&["val"]))
            .unwrap();

        assert_eq!(result.len(), 4);
        assert_eq!(
            result.columns["val"].values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
                Scalar::Float64(40.0),
            ]
        );
        let row_multiindex = result.row_multiindex.as_ref().unwrap();
        assert_eq!(row_multiindex.nlevels(), 2);
        assert_eq!(
            row_multiindex.names(),
            &[Some("grp".to_owned()), Some("index".to_owned())]
        );
        let first_tuple = row_multiindex.get_tuple(0).unwrap();
        assert_eq!(first_tuple[0], &IndexLabel::Utf8("a".to_owned()));
        assert_eq!(first_tuple[1], &IndexLabel::Int64(0));
        let last_tuple = row_multiindex.get_tuple(3).unwrap();
        assert_eq!(last_tuple[0], &IndexLabel::Utf8("b".to_owned()));
        assert_eq!(last_tuple[1], &IndexLabel::Int64(3));
    }

