    // ── DataFrame.to_dict tests ──

    #[test]
    fn dataframe_to_dict_default() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "a",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Int64(10), Scalar::Int64(20)],
            )
            .unwrap(),
        ])
        .unwrap();
        let result = df.to_dict("dict").unwrap();
        let (keys, values) = result
            .as_mapping()
            .expect("dict orient should return mapping");
        assert!(values.contains_key("a"));
        assert_eq!(values["a"].len(), 2);
        assert_eq!(keys.len(), 2); // shared index labels carried once
    }

    #[test]
    fn to_dict_dict_parallel_keys_match_serial_prefix_ironquail() {
        // Key i = the string of index label i; independent per row. The 40k frame
        // builds keys via the SERIAL path (< KEYS_PAR_MIN_ROWS); the 60k via the
        // CHUNKED-PARALLEL path. The 60k keys must have the 40k keys as an exact
        // prefix, and each column's values likewise.
        let mk = |n: usize| -> DataFrame {
            let mut cols = BTreeMap::new();
            cols.insert(
                "a".to_string(),
                Column::from_i64_values((0..n as i64).collect()),
            );
            DataFrame::new_with_column_order(
                Index::from_range(0, n as i64, 1),
                cols,
                vec!["a".to_string()],
            )
            .unwrap()
        };
        let small = mk(40_000).to_dict("dict").unwrap();
        let large = mk(60_000).to_dict("dict").unwrap();
        let (ks, vs) = small.as_mapping().expect("mapping");
        let (kl, vl) = large.as_mapping().expect("mapping");
        assert_eq!(ks.len(), 40_000);
        assert_eq!(kl.len(), 60_000);
        assert_eq!(&kl[..40_000], ks, "parallel dict keys diverge from serial");
        assert_eq!(
            &vl["a"][..40_000],
            vs["a"].as_slice(),
            "dict values prefix mismatch"
        );
    }

    #[test]
    fn to_dict_dict_parallel_matches_serial_prefix_blackthrush() {
        // The 40k x 3 frame stays below the guarded parallel-cell floor; 60k x 3
        // crosses it. The larger mapping must have the smaller one as an exact
        // key/value prefix for every column.
        let mk = |n: usize| -> DataFrame {
            let mut cols = BTreeMap::new();
            cols.insert(
                "a".to_string(),
                Column::from_i64_values((0..n as i64).collect()),
            );
            cols.insert(
                "b".to_string(),
                Column::from_f64_values((0..n).map(|i| i as f64 * 0.5).collect()),
            );
            cols.insert(
                "c".to_string(),
                Column::from_i64_values((0..n as i64).map(|i| i * 7).collect()),
            );
            DataFrame::new_with_column_order(
                Index::from_range(0, n as i64, 1),
                cols,
                vec!["a".to_string(), "b".to_string(), "c".to_string()],
            )
            .unwrap()
        };
        let small = mk(40_000).to_dict("dict").unwrap();
        let large = mk(60_000).to_dict("dict").unwrap();
        let (ks, vs) = small.as_mapping().expect("dict");
        let (kl, vl) = large.as_mapping().expect("dict");
        assert_eq!(ks.len(), 40_000);
        assert_eq!(kl.len(), 60_000);
        assert_eq!(&kl[..40_000], ks);
        for name in ["a", "b", "c"] {
            assert_eq!(vs[name].len(), 40_000);
            assert_eq!(vl[name].len(), 60_000);
            assert_eq!(&vl[name][..40_000], vs[name].as_slice());
        }
    }

    #[test]
    fn dataframe_to_dict_records() {
        let df = DataFrame::from_dict_with_index(
            vec![
                (
                    "b",
                    vec![Scalar::Utf8("x".into()), Scalar::Utf8("y".into())],
                ),
                ("a", vec![Scalar::Int64(10), Scalar::Null(NullKind::NaN)]),
            ],
            vec![IndexLabel::Int64(10), IndexLabel::Int64(20)],
        )
        .unwrap();
        let result = df.to_dict("records").unwrap();
        let (columns, rows) = result
            .as_records()
            .expect("records orient should return shared columns + row values");
        // Shared-key form: column names carried once, `rows[i][j]` aligned to columns.
        assert_eq!(columns, &["b".to_owned(), "a".to_owned()]);
        assert_eq!(
            rows,
            &[
                vec![Scalar::Utf8("x".into()), Scalar::Int64(10)],
                vec![Scalar::Utf8("y".into()), Scalar::Null(NullKind::NaN)],
            ]
        );
    }

    #[test]
    fn to_dict_records_parallel_matches_serial_prefix_ironquail() {
        // Row i's record depends only on i. The 40k frame builds via the SERIAL path
        // (< RECORDS_PAR_MIN_ROWS); the 60k via the CHUNKED-PARALLEL path. So the 60k
        // records must have the 40k records as an exact prefix, proving the parallel
        // per-row gather + concat is identical to serial across chunk boundaries.
        let mk = |n: usize| -> DataFrame {
            let mut cols = BTreeMap::new();
            cols.insert(
                "a".to_string(),
                Column::from_i64_values((0..n as i64).collect()),
            );
            cols.insert(
                "b".to_string(),
                Column::from_f64_values((0..n).map(|i| i as f64 * 0.5).collect()),
            );
            cols.insert(
                "c".to_string(),
                Column::from_i64_values((0..n as i64).map(|i| i * 7).collect()),
            );
            DataFrame::new_with_column_order(
                Index::from_range(0, n as i64, 1),
                cols,
                vec!["a".to_string(), "b".to_string(), "c".to_string()],
            )
            .unwrap()
        };
        let small = mk(40_000).to_dict("records").unwrap();
        let large = mk(60_000).to_dict("records").unwrap();
        let (cs, rs) = small.as_records().expect("records");
        let (cl, rl) = large.as_records().expect("records");
        assert_eq!(cs, cl);
        assert_eq!(rs.len(), 40_000);
        assert_eq!(rl.len(), 60_000);
        assert_eq!(
            &rl[..40_000],
            rs,
            "parallel records diverge from serial across chunks"
        );
    }

