    #[test]
    fn dataframe_to_dict_index_rejects_duplicate_index() {
        let index = Index::from_i64(vec![1, 2, 1]);
        let mut cols = BTreeMap::new();
        cols.insert(
            "a".to_string(),
            Column::from_values(vec![
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(30),
            ])
            .unwrap(),
        );
        let df = DataFrame::new_with_column_order(index, cols, vec!["a".to_string()]).unwrap();
        let err = df.to_dict("index").unwrap_err();
        assert!(matches!(err, FrameError::CompatibilityRejected(_)));
        let FrameError::CompatibilityRejected(msg) = err else {
            unreachable!();
        };
        assert!(msg.contains("duplicate index labels"));
    }

    #[test]
    fn dataframe_to_dict_index_unique_index_still_works() {
        let index = Index::from_i64(vec![10, 20, 30]);
        let mut cols = BTreeMap::new();
        cols.insert(
            "a".to_string(),
            Column::from_values(vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)])
                .unwrap(),
        );
        let df = DataFrame::new_with_column_order(index, cols, vec!["a".to_string()]).unwrap();
        let result = df.to_dict("index").unwrap();
        let (_keys, values) = result.as_mapping().expect("index orient returns mapping");
        // Three unique row buckets (one per index label).
        assert_eq!(values.len(), 3);
    }

    #[test]
    fn dataframe_to_dict_index_lazy_mapping_materializes_blackthrush() {
        let index = Index::from_i64(vec![10, 20]);
        let mut cols = BTreeMap::new();
        cols.insert(
            "a".to_string(),
            Column::from_values(vec![Scalar::Int64(1), Scalar::Int64(2)]).unwrap(),
        );
        cols.insert(
            "b".to_string(),
            Column::from_values(vec![Scalar::Float64(1.5), Scalar::Float64(2.5)]).unwrap(),
        );
        let df =
            DataFrame::new_with_column_order(index, cols, vec!["a".to_string(), "b".to_string()])
                .unwrap();

        let result = df.to_dict("index").unwrap();
        assert!(matches!(
            result,
            crate::DataFrameDictResult::IndexMappingLazy { .. }
        ));
        let cloned = result.clone();
        assert_eq!(result, cloned);
        let (keys, values) = result.as_mapping().expect("lazy index mapping");
        assert_eq!(keys, &["a".to_string(), "b".to_string()]);
        assert_eq!(values["10"], vec![Scalar::Int64(1), Scalar::Float64(1.5)]);
        assert_eq!(values["20"], vec![Scalar::Int64(2), Scalar::Float64(2.5)]);
    }

    #[test]
    fn dataframe_to_dict_tight_has_pandas_shape() {
        let df = DataFrame::from_dict(
            &["x", "y"],
            vec![
                ("x", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                (
                    "y",
                    vec![Scalar::Utf8("a".into()), Scalar::Utf8("b".into())],
                ),
            ],
        )
        .unwrap();

        let result = df.to_dict("tight").unwrap();
        let tight = result
            .as_tight()
            .expect("tight orient should return structured tight payload");
        assert_eq!(
            tight.columns,
            DataFrameDictAxisLabels::Flat(
                vec![Scalar::Utf8("x".into()), Scalar::Utf8("y".into()),]
            )
        );
        assert_eq!(tight.index, vec![Scalar::Int64(0), Scalar::Int64(1)]);
        // Row-major data: row 0 = [1, "a"], row 1 = [2, "b"]
        assert_eq!(tight.data.len(), 2);
        assert_eq!(
            tight.data[0],
            vec![Scalar::Int64(1), Scalar::Utf8("a".into())]
        );
        assert_eq!(
            tight.data[1],
            vec![Scalar::Int64(2), Scalar::Utf8("b".into())]
        );
        assert_eq!(tight.index_names, vec![None]);
        assert_eq!(tight.column_names, vec![None]);
    }

