    #[test]
    fn dataframe_cumsum_skipna_false_propagates_per_column() {
        // br-frankenpandas-tlhd6 follow-up: DataFrame.cumsum(skipna=False)
        // propagates the first NaN down each column independently. Column "a"
        // has a NaN at row 1 (-> rows 1,2 NaN); column "b" is clean.
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "a",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(3.0),
                ],
            )
            .unwrap(),
            Series::from_values(
                "b",
                vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
                vec![
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(6.0),
                ],
            )
            .unwrap(),
        ])
        .unwrap();

        let out = df.cumsum_with_skipna(false).unwrap();
        let a = out.column_as_series("a").unwrap();
        assert_eq!(a.values()[0], Scalar::Float64(1.0));
        assert!(a.values()[1].is_missing());
        assert!(a.values()[2].is_missing(), "poisoned after NaN");
        let b = out.column_as_series("b").unwrap();
        assert_eq!(b.values()[0], Scalar::Float64(2.0));
        assert_eq!(b.values()[1], Scalar::Float64(6.0));
        assert_eq!(b.values()[2], Scalar::Float64(12.0));

        // skipna=true leaves column "a" row 2 summed (NaN does not poison).
        let kept = df.cumsum_with_skipna(true).unwrap();
        let a_kept = kept.column_as_series("a").unwrap();
        assert_eq!(a_kept.values()[2], Scalar::Float64(4.0));
    }

    #[test]
    fn datetime64_cumulative_extrema_accumulate_and_sum_product_refuse_zrcug() {
        // pandas 2.2.3: Datetime64 cummin/cummax retain their dtype, leave a
        // NaT at its position, and continue the running bound after it. Unlike
        // relative timedeltas, absolute timestamps cannot be summed or
        // multiplied.
        let early = 1_700_000_000_000_000_000_i64;
        let middle = early + 60_000_000_000;
        let late = middle + 60_000_000_000;
        let series = Series::new(
            "when",
            Index::new_known_unique_int64_unit_range(0, 4),
            Column::from_datetime64_values(vec![middle, fp_types::Timestamp::NAT, early, late]),
        )
        .unwrap();

        assert_eq!(
            series.cummax().unwrap().values(),
            &[
                Scalar::Datetime64(middle),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(middle),
                Scalar::Datetime64(late),
            ]
        );
        assert_eq!(
            series.cummin().unwrap().values(),
            &[
                Scalar::Datetime64(middle),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(early),
                Scalar::Datetime64(early),
            ]
        );
        assert!(
            series.cummax_with_skipna(false).unwrap().values()[2].is_missing(),
            "skipna=False propagates the first NaT"
        );

        let frame = DataFrame::from_series(vec![series]).unwrap();
        assert_eq!(
            frame.cummax().unwrap().column("when").unwrap().values(),
            &[
                Scalar::Datetime64(middle),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(middle),
                Scalar::Datetime64(late),
            ]
        );
        assert_eq!(
            frame.cummin().unwrap().column("when").unwrap().values(),
            &[
                Scalar::Datetime64(middle),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(early),
                Scalar::Datetime64(early),
            ]
        );
        assert!(frame.cumsum().is_err(), "Datetime64 cumsum must refuse");
        assert!(frame.cumprod().is_err(), "Datetime64 cumprod must refuse");
    }

    // ── DataFrame.all / .any tests ──

    #[test]
    fn dataframe_all_any() {
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "a",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Bool(true), Scalar::Bool(true)],
            )
            .unwrap(),
            Series::from_values(
                "b",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Bool(true), Scalar::Bool(false)],
            )
            .unwrap(),
        ])
        .unwrap();
        let all_result = df.all().unwrap();
        assert_eq!(all_result.values()[0], Scalar::Bool(true)); // a: all true
        assert_eq!(all_result.values()[1], Scalar::Bool(false)); // b: not all true

        let any_result = df.any().unwrap();
        assert_eq!(any_result.values()[0], Scalar::Bool(true)); // a: any true
        assert_eq!(any_result.values()[1], Scalar::Bool(true)); // b: any true
    }

