    // ── DatetimeAccessor tests ──

    #[test]
    fn dt_accessor_on_typed_datetime64_column() {
        // br-frankenpandas-0ezw7: dt.<x> on a typed Datetime64 (i64 nanos, UTC)
        // column used to ERROR (validate_datetime_dtype rejected it); now it
        // extracts via fp_types::Timestamp. 2021-01-01 00:00:00 UTC =
        // 1_609_459_200 s; +40 days +1h1m1s = 2021-02-10 01:01:01.
        const NS: i64 = 1_000_000_000;
        let ts_a = 1_609_459_200 * NS; // 2021-01-01 00:00:00 (Friday)
        let ts_b = ts_a + (86_400 * 40 + 3_661) * NS; // 2021-02-10 01:01:01 (Wednesday)
        let ts_c = ts_a + 123_456_789; // 2021-01-01 00:00:00.123456789
        let s = Series::from_values(
            "dt",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Datetime64(ts_a),
                Scalar::Datetime64(ts_b),
                Scalar::Datetime64(ts_c),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
            ],
        )
        .unwrap();
        assert_eq!(s.dtype(), DType::Datetime64);

        // This column carries a NaT, so every numeric component is float64 —
        // measured on live pandas 2.2.3, see
        // `dt_numeric_accessors_promote_to_float64_when_a_nat_is_present`
        // (br-frankenpandas-02ijn). These rows previously pinned Int64, which
        // was FrankenPandas' own pre-fix answer.
        let year = s.dt().year().unwrap();
        assert_eq!(year.values()[0], Scalar::Float64(2021.0));
        assert_eq!(year.values()[1], Scalar::Float64(2021.0));
        assert!(year.values()[3].is_missing()); // NaT -> NaN
        let month = s.dt().month().unwrap();
        assert_eq!(month.values()[0], Scalar::Float64(1.0));
        assert_eq!(month.values()[1], Scalar::Float64(2.0));
        let day = s.dt().day().unwrap();
        assert_eq!(day.values()[0], Scalar::Float64(1.0));
        assert_eq!(day.values()[1], Scalar::Float64(10.0));
        let hour = s.dt().hour().unwrap();
        assert_eq!(hour.values()[0], Scalar::Float64(0.0));
        assert_eq!(hour.values()[1], Scalar::Float64(1.0));
        let minute = s.dt().minute().unwrap();
        assert_eq!(minute.values()[1], Scalar::Float64(1.0));
        let second = s.dt().second().unwrap();
        assert_eq!(second.values()[0], Scalar::Float64(0.0));
        assert_eq!(second.values()[1], Scalar::Float64(1.0));

        // dayofweek: pandas Monday=0; 2021-01-01 is Friday (4), 2021-02-10 is
        // Wednesday (2). dayofyear: Jan-01 -> 1, Feb-10 -> 41.
        let dow = s.dt().dayofweek().unwrap();
        assert_eq!(dow.values()[0], Scalar::Float64(4.0));
        assert_eq!(dow.values()[1], Scalar::Float64(2.0));
        let doy = s.dt().dayofyear().unwrap();
        assert_eq!(doy.values()[0], Scalar::Float64(1.0));
        assert_eq!(doy.values()[1], Scalar::Float64(41.0));
        // sub-second components on ts_c (0.123456789 s).
        let micro = s.dt().microsecond().unwrap();
        assert_eq!(micro.values()[2], Scalar::Float64(123_456.0));
        let nano = s.dt().nanosecond().unwrap();
        assert_eq!(nano.values()[2], Scalar::Float64(789.0));

        // i64 + bool components on the typed Datetime64 column. ts_a = Jan 1 2021
        // (Q1, month start, quarter start, year start; not month end / leap).
        // ts_b = Feb 10 2021 (Q1, mid-month; 2021 not leap so Feb has 28 days).
        let quarter = s.dt().quarter().unwrap();
        assert_eq!(quarter.values()[0], Scalar::Float64(1.0));
        assert_eq!(quarter.values()[1], Scalar::Float64(1.0));
        let dim = s.dt().days_in_month().unwrap();
        assert_eq!(dim.values()[0], Scalar::Float64(31.0));
        assert_eq!(dim.values()[1], Scalar::Float64(28.0));
        let leap = s.dt().is_leap_year().unwrap();
        assert_eq!(leap.values()[0], Scalar::Bool(false));
        let ms = s.dt().is_month_start().unwrap();
        assert_eq!(ms.values()[0], Scalar::Bool(true));
        assert_eq!(ms.values()[1], Scalar::Bool(false));
        let me_ = s.dt().is_month_end().unwrap();
        assert_eq!(me_.values()[0], Scalar::Bool(false));
        let qs = s.dt().is_quarter_start().unwrap();
        assert_eq!(qs.values()[0], Scalar::Bool(true));
        assert_eq!(qs.values()[1], Scalar::Bool(false));
        let ys = s.dt().is_year_start().unwrap();
        assert_eq!(ys.values()[0], Scalar::Bool(true));
        assert_eq!(ys.values()[1], Scalar::Bool(false));
        // is_quarter_end / is_year_end (bool) on the typed column. ts_a = Jan 1
        // (neither), ts_b = Feb 10 (neither).
        let qe = s.dt().is_quarter_end().unwrap();
        assert_eq!(qe.values()[0], Scalar::Bool(false));
        assert_eq!(qe.values()[1], Scalar::Bool(false));
        let ye = s.dt().is_year_end().unwrap();
        assert_eq!(ye.values()[0], Scalar::Bool(false));
        assert_eq!(ye.values()[1], Scalar::Bool(false));
        // month_name / day_name (str) on the typed column. ts_a = Friday January,
        // ts_b = Wednesday February.
        let mn = s.dt().month_name().unwrap();
        assert_eq!(mn.values()[0], Scalar::Utf8("January".to_string()));
        assert_eq!(mn.values()[1], Scalar::Utf8("February".to_string()));
        let dn = s.dt().day_name().unwrap();
        assert_eq!(dn.values()[0], Scalar::Utf8("Friday".to_string()));
        assert_eq!(dn.values()[1], Scalar::Utf8("Wednesday".to_string()));
        // date / time / strftime (str) on the typed column. ts_a = 2021-01-01
        // 00:00:00, ts_b = 2021-02-10 01:01:01.
        let date = s.dt().date().unwrap();
        assert_eq!(date.values()[0], Scalar::Utf8("2021-01-01".to_string()));
        assert_eq!(date.values()[1], Scalar::Utf8("2021-02-10".to_string()));
        let time = s.dt().time().unwrap();
        assert_eq!(time.values()[0], Scalar::Utf8("00:00:00".to_string()));
        assert_eq!(time.values()[1], Scalar::Utf8("01:01:01".to_string()));
        let strf = s.dt().strftime("%Y-%m-%d %H:%M:%S").unwrap();
        assert_eq!(
            strf.values()[0],
            Scalar::Utf8("2021-01-01 00:00:00".to_string())
        );
        assert_eq!(
            strf.values()[1],
            Scalar::Utf8("2021-02-10 01:01:01".to_string())
        );
        // floor/ceil/round/normalize on the typed column stay TYPED Datetime64
        // (pandas returns datetime64, not strings). ts_a = 2021-01-01 00:00:00
        // (day-aligned), ts_b = 2021-02-10 01:01:01.
        const DAY: i64 = 86_400 * NS;
        let midnight_b = ts_a + 40 * DAY; // 2021-02-10 00:00:00
        let floor_d = s.dt().floor("D").unwrap();
        assert_eq!(floor_d.dtype(), DType::Datetime64);
        assert_eq!(floor_d.values()[0], Scalar::Datetime64(ts_a));
        assert_eq!(floor_d.values()[1], Scalar::Datetime64(midnight_b));
        let norm = s.dt().normalize().unwrap();
        assert_eq!(norm.values()[1], Scalar::Datetime64(midnight_b));
        // floor("h") on ts_b -> 2021-02-10 01:00:00.
        let floor_h = s.dt().floor("h").unwrap();
        assert_eq!(
            floor_h.values()[1],
            Scalar::Datetime64(midnight_b + 3_600 * NS)
        );
        // round("D") on ts_b (01:01:01 < noon) rounds down to midnight.
        let round_d = s.dt().round("D").unwrap();
        assert_eq!(round_d.values()[1], Scalar::Datetime64(midnight_b));
        // NaT element stays missing across the typed components whose pandas
        // dtype can hold a missing value (numeric -> float64 NaN, object ->
        // None/NaT).
        assert!(quarter.values()[3].is_missing());
        assert!(mn.values()[3].is_missing());
        assert!(dn.values()[3].is_missing());
        assert!(date.values()[3].is_missing());
        assert!(time.values()[3].is_missing());
        // ...but NOT the boolean `dt.is_*` family, which pandas returns as a
        // non-nullable numpy bool array, so NaT reads as False
        // (br-frankenpandas-dt-is-family-nat-false-boqep). This assertion
        // previously required `is_missing()` here and so encoded the very
        // divergence that bead was filed against.
        assert_eq!(ms.values()[3], Scalar::Bool(false));
        assert_eq!(qe.values()[3], Scalar::Bool(false));
        assert_eq!(ye.values()[3], Scalar::Bool(false));
        assert!(strf.values()[3].is_missing());
        assert!(floor_d.values()[3].is_missing());
        assert!(norm.values()[3].is_missing());
    }

    #[test]
    fn dt_year_month_day() {
        let s = Series::from_values(
            "dates",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15".to_string()),
                Scalar::Utf8("2023-12-25".to_string()),
                Scalar::Utf8("2020-01-01".to_string()),
            ],
        )
        .unwrap();

        let year = s.dt().year().unwrap();
        assert_eq!(year.values()[0], Scalar::Int64(2024));
        assert_eq!(year.values()[1], Scalar::Int64(2023));
        assert_eq!(year.values()[2], Scalar::Int64(2020));

        let month = s.dt().month().unwrap();
        assert_eq!(month.values()[0], Scalar::Int64(3));
        assert_eq!(month.values()[1], Scalar::Int64(12));
        assert_eq!(month.values()[2], Scalar::Int64(1));

        let day = s.dt().day().unwrap();
        assert_eq!(day.values()[0], Scalar::Int64(15));
        assert_eq!(day.values()[1], Scalar::Int64(25));
        assert_eq!(day.values()[2], Scalar::Int64(1));
    }

    #[test]
    fn dt_hour_minute_second() {
        // CORRECTED (br-frankenpandas-hzayc). This asserted that a column
        // mixing `T` and space separators parses BOTH rows. It does not: the
        // column is parsed under ONE format guessed from the first element, so
        // the space-separated row is NaT. MEASURED, live pandas 2.2.3:
        //   pd.to_datetime(['2024-03-15T14:30:45', '2023-12-25 08:15:00'],
        //                  errors='coerce')  ->  [Timestamp(...), NaT]
        //   .dt.hour                         ->  [14.0, nan]   float64
        // Both separator forms are still covered — by the two UNIFORM columns
        // below, which is what this test was really exercising.
        let mixed = Series::from_values(
            "times",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15T14:30:45".to_string()),
                Scalar::Utf8("2023-12-25 08:15:00".to_string()),
            ],
        )
        .unwrap();
        let hour = mixed.dt().hour().unwrap();
        assert_eq!(hour.values()[0], Scalar::Float64(14.0));
        assert!(hour.values()[1].is_missing());

        let t_form = Series::from_values(
            "times",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15T14:30:45".to_string()),
                Scalar::Utf8("2023-12-25T08:15:00".to_string()),
            ],
        )
        .unwrap();
        let space_form = Series::from_values(
            "times",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15 14:30:45".to_string()),
                Scalar::Utf8("2023-12-25 08:15:00".to_string()),
            ],
        )
        .unwrap();
        for s in [&t_form, &space_form] {
            let hour = s.dt().hour().unwrap();
            assert_eq!(hour.values()[0], Scalar::Int64(14));
            assert_eq!(hour.values()[1], Scalar::Int64(8));

            let minute = s.dt().minute().unwrap();
            assert_eq!(minute.values()[0], Scalar::Int64(30));
            assert_eq!(minute.values()[1], Scalar::Int64(15));

            let second = s.dt().second().unwrap();
            assert_eq!(second.values()[0], Scalar::Int64(45));
            assert_eq!(second.values()[1], Scalar::Int64(0));
        }
    }

    #[test]
    fn dt_dayofweek() {
        let s = Series::from_values(
            "dates",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15".to_string()), // Friday = 4
                Scalar::Utf8("2024-03-18".to_string()), // Monday = 0
            ],
        )
        .unwrap();

        let dow = s.dt().dayofweek().unwrap();
        assert_eq!(dow.values()[0], Scalar::Int64(4)); // Friday
        assert_eq!(dow.values()[1], Scalar::Int64(0)); // Monday
    }

    #[test]
    fn dt_date_extraction() {
        // CORRECTED with dt_hour_minute_second (br-frankenpandas-hzayc): the
        // mixed-separator column yields ONE date and a gap, and each uniform
        // form still yields both. Measured, live pandas 2.2.3:
        //   pd.to_datetime(['2024-03-15T14:30:45','2023-12-25 08:15:00'],
        //                  errors='coerce')  ->  [Timestamp(...), NaT]
        let mixed = Series::from_values(
            "datetimes",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15T14:30:45".to_string()),
                Scalar::Utf8("2023-12-25 08:15:00".to_string()),
            ],
        )
        .unwrap();
        let dates = mixed.dt().date().unwrap();
        assert_eq!(dates.values()[0], Scalar::Utf8("2024-03-15".to_string()));
        assert!(dates.values()[1].is_missing());

        let uniform = Series::from_values(
            "datetimes",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15T14:30:45".to_string()),
                Scalar::Utf8("2023-12-25T08:15:00".to_string()),
            ],
        )
        .unwrap();
        let dates = uniform.dt().date().unwrap();
        assert_eq!(dates.values()[0], Scalar::Utf8("2024-03-15".to_string()));
        assert_eq!(dates.values()[1], Scalar::Utf8("2023-12-25".to_string()));
    }

    #[test]
    fn dt_with_nulls() {
        let s = Series::from_values(
            "dates",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-03-15".to_string()),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("invalid".to_string()),
            ],
        )
        .unwrap();

        // Two gaps (the null and the unparseable "invalid"), so year is
        // float64. Measured: pd.to_datetime(["2024-03-15", None, "invalid"],
        // errors="coerce").dt.year -> float64 [2024.0, nan, nan].
        // (br-frankenpandas-02ijn)
        let year = s.dt().year().unwrap();
        assert_eq!(year.values()[0], Scalar::Float64(2024.0));
        assert!(year.values()[1].is_missing());
        assert!(year.values()[2].is_missing());
    }

    #[test]
    fn dt_with_timezone() {
        let s = Series::from_values(
            "dates",
            vec![0_i64.into()],
            vec![Scalar::Utf8("2024-03-15T14:30:45+05:30".to_string())],
        )
        .unwrap();

        let hour = s.dt().hour().unwrap();
        assert_eq!(hour.values()[0], Scalar::Int64(14));

        let second = s.dt().second().unwrap();
        assert_eq!(second.values()[0], Scalar::Int64(45));
    }

    // --- Series.map_fn tests ---

    #[test]
    fn series_map_fn_infallible() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();

        let doubled = s
            .map_fn(|v| match v {
                Scalar::Int64(n) => Ok(Scalar::Int64(n * 2)),
                _ => Ok(v.clone()),
            })
            .unwrap();
        assert_eq!(
            doubled.values(),
            &[Scalar::Int64(2), Scalar::Int64(4), Scalar::Int64(6)]
        );
    }

    #[test]
    fn series_map_fn_with_error() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("not_a_number".to_owned())],
        )
        .unwrap();

        let result = s.map_fn(|v| match v {
            Scalar::Int64(n) => Ok(Scalar::Float64(*n as f64)),
            _ => Err(FrameError::CompatibilityRejected(
                "expected Int64".to_owned(),
            )),
        });
        assert!(result.is_err());
    }

    #[test]
    fn series_map_fn_preserves_nulls() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Int64(5), Scalar::Null(NullKind::NaN)],
        )
        .unwrap();

        let out = s
            .map_fn(|v| {
                if v.is_missing() {
                    Ok(Scalar::Int64(-1))
                } else {
                    Ok(v.clone())
                }
            })
            .unwrap();
        assert_eq!(out.values()[0], Scalar::Int64(5));
        assert_eq!(out.values()[1], Scalar::Int64(-1));
    }

