    #[test]
    fn str_islower_isupper() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("hello".to_owned()),
                Scalar::Utf8("HELLO".to_owned()),
                Scalar::Utf8("Hello".to_owned()),
            ],
        )
        .unwrap();

        let lower = s.str().islower().unwrap();
        assert_eq!(lower.values()[0], Scalar::Bool(true));
        assert_eq!(lower.values()[1], Scalar::Bool(false));
        assert_eq!(lower.values()[2], Scalar::Bool(false));

        let upper = s.str().isupper().unwrap();
        assert_eq!(upper.values()[0], Scalar::Bool(false));
        assert_eq!(upper.values()[1], Scalar::Bool(true));
        assert_eq!(upper.values()[2], Scalar::Bool(false));
    }

    #[test]
    fn str_isnumeric() {
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
                5_i64.into(),
            ],
            vec![
                Scalar::Utf8("123".to_owned()),
                Scalar::Utf8("12.3".to_owned()),
                Scalar::Utf8("٣۳𝟠".to_owned()),
                Scalar::Utf8("²①፩".to_owned()),
                Scalar::Utf8("⅕".to_owned()),
                Scalar::Utf8("一二三㊈".to_owned()),
            ],
        )
        .unwrap();

        let result = s.str().isnumeric().unwrap();
        assert_eq!(result.values()[0], Scalar::Bool(true));
        assert_eq!(result.values()[1], Scalar::Bool(false)); // '.' is not numeric
        assert_eq!(result.values()[2], Scalar::Bool(true));
        assert_eq!(result.values()[3], Scalar::Bool(true));
        assert_eq!(result.values()[4], Scalar::Bool(true));
        assert_eq!(result.values()[5], Scalar::Bool(true));
    }

    #[test]
    fn str_isascii() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Utf8("hello".to_owned()),
                Scalar::Utf8("héllo".to_owned()),
                Scalar::Utf8("123".to_owned()),
                Scalar::Utf8("日本語".to_owned()),
            ],
        )
        .unwrap();

        let result = s.str().isascii().unwrap();
        assert_eq!(result.values()[0], Scalar::Bool(true)); // "hello" is ASCII
        assert_eq!(result.values()[1], Scalar::Bool(false)); // "héllo" has non-ASCII
        assert_eq!(result.values()[2], Scalar::Bool(true)); // "123" is ASCII
        assert_eq!(result.values()[3], Scalar::Bool(false)); // Japanese is non-ASCII
    }

    // --- Series binary ops with fill_value tests ---

    #[test]
    fn series_add_fill_basic() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();

        let result = s1.add_fill(&s2, 0.0).unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(11.0)); // 1+10
        assert_eq!(result.values()[1], Scalar::Float64(20.0)); // 0+20 (fill)
        assert_eq!(result.values()[2], Scalar::Float64(3.0)); // 3+0 (fill)
    }

    #[test]
    fn series_div_fill_by_zero_is_inf_not_nan() {
        // pandas div by zero yields +/-inf (sign of the numerator); only 0/0 is
        // NaN — including the fill_value path. Verified vs live pandas 2.2.3.
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(5.0),
                Scalar::Float64(-5.0),
                Scalar::Float64(0.0),
                Scalar::Null(NullKind::NaN), // missing left -> uses fill_value
            ],
        )
        .unwrap();
        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(0.0),
                Scalar::Float64(0.0),
                Scalar::Float64(0.0),
                Scalar::Float64(0.0),
            ],
        )
        .unwrap();
        let r = s1.div_fill(&s2, 1.0).unwrap();
        assert_eq!(r.values()[0], Scalar::Float64(f64::INFINITY)); // 5/0
        assert_eq!(r.values()[1], Scalar::Float64(f64::NEG_INFINITY)); // -5/0
        assert!(
            r.values()[2].is_missing(),
            "0/0 -> NaN, got {:?}",
            r.values()[2]
        );
        // fill path: left missing -> fill(1) / 0 -> +inf
        assert_eq!(r.values()[3], Scalar::Float64(f64::INFINITY));
    }

    #[test]
    fn series_mod_fill_takes_divisor_sign() {
        // pandas .mod uses the DIVISOR's sign (floored remainder), not Rust's
        // dividend-sign %: 3 % -2 == -1. Verified vs live pandas 2.2.3 via the
        // fill_value path (missing left -> fill_value as the dividend).
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Null(NullKind::NaN), Scalar::Float64(-7.0)],
        )
        .unwrap();
        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(-2.0), Scalar::Float64(3.0)],
        )
        .unwrap();
        // idx0: fill(3) % -2 -> -1 ; idx1: -7 % 3 -> 2
        let r = s1
            .binary_op_fill(&s2, fp_columnar::ArithmeticOp::Mod, 3.0)
            .unwrap();
        assert_eq!(r.values()[0], Scalar::Float64(-1.0));
        assert_eq!(r.values()[1], Scalar::Float64(2.0));
    }

    #[test]
    fn series_add_fill_sorts_unique_outer_union_index() {
        let s1 = Series::from_values(
            "a",
            vec![3_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(30.0), Scalar::Float64(10.0)],
        )
        .unwrap();

        let s2 = Series::from_values("b", vec![2_i64.into()], vec![Scalar::Float64(2.0)]).unwrap();

        let result = s1.add_fill(&s2, 0.0).unwrap();
        assert_eq!(
            result.index().labels(),
            &[1_i64.into(), 2_i64.into(), 3_i64.into()]
        );
        assert_eq!(
            result.values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Float64(2.0),
                Scalar::Float64(30.0)
            ]
        );
    }

    #[test]
    fn series_add_fill_sorted_unique_preserves_shared_index_name()
    -> Result<(), Box<dyn std::error::Error>> {
        let s1 = Series::new(
            "a",
            Index::new(vec![0_i64.into(), 2_i64.into()]).rename_index(Some("idx")),
            Column::from_values(vec![Scalar::Float64(10.0), Scalar::Float64(20.0)])?,
        )?;
        let s2 = Series::new(
            "b",
            Index::new(vec![1_i64.into(), 2_i64.into()]).rename_index(Some("idx")),
            Column::from_values(vec![Scalar::Float64(1.0), Scalar::Float64(2.0)])?,
        )?;

        let result = s1.add_fill(&s2, 0.0)?;

        assert_eq!(
            result.index().labels(),
            &[0_i64.into(), 1_i64.into(), 2_i64.into()]
        );
        assert_eq!(result.index().name(), Some("idx"));
        assert_eq!(
            result.values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Float64(1.0),
                Scalar::Float64(22.0)
            ]
        );
        Ok(())
    }

    #[test]
    fn series_add_fill_both_nan() {
        let s1 = Series::from_values("a", vec![0_i64.into()], vec![Scalar::Null(NullKind::NaN)])
            .unwrap();

        let s2 = Series::from_values("b", vec![0_i64.into()], vec![Scalar::Null(NullKind::NaN)])
            .unwrap();

        let result = s1.add_fill(&s2, 0.0).unwrap();
        assert!(result.values()[0].is_missing()); // both NaN → NaN
    }

    #[test]
    fn series_sub_fill() {
        let s1 = Series::from_values("a", vec![0_i64.into()], vec![Scalar::Null(NullKind::NaN)])
            .unwrap();

        let s2 = Series::from_values("b", vec![0_i64.into()], vec![Scalar::Float64(5.0)]).unwrap();

        let result = s1.sub_fill(&s2, 10.0).unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(5.0)); // 10-5
    }

    #[test]
    fn series_modulo_basic() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(10.0), Scalar::Float64(7.0)],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(3.0), Scalar::Float64(4.0)],
        )
        .unwrap();

        let result = s1.modulo(&s2).unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(1.0)); // 10 % 3
        assert_eq!(result.values()[1], Scalar::Float64(3.0)); // 7 % 4
    }

    #[test]
    fn series_pow_basic() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(2.0), Scalar::Float64(3.0)],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(3.0), Scalar::Float64(2.0)],
        )
        .unwrap();

        let result = s1.pow(&s2).unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(8.0)); // 2^3
        assert_eq!(result.values()[1], Scalar::Float64(9.0)); // 3^2
    }

    #[test]
    fn series_divmod_returns_floordiv_and_mod() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(10.0), Scalar::Float64(7.0)],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(3.0), Scalar::Float64(4.0)],
        )
        .unwrap();

        let (q, r) = s1.divmod(&s2).unwrap();
        assert_eq!(q.values()[0], Scalar::Float64(3.0)); // 10 // 3
        assert_eq!(q.values()[1], Scalar::Float64(1.0)); // 7 // 4
        assert_eq!(r.values()[0], Scalar::Float64(1.0)); // 10 % 3
        assert_eq!(r.values()[1], Scalar::Float64(3.0)); // 7 % 4
    }

    #[test]
    fn series_divmod_matches_scalar_operators() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(15.0),
                Scalar::Float64(22.0),
                Scalar::Float64(9.0),
            ],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();

        let (q, r) = s1.divmod(&s2).unwrap();
        let q_expected = s1.floordiv(&s2).unwrap();
        let r_expected = s1.modulo(&s2).unwrap();
        assert_eq!(q.values(), q_expected.values());
        assert_eq!(r.values(), r_expected.values());
    }

    #[test]
    fn series_rdivmod_swaps_operands() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(3.0), Scalar::Float64(4.0)],
        )
        .unwrap();

        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(10.0), Scalar::Float64(7.0)],
        )
        .unwrap();

        let (q, r) = s1.rdivmod(&s2).unwrap();
        assert_eq!(q.values()[0], Scalar::Float64(3.0)); // 10 // 3
        assert_eq!(q.values()[1], Scalar::Float64(1.0)); // 7 // 4
        assert_eq!(r.values()[0], Scalar::Float64(1.0)); // 10 % 3
        assert_eq!(r.values()[1], Scalar::Float64(3.0)); // 7 % 4
    }

    // --- DataFrame.select_dtypes & filter_labels tests ---

    #[test]
    fn dataframe_select_dtypes_include() {
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("b", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)]),
                (
                    "c",
                    vec![Scalar::Utf8("x".to_owned()), Scalar::Utf8("y".to_owned())],
                ),
            ],
        )
        .unwrap();

        let numeric = df
            .select_dtypes(&[DType::Int64, DType::Float64], &[])
            .unwrap();
        assert_eq!(numeric.num_columns(), 2);
        let names: Vec<&str> = numeric
            .column_names()
            .into_iter()
            .map(String::as_str)
            .collect();
        assert_eq!(names, vec!["a", "b"]);
    }

    #[test]
    fn dataframe_select_dtypes_exclude() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Int64(1)]),
                ("b", vec![Scalar::Utf8("x".to_owned())]),
            ],
        )
        .unwrap();

        let non_string = df.select_dtypes(&[], &[DType::Utf8]).unwrap();
        assert_eq!(non_string.num_columns(), 1);
        assert!(non_string.column("a").is_some());
    }

    #[test]
    fn dataframe_select_dtypes_by_name_number_alias() {
        let df = DataFrame::from_dict(
            &["a", "b", "c", "d"],
            vec![
                ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("b", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)]),
                (
                    "c",
                    vec![Scalar::Utf8("x".to_owned()), Scalar::Utf8("y".to_owned())],
                ),
                ("d", vec![Scalar::Bool(true), Scalar::Bool(false)]),
            ],
        )
        .unwrap();

        let numeric = df.select_dtypes_by_name(&["number"], &[]).unwrap();
        let names: Vec<&str> = numeric
            .column_names()
            .into_iter()
            .map(String::as_str)
            .collect();
        assert_eq!(names, vec!["a", "b"]);
    }

    #[test]
    fn dataframe_select_dtypes_by_name_object_exclude() {
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                ("a", vec![Scalar::Int64(1)]),
                ("b", vec![Scalar::Float64(1.0)]),
                ("c", vec![Scalar::Utf8("x".to_owned())]),
            ],
        )
        .unwrap();

        let non_object = df.select_dtypes_by_name(&[], &["object"]).unwrap();
        assert_eq!(non_object.num_columns(), 2);
        assert!(non_object.column("c").is_none());
    }

    #[test]
    fn dataframe_select_dtypes_by_name_unknown_alias_errors() {
        let df = DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Int64(1)])]).unwrap();

        let err = df.select_dtypes_by_name(&["complex"], &[]).unwrap_err();
        assert!(matches!(err, FrameError::CompatibilityRejected(_)));
    }

    #[test]
    fn dataframe_select_dtypes_by_name_overlap_errors() {
        let df = DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Int64(1)])]).unwrap();

        let err = df
            .select_dtypes_by_name(&["int"], &["integer"])
            .unwrap_err();
        assert!(matches!(err, FrameError::CompatibilityRejected(_)));
    }

    #[test]
    fn dataframe_select_dtypes_by_name_multiple_aliases_dedup() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Int64(1)]),
                ("b", vec![Scalar::Float64(1.0)]),
            ],
        )
        .unwrap();

        // "int" and "integer" are aliases for DType::Int64; should dedupe.
        let ints = df.select_dtypes_by_name(&["int", "integer"], &[]).unwrap();
        assert_eq!(ints.num_columns(), 1);
        assert!(ints.column("a").is_some());
    }

    #[test]
