    #[test]
    fn series_interpolate_basic() {
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(0.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();

        let result = s.interpolate().unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(0.0));
        assert_eq!(result.values()[4], Scalar::Float64(4.0));

        // Interior points: 1.0, 2.0, 3.0
        let v1 = result.values()[1].to_f64().unwrap();
        let v2 = result.values()[2].to_f64().unwrap();
        let v3 = result.values()[3].to_f64().unwrap();
        assert!((v1 - 1.0).abs() < 1e-10);
        assert!((v2 - 2.0).abs() < 1e-10);
        assert!((v3 - 3.0).abs() < 1e-10);
    }

    #[test]
    fn series_interpolate_leading_trailing_nan() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();

        let result = s.interpolate().unwrap();
        // pandas default limit_direction='forward': LEADING NaN stays NaN, but
        // a TRAILING NaN is forward-filled with the last valid value.
        // Verified vs pandas 2.2.3: [NaN,10,20,NaN] -> [NaN,10,20,20].
        assert!(result.values()[0].is_missing());
        assert_eq!(result.values()[1], Scalar::Float64(10.0));
        assert_eq!(result.values()[2], Scalar::Float64(20.0));
        assert_eq!(result.values()[3], Scalar::Float64(20.0));
    }

    #[test]
    fn series_interpolate_interior_then_trailing_forward_fills() {
        // [1,NaN,3,NaN,NaN] -> [1,2,3,3,3]: interior gap interpolated, trailing
        // gap forward-filled (no extrapolation). Verified vs pandas 2.2.3.
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(3.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        let r = s.interpolate().unwrap();
        let got: Vec<f64> = r
            .values()
            .iter()
            .map(|v| match v {
                Scalar::Float64(x) => *x,
                other => panic!("expected float, got {other:?}"),
            })
            .collect();
        assert_eq!(got, [1.0, 2.0, 3.0, 3.0, 3.0]);
    }

