    #[test]
    fn series_interpolate_with_limit_caps_consecutive_fills() {
        // br-frankenpandas-su1dm: limit caps how many consecutive NaN fill from
        // the preceding anchor (default forward direction). Expected values
        // verified vs pandas 2.2.3.
        let mk = |vals: Vec<Scalar>| {
            Series::from_values(
                "x",
                (0..vals.len() as i64)
                    .map(IndexLabel::from)
                    .collect::<Vec<_>>(),
                vals,
            )
            .unwrap()
        };
        let nan = || Scalar::Null(NullKind::NaN);
        let f = Scalar::Float64;

        // [1,NaN,NaN,4,NaN] linear: limit=1 -> [1,2,NaN,4,4]; limit=2 -> [1,2,3,4,4].
        let s = mk(vec![f(1.0), nan(), nan(), f(4.0), nan()]);
        let lim1 = s.interpolate_with_limit("linear", 1).unwrap();
        assert_eq!(lim1.values()[1], f(2.0));
        assert!(lim1.values()[2].is_missing(), "beyond limit");
        assert_eq!(lim1.values()[3], f(4.0));
        assert_eq!(lim1.values()[4], f(4.0)); // trailing carry within limit
        let lim2 = s.interpolate_with_limit("linear", 2).unwrap();
        assert_eq!(lim2.values()[2], f(3.0));

        // pad method with limit=1 -> [1,1,NaN,4,4].
        let pad = s.interpolate_with_limit("pad", 1).unwrap();
        assert_eq!(pad.values()[1], f(1.0));
        assert!(pad.values()[2].is_missing());

        // Leading gap stays missing (forward never fills before the first anchor).
        let lead = mk(vec![nan(), nan(), f(3.0), nan(), f(5.0)]);
        let out = lead.interpolate_with_limit("linear", 1).unwrap();
        assert!(out.values()[0].is_missing());
        assert!(out.values()[1].is_missing());
        assert_eq!(out.values()[3], f(4.0));
    }

    #[test]
    fn series_interpolate_limit_direction_matches_pandas() {
        // br-frankenpandas-su1dm: limit_direction backward/both. Series
        // [NaN,NaN,3,NaN,NaN,6,NaN] (leading + interior + trailing gaps). All
        // expected values verified vs pandas 2.2.3.
        let nan = || Scalar::Null(NullKind::NaN);
        let f = Scalar::Float64;
        let s = Series::from_values(
            "x",
            (0..7_i64).map(IndexLabel::from).collect::<Vec<_>>(),
            vec![nan(), nan(), f(3.0), nan(), nan(), f(6.0), nan()],
        )
        .unwrap();
        let m = |v: &Series| -> Vec<Option<f64>> {
            v.values()
                .iter()
                .map(|x| {
                    if x.is_missing() {
                        None
                    } else {
                        x.to_f64().ok()
                    }
                })
                .collect()
        };
        // forward (no limit) == the bare interpolate().
        assert_eq!(
            m(&s.interpolate_with_direction(None, "forward").unwrap()),
            m(&s.interpolate().unwrap())
        );
        assert_eq!(
            m(&s.interpolate_with_direction(None, "forward").unwrap()),
            vec![
                None,
                None,
                Some(3.0),
                Some(4.0),
                Some(5.0),
                Some(6.0),
                Some(6.0)
            ]
        );
        assert_eq!(
            m(&s.interpolate_with_direction(None, "backward").unwrap()),
            vec![
                Some(3.0),
                Some(3.0),
                Some(3.0),
                Some(4.0),
                Some(5.0),
                Some(6.0),
                None
            ]
        );
        assert_eq!(
            m(&s.interpolate_with_direction(None, "both").unwrap()),
            vec![
                Some(3.0),
                Some(3.0),
                Some(3.0),
                Some(4.0),
                Some(5.0),
                Some(6.0),
                Some(6.0)
            ]
        );
        assert_eq!(
            m(&s.interpolate_with_direction(Some(1), "backward").unwrap()),
            vec![None, Some(3.0), Some(3.0), None, Some(5.0), Some(6.0), None]
        );
        assert_eq!(
            m(&s.interpolate_with_direction(Some(1), "both").unwrap()),
            vec![
                None,
                Some(3.0),
                Some(3.0),
                Some(4.0),
                Some(5.0),
                Some(6.0),
                Some(6.0)
            ]
        );
        assert!(s.interpolate_with_direction(None, "sideways").is_err());
    }

    #[test]
    fn series_interpolate_limit_area_matches_pandas() {
        // br-frankenpandas-su1dm: limit_area restricts which gaps fill.
        // [NaN,NaN,3,NaN,NaN,6,NaN]: inside=interior only, outside=edges only.
        // Verified vs pandas 2.2.3.
        let nan = || Scalar::Null(NullKind::NaN);
        let f = Scalar::Float64;
        let s = Series::from_values(
            "x",
            (0..7_i64).map(IndexLabel::from).collect::<Vec<_>>(),
            vec![nan(), nan(), f(3.0), nan(), nan(), f(6.0), nan()],
        )
        .unwrap();
        let m = |v: &Series| -> Vec<Option<f64>> {
            v.values()
                .iter()
                .map(|x| {
                    if x.is_missing() {
                        None
                    } else {
                        x.to_f64().ok()
                    }
                })
                .collect()
        };
        // inside (both direction): only the interior gap fills.
        assert_eq!(
            m(&s.interpolate_with_options(None, "both", Some("inside"))
                .unwrap()),
            vec![None, None, Some(3.0), Some(4.0), Some(5.0), Some(6.0), None]
        );
        // outside (both direction): only the leading + trailing edge gaps fill.
        assert_eq!(
            m(&s.interpolate_with_options(None, "both", Some("outside"))
                .unwrap()),
            vec![
                Some(3.0),
                Some(3.0),
                Some(3.0),
                None,
                None,
                Some(6.0),
                Some(6.0)
            ]
        );
        // outside + backward: trailing edge can't fill backward (no right anchor).
        assert_eq!(
            m(
                &s.interpolate_with_options(None, "backward", Some("outside"))
                    .unwrap()
            ),
            vec![Some(3.0), Some(3.0), Some(3.0), None, None, Some(6.0), None]
        );
        assert!(
            s.interpolate_with_options(None, "both", Some("sideways"))
                .is_err()
        );
    }

