    #[test]
    fn series_factorize() {
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Utf8("cat".to_owned()),
                Scalar::Utf8("dog".to_owned()),
                Scalar::Utf8("cat".to_owned()),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("dog".to_owned()),
            ],
        )
        .unwrap();

        let (codes, uniques) = s.factorize().unwrap();
        assert_eq!(codes.values()[0], Scalar::Int64(0));
        assert_eq!(codes.values()[1], Scalar::Int64(1));
        assert_eq!(codes.values()[2], Scalar::Int64(0));
        assert_eq!(codes.values()[3], Scalar::Int64(-1)); // NaN
        assert_eq!(codes.values()[4], Scalar::Int64(1));
        assert_eq!(uniques.len(), 2);
        assert_eq!(uniques.values()[0], Scalar::Utf8("cat".to_owned()));
        assert_eq!(uniques.values()[1], Scalar::Utf8("dog".to_owned()));
    }

    // ── sem / skew / kurtosis ──

    #[test]
    fn series_sem() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(2.0),
                Scalar::Float64(4.0),
                Scalar::Float64(6.0),
                Scalar::Float64(8.0),
            ],
        )
        .unwrap();

        let result = s.sem().unwrap();
        // std = sqrt(20/3) ≈ 2.5820, sem = std/sqrt(4) ≈ 1.2910
        assert!((result - 1.2909944).abs() < 0.001);
    }

    #[test]
    fn series_sem_returns_nan_below_two_non_null_values() {
        let single =
            Series::from_values("x", vec![0_i64.into()], vec![Scalar::Float64(42.0)]).unwrap();
        assert!(single.sem().unwrap().is_nan());

        let all_null = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)],
        )
        .unwrap();
        assert!(all_null.sem().unwrap().is_nan());

        let empty =
            Series::from_values("x", Vec::<IndexLabel>::new(), Vec::<Scalar>::new()).unwrap();
        assert!(empty.sem().unwrap().is_nan());
    }

    #[test]
    fn series_skew() {
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        // Symmetric distribution => skew ≈ 0
        let result = s.skew().unwrap();
        assert!(result.abs() < 1e-10);
    }

    #[test]
    fn series_kurtosis() {
        let s = Series::from_values(
            "x",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        // Uniform-like distribution, excess kurtosis is negative
        let result = s.kurtosis().unwrap();
        // Fisher's excess kurtosis for [1,2,3,4,5] = -1.2
        assert!((result - (-1.2)).abs() < 0.01);
    }

    #[test]
    fn series_skew_returns_nan_below_3() {
        // Per br-frankenpandas-d1aa3: pandas returns NaN (not Err) when
        // count < 3. Was previously asserting the buggy Err return.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();

        assert!(s.skew().unwrap().is_nan());
    }

