    #[test]
    fn str_index_rindex_with_bounds_matches_python() {
        // pandas str.index/rindex(sub, start, end) == Python str.index/rindex:
        // restrict to s[start:end], return full-string char index, raise if not
        // found. Reference values are Python's.
        let s = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("abcabcabc".to_owned())],
        )
        .unwrap();
        let one = |r: &Series| match &r.values()[0] {
            Scalar::Int64(v) => *v,
            other => panic!("expected Int64, got {other:?}"),
        };

        // "abcabcabc".index("abc", 1) == 3
        assert_eq!(one(&s.str().index_with_bounds("abc", 1, None).unwrap()), 3);
        // negative start: index("abc", -3) == 6
        assert_eq!(one(&s.str().index_with_bounds("abc", -3, None).unwrap()), 6);
        // rindex within s[0:6] -> 3
        assert_eq!(
            one(&s.str().rindex_with_bounds("abc", 0, Some(6)).unwrap()),
            3
        );
        // not found in the slice -> raises (Python ValueError)
        let err = s.str().index_with_bounds("abc", 1, Some(5)).unwrap_err();
        assert!(err.to_string().contains("substring not found"));
        let rerr = s.str().rindex_with_bounds("abc", 7, None).unwrap_err();
        assert!(rerr.to_string().contains("substring not found"));
    }

