    #[test]
    fn df_pivot_int64_typed_matches_generic_pvtdk() {
        // Sparse Int64-keys + Float64-values: exercises BOTH the typed fast
        // path's all-present column (`from_f64_values_owned`) and its
        // missing-cell column (`Null(NaN)`). The generic-path mirror uses
        // zero-padded Utf8 keys (lexical order == numeric order) so the typed
        // gate fails and the slow Scalar path runs; labels differ but the
        // per-column value matrix must be bit-identical.
        let rows = [10i64, 10, 20, 20, 30];
        let cols = [1i64, 2, 1, 2, 1];
        let vals = [1.5f64, 2.5, 3.5, 4.5, 5.5];
        let typed = DataFrame::from_dict(
            &["row", "col", "val"],
            vec![
                ("row", rows.iter().map(|&r| Scalar::Int64(r)).collect()),
                ("col", cols.iter().map(|&c| Scalar::Int64(c)).collect()),
                ("val", vals.iter().map(|&v| Scalar::Float64(v)).collect()),
            ],
        )
        .unwrap();
        let typed_res = typed.pivot("row", "col", "val").unwrap();

        let generic = DataFrame::from_dict(
            &["row", "col", "val"],
            vec![
                (
                    "row",
                    rows.iter()
                        .map(|&r| Scalar::Utf8(format!("r{r:03}")))
                        .collect(),
                ),
                (
                    "col",
                    cols.iter()
                        .map(|&c| Scalar::Utf8(format!("c{c:03}")))
                        .collect(),
                ),
                ("val", vals.iter().map(|&v| Scalar::Float64(v)).collect()),
            ],
        )
        .unwrap();
        let generic_res = generic.pivot("row", "col", "val").unwrap();

        assert_eq!(typed_res.len(), 3);
        assert_eq!(typed_res.column_order.len(), generic_res.column_order.len());
        for ci in 0..typed_res.column_order.len() {
            let tcol = typed_res.columns.get(&typed_res.column_order[ci]).unwrap();
            let gcol = generic_res
                .columns
                .get(&generic_res.column_order[ci])
                .unwrap();
            assert_eq!(
                tcol.values(),
                gcol.values(),
                "typed vs generic value mismatch in output column {ci}"
            );
        }
        // Concrete checks: row order [10,20,30], col labels ["1","2"]; the
        // (row=30, col=2) cell has no source row => missing.
        assert_eq!(typed_res.column_order, vec!["1".to_owned(), "2".to_owned()]);
        let c1 = typed_res.columns.get("1").unwrap();
        let c2 = typed_res.columns.get("2").unwrap();
        assert_eq!(c1.values()[0], Scalar::Float64(1.5));
        assert_eq!(c2.values()[2], Scalar::Null(NullKind::NaN));
        assert!(c2.values()[2].is_missing());
    }

