    #[test]
    fn dt_is_month_start_end() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-01-01".to_owned()),
                Scalar::Utf8("2024-01-15".to_owned()),
                Scalar::Utf8("2024-01-31".to_owned()),
            ],
        )
        .unwrap();

        let start = s.dt().is_month_start().unwrap();
        assert_eq!(start.values()[0], Scalar::Bool(true));
        assert_eq!(start.values()[1], Scalar::Bool(false));
        assert_eq!(start.values()[2], Scalar::Bool(false));

        let end = s.dt().is_month_end().unwrap();
        assert_eq!(end.values()[0], Scalar::Bool(false));
        assert_eq!(end.values()[1], Scalar::Bool(false));
        assert_eq!(end.values()[2], Scalar::Bool(true));
    }

    /// Expected `dt.is_*` output for the four rows used by the boqep tests,
    /// with the NaT row at index 1. MEASURED on live pandas 2.2.3 over
    /// `pd.to_datetime(['2024-03-01T00:00:00', None, '2024-03-15T12:00:00',
    /// '2024-04-01T23:59:59'])` — the exact input
    /// `fp_p2d_314_series_dt_is_month_start_null_hardened` pins:
    ///
    /// ```text
    /// is_leap_year     bool [True,  False, True,  True ]
    /// is_month_start   bool [True,  False, False, True ]
    /// is_month_end     bool [False, False, False, False]
    /// is_quarter_start bool [False, False, False, True ]
    /// is_quarter_end   bool [False, False, False, False]
    /// is_year_start    bool [False, False, False, False]
    /// is_year_end      bool [False, False, False, False]
    /// ```
    ///
    /// Every one is dtype `bool`, a NON-nullable numpy array: it cannot hold a
    /// null, so the NaT row is `False` — not a third value.
    const BOQEP_EXPECTED: [(&str, [bool; 4]); 7] = [
        ("is_leap_year", [true, false, true, true]),
        ("is_month_start", [true, false, false, true]),
        ("is_month_end", [false, false, false, false]),
        ("is_quarter_start", [false, false, false, true]),
        ("is_quarter_end", [false, false, false, false]),
        ("is_year_start", [false, false, false, false]),
        ("is_year_end", [false, false, false, false]),
    ];

    fn boqep_all_accessors(s: &Series) -> Vec<(&'static str, Series)> {
        vec![
            ("is_leap_year", s.dt().is_leap_year().unwrap()),
            ("is_month_start", s.dt().is_month_start().unwrap()),
            ("is_month_end", s.dt().is_month_end().unwrap()),
            ("is_quarter_start", s.dt().is_quarter_start().unwrap()),
            ("is_quarter_end", s.dt().is_quarter_end().unwrap()),
            ("is_year_start", s.dt().is_year_start().unwrap()),
            ("is_year_end", s.dt().is_year_end().unwrap()),
        ]
    }

    fn boqep_assert_matches_pandas(path: &str, results: &[(&'static str, Series)]) {
        for (op, result) in results {
            let expected = BOQEP_EXPECTED
                .iter()
                .find(|(name, _)| name == op)
                .map(|(_, vals)| vals)
                .expect("every accessor has a pinned pandas row");
            for (idx, want) in expected.iter().enumerate() {
                assert_eq!(
                    result.values()[idx],
                    Scalar::Bool(*want),
                    "{path}: dt.{op}() row {idx} must match pandas (bool dtype \
                     cannot hold a null, so the NaT row is False)"
                );
            }
        }
    }

    /// br-frankenpandas-dt-is-family-nat-false-boqep, TYPED Datetime64 path.
    ///
    /// NEGATIVE CASE: row 1 is NaT. FrankenPandas emitted `Null(NaN)` there —
    /// a value the `bool` dtype pandas returns cannot represent. Any
    /// implementation that "preserves missingness" fails this row, which is the
    /// whole point of the bead.
    #[test]
    fn dt_is_family_nat_is_false_typed_datetime64() {
        const NS: i64 = 1_000_000_000;
        // 2024-03-01T00:00:00Z = 1_709_251_200; 2024-03-15T12:00:00Z;
        // 2024-04-01T23:59:59Z.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Datetime64(1_709_251_200 * NS),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(1_710_504_000 * NS),
                Scalar::Datetime64(1_712_015_999 * NS),
            ],
        )
        .unwrap();
        assert_eq!(s.dtype(), DType::Datetime64);
        boqep_assert_matches_pandas("typed Datetime64", &boqep_all_accessors(&s));
    }

    /// Same contract on the Utf8-backed (string) path, which reaches a
    /// different helper than the typed path — the bead's sweep requirement.
    #[test]
    fn dt_is_family_nat_is_false_utf8_backed() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Utf8("2024-03-01T00:00:00".to_owned()),
                Scalar::Null(NullKind::NaT),
                Scalar::Utf8("2024-03-15T12:00:00".to_owned()),
                Scalar::Utf8("2024-04-01T23:59:59".to_owned()),
            ],
        )
        .unwrap();
        boqep_assert_matches_pandas("Utf8-backed", &boqep_all_accessors(&s));
    }

    fn dt_numeric_accessors(s: &Series) -> Vec<(&'static str, Series)> {
        vec![
            ("year", s.dt().year().unwrap()),
            ("month", s.dt().month().unwrap()),
            ("day", s.dt().day().unwrap()),
            ("hour", s.dt().hour().unwrap()),
            ("minute", s.dt().minute().unwrap()),
            ("second", s.dt().second().unwrap()),
            ("microsecond", s.dt().microsecond().unwrap()),
            ("nanosecond", s.dt().nanosecond().unwrap()),
            ("dayofweek", s.dt().dayofweek().unwrap()),
            ("dayofyear", s.dt().dayofyear().unwrap()),
            ("quarter", s.dt().quarter().unwrap()),
            ("days_in_month", s.dt().days_in_month().unwrap()),
        ]
    }

    /// A NaT widens every NUMERIC `.dt` component to float64, on both the typed
    /// `Datetime64` backing and the Utf8-backed one.
    ///
    /// MEASURED, live pandas 2.2.3, on `pd.to_datetime([...NaT...])`:
    ///
    /// ```text
    /// dt.year  -> dtype=float64  [2021.0, nan, 2022.0]
    /// ```
    ///
    /// and identically for month/day/hour/minute/second/microsecond/nanosecond/
    /// dayofweek/dayofyear/quarter/days_in_month. Without the NaT the same
    /// accessors are integer-typed, so the promotion is caused by the gap, not
    /// by the accessor. This is the `.dt` sibling of the `.str` rule in
    /// `str_int_returning_ops_promote_to_float64_unless_the_null_is_nat`.
    /// (br-frankenpandas-02ijn)
    #[test]
    fn dt_numeric_accessors_promote_to_float64_when_a_nat_is_present() {
        const NS: i64 = 1_000_000_000;
        let typed = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Datetime64(1_709_251_200 * NS),
                Scalar::Datetime64(fp_types::Timestamp::NAT),
                Scalar::Datetime64(1_710_504_000 * NS),
            ],
        )
        .unwrap();
        let utf8 = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-03-01T00:00:00".to_owned()),
                Scalar::Null(NullKind::NaT),
                Scalar::Utf8("2024-03-15T12:00:00".to_owned()),
            ],
        )
        .unwrap();
        for (backing, s) in [("typed Datetime64", &typed), ("Utf8-backed", &utf8)] {
            for (op, result) in dt_numeric_accessors(s) {
                let out = result.values();
                assert!(
                    out[1].is_missing(),
                    "{backing}: dt.{op}() must leave the NaT row missing, got {out:?}"
                );
                assert!(
                    matches!(out[0], Scalar::Float64(_)) && matches!(out[2], Scalar::Float64(_)),
                    "{backing}: dt.{op}() widens to float64 when a NaT is present — a numpy int \
                     array cannot hold the gap. Got {out:?}"
                );
            }
        }

        // The STRING-valued components share the same helpers and must be
        // untouched by the promotion — they have no Int64 cell to widen, and
        // pandas renders their gap as a float nan in an object column:
        //   s.dt.month_name() -> object ['February', nan, ...]
        // Executed here rather than assumed, because fixtures 331/332 are
        // re-banked on the strength of it.
        for (backing, s) in [("typed Datetime64", &typed), ("Utf8-backed", &utf8)] {
            for (op, result) in [
                ("month_name", s.dt().month_name().unwrap()),
                ("day_name", s.dt().day_name().unwrap()),
            ] {
                let out = result.values();
                assert_eq!(
                    out[1],
                    Scalar::Null(NullKind::NaN),
                    "{backing}: dt.{op}() renders the gap as NaN, got {out:?}"
                );
                assert!(
                    matches!(out[0], Scalar::Utf8(_)) && matches!(out[2], Scalar::Utf8(_)),
                    "{backing}: dt.{op}() is string-valued and must not be promoted, got {out:?}"
                );
            }
        }

        // Control: with no NaT the very same accessors stay Int64, so the
        // promotion above is caused by the gap and not by the accessor.
        let all_valid = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Datetime64(1_709_251_200 * NS),
                Scalar::Datetime64(1_710_504_000 * NS),
            ],
        )
        .unwrap();
        for (op, result) in dt_numeric_accessors(&all_valid) {
            let out = result.values();
            assert!(
                out.iter().all(|v| matches!(v, Scalar::Int64(_))),
                "dt.{op}() over an all-present column stays int64 in pandas, got {out:?}"
            );
        }
    }

    /// The all-valid fast path must keep agreeing with the nullable paths:
    /// same rows, no NaT, identical answers. Guards against fixing the null
    /// row by accidentally changing the non-null ones.
    #[test]
    fn dt_is_family_all_valid_path_unchanged() {
        const NS: i64 = 1_000_000_000;
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Datetime64(1_709_251_200 * NS),
                Scalar::Datetime64(1_710_504_000 * NS),
                Scalar::Datetime64(1_712_015_999 * NS),
            ],
        )
        .unwrap();
        for (op, result) in boqep_all_accessors(&s) {
            let expected = BOQEP_EXPECTED
                .iter()
                .find(|(name, _)| *name == op)
                .map(|(_, vals)| vals)
                .expect("pinned row exists");
            // Rows 0, 2, 3 of the pinned pandas output are rows 0, 1, 2 here.
            for (idx, src) in [0_usize, 2, 3].iter().enumerate() {
                assert_eq!(
                    result.values()[idx],
                    Scalar::Bool(expected[*src]),
                    "all-valid path: dt.{op}() row {idx} drifted"
                );
            }
        }
    }

    /// Every gap a WINDOW or DERIVED op leaves in a float64 column is a `NaN`,
    /// never a generic `Null` — whether the op invented it (Rule 1) or carried
    /// through a `None` the caller supplied into a float column (Rule 2).
    ///
    /// MEASURED, live pandas 2.2.3. A float64 column cannot hold anything but
    /// `nan`, so a supplied `None` is already `nan` before the op runs:
    ///
    /// ```text
    /// pd.Series([1.0, None, 3.0, 5.0, 7.0])          -> [1.0, nan, 3.0, 5.0, 7.0]
    ///   .shift(1)                                    -> [nan, 1.0, nan, 3.0, 5.0]
    ///   .rolling(3, min_periods=2).std()             -> [nan, nan, 1.41.., ...]
    ///   .expanding(min_periods=1).var()              -> [nan, nan, 2.0, ...]
    /// df.diff() / df.rank()                          -> gaps are nan
    /// ```
    ///
    /// The inputs below are the exact payloads of the eight corpus fixtures
    /// that pin these ops (fp_p2d_336/339/345/352/353/360/385/387), which pinned
    /// the marker as `null`. This test EXECUTES FrankenPandas on them rather
    /// than reasoning about the fill sites, because the conformance harness
    /// cannot see the difference: `Scalar::semantic_eq` treats every null kind
    /// as equal, so those fixtures pass either way (br-frankenpandas-gxe5s).
    /// (br-frankenpandas-nywa8)
    #[test]
    fn window_and_derived_ops_leave_nan_gaps_in_a_float64_column() {
        fn labels(n: i64) -> Vec<IndexLabel> {
            (0..n).map(Into::into).collect()
        }
        fn series(vals: Vec<Scalar>) -> Series {
            let n = vals.len() as i64;
            Series::from_values("v", labels(n), vals).unwrap()
        }
        fn f(x: f64) -> Scalar {
            Scalar::Float64(x)
        }
        let null = || Scalar::Null(NullKind::Null);

        // fp_p2d_336 / 339 / 352 / 353 / 360 all use this shape or its sibling.
        let a = || vec![f(1.0), null(), f(3.0), f(4.0), f(5.0)];
        let b = || vec![f(1.0), null(), f(3.0), f(5.0), f(7.0)];

        let mut cases: Vec<(&'static str, Vec<Scalar>)> = vec![
            (
                "rolling(3, 2).std",
                series(a())
                    .rolling(3, Some(2))
                    .std()
                    .unwrap()
                    .values()
                    .to_vec(),
            ),
            (
                "rolling(3, 1).var",
                series(a())
                    .rolling(3, Some(1))
                    .var()
                    .unwrap()
                    .values()
                    .to_vec(),
            ),
            (
                "expanding.std",
                series(b()).expanding(None).std().unwrap().values().to_vec(),
            ),
            (
                "expanding.var",
                series(b()).expanding(None).var().unwrap().values().to_vec(),
            ),
            ("shift(1)", series(b()).shift(1).unwrap().values().to_vec()),
        ];

        // fp_p2d_345 dataframe_rolling_mean, 385 dataframe_diff, 387 dataframe_rank.
        let roll_df = DataFrame::from_dict_with_index(
            vec![
                ("A", a()),
                ("B", vec![f(10.0), f(20.0), null(), f(40.0), f(50.0)]),
            ],
            labels(5),
        )
        .unwrap();
        let diff_df = DataFrame::from_dict_with_index(
            vec![
                ("a", vec![f(1.0), null(), f(3.0), f(5.0), f(8.0)]),
                ("b", vec![null(), f(10.0), f(15.0), null(), f(25.0)]),
            ],
            labels(5),
        )
        .unwrap();
        let rank_df = DataFrame::from_dict_with_index(
            vec![
                ("a", vec![f(3.0), null(), f(1.0), f(2.0)]),
                ("b", vec![null(), f(5.0), f(10.0), null()]),
            ],
            labels(4),
        )
        .unwrap();
        for (label, frame, out) in [
            (
                "df.rolling(3, 2).mean",
                &roll_df,
                roll_df.rolling(3, Some(2)).mean().unwrap(),
            ),
            ("df.diff(1)", &diff_df, diff_df.diff(1).unwrap()),
            (
                "df.rank",
                &rank_df,
                rank_df
                    .rank_with_pct("average", true, "keep", false)
                    .unwrap(),
            ),
        ] {
            for name in frame.column_names() {
                cases.push((label, out.column(name).unwrap().values().to_vec()));
            }
        }

        for (op, out) in cases {
            assert!(
                out.iter().any(Scalar::is_missing),
                "{op}: this input is supposed to leave a gap — the test proves nothing otherwise, \
                 got {out:?}"
            );
            for (i, v) in out.iter().enumerate() {
                if !v.is_missing() {
                    continue;
                }
                // Two FrankenPandas encodings are both a float NaN and both
                // correct: the `Null(NaN)` marker, and a PRESENT `Float64` whose
                // value is NaN, which the typed float kernels produce directly
                // (rolling var/std take that path). pandas has one
                // representation — the NaN bit pattern in the float64 array —
                // and the fixture format writes either as `na_n`. What must NOT
                // appear is a generic `Null` or a `NaT`: those are markers a
                // float64 column cannot hold.
                let nan_flavoured = matches!(v, Scalar::Null(NullKind::NaN))
                    || matches!(v, Scalar::Float64(x) if x.is_nan());
                assert!(
                    nan_flavoured,
                    "{op} row {i}: a gap in a float64 column is a NaN in pandas, never a generic \
                     Null or a NaT. Got {v:?}, full output {out:?}"
                );
            }
        }
    }

    #[test]
    fn dt_is_quarter_start_end() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-01-01".to_owned()),
                Scalar::Utf8("2024-03-31".to_owned()),
                Scalar::Utf8("2024-06-30".to_owned()),
            ],
        )
        .unwrap();

        let qs = s.dt().is_quarter_start().unwrap();
        assert_eq!(qs.values()[0], Scalar::Bool(true));
        assert_eq!(qs.values()[1], Scalar::Bool(false));
        assert_eq!(qs.values()[2], Scalar::Bool(false));

        let qe = s.dt().is_quarter_end().unwrap();
        assert_eq!(qe.values()[0], Scalar::Bool(false));
        assert_eq!(qe.values()[1], Scalar::Bool(true));
        assert_eq!(qe.values()[2], Scalar::Bool(true));
    }

    #[test]
    fn dt_strftime() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("2024-03-15T14:30:00".to_owned())],
        )
        .unwrap();

        let result = s.dt().strftime("%Y/%m/%d %H:%M").unwrap();
        assert_eq!(
            result.values()[0],
            Scalar::Utf8("2024/03/15 14:30".to_owned())
        );
    }

    #[test]
    fn dt_weekofyear() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("2024-01-01".to_owned())],
        )
        .unwrap();

        let result = s.dt().weekofyear().unwrap();
        // 2024-01-01 is a Monday, ISO week 1
        assert_eq!(result.values()[0], Scalar::Int64(1));
    }

    // ── DataFrame ffill / bfill / interpolate ──

    #[test]
    fn df_ffill() {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(3.0),
                ],
            )],
        )
        .unwrap();

        let result = df.ffill(None).unwrap();
        let col = result.column_as_series("a").unwrap();
        assert_eq!(col.values()[0], Scalar::Float64(1.0));
        assert_eq!(col.values()[1], Scalar::Float64(1.0));
        assert_eq!(col.values()[2], Scalar::Float64(3.0));
    }

    #[test]
    fn df_bfill() {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(2.0),
                    Scalar::Null(NullKind::NaN),
                ],
            )],
        )
        .unwrap();

        let result = df.bfill(None).unwrap();
        let col = result.column_as_series("a").unwrap();
        assert_eq!(col.values()[0], Scalar::Float64(2.0));
        assert_eq!(col.values()[1], Scalar::Float64(2.0));
        assert!(col.values()[2].is_missing());
    }

    #[test]
    fn df_ffill_axis1_promotes_target_column_for_float_fill() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Float64(1.5), Scalar::Float64(9.0)]),
                ("b", vec![Scalar::Null(NullKind::NaN), Scalar::Int64(2)]),
            ],
        )
        .unwrap();

        let result = df.ffill_axis1(None).unwrap();
        let col_b = result.column_as_series("b").unwrap();
        assert_eq!(col_b.column().dtype(), DType::Float64);
        assert_eq!(col_b.values()[0], Scalar::Float64(1.5));
        assert_eq!(col_b.values()[1], Scalar::Float64(2.0));
    }

    #[test]
    fn df_bfill_axis1_promotes_target_column_for_float_fill() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Null(NullKind::NaN), Scalar::Int64(1)]),
                ("b", vec![Scalar::Float64(2.5), Scalar::Float64(8.0)]),
            ],
        )
        .unwrap();

        let result = df.bfill_axis1(None).unwrap();
        let col_a = result.column_as_series("a").unwrap();
        assert_eq!(col_a.column().dtype(), DType::Float64);
        assert_eq!(col_a.values()[0], Scalar::Float64(2.5));
        assert_eq!(col_a.values()[1], Scalar::Float64(1.0));
    }

    #[test]
    fn df_interpolate() {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Float64(0.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(2.0),
                ],
            )],
        )
        .unwrap();

        let result = df.interpolate().unwrap();
        let col = result.column_as_series("a").unwrap();
        let mid = col.values()[1].to_f64().unwrap();
        assert!((mid - 1.0).abs() < 1e-10);
    }

    // ── Series.append / DataFrame.append ──

    #[test]
    fn series_append() {
        let s1 = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();

        let s2 = Series::from_values(
            "x",
            vec![2_i64.into(), 3_i64.into()],
            vec![Scalar::Float64(3.0), Scalar::Float64(4.0)],
        )
        .unwrap();

        let result = s1.append(&s2).unwrap();
        assert_eq!(result.len(), 4);
        assert_eq!(result.values()[0], Scalar::Float64(1.0));
        assert_eq!(result.values()[3], Scalar::Float64(4.0));
    }

    #[test]
    fn df_append() {
        let df1 = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Float64(1.0)]),
                ("b", vec![Scalar::Float64(2.0)]),
            ],
        )
        .unwrap();

        let df2 = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Float64(3.0)]),
                ("b", vec![Scalar::Float64(4.0)]),
            ],
        )
        .unwrap();

        let result = df1.append(&df2).unwrap();
        assert_eq!(result.len(), 2);
        let col_a = result.column_as_series("a").unwrap();
        assert_eq!(col_a.values()[0], Scalar::Float64(1.0));
        assert_eq!(col_a.values()[1], Scalar::Float64(3.0));
    }

    #[test]
    fn df_append_mismatched_columns() {
        let df1 = DataFrame::from_dict(&["a"], vec![("a", vec![Scalar::Float64(1.0)])]).unwrap();

        let df2 = DataFrame::from_dict(&["b"], vec![("b", vec![Scalar::Float64(2.0)])]).unwrap();

        let result = df1.append(&df2).unwrap();
        assert_eq!(result.len(), 2);
        assert_eq!(result.column_names().len(), 2);
        // Missing columns filled with NaN
        let col_a = result.column_as_series("a").unwrap();
        assert!(col_a.values()[1].is_missing());
    }

