    #[test]
    fn series_astype_safe_coerce() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("1".to_owned()),
                Scalar::Utf8("bad".to_owned()),
                Scalar::Utf8("3".to_owned()),
            ],
        )
        .unwrap();

        let result = s.astype_safe(DType::Int64, "coerce").unwrap();
        assert_eq!(result.values()[0], Scalar::Int64(1));
        assert!(result.values()[1].is_missing());
        assert_eq!(result.values()[2], Scalar::Int64(3));
    }

    #[test]
    fn series_astype_safe_raise() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into()],
            vec![Scalar::Utf8("bad".to_owned())],
        )
        .unwrap();

        // "raise" mode should error
        assert!(s.astype_safe(DType::Int64, "raise").is_err());
    }

    #[test]
    fn series_astype_safe_coerce_infinity_to_int_yields_null_lo7bq() {
        // Per br-frankenpandas-lo7bq: pandas raises on astype(int64) of
        // non-finite Float64; in coerce mode our implementation should
        // surface Null instead of silently clamping to i64::MAX / 0.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(f64::INFINITY),
                Scalar::Float64(f64::NEG_INFINITY),
                Scalar::Float64(f64::NAN),
                Scalar::Float64(1e30), // > i64::MAX
            ],
        )
        .unwrap();
        let result = s.astype_safe(DType::Int64, "coerce").unwrap();
        assert!(result.values()[0].is_missing(), "INFINITY → Null");
        assert!(result.values()[1].is_missing(), "NEG_INFINITY → Null");
        assert!(result.values()[2].is_missing(), "NaN → Null");
        assert!(result.values()[3].is_missing(), "out-of-range → Null");
    }

    #[test]
    fn series_astype_safe_coerce_in_range_float_to_int_still_works_lo7bq() {
        // Regression: in-range finite Float64 still converts cleanly.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(42.0), Scalar::Float64(-7.0)],
        )
        .unwrap();
        let result = s.astype_safe(DType::Int64, "coerce").unwrap();
        assert_eq!(result.values()[0], Scalar::Int64(42));
        assert_eq!(result.values()[1], Scalar::Int64(-7));
    }

    // ── sort_values_multi ──

    #[test]
    fn deferred_sort_gather_frame_matches_eager_order() {
        const N: usize = 1 << 18;
        let mut columns = BTreeMap::new();
        columns.insert(
            "key".to_owned(),
            Column::from_f64_values((0..N).rev().map(|value| value as f64).collect()),
        );
        columns.insert(
            "payload".to_owned(),
            Column::from_f64_values((0..N).map(|row| row as f64 + 0.25).collect()),
        );
        let df = DataFrame::new_with_column_order(
            Index::new_known_unique_int64_unit_range(0, N),
            columns,
            vec!["key".to_owned(), "payload".to_owned()],
        )
        .expect("large all-valid Float64 frame");

        let sorted = df.sort_values("key", true).expect("sort succeeds");
        let keys = sorted.columns["key"]
            .as_f64_slice()
            .expect("sorted key stays typed");
        let payload = sorted.columns["payload"]
            .as_f64_slice()
            .expect("deferred payload materializes as typed Float64");
        for &row in &[0, 1, N / 2, N - 2, N - 1] {
            assert_eq!(keys[row].to_bits(), (row as f64).to_bits());
            assert_eq!(
                payload[row].to_bits(),
                ((N - 1 - row) as f64 + 0.25).to_bits()
            );
        }
    }

    #[test]
    fn deferred_multi_sort_gather_matches_stable_lexicographic_order() {
        const N: usize = 1 << 18;
        let key_a: Vec<f64> = (0..N).map(|row| (row % 257) as f64).collect();
        let key_b: Vec<f64> = (0..N).map(|row| ((row / 257) % 1021) as f64).collect();
        let payload: Vec<f64> = (0..N).map(|row| row as f64 + 0.25).collect();

        let mut expected_order: Vec<usize> = (0..N).collect();
        expected_order.sort_by(|&left, &right| {
            key_a[left]
                .partial_cmp(&key_a[right])
                .expect("finite primary key")
                .then_with(|| {
                    key_b[right]
                        .partial_cmp(&key_b[left])
                        .expect("finite secondary key")
                })
        });

        let mut columns = BTreeMap::new();
        columns.insert("key_a".to_owned(), Column::from_f64_values(key_a.clone()));
        columns.insert("key_b".to_owned(), Column::from_f64_values(key_b.clone()));
        columns.insert(
            "payload".to_owned(),
            Column::from_f64_values(payload.clone()),
        );
        let df = DataFrame::new_with_column_order(
            Index::new_known_unique_int64_unit_range(0, N),
            columns,
            vec!["key_a".to_owned(), "key_b".to_owned(), "payload".to_owned()],
        )
        .expect("large all-valid Float64 frame");

        let sorted = df
            .sort_values_multi(&["key_a", "key_b"], &[true, false], "last")
            .expect("multi-key sort succeeds");
        let sorted_a = sorted.columns["key_a"]
            .as_f64_slice()
            .expect("deferred primary key materializes");
        let sorted_b = sorted.columns["key_b"]
            .as_f64_slice()
            .expect("deferred secondary key materializes");
        let sorted_payload = sorted.columns["payload"]
            .as_f64_slice()
            .expect("deferred payload materializes");

        for (output_row, &source_row) in expected_order.iter().enumerate() {
            assert_eq!(sorted_a[output_row].to_bits(), key_a[source_row].to_bits());
            assert_eq!(sorted_b[output_row].to_bits(), key_b[source_row].to_bits());
            assert_eq!(
                sorted_payload[output_row].to_bits(),
                payload[source_row].to_bits()
            );
        }
    }

    #[test]
    fn df_sort_values_multi() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![Scalar::Int64(1), Scalar::Int64(1), Scalar::Int64(2)],
                ),
                (
                    "b",
                    vec![Scalar::Int64(3), Scalar::Int64(1), Scalar::Int64(2)],
                ),
            ],
        )
        .unwrap();

        let sorted = df
            .sort_values_multi(&["a", "b"], &[true, true], "last")
            .unwrap();
        let col_b = sorted.column_as_series("b").unwrap();
        assert_eq!(col_b.values()[0], Scalar::Int64(1)); // (1,1)
        assert_eq!(col_b.values()[1], Scalar::Int64(3)); // (1,3)
        assert_eq!(col_b.values()[2], Scalar::Int64(2)); // (2,2)
    }

    #[test]
    fn df_sort_values_multi_descending() {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![Scalar::Int64(3), Scalar::Int64(1), Scalar::Int64(2)],
            )],
        )
        .unwrap();

        let sorted = df.sort_values_multi(&["a"], &[false], "last").unwrap();
        let col_a = sorted.column_as_series("a").unwrap();
        assert_eq!(col_a.values()[0], Scalar::Int64(3));
        assert_eq!(col_a.values()[1], Scalar::Int64(2));
        assert_eq!(col_a.values()[2], Scalar::Int64(1));
    }

