    // ── EWM tests ──

    #[test]
    fn ewm_mean_basic() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();

        // span=3 → alpha = 2/(3+1) = 0.5. pandas DEFAULT adjust=True:
        //   [1,2,3,4].ewm(alpha=0.5).mean() == [1, 1.666…, 2.428…, 3.266…]
        // (verified vs live pandas 2.2.3; NOT the adjust=False [1,1.5,2.25,3.125]).
        let result = s.ewm(Some(3.0), None).mean().unwrap();
        let got: Vec<f64> = result
            .values()
            .iter()
            .map(|v| v.to_f64().unwrap())
            .collect();
        let expected = [1.0, 5.0 / 3.0, 17.0 / 7.0, 49.0 / 15.0];
        for (g, e) in got.iter().zip(expected.iter()) {
            assert!((g - e).abs() < 1e-12, "ewm.mean {got:?} != {expected:?}");
        }
    }

    #[test]
    fn ewm_mean_with_alpha() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
            ],
        )
        .unwrap();

        // pandas DEFAULT adjust=True: [10,20,30].ewm(alpha=0.5).mean()
        //   == [10, 50/3 (=16.666…), 170/7 (=24.285…)] (verified vs pandas 2.2.3).
        let result = s.ewm(None, Some(0.5)).mean().unwrap();
        let got: Vec<f64> = result
            .values()
            .iter()
            .map(|v| v.to_f64().unwrap())
            .collect();
        let expected = [10.0, 50.0 / 3.0, 170.0 / 7.0];
        for (g, e) in got.iter().zip(expected.iter()) {
            assert!((g - e).abs() < 1e-12, "ewm.mean {got:?} != {expected:?}");
        }
    }

    #[test]
    fn ewm_mean_with_nulls() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();

        // pandas DEFAULT adjust=True, ignore_na=False: [1, NaN, 3].ewm(alpha=0.5)
        //   .mean() == [1.0, 1.0, 2.6] (the NaN still decays old_wt: at t=2
        //   old_wt = 0.5*0.5 = 0.25, avg = (0.25*1 + 1*3)/1.25 = 2.6).
        //   Verified vs live pandas 2.2.3 (NOT the adjust=False 2.0).
        let result = s.ewm(Some(3.0), None).mean().unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(1.0));
        // Per br-frankenpandas-mm77i: pandas carries forward last EWM for nulls.
        assert_eq!(result.values()[1], Scalar::Float64(1.0));
        assert!((expect_float64(&result.values()[2]) - 2.6).abs() < 1e-12);
    }

    #[test]
    fn ewm_mean_adjust_true_matches_pandas_usdk2() {
        // pandas DEFAULT ewm(alpha=..).mean() is adjust=True, ignore_na=False.
        // Each (values, alpha, expected) row was produced by live pandas 2.2.3.
        let cases: Vec<(Vec<Scalar>, f64, Vec<Option<f64>>)> = vec![
            (
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(6.0),
                ],
                0.5,
                vec![
                    Some(1.0),
                    Some(1.6666666666666667),
                    Some(2.4285714285714284),
                    Some(3.2666666666666666),
                    Some(4.161290322580645),
                    Some(5.095238095238095),
                ],
            ),
            (
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(6.0),
                ],
                0.3,
                vec![
                    Some(1.0),
                    Some(1.5882352941176472),
                    Some(2.2328767123287676),
                    Some(2.930517173312278),
                    Some(3.6767877105044895),
                    Some(4.466681626699579),
                ],
            ),
            (
                vec![
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                ],
                0.4,
                vec![Some(5.0), Some(5.0), Some(5.0), Some(5.0)],
            ),
            (
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(3.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(5.0),
                ],
                0.5,
                vec![
                    Some(1.0),
                    Some(1.0),
                    Some(2.6),
                    Some(2.6),
                    Some(4.428571428571429),
                ],
            ),
            (
                vec![
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                ],
                0.5,
                vec![None, Some(2.0), Some(3.3333333333333335)],
            ),
            (
                vec![
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(8.0),
                    Scalar::Float64(16.0),
                ],
                0.2,
                vec![
                    Some(2.0),
                    Some(3.1111111111111107),
                    Some(5.114754098360655),
                    Some(8.802168021680217),
                ],
            ),
            (
                vec![
                    Scalar::Float64(10.0),
                    Scalar::Float64(-5.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(-2.0),
                    Scalar::Float64(7.0),
                ],
                0.6,
                vec![
                    Some(10.0),
                    Some(-0.7142857142857143),
                    Some(1.6666666666666667),
                    Some(-0.5911330049261082),
                    Some(4.01066925315228),
                ],
            ),
        ];
        for (vals, alpha, expected) in cases {
            let n = vals.len();
            let idx: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
            let s = Series::from_values("x", idx, vals).unwrap();
            let got: Vec<Option<f64>> = s
                .ewm(None, Some(alpha))
                .mean()
                .unwrap()
                .values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect();
            assert_eq!(got.len(), expected.len());
            for (g, e) in got.iter().zip(expected.iter()) {
                match (g, e) {
                    (None, None) => {}
                    (Some(gv), Some(ev)) => assert!(
                        (gv - ev).abs() < 1e-12,
                        "ewm.mean(alpha={alpha}) {got:?} != {expected:?}"
                    ),
                    _ => panic!("missing-ness mismatch: {got:?} != {expected:?}"),
                }
            }
        }
    }

    #[test]
    fn ewm_var_basic() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();

        let result = s.ewm(Some(3.0), None).var().unwrap();
        // First value: NaN (can't compute variance from 1 obs)
        assert!(result.values()[0].is_missing());
        // Second value should be a positive number
        let v = expect_float64(&result.values()[1]);
        assert!(v > 0.0);
    }

    #[test]
    fn ewm_var_std_match_pandas_cupvi() {
        // pandas DEFAULT ewm(alpha=..).var() = debiased ewmcov(x,x) (adjust=True,
        // bias=False, ignore_na=False). Each row from live pandas 2.2.3; std is
        // sqrt(var) elementwise.
        let cases: Vec<(Vec<Scalar>, f64, Vec<Option<f64>>)> = vec![
            (
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(5.0),
                ],
                0.5,
                vec![
                    None,
                    Some(0.5),
                    Some(0.9285714285714284),
                    Some(1.385714285714286),
                    Some(1.8096774193548393),
                ],
            ),
            (
                vec![
                    Scalar::Float64(2.0),
                    Scalar::Float64(4.0),
                    Scalar::Float64(8.0),
                    Scalar::Float64(16.0),
                ],
                0.3,
                vec![
                    None,
                    Some(2.0),
                    Some(9.853881278538811),
                    Some(43.208666605375264),
                ],
            ),
            (
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(3.0),
                    Scalar::Float64(4.0),
                ],
                0.5,
                vec![None, None, Some(2.0), Some(1.3636363636363635)],
            ),
            (
                vec![
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(5.0),
                ],
                0.4,
                vec![None, Some(0.0), Some(0.0), Some(0.0)],
            ),
        ];
        for (vals, alpha, expected) in cases {
            let n = vals.len();
            let idx: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
            let s = Series::from_values("x", idx, vals).unwrap();
            let var = s.ewm(None, Some(alpha)).var().unwrap();
            let got: Vec<Option<f64>> = var
                .values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect();
            for (g, e) in got.iter().zip(expected.iter()) {
                match (g, e) {
                    (None, None) => {}
                    (Some(gv), Some(ev)) => assert!(
                        (gv - ev).abs() < 1e-9,
                        "ewm.var(alpha={alpha}) {got:?} != {expected:?}"
                    ),
                    _ => panic!("missing-ness mismatch: {got:?} != {expected:?}"),
                }
            }
            // std == sqrt(var) elementwise.
            let std = s.ewm(None, Some(alpha)).std().unwrap();
            for (vv, sv) in var.values().iter().zip(std.values().iter()) {
                match (vv.is_missing(), sv.is_missing()) {
                    (true, true) => {}
                    (false, false) => {
                        assert!((vv.to_f64().unwrap().sqrt() - sv.to_f64().unwrap()).abs() < 1e-12)
                    }
                    _ => panic!("var/std missing mismatch"),
                }
            }
        }
    }

