    #[test]
    fn ewm_mean_adjust_false_renormalizes_across_nan_gap() {
        // ignore_na=False renormalization: [1, NaN, 3] with alpha=0.5,
        // adjust=False. At t=2 old_wt = 0.25 (two decays), new_wt = alpha:
        // (0.25*1 + 0.5*3)/(0.25 + 0.5) = 7/3. Live pandas 2.2.3:
        // [1.0, 1.0, 2.3333333333333335] — NOT the naive 0.5*1+0.5*3 = 2.0.
        let s = ewm19_series(&[1.0, f64::NAN, 3.0]);
        let r = s
            .ewm_with_options(None, Some(0.5), false, 0)
            .mean()
            .unwrap();
        assert_series_approx(
            &r,
            &[Some(1.0), Some(1.0), Some(7.0 / 3.0)],
            "ewm adjF gap mean",
        );
    }

    #[test]
    fn ewm_mean_min_periods_counts_observations_not_rows() {
        // [1, NaN, 3, 4] with min_periods=2: the NaN row does not count, so
        // the second OBSERVATION (row 2) is the first emitted value. Live
        // pandas 2.2.3, span=3.
        let s = ewm19_series(&[1.0, f64::NAN, 3.0, 4.0]);
        let adj_t = s.ewm_with_options(Some(3.0), None, true, 2).mean().unwrap();
        assert_series_approx(
            &adj_t,
            &[None, None, Some(2.6), Some(3.461_538_461_538_461_7)],
            "ewm adjT minp2 gap mean",
        );
        let adj_f = s
            .ewm_with_options(Some(3.0), None, false, 2)
            .mean()
            .unwrap();
        assert_series_approx(
            &adj_f,
            &[
                None,
                None,
                Some(2.333_333_333_333_333_5),
                Some(3.166_666_666_666_667),
            ],
            "ewm adjF minp2 gap mean",
        );
    }

    #[test]
    fn ewm_mean_adjust_false_leading_nan() {
        // Leading NaN stays NaN and does not seed the recurrence. Live
        // pandas 2.2.3: [NaN,1,2,3].ewm(alpha=0.5, adjust=False).mean()
        // == [NaN, 1.0, 1.5, 2.25]; with min_periods=2 (adjust=True) ==
        // [NaN, NaN, 1.666..., 2.428...].
        let s = ewm19_series(&[f64::NAN, 1.0, 2.0, 3.0]);
        let adj_f = s
            .ewm_with_options(None, Some(0.5), false, 0)
            .mean()
            .unwrap();
        assert_series_approx(
            &adj_f,
            &[None, Some(1.0), Some(1.5), Some(2.25)],
            "ewm adjF leading NaN",
        );
        let minp2 = s.ewm_with_options(None, Some(0.5), true, 2).mean().unwrap();
        assert_series_approx(
            &minp2,
            &[
                None,
                None,
                Some(1.666_666_666_666_666_7),
                Some(2.428_571_428_571_428_4),
            ],
            "ewm adjT minp2 leading NaN",
        );
    }

