    // ── GroupBy pct_change tests ──

    #[test]
    fn groupby_pct_change() {
        let df = DataFrame::from_dict(
            &["g", "v"],
            vec![
                (
                    "g",
                    vec![
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Float64(100.0),
                        Scalar::Float64(110.0),
                        Scalar::Float64(121.0),
                    ],
                ),
            ],
        )
        .unwrap();

        let result = df.groupby(&["g"]).unwrap().pct_change(1).unwrap();
        let v = result.column_as_series("v").unwrap();
        assert!(v.values()[0].is_missing()); // first: NaN
        // (110-100)/100 = 0.1
        let f1 = expect_float64(&v.values()[1]);
        assert!((f1 - 0.1).abs() < 1e-10);
        // (121-110)/110 = 0.1
        let f2 = expect_float64(&v.values()[2]);
        assert!((f2 - 0.1).abs() < 1e-10);
    }

    #[test]
    fn groupby_pct_change_timedelta64_matches_pandas_dj6rv() {
        // Per br-frankenpandas-dj6rv: groupby pct_change on Timedelta64
        // now computes f64 ratios; was silently NaN via the to_f64-else
        // catch-all.
        let one_hour = 3_600 * 1_000_000_000_i64;
        let df = DataFrame::from_dict(
            &["g", "v"],
            vec![
                (
                    "g",
                    vec![
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Timedelta64(one_hour),
                        Scalar::Timedelta64(2 * one_hour),
                        Scalar::Timedelta64(4 * one_hour),
                    ],
                ),
            ],
        )
        .unwrap();

        let result = df.groupby(&["g"]).unwrap().pct_change(1).unwrap();
        let v = result.column_as_series("v").unwrap();
        assert!(v.values()[0].is_missing());
        let f1 = expect_float64(&v.values()[1]);
        assert!((f1 - 1.0).abs() < 1e-10); // (2h-1h)/1h = 1.0
        let f2 = expect_float64(&v.values()[2]);
        assert!((f2 - 1.0).abs() < 1e-10); // (4h-2h)/2h = 1.0
    }

    #[test]
    fn groupby_pct_change_forward_fills_within_group_c3zld() {
        // pandas groupby.pct_change default ffills within each group:
        // group x=[1,nan,4] -> filled [1,1,4] -> [NaN,0,3]; group y=[10] -> [NaN].
        // (br-frankenpandas-c3zld)
        let df = DataFrame::from_dict(
            &["k", "v"],
            vec![
                (
                    "k",
                    vec![
                        Scalar::Utf8("x".to_owned()),
                        Scalar::Utf8("x".to_owned()),
                        Scalar::Utf8("x".to_owned()),
                        Scalar::Utf8("y".to_owned()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(4.0),
                        Scalar::Float64(10.0),
                    ],
                ),
            ],
        )
        .unwrap();
        let result = df.groupby(&["k"]).unwrap().pct_change(1).unwrap();
        let v = result.column_as_series("v").unwrap();
        assert!(v.values()[0].is_missing());
        assert!((expect_float64(&v.values()[1]) - 0.0).abs() < 1e-10);
        assert!((expect_float64(&v.values()[2]) - 3.0).abs() < 1e-10);
        assert!(v.values()[3].is_missing());
    }

    #[test]
    fn pct_change_axis1_forward_fills_across_columns_c3zld() {
        // pandas pct_change(axis=1) default ffills across columns per row:
        // row [1, nan, 3] -> filled [1, 1, 3] -> [NaN, 0, 2]. (br-frankenpandas-c3zld)
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                ("a", vec![Scalar::Float64(1.0)]),
                ("b", vec![Scalar::Null(NullKind::NaN)]),
                ("c", vec![Scalar::Float64(3.0)]),
            ],
        )
        .unwrap();
        let result = df.pct_change_axis1(1).unwrap();
        assert!(result.column_as_series("a").unwrap().values()[0].is_missing());
        assert!(
            (expect_float64(&result.column_as_series("b").unwrap().values()[0]) - 0.0).abs()
                < 1e-10
        );
        assert!(
            (expect_float64(&result.column_as_series("c").unwrap().values()[0]) - 2.0).abs()
                < 1e-10
        );
    }

    #[test]
    fn groupby_diff_timedelta64_returns_timedelta_q82t4() {
        // Per br-frankenpandas-q82t4: groupby diff on Timedelta64 returns
        // Timedelta64 differences (preserves dtype), not Float64.
        let one_hour = 3_600 * 1_000_000_000_i64;
        let df = DataFrame::from_dict(
            &["g", "v"],
            vec![
                (
                    "g",
                    vec![
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                        Scalar::Utf8("a".to_owned()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Timedelta64(one_hour),
                        Scalar::Timedelta64(3 * one_hour),
                        Scalar::Timedelta64(2 * one_hour),
                    ],
                ),
            ],
        )
        .unwrap();

        let result = df.groupby(&["g"]).unwrap().diff(1).unwrap();
        let v = result.column_as_series("v").unwrap();
        assert!(v.values()[0].is_missing());
        match &v.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(*ns, 2 * one_hour),
            other => panic!("expected Timedelta64(2h), got {:?}", other),
        }
        match &v.values()[2] {
            Scalar::Timedelta64(ns) => assert_eq!(*ns, -one_hour),
            other => panic!("expected Timedelta64(-1h), got {:?}", other),
        }
    }

    #[test]
    fn series_groupby_transform_moments_e96wv() {
        // br-frankenpandas-e96wv: transform('skew'/'kurt'/'sem') broadcasts the
        // per-group scalar to every row in the group.
        let idx: Vec<IndexLabel> = (0..8i64).map(Into::into).collect();
        let keys = Series::from_values(
            "k",
            idx.clone(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )
        .unwrap();
        let raw = [1i64, 2, 2, 7, 3, 3, 9, 1];
        let vals = Series::from_values(
            "v",
            idx,
            raw.iter().map(|&v| Scalar::Int64(v)).collect::<Vec<_>>(),
        )
        .unwrap();

        let f = |xs: &[i64]| {
            fp_types::nanskew(
                &xs.iter()
                    .map(|&v| Scalar::Float64(v as f64))
                    .collect::<Vec<_>>(),
            )
            .to_f64()
            .unwrap()
        };
        let a_skew = f(&[1, 2, 2, 7]);
        let b_skew = f(&[3, 3, 9, 1]);

        let out = vals.groupby(&keys).unwrap().transform("skew").unwrap();
        let g = |s: &Scalar| match s {
            Scalar::Float64(v) => *v,
            _ => f64::NAN,
        };
        for i in 0..4 {
            assert!(
                (g(&out.values()[i]) - a_skew).abs() < 1e-9,
                "row {i} group a"
            );
        }
        for i in 4..8 {
            assert!(
                (g(&out.values()[i]) - b_skew).abs() < 1e-9,
                "row {i} group b"
            );
        }
        // kurt/kurtosis/sem aliases must also resolve (previously rejected).
        for func in ["kurt", "kurtosis", "sem"] {
            vals.groupby(&keys).unwrap().transform(func).unwrap();
        }
    }

    #[test]
    fn series_groupby_transform_dense_i64_std_var_min_max_blackthrush() {
        let idx: Vec<IndexLabel> = (0..5i64).map(Into::into).collect();
        let keys = Series::from_values(
            "k",
            idx.clone(),
            vec![
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(5),
                Scalar::Int64(5),
                Scalar::Int64(9),
            ],
        )
        .unwrap();
        let vals = Series::from_values(
            "v",
            idx,
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(3.0),
                Scalar::Float64(10.0),
                Scalar::Float64(14.0),
                Scalar::Float64(100.0),
            ],
        )
        .unwrap();
        let gb = vals.groupby(&keys).unwrap();
        assert_eq!(
            gb.transform("min").unwrap().values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Float64(1.0),
                Scalar::Float64(10.0),
                Scalar::Float64(10.0),
                Scalar::Float64(100.0),
            ]
        );
        assert_eq!(
            gb.transform("max").unwrap().values(),
            &[
                Scalar::Float64(3.0),
                Scalar::Float64(3.0),
                Scalar::Float64(14.0),
                Scalar::Float64(14.0),
                Scalar::Float64(100.0),
            ]
        );

        let var = gb.transform("var").unwrap();
        let std = gb.transform("std").unwrap();
        let as_f64 = |s: &Scalar| s.to_f64().unwrap();
        assert_eq!(as_f64(&var.values()[0]), 2.0);
        assert_eq!(as_f64(&var.values()[1]), 2.0);
        assert_eq!(as_f64(&var.values()[2]), 8.0);
        assert_eq!(as_f64(&var.values()[3]), 8.0);
        assert!(var.values()[4].is_missing());
        assert!((as_f64(&std.values()[0]) - 2.0_f64.sqrt()).abs() < 1e-12);
        assert!((as_f64(&std.values()[1]) - 2.0_f64.sqrt()).abs() < 1e-12);
        assert!((as_f64(&std.values()[2]) - 8.0_f64.sqrt()).abs() < 1e-12);
        assert!((as_f64(&std.values()[3]) - 8.0_f64.sqrt()).abs() < 1e-12);
        assert!(std.values()[4].is_missing());
    }

    #[test]
    fn series_groupby_agg_kurt_aliases_kl7yd() {
        // br-frankenpandas-kl7yd: SeriesGroupBy.agg now accepts kurt/kurtosis
        // (consistent with the direct .kurt() method).
        let idx: Vec<IndexLabel> = (0..5i64).map(Into::into).collect();
        let keys =
            Series::from_values("k", idx.clone(), vec![Scalar::Utf8("a".into()); 5]).unwrap();
        let vals = Series::from_values(
            "v",
            idx,
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(7),
                Scalar::Int64(3),
            ],
        )
        .unwrap();

        let direct = match &vals.groupby(&keys).unwrap().kurt().unwrap().values()[0] {
            Scalar::Float64(v) => *v,
            _ => f64::NAN,
        };
        let agg = vals.groupby(&keys).unwrap().agg(&["kurt"]).unwrap();
        let via_agg = match &agg.column(&agg.column_order[0]).unwrap().values()[0] {
            Scalar::Float64(v) => *v,
            _ => f64::NAN,
        };
        assert!(
            (direct - via_agg).abs() < 1e-9 || (direct.is_nan() && via_agg.is_nan()),
            "agg(kurt)={via_agg} vs kurt()={direct}"
        );
        // The 'kurtosis' alias must also resolve (previously rejected).
        vals.groupby(&keys).unwrap().agg(&["kurtosis"]).unwrap();
    }

    #[test]
    fn series_groupby_min_max_timedelta64_tgm2i() {
        // Per br-frankenpandas-tgm2i: SeriesGroupBy::min/max on Timedelta64
        // preserve dtype per group.
        let one_hour: i64 = 3_600 * 1_000_000_000;
        let keys = Series::from_values(
            "k",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Utf8("a".to_owned()),
                Scalar::Utf8("a".to_owned()),
                Scalar::Utf8("b".to_owned()),
                Scalar::Utf8("b".to_owned()),
            ],
        )
        .unwrap();
        let dur = Series::from_values(
            "dur",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Timedelta64(3 * one_hour),
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(5 * one_hour),
                Scalar::Timedelta64(2 * one_hour),
            ],
        )
        .unwrap();
        let mins = dur.groupby(&keys).unwrap().min().unwrap();
        match mins.values()[0] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, one_hour),
            ref other => panic!("expected Timedelta64(1h), got {:?}", other),
        }
        match mins.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 2 * one_hour),
            ref other => panic!("expected Timedelta64(2h), got {:?}", other),
        }
        let maxes = dur.groupby(&keys).unwrap().max().unwrap();
        match maxes.values()[0] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 3 * one_hour),
            ref other => panic!("expected Timedelta64(3h), got {:?}", other),
        }
        match maxes.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 5 * one_hour),
            ref other => panic!("expected Timedelta64(5h), got {:?}", other),
        }
    }

    #[test]
    fn series_groupby_temporal_keys_stay_typed_no6s4() {
        // br-frankenpandas-no6s4: a SeriesGroupBy keyed by Datetime64 /
        // Timedelta64 columns keeps the group-key labels TYPED, matching
        // pandas' DatetimeIndex / TimedeltaIndex output. The old catch-all
        // rendered EVERY unlisted dtype as the string "NaN", so two distinct
        // datetime keys shared one label. Discriminating: before the fix the
        // first assertion sees Utf8("NaN").
        let day: i64 = 86_400 * 1_000_000_000;
        let t0 = 1_704_067_200_000_000_000; // 2024-01-01T00:00Z in ns
        let positions = vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()];

        let dt_keys = Series::from_values(
            "k",
            positions.clone(),
            vec![
                Scalar::Datetime64(t0),
                Scalar::Datetime64(t0 + day),
                Scalar::Datetime64(t0),
                Scalar::Datetime64(t0 + day),
            ],
        )
        .unwrap();
        let vals = Series::from_values(
            "v",
            positions.clone(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(10),
                Scalar::Int64(2),
                Scalar::Int64(20),
            ],
        )
        .unwrap();
        let summed = vals.groupby(&dt_keys).unwrap().sum().unwrap();
        let labels = summed.index().labels();
        assert_eq!(labels.len(), 2);
        assert!(
            matches!(labels[0], IndexLabel::Datetime64(v) if v == t0),
            "expected typed Datetime64({t0}), got {:?}",
            labels[0]
        );
        assert!(
            matches!(labels[1], IndexLabel::Datetime64(v) if v == t0 + day),
            "expected typed Datetime64, got {:?}",
            labels[1]
        );

        let td_keys = Series::from_values(
            "k",
            positions,
            vec![
                Scalar::Timedelta64(day),
                Scalar::Timedelta64(2 * day),
                Scalar::Timedelta64(day),
                Scalar::Timedelta64(2 * day),
            ],
        )
        .unwrap();
        let summed_td = vals.groupby(&td_keys).unwrap().sum().unwrap();
        let td_labels = summed_td.index().labels();
        assert_eq!(td_labels.len(), 2);
        assert!(
            matches!(td_labels[0], IndexLabel::Timedelta64(v) if v == day),
            "expected typed Timedelta64, got {:?}",
            td_labels[0]
        );
        assert!(
            matches!(td_labels[1], IndexLabel::Timedelta64(v) if v == 2 * day),
            "expected typed Timedelta64, got {:?}",
            td_labels[1]
        );
    }

    #[test]
    fn series_groupby_sum_mean_timedelta64_c1bxu() {
        // Per br-frankenpandas-c1bxu: SeriesGroupBy::sum and mean on a
        // Timedelta64 source column preserve Timedelta dtype per group.
        let one_hour: i64 = 3_600 * 1_000_000_000;
        let keys = Series::from_values(
            "k",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("a".to_owned()),
                Scalar::Utf8("a".to_owned()),
                Scalar::Utf8("b".to_owned()),
            ],
        )
        .unwrap();
        let dur = Series::from_values(
            "dur",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Timedelta64(one_hour),
                Scalar::Timedelta64(2 * one_hour),
                Scalar::Timedelta64(5 * one_hour),
            ],
        )
        .unwrap();
        let sums = dur.groupby(&keys).unwrap().sum().unwrap();
        match sums.values()[0] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 3 * one_hour),
            ref other => panic!("expected Timedelta64(3h), got {:?}", other),
        }
        match sums.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 5 * one_hour),
            ref other => panic!("expected Timedelta64(5h), got {:?}", other),
        }
        let means = dur.groupby(&keys).unwrap().mean().unwrap();
        match means.values()[0] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 3 * one_hour / 2),
            ref other => panic!("expected Timedelta64(1.5h), got {:?}", other),
        }
        match means.values()[1] {
            Scalar::Timedelta64(ns) => assert_eq!(ns, 5 * one_hour),
            ref other => panic!("expected Timedelta64(5h), got {:?}", other),
        }
    }

