    #[test]
    fn dataframe_resample_cxq4t_parity_surface() {
        let df = DataFrame::from_dict_with_index(
            vec![
                (
                    "x",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(3.0),
                        Scalar::Float64(10.0),
                        Scalar::Float64(20.0),
                    ],
                ),
                (
                    "y",
                    vec![
                        Scalar::Float64(2.0),
                        Scalar::Float64(4.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(40.0),
                    ],
                ),
                (
                    "label",
                    vec![
                        Scalar::Utf8("a".into()),
                        Scalar::Utf8("b".into()),
                        Scalar::Utf8("c".into()),
                        Scalar::Utf8("c".into()),
                    ],
                ),
            ],
            vec![
                "2024-01-01".into(),
                "2024-01-15".into(),
                "2024-02-01".into(),
                "2024-02-20".into(),
            ],
        )
        .unwrap();
        let resample = df.resample("M");

        assert_eq!(resample.ngroups(), 2);
        assert_eq!(resample.ndim(), 2);
        assert_eq!(resample.level(), "M");
        assert_eq!(
            resample
                .groups()
                .get(&IndexLabel::Utf8("2024-02-29".into())),
            Some(&vec![2, 3])
        );
        assert_eq!(resample.get_group("2024-01-31").unwrap().len(), 2);

        let aggregate = resample
            .aggregate(&["sum", "mean", "sem", "size", "nunique"])
            .unwrap();
        assert_eq!(
            aggregate
                .column_names()
                .into_iter()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            vec![
                "x_sum",
                "x_mean",
                "x_sem",
                "x_size",
                "x_nunique",
                "y_sum",
                "y_mean",
                "y_sem",
                "y_size",
                "y_nunique"
            ]
        );
        assert_eq!(
            aggregate.columns()["x_mean"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(15.0)]
        );
        assert!((aggregate.columns()["x_sem"].values()[0].to_f64().unwrap() - 1.0).abs() < 1e-12);
        assert!((aggregate.columns()["x_sem"].values()[1].to_f64().unwrap() - 5.0).abs() < 1e-12);
        assert_eq!(
            aggregate.columns()["x_size"].values(),
            &[Scalar::Int64(2), Scalar::Int64(2)]
        );
        assert_eq!(
            aggregate.columns()["y_nunique"].values(),
            &[Scalar::Int64(2), Scalar::Int64(1)]
        );

        let quantile = resample.quantile(0.5).unwrap();
        assert_eq!(
            quantile.columns()["x"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(15.0)]
        );
        let sem = resample.sem().unwrap();
        assert!((sem.columns()["x"].values()[0].to_f64().unwrap() - 1.0).abs() < 1e-12);
        assert!((sem.columns()["x"].values()[1].to_f64().unwrap() - 5.0).abs() < 1e-12);

        let size = resample.size().unwrap();
        assert_eq!(size.values(), &[Scalar::Int64(2), Scalar::Int64(2)]);
        let nunique = resample.nunique().unwrap();
        assert_eq!(
            nunique.columns()["label"].values(),
            &[Scalar::Int64(2), Scalar::Int64(1)]
        );

        let ohlc = resample.ohlc().unwrap();
        assert!(ohlc.columns_multiindex().is_some());
        assert_eq!(
            ohlc.columns()["x_close"].values(),
            &[Scalar::Float64(3.0), Scalar::Float64(20.0)]
        );

        let transformed = resample.transform("mean").unwrap();
        assert_eq!(
            transformed.columns()["x"].values(),
            &[
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
                Scalar::Float64(15.0),
                Scalar::Float64(15.0)
            ]
        );
        assert_eq!(resample.pipe(|r| r.size()).unwrap().len(), 2);
        assert_eq!(
            resample.asfreq().unwrap().columns()["label"].values(),
            &[Scalar::Utf8("a".into()), Scalar::Utf8("c".into())]
        );
    }

