    #[test]
    fn series_hasnans_validity_short_circuit_equivalence_2jibm() {
        // hasnans() must equal the reference Scalar-path computation
        // (values().any(is_missing)) across dtypes — the short-circuit only
        // skips materialization, never changes the answer.
        let idx = |n: usize| (0..n as i64).map(IndexLabel::Int64).collect::<Vec<_>>();
        let cases: Vec<Vec<Scalar>> = vec![
            // all-valid Int64 (fast path -> false)
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
            // Int64 with a null (fast path -> true via validity)
            vec![Scalar::Int64(1), Scalar::Null(NullKind::NaN)],
            // all-valid Bool / Utf8 (fast path -> false)
            vec![Scalar::Bool(true), Scalar::Bool(false)],
            vec![Scalar::Utf8("a".into()), Scalar::Utf8("".into())],
            // Utf8 with a null
            vec![Scalar::Utf8("a".into()), Scalar::Null(NullKind::NaN)],
            // all-valid Float64 (deferred path -> false)
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
            // Float64 with an explicit NaN/null (deferred path)
            vec![Scalar::Float64(1.0), Scalar::Null(NullKind::NaN)],
            // Datetime64 with a NaT null (deferred path)
            vec![Scalar::Datetime64(1), Scalar::Null(NullKind::NaT)],
            // all-valid Datetime64 (deferred path -> false)
            vec![Scalar::Datetime64(1), Scalar::Datetime64(2)],
        ];
        for vals in cases {
            let s = Series::from_values("x", idx(vals.len()), vals).unwrap();
            let reference = s.column.values().iter().any(|v| v.is_missing());
            assert_eq!(
                s.hasnans(),
                reference,
                "hasnans mismatch for dtype {:?}",
                s.column.dtype()
            );
        }
    }

    #[test]
    fn series_argmin_argmax_int64_fast_path_feyjd() {
        let mk = |v: Vec<i64>| {
            Series::from_values(
                "x",
                (0..v.len() as i64)
                    .map(IndexLabel::Int64)
                    .collect::<Vec<_>>(),
                v.into_iter().map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap()
        };
        // The Int64 fast path must be exercised.
        let s = mk(vec![3, 1, 1, 2]);
        assert!(s.column.as_i64_slice().is_some());
        // argmin keeps the FIRST minimum (is_lt); argmax the first maximum (is_gt).
        assert_eq!(s.argmin().unwrap(), 1); // first 1 at idx 1
        assert_eq!(s.argmax().unwrap(), 0); // 3 at idx 0
        let s2 = mk(vec![5, 2, 5, 1]);
        assert_eq!(s2.argmax().unwrap(), 0); // first 5 at idx 0
        assert_eq!(s2.argmin().unwrap(), 3); // 1 at idx 3
        // Single, ascending, descending.
        assert_eq!(mk(vec![7]).argmin().unwrap(), 0);
        assert_eq!(mk(vec![7]).argmax().unwrap(), 0);
        assert_eq!(mk(vec![1, 2, 3]).argmin().unwrap(), 0);
        assert_eq!(mk(vec![1, 2, 3]).argmax().unwrap(), 2);
        assert_eq!(mk(vec![3, 2, 1]).argmin().unwrap(), 2);
        assert_eq!(mk(vec![3, 2, 1]).argmax().unwrap(), 0);
    }

    #[test]
    fn series_idxminmax_consistent_with_argminmax_l4m8o() {
        // Metamorphic invariant (br-frankenpandas-l4m8o): idxmin/idxmax return the
        // index label at the argmin/argmax position. Deterministic seeded LCG.
        let mut state: u64 = 0x1d24_a1b0_0a5cu64;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };
        for iter in 0..2000u32 {
            let n = (next() % 12) as usize + 1;
            // Non-trivial index labels (offset so labels != positions).
            let labels: Vec<IndexLabel> = (0..n as i64)
                .map(|i| IndexLabel::Int64(i * 10 + 3))
                .collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 7) as i64 - 3).collect();
            let s = Series::from_values(
                "x",
                labels.clone(),
                vals.iter().copied().map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap();
            let amin = s.argmin().unwrap() as usize;
            let amax = s.argmax().unwrap() as usize;
            assert_eq!(
                s.idxmin().unwrap(),
                labels[amin],
                "idxmin iter={iter} vals={vals:?}"
            );
            assert_eq!(
                s.idxmax().unwrap(),
                labels[amax],
                "idxmax iter={iter} vals={vals:?}"
            );
        }
    }

    #[test]
    fn series_is_unique_null_count_validity_path_160km() {
        let idx = |n: usize| (0..n as i64).map(IndexLabel::Int64).collect::<Vec<_>>();
        let mk = |vals: Vec<Scalar>| Series::from_values("x", idx(vals.len()), vals).unwrap();

        // Int64 fast path (null_count via validity).
        assert!(mk(vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)]).is_unique());
        assert!(!mk(vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(2)]).is_unique());
        // One null is allowed alongside distinct non-nulls; two nulls => dup.
        assert!(
            mk(vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN)
            ])
            .is_unique()
        );
        assert!(
            !mk(vec![
                Scalar::Int64(1),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN)
            ])
            .is_unique()
        );

        // Bool / Utf8 fast path.
        assert!(mk(vec![Scalar::Bool(true), Scalar::Bool(false)]).is_unique());
        assert!(!mk(vec![Scalar::Bool(true), Scalar::Bool(true)]).is_unique());
        assert!(mk(vec![Scalar::Utf8("a".into()), Scalar::Utf8("b".into())]).is_unique());
        assert!(!mk(vec![Scalar::Utf8("a".into()), Scalar::Utf8("a".into())]).is_unique());

        // Deferred dtypes (Float64 NaN, Datetime64 NaT) keep the Scalar path.
        assert!(mk(vec![Scalar::Float64(1.0), Scalar::Float64(2.0)]).is_unique());
        assert!(!mk(vec![Scalar::Float64(1.0), Scalar::Float64(1.0)]).is_unique());
        assert!(mk(vec![Scalar::Float64(1.0), Scalar::Null(NullKind::NaN)]).is_unique());
        assert!(mk(vec![Scalar::Datetime64(1), Scalar::Datetime64(2)]).is_unique());
        assert!(!mk(vec![Scalar::Datetime64(5), Scalar::Datetime64(5)]).is_unique());
    }

    #[test]
    fn series_predicate_fast_paths_match_scalar_reference_59dk2() {
        // Differential property harness (br-frankenpandas-59dk2): the typed /
        // validity fast paths added to Series predicates (is_monotonic_*, hasnans,
        // is_unique) must stay bit-identical to the pre-optimization Scalar-path
        // semantics across dtypes, nulls, NaN/NaT, ties, and sortedness.
        //
        // Deterministic seeded LCG — no external rand crate, no mocks, fully
        // reproducible. The reference values are read from the column's own
        // values() so they reflect exactly what the methods see after any
        // construction-time normalization.
        let mut state: u64 = 0x9e37_79b9_7f4a_7c15;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };

        let ref_hasnans = |vals: &[Scalar]| vals.iter().any(Scalar::is_missing);
        let ref_mono = |vals: &[Scalar], inc: bool| {
            if vals.len() <= 1 {
                return true;
            }
            for w in vals.windows(2) {
                if w[0].is_missing() || w[1].is_missing() {
                    return false;
                }
                let ok = if inc {
                    w[0].semantic_le(&w[1])
                } else {
                    w[0].semantic_ge(&w[1])
                };
                if !ok {
                    return false;
                }
            }
            true
        };

        for iter in 0..3000u32 {
            let dtype_pick = next() % 5;
            let len = (next() % 13) as usize;
            let inject_nulls = next() % 4 != 0;
            let force_sorted = next() % 3 == 0;

            // Small value range so ties / duplicates / equal-adjacent occur often.
            let mut raw: Vec<i64> = (0..len).map(|_| (next() % 7) as i64 - 3).collect();
            if force_sorted {
                raw.sort_unstable();
            }

            let vals: Vec<Scalar> = (0..len)
                .map(|i| {
                    if inject_nulls && next() % 5 == 0 {
                        let kind = if dtype_pick == 4 {
                            NullKind::NaT
                        } else {
                            NullKind::NaN
                        };
                        return Scalar::Null(kind);
                    }
                    match dtype_pick {
                        0 => Scalar::Int64(raw[i]),
                        1 if next() % 9 == 0 => Scalar::Float64(f64::NAN),
                        1 => Scalar::Float64(raw[i] as f64),
                        2 => Scalar::Bool(raw[i] & 1 == 0),
                        3 => Scalar::Utf8(format!("v{}", raw[i].rem_euclid(5))),
                        _ => Scalar::Datetime64(raw[i]),
                    }
                })
                .collect();

            let idx = (0..len as i64).map(IndexLabel::Int64).collect::<Vec<_>>();
            let Ok(s) = Series::from_values("p", idx, vals) else {
                continue;
            };

            // Canonical scalars as the methods actually see them.
            let cvals = s.column.values().to_vec();

            assert_eq!(
                s.hasnans(),
                ref_hasnans(&cvals),
                "hasnans mismatch iter={iter} dtype={dtype_pick} vals={cvals:?}"
            );
            assert_eq!(
                s.is_monotonic_increasing(),
                ref_mono(&cvals, true),
                "is_monotonic_increasing mismatch iter={iter} dtype={dtype_pick} vals={cvals:?}"
            );
            assert_eq!(
                s.is_monotonic_decreasing(),
                ref_mono(&cvals, false),
                "is_monotonic_decreasing mismatch iter={iter} dtype={dtype_pick} vals={cvals:?}"
            );

            // is_unique reference = the pre-160km formula (old null_count via the
            // Scalar scan) combined with the method's nunique(); this isolates and
            // verifies the validity-derived null_count change.
            let null_count = cvals.iter().filter(|v| v.is_missing()).count();
            let total_non_null = s.len() - null_count;
            let ref_unique = s.nunique() == total_non_null && null_count <= 1;
            assert_eq!(
                s.is_unique(),
                ref_unique,
                "is_unique mismatch iter={iter} dtype={dtype_pick} vals={cvals:?}"
            );
        }
    }

