    #[test]
    fn series_r6uci_where_and_multiindex_restructure_aliases() {
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ],
            vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)],
        )
        .unwrap();
        let cond = Series::from_values(
            "cond",
            vec![
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ],
            vec![Scalar::Bool(true), Scalar::Bool(false), Scalar::Bool(true)],
        )
        .unwrap();
        let other = Series::from_values(
            "other",
            vec![
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();

        assert_eq!(
            s.r#where(&cond, Some(&Scalar::Int64(-1))).unwrap(),
            s.where_cond(&cond, Some(&Scalar::Int64(-1))).unwrap()
        );
        assert_eq!(
            s.where_series(&cond, &other).unwrap(),
            s.where_cond_series(&cond, &other).unwrap()
        );

        let tuple_indexed = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("(outer, a)".into()),
                IndexLabel::Utf8("(outer, b)".into()),
            ],
            vec![Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        let swapped = tuple_indexed.swaplevel();
        assert_eq!(
            swapped.index().labels(),
            &[
                IndexLabel::Utf8("(a, outer)".into()),
                IndexLabel::Utf8("(b, outer)".into()),
            ]
        );
        assert_eq!(tuple_indexed.reorder_levels(&[1, 0]).unwrap(), swapped);
        let err = s.reorder_levels(&[1, 0]).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("tuple-style MultiIndex"))
        );
    }

    #[test]
    fn series_r6uci_compare_cov_get_pop_and_flags() {
        let s1 = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let s2 = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(4.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();

        assert_eq!(s1.compare(&s2).unwrap(), s1.compare_with(&s2).unwrap());
        assert_eq!(s1.cov(&s2).unwrap(), s1.cov_with(&s2).unwrap());
        assert_eq!(
            s1.get(&IndexLabel::Utf8("b".into())),
            Some(Scalar::Float64(2.0))
        );
        assert_eq!(s1.get(&IndexLabel::Utf8("missing".into())), None);
        assert_eq!(
            s1.get_or(&IndexLabel::Utf8("missing".into()), Scalar::Float64(-1.0)),
            Scalar::Float64(-1.0)
        );

        let (popped, remainder) = s1.pop(&IndexLabel::Utf8("b".into())).unwrap();
        assert_eq!(popped, Scalar::Float64(2.0));
        assert_eq!(
            remainder.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("c".into()),]
        );
        assert_eq!(
            remainder.values(),
            &[Scalar::Float64(1.0), Scalar::Float64(3.0)]
        );

        let dup = Series::from_values(
            "dup",
            vec![IndexLabel::Utf8("a".into()), IndexLabel::Utf8("a".into())],
            vec![Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        let err = dup.set_flags(Some(false)).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("duplicate labels"))
        );
    }

