    // ── DataFrame scalar arithmetic ──

    #[test]
    fn df_add_scalar() {
        let df = DataFrame::from_dict(
            &["x"],
            vec![("x", vec![Scalar::Int64(1), Scalar::Int64(2)])],
        )
        .unwrap();
        let result = df.add_scalar(10.0).unwrap();
        assert_eq!(result.columns()["x"].values()[0], Scalar::Float64(11.0));
        assert_eq!(result.columns()["x"].values()[1], Scalar::Float64(12.0));
    }

    #[test]
    fn df_add_scalar_nullable_int64_matches_reference_cf() {
        // A nullable Int64 column df op scalar routes through the typed
        // nullable-Int64 arm → Float64 output: present ⇒ Float64(v as f64 op
        // scalar); missing ⇒ Null(NaN). Build via from_i64_values_with_validity
        // to guarantee the LazyNullableInt64 backing the arm targets.
        let mut validity = fp_columnar::ValidityMask::all_valid(4);
        validity.set(1, false);
        let col = Column::from_i64_values_with_validity(vec![1, 0, 3, -5], validity);
        let mut cols = std::collections::BTreeMap::new();
        cols.insert("x".to_string(), col);
        let df = DataFrame::new(fp_index::Index::from_range(0, 4, 1), cols).unwrap();

        let added = df.add_scalar(10.0).unwrap();
        let av = added.columns()["x"].values();
        assert_eq!(added.columns()["x"].dtype(), DType::Float64);
        assert_eq!(av[0], Scalar::Float64(11.0));
        assert!(matches!(av[1], Scalar::Null(_)), "missing stays missing");
        assert_eq!(av[2], Scalar::Float64(13.0));
        assert_eq!(av[3], Scalar::Float64(5.0));

        let muled = df.mul_scalar(2.0).unwrap();
        let mv = muled.columns()["x"].values();
        assert_eq!(mv[0], Scalar::Float64(2.0));
        assert!(matches!(mv[1], Scalar::Null(_)));
        assert_eq!(mv[3], Scalar::Float64(-10.0));
    }

