    #[test]
    fn df_pandas_named_arithmetic_aliases_delegate_to_existing_ops() {
        let left = DataFrame::from_dict(
            &["x"],
            vec![("x", vec![Scalar::Float64(8.0), Scalar::Float64(12.0)])],
        )
        .unwrap();
        let right = DataFrame::from_dict(
            &["x"],
            vec![("x", vec![Scalar::Float64(2.0), Scalar::Float64(3.0)])],
        )
        .unwrap();

        assert_eq!(left.add(&right).unwrap(), left.add_df(&right).unwrap());
        assert_eq!(left.sub(&right).unwrap(), left.sub_df(&right).unwrap());
        assert_eq!(left.subtract(&right).unwrap(), left.sub_df(&right).unwrap());
        assert_eq!(left.mul(&right).unwrap(), left.mul_df(&right).unwrap());
        assert_eq!(left.multiply(&right).unwrap(), left.mul_df(&right).unwrap());
        assert_eq!(left.div(&right).unwrap(), left.div_df(&right).unwrap());
        assert_eq!(left.divide(&right).unwrap(), left.div_df(&right).unwrap());
        assert_eq!(left.truediv(&right).unwrap(), left.div_df(&right).unwrap());
        assert_eq!(
            left.floordiv(&right).unwrap(),
            left.floordiv_df(&right).unwrap()
        );
        assert_eq!(left.r#mod(&right).unwrap(), left.mod_df(&right).unwrap());
        assert_eq!(left.pow(&right).unwrap(), left.pow_df(&right).unwrap());

        assert_eq!(left.radd(&right).unwrap(), right.add_df(&left).unwrap());
        assert_eq!(left.rsub(&right).unwrap(), right.sub_df(&left).unwrap());
        assert_eq!(left.rmul(&right).unwrap(), right.mul_df(&left).unwrap());
        assert_eq!(left.rdiv(&right).unwrap(), right.div_df(&left).unwrap());
        assert_eq!(left.rtruediv(&right).unwrap(), right.div_df(&left).unwrap());
        assert_eq!(
            left.rfloordiv(&right).unwrap(),
            right.floordiv_df(&left).unwrap()
        );
        assert_eq!(left.rmod(&right).unwrap(), right.mod_df(&left).unwrap());
        assert_eq!(left.rpow(&right).unwrap(), right.pow_df(&left).unwrap());
    }

    #[test]
    fn df_pandas_named_arithmetic_aliases_accept_scalars() {
        let df = DataFrame::from_dict(
            &["x"],
            vec![("x", vec![Scalar::Float64(2.0), Scalar::Float64(4.0)])],
        )
        .unwrap();

        assert_eq!(df.add(3.0).unwrap(), df.add_scalar(3.0).unwrap());
        assert_eq!(df.sub(3.0).unwrap(), df.sub_scalar(3.0).unwrap());
        assert_eq!(df.subtract(3.0).unwrap(), df.sub_scalar(3.0).unwrap());
        assert_eq!(df.mul(3.0).unwrap(), df.mul_scalar(3.0).unwrap());
        assert_eq!(df.multiply(3.0).unwrap(), df.mul_scalar(3.0).unwrap());
        assert_eq!(df.div(2.0).unwrap(), df.div_scalar(2.0).unwrap());
        assert_eq!(df.divide(2.0).unwrap(), df.div_scalar(2.0).unwrap());
        assert_eq!(df.truediv(2.0).unwrap(), df.div_scalar(2.0).unwrap());
        assert_eq!(df.floordiv(3.0).unwrap(), df.floordiv_scalar(3.0).unwrap());
        assert_eq!(df.r#mod(3.0).unwrap(), df.mod_scalar(3.0).unwrap());
        assert_eq!(df.pow(3.0).unwrap(), df.pow_scalar(3.0).unwrap());

        let rsub = df.rsub(10.0).unwrap();
        assert_eq!(rsub.columns()["x"].values()[0], Scalar::Float64(8.0));
        assert_eq!(rsub.columns()["x"].values()[1], Scalar::Float64(6.0));

        let rdiv = df.rdiv(8.0).unwrap();
        assert_eq!(rdiv.columns()["x"].values()[0], Scalar::Float64(4.0));
        assert_eq!(rdiv.columns()["x"].values()[1], Scalar::Float64(2.0));

        let rfloordiv = df.rfloordiv(9.0).unwrap();
        assert_eq!(rfloordiv.columns()["x"].values()[0], Scalar::Float64(4.0));
        assert_eq!(rfloordiv.columns()["x"].values()[1], Scalar::Float64(2.0));

        let rmod = df.rmod(9.0).unwrap();
        assert_eq!(rmod.columns()["x"].values()[0], Scalar::Float64(1.0));
        assert_eq!(rmod.columns()["x"].values()[1], Scalar::Float64(1.0));

        let rpow = df.rpow(2.0).unwrap();
        assert_eq!(rpow.columns()["x"].values()[0], Scalar::Float64(4.0));
        assert_eq!(rpow.columns()["x"].values()[1], Scalar::Float64(16.0));
    }

    // ── Batch 12: Series duplicated/drop_duplicates/compare/reindex_like ──

    #[test]
    fn series_duplicated() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(3),
            ],
        )
        .unwrap();
        let dup = s.duplicated().unwrap();
        assert_eq!(dup.column().values()[0], Scalar::Bool(false));
        assert_eq!(dup.column().values()[1], Scalar::Bool(false));
        assert_eq!(dup.column().values()[2], Scalar::Bool(true));
        assert_eq!(dup.column().values()[3], Scalar::Bool(false));
    }

    #[test]
    fn series_drop_duplicates() {
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(3),
            ],
        )
        .unwrap();
        let result = s.drop_duplicates().unwrap();
        assert_eq!(result.len(), 3);
        assert_eq!(result.column().values()[0], Scalar::Int64(1));
        assert_eq!(result.column().values()[1], Scalar::Int64(2));
        assert_eq!(result.column().values()[2], Scalar::Int64(3));
    }

    #[test]
    fn series_compare_with() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();
        let s2 = Series::from_values(
            "b",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(99), Scalar::Int64(3)],
        )
        .unwrap();
        let diff = s1.compare_with(&s2).unwrap();
        // Only row 1 differs
        assert_eq!(diff.len(), 1);
        assert_eq!(diff.columns()["self"].values()[0], Scalar::Int64(2));
        assert_eq!(diff.columns()["other"].values()[0], Scalar::Int64(99));
    }

    #[test]
    fn series_compare_with_aligns_index() {
        let s1 = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        let s2 = Series::from_values(
            "b",
            vec![1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();

        let diff = s1.compare_with(&s2).unwrap();
        assert_eq!(diff.len(), 2);
        assert_eq!(
            diff.index().labels(),
            &[IndexLabel::Int64(0), IndexLabel::Int64(2)]
        );
        // ⚠️ NO PANDAS ORACLE BACKS THIS SHAPE. pandas REFUSES a compare across
        // differently-labelled Series — measured, 2.2.3:
        //   Series([1,2],index=[0,1]).compare(Series([2,3],index=[1,2]))
        //   -> ValueError: Can only compare identically-labeled Series objects
        // Aligning first is FrankenPandas' own contract, so these values are an
        // FP-defined expectation, not a parity claim. They are float because
        // both lanes gain a gap in that alignment and therefore widen, which IS
        // the pandas-measured align rule (br-frankenpandas-nywa8).
        assert_eq!(diff.columns()["self"].values()[0], Scalar::Float64(1.0));
        assert!(diff.columns()["other"].values()[0].is_missing());
        assert!(diff.columns()["self"].values()[1].is_missing());
        assert_eq!(diff.columns()["other"].values()[1], Scalar::Float64(3.0));
    }

    #[test]
    fn series_reindex_like() {
        let s1 = Series::from_values(
            "x",
            vec!["a".into(), "b".into(), "c".into()],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();
        let s2 = Series::from_values(
            "y",
            vec!["b".into(), "c".into(), "d".into()],
            vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)],
        )
        .unwrap();
        let result = s1.reindex_like(&s2).unwrap();
        assert_eq!(result.len(), 3);
        // Same RULE 1 widening as `reindex`. Live pandas 2.2.3:
        //   s1.reindex_like(s2) -> [2.0, 3.0, nan], dtype float64
        assert_eq!(result.column().values()[0], Scalar::Float64(2.0)); // b
        assert_eq!(result.column().values()[1], Scalar::Float64(3.0)); // c
        assert!(result.column().values()[2].is_missing()); // d -> NaN
    }

    // ── Batch 12: DataFrame row-axis aggregations ──

    #[test]
    fn df_sum_axis1() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)]),
                ("b", vec![Scalar::Float64(3.0), Scalar::Float64(4.0)]),
            ],
        )
        .unwrap();
        let result = df.sum_axis1().unwrap();
        assert_eq!(result.column().values()[0], Scalar::Float64(4.0));
        assert_eq!(result.column().values()[1], Scalar::Float64(6.0));
    }

    #[test]
    fn df_sum_prod_axis1_all_int64_preserves_int64_o9lmv() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![Scalar::Int64(1), Scalar::Int64(-2), Scalar::Int64(i64::MAX)],
                ),
                (
                    "b",
                    vec![Scalar::Int64(3), Scalar::Int64(4), Scalar::Int64(2)],
                ),
            ],
        )
        .unwrap();

        let sum = df.sum_axis1().unwrap();
        assert_eq!(sum.column().dtype(), DType::Int64);
        assert_eq!(sum.column().values()[0], Scalar::Int64(4));
        assert_eq!(sum.column().values()[1], Scalar::Int64(2));
        assert_eq!(
            sum.column().values()[2],
            Scalar::Int64(i64::MAX.wrapping_add(2))
        );

        let prod = df.prod_axis1().unwrap();
        assert_eq!(prod.column().dtype(), DType::Int64);
        assert_eq!(prod.column().values()[0], Scalar::Int64(3));
        assert_eq!(prod.column().values()[1], Scalar::Int64(-8));
        assert_eq!(
            prod.column().values()[2],
            Scalar::Int64(i64::MAX.wrapping_mul(2))
        );
    }

    #[test]
    fn df_min_max_axis1_all_int64_preserves_int64_uza04_158() {
        // br-frankenpandas-uza04.158: pandas keeps int64 for min/max(axis=1) over
        // pure-integer rows, and widens to float64 only when a Float64 column
        // participates. The sibling guard df_sum_prod_axis1_all_int64_preserves_int64_o9lmv
        // covers sum/prod; min/max route through the same reduce_rows_int64 reducer
        // but had no guard, so a regression to the generic `reduce_rows` fallback
        // (which emits Scalar::Float64) would have gone unnoticed.
        //
        // The i64::MAX / i64::MIN rows are the load-bearing negative case: neither
        // value is representable in f64 (i64::MAX as f64 rounds to i64::MAX + 1), so
        // a Float64 regression fails on the VALUE, not merely on the dtype. They also
        // pin the fold seeds — min seeds at i64::MAX and max seeds at i64::MIN, so a
        // row saturated at its own seed proves the seed is a genuine identity rather
        // than a "no contribution" sentinel that leaks.
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Int64(1),
                        Scalar::Int64(-2),
                        Scalar::Int64(i64::MAX),
                        Scalar::Int64(i64::MIN),
                        Scalar::Int64(i64::MIN),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Int64(3),
                        Scalar::Int64(4),
                        Scalar::Int64(i64::MAX),
                        Scalar::Int64(i64::MIN),
                        Scalar::Int64(i64::MAX),
                    ],
                ),
                (
                    "c",
                    vec![
                        Scalar::Int64(2),
                        Scalar::Int64(0),
                        Scalar::Int64(i64::MAX),
                        Scalar::Int64(i64::MIN),
                        Scalar::Int64(0),
                    ],
                ),
            ],
        )
        .unwrap();

        let min = df.min_axis1().unwrap();
        assert_eq!(min.column().dtype(), DType::Int64);
        assert_eq!(min.column().values()[0], Scalar::Int64(1));
        assert_eq!(min.column().values()[1], Scalar::Int64(-2));
        assert_eq!(min.column().values()[2], Scalar::Int64(i64::MAX));
        assert_eq!(min.column().values()[3], Scalar::Int64(i64::MIN));
        assert_eq!(min.column().values()[4], Scalar::Int64(i64::MIN));

        let max = df.max_axis1().unwrap();
        assert_eq!(max.column().dtype(), DType::Int64);
        assert_eq!(max.column().values()[0], Scalar::Int64(3));
        assert_eq!(max.column().values()[1], Scalar::Int64(4));
        assert_eq!(max.column().values()[2], Scalar::Int64(i64::MAX));
        assert_eq!(max.column().values()[3], Scalar::Int64(i64::MIN));
        assert_eq!(max.column().values()[4], Scalar::Int64(i64::MAX));

        // A lone Int64 column still reduces to itself, in Int64.
        let single = DataFrame::from_dict(
            &["only"],
            vec![(
                "only",
                vec![Scalar::Int64(7), Scalar::Int64(-7), Scalar::Int64(0)],
            )],
        )
        .unwrap();
        for reduced in [single.min_axis1().unwrap(), single.max_axis1().unwrap()] {
            assert_eq!(reduced.column().dtype(), DType::Int64);
            assert_eq!(reduced.column().values()[0], Scalar::Int64(7));
            assert_eq!(reduced.column().values()[1], Scalar::Int64(-7));
            assert_eq!(reduced.column().values()[2], Scalar::Int64(0));
        }

        // NEGATIVE (over-widening guard): a Float64 participant must still widen the
        // row to Float64. A naive "always emit Int64" fix would pass every assertion
        // above and fail here.
        let mixed = DataFrame::from_dict(
            &["i", "f"],
            vec![
                ("i", vec![Scalar::Int64(1), Scalar::Int64(5)]),
                ("f", vec![Scalar::Float64(2.5), Scalar::Float64(0.5)]),
            ],
        )
        .unwrap();

        let mixed_min = mixed.min_axis1().unwrap();
        assert_eq!(mixed_min.column().dtype(), DType::Float64);
        assert_eq!(mixed_min.column().values()[0], Scalar::Float64(1.0));
        assert_eq!(mixed_min.column().values()[1], Scalar::Float64(0.5));

        let mixed_max = mixed.max_axis1().unwrap();
        assert_eq!(mixed_max.column().dtype(), DType::Float64);
        assert_eq!(mixed_max.column().values()[0], Scalar::Float64(2.5));
        assert_eq!(mixed_max.column().values()[1], Scalar::Float64(5.0));

        // NEGATIVE (under-narrowing guard): a pure-Float64 frame stays Float64.
        let floats = DataFrame::from_dict(
            &["x", "y"],
            vec![
                ("x", vec![Scalar::Float64(1.5), Scalar::Float64(-3.25)]),
                ("y", vec![Scalar::Float64(4.0), Scalar::Float64(-1.0)]),
            ],
        )
        .unwrap();
        let float_min = floats.min_axis1().unwrap();
        assert_eq!(float_min.column().dtype(), DType::Float64);
        assert_eq!(float_min.column().values()[0], Scalar::Float64(1.5));
        assert_eq!(float_min.column().values()[1], Scalar::Float64(-3.25));
        let float_max = floats.max_axis1().unwrap();
        assert_eq!(float_max.column().dtype(), DType::Float64);
        assert_eq!(float_max.column().values()[0], Scalar::Float64(4.0));
        assert_eq!(float_max.column().values()[1], Scalar::Float64(-1.0));
    }

    #[test]
    fn grouped_resample_typed_gather_matches_scalar_path_vw0uu() {
        // br-frankenpandas-vw0uu: GroupByResample::apply_grouped_resample now gathers
        // each group's values through the raw f64/i64 slice (typed Column) and shares
        // one Arc-backed group Index across columns, instead of a per-cell
        // `col.values()[i].clone()` Vec<Scalar> plus a `Vec<IndexLabel>` deep-cloned
        // per column. This guard pins the OBSERVABLE contract that change must not move.
        //
        // Two value columns of DIFFERENT typed dtypes (Int64 + Float64) are the load-
        // bearing part: the second column exercises the shared-index reuse path, and
        // having one of each proves the typed gather preserves per-column dtype rather
        // than collapsing both to one backing. A third, NULLABLE column pins the
        // Scalar fallback that the typed gather must decline to.
        let ts = |d: i64| Scalar::Datetime64(d * 86_400_000_000_000);
        let df = DataFrame::from_dict(
            &["g", "t", "i", "f", "n"],
            vec![
                (
                    "g",
                    vec![
                        Scalar::Utf8("a".into()),
                        Scalar::Utf8("a".into()),
                        Scalar::Utf8("b".into()),
                        Scalar::Utf8("b".into()),
                    ],
                ),
                ("t", vec![ts(0), ts(1), ts(0), ts(1)]),
                (
                    "i",
                    vec![
                        Scalar::Int64(1),
                        Scalar::Int64(2),
                        Scalar::Int64(10),
                        Scalar::Int64(20),
                    ],
                ),
                (
                    "f",
                    vec![
                        Scalar::Float64(1.5),
                        Scalar::Float64(2.5),
                        Scalar::Float64(10.5),
                        Scalar::Float64(20.5),
                    ],
                ),
                (
                    "n",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(3.0),
                        Scalar::Float64(4.0),
                    ],
                ),
            ],
        )
        .unwrap();
        let indexed = df.set_index("t", true).unwrap();
        let grouped = indexed.groupby(&["g"]).unwrap();

        // Daily buckets: every row is its own bucket, so sum per bucket is the value
        // itself and the row count is preserved. Group "a" then group "b", in
        // build_groups order.
        let summed = grouped.resample("D").sum().unwrap();
        assert_eq!(summed.len(), 4, "one daily bucket per input row");

        let ivals = summed.columns["i"].values();
        let fvals = summed.columns["f"].values();
        let nvals = summed.columns["n"].values();
        assert_eq!(ivals.len(), 4);
        assert_eq!(fvals.len(), 4);
        assert_eq!(nvals.len(), 4);

        // Int64 column: resample sum over a single-element bucket preserves the value.
        // A gather that silently widened Int64 -> Float64 would fail these.
        let as_f = |s: &Scalar| -> f64 {
            match s {
                Scalar::Int64(v) => *v as f64,
                Scalar::Float64(v) => *v,
                other => panic!("unexpected resample output scalar: {other:?}"),
            }
        };
        assert!((as_f(&ivals[0]) - 1.0).abs() < 1e-12);
        assert!((as_f(&ivals[1]) - 2.0).abs() < 1e-12);
        assert!((as_f(&ivals[2]) - 10.0).abs() < 1e-12);
        assert!((as_f(&ivals[3]) - 20.0).abs() < 1e-12);

        // Float64 column keeps its own values — proves the SECOND column did not
        // inherit the first column's gathered buffer through the shared index reuse.
        assert!((as_f(&fvals[0]) - 1.5).abs() < 1e-12);
        assert!((as_f(&fvals[1]) - 2.5).abs() < 1e-12);
        assert!((as_f(&fvals[2]) - 10.5).abs() < 1e-12);
        assert!((as_f(&fvals[3]) - 20.5).abs() < 1e-12);

        // Nullable column takes the Scalar fallback (as_f64_slice declines on a
        // missing slot) and must still line up row-for-row.
        assert!((as_f(&nvals[0]) - 1.0).abs() < 1e-12);
        assert!((as_f(&nvals[2]) - 3.0).abs() < 1e-12);
        assert!((as_f(&nvals[3]) - 4.0).abs() < 1e-12);

        // The bucket labels are the real TIME buckets, not a positional 0..len.
        // Resample emits its buckets as `IndexLabel::Utf8` period keys (verified
        // against the emit sites in the Resample engine), so the variant check is
        // load-bearing here: had the group index been replaced with the positional
        // unit-range shortcut that grouped rolling/ewm legitimately use, the labels
        // would come back as Int64 0,1,0,1 — which would still satisfy the
        // equality/inequality assertions below, so those alone would NOT catch it.
        let labels = summed.index().labels();
        assert_eq!(labels.len(), 4);
        for label in labels {
            assert!(
                matches!(label, IndexLabel::Utf8(_)),
                "grouped resample must keep Utf8 period bucket labels, got {label:?}"
            );
        }
        assert_eq!(
            labels[0], labels[2],
            "both groups start at the same day-0 bucket"
        );
        assert_eq!(
            labels[1], labels[3],
            "both groups end at the same day-1 bucket"
        );
        assert_ne!(labels[0], labels[1], "day-0 and day-1 buckets differ");

        // mean over single-element buckets equals the value: a second agg through the
        // same typed path, guarding against an agg-specific gather regression.
        let meaned = grouped.resample("D").mean().unwrap();
        let mi = meaned.columns["i"].values();
        assert!((as_f(&mi[0]) - 1.0).abs() < 1e-12);
        assert!((as_f(&mi[3]) - 20.0).abs() < 1e-12);
    }

    #[test]
    fn df_axis1_reductions_skip_nan_skipna_default() {
        // pandas df.<reducer>(axis=1) defaults to skipna=True: NaN cells are
        // dropped before reducing. Row 0 = [1.0, NaN, 2.0]; row 1 = [NaN, NaN].
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                ("a", vec![Scalar::Float64(1.0), Scalar::Float64(f64::NAN)]),
                (
                    "b",
                    vec![Scalar::Float64(f64::NAN), Scalar::Float64(f64::NAN)],
                ),
                ("c", vec![Scalar::Float64(2.0), Scalar::Float64(f64::NAN)]),
            ],
        )
        .unwrap();

        // Row 0 skips the NaN: sum=3, mean=1.5, min=1, max=2, prod=2.
        let sum = df.sum_axis1().unwrap();
        assert_eq!(sum.column().values()[0], Scalar::Float64(3.0));
        let mean = df.mean_axis1().unwrap();
        assert_eq!(mean.column().values()[0], Scalar::Float64(1.5));
        let min = df.min_axis1().unwrap();
        assert_eq!(min.column().values()[0], Scalar::Float64(1.0));
        let max = df.max_axis1().unwrap();
        assert_eq!(max.column().values()[0], Scalar::Float64(2.0));
        let prod = df.prod_axis1().unwrap();
        assert_eq!(prod.column().values()[0], Scalar::Float64(2.0));

        // Row 1 is all-NaN: pandas min_count=0 identity — sum=0, prod=1; every
        // other reducer yields NaN.
        assert_eq!(sum.column().values()[1], Scalar::Float64(0.0));
        assert_eq!(prod.column().values()[1], Scalar::Float64(1.0));
        assert!(mean.column().values()[1].is_missing());
        assert!(min.column().values()[1].is_missing());
        assert!(max.column().values()[1].is_missing());
    }

    #[test]
    fn df_sum_axis1_includes_bool_columns_d3tdy() {
        // Per br-frankenpandas-d3tdy: pandas counts Bool as 0/1 in row-axis
        // reductions. Bool columns were previously dropped by the
        // numeric-cols filter.
        let df = DataFrame::from_dict(
            &["a", "b", "c"],
            vec![
                ("a", vec![Scalar::Bool(true), Scalar::Bool(false)]),
                ("b", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("c", vec![Scalar::Bool(true), Scalar::Bool(true)]),
            ],
        )
        .unwrap();
        let result = df.sum_axis1().unwrap();
        // row 0: True+1+True = 1+1+1 = 3
        // row 1: False+2+True = 0+2+1 = 3
        assert_eq!(result.column().values()[0], Scalar::Float64(3.0));
        assert_eq!(result.column().values()[1], Scalar::Float64(3.0));
    }

