    #[test]
    fn pivot_and_crosstab_sort_axes_like_pandas_r0t9l() {
        // Verified live pandas 2.2.3 (br-frankenpandas-r0t9l): both plain
        // pivot and crosstab sort BOTH axes ascending — first-seen input
        // order ['z','a'] / ['y','x'] / [10, 9] must come out sorted, with
        // numeric column buckets ordered numerically (9 before 10), not
        // lexicographically ("10" before "9").
        let df = DataFrame::from_series(vec![
            Series::from_values(
                "r",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Utf8("z".into()), Scalar::Utf8("a".into())],
            )
            .unwrap(),
            Series::from_values(
                "c",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Utf8("y".into()), Scalar::Utf8("x".into())],
            )
            .unwrap(),
            Series::from_values(
                "v",
                vec![0_i64.into(), 1_i64.into()],
                vec![Scalar::Int64(1), Scalar::Int64(2)],
            )
            .unwrap(),
        ])
        .unwrap();
        let pivoted = df.pivot("r", "c", "v").unwrap();
        // pandas: rows ['a','z'], cols ['x','y'], a×x=2, z×y=1, rest NaN.
        assert_eq!(
            pivoted.index.labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("z".into())]
        );
        assert_eq!(pivoted.column_order, vec!["x".to_owned(), "y".to_owned()]);
        assert_eq!(
            pivoted.columns["x"].values(),
            &[Scalar::Int64(2), Scalar::Null(NullKind::NaN)]
        );
        assert_eq!(
            pivoted.columns["y"].values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Int64(1)]
        );

        let idx = Series::from_values(
            "row_0",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("z".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("z".into()),
            ],
        )
        .unwrap();
        let cols = Series::from_values(
            "col_0",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![Scalar::Int64(10), Scalar::Int64(9), Scalar::Int64(10)],
        )
        .unwrap();
        let ct = DataFrame::crosstab(&idx, &cols).unwrap();
        // pandas: rows ['a','z'], cols [9, 10] (numeric order); a×9=1, z×10=2.
        assert_eq!(
            ct.index.labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("z".into())]
        );
        assert_eq!(ct.column_order, vec!["9".to_owned(), "10".to_owned()]);
        assert_eq!(
            ct.columns["9"].values(),
            &[Scalar::Int64(1), Scalar::Int64(0)]
        );
        assert_eq!(
            ct.columns["10"].values(),
            &[Scalar::Int64(0), Scalar::Int64(2)]
        );
    }

