    // ── DataFrame floordiv_df / mod_df ──

    #[test]
    fn df_floordiv_df() {
        let df1 = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Int64(7), Scalar::Int64(10)])],
        )
        .unwrap();
        let df2 = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Int64(3), Scalar::Int64(4)])],
        )
        .unwrap();
        let result = df1.floordiv_df(&df2).unwrap();
        // 7 // 3 = 2.0, 10 // 4 = 2.0
        assert_eq!(result.columns["a"].values()[0], Scalar::Float64(2.0));
        assert_eq!(result.columns["a"].values()[1], Scalar::Float64(2.0));
    }

    #[test]
    fn df_mod_df() {
        let df1 = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Int64(7), Scalar::Int64(10)])],
        )
        .unwrap();
        let df2 = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Int64(3), Scalar::Int64(4)])],
        )
        .unwrap();
        let result = df1.mod_df(&df2).unwrap();
        // 7 % 3 = 1.0, 10 % 4 = 2.0
        assert_eq!(result.columns["a"].values()[0], Scalar::Float64(1.0));
        assert_eq!(result.columns["a"].values()[1], Scalar::Float64(2.0));
    }

    #[test]
    fn df_mod_and_div_match_pandas_sign_and_inf() {
        // pandas DataFrame mod uses the DIVISOR's sign (floored), and div/
        // floordiv by zero give +/-inf (numerator sign), not NaN. Verified vs
        // live pandas 2.2.3. (Sibling cluster of br 5btt1.)
        let df = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Float64(-7.0), Scalar::Float64(7.0)])],
        )
        .unwrap();

        // mod_scalar: -7 % 3 == 2, 7 % 3 == 1 (floored).
        let m = df.mod_scalar(3.0).unwrap();
        assert_eq!(m.columns()["a"].values()[0], Scalar::Float64(2.0));
        assert_eq!(m.columns()["a"].values()[1], Scalar::Float64(1.0));

        // mod_scalar with a negative divisor: -7 % -3 == -1, 7 % -3 == -2.
        let mn = df.mod_scalar(-3.0).unwrap();
        assert_eq!(mn.columns()["a"].values()[0], Scalar::Float64(-1.0));
        assert_eq!(mn.columns()["a"].values()[1], Scalar::Float64(-2.0));

        // rmod scalar: 3 % column -> 3 % -7 == -4 (divisor sign), 3 % 7 == 3.
        let rm = df.rmod(3.0).unwrap();
        assert_eq!(rm.columns()["a"].values()[0], Scalar::Float64(-4.0));
        assert_eq!(rm.columns()["a"].values()[1], Scalar::Float64(3.0));

        // div by zero -> +/-inf (sign of numerator).
        let d = df.div_scalar(0.0).unwrap();
        assert_eq!(
            d.columns()["a"].values()[0],
            Scalar::Float64(f64::NEG_INFINITY)
        );
        assert_eq!(d.columns()["a"].values()[1], Scalar::Float64(f64::INFINITY));
    }

    #[test]
    fn df_floordiv_scalar() {
        let df = DataFrame::from_dict(
            &["v"],
            vec![("v", vec![Scalar::Int64(7), Scalar::Int64(10)])],
        )
        .unwrap();
        let result = df.floordiv_scalar(3.0).unwrap();
        assert_eq!(result.columns["v"].values()[0], Scalar::Float64(2.0));
        assert_eq!(result.columns["v"].values()[1], Scalar::Float64(3.0));
    }

    // ── get_dummies ──

    #[test]
    fn df_get_dummies_basic() {
        let df = DataFrame::from_dict(
            &["color", "value"],
            vec![
                (
                    "color",
                    vec![
                        Scalar::Utf8("red".to_string()),
                        Scalar::Utf8("blue".to_string()),
                        Scalar::Utf8("red".to_string()),
                    ],
                ),
                (
                    "value",
                    vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
                ),
            ],
        )
        .unwrap();
        let result = df.get_dummies(&["color"]).unwrap();
        // Should have: color_red, color_blue, value
        assert!(result.columns.contains_key("color_red"));
        assert!(result.columns.contains_key("color_blue"));
        assert!(result.columns.contains_key("value"));
        assert!(!result.columns.contains_key("color"));

        // Check indicator values (pandas 2.x get_dummies emits bool columns).
        assert_eq!(result.columns["color_red"].values()[0], Scalar::Bool(true));
        assert_eq!(result.columns["color_red"].values()[1], Scalar::Bool(false));
        assert_eq!(result.columns["color_red"].values()[2], Scalar::Bool(true));
        assert_eq!(
            result.columns["color_blue"].values()[0],
            Scalar::Bool(false)
        );
        assert_eq!(result.columns["color_blue"].values()[1], Scalar::Bool(true));
        assert_eq!(
            result.columns["color_blue"].values()[2],
            Scalar::Bool(false)
        );
    }

