    // ── to_numeric ──

    #[test]
    fn to_numeric_basic() {
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("10".to_string()),
                Scalar::Utf8("20.5".to_string()),
                Scalar::Utf8("bad".to_string()),
            ],
        )
        .unwrap();
        // Bare to_numeric now defaults to errors='raise' (pandas default), so
        // the unparseable "bad" must be rejected; the coerce policy still maps
        // it to NaN.
        assert!(to_numeric(&s).is_err());
        let result = to_numeric_with_options(
            &s,
            ToNumericOptions {
                errors: ToNumericErrors::Coerce,
            },
        )
        .unwrap();
        assert_eq!(result.column().dtype(), DType::Float64);
        assert_eq!(result.column().values()[0], Scalar::Float64(10.0));
        assert_eq!(result.column().values()[1], Scalar::Float64(20.5));
        assert!(result.column().values()[2].is_missing());
    }

    #[test]
    fn to_numeric_all_ints() {
        let s = Series::from_values(
            "ints",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("42".to_string()),
                Scalar::Utf8("99".to_string()),
            ],
        )
        .unwrap();
        let result = to_numeric(&s).unwrap();
        assert_eq!(result.column().dtype(), DType::Int64);
        assert_eq!(result.column().values()[0], Scalar::Int64(42));
        assert_eq!(result.column().values()[1], Scalar::Int64(99));
    }

    #[test]
    fn to_numeric_errors_option() {
        // br-frankenpandas-tonum-err: pandas pd.to_numeric exposes errors=, FP
        // previously only had the coerce behavior. Mirror the three policies.
        let s = Series::from_values(
            "d",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("10".to_string()),
                Scalar::Utf8("x".to_string()),
                Scalar::Utf8("30".to_string()),
            ],
        )
        .unwrap();

        // raise: errors on the first unparseable value (pandas default semantics).
        let raised = to_numeric_with_options(
            &s,
            ToNumericOptions {
                errors: ToNumericErrors::Raise,
            },
        );
        assert!(raised.is_err(), "errors=raise must reject 'x'");

        // coerce: unparseable -> NaN (== the bare to_numeric convenience).
        let coerced = to_numeric_with_options(
            &s,
            ToNumericOptions {
                errors: ToNumericErrors::Coerce,
            },
        )
        .unwrap();
        assert_eq!(coerced.column().values()[0], Scalar::Float64(10.0));
        assert!(coerced.column().values()[1].is_missing());
        assert_eq!(coerced.column().values()[2], Scalar::Float64(30.0));
        // Bare to_numeric defaults to raise, so it rejects this dirty input.
        assert!(to_numeric(&s).is_err());

        // ignore: any failure returns the input Series unchanged.
        let ignored = to_numeric_with_options(
            &s,
            ToNumericOptions {
                errors: ToNumericErrors::Ignore,
            },
        )
        .unwrap();
        assert_eq!(ignored.column().values()[0], Scalar::Utf8("10".to_string()));
        assert_eq!(ignored.column().values()[1], Scalar::Utf8("x".to_string()));

        // A clean Series converts identically under all three policies.
        let clean = Series::from_values(
            "d",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Utf8("1".to_string()), Scalar::Utf8("2".to_string())],
        )
        .unwrap();
        for errors in [
            ToNumericErrors::Raise,
            ToNumericErrors::Coerce,
            ToNumericErrors::Ignore,
        ] {
            let out = to_numeric_with_options(&clean, ToNumericOptions { errors }).unwrap();
            assert_eq!(out.column().values()[0], Scalar::Int64(1));
            assert_eq!(out.column().values()[1], Scalar::Int64(2));
        }
    }

    // ── cut / qcut ──

    #[test]
    fn cut_basic() {
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(0.0),
                Scalar::Float64(5.0),
                Scalar::Float64(7.5),
                Scalar::Float64(10.0),
            ],
        )
        .unwrap();
        let result = cut(&s, 2).unwrap();
        // Bins: (0.0, 5.0] and (5.0, 10.0]
        assert_eq!(result.column().dtype(), DType::Utf8);
        assert_eq!(result.len(), 4);
        // 0.0 falls in first bin, 5.0 in first bin, 7.5 in second, 10.0 in second
        let v0 = &result.column().values()[0];
        let v1 = &result.column().values()[1];
        let v3 = &result.column().values()[3];
        assert!(matches!(v0, Scalar::Utf8(_)));
        // Values at boundaries should have labels
        assert!(matches!(v1, Scalar::Utf8(_)));
        assert!(matches!(v3, Scalar::Utf8(_)));
    }

    #[test]
    fn qcut_basic() {
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();
        let result = qcut(&s, 2).unwrap();
        assert_eq!(result.column().dtype(), DType::Utf8);
        assert_eq!(result.len(), 4);
        // First two values in first quantile, last two in second
        let v0 = &result.column().values()[0];
        let v3 = &result.column().values()[3];
        assert!(matches!(v0, Scalar::Utf8(_)));
        assert!(matches!(v3, Scalar::Utf8(_)));
        // The labels should be different for first and last
        assert_ne!(v0, v3);
    }

    #[test]
    fn cut_with_nan() {
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let result = cut(&s, 2).unwrap();
        assert!(result.column().values()[1].is_missing());
    }

    #[test]
    fn cut_qcut_stored_float64_nan_stays_unbinned() {
        // A stored Float64(NaN) (validity-set NaN, not a Null) must be kept as
        // NaN by cut/qcut, like pandas — never collected into the bin-edge stats
        // nor assigned a bin label. Regression: `to_f64().ok()` returned
        // Some(NaN) which previously landed the NaN in bin 0.
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(f64::NAN),
                Scalar::Float64(3.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        let cut_res = cut(&s, 2).unwrap();
        assert!(cut_res.column().values()[1].is_missing());
        // The non-NaN values are still binned (not all-NaN short-circuit).
        assert!(!cut_res.column().values()[0].is_missing());
        assert!(!cut_res.column().values()[3].is_missing());

        let qcut_res = qcut(&s, 2).unwrap();
        assert!(qcut_res.column().values()[1].is_missing());
        assert!(!qcut_res.column().values()[0].is_missing());
        assert!(!qcut_res.column().values()[3].is_missing());
    }

