    #[test]
    fn dataframe_arg_axis1_parallel_matches_serial_blackthrush() {
        // Exercise the >=50k-row PARALLEL contiguous-Utf8 arg-extrema axis=1 fast
        // path (idxmin/idxmax/argmax). Independent first-min/first-max column
        // recompute must match the parallel output bit-for-bit, including at the
        // 3-worker chunk boundaries (ceil(60000/3)=20000 -> 20000, 40000).
        let n = 60_000usize;
        let names = ["c0", "c1", "c2", "c3"];
        let mut cols: Vec<Vec<f64>> = (0..4).map(|_| Vec::with_capacity(n)).collect();
        for r in 0..n {
            cols[0].push((r % 7) as f64);
            cols[1].push((r % 5) as f64);
            cols[2].push((r % 11) as f64);
            cols[3].push((r % 3) as f64);
        }
        let mut columns = BTreeMap::new();
        for (i, nm) in names.iter().enumerate() {
            columns.insert(
                (*nm).to_string(),
                Column::from_f64_values(std::mem::take(&mut cols[i])),
            );
        }
        let df = DataFrame::new_with_column_order(
            Index::new_known_unique_int64_unit_range(0, n),
            columns,
            names.iter().map(|s| (*s).to_string()).collect::<Vec<_>>(),
        )
        .unwrap();

        let imin = df.idxmin_axis1().unwrap();
        let imax = df.idxmax_axis1().unwrap();
        let amax = df.argmax_axis1().unwrap();
        // sanity: contiguous-Utf8 output length + a couple of full-column spot rows
        assert_eq!(imin.len(), n);
        assert_eq!(imax.len(), n);
        for &r in &[
            0usize, 1, 19_999, 20_000, 20_001, 39_999, 40_000, 40_001, 59_999,
        ] {
            let v = [
                (r % 7) as f64,
                (r % 5) as f64,
                (r % 11) as f64,
                (r % 3) as f64,
            ];
            let mut bi_min = 0usize;
            let mut bi_max = 0usize;
            for i in 1..4 {
                if v[i] < v[bi_min] {
                    bi_min = i;
                }
                if v[i] > v[bi_max] {
                    bi_max = i;
                }
            }
            assert_eq!(
                imin.values()[r],
                Scalar::Utf8(names[bi_min].to_string()),
                "idxmin row {r}"
            );
            assert_eq!(
                imax.values()[r],
                Scalar::Utf8(names[bi_max].to_string()),
                "idxmax row {r}"
            );
            // argmax_axis1 (largest) == idxmax (first-max-wins)
            assert_eq!(
                amax.values()[r],
                Scalar::Utf8(names[bi_max].to_string()),
                "argmax row {r}"
            );
        }
    }

