    /// `.dt.to_period(freq)` on VALUES, against pandas' measured labels.
    ///
    /// MEASURED, pandas 2.2.3, on ['2024-03-10 01:30:45', '2024-12-31 23:59:59', NaT] —
    /// and independently reproduced by the oracle handler in fp-conformance:
    /// ```text
    ///   'Y' -> 2024,       2024,       NaT
    ///   'Q' -> 2024Q1,     2024Q4,     NaT
    ///   'M' -> 2024-03,    2024-12,    NaT
    ///   'D' -> 2024-03-10, 2024-12-31, NaT
    /// ```
    ///
    /// The 2024-12-31 row is the one that separates a real calendar conversion from a
    /// string truncation: under 'Q' it must be 2024Q4, which no prefix of the input
    /// contains.
    #[test]
    fn dt_to_period_on_values_matches_pandas() {
        let s = Series::from_values(
            "d",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2024-03-10 01:30:45".into()),
                Scalar::Utf8("2024-12-31 23:59:59".into()),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();

        for (freq, first, second) in [
            ("Y", "2024", "2024"),
            ("Q", "2024Q1", "2024Q4"),
            ("M", "2024-03", "2024-12"),
            ("D", "2024-03-10", "2024-12-31"),
        ] {
            let out = s.dt().to_period(freq).expect("to_period");
            assert_eq!(
                out.values()[0],
                Scalar::Utf8(first.to_string()),
                "freq {freq} row0"
            );
            assert_eq!(
                out.values()[1],
                Scalar::Utf8(second.to_string()),
                "freq {freq} row1"
            );
            assert!(out.values()[2].is_missing(), "freq {freq} NaT row");
        }

        // ⚠️ NOT the same operation as `Series::to_period`, which converts the
        // INDEX and leaves the values alone. Both exist; this pins the difference.
        //
        // The index form needs DATETIME-LIKE INDEX LABELS — it rejects the Int64
        // index used above, so this uses its own series. (My first draft called it
        // on `s` and would have panicked on the Err.)
        let idx_series = Series::from_values(
            "d",
            vec![
                IndexLabel::Utf8("2024-03-10".into()),
                IndexLabel::Utf8("2024-12-31".into()),
            ],
            vec![Scalar::Int64(7), Scalar::Int64(8)],
        )
        .unwrap();
        let idx_form = idx_series.to_period("M").expect("Series::to_period");
        assert_eq!(
            idx_form.values()[0],
            Scalar::Int64(7),
            "Series::to_period must leave VALUES untouched"
        );
        assert_eq!(
            idx_form.index().labels()[0],
            IndexLabel::Utf8("2024-03".into()),
            "Series::to_period must convert the INDEX"
        );
    }

    /// `.dt.components` against pandas' measured 7-column output, and
    /// `.dt.to_pytimedelta`'s half-to-even rounding.
    ///
    /// MEASURED, pandas 2.2.3, `pd.to_timedelta([90061.5s, -1s, NaT, 0s])`:
    /// ```text
    ///   days [1,-1,nan,0]  hours [1,23,nan,0]  minutes [1,59,nan,0]
    ///   seconds [1,59,nan,0]  milliseconds [500,0,nan,0]
    ///   microseconds [0,0,nan,0]  nanoseconds [0,0,nan,0]
    /// ```
    /// The -1s row is the load-bearing one: the split is EUCLIDEAN, so it is
    /// -1 day + 23:59:59, not a negative hour field.
    #[test]
    fn dt_timedelta_components_and_to_pytimedelta_match_pandas() {
        use fp_types::Timedelta;
        let td = |ns: i64| Scalar::Timedelta64(ns);
        let s = Series::from_values(
            "td",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                td(90_061_500_000_000),
                td(-Timedelta::NANOS_PER_SEC),
                Scalar::Null(NullKind::NaN),
                td(0),
            ],
        )
        .unwrap();

        let c = s.dt().components().expect("components");
        // A NaT is present, so pandas promotes every column to float64.
        let expect: [(&str, [f64; 3]); 7] = [
            ("days", [1.0, -1.0, 0.0]),
            ("hours", [1.0, 23.0, 0.0]),
            ("minutes", [1.0, 59.0, 0.0]),
            ("seconds", [1.0, 59.0, 0.0]),
            ("milliseconds", [500.0, 0.0, 0.0]),
            ("microseconds", [0.0, 0.0, 0.0]),
            ("nanoseconds", [0.0, 0.0, 0.0]),
        ];
        for (name, vals) in expect {
            let col = &c.columns[name];
            assert_eq!(col.values()[0], Scalar::Float64(vals[0]), "{name} row0");
            assert_eq!(
                col.values()[1],
                Scalar::Float64(vals[1]),
                "{name} row1 (euclidean)"
            );
            assert!(col.values()[2].is_missing(), "{name} NaT row");
            assert_eq!(col.values()[3], Scalar::Float64(vals[2]), "{name} row3");
        }

        // With NOTHING missing pandas gives int64 instead — the promotion is
        // demand-driven, not a fixed dtype choice.
        let clean = Series::from_values(
            "td",
            vec![0_i64.into(), 1_i64.into()],
            vec![td(90_061_500_000_000), td(-Timedelta::NANOS_PER_SEC)],
        )
        .unwrap();
        let cc = clean.dt().components().expect("components");
        assert_eq!(cc.columns["days"].values()[0], Scalar::Int64(1));
        assert_eq!(cc.columns["days"].values()[1], Scalar::Int64(-1));
        assert_eq!(cc.columns["hours"].values()[1], Scalar::Int64(23));

        // ⚠️ to_pytimedelta ROUNDS to microseconds, ties to EVEN. Truncation would
        // pass only the 1 / -1 rows below and fail every other one.
        let rounding = Series::from_values(
            "td",
            (0..7_i64).map(Into::into).collect::<Vec<_>>(),
            vec![
                td(1),
                td(-1),
                td(999),
                td(-999),
                td(500),
                td(1500),
                td(2500),
            ],
        )
        .unwrap();
        let r = rounding.dt().to_pytimedelta().expect("to_pytimedelta");
        let got: Vec<i64> = r
            .values()
            .iter()
            .map(|v| match v {
                Scalar::Timedelta64(n) => *n,
                other => panic!("expected Timedelta64, got {other:?}"),
            })
            .collect();
        assert_eq!(got, vec![0, 0, 1_000, -1_000, 0, 2_000, 2_000]);

        // NaT survives as missing.
        let with_nat =
            Series::from_values("td", vec![0_i64.into()], vec![Scalar::Null(NullKind::NaN)])
                .unwrap();
        assert!(
            with_nat
                .dt()
                .to_pytimedelta()
                .expect("to_pytimedelta")
                .values()[0]
                .is_missing()
        );
    }

    /// br-frankenpandas-timedelta-nat-days-returns-zero-406ni: the four
    /// Timedelta component accessors, against pandas' measured answers.
    ///
    /// MEASURED, pandas 2.2.3, `pd.to_timedelta([1, None, -1, 90061.5], unit='s')`:
    /// ```text
    ///   .dt.days         -> [0.0, nan, -1.0, 1.0]        dtype float64
    ///   .dt.seconds      -> [1.0, nan, 86399.0, 3661.0]
    ///   .dt.microseconds -> [0.0, nan, 0.0, 500000.0]
    ///   .dt.nanoseconds  -> [0.0, nan, 0.0, 0.0]
    /// ```
    ///
    /// The -1s row is the one an implementation gets wrong: the day/second split
    /// is EUCLIDEAN, so it is days -1 / seconds 86399, not 0 / -1. The NaT row is
    /// the other: it must come out MISSING, never 0. That used to rest on this
    /// accessor testing `NAT` before calling the helper, because
    /// `Timedelta::days(NAT)` returned 0 internally; the helpers now return
    /// `Option<i64>` and answer `None` themselves
    /// (br-frankenpandas-timedelta-nat-days-returns-zero-406ni), so the row is
    /// still the interesting one but no longer a convention anybody can drop.
    #[test]
    fn dt_timedelta_components_match_pandas_406ni() {
        use fp_types::Timedelta;
        let s = Series::from_values(
            "td",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Timedelta64(Timedelta::NANOS_PER_SEC),
                Scalar::Null(NullKind::NaN),
                Scalar::Timedelta64(-Timedelta::NANOS_PER_SEC),
                Scalar::Timedelta64(90_061_500_000_000),
            ],
        )
        .unwrap();

        let days = s.dt().days().expect("days");
        assert_eq!(days.values()[0], Scalar::Float64(0.0));
        assert!(days.values()[1].is_missing(), "NaT must not become 0");
        assert_eq!(days.values()[2], Scalar::Float64(-1.0));
        assert_eq!(days.values()[3], Scalar::Float64(1.0));

        let secs = s.dt().seconds().expect("seconds");
        assert_eq!(secs.values()[0], Scalar::Float64(1.0));
        assert!(secs.values()[1].is_missing());
        assert_eq!(
            secs.values()[2],
            Scalar::Float64(86399.0),
            "euclidean remainder"
        );
        assert_eq!(secs.values()[3], Scalar::Float64(3661.0));

        let micros = s.dt().microseconds().expect("microseconds");
        assert_eq!(micros.values()[0], Scalar::Float64(0.0));
        assert!(micros.values()[1].is_missing());
        assert_eq!(micros.values()[3], Scalar::Float64(500_000.0));

        let nanos = s.dt().nanoseconds().expect("nanoseconds");
        assert_eq!(nanos.values()[0], Scalar::Float64(0.0));
        assert!(nanos.values()[1].is_missing());
        assert_eq!(nanos.values()[3], Scalar::Float64(0.0));

        // ⚠️ DTYPE FOLLOWS PANDAS' PROMOTION RULE, not a fixed choice. The series
        // above contains a NaT, so pandas gives float64 — asserted throughout. With
        // NO missing value pandas gives int64 instead:
        //     pd.to_timedelta([1, -1], unit='s').dt.days -> int64 [0, -1]
        // An earlier version of this accessor emitted Float64 unconditionally.
        let clean = Series::from_values(
            "td",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Timedelta64(Timedelta::NANOS_PER_SEC),
                Scalar::Timedelta64(-Timedelta::NANOS_PER_SEC),
            ],
        )
        .unwrap();
        let clean_days = clean.dt().days().expect("days");
        assert_eq!(clean_days.values()[0], Scalar::Int64(0));
        assert_eq!(clean_days.values()[1], Scalar::Int64(-1));
        let clean_secs = clean.dt().seconds().expect("seconds");
        assert_eq!(clean_secs.values()[0], Scalar::Int64(1));
        assert_eq!(clean_secs.values()[1], Scalar::Int64(86399));
    }

    #[test]
    fn dt_total_seconds() {
        // Per br-frankenpandas-i9bah: pandas dt.total_seconds() is for
        // timedelta dtype only, returns Float64.
        let s = Series::from_values(
            "d",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Timedelta64(fp_types::Timedelta::NANOS_PER_DAY), // 1 day
                Scalar::Timedelta64(fp_types::Timedelta::NANOS_PER_HOUR * 2), // 2 hours
            ],
        )
        .unwrap();
        let result = s.dt().total_seconds().unwrap();
        assert_eq!(result.values()[0], Scalar::Float64(86400.0)); // 1 day = 86400 seconds
        assert_eq!(result.values()[1], Scalar::Float64(7200.0)); // 2 hours = 7200 seconds
    }

    /// br-frankenpandas-nywa8, the `.dt` slice: the missing marker a `.dt`
    /// accessor emits is derived from its RESULT dtype, not carried over from
    /// the input. A `.dt` value lives in a datetime64/timedelta64 column where
    /// the gap is NaT, and NaT renders into the result as that dtype's own gap.
    ///
    /// Measured, live pandas 2.2.3, every input GIVEN a python `None`:
    /// ```text
    ///   pd.to_datetime(pd.Series(['2024-03-15T14:30:00', None]), errors='coerce')
    ///     .dt.strftime('%Y/%m/%d %H:%M')
    ///       dtype object -> [('str', '2024/03/15 14:30'), ('float', nan)]
    ///       the missing cell `is None` -> False, `isnan` -> True
    ///   pd.to_timedelta(pd.Series(['1 days 00:00:00', None, '0 days 01:30:00']))
    ///     .dt.total_seconds()
    ///       dtype float64 -> [86400.0, nan, 5400.0]
    /// ```
    /// So even though `strftime`'s output column is OBJECT — the one dtype where
    /// pandas otherwise preserves a supplied `None` (br-frankenpandas-lufpu) —
    /// the gap here is a float `nan`, because it never existed as a `None` in an
    /// object column: it was a NaT in a datetime column first. That is the
    /// distinction lufpu and this bead have to hold at once, and it is why the
    /// rule is "derive from the dtype the value LIVED IN", not "object preserves".
    /// br-frankenpandas-nywa8 RULE 2, on the list-like constructor: a SUPPLIED
    /// missing value survives only if the dtype can store it. numpy int64
    /// cannot, so the column widens to float64 and the marker normalizes to
    /// NaN — while an OBJECT column keeps the caller's `None`, which is the
    /// dtype-dependence br-frankenpandas-lufpu relies on.
    ///
    /// Measured, live pandas 2.2.3, `pd.DataFrame(rows, columns=['a','b'])`,
    /// reading column b:
    /// ```text
    ///   [[1, None], [2, 3]]           -> float64 [nan, 3.0]     None -> nan
    ///   [[1.0, None], [2.0, 3.0]]     -> float64 [nan, 3.0]
    ///   [["x", None], ["y", "z"]]     -> object  [None, 'z']    PRESERVED
    ///   [[True, None], [False, True]] -> object  [None, True]   PRESERVED
    ///   [[1, 4], [2, 3]]              -> int64   [4, 3]         no gap, no widening
    /// ```
    /// The last line is the control: the widening is caused by the gap, not by
    /// the constructor. The two object rows are the control that it is
    /// NUMERIC-only.
    /// br-frankenpandas-2a8yn: `DataFrame.value_counts()` defaults to
    /// `dropna=True`, and it drops a row if ANY subset column is missing.
    ///
    /// Measured, live pandas 2.2.3, on
    /// `DataFrame({'a':[1,1,2,None], 'b':[1,None,2,1]})`:
    /// ```text
    ///   df.value_counts()             -> {(1.0,1.0): 1, (2.0,2.0): 1}
    ///   df.value_counts(dropna=False) -> {(1.0,1.0): 1, (1.0,nan): 1,
    ///                                     (2.0,2.0): 1, (nan,1.0): 1}
    /// ```
    /// FrankenPandas counted every row — the `dropna=False` answer — so it
    /// returned four rows where pandas returns two. Note the dropped rows are
    /// PARTIALLY null: (1.0, nan) has a perfectly good `a`. It is the row that
    /// goes, not the cell.
    #[test]
    fn dataframe_value_counts_drops_any_row_with_a_missing_cell() {
        let frame = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Null(NullKind::NaN),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(2.0),
                        Scalar::Float64(1.0),
                    ],
                ),
            ],
        )
        .unwrap();

        let counts = frame.value_counts().unwrap();
        let labels: Vec<String> = counts
            .index()
            .labels()
            .iter()
            .map(std::string::ToString::to_string)
            .collect();
        assert_eq!(
            labels,
            vec!["1, 1".to_string(), "2, 2".to_string()],
            "rows carrying a missing cell must be dropped: {labels:?}"
        );
        assert_eq!(
            counts.values(),
            &[Scalar::Int64(1), Scalar::Int64(1)],
            "and the surviving counts are unchanged"
        );

        // Control: with no missing cell anywhere, every row is still counted —
        // the dropping is caused by the gap, not by value_counts.
        let dense = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                    ],
                ),
            ],
        )
        .unwrap();
        assert_eq!(
            dense.value_counts().unwrap().values(),
            &[Scalar::Int64(2), Scalar::Int64(1)]
        );
    }

    #[test]
    fn list_like_constructor_widens_a_numeric_column_around_a_supplied_null() {
        let build = |rows: Vec<Vec<Scalar>>| {
            DataFrame::from_list_like(
                rows,
                Some(&["a".to_owned(), "b".to_owned()]),
                Some(vec![0_i64.into(), 1_i64.into()]),
            )
            .unwrap()
        };

        let ints = build(vec![
            vec![Scalar::Int64(1), Scalar::Null(NullKind::Null)],
            vec![Scalar::Int64(2), Scalar::Int64(3)],
        ]);
        // The gap-free column is untouched...
        assert_eq!(
            ints.columns["a"].values(),
            &[Scalar::Int64(1), Scalar::Int64(2)]
        );
        // ...and the column holding the supplied None widens, marker and all.
        assert_eq!(ints.columns["b"].dtype(), DType::Float64);
        assert_eq!(
            ints.columns["b"].values(),
            &[Scalar::Null(NullKind::NaN), Scalar::Float64(3.0)]
        );

        // Control: no gap, no widening.
        let dense = build(vec![
            vec![Scalar::Int64(1), Scalar::Int64(4)],
            vec![Scalar::Int64(2), Scalar::Int64(3)],
        ]);
        assert_eq!(dense.columns["b"].dtype(), DType::Int64);

        // Control: an OBJECT column keeps the caller's None — pandas does, and
        // collapsing it would undo lufpu's null-kind identity.
        let text = build(vec![
            vec![Scalar::Utf8("x".into()), Scalar::Null(NullKind::Null)],
            vec![Scalar::Utf8("y".into()), Scalar::Utf8("z".into())],
        ]);
        assert_eq!(
            text.columns["b"].values(),
            &[Scalar::Null(NullKind::Null), Scalar::Utf8("z".into())]
        );
        let flags = build(vec![
            vec![Scalar::Bool(true), Scalar::Null(NullKind::Null)],
            vec![Scalar::Bool(false), Scalar::Bool(true)],
        ]);
        assert_eq!(
            flags.columns["b"].values(),
            &[Scalar::Null(NullKind::Null), Scalar::Bool(true)]
        );
    }

    #[test]
    fn dt_accessors_derive_the_missing_marker_from_the_result_dtype() {
        let dates = Series::from_values(
            "dates",
            (0..3_i64).map(IndexLabel::from).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("2024-03-15T14:30:00".into()),
                Scalar::Null(NullKind::Null),
                Scalar::Utf8("2024-07-04T00:00:00".into()),
            ],
        )
        .unwrap();
        let formatted = dates.dt().strftime("%Y/%m/%d %H:%M").unwrap();
        assert_eq!(
            formatted.values(),
            &[
                Scalar::Utf8("2024/03/15 14:30".into()),
                // NOT Null(Null): the input's None never lived in an object
                // column, it became NaT on the way into the datetime domain.
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("2024/07/04 00:00".into()),
            ]
        );

        let durations = Series::from_values(
            "durations",
            (0..3_i64).map(IndexLabel::from).collect::<Vec<_>>(),
            vec![
                Scalar::Timedelta64(fp_types::Timedelta::NANOS_PER_DAY),
                Scalar::Null(NullKind::Null),
                Scalar::Timedelta64(fp_types::Timedelta::NANOS_PER_HOUR + 1_800_000_000_000),
            ],
        )
        .unwrap();
        // total_seconds returns float64, and FrankenPandas spells a missing
        // float as a PRESENT-typed `Float64(NaN)` rather than `Null(NaN)` —
        // `Scalar::is_missing` treats `Float64(v) if v.is_nan()` as missing
        // (fp-types), so the two are the same value in FP's model. Assert the
        // semantics, not the spelling: missing, and float-kinded either way.
        let seconds = durations.dt().total_seconds().unwrap();
        assert_eq!(seconds.values()[0], Scalar::Float64(86400.0));
        assert_eq!(seconds.values()[2], Scalar::Float64(5400.0));
        assert!(seconds.values()[1].is_missing(), "the gap must be missing");
        assert!(
            seconds.values()[1].is_nan(),
            "and it must be the FLOAT gap, not a carried-over None: {:?}",
            seconds.values()[1]
        );
        assert!(
            !matches!(seconds.values()[1], Scalar::Null(NullKind::Null)),
            "a supplied None must not survive into a float64 result"
        );
    }

    #[test]
    fn dt_total_seconds_rejects_datetime() {
        // Per br-frankenpandas-i9bah: pandas datetime has no total_seconds().
        let s = Series::from_values(
            "d",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2024-01-15T00:00:00".to_string()),
                Scalar::Utf8("2024-01-15T01:30:00".to_string()),
            ],
        )
        .unwrap();
        let result = s.dt().total_seconds();
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.to_string().contains("total_seconds"));
    }

    #[test]
    fn timedelta_total_seconds_rejects_bare_numeric_series() {
        // br-frankenpandas-icqxw: `.dt` does not infer that bare numbers are
        // seconds. Callers must use `to_timedelta(..., unit="s")` first.
        let numeric = Series::from_values(
            "durations",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Int64(60),
                Scalar::Float64(3661.5),
                Scalar::Int64(86_400),
            ],
        )
        .unwrap();

        let error = super::timedelta_total_seconds(&numeric).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("Can only use .dt accessor with datetimelike values")
        );

        // The refusal is about a concrete numeric dtype; an empty Series keeps
        // the existing empty result behavior.
        let empty = Series::from_values("durations", Vec::new(), Vec::new()).unwrap();
        assert_eq!(super::timedelta_total_seconds(&empty).unwrap().len(), 0);
    }

