    // ── applymap_na_action ─────────────────────────────────────

    #[test]
    fn dataframe_applymap_na_action_skips_missing() {
        let df = DataFrame::from_dict(
            &["x"],
            vec![(
                "x",
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Null(NullKind::NaN),
                    Scalar::Float64(3.0),
                ],
            )],
        )
        .unwrap();

        let result = df
            .applymap_na_action(|v| {
                let f = v.to_f64().unwrap();
                Scalar::Float64(f * 10.0)
            })
            .unwrap();

        assert_eq!(result.columns["x"].values()[0], Scalar::Float64(10.0));
        assert!(result.columns["x"].values()[1].is_missing());
        assert_eq!(result.columns["x"].values()[2], Scalar::Float64(30.0));
    }

    #[test]
    fn dataframe_applymap_na_action_preserves_non_missing() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Int64(1), Scalar::Int64(2)]),
                ("b", vec![Scalar::Int64(10), Scalar::Int64(20)]),
            ],
        )
        .unwrap();

        let result = df
            .applymap_na_action(|v| {
                let f = v.to_f64().unwrap();
                Scalar::Float64(f + 100.0)
            })
            .unwrap();

        assert_eq!(result.columns["a"].values()[0], Scalar::Float64(101.0));
        assert_eq!(result.columns["b"].values()[1], Scalar::Float64(120.0));
    }

    // ── assign_fn ──────────────────────────────────────────────

    #[test]
    fn dataframe_assign_fn_computed_column() {
        let df = DataFrame::from_dict(
            &["x"],
            vec![(
                "x",
                vec![
                    Scalar::Float64(1.0),
                    Scalar::Float64(2.0),
                    Scalar::Float64(3.0),
                ],
            )],
        )
        .unwrap();

        let result = df
            .assign_fn(vec![(
                "x_doubled",
                Box::new(|df: &DataFrame| {
                    let x_col = &df.columns["x"];
                    let vals: Vec<Scalar> = x_col
                        .values()
                        .iter()
                        .map(|v| Scalar::Float64(v.to_f64().unwrap() * 2.0))
                        .collect();
                    Ok(Column::from_values(vals)?)
                }),
            )])
            .unwrap();

        assert_eq!(result.column_names().len(), 2);
        assert_eq!(
            result.columns["x_doubled"].values()[0],
            Scalar::Float64(2.0)
        );
        assert_eq!(
            result.columns["x_doubled"].values()[2],
            Scalar::Float64(6.0)
        );
    }

    #[test]
    fn dataframe_assign_fn_chained_sees_prior() {
        let df = DataFrame::from_dict(
            &["a"],
            vec![("a", vec![Scalar::Float64(10.0), Scalar::Float64(20.0)])],
        )
        .unwrap();

        let result = df
            .assign_fn(vec![
                (
                    "b",
                    Box::new(|df: &DataFrame| {
                        let vals: Vec<Scalar> = df.columns["a"]
                            .values()
                            .iter()
                            .map(|v| Scalar::Float64(v.to_f64().unwrap() + 1.0))
                            .collect();
                        Ok(Column::from_values(vals)?)
                    }) as Box<dyn Fn(&DataFrame) -> Result<Column, FrameError>>,
                ),
                (
                    "c",
                    Box::new(|df: &DataFrame| {
                        // c depends on b which was just assigned
                        let vals: Vec<Scalar> = df.columns["b"]
                            .values()
                            .iter()
                            .map(|v| Scalar::Float64(v.to_f64().unwrap() * 100.0))
                            .collect();
                        Ok(Column::from_values(vals)?)
                    }),
                ),
            ])
            .unwrap();

        assert_eq!(result.column_names().len(), 3);
        // a=[10,20], b=[11,21], c=[1100,2100]
        assert_eq!(result.columns["b"].values()[0], Scalar::Float64(11.0));
        assert_eq!(result.columns["c"].values()[0], Scalar::Float64(1100.0));
        assert_eq!(result.columns["c"].values()[1], Scalar::Float64(2100.0));
    }

    // ── corr/cov min_periods ───────────────────────────────────

    #[test]
    fn dataframe_corr_min_periods_sufficient() {
        let df = DataFrame::from_dict(
            &["x", "y"],
            vec![
                (
                    "x",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(3.0),
                    ],
                ),
                (
                    "y",
                    vec![
                        Scalar::Float64(2.0),
                        Scalar::Float64(4.0),
                        Scalar::Float64(6.0),
                    ],
                ),
            ],
        )
        .unwrap();

        // 3 observations, min_periods=3 → should produce valid result
        let result = df.corr_min_periods(3).unwrap();
        let corr_xy = result.columns["x"].values()[1].to_f64().unwrap();
        assert!((corr_xy - 1.0).abs() < 1e-10);
    }

    #[test]
    fn dataframe_corr_min_periods_insufficient() {
        let df = DataFrame::from_dict(
            &["x", "y"],
            vec![
                (
                    "x",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(3.0),
                    ],
                ),
                (
                    "y",
                    vec![
                        Scalar::Float64(2.0),
                        Scalar::Float64(4.0),
                        Scalar::Null(NullKind::NaN),
                    ],
                ),
            ],
        )
        .unwrap();

        // Only 1 valid pair (row 0), min_periods=3 → NaN
        let result = df.corr_min_periods(3).unwrap();
        let corr_xy = result.columns["x"].values()[1].to_f64().unwrap();
        assert!(corr_xy.is_nan());
    }

    #[test]
    fn dataframe_cov_min_periods_sufficient() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(3.0),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Float64(4.0),
                        Scalar::Float64(5.0),
                        Scalar::Float64(6.0),
                    ],
                ),
            ],
        )
        .unwrap();

        let result = df.cov_min_periods(2).unwrap();
        let cov_ab = result.columns["a"].values()[1].to_f64().unwrap();
        // cov(a,b) = 1.0 for perfectly correlated unit-spaced sequences
        assert!((cov_ab - 1.0).abs() < 1e-10);
    }

    #[test]
    fn dataframe_cov_min_periods_insufficient() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                ("a", vec![Scalar::Float64(1.0), Scalar::Float64(2.0)]),
                ("b", vec![Scalar::Float64(4.0), Scalar::Null(NullKind::NaN)]),
            ],
        )
        .unwrap();

        // Only 1 valid pair, min_periods=5 → NaN
        let result = df.cov_min_periods(5).unwrap();
        let cov_ab = result.columns["a"].values()[1].to_f64().unwrap();
        assert!(cov_ab.is_nan());
    }

    // ── Series.drop_duplicates_keep ────────────────────────────

    #[test]
    fn series_drop_duplicates_keep_first() {
        let s = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(3),
            ],
        )
        .unwrap();

        let result = s.drop_duplicates_keep(DuplicateKeep::First).unwrap();
        assert_eq!(result.len(), 3);
        assert_eq!(
            result.values(),
            &[Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)]
        );
    }

    #[test]
    fn series_drop_duplicates_keep_last() {
        let s = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(3),
            ],
        )
        .unwrap();

        let result = s.drop_duplicates_keep(DuplicateKeep::Last).unwrap();
        assert_eq!(result.len(), 3);
        // keeps index 1(=2), 2(=1), 3(=3)
        assert_eq!(
            result.values(),
            &[Scalar::Int64(2), Scalar::Int64(1), Scalar::Int64(3)]
        );
    }

    #[test]
    fn series_drop_duplicates_keep_none() {
        let s = Series::from_values(
            "a",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(3),
            ],
        )
        .unwrap();

        let result = s.drop_duplicates_keep(DuplicateKeep::None).unwrap();
        // 1 appears twice → dropped; 2 and 3 appear once → kept
        assert_eq!(result.len(), 2);
        assert_eq!(result.values(), &[Scalar::Int64(2), Scalar::Int64(3)]);
    }

