    #[test]
    fn test_series_groupby_ohlc_nt65g9() -> Result<(), FrameError> {
        let values = Series::from_values(
            "price",
            (0_i64..8).map(Into::into).collect(),
            vec![
                Scalar::Float64(10.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(15.0),
                Scalar::Float64(8.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(3.0),
                Scalar::Float64(1.0),
            ],
        )?;
        let groups = Series::from_values(
            "grp",
            (0_i64..8).map(Into::into).collect(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("c".into()),
                Scalar::Utf8("c".into()),
            ],
        )?;

        let ohlc = values.groupby(&groups)?.ohlc()?;
        assert_eq!(ohlc.column_names(), vec!["open", "high", "low", "close"]);
        assert_eq!(
            ohlc.index().labels(),
            &[
                IndexLabel::Utf8("a".into()),
                IndexLabel::Utf8("b".into()),
                IndexLabel::Utf8("c".into()),
            ]
        );
        assert_eq!(ohlc.columns()["open"].values()[0], Scalar::Float64(10.0));
        assert_eq!(ohlc.columns()["high"].values()[0], Scalar::Float64(15.0));
        assert_eq!(ohlc.columns()["low"].values()[0], Scalar::Float64(8.0));
        assert_eq!(ohlc.columns()["close"].values()[0], Scalar::Float64(8.0));
        assert!(
            ohlc.columns()["open"].values()[1]
                .to_f64()
                .expect("open should be numeric NaN")
                .is_nan()
        );
        assert!(
            ohlc.columns()["high"].values()[1]
                .to_f64()
                .expect("high should be numeric NaN")
                .is_nan()
        );
        assert!(
            ohlc.columns()["low"].values()[1]
                .to_f64()
                .expect("low should be numeric NaN")
                .is_nan()
        );
        assert!(
            ohlc.columns()["close"].values()[1]
                .to_f64()
                .expect("close should be numeric NaN")
                .is_nan()
        );
        assert_eq!(ohlc.columns()["open"].values()[2], Scalar::Float64(3.0));
        assert_eq!(ohlc.columns()["high"].values()[2], Scalar::Float64(3.0));
        assert_eq!(ohlc.columns()["low"].values()[2], Scalar::Float64(1.0));
        assert_eq!(ohlc.columns()["close"].values()[2], Scalar::Float64(1.0));

        Ok(())
    }

    #[test]
    fn test_series_groupby_ohlc_dense_typed_matches_fallback_1o6vv() -> Result<(), FrameError> {
        fn assert_matches_fallback(values: Column, keys: &[i64]) -> Result<(), FrameError> {
            let len = keys.len();
            let labels: Vec<IndexLabel> = (0..len as i64).map(IndexLabel::Int64).collect();
            let value_series = Series::new("price".to_owned(), Index::new(labels.clone()), values)?;
            let typed_keys = Series::new(
                "grp".to_owned(),
                Index::new(labels.clone()),
                Column::from_i64_values(keys.to_vec()),
            )?;
            let mut validity = fp_columnar::ValidityMask::all_valid(len);
            validity.set(len - 1, false);
            let fallback_keys = Series::new(
                "grp".to_owned(),
                Index::new(labels),
                Column::from_i64_values_with_validity(keys.to_vec(), validity),
            )?;

            let typed = value_series.groupby(&typed_keys)?.ohlc()?;
            let fallback = value_series.groupby(&fallback_keys)?.ohlc()?;
            assert_eq!(typed, fallback);
            for column_name in ["open", "high", "low", "close"] {
                let typed_values = typed
                    .column(column_name)
                    .expect("typed OHLC column should exist")
                    .values();
                let fallback_values = fallback
                    .column(column_name)
                    .expect("fallback OHLC column should exist")
                    .values();
                for (typed_value, fallback_value) in typed_values.iter().zip(fallback_values.iter())
                {
                    assert_eq!(
                        typed_value
                            .to_f64()
                            .expect("typed OHLC output should be numeric")
                            .to_bits(),
                        fallback_value
                            .to_f64()
                            .expect("fallback OHLC output should be numeric")
                            .to_bits(),
                    );
                }
            }
            Ok(())
        }

        let mut keys: Vec<i64> = (0..257)
            .map(|row| (((row * 73) ^ (row >> 2)) % 17) as i64 - 8)
            .collect();
        if let [.., previous, last] = keys.as_mut_slice() {
            *last = *previous;
        }

        let mut float_values: Vec<f64> = (0..257)
            .map(|row| match row {
                3 => -0.0,
                19 => f64::INFINITY,
                47 => f64::NEG_INFINITY,
                _ => (row as f64).mul_add(1.25, -90.0),
            })
            .collect();
        if let [.., previous, last] = float_values.as_mut_slice() {
            *last = *previous;
        }
        assert_matches_fallback(Column::from_f64_values(float_values), &keys)?;

        let mut int_values: Vec<i64> = (0..257)
            .map(|row| (row as i64).wrapping_mul(1_000_003) - 7_000_021)
            .collect();
        if let [.., previous, last] = int_values.as_mut_slice() {
            *last = *previous;
        }
        assert_matches_fallback(Column::from_i64_values(int_values), &keys)
    }

    #[test]
    fn test_series_groupby_transform_filter_and_pipe_nt65g1() -> Result<(), FrameError> {
        let values = Series::from_values(
            "data",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
                5_i64.into(),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(40.0),
            ],
        )?;
        let groups = Series::from_values(
            "grp",
            vec![
                0_i64.into(),
                1_i64.into(),
                2_i64.into(),
                3_i64.into(),
                4_i64.into(),
                5_i64.into(),
            ],
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )?;
        let gb = values.groupby(&groups)?;

        assert_eq!(
            gb.transform("mean")?.column().values(),
            &[
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
                Scalar::Float64(70.0 / 3.0),
                Scalar::Float64(70.0 / 3.0),
                Scalar::Float64(70.0 / 3.0),
            ]
        );
        assert_eq!(
            gb.transform("size")?.column().values(),
            &[
                Scalar::Int64(3),
                Scalar::Int64(3),
                Scalar::Int64(3),
                Scalar::Int64(3),
                Scalar::Int64(3),
                Scalar::Int64(3),
            ]
        );
        let unsupported_err = match gb.transform("definitely_not_supported") {
            Ok(series) => {
                return Err(FrameError::CompatibilityRejected(format!(
                    "unsupported transform unexpectedly returned {} rows",
                    series.len()
                )));
            }
            Err(err) => err,
        };
        assert!(
            unsupported_err
                .to_string()
                .contains("SeriesGroupBy.transform: unsupported function")
        );

        let filtered =
            gb.filter(|group| Ok(matches!(group.mean()?, Scalar::Float64(value) if value > 10.0)))?;
        assert_eq!(
            filtered.index().labels(),
            &[
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
                IndexLabel::Int64(5),
            ]
        );
        assert_eq!(
            filtered.column().values(),
            &[
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(40.0),
            ]
        );

        let empty = gb.filter(|_| Ok(false))?;
        assert_eq!(empty.len(), 0);
        assert_eq!(empty.dtype(), DType::Float64);

        let piped_sum = gb.pipe(|grouped| grouped.sum())?;
        assert_eq!(
            piped_sum.column().values(),
            &[Scalar::Float64(6.0), Scalar::Float64(70.0)]
        );

        Ok(())
    }

    #[test]
    fn test_series_groupby_apply_variants_dscmn() -> Result<(), FrameError> {
        let values = Series::from_values(
            "data",
            vec![
                IndexLabel::Utf8("r0".into()),
                IndexLabel::Utf8("r1".into()),
                IndexLabel::Utf8("r2".into()),
                IndexLabel::Utf8("r3".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ],
        )?;
        let groups = Series::from_values(
            "grp",
            vec![
                IndexLabel::Utf8("r0".into()),
                IndexLabel::Utf8("r1".into()),
                IndexLabel::Utf8("r2".into()),
                IndexLabel::Utf8("r3".into()),
            ],
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )?;
        let gb = values.groupby(&groups)?;

        let applied = gb.apply(|group| {
            let shifted = group
                .values()
                .iter()
                .map(|value| {
                    value
                        .to_f64()
                        .map(|number| Scalar::Float64(number + 1.0))
                        .unwrap_or(Scalar::Null(NullKind::NaN))
                })
                .collect();
            Series::from_values("shifted", group.index().labels().to_vec(), shifted)
        })?;
        assert_eq!(applied.name(), "data");
        assert_eq!(
            applied.index().labels(),
            &[
                IndexLabel::Utf8("a, r0".into()),
                IndexLabel::Utf8("a, r1".into()),
                IndexLabel::Utf8("b, r2".into()),
                IndexLabel::Utf8("b, r3".into()),
            ]
        );
        assert_eq!(
            applied.values(),
            &[
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(11.0),
                Scalar::Float64(21.0),
            ]
        );

        let scalar = gb.apply_scalar("total", |group| {
            Ok(Scalar::Float64(
                group
                    .values()
                    .iter()
                    .filter_map(|value| value.to_f64().ok())
                    .sum(),
            ))
        })?;
        assert_eq!(scalar.name(), "total");
        assert_eq!(
            scalar.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("b".into())]
        );
        assert_eq!(
            scalar.values(),
            &[Scalar::Float64(3.0), Scalar::Float64(30.0)]
        );

        let empty = gb.apply(|_| {
            Series::from_values("empty", Vec::<IndexLabel>::new(), Vec::<Scalar>::new())
        })?;
        assert!(empty.is_empty());
        assert_eq!(empty.dtype(), DType::Float64);

        Ok(())
    }

    #[test]
    fn test_series_groupby_rolling_reductions_qfabo() -> Result<(), FrameError> {
        let values = Series::from_values(
            "data",
            vec![
                IndexLabel::Int64(10),
                IndexLabel::Int64(11),
                IndexLabel::Int64(12),
                IndexLabel::Int64(13),
                IndexLabel::Int64(14),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
            ],
        )?;
        let groups = Series::from_values(
            "grp",
            vec![
                IndexLabel::Int64(10),
                IndexLabel::Int64(11),
                IndexLabel::Int64(12),
                IndexLabel::Int64(13),
                IndexLabel::Int64(14),
            ],
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )?;
        let grouped = values.groupby(&groups)?;
        let rolling = grouped.rolling(2);

        let sums = rolling.sum()?;
        assert_eq!(sums.index().labels(), values.index().labels());
        assert!(matches!(
            sums.values(),
            [
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(a),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(b),
                Scalar::Float64(c),
            ] if (*a - 3.0).abs() < 1e-12
                && (*b - 30.0).abs() < 1e-12
                && (*c - 50.0).abs() < 1e-12
        ));

        let means = rolling.mean()?;
        assert!(matches!(
            means.values(),
            [
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(a),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(b),
                Scalar::Float64(c),
            ] if (*a - 1.5).abs() < 1e-12
                && (*b - 15.0).abs() < 1e-12
                && (*c - 25.0).abs() < 1e-12
        ));

        let counts = rolling.count()?;
        assert_eq!(
            counts.values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
            ]
        );

        Ok(())
    }

