    #[test]
    fn test_series_groupby_ewm_reductions_fz20b() -> Result<(), FrameError> {
        let values = Series::from_values(
            "data",
            vec![
                IndexLabel::Int64(10),
                IndexLabel::Int64(11),
                IndexLabel::Int64(12),
                IndexLabel::Int64(13),
                IndexLabel::Int64(14),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
            ],
        )?;
        let groups = Series::from_values(
            "grp",
            vec![
                IndexLabel::Int64(10),
                IndexLabel::Int64(11),
                IndexLabel::Int64(12),
                IndexLabel::Int64(13),
                IndexLabel::Int64(14),
            ],
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
            ],
        )?;
        let grouped = values.groupby(&groups)?;
        let ewm = grouped.ewm(None, Some(0.5));

        let means = ewm.mean()?;
        assert_eq!(means.index().labels(), values.index().labels());
        assert!(matches!(
            means.values(),
            [
                Scalar::Float64(a),
                Scalar::Float64(b),
                Scalar::Float64(c),
                Scalar::Float64(d),
                Scalar::Float64(e),
            // pandas DEFAULT adjust=True per group: a=[1,2]->[1, 5/3];
            // b=[10,20,30]->[10, 50/3, 170/7] (verified vs pandas 2.2.3).
            ] if (*a - 1.0).abs() < 1e-12
                && (*b - 5.0 / 3.0).abs() < 1e-12
                && (*c - 10.0).abs() < 1e-12
                && (*d - 50.0 / 3.0).abs() < 1e-12
                && (*e - 170.0 / 7.0).abs() < 1e-12
        ));

        let sums = ewm.sum()?;
        assert!(matches!(
            sums.values(),
            [
                Scalar::Float64(a),
                Scalar::Float64(b),
                Scalar::Float64(c),
                Scalar::Float64(d),
                Scalar::Float64(e),
            ] if (*a - 1.0).abs() < 1e-12
                && (*b - 2.5).abs() < 1e-12
                && (*c - 10.0).abs() < 1e-12
                && (*d - 25.0).abs() < 1e-12
                && (*e - 42.5).abs() < 1e-12
        ));

        Ok(())
    }

    #[test]
    fn test_series_groupby_resample_reductions_meqrr() -> Result<(), FrameError> {
        let values = Series::from_values(
            "sales",
            vec![
                IndexLabel::Utf8("2024-01-05".into()),
                IndexLabel::Utf8("2024-01-20".into()),
                IndexLabel::Utf8("2024-01-07".into()),
                IndexLabel::Utf8("2024-02-03".into()),
                IndexLabel::Utf8("2024-02-08".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
            ],
        )?;
        let groups = Series::from_values(
            "store",
            vec![
                IndexLabel::Utf8("2024-01-05".into()),
                IndexLabel::Utf8("2024-01-20".into()),
                IndexLabel::Utf8("2024-01-07".into()),
                IndexLabel::Utf8("2024-02-03".into()),
                IndexLabel::Utf8("2024-02-08".into()),
            ],
            vec![
                Scalar::Utf8("east".into()),
                Scalar::Utf8("east".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("east".into()),
            ],
        )?;
        let grouped = values.groupby(&groups)?;
        let resample = grouped.resample("M");

        let sums = resample.sum()?;
        assert_eq!(
            sums.index().labels(),
            &[
                IndexLabel::Utf8("east, 2024-01-31".into()),
                IndexLabel::Utf8("east, 2024-02-29".into()),
                IndexLabel::Utf8("west, 2024-01-31".into()),
                IndexLabel::Utf8("west, 2024-02-29".into()),
            ]
        );
        assert_eq!(
            sums.values(),
            &[
                Scalar::Float64(3.0),
                Scalar::Float64(30.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ]
        );

        let means = resample.mean()?;
        assert_eq!(
            means.values(),
            &[
                Scalar::Float64(1.5),
                Scalar::Float64(30.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ]
        );

        let counts = resample.count()?;
        assert_eq!(
            counts.values(),
            &[
                Scalar::Int64(2),
                Scalar::Int64(1),
                Scalar::Int64(1),
                Scalar::Int64(1),
            ]
        );

        let first = resample.first()?;
        assert_eq!(
            first.values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Float64(30.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ]
        );

        let last = resample.last()?;
        assert_eq!(
            last.values(),
            &[
                Scalar::Float64(2.0),
                Scalar::Float64(30.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ]
        );

        Ok(())
    }

    #[test]
    fn test_series_groupby_describe_summary_wwcl4() -> Result<(), FrameError> {
        let values = Series::from_values(
            "sales",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(30.0),
            ],
        )?;
        let groups = Series::from_values(
            "store",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
            ],
            vec![
                Scalar::Utf8("east".into()),
                Scalar::Utf8("east".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("east".into()),
            ],
        )?;

        let desc = values.groupby(&groups)?.describe()?;

        assert_eq!(
            desc.index().labels(),
            &[
                IndexLabel::Utf8("east".into()),
                IndexLabel::Utf8("west".into()),
            ]
        );
        assert_eq!(
            desc.column_order,
            vec!["count", "mean", "std", "min", "25%", "50%", "75%", "max"]
        );
        assert_eq!(
            desc.columns["count"].values(),
            &[Scalar::Float64(3.0), Scalar::Float64(1.0)]
        );
        assert_eq!(
            desc.columns["mean"].values(),
            &[Scalar::Float64(11.0), Scalar::Float64(10.0)]
        );
        assert!(matches!(
            desc.columns["std"].values(),
            [Scalar::Float64(east), Scalar::Float64(west)]
                if (*east - 271.0_f64.sqrt()).abs() < 1e-12 && west.is_nan()
        ));
        assert_eq!(
            desc.columns["min"].values(),
            &[Scalar::Float64(1.0), Scalar::Float64(10.0)]
        );
        assert_eq!(
            desc.columns["25%"].values(),
            &[Scalar::Float64(1.5), Scalar::Float64(10.0)]
        );
        assert_eq!(
            desc.columns["50%"].values(),
            &[Scalar::Float64(2.0), Scalar::Float64(10.0)]
        );
        assert_eq!(
            desc.columns["75%"].values(),
            &[Scalar::Float64(16.0), Scalar::Float64(10.0)]
        );
        assert_eq!(
            desc.columns["max"].values(),
            &[Scalar::Float64(30.0), Scalar::Float64(10.0)]
        );

        Ok(())
    }

    #[test]
    fn test_series_groupby_pairwise_corr_cov_904tg() -> Result<(), FrameError> {
        let values = Series::from_values(
            "x",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
                IndexLabel::Int64(5),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
                Scalar::Float64(99.0),
            ],
        )?;
        let other = Series::from_values(
            "y",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
                IndexLabel::Int64(5),
            ],
            vec![
                Scalar::Float64(2.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
                Scalar::Float64(9.0),
                Scalar::Float64(15.0),
                Scalar::Float64(1.0),
            ],
        )?;
        let groups = Series::from_values(
            "store",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
                IndexLabel::Int64(4),
                IndexLabel::Int64(5),
            ],
            vec![
                Scalar::Utf8("east".into()),
                Scalar::Utf8("east".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("west".into()),
                Scalar::Utf8("east".into()),
                Scalar::Utf8("solo".into()),
            ],
        )?;
        let grouped = values.groupby(&groups)?;

        let cov = grouped.cov(&other)?;
        assert_eq!(
            cov.index().labels(),
            &[
                IndexLabel::Utf8("east".into()),
                IndexLabel::Utf8("west".into()),
                IndexLabel::Utf8("solo".into()),
            ]
        );
        assert!(matches!(
            cov.values(),
            [Scalar::Float64(east), Scalar::Float64(west), Scalar::Float64(solo)]
                if (*east - 114.5).abs() < 1e-12
                    && (*west - 20.0).abs() < 1e-12
                    && solo.is_nan()
        ));

        let corr = grouped.corr(&other)?;
        let expected_east = 114.5 / (7.0 * 271.0_f64.sqrt());
        assert!(matches!(
            corr.values(),
            [Scalar::Float64(east), Scalar::Float64(west), Scalar::Float64(solo)]
                if (*east - expected_east).abs() < 1e-12
                    && (*west - 1.0).abs() < 1e-12
                    && solo.is_nan()
        ));

        Ok(())
    }

