    #[test]
    fn dt_isocalendar_53_week_years() {
        // br-frankenpandas-isocal53: the previous string path hardcoded the
        // year-boundary clamp to 52/1, so early-January dates that belong to ISO
        // week 53 of the prior year, and Dec-31 dates in a 53-week year, were
        // wrong. These are the pandas dt.isocalendar() values (verified against
        // pandas 2.2.3): (iso_year, iso_week, iso_day, day 1=Mon..7=Sun).
        let cases = [
            ("2021-01-01", 2020, 53, 5), // Fri, ISO 2020-W53 (2020 has 53 weeks)
            ("2020-12-31", 2020, 53, 4), // Thu, still 2020-W53
            ("2016-01-01", 2015, 53, 5), // Fri, ISO 2015-W53
            ("2026-12-31", 2026, 53, 4), // Thu, 2026-W53
            ("2023-01-01", 2022, 52, 7), // Sun, ISO 2022-W52 (2022 has 52 weeks)
            ("2024-01-01", 2024, 1, 1),  // Mon, ISO 2024-W1 (unchanged)
        ];
        for (date, iso_y, iso_w, iso_d) in cases {
            let s = Series::from_values("ts", vec![0_i64.into()], vec![Scalar::Utf8(date.into())])
                .unwrap();
            let ic = s.dt().isocalendar().unwrap();
            assert_eq!(
                ic.get_column("year").column().values()[0],
                Scalar::Int64(iso_y),
                "{date} iso year"
            );
            assert_eq!(
                ic.get_column("week").column().values()[0],
                Scalar::Int64(iso_w),
                "{date} iso week"
            );
            assert_eq!(
                ic.get_column("day").column().values()[0],
                Scalar::Int64(iso_d),
                "{date} iso day"
            );
            // weekofyear() must agree with isocalendar().week.
            assert_eq!(
                s.dt().weekofyear().unwrap().values()[0],
                Scalar::Int64(iso_w),
                "{date} weekofyear"
            );
        }

        // Typed Datetime64 path: 2021-01-01 00:00:00 UTC and 2020-12-31 (one day
        // earlier) must produce the same 53-week-correct tuples as the strings.
        const NS: i64 = 1_000_000_000;
        let ts_2021_01_01 = 1_609_459_200 * NS;
        let ts_2020_12_31 = ts_2021_01_01 - 86_400 * NS;
        let s = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Datetime64(ts_2021_01_01),
                Scalar::Datetime64(ts_2020_12_31),
            ],
        )
        .unwrap();
        assert_eq!(s.dtype(), DType::Datetime64);
        let ic = s.dt().isocalendar().unwrap();
        assert_eq!(
            ic.get_column("year").column().values()[0],
            Scalar::Int64(2020)
        );
        assert_eq!(
            ic.get_column("week").column().values()[0],
            Scalar::Int64(53)
        );
        assert_eq!(ic.get_column("day").column().values()[0], Scalar::Int64(5));
        assert_eq!(
            ic.get_column("year").column().values()[1],
            Scalar::Int64(2020)
        );
        assert_eq!(
            ic.get_column("week").column().values()[1],
            Scalar::Int64(53)
        );
        assert_eq!(ic.get_column("day").column().values()[1], Scalar::Int64(4));
    }

    #[test]
    fn test_dt_tz() {
        // CORRECTED (br-frankenpandas-hzayc). The first element is `T`-separated
        // and the rest are space-separated, which is a DIFFERENT format, so
        // pandas keeps only the first. Measured, live pandas 2.2.3, on exactly
        // these four values:
        //   pd.to_datetime([...], errors='coerce')
        //     -> dtype datetime64[ns, UTC]
        //        ['2023-01-15 14:35:22+00:00', NaT, NaT, NaT]
        // The offset SPELLINGS (Z / +05:30 / -08:00) are still covered by the
        // uniform column below — they are one `%z` token and parse together.
        let mixed = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Utf8("2023-01-15T14:35:22Z".to_string()),
                Scalar::Utf8("2023-06-30 23:59:59+05:30".to_string()),
                Scalar::Utf8("2023-12-01 08:00:00-08:00".to_string()),
                Scalar::Utf8("2023-03-15 12:00:00".to_string()),
            ],
        )
        .unwrap();
        let result = mixed.dt().tz().unwrap();
        assert_eq!(result.column().values()[0], Scalar::Utf8("UTC".to_string()));
        assert!(result.column().values()[1].is_missing());
        assert!(result.column().values()[2].is_missing());
        assert!(result.column().values()[3].is_missing());

        let s = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2023-01-15 14:35:22Z".to_string()),
                Scalar::Utf8("2023-06-30 23:59:59+05:30".to_string()),
                Scalar::Utf8("2023-12-01 08:00:00-08:00".to_string()),
            ],
        )
        .unwrap();
        let result = s.dt().tz().unwrap();
        assert_eq!(result.column().values()[0], Scalar::Utf8("UTC".to_string()));
        assert_eq!(
            result.column().values()[1],
            Scalar::Utf8("+05:30".to_string())
        );
        assert_eq!(
            result.column().values()[2],
            Scalar::Utf8("-08:00".to_string())
        );
    }

    /// `.dt.timetz` across EVERY offset spelling, not one.
    ///
    /// br-frankenpandas-t2n6i. The tz family's only banked fixture
    /// (fp_p2d_240_series_dt_timetz_keeps_offset_strict) carries a single `+05:30`
    /// case, and it AGREES with pandas — I replayed its own payload through the
    /// oracle against live 2.2.3 and got its banked value back. It still could not
    /// see the defect, because the only spelling that diverged was Zulu. That is the
    /// one-sign-census failure: a positive fixed offset passes against a bug that
    /// only fires on `Z`.
    ///
    /// MEASURED, live pandas 2.2.3 (CrimsonPine 2026-08-18),
    /// `pd.to_datetime(pd.Series([...])).dt.timetz` rendered with `str()`:
    /// ```text
    ///   '2024-01-15 10:30:00'        -> '10:30:00'          naive, no suffix
    ///   '2024-01-15 10:30:00+05:30'  -> '10:30:00+05:30'    positive offset
    ///   '2024-01-15 10:30:00-05:00'  -> '10:30:00-05:00'    NEGATIVE offset
    ///   '2024-01-15T10:30:00Z'       -> '10:30:00+00:00'    Zulu becomes +00:00
    /// ```
    /// Each case is built as its OWN single-element series on purpose: `.dt` takes
    /// pandas' one-format lock, so mixing these spellings in one column would NaT
    /// every element after the first and the test would assert nothing about them.
    #[test]
    fn dt_timetz_renders_every_offset_spelling_like_pandas_t2n6i() {
        let one = |value: &str| {
            Series::from_values(
                "ts",
                vec![0_i64.into()],
                vec![Scalar::Utf8(value.to_string())],
            )
            .unwrap()
            .dt()
            .timetz()
            .unwrap()
            .column()
            .values()[0]
                .clone()
        };

        assert_eq!(one("2024-01-15 10:30:00"), Scalar::Utf8("10:30:00".into()));
        assert_eq!(
            one("2024-01-15 10:30:00+05:30"),
            Scalar::Utf8("10:30:00+05:30".into())
        );
        // ⚠️ The negative case is not symmetric plumbing: timetz slices the suffix off
        // after splitting on '-', which is also the DATE separator, so a sign error
        // here would surface only on this row.
        assert_eq!(
            one("2024-01-15 10:30:00-05:00"),
            Scalar::Utf8("10:30:00-05:00".into())
        );
        // ⚠️ THE ROW THAT WAS WRONG: the source spelling 'Z' must not survive.
        assert_eq!(
            one("2024-01-15T10:30:00Z"),
            Scalar::Utf8("10:30:00+00:00".into())
        );
        // ⚠️ LOWERCASE 'z' IS A DIFFERENT ANSWER, NOT THE SAME ONE CASE-FOLDED.
        // pandas consumes it and yields a NAIVE timestamp, so the time renders with
        // NO offset. The previous revision of this test could not assert this row:
        // FrankenPandas left the letter attached to the time, `parse_time` failed and
        // the element came back Null — a missing value where pandas has a time.
        assert_eq!(one("2024-01-15T10:30:00z"), Scalar::Utf8("10:30:00".into()));
        // space separator reaches the same suffix logic
        assert_eq!(one("2024-01-15 10:30:00z"), Scalar::Utf8("10:30:00".into()));
    }

    #[test]
    fn test_dt_timetz() {
        // CORRECTED with test_dt_tz (br-frankenpandas-hzayc): `T`-separated
        // first element, space-separated rest, so only the first survives.
        // Measured: pd.to_datetime([...], errors='coerce') ->
        //   ['2023-01-15 14:35:22+00:00', NaT, NaT]  dtype datetime64[ns, UTC]
        let mixed = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Utf8("2023-01-15T14:35:22Z".to_string()),
                Scalar::Utf8("2023-06-30 23:59:59+05:30".to_string()),
                Scalar::Utf8("2023-12-01 08:00:00".to_string()),
            ],
        )
        .unwrap();
        let result = mixed.dt().timetz().unwrap();
        // ⚠️ '+00:00', NOT 'Z' (br-frankenpandas-t2n6i). This pinned the raw source
        // spelling; pandas renders the tzinfo, and a parsed 'Z' is a fixed UTC
        // offset. MEASURED live 2.2.3: to_datetime('...T10:30:00Z').dt.timetz
        // is '10:30:00+00:00'.
        assert_eq!(
            result.column().values()[0],
            Scalar::Utf8("14:35:22+00:00".to_string())
        );
        assert!(result.column().values()[1].is_missing());
        assert!(result.column().values()[2].is_missing());

        let s = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2023-01-15 14:35:22Z".to_string()),
                Scalar::Utf8("2023-06-30 23:59:59+05:30".to_string()),
            ],
        )
        .unwrap();
        let result = s.dt().timetz().unwrap();
        assert_eq!(
            result.column().values()[0],
            Scalar::Utf8("14:35:22+00:00".to_string())
        );
        assert_eq!(
            result.column().values()[1],
            Scalar::Utf8("23:59:59+05:30".to_string())
        );

        // pandas applies the same zero-fraction rendering before retaining
        // timetz's suffix: `23:59:59.000000+05:30` -> `23:59:59+05:30`.
        let zero_fraction = Series::from_values(
            "ts",
            vec![0_i64.into(), 1_i64.into()],
            vec![
                Scalar::Utf8("2023-06-30 23:59:59.000000+05:30".to_string()),
                Scalar::Utf8("2023-12-01 08:00:00.123456+05:30".to_string()),
            ],
        )
        .unwrap();
        let result = zero_fraction.dt().timetz().unwrap();
        assert_eq!(
            result.column().values()[0],
            Scalar::Utf8("23:59:59+05:30".to_string())
        );
        assert_eq!(
            result.column().values()[1],
            Scalar::Utf8("08:00:00.123456+05:30".to_string())
        );
    }

