    #[test]
    fn test_nlargest_nsmallest_f64_with_nan_matches_sort_head_ferm3() {
        // Parity lock for the Float64 top-k skip-NaN fast path: a Float64
        // ordering column WITH interior NaN must return the SAME rows as the
        // prior generic fallback `sort_values(col, ascending).head(n)` (which is
        // what df.nlargest/nsmallest ran before the fast path learned to skip
        // NaN). Enough non-missing values (26) exist that the fast path is the
        // one exercised for these takes; NaN keys must be excluded from the
        // result (br-frankenpandas-ovpm9) and ties broken by input position
        // (metamorphic br-frankenpandas-4v2lh: nsmallest(k)==sort_values(asc).head(k)).
        let rows = 30usize;
        let mut a: Vec<Scalar> = Vec::with_capacity(rows);
        let mut b: Vec<Scalar> = Vec::with_capacity(rows);
        for i in 0..rows {
            if i % 7 == 3 {
                a.push(Scalar::Float64(f64::NAN));
            } else {
                // non-monotonic, with a deliberate tie (two rows share 25.0)
                a.push(Scalar::Float64(((i * 37 + 11) % 100) as f64 * 0.5));
            }
            b.push(Scalar::Int64(i as i64));
        }
        let df = DataFrame::from_dict(&["a", "b"], vec![("a", a), ("b", b)]).unwrap();

        for &take in &[1usize, 5, 10] {
            let fast = df.nlargest(take, "a").unwrap();
            let reference = df
                .sort_values("a", false)
                .unwrap()
                .head(take as i64)
                .unwrap();
            assert_eq!(
                fast.columns["b"].values(),
                reference.columns["b"].values(),
                "nlargest({take}) rows must match sort_values(desc).head"
            );
            assert_eq!(fast.columns["a"].values(), reference.columns["a"].values());

            let fast_s = df.nsmallest(take, "a").unwrap();
            let reference_s = df
                .sort_values("a", true)
                .unwrap()
                .head(take as i64)
                .unwrap();
            assert_eq!(
                fast_s.columns["b"].values(),
                reference_s.columns["b"].values(),
                "nsmallest({take}) rows must match sort_values(asc).head"
            );
            assert_eq!(
                fast_s.columns["a"].values(),
                reference_s.columns["a"].values()
            );
        }
    }

    #[test]
    fn test_rolling_agg_multi() {
        let s = Series::from_values(
            "data",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into(), 3_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();
        let result = s
            .rolling(2, None)
            .agg(&["sum", "mean", "first", "last", "prod"])
            .unwrap();
        let col_names: Vec<String> = result.column_names().into_iter().cloned().collect();
        assert!(col_names.contains(&"sum".to_string()));
        assert!(col_names.contains(&"mean".to_string()));
        assert!(col_names.contains(&"first".to_string()));
        assert!(col_names.contains(&"last".to_string()));
        assert!(col_names.contains(&"prod".to_string()));
        assert_eq!(result.len(), 4); // same length as input
        assert_eq!(
            result.columns["first"].values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ]
        );
        assert_eq!(
            result.columns["last"].values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ]
        );
        assert_eq!(
            result.columns["prod"].values(),
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Float64(6.0),
                Scalar::Float64(12.0),
            ]
        );
    }

