        assert!(vals[0].is_missing());
        assert_eq!(vals[1], Scalar::Float64(3.0));
        assert_eq!(vals[2], Scalar::Float64(5.0));
        assert!(vals[3].is_missing());
        assert_eq!(vals[4], Scalar::Float64(30.0));
