    #[test]
    fn groupby_rolling_min_max_count_use_group_local_windows() {
        let df = DataFrame::from_dict(
            &["grp", "val"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                    ],
                ),
                (
                    "val",
                    vec![
                        Scalar::Float64(5.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(7.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(6.0),
                        Scalar::Float64(4.0),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        let mins = gb.rolling(2).min().unwrap();
        assert_eq!(mins.column_names(), vec!["grp", "val"]);
        // ⚠️ GROUP ORDER (br-frankenpandas-nyjxf): group a is source rows
        // 0,2,4,6 and group b is 1,3,5, so the labels follow the rows.
        assert_int64_index_labels(mins.index(), &[0, 2, 4, 6, 1, 3, 5]);
        assert_eq!(
            mins.column("grp").unwrap().values(),
            // The key column is gathered through the SAME permutation as the
            // values, so it reads a,a,a,a,b,b,b — pairing group-ordered values
            // with source-ordered keys would be worse than either order alone.
            &[
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("b".to_string()),
                Scalar::Utf8("b".to_string()),
                Scalar::Utf8("b".to_string()),
            ]
        );
        let min_vals = mins.column("val").unwrap().values();
        // ⚠️ GROUP ORDER, NOT SOURCE ORDER (br-frankenpandas-nyjxf): the rows are
        // group a (source 0,2,4,6) then group b (source 1,3,5). MEASURED, live
        // pandas 2.2.3, `df.groupby('grp').rolling(2)` on this frame:
        //
        //     index   a0    a2   a4   a6      b1    b3   b5
        //     min    NaN   1.0  NaN  NaN     NaN   2.0  6.0
        //     max    NaN   5.0  NaN  NaN     NaN   7.0  7.0
        //     count  NaN   2.0  1.0  1.0     NaN   2.0  2.0
        //
        // A NaN inside a full window makes min/max NaN at the default
        // min_periods, and the FIRST row of each group has an incomplete window.
        assert!(min_vals[0].is_missing());
        assert_eq!(min_vals[1], Scalar::Float64(1.0));
        assert!(min_vals[2].is_missing());
        assert!(min_vals[3].is_missing());
        assert!(min_vals[4].is_missing());
        assert_eq!(min_vals[5], Scalar::Float64(2.0));
        assert_eq!(min_vals[6], Scalar::Float64(6.0));

        let maxs = gb.rolling(2).max().unwrap();
        let max_vals = maxs.column("val").unwrap().values();
        assert!(max_vals[0].is_missing());
        assert_eq!(max_vals[1], Scalar::Float64(5.0));
        assert!(max_vals[2].is_missing());
        assert!(max_vals[3].is_missing());
        assert!(max_vals[4].is_missing());
        assert_eq!(max_vals[5], Scalar::Float64(7.0));
        assert_eq!(max_vals[6], Scalar::Float64(7.0));

        let counts = gb.rolling(2).count().unwrap();
        let count_vals = counts.column("val").unwrap().values();
        assert!(count_vals[0].is_missing());
        assert_eq!(count_vals[1], Scalar::Float64(2.0));
        assert_eq!(count_vals[2], Scalar::Float64(1.0));
        assert_eq!(count_vals[3], Scalar::Float64(1.0));
        assert!(count_vals[4].is_missing());
        assert_eq!(count_vals[5], Scalar::Float64(2.0));
        assert_eq!(count_vals[6], Scalar::Float64(2.0));
    }

    #[test]
    fn groupby_rolling_min_max_count_int64_input_widens_to_float() {
        // x5oy covers the Float64 baseline; 4hkt complements with Int64
        // input to lock the dtype-coercion path on grouped rolling
        // min/max/count. Pandas widens Int64 -> Float64 on rolling
        // aggregations (matching Series.rolling() dtype semantics)
        // because NaN must be representable alongside partial-window
        // results. Verifies fp-frame follows the same rule.
        let df = DataFrame::from_dict(
            &["grp", "v"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Int64(10),
                        Scalar::Int64(7),
                        Scalar::Int64(4),
                        Scalar::Int64(2),
                        Scalar::Int64(8),
                        Scalar::Int64(5),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        let mins = gb.rolling(2).min().unwrap();
        assert_eq!(mins.column_names(), vec!["grp", "v"]);
        // ⚠️ GROUP ORDER: group a is source rows 0,2,4 and group b is 1,3,5.
        assert_int64_index_labels(mins.index(), &[0, 2, 4, 1, 3, 5]);
        let min_vals = mins.column("v").unwrap().values();
        assert_eq!(mins.column("v").unwrap().dtype(), DType::Float64);
        // MEASURED, live pandas 2.2.3, groupby('grp').rolling(2) on this frame:
        //     min  a0 NaN  a2 4.0  a4 4.0   b1 NaN  b3 2.0  b5 2.0
        //     max  a0 NaN  a2 10.0 a4 8.0   b1 NaN  b3 7.0  b5 5.0
        assert!(min_vals[0].is_missing());
        assert_eq!(min_vals[1], Scalar::Float64(4.0));
        assert_eq!(min_vals[2], Scalar::Float64(4.0));
        assert!(min_vals[3].is_missing());
        assert_eq!(min_vals[4], Scalar::Float64(2.0));
        assert_eq!(min_vals[5], Scalar::Float64(2.0));

        let maxs = gb.rolling(2).max().unwrap();
        let max_vals = maxs.column("v").unwrap().values();
        assert_eq!(maxs.column("v").unwrap().dtype(), DType::Float64);
        assert!(max_vals[0].is_missing());
        assert_eq!(max_vals[1], Scalar::Float64(10.0));
        assert_eq!(max_vals[2], Scalar::Float64(8.0));
        assert!(max_vals[3].is_missing());
        assert_eq!(max_vals[4], Scalar::Float64(7.0));
        assert_eq!(max_vals[5], Scalar::Float64(5.0));

        let counts = gb.rolling(2).count().unwrap();
        assert_eq!(counts.column("v").unwrap().dtype(), DType::Float64);
        assert_eq!(
            counts.column("v").unwrap().values(),
            // pandas: count is NaN for the FIRST row of each group (incomplete
            // window) and 2.0 thereafter -> [NaN, 2, 2, NaN, 2, 2] in group order.
            &[
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Float64(2.0),
            ]
        );
    }

    #[test]
    fn groupby_rolling_window_one_emits_per_row_identity() {
        // Window=1 is degenerate: every row's window is the row itself.
        // min == max == original value for non-null rows; count follows pandas
        // and emits 0 for a full window containing only a missing value.
        let df = DataFrame::from_dict(
            &["grp", "v"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Float64(3.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(7.0),
                        Scalar::Float64(9.0),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        let mins = gb.rolling(1).min().unwrap();
        let maxs = gb.rolling(1).max().unwrap();
        let counts = gb.rolling(1).count().unwrap();

        let min_vals = mins.column("v").unwrap().values();
        let max_vals = maxs.column("v").unwrap().values();
        let count_vals = counts.column("v").unwrap().values();

        assert_eq!(min_vals[0], Scalar::Float64(3.0));
        assert_eq!(max_vals[0], Scalar::Float64(3.0));
        // ⚠️ ROWS ARE IN GROUP ORDER, NOT SOURCE ORDER (br-frankenpandas-nyjxf).
        // This test previously read the source-ordered scatter, so index 1 was
        // b's NaN. MEASURED, live pandas 2.2.3, on the same frame:
        //
        //     df.groupby('grp').rolling(1).min()
        //       a  0  3.0        max: same        count: 1.0
        //          2  7.0                                1.0
        //       b  1  NaN                                0.0
        //          3  9.0                                1.0
        //
        // so index 1 is now a's second row (7.0) and the NaN has moved to
        // index 2. The VALUES are unchanged; only their order is.
        assert_eq!(min_vals[1], Scalar::Float64(7.0));
        assert_eq!(max_vals[1], Scalar::Float64(7.0));
        assert!(min_vals[2].is_missing());
        assert!(max_vals[2].is_missing());
        assert_eq!(min_vals[3], Scalar::Float64(9.0));
        assert_eq!(max_vals[3], Scalar::Float64(9.0));

        assert_eq!(count_vals[0], Scalar::Float64(1.0));
        assert_eq!(count_vals[1], Scalar::Float64(1.0));
        assert_eq!(count_vals[2], Scalar::Float64(0.0));
        assert_eq!(count_vals[3], Scalar::Float64(1.0));
    }

    #[test]
    fn groupby_rolling_std_var_respect_group_boundaries_and_missing_windows() {
        let df = DataFrame::from_dict(
            &["grp", "val"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                    ],
                ),
                (
                    "val",
                    vec![
                        Scalar::Float64(2.0),
                        Scalar::Float64(1.0),
                        Scalar::Float64(4.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(6.0),
                        Scalar::Float64(3.0),
                        Scalar::Null(NullKind::NaN),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        // GROUP ORDER, not source order — br-frankenpandas-nyjxf (0daee4272) made
        // grouped rolling visit groups in sorted key order to match pandas, and
        // 7db195ce6 / d9f142ce0 / 84ef98d98 re-pinned the neighbouring assertions.
        // This test was missed by that sweep and has been red since.
        //
        // MEASURED, live pandas 2.2.3, on exactly these inputs:
        //   df.groupby("grp").rolling(3).std()
        //     index [('a',0), ('a',2), ('a',4), ('a',6), ('b',1), ('b',3), ('b',5)]
        //     val   [nan, nan, 2.0, nan, nan, nan, 1.0]
        //   df.groupby("grp").rolling(3).var()
        //     val   [nan, nan, 4.0, nan, nan, nan, 1.0]
        //
        // The VALUES never disagreed — 2.0 still lands on source row 4 and 1.0 on
        // source row 5. Only their positions move, because the rows are now
        // emitted grouped. (pandas carries the key as an index LEVEL and returns
        // `val` alone; FP keeps `grp` as a column, a divergence documented
        // separately in 732803e70, so column_names is asserted unchanged.)
        let stds = gb.rolling(3).std().unwrap();
        assert_eq!(stds.column_names(), vec!["grp", "val"]);
        assert_int64_index_labels(stds.index(), &[0, 2, 4, 6, 1, 3, 5]);
        let std_vals = stds.column("val").unwrap().values();
        assert!(std_vals[0].is_missing());
        assert!(std_vals[1].is_missing());
        assert!((expect_float64(&std_vals[2]) - 2.0).abs() < 1e-10);
        assert!(std_vals[3].is_missing());
        assert!(std_vals[4].is_missing());
        assert!(std_vals[5].is_missing());
        assert!((expect_float64(&std_vals[6]) - 1.0).abs() < 1e-10);

        let vars = gb.rolling(3).var().unwrap();
        assert_int64_index_labels(vars.index(), &[0, 2, 4, 6, 1, 3, 5]);
        let var_vals = vars.column("val").unwrap().values();
        assert!(var_vals[0].is_missing());
        assert!(var_vals[1].is_missing());
        assert!((expect_float64(&var_vals[2]) - 4.0).abs() < 1e-10);
        assert!(var_vals[3].is_missing());
        assert!(var_vals[4].is_missing());
        assert!(var_vals[5].is_missing());
        assert!((expect_float64(&var_vals[6]) - 1.0).abs() < 1e-10);
    }

    #[test]
    fn groupby_rolling_std_var_int64_input_widens_to_float_with_ddof1_semantics() {
        // Complements groupby_rolling_std_var_respect_group_boundaries...
        // by exercising Int64 inputs and explicit ddof=1 sample-variance
        // semantics on a constant window (var=0, std=0). Uses two
        // multi-row groups with a constant tail to lock numeric
        // expectations and dtype coercion to Float64 output.
        let df = DataFrame::from_dict(
            &["grp", "v"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("b".to_string()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Int64(2),
                        Scalar::Int64(4),
                        Scalar::Int64(4),
                        Scalar::Int64(4),
                        Scalar::Int64(10),
                        Scalar::Int64(10),
                        Scalar::Int64(10),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        let stds = gb.rolling(3).std().unwrap();
        let std_vals = stds.column("v").unwrap().values();
        // group a windows (positions 0..3 in original order):
        //   [2,4,4]   -> mean 10/3, ssq = (2-10/3)^2 + 2*(4-10/3)^2 = 8/3 → ddof=1 var = (8/3)/2 = 4/3
        // group a windows (positions 1..3):
        //   [4,4,4]   -> var = 0
        // group b windows: [10,10,10] -> var = 0
        assert!(std_vals[0].is_missing());
        assert!(std_vals[1].is_missing());
        assert!((expect_float64(&std_vals[2]) - (4.0_f64 / 3.0).sqrt()).abs() < 1e-10);
        assert!((expect_float64(&std_vals[3]) - 0.0).abs() < 1e-12);
        assert!(std_vals[4].is_missing());
        assert!(std_vals[5].is_missing());
        assert!((expect_float64(&std_vals[6]) - 0.0).abs() < 1e-12);

        let vars = gb.rolling(3).var().unwrap();
        let var_vals = vars.column("v").unwrap().values();
        assert!(var_vals[0].is_missing());
        assert!(var_vals[1].is_missing());
        assert!((expect_float64(&var_vals[2]) - (4.0_f64 / 3.0)).abs() < 1e-10);
        assert!((expect_float64(&var_vals[3]) - 0.0).abs() < 1e-12);
        assert!(var_vals[4].is_missing());
        assert!(var_vals[5].is_missing());
        assert!((expect_float64(&var_vals[6]) - 0.0).abs() < 1e-12);

        // Output dtype must widen Int64 -> Float64 (variance is fractional).
        assert_eq!(stds.column("v").unwrap().dtype(), DType::Float64);
        assert_eq!(vars.column("v").unwrap().dtype(), DType::Float64);
    }

    #[test]
    fn groupby_rolling_std_var_all_nan_window_emits_nan() {
        // When every value inside a group's rolling window is NaN, std/var
        // must emit NaN (pandas oracle). Group b is all-NaN to exercise
        // this end-to-end; group a serves as a sanity baseline.
        let df = DataFrame::from_dict(
            &["grp", "v"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(2.0),
                        Scalar::Null(NullKind::NaN),
                        Scalar::Float64(3.0),
                        Scalar::Null(NullKind::NaN),
                    ],
                ),
            ],
        )
        .unwrap();

        let gb = df.groupby(&["grp"]).unwrap();

        let stds = gb.rolling(2).std().unwrap();
        let std_vals = stds.column("v").unwrap().values();
        // ⚠️ GROUP ORDER (br-frankenpandas-nyjxf): rows are group a (source 0,2,4)
        // then group b (source 1,3,5). MEASURED, live pandas 2.2.3:
        //     std  a0 NaN   a2 0.707107   a4 0.707107   b1 NaN   b3 NaN   b5 NaN
        //     var  a0 NaN   a2 0.5        a4 0.5        b1 NaN   b3 NaN   b5 NaN
        // Group b is all-NaN, so every one of its windows is NaN; group a's two
        // full windows each have sample variance 0.5.
        assert!(std_vals[0].is_missing());
        assert!((expect_float64(&std_vals[1]) - (1.0_f64 / 2.0).sqrt()).abs() < 1e-10);
        assert!((expect_float64(&std_vals[2]) - (1.0_f64 / 2.0).sqrt()).abs() < 1e-10);
        assert!(std_vals[3].is_missing());
        assert!(std_vals[4].is_missing());
        assert!(std_vals[5].is_missing());

        let vars = gb.rolling(2).var().unwrap();
        let var_vals = vars.column("v").unwrap().values();
        assert!(var_vals[0].is_missing());
        assert!((expect_float64(&var_vals[1]) - 0.5).abs() < 1e-10);
        assert!((expect_float64(&var_vals[2]) - 0.5).abs() < 1e-10);
        assert!(var_vals[3].is_missing());
        assert!(var_vals[4].is_missing());
        assert!(var_vals[5].is_missing());
    }

    // ── GroupBy resample tests ───────────────────────────────────────

    #[test]
    fn groupby_resample_sum() {
        let df_with_idx = DataFrame::from_dict_with_index(
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("a".to_string()),
                        Scalar::Utf8("b".to_string()),
                        Scalar::Utf8("b".to_string()),
                    ],
                ),
                (
                    "val",
                    vec![
                        Scalar::Float64(100.0),
                        Scalar::Float64(200.0),
                        Scalar::Float64(10.0),
                        Scalar::Float64(20.0),
                    ],
                ),
            ],
            vec![
                "2024-01-01".into(),
                "2024-02-01".into(),
                "2024-01-15".into(),
                "2024-02-15".into(),
            ],
        )
        .unwrap();

        let result = df_with_idx
            .groupby(&["grp"])
            .unwrap()
            .resample("M")
            .sum()
            .unwrap();
        assert_eq!(result.column_names(), vec!["grp", "val"]);
        assert_eq!(result.len(), 4);
        assert_utf8_index_labels(
            result.index(),
            &["2024-01-31", "2024-02-29", "2024-01-31", "2024-02-29"],
        );
        assert_eq!(
            result.column("grp").unwrap().values(),
            &[
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("b".to_string()),
                Scalar::Utf8("b".to_string()),
            ]
        );
        assert_eq!(
            result.column("val").unwrap().values(),
            &[
                Scalar::Float64(100.0),
                Scalar::Float64(200.0),
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
            ]
        );
    }

