    // ── Categorical tests ──

    #[test]
    fn categorical_from_values() {
        let s = Series::from_categorical(
            "color",
            vec![
                Scalar::Utf8("red".into()),
                Scalar::Utf8("blue".into()),
                Scalar::Utf8("red".into()),
                Scalar::Utf8("green".into()),
            ],
            false,
        )
        .unwrap();

        assert!(s.is_categorical());
        let cat = s.cat().unwrap();
        assert_eq!(cat.categories().len(), 3);
        assert!(!cat.ordered());

        // Codes should map: red=0, blue=1, green=2
        assert_eq!(s.column().values()[0], Scalar::Int64(0));
        assert_eq!(s.column().values()[1], Scalar::Int64(1));
        assert_eq!(s.column().values()[2], Scalar::Int64(0));
        assert_eq!(s.column().values()[3], Scalar::Int64(2));
    }

    #[test]
    fn categorical_from_codes() {
        let categories = vec![
            Scalar::Utf8("low".into()),
            Scalar::Utf8("medium".into()),
            Scalar::Utf8("high".into()),
        ];
        let s =
            Series::from_categorical_codes("rating", vec![0, 2, 1, 0], categories, true).unwrap();

        assert!(s.is_categorical());
        let cat = s.cat().unwrap();
        assert_eq!(cat.categories().len(), 3);
        assert!(cat.ordered());
    }

    #[test]
    fn categorical_from_codes_allows_missing_code() {
        let categories = vec![Scalar::Utf8("low".into()), Scalar::Utf8("high".into())];
        let s =
            Series::from_categorical_codes("rating", vec![0, -1, 1], categories, false).unwrap();

        let values = s.cat().unwrap().to_values().unwrap();
        assert_eq!(values.values()[0], Scalar::Utf8("low".into()));
        // The -1 code is a gap the DECODE invents, so pandas renders it as a
        // float nan even though every category is a string. MEASURED, live
        // pandas 2.2.3: pd.Categorical.from_codes([0,-1,1], ['low','high'])
        //   -> ['low', nan, 'high'], kinds ['str', 'float', 'str'].
        // This pinned Null(NullKind::Null) — a supplied-None marker, which is
        // Rule 2 and the wrong rule here. (br-frankenpandas-nywa8)
        assert_eq!(values.values()[1], Scalar::Null(NullKind::NaN));
        assert_eq!(values.values()[2], Scalar::Utf8("high".into()));
    }

    /// ⚠️ `astype` ON A CATEGORICAL MUST CAST THE CATEGORIES, NOT THE CODES.
    /// The column holds integer positions, so casting it directly produced
    /// "0", "1", "0" for a column whose labels are 'x', 'y', 'x'. Every expected
    /// value transcribed from live pandas 2.2.3.
    #[test]
    fn astype_on_a_categorical_casts_the_categories_not_the_codes() {
        // codes [0, 1, 0] over categories ['x', 'y'] — the pair that makes the
        // two answers visibly different.
        let labels = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
            ],
            false,
        )
        .unwrap();
        assert_eq!(
            labels.astype(DType::Utf8).unwrap().values(),
            &[
                Scalar::Utf8("x".to_owned()),
                Scalar::Utf8("y".to_owned()),
                Scalar::Utf8("x".to_owned()),
            ],
            "the CODES would render as 0, 1, 0"
        );

        // Integer categories: Int64 -> Utf8 is a real cast, so the missing is
        // stringified. pandas: ['1', '2', 'nan'].
        let numbers = Series::from_categorical(
            "c",
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN),
            ],
            false,
        )
        .unwrap();
        assert_eq!(
            numbers.astype(DType::Utf8).unwrap().values(),
            &[
                Scalar::Utf8("1".to_owned()),
                Scalar::Utf8("2".to_owned()),
                Scalar::Utf8("nan".to_owned()),
            ]
        );
        // ...and to a numeric target. pandas: [1.0, 2.0, nan].
        let widened = numbers.astype(DType::Float64).unwrap();
        assert_eq!(widened.values()[0], Scalar::Float64(1.0));
        assert_eq!(widened.values()[1], Scalar::Float64(2.0));
        assert!(widened.values()[2].is_missing());

        // Boolean categories render pandas' spellings, not Rust's.
        let flags =
            Series::from_categorical("c", vec![Scalar::Bool(true), Scalar::Bool(false)], false)
                .unwrap();
        assert_eq!(
            flags.astype(DType::Utf8).unwrap().values(),
            &[
                Scalar::Utf8("True".to_owned()),
                Scalar::Utf8("False".to_owned()),
            ]
        );

        // astype_safe reads the column directly in its "coerce" arm, so it needs
        // the same guard — without it this coerces the codes.
        assert_eq!(
            numbers
                .astype_safe(DType::Float64, "coerce")
                .unwrap()
                .values()[0],
            Scalar::Float64(1.0)
        );

        // The residual divergence this test used to pin is CLOSED: `astype(Utf8)`
        // on an already-Utf8 column no longer short-circuits when the column
        // carries a missing value, so the categorical's NaN marker is stringified
        // as pandas spells it. MEASURED:
        //   pd.Series(pd.Categorical(['a', None, 'b'])).astype(str)
        //     -> ['a', 'nan', 'b']
        let with_missing = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("b".into()),
            ],
            false,
        )
        .unwrap();
        let cast = with_missing.astype(DType::Utf8).unwrap();
        assert_eq!(cast.values()[0], Scalar::Utf8("a".to_owned()));
        assert_eq!(cast.values()[2], Scalar::Utf8("b".to_owned()));
        assert_eq!(
            cast.values()[1],
            Scalar::Utf8("nan".to_owned()),
            "a categorical's missing is the NaN marker, which stringifies as 'nan'"
        );
    }

    /// `to_list`/`tolist` returned the CODES for a categorical. Values from
    /// live pandas 2.2.3: `pd.Series(pd.Categorical(['x','y','x'])).tolist()`
    /// is `['x','y','x']` while `list(c.codes)` is `[0, 1, 0]`.
    #[test]
    fn to_list_on_a_categorical_returns_categories_not_codes() {
        let labels = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
            ],
            false,
        )
        .unwrap();
        // The codes are what the column actually holds.
        assert_eq!(labels.column().values()[0], Scalar::Int64(0));
        assert_eq!(labels.column().values()[1], Scalar::Int64(1));
        // ...and the list is the labels, through both spellings.
        let want = vec![
            Scalar::Utf8("x".to_owned()),
            Scalar::Utf8("y".to_owned()),
            Scalar::Utf8("x".to_owned()),
        ];
        assert_eq!(labels.to_list(), want);
        assert_eq!(labels.tolist(), want);

        // A missing code decodes to NaN, not to -1. pandas: ['a', nan, 'b'].
        let gapped = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Null(NullKind::Null),
                Scalar::Utf8("b".into()),
            ],
            false,
        )
        .unwrap();
        let got = gapped.to_list();
        assert_eq!(got[0], Scalar::Utf8("a".to_owned()));
        assert!(got[1].is_missing());
        assert_eq!(got[2], Scalar::Utf8("b".to_owned()));

        // A non-categorical Series is untouched by the guard.
        let plain =
            Series::from_values("p", vec![IndexLabel::Int64(0)], vec![Scalar::Int64(7)]).unwrap();
        assert_eq!(plain.to_list(), vec![Scalar::Int64(7)]);
    }

    /// `isin` on a categorical must test the CATEGORY VALUES. Unguarded, the
    /// Int64 fast path matched the user's integers against the codes — a
    /// confidently wrong answer rather than a miss. From live pandas 2.2.3 on
    /// `Categorical([10, 20, 10])`, whose codes are `[0, 1, 0]`.
    #[test]
    fn isin_on_a_categorical_tests_values_not_codes() {
        let numbers = Series::from_categorical(
            "c",
            vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(10)],
            false,
        )
        .unwrap();
        assert_eq!(numbers.column().values()[0], Scalar::Int64(0), "codes");

        let by_value = numbers.isin(&[Scalar::Int64(10)]).unwrap();
        assert_eq!(
            by_value.values(),
            &[Scalar::Bool(true), Scalar::Bool(false), Scalar::Bool(true)]
        );

        // ⚠️ THE ROW THAT FAILS WITHOUT THE GUARD: code 0 exists, value 0 does not.
        let by_code = numbers.isin(&[Scalar::Int64(0)]).unwrap();
        assert_eq!(
            by_code.values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(false),
                Scalar::Bool(false)
            ],
            "matching a CODE must not report membership"
        );

        // String categories, where the unguarded answer was merely all-false.
        let labels = Series::from_categorical(
            "c",
            vec![Scalar::Utf8("x".into()), Scalar::Utf8("y".into())],
            false,
        )
        .unwrap();
        assert_eq!(
            labels.isin(&[Scalar::Utf8("x".into())]).unwrap().values(),
            &[Scalar::Bool(true), Scalar::Bool(false)]
        );
    }

    /// `unique` returned distinct CODES. From live pandas 2.2.3 on
    /// `Categorical([10, 20, 10, 30])`, whose codes are `[0, 1, 0, 2]`:
    /// `s.unique()` is `[10, 20, 30]`.
    #[test]
    fn unique_on_a_categorical_returns_categories_not_codes() {
        let numbers = Series::from_categorical(
            "c",
            vec![
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(10),
                Scalar::Int64(30),
            ],
            false,
        )
        .unwrap();
        // The codes are what the column holds, and they are NOT the answer.
        assert_eq!(numbers.column().values()[3], Scalar::Int64(2));
        assert_eq!(
            numbers.unique(),
            vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)]
        );

        // First-appearance order, which decoding before the dedup preserves.
        let labels = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
            ],
            false,
        )
        .unwrap();
        assert_eq!(
            labels.unique(),
            vec![Scalar::Utf8("y".to_owned()), Scalar::Utf8("x".to_owned())]
        );
    }

    /// `map` on a categorical resolved the mapping against CODES. From live
    /// pandas 2.2.3 on `Categorical([10, 20, 10, 30])`, codes `[0, 1, 0, 2]`.
    #[test]
    fn map_on_a_categorical_resolves_values_not_codes() {
        let numbers = Series::from_categorical(
            "c",
            vec![
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(10),
                Scalar::Int64(30),
            ],
            false,
        )
        .unwrap();

        let by_value = numbers
            .map(&[(Scalar::Int64(10), Scalar::Utf8("a".into()))])
            .unwrap();
        assert_eq!(by_value.values()[0], Scalar::Utf8("a".to_owned()));
        assert!(by_value.values()[1].is_missing());
        assert_eq!(by_value.values()[2], Scalar::Utf8("a".to_owned()));
        assert!(by_value.values()[3].is_missing());

        // ⚠️ THE ROW THAT FAILS WITHOUT THE GUARD: keying on 0 hits code 0.
        let by_code = numbers
            .map(&[(Scalar::Int64(0), Scalar::Utf8("a".into()))])
            .unwrap();
        for value in by_code.values() {
            assert!(
                value.is_missing(),
                "a CODE must not resolve as a value, got {value:?}"
            );
        }

        let labels = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
            ],
            false,
        )
        .unwrap();
        let hits = labels
            .map(&[(Scalar::Utf8("x".into()), Scalar::Utf8("hit".into()))])
            .unwrap();
        assert_eq!(hits.values()[0], Scalar::Utf8("hit".to_owned()));
        assert!(hits.values()[1].is_missing());
    }

    /// `mode` on a categorical returned CODES, ordered by code. From live
    /// pandas 2.2.3: `Categorical(['b','a','b','a']).mode()` is `['a','b']` —
    /// sorted by VALUE, which FP's first-seen code numbering does not give.
    #[test]
    fn mode_on_a_categorical_returns_values_sorted_by_value() {
        let tied = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
            ],
            false,
        )
        .unwrap();
        // 'b' is seen first, so it is code 0 — ordering by code would put it
        // first, and pandas puts 'a' first.
        assert_eq!(tied.column().values()[0], Scalar::Int64(0));
        assert_eq!(
            tied.mode().unwrap().values(),
            &[Scalar::Utf8("a".to_owned()), Scalar::Utf8("b".to_owned())]
        );

        let numbers = Series::from_categorical(
            "c",
            vec![
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(10),
                Scalar::Int64(30),
            ],
            false,
        )
        .unwrap();
        assert_eq!(numbers.mode().unwrap().values(), &[Scalar::Int64(10)]);
    }

    /// `drop_duplicates` picked the right ROWS on a categorical (codes and
    /// categories are a bijection) but returned them as a plain Int64 Series of
    /// codes. pandas keeps `dtype: category`. Values from live pandas 2.2.3 on
    /// `Categorical([10, 20, 10, 30])`.
    #[test]
    fn drop_duplicates_on_a_categorical_stays_categorical() {
        let numbers = Series::from_categorical(
            "c",
            vec![
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(10),
                Scalar::Int64(30),
            ],
            false,
        )
        .unwrap();

        let first = numbers.drop_duplicates().unwrap();
        assert_eq!(first.dtype(), DType::Categorical, "pandas keeps category");
        // Read through the accessor: the values, not the codes.
        assert_eq!(
            first.to_list(),
            vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)]
        );
        // ...and the surviving rows are the first occurrences.
        assert_eq!(first.index().labels().len(), 3);

        // keep=Last selects different ROWS; the metadata must survive that too.
        let last = numbers.drop_duplicates_keep(DuplicateKeep::Last).unwrap();
        assert_eq!(last.dtype(), DType::Categorical);
        assert_eq!(
            last.to_list(),
            vec![Scalar::Int64(20), Scalar::Int64(10), Scalar::Int64(30)]
        );
    }

    /// Row-subset methods must keep `dtype: category`. `Series::new` drops the
    /// metadata, so every one of them silently returned the codes' int64.
    /// MEASURED, live pandas 2.2.3, on `Categorical(['x','y','x','z'])`: head,
    /// tail, sort_values, iloc and a row window all report `category`.
    #[test]
    fn row_subset_methods_keep_the_categorical_dtype() {
        let source = Series::from_categorical(
            "c",
            vec![
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
                Scalar::Utf8("z".into()),
            ],
            false,
        )
        .unwrap();
        assert_eq!(source.dtype(), DType::Categorical);

        let first_two = source.head(2).unwrap();
        assert_eq!(first_two.dtype(), DType::Categorical, "head");
        assert_eq!(
            first_two.to_list(),
            vec![Scalar::Utf8("x".to_owned()), Scalar::Utf8("y".to_owned())]
        );

        let last_two = source.tail(2).unwrap();
        assert_eq!(last_two.dtype(), DType::Categorical, "tail");
        assert_eq!(
            last_two.to_list(),
            vec![Scalar::Utf8("x".to_owned()), Scalar::Utf8("z".to_owned())]
        );

        // The subset keeps the FULL category list, exactly as pandas does — a
        // category that no surviving row uses is still a category.
        assert_eq!(
            last_two
                .cat()
                .expect("still categorical")
                .categories()
                .len(),
            3
        );
    }

