    // ── DataFrame eval/query/filter/map/where alias suite (br-frankenpandas-nk54a) ─

    fn nk54a_df() -> DataFrame {
        let cols = vec![
            (
                "a".to_owned(),
                Column::new(
                    DType::Int64,
                    vec![Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)],
                )
                .unwrap(),
            ),
            (
                "b".to_owned(),
                Column::new(
                    DType::Int64,
                    vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
                )
                .unwrap(),
            ),
            (
                "secret".to_owned(),
                Column::new(
                    DType::Utf8,
                    vec![
                        Scalar::Utf8("x".into()),
                        Scalar::Utf8("y".into()),
                        Scalar::Utf8("z".into()),
                    ],
                )
                .unwrap(),
            ),
        ];
        let mut map = BTreeMap::new();
        let order: Vec<String> = cols.iter().map(|(n, _)| n.clone()).collect();
        for (n, c) in cols {
            map.insert(n, c);
        }
        DataFrame::new_with_column_order(
            Index::new(vec![0_i64.into(), 1_i64.into(), 2_i64.into()]),
            map,
            order,
        )
        .unwrap()
    }

    #[test]
    fn dataframe_map_aliases_applymap() {
        let df = nk54a_df();
        let inc = |s: &Scalar| match s {
            Scalar::Int64(v) => Scalar::Int64(v + 1),
            other => other.clone(),
        };
        let via_map = df.map(inc).unwrap();
        let via_applymap = df.applymap(inc).unwrap();
        for col in df.column_names() {
            assert_eq!(
                via_map.column(col).unwrap().values(),
                via_applymap.column(col).unwrap().values(),
                "column {col} differs"
            );
        }
    }

    #[test]
    fn dataframe_where_aliases_where_cond() {
        let df = nk54a_df();
        let cond = nk54a_df()
            .map(|s| match s {
                Scalar::Int64(v) => Scalar::Bool(*v >= 20),
                _ => Scalar::Bool(true),
            })
            .unwrap();
        let via_where = df.r#where(&cond, Some(&Scalar::Int64(-1))).unwrap();
        let via_where_cond = df.where_cond(&cond, Some(&Scalar::Int64(-1))).unwrap();
        for col in df.column_names() {
            assert_eq!(
                via_where.column(col).unwrap().values(),
                via_where_cond.column(col).unwrap().values(),
                "column {col} differs"
            );
        }
    }

    #[test]
    fn dataframe_filter_items_keeps_listed_columns_in_order() {
        let df = nk54a_df();
        let out = df.filter(Some(&["b", "a"]), None, None).unwrap();
        assert_eq!(out.column_names(), vec!["b", "a"]);
        assert!(out.column("secret").is_none());
        // "missing" silently dropped
        let out2 = df.filter(Some(&["b", "no_such", "a"]), None, None).unwrap();
        assert_eq!(out2.column_names(), vec!["b", "a"]);
    }

    #[test]
    fn dataframe_filter_like_keeps_substring_matches() {
        let df = nk54a_df();
        let out = df.filter(None, Some("ec"), None).unwrap();
        assert_eq!(out.column_names(), vec!["secret"]);
    }

    #[test]
    fn dataframe_filter_regex_keeps_pattern_matches() {
        let df = nk54a_df();
        // Match single-letter column names
        let out = df.filter(None, None, Some(r"^[a-z]$")).unwrap();
        assert_eq!(out.column_names(), vec!["a", "b"]);
        let out2 = df.filter(None, None, Some(r"^sec")).unwrap();
        assert_eq!(out2.column_names(), vec!["secret"]);
    }

    #[test]
    fn dataframe_filter_rejects_zero_or_multiple_args() {
        let df = nk54a_df();
        let err = df
            .filter(None, None, None)
            .expect_err("zero-arg must reject");
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("exactly one"))
        );
        let err2 = df
            .filter(Some(&["a"]), Some("a"), None)
            .expect_err("multi-arg must reject");
        assert!(matches!(err2, FrameError::CompatibilityRejected(_)));
    }

    // ── DataFrame metadata and accessor aliases (frankenpandas-qn0bj) ──

    #[test]
    fn dataframe_qn0bj_metadata_aliases_cover_t_values_product_and_get() {
        let df = nk54a_df();
        assert_eq!(df.T().unwrap(), df.transpose().unwrap());
        // `product` is an alias of `prod`, so it must agree on BOTH paths. This
        // frame carries a Utf8 column, and since
        // br-frankenpandas-reductions-numeric-only-default-zx21n the default is
        // pandas 2.x's numeric_only=False, under which prod RAISES
        // ("can't multiply sequence by non-int of type 'str'"). Comparing the
        // refusals as well as the values keeps this an ALIAS test rather than
        // one that quietly re-pins a reduction default.
        assert_eq!(
            df.product().unwrap_err().to_string(),
            df.prod().unwrap_err().to_string()
        );
        assert_eq!(
            df.product_with_numeric_only(true).unwrap().values(),
            df.prod_with_numeric_only(true).unwrap().values()
        );

        let values = df.values();
        assert_eq!(values.len(), 3);
        assert_eq!(values[0][0], Scalar::Int64(10));
        assert_eq!(values[0][2], Scalar::Utf8("x".into()));

        let found = df.get("a").unwrap().expect("column a should exist");
        assert_eq!(
            found.values(),
            &[Scalar::Int64(10), Scalar::Int64(20), Scalar::Int64(30)]
        );
        assert!(df.get("missing").unwrap().is_none());

        let default = Series::from_values(
            "fallback",
            vec![0_i64.into()],
            vec![Scalar::Utf8("default".into())],
        )
        .unwrap();
        let fallback = df.get_or("missing", default.clone()).unwrap();
        assert_eq!(fallback, default);
    }

    #[test]
    fn dataframe_qn0bj_attrs_flags_style_sparse_and_bool() {
        let bool_df =
            DataFrame::from_dict(&["flag"], vec![("flag", vec![Scalar::Bool(true)])]).unwrap();
        assert!(bool_df.bool_().unwrap());
        assert!(bool_df.attrs().is_empty());
        assert!(bool_df.flags().allows_duplicate_labels());
        assert_eq!(bool_df.set_flags(None).unwrap(), bool_df);
        let strict = bool_df.set_flags(Some(false)).unwrap();
        assert!(!strict.flags().allows_duplicate_labels());
        assert!(!strict.copy().flags().allows_duplicate_labels());
        assert!(
            !strict
                .set_flags(None)
                .unwrap()
                .flags()
                .allows_duplicate_labels()
        );
        assert!(
            strict
                .set_flags(Some(true))
                .unwrap()
                .flags()
                .allows_duplicate_labels()
        );
        assert_eq!(
            strict.column("flag").unwrap().values(),
            bool_df.column("flag").unwrap().values()
        );
        assert_eq!(bool_df.style().dataframe(), &bool_df);
        assert_eq!(bool_df.sparse().dataframe(), &bool_df);

        let err = nk54a_df().bool_().unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("exactly one element"))
        );
    }

    #[test]
    fn dataframe_qn0bj_set_flags_rejects_duplicate_labels_when_disallowed() {
        let mut columns = BTreeMap::new();
        columns.insert(
            "x".to_owned(),
            Column::from_values(vec![Scalar::Int64(1), Scalar::Int64(2)]).unwrap(),
        );
        let df = DataFrame::new(Index::new(vec![0_i64.into(), 0_i64.into()]), columns).unwrap();

        let err = df.set_flags(Some(false)).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("duplicate labels"))
        );
    }

    #[test]
    fn dataframe_ia1v9_style_renders_html_and_classed_tables() -> Result<(), FrameError> {
        let df = DataFrame::from_dict(
            &["label", "value"],
            vec![
                (
                    "label",
                    vec![
                        Scalar::Utf8("<low>".to_owned()),
                        Scalar::Utf8("high".to_owned()),
                    ],
                ),
                ("value", vec![Scalar::Int64(1), Scalar::Int64(2)]),
            ],
        )?;
        let style = df.style();

        assert_eq!(style.dataframe(), &df);
        assert_eq!(style.to_html(true), df.to_html(true));
        assert_eq!(style.to_string_table(false), df.to_string_table(false));

        let classed = style.to_html_with_classes(true, &["report", " compact ", ""]);
        assert!(classed.contains("class=\"report compact\""));
        assert!(classed.contains("<td>&lt;low&gt;</td>"));
        assert!(classed.contains("<th></th>"));

        let escaped = style.to_html_classed(false, "summary\"<table>");
        assert!(escaped.contains("class=\"summary&quot;&lt;table&gt;\""));
        assert!(!escaped.contains("<th></th>"));

        let default_class = style.to_html_with_classes(true, &["", "  "]);
        assert!(default_class.contains("class=\"dataframe\""));
        Ok(())
    }

    #[test]
    fn dataframe_9hn_style_highlight_gradient_format_caption() -> Result<(), FrameError> {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(3.0),
                        Scalar::Float64(2.0),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Float64(10.0),
                        Scalar::Float64(20.0),
                        Scalar::Float64(30.0),
                    ],
                ),
            ],
        )?;

        // highlight_max marks the per-column maximum cell(s); highlight_min the
        // minimum. Column a max=3.0 (row 1), b max=30.0 (row 2).
        let html = df.style().highlight_max("yellow").to_html(false);
        // Row 1 col a (3.0) and row 2 col b (30.0) are highlighted; 1.0 is not.
        assert!(html.contains("<td style=\"background-color: yellow;\">3.0</td>"));
        assert!(html.contains("<td style=\"background-color: yellow;\">30.0</td>"));
        assert!(html.contains("<td>1.0</td>"));

        let html_min = df.style().highlight_min("#ff0000").to_html(false);
        // Column a min=1.0 (row 0), column b min=10.0 (row 0).
        assert!(html_min.contains("<td style=\"background-color: #ff0000;\">1.0</td>"));
        assert!(html_min.contains("<td style=\"background-color: #ff0000;\">10.0</td>"));

        // background_gradient: column a min(1.0)->#000000, max(3.0)->#ffffff;
        // the minimum cell gets the low endpoint, the maximum the high endpoint.
        let grad = df
            .style()
            .background_gradient("#000000", "#ffffff")
            .to_html(false);
        assert!(grad.contains("<td style=\"background-color: #000000;\">1.0</td>"));
        assert!(grad.contains("<td style=\"background-color: #ffffff;\">3.0</td>"));
        // Midpoint 2.0 -> t=0.5 -> #808080 (128 rounded).
        assert!(grad.contains("<td style=\"background-color: #808080;\">2.0</td>"));

        // format applies a Python-style spec to numeric cells.
        let fmt = df.style().format("{:.2f}").to_html(false);
        assert!(fmt.contains("<td>1.00</td>"));
        assert!(fmt.contains("<td>30.00</td>"));

        // Thousands separators + prefix.
        let money = DataFrame::from_dict(&["x"], vec![("x", vec![Scalar::Float64(1234567.5)])])?;
        let money_html = money.style().format("${:,.2f}").to_html(false);
        assert!(money_html.contains("<td>$1,234,567.50</td>"));

        // Percent format.
        let pct = DataFrame::from_dict(&["p"], vec![("p", vec![Scalar::Float64(0.125)])])?;
        let pct_html = pct.style().format("{:.1%}").to_html(false);
        assert!(pct_html.contains("<td>12.5%</td>"));

        // set_caption emits a <caption>; HTML special chars are escaped.
        let cap = df.style().set_caption("Summary <b> & co").to_html(false);
        assert!(cap.contains("<caption>Summary &lt;b&gt; &amp; co</caption>"));

        // Chaining all directives together still renders a single table.
        let chained = df
            .style()
            .set_caption("All")
            .format("{:.1f}")
            .highlight_max("yellow")
            .to_html(true);
        assert!(chained.contains("<caption>All</caption>"));
        assert!(chained.contains("background-color: yellow;"));
        assert_eq!(chained.matches("<table").count(), 1);

        // No directives → byte-identical to DataFrame::to_html.
        assert_eq!(df.style().to_html(true), df.to_html(true));
        Ok(())
    }

    #[test]
    fn dataframe_ium6s_style_set_properties_bar_hide_index() -> Result<(), FrameError> {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Float64(0.0),
                    Scalar::Float64(5.0),
                    Scalar::Float64(10.0),
                ],
            )],
        )?;

        // set_properties applies fixed CSS to every data cell (not headers).
        let props = df
            .style()
            .set_properties(&[("color", "white"), ("font-weight", "bold")])
            .to_html(false);
        assert_eq!(
            props
                .matches("<td style=\"color: white;font-weight: bold;\">")
                .count(),
            3
        );

        // bar fills each numeric cell proportionally: 0->0%, 5->50%, 10->100%.
        let bars = df.style().bar("steelblue").to_html(false);
        assert!(bars.contains(
            "<td style=\"background: linear-gradient(90deg, steelblue 0%, transparent 0%);\">0.0</td>"
        ));
        assert!(bars.contains(
            "<td style=\"background: linear-gradient(90deg, steelblue 50%, transparent 50%);\">5.0</td>"
        ));
        assert!(bars.contains(
            "<td style=\"background: linear-gradient(90deg, steelblue 100%, transparent 100%);\">10.0</td>"
        ));

        // hide_index suppresses the index column/header even when callers ask
        // for it.
        let hidden = df.style().hide_index().to_html(true);
        assert!(!hidden.contains("<th></th>"));
        assert!(!hidden.contains("<th>0</th>"));
        // The single data column header survives.
        assert!(hidden.contains("<th>a</th>"));

        // set_properties + bar compose on the same cell, in declaration order.
        let combined = df
            .style()
            .set_properties(&[("color", "red")])
            .bar("gray")
            .to_html(false);
        assert!(combined.contains(
            "<td style=\"color: red;background: linear-gradient(90deg, gray 50%, transparent 50%);\">5.0</td>"
        ));
        Ok(())
    }

    #[test]
    fn dataframe_to3n2_style_na_rep_renders_missing_placeholder() -> Result<(), FrameError> {
        let df = DataFrame::from_dict(
            &["a"],
            vec![(
                "a",
                vec![
                    Scalar::Float64(1.5),
                    Scalar::Null(NullKind::Null),
                    Scalar::Float64(f64::NAN),
                ],
            )],
        )?;

        // Default render shows "NaN" for both missing kinds.
        assert_eq!(df.style().to_html(false).matches("<td>NaN</td>").count(), 2);

        // na_rep replaces missing cells; HTML-special chars are escaped.
        let html = df.style().na_rep("<n/a>").to_html(false);
        assert_eq!(html.matches("<td>&lt;n/a&gt;</td>").count(), 2);
        assert!(html.contains("<td>1.5</td>"));

        // na_rep takes precedence over a numeric format on missing cells, while
        // present cells still honour the format.
        let fmt = df.style().na_rep("-").format("{:.2f}").to_html(false);
        assert_eq!(fmt.matches("<td>-</td>").count(), 2);
        assert!(fmt.contains("<td>1.50</td>"));
        Ok(())
    }

    #[test]
    fn dataframe_zvvtk_sparse_accessor_reports_density_npoints_and_dense_copy()
    -> Result<(), FrameError> {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![Scalar::Int64(0), Scalar::Int64(5), Scalar::Int64(0)],
                ),
                (
                    "b",
                    vec![
                        Scalar::Int64(0),
                        Scalar::Null(NullKind::Null),
                        Scalar::Int64(4),
                    ],
                ),
            ],
        )
        .and_then(|df| df.set_flags(Some(false)))?;

        let sparse = df.sparse();
        assert_eq!(sparse.dataframe(), &df);

        let default_npoints = sparse.column_npoints();
        assert_eq!(default_npoints.get("a"), Some(&3));
        assert_eq!(default_npoints.get("b"), Some(&2));
        assert_eq!(sparse.npoints(), 5);
        assert!((sparse.density() - (5.0 / 6.0)).abs() < f64::EPSILON);

        let zero_npoints = sparse.column_npoints_with_fill_value(&Scalar::Int64(0));
        assert_eq!(zero_npoints.get("a"), Some(&1));
        assert_eq!(zero_npoints.get("b"), Some(&2));
        assert_eq!(sparse.npoints_with_fill_value(&Scalar::Int64(0)), 3);

        let zero_density = sparse.column_density_with_fill_value(&Scalar::Int64(0));
        assert!(
            matches!(zero_density.get("a"), Some(value) if (*value - (1.0 / 3.0)).abs() < f64::EPSILON)
        );
        assert!(
            matches!(zero_density.get("b"), Some(value) if (*value - (2.0 / 3.0)).abs() < f64::EPSILON)
        );
        assert!((sparse.density_with_fill_value(&Scalar::Int64(0)) - 0.5).abs() < f64::EPSILON);

        let dense = sparse.to_dense();
        assert_eq!(dense, df);
        assert!(!dense.flags().allows_duplicate_labels());
        Ok(())
    }

    #[test]
    fn dataframe_qn0bj_strict_flags_reject_duplicate_label_reindexing() {
        let df = DataFrame::from_dict(
            &["x"],
            vec![("x", vec![Scalar::Int64(1), Scalar::Int64(2)])],
        )
        .unwrap()
        .set_flags(Some(false))
        .unwrap();

        let err = df
            .set_axis(vec![0_i64.into(), 0_i64.into()], 0)
            .unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("duplicate labels"))
        );

        let err = df.reindex(vec![0_i64.into(), 0_i64.into()]).unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("duplicate labels"))
        );

        let err = df
            .reindex_fill(
                vec![0_i64.into(), 0_i64.into()],
                Scalar::Null(NullKind::NaN),
            )
            .unwrap_err();
        assert!(
            matches!(err, FrameError::CompatibilityRejected(msg) if msg.contains("duplicate labels"))
        );
    }

