    #[test]
    fn dataframe_to_period_anchored_weekly_freqs_krw0g() {
        // br-frankenpandas-krw0g: anchored weekly aliases W-MON..W-SAT. The week
        // ends on the anchor weekday; labels are START/END. Verified vs live
        // pandas 2.2.3 for index 2020-01-01 (Wed) / 2020-01-04 (Sat):
        //   W-MON -> both 2019-12-31/2020-01-06
        //   W-WED -> 2019-12-26/2020-01-01 , 2020-01-02/2020-01-08
        //   W-SAT -> both 2019-12-29/2020-01-04
        let mut columns = BTreeMap::new();
        columns.insert(
            "value".to_owned(),
            Column::from_values(vec![Scalar::Int64(10), Scalar::Int64(20)]).unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::from_utf8(vec!["2020-01-01".to_owned(), "2020-01-04".to_owned()])
                .set_names(Some("when")),
            columns,
            vec!["value".to_owned()],
        )
        .unwrap();

        let cases = [
            ("W-MON", ["2019-12-31/2020-01-06", "2019-12-31/2020-01-06"]),
            ("W-WED", ["2019-12-26/2020-01-01", "2020-01-02/2020-01-08"]),
            ("W-SAT", ["2019-12-29/2020-01-04", "2019-12-29/2020-01-04"]),
        ];
        for (freq, expected) in cases {
            let periods = df.to_period(freq).unwrap();
            assert_eq!(
                periods.index().labels(),
                &[
                    IndexLabel::Utf8(expected[0].into()),
                    IndexLabel::Utf8(expected[1].into()),
                ],
                "to_period({freq})"
            );
            assert_eq!(periods.index().name(), Some("when"));
        }

        // to_timestamp round-trips the anchored label (anchor-independent split).
        let wwed = df.to_period("W-WED").unwrap();
        let ends = wwed.to_timestamp("W-WED", "end").unwrap();
        assert_eq!(
            ends.index().labels(),
            &[
                IndexLabel::Datetime64(
                    parse_datetime64_nanos("2020-01-01 23:59:59.999999999").unwrap()
                ),
                IndexLabel::Datetime64(
                    parse_datetime64_nanos("2020-01-08 23:59:59.999999999").unwrap()
                ),
            ]
        );
    }

    #[test]
    fn dataframe_to_period_anchored_annual_freqs_krw0g() {
        // br-frankenpandas-krw0g: anchored annual aliases Y-JAN..Y-NOV (fiscal
        // year ENDS in the anchor month; label is the ending calendar year).
        // Verified vs live pandas 2.2.3 for index 2024-01-15 / 2024-07-15:
        //   Y-JAN -> 2024 , 2025      Y-MAR -> 2024 , 2025
        //   Y-NOV -> 2024 , 2024      (default Y-DEC -> 2024 , 2024)
        let mut columns = BTreeMap::new();
        columns.insert(
            "value".to_owned(),
            Column::from_values(vec![Scalar::Int64(10), Scalar::Int64(20)]).unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::from_utf8(vec!["2024-01-15".to_owned(), "2024-07-15".to_owned()])
                .set_names(Some("when")),
            columns,
            vec!["value".to_owned()],
        )
        .unwrap();

        for (freq, expected) in [
            ("Y-JAN", ["2024", "2025"]),
            ("Y-MAR", ["2024", "2025"]),
            ("Y-NOV", ["2024", "2024"]),
            ("Y-DEC", ["2024", "2024"]),
        ] {
            let periods = df.to_period(freq).unwrap();
            assert_eq!(
                periods.index().labels(),
                &[
                    IndexLabel::Utf8(expected[0].into()),
                    IndexLabel::Utf8(expected[1].into()),
                ],
                "to_period({freq})"
            );
        }

        // to_timestamp for an anchored fiscal year: Y-MAR 2025 spans
        // 2024-04-01 .. 2025-03-31 (verified vs pandas).
        let ymar = df.to_period("Y-MAR").unwrap();
        let starts = ymar.to_timestamp("Y-MAR", "start").unwrap();
        let ends = ymar.to_timestamp("Y-MAR", "end").unwrap();
        assert_eq!(
            starts.index().labels()[1],
            IndexLabel::Datetime64(parse_datetime64_nanos("2024-04-01 00:00:00").unwrap())
        );
        assert_eq!(
            ends.index().labels()[1],
            IndexLabel::Datetime64(
                parse_datetime64_nanos("2025-03-31 23:59:59.999999999").unwrap()
            )
        );
    }

    #[test]
    fn dataframe_to_period_anchored_quarterly_freqs_krw0g() {
        // br-frankenpandas-krw0g: anchored quarterly aliases Q-JAN..Q-NOV (the
        // fiscal year — and Q4 — ends in the anchor month; Q1 starts the month
        // after). Verified vs live pandas 2.2.3 for index 2024-01-15 / 2024-07-15:
        //   Q-JAN/Q-FEB/Q-MAR -> 2024Q4 , 2025Q2   (default Q-DEC -> 2024Q1 , 2024Q3)
        let mut columns = BTreeMap::new();
        columns.insert(
            "value".to_owned(),
            Column::from_values(vec![Scalar::Int64(10), Scalar::Int64(20)]).unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::from_utf8(vec!["2024-01-15".to_owned(), "2024-07-15".to_owned()])
                .set_names(Some("when")),
            columns,
            vec!["value".to_owned()],
        )
        .unwrap();

        for (freq, expected) in [
            ("Q-JAN", ["2024Q4", "2025Q2"]),
            ("Q-FEB", ["2024Q4", "2025Q2"]),
            ("Q-MAR", ["2024Q4", "2025Q2"]),
            ("Q-DEC", ["2024Q1", "2024Q3"]),
        ] {
            let periods = df.to_period(freq).unwrap();
            assert_eq!(
                periods.index().labels(),
                &[
                    IndexLabel::Utf8(expected[0].into()),
                    IndexLabel::Utf8(expected[1].into()),
                ],
                "to_period({freq})"
            );
        }

        // to_timestamp for anchored fiscal quarters (Q-JAN): 2024Q4 spans
        // 2023-11-01 .. 2024-01-31; 2025Q2 spans 2024-05-01 .. 2024-07-31.
        let qjan = df.to_period("Q-JAN").unwrap();
        let starts = qjan.to_timestamp("Q-JAN", "start").unwrap();
        let ends = qjan.to_timestamp("Q-JAN", "end").unwrap();
        assert_eq!(
            starts.index().labels(),
            &[
                IndexLabel::Datetime64(parse_datetime64_nanos("2023-11-01 00:00:00").unwrap()),
                IndexLabel::Datetime64(parse_datetime64_nanos("2024-05-01 00:00:00").unwrap()),
            ]
        );
        assert_eq!(
            ends.index().labels(),
            &[
                IndexLabel::Datetime64(
                    parse_datetime64_nanos("2024-01-31 23:59:59.999999999").unwrap()
                ),
                IndexLabel::Datetime64(
                    parse_datetime64_nanos("2024-07-31 23:59:59.999999999").unwrap()
                ),
            ]
        );
    }

