    // Isomorphism guard for the O(n) online roll_sum/roll_mean rewrite
    // (br-frankenpandas-slt1p): the compensated two-pointer sweep must agree
    // with the historical per-window naive recompute within tight tolerance and
    // match NaN/missing positions exactly, across window sizes, min_periods,
    // centering, and missing patterns. The conformance live-oracle separately
    // pins parity vs real pandas; this keeps the two FP paths equivalent.
    #[test]
    fn rolling_online_sum_mean_matches_naive_reference() {
        fn naive(
            vals: &[Option<f64>],
            window: usize,
            min_periods: usize,
            center: bool,
            mean: bool,
        ) -> Vec<Option<f64>> {
            let len = vals.len();
            let mut out = Vec::with_capacity(len);
            for i in 0..len {
                let (start, end) = if center {
                    let half = window / 2;
                    (i.saturating_sub(half), (i + half + window % 2).min(len))
                } else {
                    ((i + 1).saturating_sub(window), i + 1)
                };
                let nums: Vec<f64> = vals[start..end].iter().filter_map(|v| *v).collect();
                if nums.len() < min_periods {
                    out.push(None);
                } else if mean {
                    if nums.is_empty() {
                        out.push(None); // NaN, normalized to missing on the column
                    } else {
                        out.push(Some(nums.iter().sum::<f64>() / nums.len() as f64));
                    }
                } else {
                    out.push(Some(nums.iter().sum::<f64>())); // empty -> 0.0
                }
            }
            out
        }

        // Deterministic xorshift values in [-100, 100] (2-decimal, no -0.0),
        // with ~9% missing cells.
        let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
        let mut next = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        let n = 200usize;
        let mut labels = Vec::with_capacity(n);
        let mut scalars = Vec::with_capacity(n);
        let mut opt: Vec<Option<f64>> = Vec::with_capacity(n);
        for i in 0..n {
            labels.push((i as i64).into());
            let r = next();
            if r % 11 == 0 {
                scalars.push(Scalar::Null(NullKind::NaN));
                opt.push(None);
            } else {
                let v = ((r % 20_000) as f64) / 100.0 - 100.0;
                scalars.push(Scalar::Float64(v));
                opt.push(Some(v));
            }
        }
        let s = Series::from_values("v", labels, scalars).unwrap();

        for &window in &[1usize, 2, 3, 7, 50, 200] {
            for &mp in &[
                None,
                Some(0usize),
                Some(1),
                Some(window.min(3)),
                Some(window),
            ] {
                let min_periods = mp.unwrap_or(window);
                if min_periods > window {
                    continue;
                }
                for &center in &[false, true] {
                    for mean in [false, true] {
                        let r = if center {
                            s.rolling_with_center(window, mp, true)
                        } else {
                            s.rolling(window, mp)
                        };
                        let got = if mean {
                            r.mean().unwrap()
                        } else {
                            r.sum().unwrap()
                        };
                        let want = naive(&opt, window, min_periods, center, mean);
                        assert_eq!(got.len(), want.len());
                        for (idx, w) in want.iter().enumerate() {
                            let g = &got.values()[idx];
                            match w {
                                None => assert!(
                                    g.is_missing(),
                                    "expected missing at {idx}: got={g:?} window={window} mp={mp:?} center={center} mean={mean}"
                                ),
                                Some(wv) if wv.is_nan() => assert!(g.is_missing()),
                                Some(wv) => {
                                    let gv = g.to_f64().unwrap();
                                    let tol = 1e-9 * wv.abs().max(1.0);
                                    assert!(
                                        (gv - wv).abs() <= tol,
                                        "value drift at {idx}: got={gv} want={wv} window={window} mp={mp:?} center={center} mean={mean}"
                                    );
                                }
                            }
                        }
                    }
                }
            }
        }
    }

