    #[test]
    fn stack_parallel_label_build_matches_serial_prefix_ironquail() {
        // Row i produces composite labels "i|a","i|b","i|c" — depends only on i. The 40k
        // frame stacks via the SERIAL label build (< STACK_LABEL_PAR_MIN_ROWS); the 60k
        // via the CHUNKED-PARALLEL build. So the 60k stacked index labels (and value
        // column) must have the 40k results as an exact prefix, proving the parallel
        // concat/offset math is identical to serial across chunk boundaries.
        let mk = |n: usize| -> DataFrame {
            let mut cols = BTreeMap::new();
            cols.insert(
                "a".to_string(),
                Column::from_i64_values((0..n as i64).collect()),
            );
            cols.insert(
                "b".to_string(),
                Column::from_i64_values((0..n as i64).map(|i| i + 1).collect()),
            );
            cols.insert(
                "c".to_string(),
                Column::from_i64_values((0..n as i64).map(|i| i + 2).collect()),
            );
            DataFrame::new_with_column_order(
                Index::from_range(0, n as i64, 1),
                cols,
                vec!["a".to_string(), "b".to_string(), "c".to_string()],
            )
            .unwrap()
        };
        let small = mk(40_000).stack().unwrap();
        let large = mk(60_000).stack().unwrap();
        let ls = small.index().labels();
        let ll = large.index().labels();
        assert_eq!(ls.len(), 40_000 * 3);
        assert_eq!(ll.len(), 60_000 * 3);
        assert_eq!(
            &ll[..40_000 * 3],
            ls,
            "parallel stack labels diverge from serial across chunk boundaries"
        );
        let vs = small.column("value").unwrap().values();
        let vl = large.column("value").unwrap().values();
        assert_eq!(
            &vl[..40_000 * 3],
            vs,
            "parallel stack value column prefix mismatch"
        );
    }

