    #[test]
    fn duplicated_single_utf8_matches_oracle_blackthrush() {
        // Differential harness (BlackThrush): the single-all-valid-Utf8-column
        // duplicate fast path must equal an independent exact-string oracle for
        // keep=First/Last/None. Seeded LCG, small alphabet to force dups.
        let mut state: u64 = 0xabcd_1234_5678_9f0e;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };
        for iter in 0..1200u32 {
            let n = (next() % 28) as usize + 1;
            let alphabet = (next() % 5) + 1; // 1..=5 distinct labels
            let keys: Vec<String> = (0..n)
                .map(|_| format!("k{:02}", next() % alphabet))
                .collect();
            let scalars: Vec<Scalar> = keys.iter().map(|k| Scalar::Utf8(k.clone())).collect();
            let df = DataFrame::from_dict(&["a"], vec![("a", scalars)]).unwrap();
            for keep in [
                DuplicateKeep::First,
                DuplicateKeep::Last,
                DuplicateKeep::None,
            ] {
                let got: Vec<bool> = df
                    .duplicated(Some(&["a".to_string()]), keep)
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect();
                let mut expected = vec![false; n];
                match keep {
                    DuplicateKeep::First => {
                        let mut seen = std::collections::HashSet::new();
                        for i in 0..n {
                            expected[i] = !seen.insert(keys[i].clone());
                        }
                    }
                    DuplicateKeep::Last => {
                        let mut seen = std::collections::HashSet::new();
                        for i in (0..n).rev() {
                            expected[i] = !seen.insert(keys[i].clone());
                        }
                    }
                    DuplicateKeep::None => {
                        let mut counts: std::collections::HashMap<String, u32> =
                            std::collections::HashMap::new();
                        for k in &keys {
                            *counts.entry(k.clone()).or_insert(0) += 1;
                        }
                        for i in 0..n {
                            expected[i] = counts[&keys[i]] > 1;
                        }
                    }
                }
                assert_eq!(got, expected, "iter={iter} keep={keep:?} keys={keys:?}");
            }
        }
    }

    #[test]
    fn duplicated_single_i64_matches_oracle_blackthrush() {
        // Differential harness (BlackThrush): the single-all-valid-Int64-column
        // duplicate fast path must equal an independent exact-value oracle for
        // keep=First/Last/None. Seeded LCG, small alphabet to force dups.
        let mut state: u64 = 0x0fed_cba9_8765_4321;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };
        for iter in 0..1500u32 {
            let n = (next() % 30) as usize + 1;
            let alphabet = (next() % 6) as i64 + 1; // 1..=6 distinct values
            let keys: Vec<i64> = (0..n)
                .map(|_| (next() as i64).rem_euclid(alphabet) - 2)
                .collect();
            let scalars: Vec<Scalar> = keys.iter().map(|&k| Scalar::Int64(k)).collect();
            let df = DataFrame::from_dict(&["a"], vec![("a", scalars)]).unwrap();
            for keep in [
                DuplicateKeep::First,
                DuplicateKeep::Last,
                DuplicateKeep::None,
            ] {
                let got: Vec<bool> = df
                    .duplicated(Some(&["a".to_string()]), keep)
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect();
                let mut expected = vec![false; n];
                match keep {
                    DuplicateKeep::First => {
                        let mut seen = std::collections::HashSet::new();
                        for i in 0..n {
                            expected[i] = !seen.insert(keys[i]);
                        }
                    }
                    DuplicateKeep::Last => {
                        let mut seen = std::collections::HashSet::new();
                        for i in (0..n).rev() {
                            expected[i] = !seen.insert(keys[i]);
                        }
                    }
                    DuplicateKeep::None => {
                        let mut counts: std::collections::HashMap<i64, u32> =
                            std::collections::HashMap::new();
                        for k in &keys {
                            *counts.entry(*k).or_insert(0) += 1;
                        }
                        for i in 0..n {
                            expected[i] = counts[&keys[i]] > 1;
                        }
                    }
                }
                assert_eq!(got, expected, "iter={iter} keep={keep:?} keys={keys:?}");
            }
        }
    }

    #[test]
    fn duplicated_single_f64_matches_oracle_blackthrush() {
        // Differential harness (BlackThrush): the single-Float64-column duplicate
        // fast path must equal an independent exact-bits oracle (missing/NaN form
        // one class) for keep=First/Last/None, including NaN and nulls. Seeded
        // LCG, small value alphabet to force dense duplicates, no rand, no mocks.
        let mut state: u64 = 0x1234_5678_9abc_def1;
        let mut next = || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (state >> 33) as u32
        };

        for iter in 0..1500u32 {
            let n = (next() % 30) as usize + 1;
            let mut scalars = Vec::with_capacity(n);
            // bits key per row for the oracle: Some(bits) present, None missing.
            let mut keys: Vec<Option<u64>> = Vec::with_capacity(n);
            for _ in 0..n {
                match next() % 8 {
                    0 => {
                        scalars.push(Scalar::Float64(f64::NAN));
                        keys.push(None);
                    }
                    1 => {
                        scalars.push(Scalar::Null(NullKind::Null));
                        keys.push(None);
                    }
                    other => {
                        // small set {-0.0, 0.0, 1.0, 2.0, 3.0, 4.0} to force dups.
                        let v = match other {
                            2 => 0.0_f64,
                            3 => -0.0_f64,
                            k => (k as f64) - 2.0,
                        };
                        scalars.push(Scalar::Float64(v));
                        keys.push(Some(v.to_bits()));
                    }
                }
            }
            let df = DataFrame::from_dict(&["a"], vec![("a", scalars)]).unwrap();

            for keep in [
                DuplicateKeep::First,
                DuplicateKeep::Last,
                DuplicateKeep::None,
            ] {
                let got: Vec<bool> = df
                    .duplicated(Some(&["a".to_string()]), keep)
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect();

                // Oracle.
                let mut expected = vec![false; n];
                match keep {
                    DuplicateKeep::First => {
                        let mut seen: std::collections::HashSet<Option<u64>> =
                            std::collections::HashSet::new();
                        for i in 0..n {
                            expected[i] = !seen.insert(keys[i]);
                        }
                    }
                    DuplicateKeep::Last => {
                        let mut seen: std::collections::HashSet<Option<u64>> =
                            std::collections::HashSet::new();
                        for i in (0..n).rev() {
                            expected[i] = !seen.insert(keys[i]);
                        }
                    }
                    DuplicateKeep::None => {
                        let mut counts: std::collections::HashMap<Option<u64>, u32> =
                            std::collections::HashMap::new();
                        for k in &keys {
                            *counts.entry(*k).or_insert(0) += 1;
                        }
                        for i in 0..n {
                            expected[i] = counts[&keys[i]] > 1;
                        }
                    }
                }
                assert_eq!(got, expected, "iter={iter} keep={keep:?} keys={keys:?}");
            }
        }
    }

    #[test]
    fn groupby_all_nan_group_sum_mean_match_pandas_dustysummit() {
        // pandas 2.2.3: groupby sum of an all-NaN-value group is 0.0 (NOT NaN);
        // mean of an all-NaN group is NaN. Groups sorted ascending by key.
        let df = DataFrame::from_dict(
            &["k", "v"],
            vec![
                (
                    "k",
                    vec![Scalar::Int64(1), Scalar::Int64(1), Scalar::Int64(2)],
                ),
                (
                    "v",
                    vec![
                        Scalar::Float64(f64::NAN),
                        Scalar::Float64(f64::NAN),
                        Scalar::Float64(5.0),
                    ],
                ),
            ],
        )
        .unwrap();
        let sums = df
            .groupby(&["k"])
            .unwrap()
            .sum()
            .unwrap()
            .column_as_series("v")
            .unwrap()
            .to_numpy();
        assert_eq!(sums.len(), 2, "two groups");
        assert_eq!(
            sums[0], 0.0,
            "all-NaN group sum should be 0.0, got {}",
            sums[0]
        );
        assert_eq!(sums[1], 5.0);
        let means = df
            .groupby(&["k"])
            .unwrap()
            .mean()
            .unwrap()
            .column_as_series("v")
            .unwrap()
            .to_numpy();
        assert!(
            means[0].is_nan(),
            "all-NaN group mean should be NaN, got {}",
            means[0]
        );
        assert_eq!(means[1], 5.0);
    }

    #[test]
    fn groupby_unsorted_keys_sorts_ascending_dustysummit() {
        // pandas default sort=True: groups sorted by key ascending regardless of
        // input order. keys [3,1,2,1,3], v [10,20,30,40,50] -> (1,60),(2,30),(3,60).
        let df = DataFrame::from_dict(
            &["k", "v"],
            vec![
                (
                    "k",
                    vec![
                        Scalar::Int64(3),
                        Scalar::Int64(1),
                        Scalar::Int64(2),
                        Scalar::Int64(1),
                        Scalar::Int64(3),
                    ],
                ),
                (
                    "v",
                    vec![
                        Scalar::Int64(10),
                        Scalar::Int64(20),
                        Scalar::Int64(30),
                        Scalar::Int64(40),
                        Scalar::Int64(50),
                    ],
                ),
            ],
        )
        .unwrap();
        let g = df.groupby(&["k"]).unwrap().sum().unwrap();
        let keys: Vec<i64> = g
            .index()
            .labels()
            .iter()
            .map(|l| match l {
                IndexLabel::Int64(v) => *v,
                other => panic!("key {other:?}"),
            })
            .collect();
        let vals = g.column_as_series("v").unwrap().to_numpy();
        assert_eq!(
            keys,
            vec![1, 2, 3],
            "groups must be sorted ascending by key"
        );
        assert_eq!(vals, vec![60.0, 30.0, 60.0]);
    }

