    #[test]
    fn dataframe_crosstab_dense_utf8_fast_path_1q4q4() {
        // Exercises the typed dense-Utf8 crosstab path with an ABSENT cell
        // (row "a" never pairs with col "y") and first-seen order "z","a"/"x","y"
        // to pin the str::cmp ascending sort (rows a<z, cols x<y) and the 0-fill.
        let idx: Vec<IndexLabel> = (0..5_i64).map(Into::into).collect();
        let index = Series::from_values(
            "row",
            idx.clone(),
            vec![
                Scalar::Utf8("z".into()),
                Scalar::Utf8("z".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("z".into()),
            ],
        )
        .unwrap();
        let columns = Series::from_values(
            "col",
            idx,
            vec![
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
                Scalar::Utf8("x".into()),
                Scalar::Utf8("x".into()),
                Scalar::Utf8("y".into()),
            ],
        )
        .unwrap();
        let ct = DataFrame::crosstab(&index, &columns).unwrap();
        assert_eq!(ct.column_order, vec!["x".to_string(), "y".to_string()]);
        assert_eq!(
            ct.index().labels(),
            &[IndexLabel::Utf8("a".into()), IndexLabel::Utf8("z".into())]
        );
        // row a: x=2 (rows 2,3), y=0 (absent). row z: x=1 (row0), y=2 (rows 1,4).
        assert_eq!(
            ct.columns["x"].values(),
            &[Scalar::Int64(2), Scalar::Int64(1)]
        );
        assert_eq!(
            ct.columns["y"].values(),
            &[Scalar::Int64(0), Scalar::Int64(2)]
        );
        // Index name propagated from the index Series.
        assert_eq!(ct.index().name(), Some("row"));
    }

