    #[test]
    fn series_resample_subdaily_typed_fast_path_emits_datetime64_labels() {
        let base = 1_577_836_800_000_000_000i64;
        let minute = 60_000_000_000i64;
        let s = Series::new(
            "x",
            Index::from_datetime64(vec![base, base + minute, base + 2 * minute]),
            Column::from_f64_values(vec![1.0, 2.0, 3.0]),
        )
        .unwrap();

        let result = s.resample("min").sum().unwrap();
        let mean = s.resample("min").mean().unwrap();

        assert_eq!(
            result.index().labels(),
            &[
                IndexLabel::Datetime64(base),
                IndexLabel::Datetime64(base + minute),
                IndexLabel::Datetime64(base + 2 * minute),
            ]
        );
        assert_eq!(
            result.values(),
            &[
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ]
        );
        assert_eq!(mean.index().labels(), result.index().labels());
        assert_eq!(mean.values(), result.values());
    }

