    #[test]
    fn series_resample_daily_and_weekly_fill_empty_bins_eov68() {
        // pandas resample emits a CONTIGUOUS bin range and fills dataless bins
        // (sum->0, mean/min/max->NaN, count->0). Verified vs live pandas 2.2.3.
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let f64s = |s: &Series| -> Vec<Option<f64>> {
            s.values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect()
        };

        // Daily with a 2-day gap: 01-01 .. 01-04 -> every day present.
        let d = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-01".into()),
                IndexLabel::Utf8("2024-01-04".into()),
            ],
            vec![Scalar::Float64(10.0), Scalar::Float64(40.0)],
        )
        .unwrap();
        let dsum = d.resample("D").sum().unwrap();
        assert_eq!(
            labels(&dsum),
            vec!["2024-01-01", "2024-01-02", "2024-01-03", "2024-01-04"]
        );
        assert_eq!(
            f64s(&dsum),
            vec![Some(10.0), Some(0.0), Some(0.0), Some(40.0)]
        );
        assert_eq!(
            f64s(&d.resample("D").mean().unwrap()),
            vec![Some(10.0), None, None, Some(40.0)]
        );
        assert_eq!(
            f64s(&d.resample("D").count().unwrap()),
            vec![Some(1.0), Some(0.0), Some(0.0), Some(1.0)]
        );

        // Weekly with two empty weeks between 01-03 (-> 01-07) and 01-22 (-> 01-28).
        let w = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-03".into()),
                IndexLabel::Utf8("2024-01-22".into()),
            ],
            vec![Scalar::Float64(1.0), Scalar::Float64(9.0)],
        )
        .unwrap();
        let wsum = w.resample("W").sum().unwrap();
        assert_eq!(
            labels(&wsum),
            vec!["2024-01-07", "2024-01-14", "2024-01-21", "2024-01-28"]
        );
        assert_eq!(
            f64s(&wsum),
            vec![Some(1.0), Some(0.0), Some(0.0), Some(9.0)]
        );
        assert_eq!(
            f64s(&w.resample("W").mean().unwrap()),
            vec![Some(1.0), None, None, Some(9.0)]
        );
    }

    #[test]
    fn series_resample_monthly_yearly_empty_bins_eov68() {
        // Monthly/quarterly/yearly resample fills dataless calendar buckets (sum->0,
        // mean->NaN), matching pandas' contiguous bucket range. Verified vs
        // live pandas 2.2.3:
        //   M gap (Jan/Apr) -> 2024-01-31:1, 2024-02-29:0, 2024-03-31:0, 2024-04-30:2
        //   Q gap (Q1/Q4) -> 2024-03-31:1, 2024-06-30:0, 2024-09-30:0, 2024-12-31:2
        //   Y gap (2020/2023) -> 2020-12-31:1, 2021-12-31:0, 2022-12-31:0, 2023-12-31:2
        //   2M gap -> 2024-01-31:1, 2024-03-31:2, 2024-05-31:3, ..., 2025-03-31:4
        //   2Q gap -> 2024-03-31:3, 2024-09-30:3, 2025-03-31:4
        //   2Y gap -> 2024-12-31:6, 2026-12-31:4
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let f64s = |s: &Series| -> Vec<Option<f64>> {
            s.values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect()
        };

        let m = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-15".into()),
                IndexLabel::Utf8("2024-04-20".into()),
            ],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();
        let msum = m.resample("M").sum().unwrap();
        assert_eq!(
            labels(&msum),
            vec!["2024-01-31", "2024-02-29", "2024-03-31", "2024-04-30"]
        );
        assert_eq!(
            f64s(&msum),
            vec![Some(1.0), Some(0.0), Some(0.0), Some(2.0)]
        );
        assert_eq!(
            f64s(&m.resample("M").mean().unwrap()),
            vec![Some(1.0), None, None, Some(2.0)]
        );

        let q = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-15".into()),
                IndexLabel::Utf8("2024-10-20".into()),
            ],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();
        let qsum = q.resample("Q").sum().unwrap();
        assert_eq!(
            labels(&qsum),
            vec!["2024-03-31", "2024-06-30", "2024-09-30", "2024-12-31"]
        );
        assert_eq!(
            f64s(&qsum),
            vec![Some(1.0), Some(0.0), Some(0.0), Some(2.0)]
        );
        assert_eq!(
            f64s(&q.resample("Q").mean().unwrap()),
            vec![Some(1.0), None, None, Some(2.0)]
        );

        let y = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2020-06-15".into()),
                IndexLabel::Utf8("2023-03-20".into()),
            ],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();
        let ysum = y.resample("Y").sum().unwrap();
        assert_eq!(
            labels(&ysum),
            vec!["2020-12-31", "2021-12-31", "2022-12-31", "2023-12-31"]
        );
        assert_eq!(
            f64s(&ysum),
            vec![Some(1.0), Some(0.0), Some(0.0), Some(2.0)]
        );

        let multiplied = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-15".into()),
                IndexLabel::Utf8("2024-02-20".into()),
                IndexLabel::Utf8("2024-05-01".into()),
                IndexLabel::Utf8("2025-02-01".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();
        let two_month = multiplied.resample("2M").sum().unwrap();
        assert_eq!(
            labels(&two_month),
            vec![
                "2024-01-31",
                "2024-03-31",
                "2024-05-31",
                "2024-07-31",
                "2024-09-30",
                "2024-11-30",
                "2025-01-31",
                "2025-03-31"
            ]
        );
        assert_eq!(
            f64s(&two_month),
            vec![
                Some(1.0),
                Some(2.0),
                Some(3.0),
                Some(0.0),
                Some(0.0),
                Some(0.0),
                Some(0.0),
                Some(4.0)
            ]
        );

        let two_quarter = multiplied.resample("2Q").sum().unwrap();
        assert_eq!(
            labels(&two_quarter),
            vec!["2024-03-31", "2024-09-30", "2025-03-31"]
        );
        assert_eq!(f64s(&two_quarter), vec![Some(3.0), Some(3.0), Some(4.0)]);

        let two_year = multiplied.resample("2Y").sum().unwrap();
        assert_eq!(labels(&two_year), vec!["2024-12-31", "2026-12-31"]);
        assert_eq!(f64s(&two_year), vec![Some(6.0), Some(4.0)]);
    }

    #[test]
    fn series_resample_nday_multiple_empty_bins_eov68() {
        // N-day multiples (2D/3D) anchor bins at the first label and step by
        // `mult` days, filling dataless bins (sum->0, mean->NaN). Verified vs
        // live pandas 2.2.3 for index 2024-01-01 / 2024-01-08:
        //   2D sum -> 01-01:10, 01-03:0, 01-05:0, 01-07:80
        //   3D sum -> 01-01:10, 01-04:0, 01-07:80
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-01".into()),
                IndexLabel::Utf8("2024-01-08".into()),
            ],
            vec![Scalar::Float64(10.0), Scalar::Float64(80.0)],
        )
        .unwrap();
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let f64s = |s: &Series| -> Vec<Option<f64>> {
            s.values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect()
        };

        let d2 = s.resample("2D").sum().unwrap();
        assert_eq!(
            labels(&d2),
            vec!["2024-01-01", "2024-01-03", "2024-01-05", "2024-01-07"]
        );
        assert_eq!(
            f64s(&d2),
            vec![Some(10.0), Some(0.0), Some(0.0), Some(80.0)]
        );
        assert_eq!(
            f64s(&s.resample("2D").mean().unwrap()),
            vec![Some(10.0), None, None, Some(80.0)]
        );

        let d3 = s.resample("3D").sum().unwrap();
        assert_eq!(labels(&d3), vec!["2024-01-01", "2024-01-04", "2024-01-07"]);
        assert_eq!(f64s(&d3), vec![Some(10.0), Some(0.0), Some(80.0)]);
    }

    #[test]
    fn series_resample_business_day_b_eov68() {
        // pandas resample('B') = one bin per weekday; a weekend timestamp rolls
        // BACK to the preceding Friday; dataless business days fill (sum->0,
        // mean->NaN). Verified vs live pandas 2.2.3.
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let f64s = |s: &Series| -> Vec<Option<f64>> {
            s.values()
                .iter()
                .map(|v| {
                    if v.is_missing() {
                        None
                    } else {
                        v.to_f64().ok()
                    }
                })
                .collect()
        };

        // Wed 01-03, Tue 01-09, Fri 01-12 -> every business day 01-03..01-12,
        // weekends (06/07) skipped, dataless days filled.
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-03".into()),
                IndexLabel::Utf8("2024-01-09".into()),
                IndexLabel::Utf8("2024-01-12".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let sum = s.resample("B").sum().unwrap();
        assert_eq!(
            labels(&sum),
            vec![
                "2024-01-03",
                "2024-01-04",
                "2024-01-05",
                "2024-01-08",
                "2024-01-09",
                "2024-01-10",
                "2024-01-11",
                "2024-01-12"
            ]
        );
        assert_eq!(
            f64s(&sum),
            vec![
                Some(1.0),
                Some(0.0),
                Some(0.0),
                Some(0.0),
                Some(2.0),
                Some(0.0),
                Some(0.0),
                Some(3.0)
            ]
        );

        // Weekend data point rolls back to Friday: Sat 01-06 -> 01-05 bin.
        let s2 = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-06".into()),
                IndexLabel::Utf8("2024-01-09".into()),
            ],
            vec![Scalar::Float64(5.0), Scalar::Float64(7.0)],
        )
        .unwrap();
        let sum2 = s2.resample("B").sum().unwrap();
        assert_eq!(
            labels(&sum2),
            vec!["2024-01-05", "2024-01-08", "2024-01-09"]
        );
        assert_eq!(f64s(&sum2), vec![Some(5.0), Some(0.0), Some(7.0)]);
    }

    #[test]
    fn series_resample_multi_week_2w_3w_eov68() {
        // pandas multi-week resample anchors bin ends on Sundays `7*mult` days
        // apart from the first week-ending Sunday, filling dataless bins.
        // Verified vs live pandas 2.2.3 (idx 2024-01-03,05,10,15,22 / vals 1..5):
        //   2W sum -> {01-07:3, 01-21:7, 02-04:5}
        //   3W sum -> {01-07:3, 01-28:12}
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-03".into()),
                IndexLabel::Utf8("2024-01-05".into()),
                IndexLabel::Utf8("2024-01-10".into()),
                IndexLabel::Utf8("2024-01-15".into()),
                IndexLabel::Utf8("2024-01-22".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let vals =
            |s: &Series| -> Vec<f64> { s.values().iter().map(|v| v.to_f64().unwrap()).collect() };

        let s2 = s.resample("2W").sum().unwrap();
        assert_eq!(labels(&s2), vec!["2024-01-07", "2024-01-21", "2024-02-04"]);
        assert_eq!(vals(&s2), vec![3.0, 7.0, 5.0]);

        let s3 = s.resample("3W").sum().unwrap();
        assert_eq!(labels(&s3), vec!["2024-01-07", "2024-01-28"]);
        assert_eq!(vals(&s3), vec![3.0, 12.0]);
    }

    #[test]
    fn series_resample_multi_week_gappy_empty_bins_eov68() {
        // Multi-week (2W) over a gappy span must synthesize a CONTIGUOUS run of
        // Sunday-anchored bin ends (7*mult apart) and fill dataless bins:
        // 0.0 for sum, NaN for mean. Verified vs live pandas 2.2.3 for
        // index 2024-02-01 / 2024-03-20:
        //   2W sum  -> 02-04:10, 02-18:0, 03-03:0, 03-17:0, 03-31:20
        //   2W mean -> 02-04:10, (02-18/03-03/03-17 NaN), 03-31:20
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-02-01".into()),
                IndexLabel::Utf8("2024-03-20".into()),
            ],
            vec![Scalar::Float64(10.0), Scalar::Float64(20.0)],
        )
        .unwrap();
        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };

        let sum = s.resample("2W").sum().unwrap();
        assert_eq!(
            labels(&sum),
            vec![
                "2024-02-04",
                "2024-02-18",
                "2024-03-03",
                "2024-03-17",
                "2024-03-31"
            ]
        );
        assert_eq!(
            sum.values()
                .iter()
                .map(|v| v.to_f64().unwrap())
                .collect::<Vec<_>>(),
            vec![10.0, 0.0, 0.0, 0.0, 20.0]
        );

        let mean = s.resample("2W").mean().unwrap();
        let mean_vals: Vec<Option<f64>> = mean
            .values()
            .iter()
            .map(|v| {
                if v.is_missing() {
                    None
                } else {
                    Some(v.to_f64().unwrap())
                }
            })
            .collect();
        assert_eq!(mean_vals, vec![Some(10.0), None, None, None, Some(20.0)]);
    }

    #[test]
    fn series_resample_weekly_w_sun_rj4fn() {
        // pandas `resample('W')` is W-SUN: each label maps to the week-ending
        // SUNDAY (right edge). Verified vs live pandas 2.2.3 over contiguous
        // weeks (fp-frame, like every resample freq, does not synthesize empty
        // bins, so the fixture leaves no gap week):
        //   idx 2024-01-03,05,10,15,22 / vals 1..5 ->
        //   sum {01-07:3, 01-14:3, 01-21:4, 01-28:5}
        let s = Series::from_values(
            "x",
            vec![
                IndexLabel::Utf8("2024-01-03".into()),
                IndexLabel::Utf8("2024-01-05".into()),
                IndexLabel::Utf8("2024-01-10".into()),
                IndexLabel::Utf8("2024-01-15".into()),
                IndexLabel::Utf8("2024-01-22".into()),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        let labels = |s: &Series| -> Vec<String> {
            s.index()
                .labels()
                .iter()
                .map(|l| match l {
                    IndexLabel::Utf8(d) => d.clone(),
                    other => format!("{other:?}"),
                })
                .collect()
        };
        let sum = s.resample("W").sum().unwrap();
        assert_eq!(
            labels(&sum),
            vec!["2024-01-07", "2024-01-14", "2024-01-21", "2024-01-28"]
        );
        let sum_vals: Vec<f64> = sum.values().iter().map(|v| v.to_f64().unwrap()).collect();
        assert_eq!(sum_vals, vec![3.0, 3.0, 4.0, 5.0]);

        let mean_vals: Vec<f64> = s
            .resample("W")
            .mean()
            .unwrap()
            .values()
            .iter()
            .map(|v| v.to_f64().unwrap())
            .collect();
        assert_eq!(mean_vals, vec![1.5, 3.0, 4.0, 5.0]);

        let count_vals: Vec<f64> = s
            .resample("W")
            .count()
            .unwrap()
            .values()
            .iter()
            .map(|v| v.to_f64().unwrap())
            .collect();
        assert_eq!(count_vals, vec![2.0, 1.0, 1.0, 1.0]);
    }

    #[test]
    fn series_rolling_min_periods_above_window_errors() {
        // Per br-frankenpandas-7c962: pandas raises ValueError when
        // min_periods > window. Was silently producing all-NaN.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let err = s.rolling(3, Some(5)).mean().unwrap_err();
        assert!(matches!(&err,
            FrameError::CompatibilityRejected(msg)
                if msg.contains("min_periods 5") && msg.contains("window 3")));
    }

    #[test]
    fn series_rolling_min_periods_above_window_errors_for_all_aggs() {
        // Validation should propagate through every Rolling aggregator.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into()],
            vec![Scalar::Float64(1.0), Scalar::Float64(2.0)],
        )
        .unwrap();
        let mp_above = s.rolling(2, Some(10));
        assert!(matches!(mp_above.mean().unwrap_err(),
            FrameError::CompatibilityRejected(msg) if msg.contains("min_periods")));
        assert!(matches!(s.rolling(2, Some(10)).count().unwrap_err(),
            FrameError::CompatibilityRejected(msg) if msg.contains("min_periods")));
        assert!(matches!(s.rolling(2, Some(10)).sum().unwrap_err(),
            FrameError::CompatibilityRejected(msg) if msg.contains("min_periods")));
        assert!(matches!(s.rolling(2, Some(10)).std().unwrap_err(),
            FrameError::CompatibilityRejected(msg) if msg.contains("min_periods")));
    }

    #[test]
    fn series_rolling_min_periods_equal_window_is_valid() {
        // min_periods == window is the boundary; pandas accepts it.
        // (This is also the default when min_periods=None.)
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let result = s.rolling(2, Some(2)).mean().unwrap();
        // First entry NaN (only one value seen); rest are window means.
        let vals = result.column().values();
        assert!(matches!(vals[0], Scalar::Null(_) | Scalar::Float64(_)));
        assert!(matches!(vals[1], Scalar::Float64(v) if v == 1.5));
        assert!(matches!(vals[2], Scalar::Float64(v) if v == 2.5));
    }

    #[test]
    fn series_rolling_min_periods_below_window_is_valid_regression_guard() {
        // min_periods < window is also valid (pandas accepts). Just
        // verify the call succeeds (no Err) — exact value semantics
        // depend on rolling-window convention.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .unwrap();
        // window=3, min_periods=1 — should NOT error (was previously
        // valid, must remain so).
        let result = s.rolling(3, Some(1)).mean();
        assert!(result.is_ok());
        assert_eq!(result.unwrap().len(), 4);
    }

