    #[test]
    fn series_drop_rejects_missing_labels_dopex() {
        // Per br-frankenpandas-dopex: pandas raises KeyError when a
        // requested label isn't in the index. Was silently no-op'ing.
        let s = Series::from_values(
            "v",
            vec!["a".into(), "b".into(), "c".into()],
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();
        let err = s
            .drop(&["zzz".into()])
            .expect_err("missing label must reject");
        match err {
            FrameError::CompatibilityRejected(msg) => {
                assert!(msg.contains("not found"));
            }
            other => panic!("expected CompatibilityRejected, got {other:?}"),
        }
        // Valid drops still succeed.
        let out = s.drop(&["b".into()]).unwrap();
        assert_eq!(out.len(), 2);
    }

    #[test]
    fn series_rolling_max_prod_empty_window_returns_nan_5m7r1() {
        // Per br-frankenpandas-5m7r1: with min_periods=0 and an all-NaN
        // window, max should return NaN (not -∞) and prod should return
        // NaN (not the multiplicative identity 1.0). Pandas-faithful.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(f64::NAN),
                Scalar::Float64(f64::NAN),
                Scalar::Float64(f64::NAN),
            ],
        )
        .unwrap();
        let m = s.rolling(2, Some(0)).max().unwrap();
        for v in m.column().values() {
            assert!(v.is_missing(), "max should be NaN, got {v:?}");
        }
        let p = s.rolling(2, Some(0)).prod().unwrap();
        for v in p.column().values() {
            assert!(v.is_missing(), "prod should be NaN, got {v:?}");
        }
    }

    #[test]
    fn series_rolling_first_last_no_panic_on_empty_window_dvxj7() {
        // Per br-frankenpandas-dvxj7: rolling first/last on an all-missing
        // window with min_periods=0 previously panicked via nums[0] /
        // nums.last() on an empty Vec. Now bails to NaN.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(f64::NAN),
                Scalar::Float64(f64::NAN),
                Scalar::Float64(f64::NAN),
            ],
        )
        .unwrap();
        let f = s.rolling(2, Some(0)).first().unwrap();
        for v in f.column().values() {
            assert!(v.is_missing());
        }
        let l = s.rolling(2, Some(0)).last().unwrap();
        for v in l.column().values() {
            assert!(v.is_missing());
        }
    }

    #[test]
    fn series_ewm_sum_does_not_panic_on_utf8_ntoqd() {
        // Per br-frankenpandas-ntoqd: ewm.sum's guard used
        // is_ok_and(f64::is_nan), which let Utf8 inputs slip through
        // to the unwrap below, panicking. A Utf8 row is treated as a
        // missing observation; per pandas' ignore_na=False gap semantics
        // (issue #19) it decays the running sum and emits the decayed
        // carry instead of Null.
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Utf8("oops".to_owned()),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        let result = s.ewm(None, Some(0.5)).sum().unwrap();
        let vals = result.column().values();
        // First numeric → emits Float64
        assert!(matches!(vals[0], Scalar::Float64(_)));
        // Utf8 row → gap: decayed carry 1 * 0.5 = 0.5 (no panic).
        assert_eq!(vals[1], Scalar::Float64(0.5));
        // Numeric resumes, folding the decayed sum: 3 + 0.5*0.5 = 3.25.
        assert_eq!(vals[2], Scalar::Float64(3.25));
    }

    #[test]
    fn series_ewm_alpha_at_one_is_valid_regression_guard() {
        // alpha = 1.0 is the max valid value (matches pandas).
        let s = Series::from_values(
            "x",
            vec![0_i64.into(), 1_i64.into(), 2_i64.into()],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ],
        )
        .unwrap();
        // Should not error.
        let result = s.ewm(None, Some(1.0)).mean().unwrap();
        // alpha=1 → output equals input (no smoothing).
        let vals = result.column().values();
        assert!(matches!(vals[0], Scalar::Float64(v) if v == 1.0));
        assert!(matches!(vals[1], Scalar::Float64(v) if v == 2.0));
        assert!(matches!(vals[2], Scalar::Float64(v) if v == 3.0));
    }

    #[test]
    fn dataframe_groupby_value_counts_uses_o_n_hashmap_per_group() {
        // Per br-frankenpandas-c0c48: O(n²) → O(n) per-group regression
        // guard. 2 groups × 2500 rows each × 50 unique values per group.
        let n: i64 = 5_000;
        let mut cols = BTreeMap::new();
        // Group key splits by halves (first 2500 rows = g0, last 2500 = g1)
        // so the value cycle (i % 50) is fully exercised within each group.
        let group_vals: Vec<Scalar> = (0..n)
            .map(|i| Scalar::Utf8(format!("g{}", i / 2500)))
            .collect();
        // Value cycles 0..49 → 50 unique per group.
        let value_vals: Vec<Scalar> = (0..n).map(|i| Scalar::Int64(i % 50)).collect();
        cols.insert("group".to_owned(), Column::from_values(group_vals).unwrap());
        cols.insert("val".to_owned(), Column::from_values(value_vals).unwrap());
        let df = DataFrame::new_with_column_order(
            Index::new((0..n).map(IndexLabel::Int64).collect()),
            cols,
            vec!["group".to_owned(), "val".to_owned()],
        )
        .unwrap();
        let gb = df.groupby(&["group"]).unwrap();
        let result = gb.value_counts().unwrap();
        // Expected: 2 groups × 50 unique values = 100 rows.
        assert_eq!(result.len(), 100);
    }

    #[test]
    fn dataframe_groupby_value_counts_preserves_descending_count_sort() {
        // Per br-frankenpandas-c0c48: stable sort by count descending
        // must be preserved across the HashMap-based fix.
        // Group "g0": values [1, 1, 2] → counts {1:2, 2:1}
        // Group "g1": values [3, 3, 3] → counts {3:3}
        let mut cols = BTreeMap::new();
        cols.insert(
            "group".to_owned(),
            Column::from_values(vec![
                Scalar::Utf8("g0".into()),
                Scalar::Utf8("g0".into()),
                Scalar::Utf8("g0".into()),
                Scalar::Utf8("g1".into()),
                Scalar::Utf8("g1".into()),
                Scalar::Utf8("g1".into()),
            ])
            .unwrap(),
        );
        cols.insert(
            "val".to_owned(),
            Column::from_values(vec![
                Scalar::Int64(1),
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Int64(3),
                Scalar::Int64(3),
            ])
            .unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::new((0..6_i64).map(IndexLabel::Int64).collect()),
            cols,
            vec!["group".to_owned(), "val".to_owned()],
        )
        .unwrap();
        let gb = df.groupby(&["group"]).unwrap();
        let result = gb.value_counts().unwrap();
        // 3 rows total (g0:1, g0:2, g1:3).
        assert_eq!(result.len(), 3);
        // Counts: g0:1 has count 2; g0:2 has count 1; g1:3 has count 3.
        // Descending sort within group → g0 ordered (1:2, 2:1).
        // Cross-group ordering is preserved by group enumeration.
        // We just verify total count sum equals 6.
        let count_col = &result.columns["count"];
        let total: i64 = count_col
            .values()
            .iter()
            .filter_map(|v| {
                if let Scalar::Int64(n) = v {
                    Some(*n)
                } else {
                    None
                }
            })
            .sum();
        assert_eq!(total, 6);
    }

    #[test]
    fn dataframe_value_counts_hashmap_perf_regression_guard() {
        // Per br-frankenpandas-62849: O(n²) → O(n) regression guard.
        // 5K rows × 2 cols, ~500 unique combinations.
        let n: i64 = 5_000;
        let mut cols = BTreeMap::new();
        // Use independent index axes so a=i%50 and b=(i/50)%10 give
        // independent cycles; lcm(50,10) gives 500 unique pairs.
        let a_vals: Vec<Scalar> = (0..n).map(|i| Scalar::Int64(i % 50)).collect();
        let b_vals: Vec<Scalar> = (0..n).map(|i| Scalar::Int64((i / 50) % 10)).collect();
        cols.insert("a".to_owned(), Column::from_values(a_vals).unwrap());
        cols.insert("b".to_owned(), Column::from_values(b_vals).unwrap());
        let df = DataFrame::new_with_column_order(
            Index::new((0..n).map(IndexLabel::Int64).collect()),
            cols,
            vec!["a".to_owned(), "b".to_owned()],
        )
        .unwrap();
        let result = df.value_counts().unwrap();
        // 50 × 10 = 500 distinct combinations expected (since gcd issues
        // would still produce most combinations; for i % 50 and i % 10
        // independently, we get 500 unique pairs as i ranges over 5000).
        assert_eq!(result.len(), 500);
        // Every combination appears n / 500 == 10 times.
        for v in result.column().values() {
            assert_eq!(*v, Scalar::Int64(10));
        }
    }

    #[test]
    fn dataframe_value_counts_preserves_count_descending_sort() {
        // Per br-frankenpandas-62849: stable sort by count descending
        // must be preserved across the HashMap-based fix.
        // Input: a=[1,1,2,2,2,3], b=[10,10,20,20,20,30]
        // Expected: (2,20)→3, (1,10)→2, (3,30)→1
        let mut cols = BTreeMap::new();
        cols.insert(
            "a".to_owned(),
            Column::from_values(vec![
                Scalar::Int64(1),
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(3),
            ])
            .unwrap(),
        );
        cols.insert(
            "b".to_owned(),
            Column::from_values(vec![
                Scalar::Int64(10),
                Scalar::Int64(10),
                Scalar::Int64(20),
                Scalar::Int64(20),
                Scalar::Int64(20),
                Scalar::Int64(30),
            ])
            .unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::new((0..6_i64).map(IndexLabel::Int64).collect()),
            cols,
            vec!["a".to_owned(), "b".to_owned()],
        )
        .unwrap();
        let result = df.value_counts().unwrap();
        assert_eq!(result.len(), 3);
        // Sorted descending by count.
        assert_eq!(result.column().values()[0], Scalar::Int64(3));
        assert_eq!(result.column().values()[1], Scalar::Int64(2));
        assert_eq!(result.column().values()[2], Scalar::Int64(1));
    }

    #[test]
    fn dataframe_nunique_uses_o_n_hashmap_per_column() {
        // Per br-frankenpandas-6ce89: regression guard for the O(n²) →
        // O(n) per-column fix. 5K rows × 3 cols, each column dtype
        // homogeneous, ~500 unique values each. Old impl: ~12.5M
        // comparisons per col × 3 = 37.5M. New: ~15K hash ops.
        let n: i64 = 5_000;
        let mut cols = BTreeMap::new();
        let int_vals: Vec<Scalar> = (0..n).map(|i| Scalar::Int64(i % 500)).collect();
        let float_vals: Vec<Scalar> = (0..n).map(|i| Scalar::Float64((i % 500) as f64)).collect();
        let utf8_vals: Vec<Scalar> = (0..n)
            .map(|i| Scalar::Utf8(format!("v{}", i % 500)))
            .collect();
        cols.insert("ints".to_owned(), Column::from_values(int_vals).unwrap());
        cols.insert(
            "floats".to_owned(),
            Column::from_values(float_vals).unwrap(),
        );
        cols.insert(
            "strings".to_owned(),
            Column::from_values(utf8_vals).unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::new((0..n).map(IndexLabel::Int64).collect()),
            cols,
            vec!["ints".to_owned(), "floats".to_owned(), "strings".to_owned()],
        )
        .unwrap();
        let result = df.nunique().unwrap();
        // Each column has 500 unique values.
        assert_eq!(result.len(), 3);
        for v in result.column().values() {
            assert_eq!(*v, Scalar::Int64(500));
        }
    }

    #[test]
    fn dataframe_nunique_with_nulls_dropna_false() {
        // dropna=false: null values count as one bucket per column.
        let mut cols = BTreeMap::new();
        cols.insert(
            "x".to_owned(),
            Column::from_values(vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN),
            ])
            .unwrap(),
        );
        let df = DataFrame::new_with_column_order(
            Index::new((0..5_i64).map(IndexLabel::Int64).collect()),
            cols,
            vec!["x".to_owned()],
        )
        .unwrap();
        let result = df.nunique_with_dropna(false).unwrap();
        // Distinct: {1, 2, Null} = 3 buckets.
        assert_eq!(result.column().values()[0], Scalar::Int64(3));

        let result_dropna = df.nunique_with_dropna(true).unwrap();
        // Distinct non-null: {1, 2} = 2.
        assert_eq!(result_dropna.column().values()[0], Scalar::Int64(2));
    }

