    #[test]
    fn series_nsmallest_keep_all_utf8() {
        // Per br-frankenpandas-9978d: 'all' keep also works on Utf8.
        // Input: ['c','a','b','a'] with n=1, keep='all' should return
        // both 'a' values (tied for smallest).
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("c".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
            ],
        )
        .unwrap();
        let result = s.nsmallest_keep(1, "all").unwrap();
        // Two 'a' values tied for smallest with keep='all'.
        assert_eq!(result.len(), 2);
        for v in result.column().values() {
            assert_eq!(*v, Scalar::Utf8("a".into()));
        }
    }

    #[test]
    fn series_idxmin_idxmax_utf8_lexicographic() {
        // Per br-frankenpandas-7db78: pandas supports idxmin/idxmax on
        // Utf8, returning the label of the lex-min/max element.
        let s = Series::from_values(
            "x",
            vec![10_i64.into(), 20_i64.into(), 30_i64.into()],
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert_eq!(s.idxmin().unwrap(), IndexLabel::Int64(20));
        assert_eq!(s.idxmax().unwrap(), IndexLabel::Int64(30));
    }

    #[test]
    fn series_idxmin_utf8_first_occurrence_tie_breaking() {
        // Same first-occurrence semantics as the numeric path. For
        // ['b', 'a', 'a', 'c'], idxmin should return label of FIRST 'a'.
        let s = Series::from_values(
            "x",
            vec![10_i64.into(), 20_i64.into(), 30_i64.into(), 40_i64.into()],
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert_eq!(s.idxmin().unwrap(), IndexLabel::Int64(20));
    }

    #[test]
    fn series_idxmin_utf8_skips_nulls() {
        // is_missing values should be skipped.
        let s = Series::from_values(
            "x",
            vec![10_i64.into(), 20_i64.into(), 30_i64.into()],
            vec![
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert_eq!(s.idxmin().unwrap(), IndexLabel::Int64(20));
        assert_eq!(s.idxmax().unwrap(), IndexLabel::Int64(30));
    }

    #[test]
    fn series_idxmin_utf8_all_null_returns_err() {
        // Matches the existing numeric path: all-null returns Err.
        let s = Series::from_values(
            "x",
            vec![10_i64.into(), 20_i64.into()],
            vec![Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)],
        )
        .unwrap();
        // (NB: declared dtype on a series of all-Null is Null, not Utf8 —
        // so this exercises the existing all-null Err path. Keeping the
        // test for documentation completeness.)
        assert!(s.idxmin().is_err() || s.idxmax().is_err());
    }

    #[test]
    fn series_idxmin_utf8_metamorphic_consistency_with_min() {
        // Per br-frankenpandas-7db78: metamorphic property —
        // s.values()[position_of(s.idxmin())] == s.min()
        let s = Series::from_values(
            "x",
            vec![10_i64.into(), 20_i64.into(), 30_i64.into(), 40_i64.into()],
            vec![
                Scalar::Utf8("dog".into()),
                Scalar::Utf8("apple".into()),
                Scalar::Utf8("banana".into()),
                Scalar::Utf8("cherry".into()),
            ],
        )
        .unwrap();
        let idxmin_label = s.idxmin().unwrap();
        // Find the position of idxmin_label in the index.
        let pos = s
            .index()
            .labels()
            .iter()
            .position(|l| *l == idxmin_label)
            .unwrap();
        let val_at_idxmin = s.column().values()[pos].clone();
        assert_eq!(val_at_idxmin, s.min().unwrap());
        // And it should be "apple" (lex min).
        assert_eq!(val_at_idxmin, Scalar::Utf8("apple".into()));
    }

    #[test]
    fn series_min_max_utf8_lexicographic() {
        // Per br-frankenpandas-83c2a: pandas supports min/max on Utf8
        // lexicographically.
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert_eq!(s.min().unwrap(), Scalar::Utf8("a".into()));
        assert_eq!(s.max().unwrap(), Scalar::Utf8("c".into()));
    }

    #[test]
    fn series_min_max_utf8_skips_nulls() {
        // is_missing values should be skipped in the lexicographic scan.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Null(NullKind::NaN),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert_eq!(s.min().unwrap(), Scalar::Utf8("a".into()));
        assert_eq!(s.max().unwrap(), Scalar::Utf8("c".into()));
    }

    #[test]
    fn series_min_max_utf8_all_null_returns_nan() {
        // All-null Utf8 series: best stays None → Float64(NaN) sentinel
        // (matching the existing all-null behavior for Int64/Bool/Float64).
        let s = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Null(NullKind::NaN), Scalar::Null(NullKind::NaN)],
        )
        .unwrap();
        let min_val = s.min().unwrap();
        let max_val = s.max().unwrap();
        assert!(matches!(min_val, Scalar::Float64(v) if v.is_nan()));
        assert!(matches!(max_val, Scalar::Float64(v) if v.is_nan()));
    }

    #[test]
    fn series_cummax_last_equals_max_metamorphic_utf8() {
        // Per br-frankenpandas-83c2a: the metamorphic property that
        // surfaced this fix. cummax(s)[-1] == max(s) on a Utf8 series.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("dog".into()),
                Scalar::Utf8("apple".into()),
                Scalar::Utf8("banana".into()),
                Scalar::Utf8("cherry".into()),
            ],
        )
        .unwrap();
        let cm = s.cummax().unwrap();
        let cm_last = cm.column().values().last().unwrap().clone();
        let max = s.max().unwrap();
        assert_eq!(cm_last, max);
        // Sanity: max should be "dog" (lex max of these strings —
        // "dog" > "cherry" > "banana" > "apple").
        assert_eq!(max, Scalar::Utf8("dog".into()));
    }

    #[test]
    fn series_cummax_utf8_lexicographic() {
        // Per br-frankenpandas-c4898: pandas cummax on Utf8 series.
        // Input: ['b', 'a', 'c'] → ['b', 'b', 'c'] (running max
        // lexicographically).
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("b".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        let out = s.cummax().unwrap();
        assert_eq!(
            out.column().values(),
            &[
                Scalar::Utf8("b".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("c".into()),
            ]
        );
    }

