    #[test]
    fn series_mode_handles_many_unique_fast() {
        // Per br-frankenpandas-cec8f: O(n) HashMap fast path. 5K distinct
        // Int64 values; old impl would do ~12.5M comparisons.
        let n: i64 = 5_000;
        let labels: Vec<IndexLabel> = (0..n).map(IndexLabel::Int64).collect();
        let values: Vec<Scalar> = (0..n).map(Scalar::Int64).collect();
        let s = Series::from_values("x", labels, values).unwrap();

        let modes = s.mode().unwrap();
        // Every value appears exactly once → all are modes; len == n.
        assert_eq!(modes.len() as i64, n);
    }

    #[test]
    fn series_mode_returns_single_most_frequent() {
        // Input: [1, 2, 2, 3, 2, 1] → mode is [2] (count 3).
        let s = Series::from_values(
            "x",
            (0..6_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Int64(2),
                Scalar::Int64(1),
            ],
        )
        .unwrap();
        let modes = s.mode().unwrap();
        assert_eq!(modes.len(), 1);
        assert_eq!(modes.column().values()[0], Scalar::Int64(2));
    }

    #[test]
    fn series_mode_returns_all_values_for_uniform_input() {
        // All values appear once → all are modes (sorted by scalar_key_cmp).
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Int64(3), Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        let modes = s.mode().unwrap();
        assert_eq!(modes.len(), 3);
        // Sorted by scalar_key_cmp (numeric ascending).
        assert_eq!(modes.column().values()[0], Scalar::Int64(1));
        assert_eq!(modes.column().values()[1], Scalar::Int64(2));
        assert_eq!(modes.column().values()[2], Scalar::Int64(3));
    }

    #[test]
    fn series_mode_with_ties_returns_all_tied_values() {
        // Input: [1, 1, 2, 2, 3] → mode is [1, 2] (count 2 each).
        let s = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(3),
            ],
        )
        .unwrap();
        let modes = s.mode().unwrap();
        assert_eq!(modes.len(), 2);
        // Sorted ascending.
        assert_eq!(modes.column().values()[0], Scalar::Int64(1));
        assert_eq!(modes.column().values()[1], Scalar::Int64(2));
    }

    #[test]
    fn series_mode_handles_nulls_with_dropna_false() {
        // dropna=false: Null counts as a value; if it's the most
        // frequent, it's the mode.
        let s = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Int64(2),
            ],
        )
        .unwrap();
        let modes = s.mode_with_dropna(false).unwrap();
        assert_eq!(modes.len(), 1);
        // Mode is the null value (count 3).
        assert!(modes.column().values()[0].is_missing());
    }

    #[test]
    fn series_is_monotonic_increasing_works_on_utf8() {
        // Per br-frankenpandas-526a2: previously returned false for sorted
        // Utf8 because to_f64 failed on strings. Now uses semantic_le.
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert!(s.is_monotonic_increasing());
    }

    #[test]
    fn series_is_monotonic_increasing_works_on_bool() {
        // Bool ordering: false < true (per derived Ord). [false, true]
        // should be increasing.
        let s = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Bool(false), Scalar::Bool(true)],
        )
        .unwrap();
        assert!(s.is_monotonic_increasing());

        // [true, false] is NOT increasing.
        let s2 = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Bool(true), Scalar::Bool(false)],
        )
        .unwrap();
        assert!(!s2.is_monotonic_increasing());
    }

    #[test]
    fn series_is_monotonic_increasing_int64_regression_guard() {
        // Regression guard: numeric path (was already correct) must
        // remain green after the semantic_le refactor.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(2),
                Scalar::Int64(5),
            ],
        )
        .unwrap();
        // Non-strict: equal adjacent values still count as monotonic.
        assert!(s.is_monotonic_increasing());

        let s_unsorted = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Int64(1), Scalar::Int64(3), Scalar::Int64(2)],
        )
        .unwrap();
        assert!(!s_unsorted.is_monotonic_increasing());
    }

    #[test]
    fn series_is_monotonic_int64_typed_fast_path_z53ed() {
        let make = |vals: Vec<i64>| {
            Series::from_values(
                "x",
                (0..vals.len() as i64)
                    .map(IndexLabel::Int64)
                    .collect::<Vec<_>>(),
                vals.iter().copied().map(Scalar::Int64).collect::<Vec<_>>(),
            )
            .unwrap()
        };

        // The typed Int64 fast path must actually be exercised.
        let asc = make(vec![1, 2, 2, 5]);
        assert!(
            asc.column.as_i64_slice().is_some(),
            "test must exercise the as_i64_slice fast path"
        );
        assert!(asc.is_monotonic_increasing());
        assert!(!asc.is_monotonic_decreasing());

        let desc = make(vec![9, 5, 5, -3]);
        assert!(!desc.is_monotonic_increasing());
        assert!(desc.is_monotonic_decreasing());

        let unsorted = make(vec![1, 3, 2]);
        assert!(!unsorted.is_monotonic_increasing());
        assert!(!unsorted.is_monotonic_decreasing());

        // Constant series is monotonic both ways (non-strict).
        let flat = make(vec![4, 4, 4]);
        assert!(flat.is_monotonic_increasing() && flat.is_monotonic_decreasing());

        // Single-element and empty are trivially monotonic both ways.
        let one = make(vec![7]);
        assert!(one.is_monotonic_increasing() && one.is_monotonic_decreasing());
        let empty = make(Vec::new());
        assert!(empty.is_monotonic_increasing() && empty.is_monotonic_decreasing());

        // Bit-identical to the generic Scalar path: a Utf8 series whose string
        // values mirror the integer order takes the fallback and must agree with
        // the typed result for the same logical ordering.
        let typed_sorted = make(vec![1, 2, 3]);
        let utf8_sorted = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
                Scalar::Utf8("c".into()),
            ],
        )
        .unwrap();
        assert!(utf8_sorted.column.as_i64_slice().is_none());
        assert_eq!(
            typed_sorted.is_monotonic_increasing(),
            utf8_sorted.is_monotonic_increasing()
        );
    }

    #[test]
    fn series_is_monotonic_increasing_unsorted_utf8_returns_false() {
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Utf8("c".into()),
                Scalar::Utf8("a".into()),
                Scalar::Utf8("b".into()),
            ],
        )
        .unwrap();
        assert!(!s.is_monotonic_increasing());
    }

    #[test]
    fn series_is_monotonic_increasing_with_missing_returns_false() {
        // Sister behavior to is_monotonic_decreasing: any missing value
        // makes the result false (matches the existing _decreasing impl).
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Null(NullKind::NaN),
                Scalar::Int64(3),
            ],
        )
        .unwrap();
        assert!(!s.is_monotonic_increasing());
    }

    #[test]
    fn series_is_unique_true_with_single_null() {
        // Per br-frankenpandas-05216: pandas treats a single null as one
        // distinct value alongside other distinct non-null values.
        // [1, 2, 3, Null] is unique (4 distinct values).
        // Was returning false because the implementation conflated
        // unique()'s null bucket with the null count.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        assert!(s.is_unique());
    }

    #[test]
    fn series_is_unique_false_with_two_nulls() {
        // Two nulls are "duplicate" per pandas (NaN == NaN for is_unique
        // purposes). The null_count <= 1 guard catches this.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        assert!(!s.is_unique());
    }

    #[test]
    fn series_is_unique_false_with_repeated_value_and_one_null() {
        // Repeated non-null value blocks uniqueness regardless of nulls.
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        assert!(!s.is_unique());
    }

    #[test]
    fn series_is_unique_true_for_all_distinct_no_nulls() {
        // Regression guard: original-correct path (no nulls, all distinct).
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)],
        )
        .unwrap();
        assert!(s.is_unique());
    }

    #[test]
    fn series_has_duplicates_inverse_of_is_unique() {
        // Metamorphic property: has_duplicates() == !is_unique().
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Null(NullKind::NaN),
            ],
        )
        .unwrap();
        assert_eq!(s.has_duplicates(), !s.is_unique());
        // For this input both should reflect "no duplicates".
        assert!(!s.has_duplicates());
        assert!(s.is_unique());
    }

    #[test]
    fn qcut_uses_log_q_binary_search_per_value() {
        // Per br-frankenpandas-e00ce: qcut() now resolves bucket via
        // partition_point binary search over sorted edges. Was O(n × q)
        // inner scan + n redundant String allocations. 1000 values × 10
        // quantile bins; correctness check.
        let labels: Vec<IndexLabel> = (0..1000_i64).map(IndexLabel::Int64).collect();
        let values: Vec<Scalar> = (0..1000_i64).map(|i| Scalar::Float64(i as f64)).collect();
        let s = Series::from_values("x", labels, values).unwrap();

        let binned = qcut(&s, 10).unwrap();
        // Approx 10 distinct quantile labels (some quantiles may collide
        // for tightly-packed sorted data, but should be close).
        let unique = binned.unique();
        assert!(
            (5..=10).contains(&unique.len()),
            "expected 5..=10 distinct quantile labels, got {}",
            unique.len()
        );
        // Every output is a Utf8 label (no nulls in input).
        for v in binned.column().values() {
            assert!(matches!(v, Scalar::Utf8(_)));
        }
    }

    #[test]
    fn qcut_value_at_quantile_boundary_uses_right_closed_semantics() {
        // Per br-frankenpandas-e00ce: pandas right-closed (left, right].
        // For input [1, 2, 3, 4, 5] with q=2: edges from 0/1/2 quantiles
        // are [1, 3, 5]; 50th percentile is 3.0.
        // Bin 0: [1, 3] (first-bin-inclusive on both sides).
        // Bin 1: (3, 5].
        // Value 3 should land in bin 0 (right edge inclusive for bin 0,
        // and partition_point on [3, 5] for `right < 3` returns 0).
        // Value 4 should land in bin 1.
        let s = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();

        let binned = qcut(&s, 2).unwrap();
        // 3 values (1, 2, 3) in bin 0; 2 values (4, 5) in bin 1.
        let counts = binned.value_counts().unwrap();
        // Two distinct labels.
        assert_eq!(counts.len(), 2);
        // Most-frequent is bin 0 with count 3.
        assert_eq!(counts.column().values()[0], Scalar::Int64(3));
        // Then bin 1 with count 2.
        assert_eq!(counts.column().values()[1], Scalar::Int64(2));
    }

    #[test]
    fn cut_uses_o1_bucket_index_per_value() {
        // Per br-frankenpandas-21a14: cut() now computes bucket index in
        // O(1) per value via ((v - min) / width).ceil() - 1, with clamping.
        // Was O(bins) linear scan + n redundant String allocations.
        // Test with 1000 values across 10 bins; verify each value lands
        // in the correct bin (matches the right-closed-interval semantics).
        let labels: Vec<IndexLabel> = (0..1000_i64).map(IndexLabel::Int64).collect();
        // Values 0..1000, range [0, 999], 10 bins → width = 99.9.
        let values: Vec<Scalar> = (0..1000_i64).map(|i| Scalar::Float64(i as f64)).collect();
        let s = Series::from_values("x", labels, values).unwrap();

        let binned = cut(&s, 10).unwrap();
        // 10 unique bin labels (assuming all bins are populated, which
        // they should be for a uniform 0..1000 spread).
        let unique = binned.unique();
        assert!(
            unique.len() >= 9 && unique.len() <= 10,
            "expected ~10 distinct bin labels, got {}",
            unique.len()
        );
        // Every output is a Utf8 bin label (no NaNs since input has no nulls).
        for v in binned.column().values() {
            assert!(
                matches!(v, Scalar::Utf8(_)),
                "expected Utf8 label, got {v:?}"
            );
        }
    }

    #[test]
    fn cut_value_at_bin_boundary_uses_right_closed_semantics() {
        // Per br-frankenpandas-21a14: pandas right-closed intervals
        // (left, right]. A value at the exact upper edge of bin k
        // belongs to bin k, NOT k+1. With min=1, max=10, bins=3,
        // width=3.0, edges at [1, 4, 7, 10]:
        // - 1 → bin 0 (first-bin-inclusive on left)
        // - 4 → bin 0 (right edge of bin 0, inclusive)
        // - 5 → bin 1 ((4, 7])
        // - 7 → bin 1 (right edge of bin 1)
        // - 10 → bin 2 (right edge of bin 2)
        let s = Series::from_values(
            "x",
            (0..5_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(7.0),
                Scalar::Float64(10.0),
            ],
        )
        .unwrap();

        let counts = s.value_counts_bins(3).unwrap();
        // All 3 bins should be populated:
        // - bin 0 (1, 4]: values 1, 2, 3 (with 1 inclusive via clamp)
        // - bin 1 (4, 7]: value 7
        // - bin 2 (7, 10]: value 10
        assert_eq!(counts.len(), 3);
    }

    #[test]
    fn cut_handles_all_equal_values_via_zero_width_branch() {
        // Edge case: when min == max (all values equal), width is 0;
        // every value should land in bin 0. Old impl handled this
        // (sort of) via the loop; new impl explicitly branches.
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Float64(5.0),
                Scalar::Float64(5.0),
                Scalar::Float64(5.0),
            ],
        )
        .unwrap();
        let binned = cut(&s, 4).unwrap();
        assert_eq!(binned.len(), 3);
        // All three values should map to the same bin label.
        let first_label = binned.column().values()[0].clone();
        for v in binned.column().values() {
            assert_eq!(*v, first_label);
        }
    }

    #[test]
    fn series_isin_uses_hash_fast_path() {
        // Per br-frankenpandas-f7201: O(n + m) regression guard. 1000-entry
        // test set on 5000-element series; old impl would do 5×10⁶ comparisons,
        // new ~5K + 1K (one HashSet build).
        let test_values: Vec<Scalar> = (0..1000_i64).map(Scalar::Int64).collect();
        let labels: Vec<IndexLabel> = (0..5000_i64).map(IndexLabel::Int64).collect();
        let values: Vec<Scalar> = (0..5000_i64).map(Scalar::Int64).collect();
        let s = Series::from_values("x", labels, values).unwrap();

        let out = s.isin(&test_values).unwrap();
        // Values 0..1000 should be in; 1000..5000 should be out.
        for (i, v) in out.column().values().iter().enumerate() {
            let expected = i < 1000;
            assert_eq!(*v, Scalar::Bool(expected), "row {i}");
        }
    }

    #[test]
    fn series_isin_cross_type_int_in_float_test_values() {
        // Per br-frankenpandas-f7201: pandas isin matches Int64(1) against
        // a Float64(1.0) test value. The IsinIndex consults float_bits with
        // the int's f64 representation when missing from the int set.
        let test_values = vec![
            Scalar::Float64(1.0),
            Scalar::Float64(2.0),
            Scalar::Float64(3.0),
        ];
        let s = Series::from_values(
            "x",
            (0..4_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Int64(1),
                Scalar::Int64(2),
                Scalar::Int64(3),
                Scalar::Int64(4),
            ],
        )
        .unwrap();
        let out = s.isin(&test_values).unwrap();
        assert_eq!(
            out.column().values(),
            &[
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Bool(false),
            ]
        );
    }

    #[test]
    fn series_isin_cross_type_float_in_int_test_values() {
        // Reverse direction: Float64(1.0) in [Int64(1), Int64(2)] → true.
        // Float64(1.5) → false (not integer-valued).
        let test_values = vec![Scalar::Int64(1), Scalar::Int64(2), Scalar::Int64(3)];
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(1.5),
                Scalar::Float64(2.0),
            ],
        )
        .unwrap();
        let out = s.isin(&test_values).unwrap();
        assert_eq!(
            out.column().values(),
            &[Scalar::Bool(true), Scalar::Bool(false), Scalar::Bool(true)]
        );
    }

    #[test]
    fn series_isin_missing_input_matches_only_when_test_has_missing() {
        // is_missing input → returns true iff any test_value is missing.
        let s = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Int64(5), Scalar::Null(NullKind::NaN)],
        )
        .unwrap();

        // Test set with no missing → null input gives false.
        let no_null = vec![Scalar::Int64(1), Scalar::Int64(5)];
        let out_no_null = s.isin(&no_null).unwrap();
        assert_eq!(
            out_no_null.column().values(),
            &[Scalar::Bool(true), Scalar::Bool(false)]
        );

        // Test set with NaN → null input gives true.
        let with_null = vec![Scalar::Int64(99), Scalar::Float64(f64::NAN)];
        let out_with_null = s.isin(&with_null).unwrap();
        assert_eq!(
            out_with_null.column().values(),
            &[Scalar::Bool(false), Scalar::Bool(true)]
        );
    }

    #[test]
    fn series_isin_bool_cross_matches_int_per_pandas() {
        // Per br-frankenpandas-8c63b: pandas isin treats Bool as 0/1 for
        // numeric comparison. Bool(true) matches Int64(1); Bool(false)
        // matches Int64(0). Was previously [false, false] (preserved
        // divergence under f7201); now matches pandas.
        let s = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Bool(true), Scalar::Bool(false)],
        )
        .unwrap();
        let test_values = vec![Scalar::Int64(1), Scalar::Int64(0)];
        let out = s.isin(&test_values).unwrap();
        assert_eq!(
            out.column().values(),
            &[Scalar::Bool(true), Scalar::Bool(true)]
        );
    }

    #[test]
    fn series_isin_bool_cross_matches_float() {
        // Pandas: Bool(true) matches Float64(1.0); Bool(false) matches
        // Float64(0.0).
        let s = Series::from_values(
            "x",
            (0..2_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Bool(true), Scalar::Bool(false)],
        )
        .unwrap();
        let test_values = vec![Scalar::Float64(1.0), Scalar::Float64(0.0)];
        let out = s.isin(&test_values).unwrap();
        assert_eq!(
            out.column().values(),
            &[Scalar::Bool(true), Scalar::Bool(true)]
        );
    }

    #[test]
    fn series_isin_int_zero_one_cross_matches_bool() {
        // Reverse direction: Int64(0|1) matches Bool(false)/Bool(true).
        // Int64(2) must NOT match any Bool.
        let s = Series::from_values(
            "x",
            (0..3_i64).map(IndexLabel::Int64).collect::<Vec<_>>(),
            vec![Scalar::Int64(0), Scalar::Int64(1), Scalar::Int64(2)],
        )
        .unwrap();
        let test_values = vec![Scalar::Bool(true), Scalar::Bool(false)];
        let out = s.isin(&test_values).unwrap();
        // 0 → matches false; 1 → matches true; 2 → no Bool match
        assert_eq!(
            out.column().values(),
            &[Scalar::Bool(true), Scalar::Bool(true), Scalar::Bool(false)]
        );
    }

