    #[test]
    fn series_to_period_converts_datetime_index_to_month_labels() {
        let idx = vec![
            IndexLabel::Utf8("2024-01-15".into()),
            IndexLabel::Utf8("2024-02-20".into()),
            IndexLabel::Utf8("2024-03-10".into()),
        ];
        let s = Series::new(
            "vals".to_owned(),
            Index::new(idx).set_names(Some("when")),
            Column::from_values(vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
            ])
            .unwrap(),
        )
        .unwrap();
        let result = s.to_period("M").unwrap();
        assert_eq!(result.name(), "vals");
        assert_eq!(result.len(), 3);
        assert_eq!(result.index().name(), Some("when"));
        assert_eq!(result.values(), s.values());
        assert_eq!(
            result.index().labels()[0],
            IndexLabel::Utf8("2024-01".into())
        );
        assert_eq!(
            result.index().labels()[1],
            IndexLabel::Utf8("2024-02".into())
        );
        assert_eq!(
            result.index().labels()[2],
            IndexLabel::Utf8("2024-03".into())
        );
    }

