    #[test]
    fn median_typed_quickselect_matches_sort() {
        // The typed quickselect median must equal the sort-based reference for
        // all-valid Int64/Float64, across odd/even lengths and heavy duplicates.
        let mut state: u64 = 0x71B0_CE38_4A5F_2D19;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let sort_median = |mut v: Vec<f64>| -> f64 {
            v.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let mid = v.len() / 2;
            if v.len().is_multiple_of(2) {
                (v[mid - 1] + v[mid]) / 2.0
            } else {
                v[mid]
            }
        };
        for trial in 0..200 {
            let n = (next() % 400) as usize + 1;
            // Narrow range → many duplicate medians.
            let raw: Vec<i64> = (0..n).map(|_| (next() % 15) as i64 - 7).collect();
            let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();

            let si = Series::new(
                "s".to_owned(),
                Index::new(labels.clone()),
                Column::from_i64_values_owned(raw.clone()),
            )
            .unwrap();
            let want_i = sort_median(raw.iter().map(|&v| v as f64).collect());
            match si.median().unwrap() {
                Scalar::Float64(g) => {
                    assert_eq!(g.to_bits(), want_i.to_bits(), "trial {trial} int median")
                }
                o => panic!("{o:?}"),
            }

            let fraw: Vec<f64> = raw.iter().map(|&v| v as f64 / 3.0).collect();
            let sf = Series::new(
                "s".to_owned(),
                Index::new(labels),
                Column::from_f64_values(fraw.clone()),
            )
            .unwrap();
            let want_f = sort_median(fraw.clone());
            match sf.median().unwrap() {
                Scalar::Float64(g) => {
                    assert_eq!(g.to_bits(), want_f.to_bits(), "trial {trial} float median")
                }
                o => panic!("{o:?}"),
            }
        }
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn median_typed_quickselect_timing() {
        use std::time::Instant;
        let n = 5_000_000usize;
        let iters = 10;
        let mut state: u64 = 0x53C2_99DA_2C8E_71B0;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let data: Vec<f64> = (0..n).map(|_| (next() % 1_000_000) as f64).collect();
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let mk = || {
            Series::new(
                "s".to_owned(),
                Index::new(labels.clone()),
                Column::from_f64_values(data.clone()),
            )
            .unwrap()
        };
        let t0 = Instant::now();
        let mut chk = 0u64;
        for _ in 0..iters {
            if let Scalar::Float64(m) = mk().median().unwrap() {
                chk ^= m.to_bits();
            }
        }
        let typed = t0.elapsed();
        // OLD: materialize f64 (to_f64) + full sort + middle.
        let t1 = Instant::now();
        let mut chk2 = 0u64;
        for _ in 0..iters {
            let s = mk();
            let mut vals: Vec<f64> = s
                .column
                .values()
                .iter()
                .map(|v| v.to_f64().unwrap())
                .collect();
            vals.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let mid = vals.len() / 2;
            let m = if vals.len().is_multiple_of(2) {
                (vals[mid - 1] + vals[mid]) / 2.0
            } else {
                vals[mid]
            };
            chk2 ^= m.to_bits();
        }
        let scalar = t1.elapsed();
        let t2 = Instant::now();
        let mut sink = 0usize;
        for _ in 0..iters {
            sink ^= mk().len();
        }
        let build = t2.elapsed();
        eprintln!(
            "median 5M f64 x{iters}: typed={typed:?} scalar_sort={scalar:?} build={build:?} op-only={:.2}x (full {:.2}x, chk {chk}/{chk2}/{sink})",
            scalar.saturating_sub(build).as_secs_f64() / typed.saturating_sub(build).as_secs_f64(),
            scalar.as_secs_f64() / typed.as_secs_f64()
        );
    }

    #[test]
    fn groupby_cum_dense_matches_reference_gbcum() {
        // The dense-gid typed cum* fast path must equal a per-group, row-order
        // running-scan reference for every op — including duplicate keys, -0.0
        // vs 0.0 ties (cummin/cummax keep the existing value), and negatives.
        let keys: Vec<i64> = vec![0, 1, 0, 2, 1, 0, 2, 2, 1, 0];
        let vals: Vec<f64> = vec![1.0, -0.0, 0.0, 3.0, 2.0, -1.0, 3.0, -2.5, 2.0, 0.0];
        let n = vals.len();
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let value = Series::new(
            "v".to_owned(),
            Index::new(labels.clone()),
            Column::from_f64_values(vals.clone()),
        )
        .unwrap();
        let key = Series::new(
            "k".to_owned(),
            Index::new(labels),
            Column::from_i64_values_owned(keys.clone()),
        )
        .unwrap();

        type Step = fn(f64, f64) -> f64;
        let cases: [(&str, f64, Step); 4] = [
            ("cumsum", 0.0, |a, v| a + v),
            ("cumprod", 1.0, |a, v| a * v),
            ("cummin", f64::INFINITY, |a, v| if v < a { v } else { a }),
            (
                "cummax",
                f64::NEG_INFINITY,
                |a, v| if v > a { v } else { a },
            ),
        ];
        for (name, init, step) in cases {
            let mut acc: std::collections::HashMap<i64, f64> = std::collections::HashMap::new();
            let want: Vec<u64> = (0..n)
                .map(|i| {
                    let a = acc.entry(keys[i]).or_insert(init);
                    *a = step(*a, vals[i]);
                    a.to_bits()
                })
                .collect();
            let grouped = value.groupby(&key).unwrap();
            let got = match name {
                "cumsum" => grouped.cumsum(),
                "cumprod" => grouped.cumprod(),
                "cummin" => grouped.cummin(),
                _ => grouped.cummax(),
            }
            .unwrap();
            let got_bits: Vec<u64> = got
                .column
                .as_f64_slice()
                .expect("dense cum output is typed f64")
                .iter()
                .map(|x| x.to_bits())
                .collect();
            assert_eq!(got_bits, want, "groupby {name} mismatch");
        }
    }

    #[test]
    fn dataframe_groupby_cum_dense_matches_reference_gbcum() {
        // DataFrameGroupBy dense cum* over multiple Float64 value columns must
        // equal a per-column, per-group, row-order running-scan reference.
        let keys: Vec<i64> = vec![0, 1, 0, 2, 1, 0, 2, 2, 1, 0];
        let v0: Vec<f64> = vec![1.0, -0.0, 0.0, 3.0, 2.0, -1.0, 3.0, -2.5, 2.0, 0.0];
        let v1: Vec<f64> = vec![2.0, 1.5, -4.0, 0.5, 9.0, -3.0, 1.0, 1.0, -0.0, 2.0];
        let n = keys.len();
        let mut map = BTreeMap::new();
        map.insert("k".to_string(), Column::from_i64_values_owned(keys.clone()));
        map.insert("v0".to_string(), Column::from_f64_values(v0.clone()));
        map.insert("v1".to_string(), Column::from_f64_values(v1.clone()));
        let order = vec!["k".to_string(), "v0".to_string(), "v1".to_string()];
        let df = DataFrame::new_with_column_order(
            Index::new((0..n as i64).map(IndexLabel::Int64).collect()),
            map,
            order,
        )
        .unwrap();

        type Step = fn(f64, f64) -> f64;
        let cases: [(&str, f64, Step); 4] = [
            ("cumsum", 0.0, |a, v| a + v),
            ("cumprod", 1.0, |a, v| a * v),
            ("cummin", f64::INFINITY, |a, v| if v < a { v } else { a }),
            (
                "cummax",
                f64::NEG_INFINITY,
                |a, v| if v > a { v } else { a },
            ),
        ];
        for (name, init, step) in cases {
            let grouped = df.groupby(&["k"]).unwrap();
            let got = match name {
                "cumsum" => grouped.cumsum(),
                "cumprod" => grouped.cumprod(),
                "cummin" => grouped.cummin(),
                _ => grouped.cummax(),
            }
            .unwrap();
            for (cname, vals) in [("v0", &v0), ("v1", &v1)] {
                let mut acc: std::collections::HashMap<i64, f64> = std::collections::HashMap::new();
                let want: Vec<u64> = (0..n)
                    .map(|i| {
                        let a = acc.entry(keys[i]).or_insert(init);
                        *a = step(*a, vals[i]);
                        a.to_bits()
                    })
                    .collect();
                let got_bits: Vec<u64> = got.columns[cname]
                    .as_f64_slice()
                    .expect("dense cum output is typed f64")
                    .iter()
                    .map(|x| x.to_bits())
                    .collect();
                assert_eq!(got_bits, want, "df groupby {name} col {cname} mismatch");
            }
        }
    }

    #[test]
    fn groupby_shift_dense_matches_reference_gbcum() {
        // SeriesGroupBy + DataFrameGroupBy dense shift(periods>0) must equal a
        // per-group, row-order reference: out = value `periods` rows earlier
        // within the group, missing for the first `periods` rows.
        let keys: Vec<i64> = vec![0, 1, 0, 2, 1, 0, 2, 0, 1, 0];
        let v0: Vec<f64> = vec![1.0, -0.0, 0.0, 3.0, 2.0, -1.0, 7.0, -2.5, 2.0, 4.0];
        let v1: Vec<f64> = vec![2.0, 1.5, -4.0, 0.5, 9.0, -3.0, 1.0, 1.0, -0.0, 2.0];
        let n = keys.len();

        let reference = |vals: &[f64], periods: usize| -> Vec<Option<u64>> {
            let mut hist: std::collections::HashMap<i64, Vec<f64>> =
                std::collections::HashMap::new();
            (0..n)
                .map(|i| {
                    let list = hist.entry(keys[i]).or_default();
                    let local = list.len();
                    let res = if local >= periods {
                        Some(list[local - periods].to_bits())
                    } else {
                        None
                    };
                    list.push(vals[i]);
                    res
                })
                .collect()
        };
        let check = |col: &Column, want: &[Option<u64>], ctx: &str| {
            let vals = col.values();
            for (i, w) in want.iter().enumerate() {
                match w {
                    None => assert!(vals[i].is_missing(), "{ctx} row {i} expected missing"),
                    Some(bits) => match &vals[i] {
                        Scalar::Float64(f) => assert_eq!(f.to_bits(), *bits, "{ctx} row {i}"),
                        other => panic!("{ctx} row {i} expected Float64, got {other:?}"),
                    },
                }
            }
        };

        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let value = Series::new(
            "v".to_owned(),
            Index::new(labels.clone()),
            Column::from_f64_values(v0.clone()),
        )
        .unwrap();
        let key = Series::new(
            "k".to_owned(),
            Index::new(labels.clone()),
            Column::from_i64_values_owned(keys.clone()),
        )
        .unwrap();
        for periods in [1i64, 2] {
            let got = value.groupby(&key).unwrap().shift(periods).unwrap();
            check(
                &got.column,
                &reference(&v0, periods as usize),
                &format!("series p={periods}"),
            );
        }

        let mut map = BTreeMap::new();
        map.insert("k".to_string(), Column::from_i64_values_owned(keys.clone()));
        map.insert("v0".to_string(), Column::from_f64_values(v0.clone()));
        map.insert("v1".to_string(), Column::from_f64_values(v1.clone()));
        let order = vec!["k".to_string(), "v0".to_string(), "v1".to_string()];
        let df = DataFrame::new_with_column_order(Index::new(labels), map, order).unwrap();
        for periods in [1i64, 2] {
            let got = df.groupby(&["k"]).unwrap().shift(periods).unwrap();
            check(
                &got.columns["v0"],
                &reference(&v0, periods as usize),
                &format!("df v0 p={periods}"),
            );
            check(
                &got.columns["v1"],
                &reference(&v1, periods as usize),
                &format!("df v1 p={periods}"),
            );
        }
    }

    #[test]
    fn groupby_diff_dense_matches_reference_gbcum() {
        // SeriesGroupBy + DataFrameGroupBy dense diff(periods) must equal a
        // per-group, row-order windowed-difference reference, with the first
        // `periods` rows of each group missing. Covers periods 1 and 2, a group
        // smaller than periods (all-null), and an inf (inf-inf == NaN valid).
        let keys: Vec<i64> = vec![0, 1, 0, 2, 1, 0, 2, 0, 1, 0];
        let v0: Vec<f64> = vec![
            1.0,
            5.0,
            3.0,
            f64::INFINITY,
            2.0,
            -1.0,
            f64::INFINITY,
            0.0,
            2.0,
            4.0,
        ];
        let v1: Vec<f64> = vec![2.0, 1.5, -4.0, 0.5, 9.0, -3.0, 1.0, 7.0, -0.0, 2.0];
        let n = keys.len();

        let reference = |vals: &[f64], periods: usize| -> Vec<Option<u64>> {
            let mut hist: std::collections::HashMap<i64, Vec<f64>> =
                std::collections::HashMap::new();
            (0..n)
                .map(|i| {
                    let list = hist.entry(keys[i]).or_default();
                    let local = list.len();
                    let res = if local >= periods {
                        Some((vals[i] - list[local - periods]).to_bits())
                    } else {
                        None
                    };
                    list.push(vals[i]);
                    res
                })
                .collect()
        };
        let check = |col: &Column, want: &[Option<u64>], ctx: &str| {
            let vals = col.values();
            for (i, w) in want.iter().enumerate() {
                match w {
                    None => assert!(vals[i].is_missing(), "{ctx} row {i} expected missing"),
                    Some(bits) => match &vals[i] {
                        Scalar::Float64(f) => {
                            assert_eq!(f.to_bits(), *bits, "{ctx} row {i}")
                        }
                        other => panic!("{ctx} row {i} expected Float64, got {other:?}"),
                    },
                }
            }
        };

        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let value = Series::new(
            "v".to_owned(),
            Index::new(labels.clone()),
            Column::from_f64_values(v0.clone()),
        )
        .unwrap();
        let key = Series::new(
            "k".to_owned(),
            Index::new(labels.clone()),
            Column::from_i64_values_owned(keys.clone()),
        )
        .unwrap();
        for periods in [1usize, 2] {
            let got = value.groupby(&key).unwrap().diff(periods).unwrap();
            check(
                &got.column,
                &reference(&v0, periods),
                &format!("series p={periods}"),
            );
        }

        let mut map = BTreeMap::new();
        map.insert("k".to_string(), Column::from_i64_values_owned(keys.clone()));
        map.insert("v0".to_string(), Column::from_f64_values(v0.clone()));
        map.insert("v1".to_string(), Column::from_f64_values(v1.clone()));
        let order = vec!["k".to_string(), "v0".to_string(), "v1".to_string()];
        let df = DataFrame::new_with_column_order(Index::new(labels), map, order).unwrap();
        for periods in [1usize, 2] {
            let got = df.groupby(&["k"]).unwrap().diff(periods).unwrap();
            check(
                &got.columns["v0"],
                &reference(&v0, periods),
                &format!("df v0 p={periods}"),
            );
            check(
                &got.columns["v1"],
                &reference(&v1, periods),
                &format!("df v1 p={periods}"),
            );
        }
    }

    #[test]
    fn cumsum_typed_matches_reference() {
        // The typed cumsum fast path must be bit-identical to the prefix-sum
        // reference for all-valid Int64 (wrapping_add) and Float64 (acc+=v).
        let mut state: u64 = 0x2B99_2DDF_A232_5719;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..150 {
            let n = (next() % 400) as usize + 1;
            let raw: Vec<i64> = (0..n).map(|_| (next() % 2000) as i64 - 1000).collect();
            let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();

            let si = Series::new(
                "s".to_owned(),
                Index::new(labels.clone()),
                Column::from_i64_values_owned(raw.clone()),
            )
            .unwrap();
            let mut acc = 0i64;
            let want_i: Vec<i64> = raw
                .iter()
                .map(|&v| {
                    acc = acc.wrapping_add(v);
                    acc
                })
                .collect();
            let got_i: Vec<i64> = si
                .cumsum()
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    o => panic!("{o:?}"),
                })
                .collect();
            assert_eq!(got_i, want_i, "trial {trial} cumsum int");

            let fraw: Vec<f64> = raw.iter().map(|&v| v as f64 / 8.0).collect();
            let sf = Series::new(
                "s".to_owned(),
                Index::new(labels.clone()),
                Column::from_f64_values(fraw.clone()),
            )
            .unwrap();
            let mut accf = 0.0f64;
            let want_f: Vec<f64> = fraw
                .iter()
                .map(|&v| {
                    accf += v;
                    accf
                })
                .collect();
            let got_f: Vec<f64> = sf
                .cumsum()
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    o => panic!("{o:?}"),
                })
                .collect();
            for (g, w) in got_f.iter().zip(&want_f) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} cumsum float");
            }

            // cumprod / cummin / cummax — Int64 + Float64, bit-exact prefix scans.
            let geti = |s: &Series| -> Vec<i64> {
                s.values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        o => panic!("{o:?}"),
                    })
                    .collect()
            };
            let getf = |s: &Series| -> Vec<u64> {
                s.values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => x.to_bits(),
                        o => panic!("{o:?}"),
                    })
                    .collect()
            };
            // Int64 references.
            let mut a = 1i64;
            let wp_i: Vec<i64> = raw
                .iter()
                .map(|&v| {
                    a = a.wrapping_mul(v);
                    a
                })
                .collect();
            let mut a = i64::MAX;
            let wmin_i: Vec<i64> = raw
                .iter()
                .map(|&v| {
                    a = a.min(v);
                    a
                })
                .collect();
            let mut a = i64::MIN;
            let wmax_i: Vec<i64> = raw
                .iter()
                .map(|&v| {
                    a = a.max(v);
                    a
                })
                .collect();
            assert_eq!(
                geti(&si.cumprod().unwrap()),
                wp_i,
                "trial {trial} cumprod int"
            );
            assert_eq!(
                geti(&si.cummin().unwrap()),
                wmin_i,
                "trial {trial} cummin int"
            );
            assert_eq!(
                geti(&si.cummax().unwrap()),
                wmax_i,
                "trial {trial} cummax int"
            );
            // Float64 references.
            let mut a = 1.0f64;
            let wp_f: Vec<u64> = fraw
                .iter()
                .map(|&v| {
                    a *= v;
                    a.to_bits()
                })
                .collect();
            let mut a = f64::INFINITY;
            let wmin_f: Vec<u64> = fraw
                .iter()
                .map(|&v| {
                    if v < a {
                        a = v;
                    }
                    a.to_bits()
                })
                .collect();
            let mut a = f64::NEG_INFINITY;
            let wmax_f: Vec<u64> = fraw
                .iter()
                .map(|&v| {
                    if v > a {
                        a = v;
                    }
                    a.to_bits()
                })
                .collect();
            assert_eq!(
                getf(&sf.cumprod().unwrap()),
                wp_f,
                "trial {trial} cumprod float"
            );
            assert_eq!(
                getf(&sf.cummin().unwrap()),
                wmin_f,
                "trial {trial} cummin float"
            );
            assert_eq!(
                getf(&sf.cummax().unwrap()),
                wmax_f,
                "trial {trial} cummax float"
            );
        }
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn cumsum_typed_timing() {
        use std::time::Instant;
        let n = 5_000_000usize;
        let iters = 10;
        let mut state: u64 = 0x0A2C_5B7D_91E3_46F0;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let data: Vec<f64> = (0..n).map(|_| (next() % 1000) as f64).collect();
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let mk = || {
            Series::new(
                "s".to_owned(),
                Index::new(labels.clone()),
                Column::from_f64_values(data.clone()),
            )
            .unwrap()
        };
        let t0 = Instant::now();
        let mut chk = 0usize;
        for _ in 0..iters {
            chk ^= mk().cumsum().unwrap().len();
        }
        let typed = t0.elapsed();
        let t1 = Instant::now();
        let mut chk2 = 0usize;
        for _ in 0..iters {
            let s = mk();
            let mut acc = 0.0f64;
            let out: Vec<Scalar> = s
                .column
                .values()
                .iter()
                .map(|v| {
                    acc += v.to_f64().unwrap();
                    Scalar::Float64(acc)
                })
                .collect();
            let r = s
                .with_labels_and_values_preserving_name(s.index.labels().to_vec(), out)
                .unwrap();
            chk2 ^= r.len();
        }
        let scalar = t1.elapsed();
        let t2 = Instant::now();
        let mut sink = 0usize;
        for _ in 0..iters {
            sink ^= mk().len();
        }
        let build = t2.elapsed();
        eprintln!(
            "cumsum 5M f64 x{iters}: typed={typed:?} scalar={scalar:?} build={build:?} op-only={:.2}x (full {:.2}x, chk {chk}/{chk2}/{sink})",
            scalar.saturating_sub(build).as_secs_f64() / typed.saturating_sub(build).as_secs_f64(),
            scalar.as_secs_f64() / typed.as_secs_f64()
        );
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn series_sort_values_typed_radix_timing() {
        use std::{cmp::Ordering, time::Instant};
        let n = 5_000_000usize;
        let mut state: u64 = 0xABCD_1234_5678_9F01;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let data: Vec<i64> = (0..n).map(|_| next() as i64).collect();
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let series = Series::new(
            "s".to_owned(),
            Index::new(labels),
            Column::from_i64_values_owned(data.clone()),
        )
        .unwrap();

        let iters = 10;
        // NEW: user-facing sort_values routes through Column::argsort_with radix.
        let t0 = Instant::now();
        let mut chk = 0i64;
        for _ in 0..iters {
            let sorted = series.sort_values(true).unwrap();
            if let Scalar::Int64(v) = &sorted.values()[0] {
                chk ^= *v;
            }
        }
        let radix = t0.elapsed();

        // OLD: positional sort_by the Scalar comparator, then reorder (the path
        // this commit replaced). Same reorder_by_positions in both.
        let t1 = Instant::now();
        let mut chk2 = 0i64;
        for _ in 0..iters {
            let vals = series.values();
            let mut order: Vec<usize> = (0..n).collect();
            order.sort_by(|&l, &r| match (&vals[l], &vals[r]) {
                (Scalar::Int64(a), Scalar::Int64(b)) => a.cmp(b),
                _ => Ordering::Equal,
            });
            let sorted = series.reorder_by_positions(&order).unwrap();
            if let Scalar::Int64(v) = &sorted.values()[0] {
                chk2 ^= *v;
            }
        }
        let scalar = t1.elapsed();
        eprintln!(
            "series.sort_values 5M i64 x{iters}: radix={radix:?} scalar_cmp={scalar:?} ratio={:.2}x (chk {chk}/{chk2})",
            scalar.as_secs_f64() / radix.as_secs_f64()
        );
    }

    #[test]
    fn value_counts_dense_matches_reference() {
        // Independent reference: first-seen counts via linear scan, then the
        // same stable sort-by-count the impl applies. The direct-address dense
        // histogram fast path must be bit-identical (index labels + counts)
        // across sort/ascending modes for bounded-range all-valid Int64.
        let mut state: u64 = 0x77E1_5C44_9A2B_3D16;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 250) as usize + 1;
            let data: Vec<i64> = (0..n).map(|_| (next() % 11) as i64 - 5).collect();
            let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
            let series = Series::new(
                "s".to_owned(),
                Index::new(labels),
                Column::from_i64_values_owned(data.clone()),
            )
            .unwrap();

            for sort in [false, true] {
                for ascending in [false, true] {
                    // Reference first-seen counts.
                    let mut order: Vec<i64> = Vec::new();
                    let mut cnt: Vec<usize> = Vec::new();
                    for &v in &data {
                        match order.iter().position(|&u| u == v) {
                            Some(p) => cnt[p] += 1,
                            None => {
                                order.push(v);
                                cnt.push(1);
                            }
                        }
                    }
                    let mut pairs: Vec<(i64, usize)> = order.into_iter().zip(cnt).collect();
                    if sort {
                        if ascending {
                            pairs.sort_by_key(|&(_, c)| c);
                        } else {
                            pairs.sort_by_key(|&(_, c)| std::cmp::Reverse(c));
                        }
                    }

                    let vc = series
                        .value_counts_with_options(false, sort, ascending, true)
                        .unwrap();
                    let got_labels: Vec<i64> = vc
                        .index()
                        .labels()
                        .iter()
                        .map(|l| match l {
                            IndexLabel::Int64(v) => *v,
                            other => panic!("unexpected label {other:?}"),
                        })
                        .collect();
                    let got_counts: Vec<i64> = vc
                        .values()
                        .iter()
                        .map(|v| match v {
                            Scalar::Int64(c) => *c,
                            other => panic!("unexpected count {other:?}"),
                        })
                        .collect();
                    let want_labels: Vec<i64> = pairs.iter().map(|&(v, _)| v).collect();
                    let want_counts: Vec<i64> = pairs.iter().map(|&(_, c)| c as i64).collect();
                    assert_eq!(
                        got_labels, want_labels,
                        "trial {trial} sort={sort} asc={ascending} labels"
                    );
                    assert_eq!(
                        got_counts, want_counts,
                        "trial {trial} sort={sort} asc={ascending} counts"
                    );
                }
            }
        }
    }

    #[test]
    fn dataframe_groupby_dense_float_agg_matches_reference() {
        // df.groupby([int]).{sum,mean,count} over all-valid Float64 value
        // columns exercises the dense single-pass accumulation path. Must be
        // bit-identical to a row-order left-fold reference (sorted groups).
        let mut state: u64 = 0x9216_D5D9_8979_FB1B;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 200) as usize + 1;
            let keys: Vec<i64> = (0..n).map(|_| (next() % 8) as i64 - 4).collect();
            let vals: Vec<f64> = (0..n).map(|_| (next() % 1000) as f64 / 4.0).collect();
            let df = DataFrame::from_dict(
                &["k", "v"],
                vec![
                    ("k", keys.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("v", vals.iter().map(|&v| Scalar::Float64(v)).collect()),
                ],
            )
            .unwrap();

            let mut distinct: Vec<i64> = keys.clone();
            distinct.sort_unstable();
            distinct.dedup();
            // Row-order left-fold sum/count per sorted group.
            let group_f64 = |g: i64| -> Vec<f64> {
                keys.iter()
                    .zip(&vals)
                    .filter(|(k, _)| **k == g)
                    .map(|(_, &v)| v)
                    .collect()
            };
            let want_sum: Vec<f64> = distinct
                .iter()
                .map(|&g| group_f64(g).iter().sum())
                .collect();
            let want_cnt: Vec<i64> = distinct
                .iter()
                .map(|&g| group_f64(g).len() as i64)
                .collect();
            let want_mean: Vec<f64> = distinct
                .iter()
                .map(|&g| {
                    let gv = group_f64(g);
                    gv.iter().sum::<f64>() / gv.len() as f64
                })
                .collect();

            let gb = df.groupby(&["k"]).unwrap();
            let labels_of = |res: &DataFrame| -> Vec<i64> {
                res.index()
                    .labels()
                    .iter()
                    .map(|l| match l {
                        IndexLabel::Int64(v) => *v,
                        other => panic!("{other:?}"),
                    })
                    .collect()
            };
            let f64_of = |res: &DataFrame| -> Vec<f64> {
                res.column("v")
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => *x,
                        other => panic!("{other:?}"),
                    })
                    .collect()
            };
            let i64_of = |res: &DataFrame| -> Vec<i64> {
                res.column("v")
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        other => panic!("{other:?}"),
                    })
                    .collect()
            };

            let s = gb.sum().unwrap();
            assert_eq!(labels_of(&s), distinct, "trial {trial} sum labels");
            for (g, w) in f64_of(&s).iter().zip(&want_sum) {
                assert_eq!(
                    g.to_bits(),
                    w.to_bits(),
                    "trial {trial} sum (left-fold must match)"
                );
            }
            let m = gb.mean().unwrap();
            for (g, w) in f64_of(&m).iter().zip(&want_mean) {
                assert!((g - w).abs() < 1e-9, "trial {trial} mean");
            }
            assert_eq!(
                i64_of(&gb.count().unwrap()),
                want_cnt,
                "trial {trial} count"
            );
            let want_min: Vec<f64> = distinct
                .iter()
                .map(|&g| {
                    group_f64(g)
                        .into_iter()
                        .reduce(|a, b| if b < a { b } else { a })
                        .unwrap()
                })
                .collect();
            let want_max: Vec<f64> = distinct
                .iter()
                .map(|&g| {
                    group_f64(g)
                        .into_iter()
                        .reduce(|a, b| if b > a { b } else { a })
                        .unwrap()
                })
                .collect();
            for (g, w) in f64_of(&gb.min().unwrap()).iter().zip(&want_min) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} min");
            }
            for (g, w) in f64_of(&gb.max().unwrap()).iter().zip(&want_max) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} max");
            }
            // var/std: two-pass mean then Σ(x-mean)^2 / (n-1), ddof=1, n<=1→Null.
            let nan_of = |res: &DataFrame| -> Vec<Option<f64>> {
                res.column("v")
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => Some(*x),
                        Scalar::Null(_) => None,
                        other => panic!("{other:?}"),
                    })
                    .collect()
            };
            let want_var: Vec<Option<f64>> = distinct
                .iter()
                .map(|&g| {
                    let gv = group_f64(g);
                    if gv.len() <= 1 {
                        None
                    } else {
                        let mean = gv.iter().sum::<f64>() / gv.len() as f64;
                        let ss: f64 = gv.iter().map(|x| (x - mean).powi(2)).sum();
                        Some(ss / (gv.len() - 1) as f64)
                    }
                })
                .collect();
            for (g, w) in nan_of(&gb.var().unwrap()).iter().zip(&want_var) {
                match (g, w) {
                    (Some(a), Some(b)) => assert_eq!(a.to_bits(), b.to_bits(), "trial {trial} var"),
                    (None, None) => {}
                    _ => panic!("trial {trial} var null mismatch {g:?} {w:?}"),
                }
            }
            for (g, w) in nan_of(&gb.std().unwrap()).iter().zip(&want_var) {
                match (g, w) {
                    (Some(a), Some(b)) => {
                        assert_eq!(a.to_bits(), b.sqrt().to_bits(), "trial {trial} std")
                    }
                    (None, None) => {}
                    _ => panic!("trial {trial} std null mismatch"),
                }
            }
            // first/last: literal first/last group value in row order.
            let want_first: Vec<f64> = distinct.iter().map(|&g| group_f64(g)[0]).collect();
            let want_last: Vec<f64> = distinct
                .iter()
                .map(|&g| *group_f64(g).last().unwrap())
                .collect();
            for (g, w) in f64_of(&gb.first().unwrap()).iter().zip(&want_first) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} first");
            }
            for (g, w) in f64_of(&gb.last().unwrap()).iter().zip(&want_last) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} last");
            }
            // prod: row-order left-fold product seeded 1.0, bit-exact.
            let want_prod: Vec<f64> = distinct
                .iter()
                .map(|&g| group_f64(g).iter().fold(1.0_f64, |a, &b| a * b))
                .collect();
            for (g, w) in f64_of(&gb.prod().unwrap()).iter().zip(&want_prod) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} prod");
            }
            // median: sort-based reference (per group), bit-exact.
            let want_median: Vec<f64> = distinct
                .iter()
                .map(|&g| {
                    let mut gv = group_f64(g);
                    gv.sort_unstable_by(|a, b| {
                        a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
                    });
                    let mid = gv.len() / 2;
                    if gv.len() % 2 == 0 {
                        (gv[mid - 1] + gv[mid]) / 2.0
                    } else {
                        gv[mid]
                    }
                })
                .collect();
            for (g, w) in f64_of(&gb.median().unwrap()).iter().zip(&want_median) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} median");
            }
        }
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn dataframe_groupby_dense_sum_timing() {
        use std::time::Instant;
        let rows = 2_000_000usize;
        let iters = 10;
        let mut state: u64 = 0x6C44_5202_8A1E_3FB7;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let keys: Vec<i64> = (0..rows).map(|_| (next() % 10_000) as i64).collect();
        let v0: Vec<f64> = (0..rows).map(|_| (next() % 1000) as f64).collect();
        let v1: Vec<f64> = (0..rows).map(|_| (next() % 1000) as f64).collect();
        let labels: Vec<IndexLabel> = (0..rows as i64).map(IndexLabel::Int64).collect();
        let mk = || {
            let mut cols = std::collections::BTreeMap::new();
            cols.insert("k".to_owned(), Column::from_i64_values_owned(keys.clone()));
            cols.insert("v0".to_owned(), Column::from_f64_values(v0.clone()));
            cols.insert("v1".to_owned(), Column::from_f64_values(v1.clone()));
            DataFrame::new_with_column_order(
                Index::new(labels.clone()),
                cols,
                vec!["k".to_owned(), "v0".to_owned(), "v1".to_owned()],
            )
            .unwrap()
        };

        // NEW: dense-agg df.groupby.sum (this commit).
        let df = mk();
        let t0 = Instant::now();
        let mut chk = 0usize;
        for _ in 0..iters {
            chk ^= df.groupby(&["k"]).unwrap().sum().unwrap().shape().0;
        }
        let dense = t0.elapsed();

        // OLD agg: dense grouping (gid) + per-group Scalar gather + nansum —
        // the path this commit replaces, isolating the aggregation lever.
        let (dmin, drange) = {
            let mut mn = keys[0];
            let mut mx = keys[0];
            for &k in &keys {
                mn = mn.min(k);
                mx = mx.max(k);
            }
            (mn, (mx - mn + 1) as usize)
        };
        let t1 = Instant::now();
        let mut chk2 = 0usize;
        for _ in 0..iters {
            let mut gid_table = vec![usize::MAX; drange];
            let mut positions: Vec<Vec<usize>> = Vec::new();
            for (row, &k) in keys.iter().enumerate() {
                let slot = (k - dmin) as usize;
                let g = if gid_table[slot] == usize::MAX {
                    gid_table[slot] = positions.len();
                    positions.push(Vec::new());
                    positions.len() - 1
                } else {
                    gid_table[slot]
                };
                positions[g].push(row);
            }
            let mut s = 0usize;
            for col in [&df.columns["v0"], &df.columns["v1"]] {
                for pos in &positions {
                    let gvals: Vec<Scalar> = pos.iter().map(|&i| col.values()[i].clone()).collect();
                    let _ = fp_types::nansum(&gvals);
                    s += 1;
                }
            }
            chk2 ^= s;
        }
        let scalar = t1.elapsed();
        eprintln!(
            "df.groupby([int]).sum agg {rows}x2 f64 keys=10k x{iters}: dense={dense:?} old_gather_nansum={scalar:?} ratio={:.2}x (chk {chk}/{chk2})",
            scalar.as_secs_f64() / dense.as_secs_f64()
        );
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn dataframe_groupby_multicol_dense_timing() {
        use std::time::Instant;
        let rows = 2_000_000usize;
        let iters = 10;
        let mut state: u64 = 0xF1BB_CDCB_FA53_E0AD;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let ka: Vec<i64> = (0..rows).map(|_| (next() % 1000) as i64).collect();
        let kb: Vec<i64> = (0..rows).map(|_| (next() % 10) as i64).collect();

        // DENSE: mixed-radix composite slot (range_a * range_b = 10k slots).
        let (amin, arange) = (0i64, 1000usize);
        let (bmin, brange) = (0i64, 10usize);
        let stride_a = brange;
        let combined = arange * brange;
        let t0 = Instant::now();
        let mut chk = 0usize;
        for _ in 0..iters {
            let mut gid = vec![usize::MAX; combined];
            let mut order: Vec<Vec<ScalarKey>> = Vec::new();
            let mut positions: Vec<Vec<usize>> = Vec::new();
            for row in 0..rows {
                let slot = (ka[row] - amin) as usize * stride_a + (kb[row] - bmin) as usize;
                let g = if gid[slot] == usize::MAX {
                    let ng = order.len();
                    gid[slot] = ng;
                    order.push(vec![ScalarKey::Int64(ka[row]), ScalarKey::Int64(kb[row])]);
                    positions.push(Vec::new());
                    ng
                } else {
                    gid[slot]
                };
                positions[g].push(row);
            }
            chk ^= order.len();
        }
        let dense = t0.elapsed();

        // OLD: per-row Vec<ScalarKey> heap alloc + HashMap.
        let t1 = Instant::now();
        let mut chk2 = 0usize;
        for _ in 0..iters {
            let mut group_order: Vec<Vec<ScalarKey>> = Vec::new();
            let mut groups: std::collections::HashMap<Vec<ScalarKey>, Vec<usize>> =
                std::collections::HashMap::new();
            for row in 0..rows {
                let key = vec![ScalarKey::Int64(ka[row]), ScalarKey::Int64(kb[row])];
                if !groups.contains_key(&key) {
                    group_order.push(key.clone());
                }
                groups.entry(key).or_default().push(row);
            }
            chk2 ^= group_order.len();
        }
        let scalar = t1.elapsed();
        eprintln!(
            "build_groups 2-col {rows} rows x{iters}: dense={dense:?} old_veckey_hashmap={scalar:?} ratio={:.2}x (chk {chk}/{chk2})",
            scalar.as_secs_f64() / dense.as_secs_f64()
        );
    }

    #[test]
    fn dataframe_groupby_multicol_dense_matches_reference() {
        // df.groupby([int_a, int_b]).sum (default sort=true) over all-valid
        // Int64 keys must match a lexicographically-sorted composite-group
        // reference. Exercises the multi-column mixed-radix dense build_groups.
        let mut state: u64 = 0xC3A5_C85C_97CB_3127;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 150) as usize + 1;
            let ka: Vec<i64> = (0..n).map(|_| (next() % 5) as i64 - 2).collect();
            let kb: Vec<i64> = (0..n).map(|_| (next() % 4) as i64).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 100) as i64).collect();
            let df = DataFrame::from_dict(
                &["a", "b", "v"],
                vec![
                    ("a", ka.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("b", kb.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("v", vals.iter().map(|&v| Scalar::Int64(v)).collect()),
                ],
            )
            .unwrap();

            // Sorted distinct (a,b) pairs + per-group sum.
            let mut pairs: Vec<(i64, i64)> = ka.iter().zip(&kb).map(|(&a, &b)| (a, b)).collect();
            pairs.sort_unstable();
            pairs.dedup();
            let want_sum: Vec<i64> = pairs
                .iter()
                .map(|&(a, b)| {
                    ka.iter()
                        .zip(&kb)
                        .zip(&vals)
                        .filter(|((x, y), _)| **x == a && **y == b)
                        .map(|(_, &v)| v)
                        .sum()
                })
                .collect();

            let res = df.groupby(&["a", "b"]).unwrap().sum().unwrap();
            // as_index default → composite labels; verify the value column sum.
            let got: Vec<i64> = res
                .column("v")
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Int64(x) => *x,
                    Scalar::Float64(x) => *x as i64,
                    other => panic!("{other:?}"),
                })
                .collect();
            assert_eq!(got, want_sum, "trial {trial} multicol sum (n={n})");
            assert_eq!(res.shape().0, pairs.len(), "trial {trial} group count");

            // Float64 value column → multi-col dense agg (mean), bit-exact.
            let fvals: Vec<f64> = vals.iter().map(|&v| v as f64 / 4.0).collect();
            let dff = DataFrame::from_dict(
                &["a", "b", "v"],
                vec![
                    ("a", ka.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("b", kb.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("v", fvals.iter().map(|&v| Scalar::Float64(v)).collect()),
                ],
            )
            .unwrap();
            let want_mean: Vec<f64> = pairs
                .iter()
                .map(|&(a, b)| {
                    let gv: Vec<f64> = ka
                        .iter()
                        .zip(&kb)
                        .zip(&fvals)
                        .filter(|((x, y), _)| **x == a && **y == b)
                        .map(|(_, &v)| v)
                        .collect();
                    gv.iter().sum::<f64>() / gv.len() as f64
                })
                .collect();
            let got_mean: Vec<f64> = dff
                .groupby(&["a", "b"])
                .unwrap()
                .mean()
                .unwrap()
                .column("v")
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    other => panic!("{other:?}"),
                })
                .collect();
            for (g, w) in got_mean.iter().zip(&want_mean) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} multicol mean");
            }
        }
    }

    #[test]
    fn dataframe_groupby_dense_build_groups_matches_reference() {
        // df.groupby([int_col]).{sum,count,max} (default sort=true) over an
        // all-valid Int64 key must match a sorted-group reference. Exercises
        // the dense build_groups path + its sort branch; agg logic is unchanged.
        let mut state: u64 = 0x1F83_D9AB_FB41_BD6B;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 200) as usize + 1;
            let keys: Vec<i64> = (0..n).map(|_| (next() % 8) as i64 - 4).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 100) as i64).collect();
            let df = DataFrame::from_dict(
                &["k", "v"],
                vec![
                    ("k", keys.iter().map(|&v| Scalar::Int64(v)).collect()),
                    ("v", vals.iter().map(|&v| Scalar::Int64(v)).collect()),
                ],
            )
            .unwrap();

            // Sorted distinct keys + per-group sum/count/max.
            let mut distinct: Vec<i64> = keys.clone();
            distinct.sort_unstable();
            distinct.dedup();
            let agg = |sel: &dyn Fn(&[i64]) -> i64| -> Vec<i64> {
                distinct
                    .iter()
                    .map(|&g| {
                        let gv: Vec<i64> = keys
                            .iter()
                            .zip(&vals)
                            .filter(|(k, _)| **k == g)
                            .map(|(_, &v)| v)
                            .collect();
                        sel(&gv)
                    })
                    .collect()
            };
            let want_sum = agg(&|gv| gv.iter().sum());
            let want_count = agg(&|gv| gv.len() as i64);
            let want_max = agg(&|gv| *gv.iter().max().unwrap());

            let gb = df.groupby(&["k"]).unwrap();
            let check = |res: &DataFrame, want: &[i64], op: &str| {
                let labels: Vec<i64> = res
                    .index()
                    .labels()
                    .iter()
                    .map(|l| match l {
                        IndexLabel::Int64(v) => *v,
                        other => panic!("{other:?}"),
                    })
                    .collect();
                assert_eq!(labels, distinct, "trial {trial} {op} labels");
                let got: Vec<i64> = res
                    .column("v")
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        Scalar::Float64(x) => *x as i64,
                        other => panic!("{other:?}"),
                    })
                    .collect();
                assert_eq!(got, want, "trial {trial} {op} values");
            };
            check(&gb.sum().unwrap(), &want_sum, "sum");
            check(&gb.count().unwrap(), &want_count, "count");
            check(&gb.max().unwrap(), &want_max, "max");
            // Int64 mean → Float64 (row-order f64 sum / count), bit-exact.
            let want_mean: Vec<f64> = distinct
                .iter()
                .map(|&g| {
                    let gv: Vec<i64> = keys
                        .iter()
                        .zip(&vals)
                        .filter(|(k, _)| **k == g)
                        .map(|(_, &v)| v)
                        .collect();
                    gv.iter().map(|&x| x as f64).sum::<f64>() / gv.len() as f64
                })
                .collect();
            let mean_res = gb.mean().unwrap();
            let got_mean: Vec<f64> = mean_res
                .column("v")
                .unwrap()
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    other => panic!("{other:?}"),
                })
                .collect();
            for (g, w) in got_mean.iter().zip(&want_mean) {
                assert_eq!(g.to_bits(), w.to_bits(), "trial {trial} int mean");
            }
        }
    }

