    #[test]
    fn groupby_dense_agg_matches_reference() {
        // Independent first-seen reference for Series.groupby(by).sum()/.mean()
        // over all-valid Int64 keys + numeric values. The dense-bucket fast
        // path must be bit-identical in group order, labels, and values.
        let mut state: u64 = 0x3B97_4F2A_18CD_6E05;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 300) as usize + 1;
            let keys: Vec<i64> = (0..n).map(|_| (next() % 9) as i64 - 4).collect();
            let vals: Vec<i64> = (0..n).map(|_| (next() % 200) as i64 - 100).collect();
            let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
            let by = Series::new(
                "k".to_owned(),
                Index::new(labels.clone()),
                Column::from_i64_values_owned(keys.clone()),
            )
            .unwrap();
            let series = Series::new(
                "v".to_owned(),
                Index::new(labels),
                Column::from_i64_values_owned(vals.clone()),
            )
            .unwrap();

            // Reference: first-seen group order, accumulate f64 values.
            let mut order: Vec<i64> = Vec::new();
            let mut sums: Vec<f64> = Vec::new();
            let mut counts: Vec<usize> = Vec::new();
            for (&k, &v) in keys.iter().zip(&vals) {
                let g = match order.iter().position(|&o| o == k) {
                    Some(p) => p,
                    None => {
                        order.push(k);
                        sums.push(0.0);
                        counts.push(0);
                        order.len() - 1
                    }
                };
                sums[g] += v as f64;
                counts[g] += 1;
            }

            let gb = series.groupby(&by).unwrap();
            let mean_ref: Vec<f64> = sums
                .iter()
                .zip(&counts)
                .map(|(s, &c)| s / c as f64)
                .collect();
            for (opname, want) in [("sum", sums.clone()), ("mean", mean_ref)] {
                let got = if opname == "sum" { gb.sum() } else { gb.mean() }.unwrap();
                let glabels: Vec<i64> = got
                    .index()
                    .labels()
                    .iter()
                    .map(|l| match l {
                        IndexLabel::Int64(v) => *v,
                        other => panic!("{other:?}"),
                    })
                    .collect();
                let gvals: Vec<f64> = got
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(f) => *f,
                        other => panic!("{other:?}"),
                    })
                    .collect();
                assert_eq!(glabels, order, "trial {trial} {opname} labels");
                assert_eq!(gvals.len(), want.len());
                for (g, w) in gvals.iter().zip(&want) {
                    assert!((g - w).abs() < 1e-9, "trial {trial} {opname}: {g} vs {w}");
                }
            }
        }
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn groupby_dense_sum_timing() {
        use std::time::Instant;
        let n = 5_000_000usize;
        let iters = 10;
        let mut state: u64 = 0x510E_527F_ADE6_82D1;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        // 10k distinct integer groups.
        let keys: Vec<i64> = (0..n).map(|_| (next() % 10_000) as i64).collect();
        let vals: Vec<f64> = (0..n).map(|_| (next() % 1000) as f64).collect();
        let labels: Vec<IndexLabel> = (0..n as i64).map(IndexLabel::Int64).collect();
        let by = Series::new(
            "k".to_owned(),
            Index::new(labels.clone()),
            Column::from_i64_values_owned(keys.clone()),
        )
        .unwrap();
        let series = Series::new(
            "v".to_owned(),
            Index::new(labels),
            Column::from_f64_values(vals.clone()),
        )
        .unwrap();

        let t0 = Instant::now();
        let mut chk = 0usize;
        for _ in 0..iters {
            chk ^= series.groupby(&by).unwrap().sum().unwrap().len();
        }
        let dense = t0.elapsed();

        // OLD path: HashMap<ScalarKey,Vec<usize>> grouping + per-group filter/to_f64.
        let t1 = Instant::now();
        let mut chk2 = 0usize;
        for _ in 0..iters {
            let mut order: Vec<i64> = Vec::new();
            let mut groups: std::collections::HashMap<i64, Vec<usize>> =
                std::collections::HashMap::new();
            let mut seen = std::collections::HashSet::new();
            for (i, &k) in keys.iter().enumerate() {
                if seen.insert(k) {
                    order.push(k);
                }
                groups.entry(k).or_default().push(i);
            }
            let svals = series.column.values();
            let mut s = 0usize;
            for k in &order {
                let nums: Vec<f64> = groups[k]
                    .iter()
                    .filter_map(|&idx| svals[idx].to_f64().ok())
                    .collect();
                let _: f64 = nums.iter().sum();
                s += 1;
            }
            chk2 ^= s;
        }
        let scalar = t1.elapsed();
        eprintln!(
            "groupby.sum 5M i64 keys=10k x{iters}: dense={dense:?} hashmap={scalar:?} ratio={:.2}x (chk {chk}/{chk2})",
            scalar.as_secs_f64() / dense.as_secs_f64()
        );
    }

    #[test]
    fn dataframe_scalar_arith_typed_matches_reference() {
        // Independent reference: to_f64 + op per cell → Float64 (the scalar
        // loop). The typed fast path must be bit-identical for all-valid
        // Int64/Float64 columns across add/sub/mul/div, incl div-by-zero NaN/inf.
        let mut state: u64 = 0xA54F_F53A_5F1D_36F1;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        type ScalarBinaryRef = (&'static str, fn(f64, f64) -> f64);
        let ops: [ScalarBinaryRef; 4] = [
            ("add", |a, b| a + b),
            ("sub", |a, b| a - b),
            ("mul", |a, b| a * b),
            ("div", |a, b| a / b),
        ];
        for trial in 0..120 {
            let n = (next() % 60) as usize + 1;
            let raw: Vec<i64> = (0..n).map(|_| (next() % 200) as i64 - 100).collect();
            let scalar = match next() % 5 {
                0 => 0.0,
                1 => 2.5,
                2 => -3.0,
                _ => (next() % 20) as f64 - 10.0,
            };
            for as_float in [false, true] {
                let vals: Vec<Scalar> = if as_float {
                    raw.iter().map(|&v| Scalar::Float64(v as f64)).collect()
                } else {
                    raw.iter().map(|&v| Scalar::Int64(v)).collect()
                };
                let df = DataFrame::from_dict(&["a"], vec![("a", vals.clone())]).unwrap();
                for (opname, op) in ops {
                    let got: Vec<Scalar> = match opname {
                        "add" => df.add_scalar(scalar),
                        "sub" => df.sub_scalar(scalar),
                        "mul" => df.mul_scalar(scalar),
                        _ => df.div_scalar(scalar),
                    }
                    .unwrap()
                    .column("a")
                    .unwrap()
                    .values()
                    .to_vec();
                    // Both the typed path (from_f64_values) and the old scalar
                    // loop (from_values over Scalar::Float64(op(..))) store the
                    // raw op result — incl NaN as Float64(NaN), NOT Null — so
                    // the reference wraps op() directly and compares by bits.
                    let want: Vec<Scalar> = vals
                        .iter()
                        .map(|v| Scalar::Float64(op(v.to_f64().unwrap(), scalar)))
                        .collect();
                    assert_eq!(got.len(), want.len());
                    for (g, w) in got.iter().zip(&want) {
                        match (g, w) {
                            (Scalar::Float64(a), Scalar::Float64(b)) => {
                                assert_eq!(
                                    a.to_bits(),
                                    b.to_bits(),
                                    "trial {trial} {opname} float={as_float}"
                                );
                            }
                            _ => panic!("trial {trial} {opname} float={as_float}: {g:?} vs {w:?}"),
                        }
                    }
                }
            }
        }
    }

    #[test]
    #[ignore = "timing benchmark; run with --ignored --nocapture on the rch VM"]
    fn dataframe_scalar_arith_typed_timing() {
        use std::time::Instant;
        let rows = 1_000_000usize;
        let ncols = 5usize;
        let iters = 10;
        let mut state: u64 = 0x71D6_7FFF_EDA6_0000;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        let names = ["c0", "c1", "c2", "c3", "c4"];
        let data: Vec<Vec<f64>> = (0..ncols)
            .map(|_| (0..rows).map(|_| (next() % 1_000_000) as f64).collect())
            .collect();
        let labels: Vec<IndexLabel> = (0..rows as i64).map(IndexLabel::Int64).collect();
        let mk = || {
            let mut cols = std::collections::BTreeMap::new();
            for c in 0..ncols {
                cols.insert(
                    names[c].to_owned(),
                    Column::from_f64_values(data[c].clone()),
                );
            }
            DataFrame::new_with_column_order(
                Index::new(labels.clone()),
                cols,
                (0..ncols).map(|c| names[c].to_owned()).collect::<Vec<_>>(),
            )
            .unwrap()
        };

        let t0 = Instant::now();
        let mut chk = 0usize;
        for _ in 0..iters {
            chk ^= mk().mul_scalar(2.5).unwrap().shape().0;
        }
        let typed = t0.elapsed();

        let t1 = Instant::now();
        let mut chk2 = 0usize;
        for _ in 0..iters {
            let df = mk();
            let mut cols = std::collections::BTreeMap::new();
            for name in &df.column_order {
                let col = &df.columns[name];
                let vals: Vec<Scalar> = col
                    .values()
                    .iter()
                    .map(|v| match v.to_f64() {
                        Ok(f) => Scalar::Float64(f * 2.5),
                        Err(_) => Scalar::Null(NullKind::NaN),
                    })
                    .collect();
                cols.insert(name.clone(), Column::from_values(vals).unwrap());
            }
            let out =
                DataFrame::new_with_column_order(df.index.clone(), cols, df.column_order.clone())
                    .unwrap();
            chk2 ^= out.shape().0;
        }
        let scalar = t1.elapsed();
        let t2 = Instant::now();
        let mut sink = 0usize;
        for _ in 0..iters {
            sink ^= mk().shape().0;
        }
        let build = t2.elapsed();
        let typed_op = typed.saturating_sub(build).as_secs_f64();
        let scalar_op = scalar.saturating_sub(build).as_secs_f64();
        eprintln!(
            "df.mul_scalar {rows}x{ncols} f64 x{iters}: typed={typed:?} scalar={scalar:?} build={build:?} \
             op-only ratio={:.2}x (full {:.2}x, chk {chk}/{chk2}/{sink})",
            scalar_op / typed_op,
            scalar.as_secs_f64() / typed.as_secs_f64()
        );
    }

    #[test]
    fn dataframe_isna_notna_validity_matches_reference() {
        // df.isna/notna via the validity-mask helper must match per-cell
        // is_missing across mixed-dtype columns with nulls/NaN.
        let mut state: u64 = 0x6C62_72E0_7BB0_1442;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            state
        };
        for trial in 0..120 {
            let n = (next() % 50) as usize + 1;
            let col_a: Vec<Scalar> = (0..n)
                .map(|_| match next() % 4 {
                    0 => Scalar::Null(NullKind::NaN),
                    1 => Scalar::Float64(f64::NAN),
                    _ => Scalar::Float64((next() % 500) as f64),
                })
                .collect();
            let col_b: Vec<Scalar> = (0..n)
                .map(|_| match next() % 3 {
                    0 => Scalar::Null(NullKind::Null),
                    _ => Scalar::Int64((next() % 500) as i64),
                })
                .collect();
            let df = DataFrame::from_dict(
                &["a", "b"],
                vec![("a", col_a.clone()), ("b", col_b.clone())],
            )
            .unwrap();
            let isna = df.isna().unwrap();
            let notna = df.notna().unwrap();
            for (name, src) in [("a", &col_a), ("b", &col_b)] {
                let gi: Vec<bool> = isna
                    .column(name)
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect();
                let gn: Vec<bool> = notna
                    .column(name)
                    .unwrap()
                    .values()
                    .iter()
                    .map(|v| matches!(v, Scalar::Bool(true)))
                    .collect();
                let wi: Vec<bool> = src.iter().map(|v| v.is_missing()).collect();
                assert_eq!(gi, wi, "trial {trial} col {name} isna");
                assert_eq!(
                    gn,
                    wi.iter().map(|&b| !b).collect::<Vec<_>>(),
                    "trial {trial} col {name} notna"
                );
            }
        }
    }

