        const CHILD_ENV: &str = "FP_PAIR_BUFFER_PROFILE_CHILD";
        const SENTINEL: &str = "pair_buffer_build_morsel_candidate_cod_fp";

        let available = fp_columnar::cached_available_parallelism();
